internal static partial class GameInventoryReader
{
    // Auto Build uses the user's independent overall search limit, but each expensive combat
    // package is ranked over this shorter, shared preview window. Keeping the
    // search deadline and the combat horizon independent lets more shortlisted
    // equipment packages reach exact evaluation without changing the user's
    // overall search budget.
    private const double PerformancePreviewWindowSeconds = 30d;
    private const double PerformanceScoreReferenceSeconds = 60d;
    private const double PerformanceTimeLinearNormalization =
        PerformanceScoreReferenceSeconds / PerformancePreviewWindowSeconds;
    // Defense candidates are compared against one immutable snapshot of the
    // selected hero's current, resource-limited base attack. Doubling that
    // pressure makes mitigation meaningful, while the per-hit ceiling prevents
    // a single oversized preview event from turning every candidate into an
    // indistinguishable instant death.
    private const double DefenseStressDamageMultiplier = 2d;
    private const double DefenseStressMaximumRawHitHealthFraction = 0.45d;
    private const double BloodiedHealthFraction = 0.50d;
    private const int DefenseSimulationStepsPerSecond = 10;
    // A loot-container-only affix has no combat value. Keep the penalty much
    // larger than a normal item's complete heuristic score so a GM/utility item
    // cannot win a combat build through the word "damage" or a hidden flag.
    private const double NonCombatTargetAffixPenalty = 5000d;
    // A skill/set-specific special that the selected package cannot activate is
    // not a negative combat stat, but it does consume the item's defining
    // special-effect budget. Charge a bounded opportunity cost so raw item
    // level can still win by a meaningful margin while an unusable Unique or
    // set lane no longer wins every close comparison for free.
    private const double InactiveSpecialOpportunityCostPenalty = 180d;
    private const double InactiveSetThresholdOpportunityCostPenalty = 220d;
    // This is a corruption/runaway guard, not a time budget. Keep its existing
    // capacity when shortening the window so legitimate high-rate builds are not
    // rejected merely because the performance optimization changed.
    private const int MaximumPerformancePreviewEvents = 6000;
    private const int MaximumPerformancePackageEvents = MaximumPerformancePreviewEvents * 2;

