    internal static bool TryAcquireRuntimeTestNoHeroSelection(out string reason)
    {
        try
        {
            if (runtimeTestSelectionLeaseActive)
            {
                if (!runtimeTestSelectionHeroLeaseActive)
                {
                    reason = "a previous runtime selection cleanup is incomplete";
                    return false;
                }
                var currentSeason = Read(ReadStatic("Game", "dataMgr"), "nowSeasonData");
                var currentLord = Read(currentSeason, "lordData");
                if (!NativeEquals(currentSeason, runtimeTestSelectionSeason)
                    || !NativeEquals(currentLord, runtimeTestSelectionLord))
                {
                    reason = "season changed after the runtime no-hero selection was acquired";
                    return false;
                }
                if (currentLord is null
                    || ReadRequiredProperty(currentLord, "nowHeroData") is not null)
                {
                    reason = "a hero was selected after the runtime no-hero selection was acquired";
                    return false;
                }
                reason = string.Empty;
                return true;
            }

            var dataManager = ReadStatic("Game", "dataMgr");
            var seasonData = Read(dataManager, "nowSeasonData");
            var lordData = Read(seasonData, "lordData");
            if (seasonData is null || lordData is null)
            {
                reason = "season/lord data is not loaded";
                return false;
            }

            var previousHero = ReadRequiredProperty(lordData, "nowHeroData");
            runtimeTestSelectionLeaseActive = true;
            runtimeTestSelectionHeroLeaseActive = true;
            runtimeTestSelectionSeason = seasonData;
            runtimeTestSelectionLord = lordData;
            runtimeTestSelectionPreviousHero = previousHero;
            runtimeTestSelectionInjectedHero = null;
            Plugin.BeginRuntimeNoActivateWindowScope();
            Write(lordData, "nowHeroData", null);
            if (ReadRequiredProperty(lordData, "nowHeroData") is not null)
            {
                ReleaseRuntimeTestHeroSelection(out _);
                reason = "the selected hero could not be cleared for the no-hero test";
                return false;
            }
            reason = string.Empty;
            return true;
        }
        catch (Exception error)
        {
            ReleaseRuntimeTestHeroSelection(out var cleanupReason);
            reason = $"runtime no-hero selection failed: {error.GetBaseException().Message}";
            if (!string.IsNullOrWhiteSpace(cleanupReason)) reason += $"; cleanup: {cleanupReason}";
            return false;
        }
    }

    internal static bool TryAcquireRuntimeTestHeroSelection(
        int uniqueId,
        out string reason,
        out bool initialLoadPending)
    {
        initialLoadPending = false;
        try
        {
            if (uniqueId <= 0)
            {
                reason = "runtime target hero id is invalid";
                return false;
            }

            if (runtimeTestSelectionLeaseActive)
            {
                if (!runtimeTestSelectionHeroLeaseActive)
                {
                    reason = "a previous runtime selection cleanup is incomplete";
                    return false;
                }
                var currentSeason = Read(ReadStatic("Game", "dataMgr"), "nowSeasonData");
                var currentLord = Read(currentSeason, "lordData");
                if (!NativeEquals(currentSeason, runtimeTestSelectionSeason)
                    || !NativeEquals(currentLord, runtimeTestSelectionLord))
                {
                    reason = "season changed after the runtime hero selection was acquired";
                    return false;
                }
                if (currentLord is null
                    || !NativeEquals(
                        ReadRequiredProperty(currentLord, "nowHeroData"),
                        runtimeTestSelectionInjectedHero))
                {
                    reason = "the user changed the selected hero after the runtime selection was acquired";
                    return false;
                }
                if (!TryPrepareRuntimeTestHeroAuto(out reason)) return false;
                reason = string.Empty;
                return true;
            }

            var dataManager = ReadStatic("Game", "dataMgr");
            var seasonData = Read(dataManager, "nowSeasonData");
            var lordData = Read(seasonData, "lordData");
            if (seasonData is null || lordData is null)
            {
                initialLoadPending = true;
                reason = "season/lord data is not loaded";
                return false;
            }

            object? targetHero = null;
            foreach (var field in ReadList(ReadRequiredProperty(lordData, "heroFieldList")))
            {
                var candidate = Read(field, "heroData");
                if ((ReadNullableInt(Read(candidate, "saveHeroData"), "uniqueId") ?? 0) != uniqueId) continue;
                targetHero = candidate;
                break;
            }
            if (targetHero is null)
            {
                initialLoadPending = true;
                reason = $"owned runtime hero {uniqueId} is not loaded";
                return false;
            }
            if (ReadRequiredProperty(targetHero, "saveHeroData") is null
                || ReadRequiredProperty(targetHero, "heroTalentData") is null
                || ReadRequiredProperty(targetHero, "heroEquipData") is null)
            {
                initialLoadPending = true;
                reason = $"runtime hero {uniqueId} save/talent/equipment data is not loaded";
                return false;
            }

            // Capture the previous selection through the required accessor before
            // activating the lease. A real null selection is valid; a missing or
            // throwing getter must not be collapsed into null and later restored.
            var previousHero = ReadRequiredProperty(lordData, "nowHeroData");
            runtimeTestSelectionLeaseActive = true;
            runtimeTestSelectionHeroLeaseActive = true;
            runtimeTestSelectionSeason = seasonData;
            runtimeTestSelectionLord = lordData;
            runtimeTestSelectionPreviousHero = previousHero;
            runtimeTestSelectionInjectedHero = targetHero;
            Plugin.BeginRuntimeNoActivateWindowScope();
            Write(lordData, "nowHeroData", targetHero);
            if (!NativeEquals(ReadRequiredProperty(lordData, "nowHeroData"), targetHero))
            {
                ReleaseRuntimeTestHeroSelection(out _);
                reason = $"runtime hero {uniqueId} could not be selected";
                return false;
            }
            if (!TryPrepareRuntimeTestHeroAuto(out reason))
            {
                initialLoadPending = reason.Contains("loading", StringComparison.OrdinalIgnoreCase);
                ReleaseRuntimeTestHeroSelection(out var cleanupReason);
                if (!string.IsNullOrWhiteSpace(cleanupReason)) reason += $"; cleanup: {cleanupReason}";
                return false;
            }
            reason = string.Empty;
            return true;
        }
        catch (Exception error)
        {
            ReleaseRuntimeTestHeroSelection(out var cleanupReason);
            reason = $"runtime hero selection failed: {error.GetBaseException().Message}";
            if (!string.IsNullOrWhiteSpace(cleanupReason)) reason += $"; cleanup: {cleanupReason}";
            return false;
        }
    }

    private static bool TryPrepareRuntimeTestHeroAuto(out string reason)
    {
        if (runtimeTestSelectionAutoLeaseActive)
        {
            if (runtimeTestSelectionAutoField is null || runtimeTestSelectionAutoSaveField is null)
            {
                reason = "runtime adventure Auto lease is incomplete";
                return false;
            }
            var currentSaveField = ReadRequiredProperty(
                runtimeTestSelectionAutoField, "saveAdvFieldData");
            if (!NativeEquals(currentSaveField, runtimeTestSelectionAutoSaveField))
            {
                reason = "runtime hero adventure field changed after Auto was paused";
                return false;
            }
            var currentAuto = ReadRequiredBoolProperty(runtimeTestSelectionAutoSaveField, "isAuto");
            if (currentAuto)
            {
                if (!runtimeTestSelectionPreviousAuto)
                {
                    reason = "runtime hero adventure Auto changed after the lease was acquired";
                    return false;
                }
                InvokeRequiredInstance(runtimeTestSelectionAutoField, "SetAuto", false);
                if (ReadRequiredBoolProperty(runtimeTestSelectionAutoSaveField, "isAuto"))
                {
                    reason = "runtime hero adventure Auto could not be kept paused";
                    return false;
                }
            }
            reason = string.Empty;
            return true;
        }
        var hero = runtimeTestSelectionInjectedHero;
        var seasonData = runtimeTestSelectionSeason;
        if (hero is null || seasonData is null)
        {
            reason = "runtime hero selection lease is incomplete";
            return false;
        }

        var heroFieldData = Read(hero, "heroFieldData");
        var saveHeroData = Read(hero, "saveHeroData");
        var adventureIndexes = new HashSet<int>();
        var runtimeIndex = ReadNullableInt(heroFieldData, "advIndex");
        var savedIndex = ReadNullableInt(saveHeroData, "advIndex");
        if (runtimeIndex is >= 0) adventureIndexes.Add(runtimeIndex.Value);
        if (savedIndex is >= 0) adventureIndexes.Add(savedIndex.Value);

        var adventureData = Read(seasonData, "advData");
        var fields = ReadValues(Read(adventureData, "advFieldList")).ToList();
        object? ownedField = null;
        if (heroFieldData is not null)
        {
            ownedField = fields.FirstOrDefault(field => ReadValues(Read(field, "heroFieldList"))
                .Any(member => NativeEquals(member, heroFieldData)));
        }
        ownedField ??= fields.FirstOrDefault(field =>
        {
            var fieldIndex = ReadNullableInt(Read(field, "saveAdvFieldData"), "index");
            return fieldIndex is not null && adventureIndexes.Contains(fieldIndex.Value);
        });

        if (ownedField is null)
        {
            if (adventureIndexes.Count > 0)
            {
                reason = "runtime hero adventure assignment is still loading";
                return false;
            }
            reason = string.Empty;
            return true;
        }

        var saveField = Read(ownedField, "saveAdvFieldData");
        if (saveField is null)
        {
            reason = "runtime hero adventure field save data is not loaded";
            return false;
        }
        var previousAuto = ReadRequiredBoolProperty(saveField, "isAuto");
        runtimeTestSelectionAutoLeaseActive = true;
        runtimeTestSelectionAutoField = ownedField;
        runtimeTestSelectionAutoSaveField = saveField;
        runtimeTestSelectionPreviousAuto = previousAuto;
        if (runtimeTestSelectionPreviousAuto)
        {
            InvokeRequiredInstance(ownedField, "SetAuto", false);
            if (ReadRequiredBoolProperty(saveField, "isAuto"))
            {
                reason = "runtime hero adventure Auto could not be paused";
                return false;
            }
        }
        reason = string.Empty;
        return true;
    }

    internal static bool TryGetRuntimeTestHeroAdventureBusy(
        out bool busy,
        out string reason)
    {
        busy = true;
        try
        {
            if (!runtimeTestSelectionLeaseActive
                || !runtimeTestSelectionHeroLeaseActive
                || runtimeTestSelectionInjectedHero is null)
            {
                reason = "runtime hero selection lease is incomplete";
                return false;
            }
            if (!TryPrepareRuntimeTestHeroAuto(out reason)) return false;
            busy = Convert.ToBoolean(
                InvokeRequiredInstance(runtimeTestSelectionInjectedHero, "IsAdventureBusy")
                ?? throw new InvalidOperationException("HeroData.IsAdventureBusy returned no value."),
                CultureInfo.InvariantCulture);
            reason = string.Empty;
            return true;
        }
        catch (Exception error)
        {
            reason = $"runtime hero adventure state could not be read: {error.GetBaseException().Message}";
            return false;
        }
    }

    internal static void ReleaseRuntimeTestHeroSelection(out string reason)
    {
        var cleanupNotes = new List<string>();
        if (!runtimeTestSelectionLeaseActive)
        {
            reason = string.Empty;
            return;
        }

        // Restore the selected hero and adventure Auto independently. A failure
        // in one cleanup must never skip the other, and failed cleanup references
        // stay live so teardown can retry instead of silently discarding them.
        if (runtimeTestSelectionHeroLeaseActive)
        {
            try
            {
                var leasedLord = runtimeTestSelectionLord
                                 ?? throw new InvalidOperationException("runtime selected-hero owner is unavailable");
                var currentHero = ReadRequiredProperty(leasedLord, "nowHeroData");
                var stillInjected = runtimeTestSelectionInjectedHero is null
                    ? currentHero is null
                    : NativeEquals(currentHero, runtimeTestSelectionInjectedHero);
                if (stillInjected)
                {
                    Write(leasedLord, "nowHeroData", runtimeTestSelectionPreviousHero);
                    var restored = ReadRequiredProperty(leasedLord, "nowHeroData");
                    var expectedNull = runtimeTestSelectionPreviousHero is null && restored is null;
                    if (!expectedNull && !NativeEquals(restored, runtimeTestSelectionPreviousHero))
                        throw new InvalidOperationException("original selected hero could not be restored");
                }
                else if (!(currentHero is null && runtimeTestSelectionPreviousHero is null)
                         && !NativeEquals(currentHero, runtimeTestSelectionPreviousHero))
                {
                    // Do not overwrite a user/game selection made after the test.
                    cleanupNotes.Add("selected hero changed; restore skipped");
                }
                else
                {
                    // A previous cleanup attempt may have restored the value and
                    // then failed during verification. Treat the exact prior value
                    // (including a real null selection) as already restored.
                }
                runtimeTestSelectionHeroLeaseActive = false;
                runtimeTestSelectionLord = null;
                runtimeTestSelectionPreviousHero = null;
                runtimeTestSelectionInjectedHero = null;
            }
            catch (Exception error)
            {
                cleanupNotes.Add($"selected hero cleanup failed: {error.GetBaseException().Message}");
            }
        }

        if (runtimeTestSelectionAutoLeaseActive)
        {
            try
            {
                var leasedField = runtimeTestSelectionAutoField
                                  ?? throw new InvalidOperationException("runtime adventure Auto field is unavailable");
                var leasedSaveField = runtimeTestSelectionAutoSaveField
                                      ?? throw new InvalidOperationException("runtime adventure Auto save data is unavailable");
                var currentAuto = ReadRequiredBoolProperty(leasedSaveField, "isAuto");
                if (runtimeTestSelectionPreviousAuto && !currentAuto)
                {
                    var currentSaveField = ReadRequiredProperty(leasedField, "saveAdvFieldData");
                    if (NativeEquals(currentSaveField, leasedSaveField))
                        InvokeRequiredInstance(leasedField, "SetAuto", true);
                    else
                    {
                        // SetAuto would target the replacement save object. Restore
                        // only the exact persistent object changed by this lease.
                        Write(leasedSaveField, "isAuto", true);
                    }
                    if (!ReadRequiredBoolProperty(leasedSaveField, "isAuto"))
                        throw new InvalidOperationException("adventure Auto could not be restored");
                }
                else if (!runtimeTestSelectionPreviousAuto && currentAuto)
                {
                    // We never enabled Auto. A true value here belongs to the
                    // user/game and must not be overwritten by diagnostic cleanup.
                    cleanupNotes.Add("adventure Auto changed; restore skipped");
                }
                runtimeTestSelectionAutoLeaseActive = false;
                runtimeTestSelectionAutoField = null;
                runtimeTestSelectionAutoSaveField = null;
                runtimeTestSelectionPreviousAuto = false;
            }
            catch (Exception error)
            {
                cleanupNotes.Add($"adventure Auto cleanup failed: {error.GetBaseException().Message}");
            }
        }

        runtimeTestSelectionLeaseActive = runtimeTestSelectionHeroLeaseActive
                                          || runtimeTestSelectionAutoLeaseActive;
        if (!runtimeTestSelectionLeaseActive)
        {
            runtimeTestSelectionSeason = null;
            Plugin.EndRuntimeNoActivateWindowScope();
        }
        reason = string.Join("; ", cleanupNotes);
    }

    internal static void BeginRuntimeJointBuildProgress()
    {
        lock (RuntimeJointBuildProgressSync)
        {
            runtimeJointBuildProgressClock = Stopwatch.StartNew();
            runtimeJointBuildProgressActive = true;
            runtimeJointBuildLastTraceStage = string.Empty;
        }
        try { System.IO.File.Delete(RuntimeJointBuildTracePath); } catch { }
        WriteRuntimeJointBuildProgress("waiting-safe-state", 0, 0);
    }

    internal static void EndRuntimeJointBuildProgress()
    {
        // Preserve the last real phase for post-run diagnosis. The result file
        // already records completion; overwriting this snapshot with a generic
        // "finished" marker used to hide the exact stage that hit a watchdog.
        lock (RuntimeJointBuildProgressSync)
        {
            runtimeJointBuildProgressActive = false;
            runtimeJointBuildProgressClock = null;
        }
    }

    private static void WriteRuntimeJointBuildProgress(
        string phase,
        int index = 0,
        int total = 0,
        string detail = "")
    {
        long elapsedMilliseconds;
        lock (RuntimeJointBuildProgressSync)
        {
            if (!runtimeJointBuildProgressActive) return;
            elapsedMilliseconds = runtimeJointBuildProgressClock?.ElapsedMilliseconds ?? 0;
        }

        var safePhase = (phase ?? string.Empty)
            .Replace("\r", " ", StringComparison.Ordinal)
            .Replace("\n", " ", StringComparison.Ordinal);
        var safeDetail = (detail ?? string.Empty)
            .Replace("\r", " ", StringComparison.Ordinal)
            .Replace("\n", " ", StringComparison.Ordinal);
        try
        {
            System.IO.File.WriteAllText(
                RuntimeJointBuildProgressPath,
                $"phase={safePhase}\ndetail={safeDetail}\nindex={Math.Max(0, index)}\ntotal={Math.Max(0, total)}\nelapsed_ms={Math.Max(0, elapsedMilliseconds)}\n",
                new UTF8Encoding(false));
            var traceStage = $"{safePhase}|{safeDetail}";
            var appendTrace = false;
            lock (RuntimeJointBuildProgressSync)
            {
                if (!string.Equals(
                        traceStage, runtimeJointBuildLastTraceStage,
                        StringComparison.Ordinal))
                {
                    runtimeJointBuildLastTraceStage = traceStage;
                    appendTrace = true;
                }
            }
            if (appendTrace)
                System.IO.File.AppendAllText(
                    RuntimeJointBuildTracePath,
                    $"{Math.Max(0, elapsedMilliseconds)}|{safePhase}|{Math.Max(0, index)}/{Math.Max(0, total)}|{safeDetail}\n",
                    new UTF8Encoding(false));
        }
        catch
        {
            // Runtime progress must never alter the build transaction.
        }
    }
#endif

    private static void ReportAutoBuildProgress(
        AutoBuildStep step,
        int index = 0,
        int total = 0,
        string detail = "",
        bool writeRuntimeProgress = true,
        bool stageComplete = false)
    {
        var operation = MainThreadNativeGateway.CurrentWorkerOperation;
        if (operation is not null)
        {
            operation.ThrowIfPlanningStopped();
            operation.SetProgress(step, index, total, detail);
        }
#if PATHOFIDLE_RUNTIME_TEST
        if (!writeRuntimeProgress) return;
        var runtimePhase = step switch
        {
            AutoBuildStep.CollectingCandidates => "candidate-collection",
            AutoBuildStep.SearchingLoadouts => stageComplete ? "beam-complete" : "beam",
            AutoBuildStep.CoarseEvaluation => "coarse",
            AutoBuildStep.StructuralScreen => "structural-screen",
            AutoBuildStep.FinalRefinement => "full-refine",
            AutoBuildStep.ApplyingGear or AutoBuildStep.ApplyingSkills => "apply",
            AutoBuildStep.Verifying => "verify",
            AutoBuildStep.RollingBack => "rollback",
            AutoBuildStep.FinalizingStorage => "storage-finalize",
            _ => "planning"
        };
        WriteRuntimeJointBuildProgress(runtimePhase, index, total, detail);
#endif
    }

    private static bool AutoTransformSkillsEnabled
        => MainThreadNativeGateway.CurrentWorkerOperation?.AutoTransformSkills
           ?? Plugin.AutoTransformSkills.Value;

    private static int AutoTransformAttemptLimit
        => MainThreadNativeGateway.CurrentWorkerOperation?.AutoTransformMaxAttempts
           ?? Math.Clamp(Plugin.AutoTransformMaxAttempts.Value, 0, 50);

    private static bool AutoBuildIncludesForgeBonuses
        => MainThreadNativeGateway.CurrentWorkerOperation?.IncludeForgeBonuses ?? true;

    private static void ThrowIfAutoBuildCancellationRequested()
    {
        var operation = MainThreadNativeGateway.CurrentWorkerOperation;
        operation?.ThrowIfPlanningStopped();
    }

    private static bool AutoBuildSearchDeadlineReached()
    {
        var operation = MainThreadNativeGateway.CurrentWorkerOperation;
        return operation is { MutationStarted: false, PlanningDeadlineReached: true };
    }

    private static void ThrowIfAutoBuildSearchDeadlineReached()
    {
        if (AutoBuildSearchDeadlineReached())
            throw new AutoBuildSearchDeadlineException();
    }

    internal static bool TryCaptureAutoBuildTarget(out string targetHeroKey, out string reason)
    {
        var localKey = string.Empty;
        var localReason = string.Empty;
        var captured = MainThreadNativeGateway.Invoke(() =>
        {
            var hero = GetSelectedHero();
            if (hero is null)
            {
                localReason = UiText.L("선택된 영웅이 없습니다.", "No hero is selected.", "未选择英雄。", "未選擇英雄。");
                return false;
            }
            if (Read(hero, "saveHeroData") is null || Read(hero, "heroTalentData") is null)
            {
                localReason = UiText.L(
                    "선택한 영웅 데이터가 아직 준비되지 않았습니다.",
                    "The selected hero data is not ready yet.",
                    "所选英雄的数据尚未准备好。",
                    "所選英雄的資料尚未準備好。");
                return false;
            }
            localKey = GetJointSkillPlanHeroKey(hero);
            if (!string.IsNullOrWhiteSpace(localKey)) return true;
            localReason = UiText.L(
                "선택한 영웅을 안전하게 식별하지 못했습니다.",
                "The selected hero could not be identified safely.",
                "无法安全识别所选英雄。",
                "無法安全識別所選英雄。");
            return false;
        });
        targetHeroKey = localKey;
        reason = localReason;
        return captured;
    }

    internal static void WaitForAutoBuildReadiness()
    {
        var operation = MainThreadNativeGateway.CurrentWorkerOperation;
        if (operation is null) return;
        while (true)
        {
            operation.ThrowIfPlanningStopped();
            if (TryGetAutoBuildReadiness(out var reason))
            {
                if (!operation.MutationStarted) operation.BeginPlanning();
                return;
            }
            // Once the first write has started the Unity thread is held inside
            // the exact transaction. Waiting for a battle/scene state that needs
            // Unity Update to advance would deadlock both threads. Fail fast so
            // the caller can execute its already-captured rollback instead.
            if (operation.MutationStarted)
                throw new InvalidOperationException(
                    $"The selected hero became unsafe during the live Auto Build transaction ({reason}).");
            operation.SetPhase(AutoBuildPhase.WaitingForSafeState, reason);
            Thread.Sleep(100);
        }
    }

    internal static bool TryGetAutoBuildReadiness(out string reason)
    {
        var operation = MainThreadNativeGateway.CurrentWorkerOperation;
        string localReason = string.Empty;
        var ready = MainThreadNativeGateway.Invoke(() => TryGetAutoBuildReadinessCore(operation, out localReason));
        reason = localReason;
        return ready;
    }

    private static bool TryGetAutoBuildReadinessCore(AutoBuildOperation? operation, out string reason)
    {
        var hero = GetSelectedHero();
        if (hero is null)
        {
            reason = UiText.L("선택된 영웅을 기다리는 중", "waiting for a selected hero", "正在等待选择英雄", "正在等待選擇英雄");
            return false;
        }
        if (Read(hero, "saveHeroData") is null || Read(hero, "heroTalentData") is null)
        {
            reason = UiText.L("영웅 데이터가 안정되기를 기다리는 중", "waiting for hero data to settle", "正在等待英雄数据稳定", "正在等待英雄資料穩定");
            return false;
        }
        if (operation is not null
            && !string.Equals(GetJointSkillPlanHeroKey(hero), operation.TargetHeroKey, StringComparison.Ordinal))
            throw new InvalidOperationException(
                UiText.L(
                    "자동 빌드를 요청한 뒤 선택 영웅이 바뀌었습니다. 아무것도 변경하지 않았습니다.",
                    "The selected hero changed after Auto Build was requested. Nothing was changed.",
                    "请求自动构筑后所选英雄已更改。未进行任何更改。",
                    "請求自動配置後所選英雄已變更。未進行任何變更。"));
        reason = string.Empty;
        return true;
    }

    private static object? GetSelectedHeroAfterAutoBuildWait()
    {
        var operation = MainThreadNativeGateway.CurrentWorkerOperation;
        while (true)
        {
            if (operation is not null) WaitForAutoBuildReadiness();
            var hero = GetSelectedHero();
            if (hero is null) return null;
            if (operation is not null
                && !string.Equals(GetJointSkillPlanHeroKey(hero), operation.TargetHeroKey, StringComparison.Ordinal))
                throw new InvalidOperationException(
                    "The selected hero changed before Auto Build planning could start.");
            return hero;
        }
    }

    private static void BeginLiveMutation(
        object expectedHero,
        string? expectedGearFingerprint = null,
        string? expectedSkillFingerprint = null)
    {
        var operation = MainThreadNativeGateway.CurrentWorkerOperation;
        if (operation is null) return;
        Plugin.DiagInfo("AUTO-BUILD MUTATION ENTRY|stage=worker");
        while (true)
        {
            operation.ThrowIfPlanningStopped();

            var reason = string.Empty;
            var entered = MainThreadNativeGateway.Invoke(() =>
            {
                Plugin.DiagInfo("AUTO-BUILD MUTATION ENTRY|stage=main-thread");
                if (!TryGetAutoBuildReadinessCore(operation, out reason)) return false;
                Plugin.DiagInfo("AUTO-BUILD MUTATION ENTRY|stage=ready");
                var selectedHero = GetSelectedHero();
                if (!NativeEquals(expectedHero, selectedHero))
                    throw new InvalidOperationException("The selected hero changed before the build could be applied.");
                Plugin.DiagInfo("AUTO-BUILD MUTATION ENTRY|stage=hero-verified");
                if (!string.IsNullOrEmpty(expectedGearFingerprint)
                    && !string.Equals(expectedGearFingerprint, GetCurrentGearFingerprint(expectedHero), StringComparison.Ordinal))
                    throw new InvalidOperationException("The equipped items changed while Auto Build was calculating.");
                Plugin.DiagInfo("AUTO-BUILD MUTATION ENTRY|stage=gear-verified");
                if (!string.IsNullOrEmpty(expectedSkillFingerprint)
                    && !string.Equals(expectedSkillFingerprint, GetSkillStateFingerprint(expectedHero), StringComparison.Ordinal))
                    throw new InvalidOperationException("The selected hero's skill state changed while Auto Build was calculating.");
                Plugin.DiagInfo("AUTO-BUILD MUTATION ENTRY|stage=skills-verified");
                if (!operation.TryBeginMutation())
                    throw new OperationCanceledException("Auto Build was cancelled before mutation.");
                Plugin.DiagInfo("AUTO-BUILD MUTATION ENTRY|stage=transitioned");
                MainThreadNativeGateway.EnterExclusiveMutation(operation);
                Plugin.DiagInfo("AUTO-BUILD MUTATION ENTRY|stage=exclusive");
                return true;
            });
            if (entered)
            {
                Plugin.DiagInfo("AUTO-BUILD MUTATION ENTRY|stage=complete");
                return;
            }
            if (operation.MutationStarted)
                throw new InvalidOperationException(
                    $"The selected hero became unsafe during the live Auto Build transaction ({reason}).");
            operation.SetPhase(AutoBuildPhase.WaitingForSafeState, reason);
            Thread.Sleep(100);
        }
    }

