    public static string GetGameLanguageCode()
    {
        try
        {
            LogSupportedLanguagesOnce();
            var dataManager = ReadStatic("Game", "dataMgr");
            var index = ReadNullableInt(Read(dataManager, "nativeData"), "l10nIndex") ?? 0;
            object? row = null;
            foreach (var candidate in new[] { index, index + 1 })
            {
                row = InvokeStatic("TableData", "getTLanguageData", candidate);
                if (row is not null) break;
            }
            var value = ((ReadString(row, "shortName") ?? ReadString(row, "name") ?? string.Empty).Trim()).ToLowerInvariant();
            if (value.Contains("ko") || value.Contains("kr") || value.Contains("korean") || value.Contains("한국")) return "ko";
            if (value.Contains("tchinese") || value == "tc" || value.Contains("traditional") || value.Contains("繁")) return "zh-tw";
            if (value.Contains("schinese") || value == "sc" || value.Contains("cn") || value.Contains("simplified") || value.Contains("简")) return "zh-cn";
            return "en";
        }
        catch
        {
            return "en";
        }
    }

    public static AutoBuildSummary GetSelectedHeroBuildSummary()
    {
        try
        {
            var hero = GetSelectedHero();
            if (hero is null)
                return new AutoBuildSummary(string.Empty, string.Empty, UiText.L("게임에서 최적화할 영웅을 선택하세요.", "Select a hero in the game to optimize.", "请在游戏中选择要优化的英雄。", "請在遊戲中選擇要最佳化的英雄。"));

            var save = Read(hero, "saveHeroData");
            var job = Read(hero, "tHeroJobData");
            var name = Clean(ReadString(save, "name") ?? InvokeString(save ?? hero, "GetL10nName") ?? UiText.L("이름 없는 영웅", "Unnamed hero", "未命名英雄", "未命名英雄"));
            var jobName = Clean(ReadString(hero, "jobName") ?? ReadString(job, "name") ?? UiText.L("직업 미상", "Unknown job", "未知职业", "未知職業"));
            var level = ReadNullableInt(save, "level") ?? 0;
            var quality = ReadNullableInt(save, "quality") ?? 0;
            var requestedTheme = GetHeroBuildTheme(hero);
            var focus = ResolveHeroFocus(hero, requestedTheme);
            var heroLine = $"{name}  ·  {jobName}  ·  Lv.{level}  ·  Q{quality}";
            var profile = requestedTheme == "auto"
                ? UiText.L($"자동 목표: {focus.Localized}  ·  공식 장비 추천 보너스 없음", $"Auto objective: {focus.English}  ·  no official-gear bonus", $"自动目标：{focus.Localized} · 无官方装备加成", $"自動目標：{focus.Localized} · 無官方裝備加成")
                : UiText.L($"선택 목표: {focus.Localized}  ·  공식 장비 추천 보너스 없음", $"Selected objective: {focus.English}  ·  no official-gear bonus", $"所选目标：{focus.Localized} · 无官方装备加成", $"所選目標：{focus.Localized} · 無官方裝備加成");
            return new AutoBuildSummary(heroLine, profile, UiText.L("자동 장착할 기능을 선택하세요.", "Choose an optimization action.", "请选择自动优化功能。", "請選擇自動最佳化功能。"));
        }
        catch (Exception error)
        {
            return new AutoBuildSummary(string.Empty, string.Empty, UiText.L($"영웅 데이터 대기 중: {error.Message}", $"Waiting for hero data: {error.Message}", $"正在等待英雄数据：{error.Message}", $"正在等待英雄資料：{error.Message}"));
        }
    }

    public static bool TryLogTeamRecommendations()
    {
        try
        {
            var dataManager = ReadStatic("Game", "dataMgr");
            var seasonData = Read(dataManager, "nowSeasonData");
            var lordData = Read(seasonData, "lordData");
            var owned = new List<TeamCandidate>();
            foreach (var field in ReadList(Read(lordData, "heroFieldList")))
            {
                var hero = Read(field, "heroData");
                if (hero is null) continue;
                var save = Read(hero, "saveHeroData");
                var key = $"hero:{ReadNullableInt(save, "uniqueId") ?? owned.Count}";
                var name = Clean(ReadString(save, "name") ?? InvokeString(save ?? hero, "GetL10nName") ?? key);
                var job = Clean(ReadString(hero, "jobName") ?? ReadString(Read(hero, "tHeroJobData"), "name") ?? "?");
                var textParts = new List<string>
                {
                    EnglishName(Read(hero, "tHeroJobData"), job) ?? job,
                    EnglishText(Read(hero, "tHeroJobData"), "_des", string.Empty) ?? string.Empty
                };
                var buildHints = new List<string>();
                foreach (var talent in ReadValues(Read(Read(hero, "heroTalentData"), "talentDic")))
                {
                    var level = Convert.ToInt32(InvokeInstance(talent, "GetLevel") ?? 0, CultureInfo.InvariantCulture);
                    if (level <= 0) continue;
                    var def = Read(talent, "tTalentData");
                    var skill = Read(talent, "skillData");
                    var skillRow = Read(skill, "tSkillData");
                    var info = Read(skill, "tSkillInfoData");
                    var talentName = Clean(EnglishName(skillRow, EnglishName(def, string.Empty)) ?? string.Empty);
                    if (talentName.Length > 0 && buildHints.Count < 2) buildHints.Add(talentName);
                    textParts.Add(talentName);
                    textParts.Add(EnglishText(info, "_des", string.Empty) ?? string.Empty);
                }
                owned.Add(CreateTeamCandidate(key, name, job, string.Join(" ", textParts), hero, string.Join(" / ", buildHints)));
            }
            if (owned.Count < 3) return false;

            var endgame = new List<TeamCandidate>();
            var talentRows = ReadValues(ReadStatic("TableData", "TTalentDict")).ToList();
            foreach (var jobRow in ReadValues(ReadStatic("TableData", "THeroJobDict")))
            {
                var jobId = ReadNullableInt(jobRow, "id") ?? 0;
                if (jobId <= 0) continue;
                var jobName = Clean(ReadString(jobRow, "name") ?? EnglishName(jobRow, $"Job {jobId}") ?? $"Job {jobId}");
                var textParts = new List<string> { EnglishName(jobRow, jobName) ?? jobName, EnglishText(jobRow, "_des", string.Empty) ?? string.Empty };
                var hints = new List<string>();
                foreach (var talent in talentRows.Where(row => ReadNullableInt(row, "jobId") == jobId))
                {
                    var skillId = ReadNullableInt(talent, "skillId") ?? 0;
                    var masteryId = ReadNullableInt(talent, "masteryId") ?? 0;
                    var skill = skillId > 0 ? InvokeStatic("TableData", "getTSkillData", skillId) : null;
                    var infoId = ReadNullableInt(skill, "infoId") ?? 0;
                    var info = infoId > 0 ? InvokeStatic("TableData", "getTSkillInfoData", infoId) : null;
                    var mastery = masteryId > 0 ? InvokeStatic("TableData", "getTMasteryData", masteryId) : null;
                    var hint = Clean(EnglishName(skill, EnglishName(mastery, EnglishName(talent, string.Empty))) ?? string.Empty);
                    if (hint.Length > 0 && !hints.Contains(hint, StringComparer.OrdinalIgnoreCase) && hints.Count < 3) hints.Add(hint);
                    textParts.Add(hint);
                    textParts.Add(EnglishText(info, "_des", string.Empty) ?? string.Empty);
                }
                endgame.Add(CreateTeamCandidate($"job:{jobId}", jobName, jobName, string.Join(" ", textParts), null, string.Join(" / ", hints.Take(2))));
            }
            if (endgame.Count < 3) return false;

            LogTeamSet("OWNED", FindBestTeams(owned));
            LogTeamSet("ENDGAME", FindBestTeams(endgame));
            return true;
        }
        catch (Exception error)
        {
            Plugin.DiagDebug($"Team recommendation report deferred: {error.Message}");
            return false;
        }
    }

    private static TeamCandidate CreateTeamCandidate(string key, string name, string job, string rawText, object? hero, string buildHint)
    {
        var text = Clean(rawText).ToLowerInvariant();
        var offense = 30d + KeywordScore(text, PhysicalWords.Concat(ElementalWords)) * 8d;
        var defense = 15d + KeywordScore(text, TankWords) * 12d;
        var support = 10d + KeywordScore(text, SupportWords) * 13d;
        var control = 8d + KeywordScore(text, new[] { "debuff", "weaken", "slow", "stun", "bleed", "corrosion", "ailment", "freeze", "armor break", "shatter" }) * 11d;
        var power = 40d;
        if (hero is not null)
        {
            offense += Math.Log10(1d + Math.Max(0d, ReadHeroAttr(hero, 1) + ReadHeroAttr(hero, 2))) * 14d;
            defense += Math.Log10(1d + Math.Max(0d, ReadHeroAttr(hero, 3) + ReadHeroAttr(hero, 4) + ReadHeroAttr(hero, 5))) * 12d;
            power = Math.Log10(1d + Math.Max(0d, ReadHeroAttr(hero, 1) + ReadHeroAttr(hero, 2) + ReadHeroAttr(hero, 3) + ReadHeroAttr(hero, 4) + ReadHeroAttr(hero, 5))) * 18d;
            power += (ReadNullableInt(Read(hero, "saveHeroData"), "level") ?? 0) * 0.35d + (ReadNullableInt(Read(hero, "saveHeroData"), "quality") ?? 0) * 4d;
        }
        var themes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var theme in new Dictionary<string, string[]>
        {
            ["fire"] = new[] { "fire", "burn" }, ["ice"] = new[] { "ice", "frost", "freeze" }, ["lightning"] = new[] { "lightning", "shock" },
            ["physical"] = new[] { "physical", "martial", "blunt", "slash", "pierce" }, ["crit"] = new[] { "crit", "critical" },
            ["bleed"] = new[] { "bleed" }, ["corrosion"] = new[] { "corrosion", "poison" }, ["summon"] = new[] { "summon", "minion" },
            ["aura"] = new[] { "aura", "ally", "buff" }, ["debuff"] = new[] { "debuff", "weaken", "ailment" }
        }) if (theme.Value.Any(word => text.Contains(word, StringComparison.OrdinalIgnoreCase))) themes.Add(theme.Key);
        return new TeamCandidate(key, name, job, offense, defense, support, control, power, themes, buildHint);
    }

    private static List<TeamSuggestion> FindBestTeams(List<TeamCandidate> candidates)
    {
        var results = new List<TeamSuggestion>();
        for (var a = 0; a < candidates.Count - 2; a++)
        for (var b = a + 1; b < candidates.Count - 1; b++)
        for (var c = b + 1; c < candidates.Count; c++)
        {
            var team = new[] { candidates[a], candidates[b], candidates[c] };
            var offense = team.Sum(hero => hero.Offense);
            var defense = team.Sum(hero => hero.Defense);
            var support = team.Sum(hero => hero.Support);
            var control = team.Sum(hero => hero.Control);
            var score = team.Sum(hero => hero.Power) * 0.65d + offense * 0.35d + defense * 0.30d + support * 0.36d + control * 0.18d;
            var reasons = new List<string>();
            if (team.Any(hero => hero.Defense >= 45d) && team.Any(hero => hero.Support >= 38d)) { score += 42d; reasons.Add("frontline+support"); }
            if (team.Any(hero => hero.Offense >= 65d) && team.Any(hero => hero.Support >= 38d)) { score += 28d; reasons.Add("carry+buff"); }
            var shared = team.SelectMany(hero => hero.Themes).GroupBy(theme => theme, StringComparer.OrdinalIgnoreCase).Where(group => group.Count() >= 2).OrderByDescending(group => group.Count()).Select(group => group.Key).Take(2).ToList();
            score += shared.Count * 24d;
            if (shared.Count > 0) reasons.Add(string.Join("+", shared));
            if (team.Select(hero => hero.Job).Distinct(StringComparer.OrdinalIgnoreCase).Count() == 3) score += 12d;
            results.Add(new TeamSuggestion(team[0], team[1], team[2], score, reasons.Count == 0 ? "balanced roles" : string.Join(", ", reasons)));
        }
        return results.OrderByDescending(result => result.Score).Take(3).ToList();
    }

    [Conditional("PATHOFIDLE_DIAGNOSTICS")]
    private static void LogTeamSet(string scope, List<TeamSuggestion> teams)
    {
        for (var index = 0; index < teams.Count; index++)
        {
            var team = teams[index];
            Plugin.DiagInfo($"TEAM-{scope}|{index + 1}|{team.Score:0.0}|{team.A.Name} [{team.A.Job}] + {team.B.Name} [{team.B.Job}] + {team.C.Name} [{team.C.Job}]|{team.Reason}|{team.A.BuildHint} ; {team.B.BuildHint} ; {team.C.BuildHint}");
        }
    }

    public static bool TryOptimizeSelectedHeroGear(bool includeStorage, out string message)
        => TryOptimizeSelectedHeroGear(includeStorage, false, out _, out _, out message);

#if PATHOFIDLE_RUNTIME_TEST
    internal static AutoBuildPlanningPreviewResult PreviewSelectedHeroAutoBuild(bool includeStorage)
    {
        try
        {
            var succeeded = TryOptimizeSelectedHeroGear(
                includeStorage,
                false,
                out _,
                out _,
                out var message,
                previewOnly: true);
            return new AutoBuildPlanningPreviewResult(succeeded, false, message);
        }
        catch (OperationCanceledException)
        {
            return new AutoBuildPlanningPreviewResult(
                false, true, "read-only Auto Build preview cancelled");
        }
        catch (Exception error)
        {
            return new AutoBuildPlanningPreviewResult(
                false, false, error.GetBaseException().Message);
        }
    }
#endif

    private static bool TryOptimizeSelectedHeroGear(
        bool includeStorage,
        bool combinedFlow,
        out bool gearCommitted,
        out PendingGearCommit? pendingGearCommit,
        out string message,
        bool previewOnly = false)
    {
        gearCommitted = false;
        pendingGearCommit = null;
        var moveJournal = new List<MoveReceipt>();
        object? gearTalentData = null;
        object? rollbackHero = null;
        string? rollbackGearFingerprint = null;
        GearAbilityBaseline? rollbackAbilityBaseline = null;
        var irreversibleStorageNormalizationStarted = false;
        var jointPlanRemembered = false;
        try
        {
            var hero = GetSelectedHeroAfterAutoBuildWait();
            if (hero is null)
            {
                message = UiText.L("선택된 영웅이 없습니다.", "No hero is selected.", "未选择英雄。", "未選擇英雄。");
                return false;
            }
            rollbackHero = hero;
            var dataManager = ReadStatic("Game", "dataMgr");
            var seasonData = Read(dataManager, "nowSeasonData");
            var lordData = Read(seasonData, "lordData");
            if (lordData is null) throw new InvalidOperationException("Lord data is unavailable.");
            ReportAutoBuildProgress(AutoBuildStep.CollectingCandidates);
            var focus = MainThreadNativeGateway.Invoke(() =>
                ResolveHeroFocus(hero, GetHeroBuildTheme(hero)));
            var profile = BuildHeroEffectProfile(hero, focus);
            // Freeze one resource-limited incoming-pressure profile before any
            // candidate is evaluated. Candidate offense can therefore never
            // make its own defense test easier or harder.
            var incomingPressure = MainThreadNativeGateway.Invoke(() =>
                CaptureDefensePressureProfile(hero));
            ReportAutoBuildProgress(
                AutoBuildStep.CollectingCandidates,
                detail: UiText.L("현재 장비 상태 복사 중", "Snapshotting current equipment", "正在复制当前装备状态", "正在複製目前裝備狀態"));
            var currentSnapshot = MainThreadNativeGateway.Invoke(() =>
            {
                var talentDataSnapshot = Read(hero, "heroTalentData");
                var slotSnapshot = GetGearSlots();
                var equippedSnapshot = slotSnapshot.ToDictionary(
                    slot => slot,
                    slot => GetEquippedItem(hero, slot.Part, slot.MainWeapon));
                return (
                    TalentData: talentDataSnapshot,
                    Slots: slotSnapshot,
                    Equipped: equippedSnapshot,
                    GearFingerprint: GetCurrentGearFingerprint(hero),
                    SkillFingerprint: GetSkillStateFingerprint(hero));
            });
            gearTalentData = currentSnapshot.TalentData;
            var slots = currentSnapshot.Slots;
            var currentBySlot = currentSnapshot.Equipped;
            var originalGearFingerprint = currentSnapshot.GearFingerprint;
            rollbackGearFingerprint = originalGearFingerprint;
            var originalSkillFingerprint = currentSnapshot.SkillFingerprint;
            // Capture non-gear ability counts before the first move. Post-equip
            // verification can then prove the exact count delta instead of a
            // same-ID class/skill ability masking a missing gear ability.
            var currentItems = currentBySlot.Values
                .Where(item => item is not null).Cast<object>().ToList();
            var abilityBaseline = MainThreadNativeGateway.Invoke(() =>
                CaptureGearAbilityBaseline(hero, currentItems));
            rollbackAbilityBaseline = abilityBaseline;
            // Snapshot the current eight-slot loadout, but do not score or fully
            // refine it yet. A current-first refinement consumed the search
            // budget before any challenger was evaluated and made a deadline
            // look like proof that the unchanged gear was best.
            ReportAutoBuildProgress(
                AutoBuildStep.CollectingCandidates,
                detail: UiText.L("현재 8부위 비교 기준 복사 중", "Snapshotting the current 8-slot comparison baseline", "正在复制当前 8 部位对比基准", "正在複製目前 8 部位比較基準"));
            var currentCandidates = new List<GearCandidate>();
            foreach (var slotBatch in slots.Chunk(4))
            {
                var batch = slotBatch.ToList();
                var converted = MainThreadNativeGateway.Invoke(() => batch
                    .Select(slot => currentBySlot[slot] is { } item
                        ? CreateGearCandidate(
                            DescribeEquipmentSource(
                                item,
                                UiText.L("현재 착용", "Equipped", "当前装备", "目前裝備"),
                                StorageKind.Inventory,
                                StorageSource.Equipped),
                            hero,
                            profile,
                            allowExistingEquippedItem: true)
                        : null)
                    .Where(candidate => candidate is not null).Cast<GearCandidate>()
                    .ToList());
                currentCandidates.AddRange(converted);
            }
            LoadoutState? currentState = null;
            var currentStateKey = string.Empty;
            (LoadoutState State, LoadoutEvaluation Evaluation)? currentIncumbent = null;
            if (currentCandidates.Count == slots.Count)
            {
                currentState = new LoadoutState(
                    currentCandidates,
                    currentCandidates.Select(candidate => candidate.Key).ToHashSet(StringComparer.Ordinal),
                    currentCandidates.SelectMany(candidate => candidate.NonStackingEffectKeys)
                        .ToHashSet(StringComparer.Ordinal),
                    currentCandidates.Sum(candidate => candidate.Score));
                currentStateKey = string.Join("|", currentState.Items.Select(item => item.Key));
            }
            var alternativeCandidatesDiscovered = 0;
            var alternativeComparisonsAttempted = 0;
            var alternativeComparisonsValid = 0;
            var alternativeComparisonsRejected = 0;
            var comparisonDeadlineExits = 0;
            var honestComparisonReady = false;
            var transactionalVaultCandidatesConsidered = 0;
            var transactionalVaultCandidatesSkipped = 0;
            var alternativeComparisonRejectionReasons = new List<string>();
            string ComparisonAudit()
            {
                var audit = UiText.L(
                    $"비현재 후보 발견 {alternativeCandidatesDiscovered} · 제한형 고정 스킬안/네이티브 장비 비교 {alternativeComparisonsAttempted} · 유효 {alternativeComparisonsValid} · 기각 {alternativeComparisonsRejected} · 제한시간 종료 {comparisonDeadlineExits} · Vault 후보 평가 {transactionalVaultCandidatesConsidered} · 복구 공간 부족으로 보류 {transactionalVaultCandidatesSkipped}",
                    $"non-current candidates {alternativeCandidatesDiscovered} · bounded fixed-plan/native gear comparisons {alternativeComparisonsAttempted} · valid {alternativeComparisonsValid} · rejected {alternativeComparisonsRejected} · deadline exits {comparisonDeadlineExits} · Vault candidates evaluated {transactionalVaultCandidatesConsidered} · deferred for rollback capacity {transactionalVaultCandidatesSkipped}",
                    $"非当前候选 {alternativeCandidatesDiscovered} · 有界固定技能方案/原生装备比较 {alternativeComparisonsAttempted} · 有效 {alternativeComparisonsValid} · 拒绝 {alternativeComparisonsRejected} · 超时结束 {comparisonDeadlineExits} · 已评估宝库候选 {transactionalVaultCandidatesConsidered} · 因回滚容量暂缓 {transactionalVaultCandidatesSkipped}",
                    $"非目前候選 {alternativeCandidatesDiscovered} · 有界固定技能方案/原生裝備比較 {alternativeComparisonsAttempted} · 有效 {alternativeComparisonsValid} · 拒絕 {alternativeComparisonsRejected} · 逾時結束 {comparisonDeadlineExits} · 已評估寶庫候選 {transactionalVaultCandidatesConsidered} · 因復原容量暫緩 {transactionalVaultCandidatesSkipped}");
#if PATHOFIDLE_RUNTIME_TEST
                if (alternativeComparisonRejectionReasons.Count > 0)
                    audit += $" · rejection reasons [{string.Join(" | ", alternativeComparisonRejectionReasons)}]";
#endif
                return audit;
            }
            var maxMythic = Convert.ToInt32(
                InvokeRequiredStaticMany("HeroEquipData", "GetMaxMythEquipCount", hero)
                ?? throw new InvalidOperationException("The native Mythic equipment limit is unavailable."),
                CultureInfo.InvariantCulture);
            if (maxMythic is < 0 or > 8)
                throw new InvalidOperationException($"The native Mythic equipment limit is invalid ({maxMythic}).");
            Plugin.DiagInfo($"AUTO-GEAR MYTHIC LIMIT|heroLevel={ReadNullableInt(Read(hero, "saveHeroData"), "level") ?? 0}|limit={maxMythic}");
            var candidates = new List<GearCandidate>(currentCandidates);
            (LoadoutState State, LoadoutEvaluation Evaluation) winner;
            var winnerApplicationReady = false;
            if (AutoBuildSearchDeadlineReached())
            {
                if (currentIncumbent is null) goto DeadlineWithoutComplete;
                winner = currentIncumbent.Value;
                winnerApplicationReady = true;
                goto WinnerSelected;
            }

            {
            // Auto Build needs the native item/source objects and a few display
            // fields, not the search page's fully localized tooltip, every set
            // member description, or multilingual affix text. Building those
            // strings for the whole warehouse dominated planning time without
            // contributing to any score.
            ReportAutoBuildProgress(
                AutoBuildStep.CollectingCandidates,
                detail: UiText.L("장비 원본 목록 복사 중", "Snapshotting equipment sources", "正在复制装备来源", "正在複製裝備來源"));
            var recordSnapshot = MainThreadNativeGateway.Invoke(() =>
            {
                var equippedKeys = currentItems
                    .Select(item => NativeObjectKey(item, item)).ToHashSet(StringComparer.Ordinal);
                var allRecords = ReadAllEquipmentSources(includeStorage)
                    .Where(record => !equippedKeys.Contains(NativeObjectKey(record.ItemData, record.ItemData)))
                    .ToList();
                // Vault equipment is a real owned source and must participate in
                // the same shortlist as bag/Warehouse gear. A failed combined
                // transaction never calls the game's known-blocking Vault
                // reinsertion path: extracted candidates are preserved in
                // preflighted ordinary-Warehouse rollback slots instead.
                var vaultCandidates = allRecords.Count(record =>
                    record.StorageSource == StorageSource.Treasure);
                return (Records: allRecords, VaultCandidates: vaultCandidates, VaultSkipped: 0);
            });
            var records = recordSnapshot.Records;
            transactionalVaultCandidatesConsidered = recordSnapshot.VaultCandidates;
            transactionalVaultCandidatesSkipped = recordSnapshot.VaultSkipped;

            // Full affix/effect scoring is expensive and the warehouse can grow
            // while Auto Build runs. Copy only compatibility, level/power, set,
            // and shallow special-affix identities first. Current equipment was
            // already copied above and is never subject to this bound.
            var sourceRecordCount = records.Count;
            var prefilterFacts = new List<GearPrefilterFact>();
            const int prefilterNativeBatchSize = 64;
            for (var offset = 0; offset < records.Count; offset += prefilterNativeBatchSize)
            {
                ThrowIfAutoBuildCancellationRequested();
                var batch = records.Skip(offset).Take(prefilterNativeBatchSize).ToList();
                var batchFacts = MainThreadNativeGateway.Invoke(() => batch
                    .Select(record => CreateGearPrefilterFact(record, hero, profile))
                    .Where(fact => fact is not null).Cast<GearPrefilterFact>()
                    .ToList());
                prefilterFacts.AddRange(batchFacts);
                ReportAutoBuildProgress(
                    AutoBuildStep.CollectingCandidates,
                    Math.Min(offset + batch.Count, sourceRecordCount),
                    sourceRecordCount,
                    UiText.L("레벨·구조 후보 선별 중", "Screening level and structural candidates", "正在筛选等级和结构候选", "正在篩選等級和結構候選"));
                if (AutoBuildSearchDeadlineReached())
                {
                    if (currentIncumbent is null) goto DeadlineWithoutComplete;
                    winner = currentIncumbent.Value;
                    goto WinnerSelected;
                }
            }

            var shortlistedFacts = SelectGearPrefilterFacts(
                prefilterFacts,
                out var structuralRetained,
                out var structuralRepresentatives);
            records = shortlistedFacts.Select(fact => fact.Record).ToList();
            var perPartShortlist = string.Join(",", shortlistedFacts
                .GroupBy(fact => fact.Identity.Part)
                .OrderBy(group => group.Key)
                .Select(group => $"{group.Key}:{group.Count()}"));
            Plugin.DiagInfo(
                $"AUTO-GEAR PREFILTER|sources={sourceRecordCount}|wearable={prefilterFacts.Count}|shortlisted={records.Count}|structural={structuralRetained}/{structuralRepresentatives}|perPart={perPartShortlist}");

            const int candidateNativeBatchSize = 4;
            for (var offset = 0; offset < records.Count; offset += candidateNativeBatchSize)
            {
                ThrowIfAutoBuildCancellationRequested();
                var batch = records.Skip(offset).Take(candidateNativeBatchSize).ToList();
                var batchCandidates = MainThreadNativeGateway.Invoke(() => batch
                    .Select(record => CreateGearCandidate(record, hero, profile))
                    .Where(candidate => candidate is not null).Cast<GearCandidate>()
                    .ToList());
                candidates.AddRange(batchCandidates);
                ReportAutoBuildProgress(
                    AutoBuildStep.CollectingCandidates,
                    Math.Min(offset + batch.Count, records.Count),
                    records.Count,
                    UiText.L("장비 효과 읽는 중", "Reading equipment effects", "正在读取装备效果", "正在讀取裝備效果"));
                if (AutoBuildSearchDeadlineReached())
                {
                    if (currentIncumbent is null) goto DeadlineWithoutComplete;
                    winner = currentIncumbent.Value;
                    goto WinnerSelected;
                }
            }
            if (AutoBuildSearchDeadlineReached())
            {
                if (currentIncumbent is null) goto DeadlineWithoutComplete;
                winner = currentIncumbent.Value;
                goto WinnerSelected;
            }
            ReportAutoBuildProgress(
                AutoBuildStep.CollectingCandidates,
                candidates.Count,
                candidates.Count);
            if (candidates.Count == 0)
            {
                message = UiText.L("착용 가능한 장비 후보가 없습니다.", "No wearable gear candidates were found.", "没有可穿戴的装备候选。", "沒有可穿戴的裝備候選。");
                return false;
            }
            var selectableSetFacts = BuildSelectableSetFacts(
                profile,
                candidates,
                allowDeadlineExit: true);
            // `selectableSetFacts` protects every same-job joint-plan lane while
            // the beam is still allowed to change skills. Keep a second, stricter
            // view for the already selected package so a Fire/Ice set cannot use
            // the only bounded structural comparison after Auto resolved
            // Lightning (and likewise for every other native role/theme).
            var selectedPlanSetFacts = BuildSelectableSetFacts(
                profile,
                candidates,
                allowDeadlineExit: true,
                relevanceScope: EffectRelevanceScope.SelectedJointPlan);
#if PATHOFIDLE_RUNTIME_TEST
            Plugin.DiagInfo(
                $"AUTO-GEAR STAGE|name=set-facts|selectable={selectableSetFacts.EffectsBySet.Count}|selected={selectedPlanSetFacts.EffectsBySet.Count}|elapsed={MainThreadNativeGateway.CurrentWorkerOperation?.PlanningElapsedSeconds ?? -1d:0.000}");
#endif
            if (AutoBuildSearchDeadlineReached())
            {
                if (currentIncumbent is null) goto DeadlineWithoutComplete;
                winner = currentIncumbent.Value;
                goto WinnerSelected;
            }

            // Search complete eight-slot loadouts (two weapon slots plus six other
            // parts). Keeping equipped pieces in the pool prevents a good existing
            // set from disappearing just because it is no longer in the bag.
            var beam = new List<LoadoutState>
            {
                new(new List<GearCandidate>(), new HashSet<string>(StringComparer.Ordinal), new HashSet<string>(StringComparer.Ordinal), 0d)
            };
            var completedBeamSlots = 0;
            ReportAutoBuildProgress(AutoBuildStep.SearchingLoadouts, 0, slots.Count);
            foreach (var slot in slots)
            {
                ThrowIfAutoBuildCancellationRequested();
                if (AutoBuildSearchDeadlineReached())
                {
                    if (currentIncumbent is null) goto DeadlineWithoutComplete;
                    winner = currentIncumbent.Value;
                    goto WinnerSelected;
                }
                var current = currentBySlot[slot];
                var currentKey = current is null ? string.Empty : NativeObjectKey(current, current);
                var slotCandidates = candidates.Where(candidate => candidate.Part == slot.Part).ToList();
                var options = slotCandidates.OrderByDescending(candidate => candidate.Score)
                    .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).Take(16)
                    .Concat(slotCandidates.OrderByDescending(candidate => candidate.NumericScore)
                        .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).Take(10))
                    .Concat(slotCandidates.OrderByDescending(GetRawCandidatePower)
                        .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).Take(8))
                    .Concat(slotCandidates.Where(candidate => candidate.SetId > 0
                                                       && HasRelevantSetThreshold(
                                                           candidate.SetId,
                                                           selectableSetFacts))
                        .GroupBy(candidate => candidate.SetId)
                        .SelectMany(group => group.OrderByDescending(candidate => candidate.Score)
                            .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).Take(3)))
                    .Concat(slotCandidates.Where(candidate => candidate.Record.Quality == 5)
                        .OrderByDescending(candidate => candidate.Score + candidate.NumericScore * 0.1d)
                        .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).Take(12))
                    .Concat(slotCandidates.Where(candidate => profile.RecommendedEquipmentIds.Contains(candidate.DefinitionId)))
                    .GroupBy(candidate => candidate.Key, StringComparer.Ordinal)
                    .Select(group => group.OrderByDescending(candidate => candidate.Score)
                        .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).First())
                    .OrderByDescending(candidate => candidate.Score)
                    .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal)
                    .Take(36).ToList();
                if (AutoBuildSearchDeadlineReached())
                {
                    if (currentIncumbent is null) goto DeadlineWithoutComplete;
                    winner = currentIncumbent.Value;
                    goto WinnerSelected;
                }
                // The global score cut must not erase independent raw-stat,
                // Mythic, or curated-build lanes. Reserve a small number of
                // representatives after the cut; the full package score still
                // decides the winner later.
                var protectedAlternatives = slotCandidates
                    .OrderByDescending(candidate => candidate.NumericScore)
                    .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).Take(2)
                    .Concat(slotCandidates.OrderByDescending(GetRawCandidatePower)
                        .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).Take(2))
                    .Concat(slotCandidates.Where(candidate => candidate.Record.Quality == 5)
                        .OrderByDescending(GetRawCandidatePower)
                        .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).Take(2))
                    .Concat(slotCandidates.Where(candidate =>
                            profile.RecommendedEquipmentIds.Contains(candidate.DefinitionId))
                        .OrderByDescending(candidate => candidate.Score)
                        .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).Take(2))
                    .DistinctBy(candidate => candidate.Key);
                foreach (var alternative in protectedAlternatives)
                    if (options.All(candidate => candidate.Key != alternative.Key)) options.Add(alternative);
                if (slot.Part == 1)
                {
                    // The prefilter retained every native weapon type; carry one
                    // representative of each into both weapon-slot option lists.
                    // This is structural availability, not a score bonus—the
                    // later native 30-second comparison still decides its value.
                    foreach (var alternative in slotCandidates
                                 .Where(candidate => candidate.WeaponType > 0)
                                 .GroupBy(candidate => candidate.WeaponType)
                                 .OrderBy(group => group.Key)
                                 .Select(group => group
                                     .OrderByDescending(candidate => candidate.Score)
                                     .ThenByDescending(candidate => candidate.NumericScore)
                                     .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal)
                                     .First()))
                    {
                        if (options.All(candidate => candidate.Key != alternative.Key))
                            options.Add(alternative);
                    }
                }
                // The global shortlist above is intentionally small, but its
                // final ordering can otherwise remove every member of a lower-
                // stat set even though those members were concatenated before
                // Take(36). Keep bounded representatives after the global cut so
                // the structural set-completion lanes always have a real item to
                // extend in this slot. One score leader and one numeric leader
                // retain materially different rolls without making the ordinary
                // shortlist unbounded.
                foreach (var alternative in slotCandidates
                             .Where(candidate => candidate.SetId > 0
                                                 && HasRelevantSetThreshold(
                                                     candidate.SetId,
                                                     selectableSetFacts))
                             .GroupBy(candidate => candidate.SetId)
                             .SelectMany(group => group
                                 .OrderByDescending(candidate => candidate.Score)
                                 .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal)
                                 .Take(1)
                                 .Concat(group
                                     .OrderByDescending(candidate => candidate.NumericScore)
                                     .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal)
                                     .Take(1)))
                             .DistinctBy(candidate => candidate.Key))
                {
                    if (options.All(candidate => candidate.Key != alternative.Key))
                        options.Add(alternative);
                    if (AutoBuildSearchDeadlineReached())
                    {
                        if (currentIncumbent is null) goto DeadlineWithoutComplete;
                        winner = currentIncumbent.Value;
                        goto WinnerSelected;
                    }
                }
                // High-value duplicate Uniques can otherwise fill the whole
                // per-slot shortlist. Keep one representative for every narrow
                // exclusive-effect policy signature (and one ordinary
                // alternative), so the beam can compare a different effect.
                foreach (var alternative in slotCandidates
                             .Where(candidate => !candidate.NonStackingEffectKeys.Any(IsHardExclusiveEffectKey)
                                                 || candidate.SelectableFacts.RelevantHardExclusiveKeys.Count > 0)
                             .GroupBy(candidate => GetNonStackingEffectSignature(
                                 candidate.SelectableFacts.RelevantHardExclusiveKeys), StringComparer.Ordinal)
                             .Select(group => group.OrderByDescending(candidate => candidate.Score)
                                 .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal).First())
                             .OrderByDescending(candidate => candidate.Score)
                             .ThenBy(candidate => candidate.StableOrderKey, StringComparer.Ordinal))
                {
                    if (options.All(candidate => candidate.Key != alternative.Key)) options.Add(alternative);
                    if (AutoBuildSearchDeadlineReached())
                    {
                        if (currentIncumbent is null) goto DeadlineWithoutComplete;
                        winner = currentIncumbent.Value;
                        goto WinnerSelected;
                    }
                }
                // Native keeps the highest-level source when several equipment
                // affixes grant the same extra skill. Preserve a max-level
                // representative even when a lower-level, high-stat copy won
                // the ordinary shortlist.
                foreach (var alternative in slotCandidates
                             .SelectMany(candidate => candidate.SelectableFacts.GrantedSkillLevels
                                 .Select(entry => (Candidate: candidate, entry.Key, entry.Value)))
                             .GroupBy(entry => entry.Key, StringComparer.Ordinal)
                             .Select(group => group.OrderByDescending(entry => entry.Value)
                                 .ThenByDescending(entry => entry.Candidate.Score)
                                 .ThenBy(entry => entry.Candidate.StableOrderKey, StringComparer.Ordinal)
                                 .First().Candidate))
                {
                    if (options.All(candidate => candidate.Key != alternative.Key)) options.Add(alternative);
                    if (AutoBuildSearchDeadlineReached())
                    {
                        if (currentIncumbent is null) goto DeadlineWithoutComplete;
                        winner = currentIncumbent.Value;
                        goto WinnerSelected;
                    }
                }
                // A variant item can be worthless for the baseline skill yet be
                // the key to the best jointly selected skill package. Preserve a
                // representative for every exact native variant target ID.
                foreach (var alternative in slotCandidates
                             .SelectMany(candidate => candidate.SelectableFacts.VariantIds
                                 .Select(skillId => (Candidate: candidate, SkillId: skillId)))
                             .GroupBy(entry => entry.SkillId)
                             .Select(group => group.OrderByDescending(entry => GetRawCandidatePower(entry.Candidate))
                                 .ThenByDescending(entry => entry.Candidate.Score)
                                 .ThenBy(entry => entry.Candidate.StableOrderKey, StringComparer.Ordinal)
                                 .First().Candidate))
                {
                    if (options.All(candidate => candidate.Key != alternative.Key)) options.Add(alternative);
                    if (AutoBuildSearchDeadlineReached())
                    {
                        if (currentIncumbent is null) goto DeadlineWithoutComplete;
                        winner = currentIncumbent.Value;
                        goto WinnerSelected;
                    }
                }
                // Conditional/special abilities receive a conservative zero when
                // their battle event cannot be simulated. Preserve one candidate
                // for every exact native ability ID so that a zero lower bound
                // does not prune the entire effect family before finalist review.
                foreach (var alternative in slotCandidates
                             .SelectMany(candidate => candidate.SelectableFacts.NativeAbilityIds
                                 .Select(abilityId => (Candidate: candidate, AbilityId: abilityId)))
                             .GroupBy(entry => entry.AbilityId)
                             .Select(group => group.OrderByDescending(entry => GetRawCandidatePower(entry.Candidate))
                                 .ThenByDescending(entry => entry.Candidate.Score)
                                 .ThenBy(entry => entry.Candidate.StableOrderKey, StringComparer.Ordinal)
                                 .First().Candidate))
                {
                    if (options.All(candidate => candidate.Key != alternative.Key)) options.Add(alternative);
                    if (AutoBuildSearchDeadlineReached())
                    {
                        if (currentIncumbent is null) goto DeadlineWithoutComplete;
                        winner = currentIncumbent.Value;
                        goto WinnerSelected;
                    }
                }
                if (current is not null && options.All(candidate => candidate.Key != currentKey))
                {
                    var currentCandidate = candidates.FirstOrDefault(candidate => candidate.Key == currentKey);
                    if (currentCandidate is not null) options.Add(currentCandidate);
                }

                var expandedBeam = new List<LoadoutState>();
                var expandedCount = 0;
                foreach (var state in beam)
                {
                    foreach (var candidate in options)
                    {
                        ThrowIfAutoBuildCancellationRequested();
                        if ((++expandedCount & 63) == 0
                            && AutoBuildSearchDeadlineReached())
                        {
                            if (currentIncumbent is null) goto DeadlineWithoutComplete;
                            winner = currentIncumbent.Value;
                            goto WinnerSelected;
                        }
                        if (state.UsedKeys.Contains(candidate.Key)) continue;
                        // Only the user's duplicate-Unique policy rejects a
                        // whole item. Boolean variants and highest-level extra
                        // skills remain valid; duplicate score is removed below.
                        if (candidate.SelectableFacts.RelevantHardExclusiveKeys
                            .Any(state.NonStackingEffectKeys.Contains)) continue;
                        if (state.Items.Count(item => item.Record.Quality == 5)
                            + (candidate.Record.Quality == 5 ? 1 : 0) > maxMythic) continue;
                        if (HasLegendMythWeaponConflict(state.Items.Append(candidate))) continue;
                        var combinedItems = state.Items.Append(candidate).ToList();
                        expandedBeam.Add(new LoadoutState(
                            combinedItems,
                            new HashSet<string>(state.UsedKeys, StringComparer.Ordinal) { candidate.Key },
                            UnionEffectKeys(
                                state.NonStackingEffectKeys,
                                candidate.SelectableFacts.RelevantHardExclusiveKeys),
                            ScoreItemsWithDeduplicatedEffects(
                                combinedItems,
                                profile,
                                EffectRelevanceScope.SelectableJointPlan)));
                    }
                }
                if (AutoBuildSearchDeadlineReached())
                {
                    if (currentIncumbent is null) goto DeadlineWithoutComplete;
                    winner = currentIncumbent.Value;
                    goto WinnerSelected;
                }
                // Weapon requirements belong to the jointly selected skill
                // package, not the baseline plan. Pruning here would discard a
                // valid weapon + alternate-skill + Unique-variant combination
                // before finalist evaluation can compare it.
                beam = SelectBeamStatesWithSetCompletionLanes(
                    expandedBeam,
                    profile,
                    selectableSetFacts,
                    360);
#if PATHOFIDLE_RUNTIME_TEST
                Plugin.DiagInfo(
                    $"AUTO-GEAR STAGE|name=beam-slot-{completedBeamSlots + 1}|expanded={expandedBeam.Count}|kept={beam.Count}|elapsed={MainThreadNativeGateway.CurrentWorkerOperation?.PlanningElapsedSeconds ?? -1d:0.000}");
#endif
                if (AutoBuildSearchDeadlineReached())
                {
                    if (currentIncumbent is null) goto DeadlineWithoutComplete;
                    winner = currentIncumbent.Value;
                    goto WinnerSelected;
                }
                if (beam.Count == 0) throw new InvalidOperationException($"No valid loadout remains for {slot.Label}.");
                ReportAutoBuildProgress(
                    AutoBuildStep.SearchingLoadouts,
                    ++completedBeamSlots,
                    slots.Count,
                    slot.Label);
            }
            ReportAutoBuildProgress(
                AutoBuildStep.SearchingLoadouts,
                slots.Count,
                slots.Count,
                stageComplete: true);

            string LoadoutDiversityKey(LoadoutState state)
            {
                var sets = string.Join(",", GetActiveSetLaneKeys(
                    state,
                    profile,
                    EffectRelevanceScope.SelectableJointPlan,
                    selectableSetFacts));
                var granted = string.Join(",", state.Items
                    .SelectMany(item => item.SelectableFacts.GrantedSkillLevels)
                    // Native GetSkillList keeps the highest level when several
                    // equipped affixes grant the same skill. Redundant lower
                    // copies therefore must not manufacture fake diversity and
                    // displace a real set/variant/weapon representative.
                    .GroupBy(entry => entry.Key, StringComparer.Ordinal)
                    .OrderBy(group => group.Key, StringComparer.Ordinal)
                    .Select(group => $"{group.Key}:{group.Max(entry => entry.Value)}"));
                var variants = string.Join(",", state.Items
                    .SelectMany(item => item.SelectableFacts.VariantIds)
                    .Distinct().OrderBy(id => id));
                var abilities = string.Join(",", state.Items
                    .SelectMany(item => item.SelectableFacts.NativeAbilityIds)
                    .Distinct().OrderBy(id => id));
                var weapons = string.Join(",", state.Items.Where(item => item.Part == 1)
                    .Select(item => item.WeaponType).OrderBy(id => id));
                return $"w={weapons}|s={sets}|g={granted}|v={variants}|a={abilities}";
            }

            var finalistStates = beam
                .OrderByDescending(state => state.HeuristicScore + EstimatePartialSetSynergy(
                    state.Items,
                    profile,
                    EffectRelevanceScope.SelectableJointPlan,
                    selectableSetFacts))
                .ThenBy(state => state, StableLoadoutStateComparer.Instance)
                .ThenBy(
                    state => string.Join("|", state.Items.Select(item => item.Key)),
                    StringComparer.Ordinal)
                // Joint skill/variant/set evaluation is intentionally delayed
                // until a complete 8-slot loadout exists. Retain the full beam so
                // an alternate-skill enabler is not discarded by the baseline
                // profile immediately before that exact comparison.
                .Take(360)
                .ToList();
#if PATHOFIDLE_RUNTIME_TEST
            Plugin.DiagInfo(
                $"AUTO-GEAR STAGE|name=finalists|count={finalistStates.Count}|elapsed={MainThreadNativeGateway.CurrentWorkerOperation?.PlanningElapsedSeconds ?? -1d:0.000}");
#endif
            if (finalistStates.Count == 0)
            {
                message = UiText.L(
                    "현재 후보에서는 추천 스킬을 모두 사용할 수 있는 8부위 장비 조합을 찾지 못했습니다.",
                    "No evaluated 8-slot loadout can use every recommended skill with its selected weapons.",
                    "在已评估候选中找不到可用所选武器使用全部推荐技能的 8 部位装备组合。",
                    "在已評估候選中找不到可用所選武器使用全部推薦技能的 8 部位裝備組合。");
                return false;
            }
            string StateKey(LoadoutState state)
                => string.Join("|", state.Items.Select(item => item.Key));
            bool IsCurrentState(LoadoutState state)
                => currentState is not null
                   && string.Equals(StateKey(state), currentStateKey, StringComparison.Ordinal);
            alternativeCandidatesDiscovered = finalistStates.Count(state => !IsCurrentState(state));
            (LoadoutState State, LoadoutEvaluation Evaluation)? bestApplicationReady = null;
            var applicationReadyByState = new Dictionary<
                string,
                (LoadoutState State, LoadoutEvaluation Evaluation)>(StringComparer.Ordinal);
            var coverageGuardReasons = new HashSet<string>(StringComparer.Ordinal);
            void ConsiderApplicationReady(LoadoutState state, LoadoutEvaluation evaluation)
            {
                if (!evaluation.IsValid || !double.IsFinite(evaluation.Score)) return;
                applicationReadyByState[StateKey(state)] = (state, evaluation);

                var currentReady = applicationReadyByState.Values
                    .Where(entry => IsCurrentState(entry.State))
                    .OrderByDescending(entry => entry.Evaluation.Score)
                    .FirstOrDefault();
                var hasCurrentReady = currentReady.State is not null;
                var eligible = new List<(LoadoutState State, LoadoutEvaluation Evaluation)>();
                if (hasCurrentReady) eligible.Add(currentReady);

                foreach (var candidate in applicationReadyByState.Values
                             .Where(entry => !IsCurrentState(entry.State)))
                {
                    if (!hasCurrentReady)
                    {
                        eligible.Add(candidate);
                        continue;
                    }
                    if (candidate.Evaluation.Score
                        <= currentReady.Evaluation.Score + 0.000000001d) continue;
                    if (CanCandidateReplaceCurrentUnderCoverage(
                            currentReady.Evaluation.Score,
                            currentReady.Evaluation.UnmodeledRelevantSetEffectIds,
                            candidate.Evaluation.Score,
                            candidate.Evaluation.ActiveRelevantSetEffectIds,
                            out var coverageReason))
                    {
                        eligible.Add(candidate);
                        continue;
                    }
                    if (coverageGuardReasons.Add(coverageReason))
                        Plugin.DiagWarning($"AUTO-GEAR COVERAGE GUARD|{coverageReason}");
                }

                bestApplicationReady = eligible
                    .OrderByDescending(entry => entry.Evaluation.Score)
                    .ThenBy(entry => IsCurrentState(entry.State) ? 0 : 1)
                    .ThenBy(entry => entry.State, StableLoadoutStateComparer.Instance)
                    .ThenBy(entry => StateKey(entry.State), StringComparer.Ordinal)
                    .Select(entry => ((LoadoutState State, LoadoutEvaluation Evaluation)?)entry)
                    .FirstOrDefault();
            }
            if (AutoBuildSearchDeadlineReached())
            {
                if (bestApplicationReady is null) goto DeadlineWithoutComplete;
                winner = bestApplicationReady.Value;
                winnerApplicationReady = true;
                goto WinnerSelected;
            }
            // Native skill, mastery, trigger and summon previews are reflection-
            // heavy. Preserve both score leaders and one representative of each
            // structural set/variant/granted-skill/weapon family before invoking
            // that joint engine. This avoids freezing the Unity UI for minutes
            // while retaining the combinations that can materially change the
            // selected skill package.
            const int coarseLeaderCount = 12;
            const int coarseMinimumStateLimit = 24;
            const int coarseHardStateLimit = 48;
            var coarseSetLaneStates = finalistStates
                .SelectMany(state => GetActiveSetLaneKeys(
                        state,
                        profile,
                        EffectRelevanceScope.SelectableJointPlan,
                        selectableSetFacts)
                    .Select(lane => (State: state, Lane: lane)))
                .GroupBy(entry => entry.Lane, StringComparer.Ordinal)
                // A threshold representative must be usable, not merely the
                // first high-stat state that reached the piece count. Prefer a
                // loadout compatible with the current complete skill contract;
                // the joint resolver can still replace that package later.
                .Select(group => group
                    .OrderByDescending(entry =>
                        IsLoadoutWeaponCompatible(entry.State.Items, profile))
                    .ThenByDescending(entry => entry.State.HeuristicScore)
                    .ThenBy(entry => entry.State, StableLoadoutStateComparer.Instance)
                    .ThenBy(entry => StateKey(entry.State), StringComparer.Ordinal)
                    .First().State)
                .DistinctBy(state => string.Join("|", state.Items.Select(item => item.Key)))
                .Take(coarseHardStateLimit)
                .ToList();
#if PATHOFIDLE_RUNTIME_TEST
            Plugin.DiagInfo(
                $"AUTO-GEAR STAGE|name=selectable-set-lanes|count={coarseSetLaneStates.Count}|elapsed={MainThreadNativeGateway.CurrentWorkerOperation?.PlanningElapsedSeconds ?? -1d:0.000}");
#endif
            var selectedPlanSetLaneStates = finalistStates
                .SelectMany(state => GetActiveSetLaneKeys(
                        state,
                        profile,
                        EffectRelevanceScope.SelectedJointPlan,
                        selectedPlanSetFacts)
                    .Select(lane => (State: state, Lane: lane)))
                .GroupBy(entry => entry.Lane, StringComparer.Ordinal)
                .Select(group => group
                    .OrderByDescending(entry =>
                        IsLoadoutWeaponCompatible(entry.State.Items, profile))
                    .ThenByDescending(entry => entry.State.HeuristicScore)
                    .ThenBy(entry => entry.State, StableLoadoutStateComparer.Instance)
                    .ThenBy(entry => StateKey(entry.State), StringComparer.Ordinal)
                    .First().State)
                .DistinctBy(state => string.Join("|", state.Items.Select(item => item.Key)))
                .Take(coarseHardStateLimit)
                .ToList();
#if PATHOFIDLE_RUNTIME_TEST
            Plugin.DiagInfo(
                $"AUTO-GEAR STAGE|name=selected-set-lanes|count={selectedPlanSetLaneStates.Count}|elapsed={MainThreadNativeGateway.CurrentWorkerOperation?.PlanningElapsedSeconds ?? -1d:0.000}");
#endif
            // The beam preserves weapon reach, but this second coarse reduction
            // must preserve it again before the four expensive native previews.
            // Keep every individual native weapon type and a bounded set of
            // exact two-slot type combinations, independent of their stat score.
            var coarseWeaponTypeStates = finalistStates
                .SelectMany(state => state.Items
                    .Where(item => item.Part == 1 && item.WeaponType > 0)
                    .Select(item => (State: state, WeaponType: item.WeaponType)))
                .GroupBy(entry => entry.WeaponType)
                .OrderBy(group => group.Key)
                .Select(group => group.First().State)
                .DistinctBy(state => StateKey(state))
                .ToList();
            var coarseWeaponCombinationStates = finalistStates
                .Select(state => new
                {
                    State = state,
                    Key = string.Join(",", state.Items
                        .Where(item => item.Part == 1 && item.WeaponType > 0)
                        .Select(item => item.WeaponType)
                        .OrderBy(value => value))
                })
                .Where(entry => entry.Key.Length > 0)
                .GroupBy(entry => entry.Key, StringComparer.Ordinal)
                .Select(group => group.First().State)
                .DistinctBy(state => StateKey(state))
                .Take(16)
                .ToList();
            var coarseWeaponLaneStates = coarseWeaponTypeStates
                .Concat(coarseWeaponCombinationStates)
                .DistinctBy(state => StateKey(state))
                .ToList();
#if PATHOFIDLE_RUNTIME_TEST
            Plugin.DiagInfo(
                $"AUTO-GEAR STAGE|name=weapon-lanes|count={coarseWeaponLaneStates.Count}|types={string.Join(',', finalistStates.SelectMany(state => state.Items.Where(item => item.Part == 1).Select(item => item.WeaponType)).Where(value => value > 0).Distinct().OrderBy(value => value))}|elapsed={MainThreadNativeGateway.CurrentWorkerOperation?.PlanningElapsedSeconds ?? -1d:0.000}");
#endif
            var coarseStateLimit = Math.Min(
                coarseHardStateLimit,
                Math.Max(coarseMinimumStateLimit,
                    coarseWeaponLaneStates.Count
                    + selectedPlanSetLaneStates.Count
                    + coarseSetLaneStates.Count
                    + coarseLeaderCount));
            // The first complete non-current state owns the first screening
            // reservation. Otherwise score/set reservations can fill the bound
            // with the current gear and recreate the no-op deadline bug.
            var mandatoryChallengerStates = finalistStates
                .Where(state => !IsCurrentState(state))
                .Take(1)
                .ToList();
            // A real active set threshold is a structural finalist, not merely a
            // score-diversity hint. Reserve every bounded set lane before score
            // leaders so leaders cannot consume the old 24-state cap first.
            var coarseCandidateStates = mandatoryChallengerStates
                .Concat(coarseWeaponLaneStates)
                .Concat(selectedPlanSetLaneStates)
                .Concat(coarseSetLaneStates)
                .Concat(finalistStates.Take(coarseLeaderCount))
                .Concat(finalistStates.GroupBy(LoadoutDiversityKey, StringComparer.Ordinal)
                    .Select(group => group.First()))
                .DistinctBy(state => string.Join("|", state.Items.Select(item => item.Key)))
                .Take(coarseStateLimit)
                .ToList();
#if PATHOFIDLE_RUNTIME_TEST
            Plugin.DiagInfo(
                $"AUTO-GEAR STAGE|name=coarse-candidates|count={coarseCandidateStates.Count}|elapsed={MainThreadNativeGateway.CurrentWorkerOperation?.PlanningElapsedSeconds ?? -1d:0.000}");
#endif
            var coarseProgressIndex = 0;
            ReportAutoBuildProgress(
                AutoBuildStep.CoarseEvaluation,
                0,
                coarseCandidateStates.Count);
            var coarseEvaluations = new List<(LoadoutState State, LoadoutEvaluation Evaluation)>();
            foreach (var state in coarseCandidateStates)
            {
                ReportAutoBuildProgress(
                    AutoBuildStep.CoarseEvaluation,
                    ++coarseProgressIndex,
                    coarseCandidateStates.Count);
                // This stage only orders complete beam states before the bounded
                // native structural pass. Running the entire native skill,
                // ability and 30-second combat preview here made "coarse" 1/24
                // spend longer than the whole transaction deadline. No result
                // from this screen is ever applied.
                var coarseScore = state.HeuristicScore + EstimatePartialSetSynergy(
                    state.Items,
                    profile,
                    EffectRelevanceScope.SelectableJointPlan,
                    selectableSetFacts);
                var evaluation = new LoadoutEvaluation(coarseScore, profile);
                coarseEvaluations.Add((state, evaluation));
                // The deadline is cooperative, but only a completed bounded
                // fixed-plan/native gear comparison result may be applied.
                // Heuristic screening never reaches the mutation path.
                if (AutoBuildSearchDeadlineReached())
                {
                    if (bestApplicationReady is null) goto DeadlineWithoutComplete;
                    winner = bestApplicationReady.Value;
                    winnerApplicationReady = true;
                    goto WinnerSelected;
                }
            }
            var coarseFinalists = coarseEvaluations
                .Where(entry => entry.Evaluation.IsValid && double.IsFinite(entry.Evaluation.Score))
                .OrderByDescending(entry => entry.Evaluation.Score)
                .ToList();
            if (coarseFinalists.Count == 0)
            {
                message = UiText.L(
                    "장비·스킬 공동 예비 계산을 완료하지 못해 장비를 변경하지 않았습니다.",
                    "The joint gear/skill pre-evaluation could not be completed, so no gear was changed.",
                    "无法完成装备与技能联合预评估，因此未更换装备。",
                    "無法完成裝備與技能聯合預評估，因此未更換裝備。");
#if PATHOFIDLE_RUNTIME_TEST
                var runtimeFailure = coarseEvaluations.Select(entry => entry.Evaluation.Failure)
                    .FirstOrDefault(value => !string.IsNullOrWhiteSpace(value)) ?? "native preview failed";
                message += $" [runtime: {runtimeFailure}]";
#endif
                return false;
            }
            if (AutoBuildSearchDeadlineReached()) goto DeadlineWithoutComplete;

            // Interactive Auto Build has the operation's configured planning deadline.
            // Resolve a weapon-compatible joint package for the current loadout
            // and at most two challengers; direct diagnostic callers without a
            // worker deadline may use the wider structural refinement below.
            var useBoundedApplicationReadyComparison =
                MainThreadNativeGateway.CurrentWorkerOperation is not null;
            if (useBoundedApplicationReadyComparison)
            {
                var rankedNonCurrentPool = coarseFinalists
                    .Where(entry => !IsCurrentState(entry.State))
                    .DistinctBy(entry => StateKey(entry.State))
                    .ToList();
                // Keep the highest coarse scorer, then reserve a small bounded
                // group of genuinely different structural lanes. A single
                // representative was insufficient when two different 4-piece
                // conditional sets survived the beam: only one reached the
                // expected-proc calculation, so the other could never win on
                // its measured value. Four challengers keeps the UI work bounded
                // while allowing the native comparison to decide between those
                // alternatives instead of forcing either set.
                const int boundedNonCurrentCandidateLimit = 4;
                var rankedNonCurrentStates = rankedNonCurrentPool.Take(1).ToList();
                if (rankedNonCurrentPool.Count > 1)
                {
                    var leader = rankedNonCurrentPool[0];
                    var selectedStateKeys = rankedNonCurrentStates
                        .Select(entry => StateKey(entry.State))
                        .ToHashSet(StringComparer.Ordinal);
                    void ReserveWeaponContractRepresentative(
                        (LoadoutState State, LoadoutEvaluation Evaluation) representative)
                    {
                        if (representative.State is null
                            || rankedNonCurrentStates.Count >= boundedNonCurrentCandidateLimit)
                            return;
                        var key = StateKey(representative.State);
                        if (selectedStateKeys.Add(key))
                            rankedNonCurrentStates.Add(representative);
                    }

                    // Theme contracts are derived before the final skill plan.
                    // Reserve their native base-weapon lanes first; the baseline
                    // profile can still describe an older/current base while a
                    // support, status, summon, or future lane selects another.
                    var requiredThemeBaseWeaponRequirements =
                        MainThreadNativeGateway.Invoke(() =>
                            (profile.PlannedSkills.RequiredBaseSkillIds
                             ?? new HashSet<int>())
                            .Where(id => id > 0)
                            .Select(id => InvokeStatic("TableData", "getTSkillData", id))
                            .Where(row => row is not null)
                            .Select(row => ReadSequence(Read(row, "weaponArr"))
                                .Select(ToInt).Where(value => value > 0).ToHashSet())
                            .Where(required => required.Count > 0)
                            .GroupBy(required => string.Join(",", required.OrderBy(value => value)),
                                StringComparer.Ordinal)
                            .Select(group => group.First())
                            .ToList());
                    foreach (var requiredWeapons in requiredThemeBaseWeaponRequirements)
                    {
                        var themeBaseWeaponRepresentative = rankedNonCurrentPool
                            .FirstOrDefault(entry => entry.State.Items
                                .Where(item => item.Part == 1)
                                .Select(item => item.WeaponType)
                                .Where(value => value > 0)
                                .Any(requiredWeapons.Contains));
                        ReserveWeaponContractRepresentative(themeBaseWeaponRepresentative);
                    }

                    // A raw-stat or set leader must not consume every remaining
                    // finalist slot with weapons that exclude the planned base
                    // skill. Preserve a full fixed-package-compatible candidate,
                    // then a base-compatible candidate whose active rows the
                    // joint resolver may legally replace. These contracts come
                    // from native skill data, so future jobs/items need no IDs.
                    var fixedPackageWeaponRepresentative = rankedNonCurrentPool
                        .FirstOrDefault(entry =>
                            IsLoadoutWeaponCompatible(entry.State.Items, profile));
                    ReserveWeaponContractRepresentative(fixedPackageWeaponRepresentative);
                    if (profile.BaseWeaponRequirement.Count > 0)
                    {
                        var baseWeaponRepresentative = rankedNonCurrentPool
                            .FirstOrDefault(entry => entry.State.Items
                                .Where(item => item.Part == 1)
                                .Select(item => item.WeaponType)
                                .Where(value => value > 0)
                                .Any(profile.BaseWeaponRequirement.Contains));
                        ReserveWeaponContractRepresentative(baseWeaponRepresentative);
                    }

                    // Audit a bounded top slice once, with each distinct item
                    // read only once. Reserve a challenger with lower proven
                    // compatibility debt so a raw-stat leader cannot prune all
                    // loadouts whose skill-specific slots actually function.
                    const int compatibilityDebtAuditLimit = 16;
                    var compatibilityAuditPool = rankedNonCurrentPool
                        .Take(compatibilityDebtAuditLimit).ToList();
                    var compatibilityDebtByState = MainThreadNativeGateway.Invoke(() =>
                    {
                        var itemDebtByKey = compatibilityAuditPool
                            .SelectMany(entry => entry.State.Items)
                            .DistinctBy(item => item.Key, StringComparer.Ordinal)
                            .ToDictionary(
                                item => item.Key,
                                item => ScoreEquipment(
                                        item.Record.ItemData,
                                        profile,
                                        EffectRelevanceScope.SelectedJointPlan)
                                    .InactiveSpecialEffects.Count,
                                StringComparer.Ordinal);
                        return compatibilityAuditPool.ToDictionary(
                            entry => StateKey(entry.State),
                            entry => entry.State.Items.Sum(item =>
                                         itemDebtByKey.GetValueOrDefault(item.Key))
                                     + ScoreInactiveSetThresholdOpportunityCost(
                                         entry.State.Items, profile).Count,
                            StringComparer.Ordinal);
                    });
                    int CompatibilityDebt(LoadoutState state)
                        => compatibilityDebtByState.GetValueOrDefault(
                            StateKey(state), int.MaxValue);
                    var leaderDiversity = LoadoutDiversityKey(leader.State);
                    var leaderSelectedSetLanes = GetActiveSetLaneKeys(
                            leader.State,
                            profile,
                            EffectRelevanceScope.SelectedJointPlan,
                            selectedPlanSetFacts)
                        .ToHashSet(StringComparer.Ordinal);
                    var leaderSetLanes = GetActiveSetLaneKeys(
                            leader.State,
                            profile,
                            EffectRelevanceScope.SelectableJointPlan,
                            selectableSetFacts)
                        .ToHashSet(StringComparer.Ordinal);
                    var structuralCandidates = rankedNonCurrentPool.Skip(1)
                        .Select(entry => new
                        {
                            Entry = entry,
                            SelectedPlanSetLanes = GetActiveSetLaneKeys(
                                    entry.State,
                                    profile,
                                    EffectRelevanceScope.SelectedJointPlan,
                                    selectedPlanSetFacts)
                                .ToList(),
                            NewSetLanes = GetActiveSetLaneKeys(
                                    entry.State,
                                    profile,
                                    EffectRelevanceScope.SelectableJointPlan,
                                    selectableSetFacts)
                                .Where(lane => !leaderSetLanes.Contains(lane))
                                .ToList(),
                            CompatibilityDebt = CompatibilityDebt(entry.State),
                            DifferentStructure = !string.Equals(
                                LoadoutDiversityKey(entry.State),
                                leaderDiversity,
                                StringComparison.Ordinal)
                        })
                        // The selected package is the actual fixed comparison
                        // contract. Prefer a set threshold it can activate; only
                        // then use the broader same-job set/variant diversity as
                        // the fallback. The native score still decides the winner.
                        .OrderByDescending(candidate => candidate.SelectedPlanSetLanes
                            .Count(lane => !leaderSelectedSetLanes.Contains(lane)) > 0)
                        .ThenByDescending(candidate => candidate.SelectedPlanSetLanes
                            .Count(lane => !leaderSelectedSetLanes.Contains(lane)))
                        .ThenByDescending(candidate => candidate.NewSetLanes.Count > 0)
                        .ThenByDescending(candidate => candidate.NewSetLanes.Count)
                        .ThenByDescending(candidate => candidate.DifferentStructure)
                        .ThenByDescending(candidate => candidate.Entry.Evaluation.Score)
                        .ThenBy(candidate => candidate.Entry.State, StableLoadoutStateComparer.Instance)
                        .ThenBy(candidate => StateKey(candidate.Entry.State), StringComparer.Ordinal)
                        .ToList();

                    var compatibilityRepresentative = structuralCandidates
                        .Where(candidate => candidate.CompatibilityDebt < int.MaxValue)
                        .OrderBy(candidate => candidate.CompatibilityDebt)
                        .ThenByDescending(candidate => candidate.Entry.Evaluation.Score)
                        .ThenBy(candidate => candidate.Entry.State, StableLoadoutStateComparer.Instance)
                        .ThenBy(candidate => StateKey(candidate.Entry.State), StringComparer.Ordinal)
                        .FirstOrDefault();
                    if (compatibilityRepresentative is not null
                        && compatibilityRepresentative.CompatibilityDebt
                           < CompatibilityDebt(leader.State))
                        rankedNonCurrentStates.Add(compatibilityRepresentative.Entry);

                    // Reserve one candidate per newly activated threshold before
                    // filling spare slots. Merely deduplicating the full diversity
                    // key still allowed weapon permutations of one 4-piece set to
                    // consume every slot ahead of another 4-piece set.
                    var remainingSlots = boundedNonCurrentCandidateLimit
                                         - rankedNonCurrentStates.Count;
                    var keysBeforeSetLanes = rankedNonCurrentStates
                        .Select(entry => StateKey(entry.State))
                        .ToHashSet(StringComparer.Ordinal);
                    var laneRepresentatives = structuralCandidates
                        .Where(candidate => !keysBeforeSetLanes.Contains(
                            StateKey(candidate.Entry.State)))
                        .SelectMany(candidate => candidate.NewSetLanes.Select(lane => new
                        {
                            Candidate = candidate,
                            Lane = lane
                        }))
                        .GroupBy(entry => entry.Lane, StringComparer.Ordinal)
                        .Select(group => group.First().Candidate)
                        .DistinctBy(candidate => StateKey(candidate.Entry.State), StringComparer.Ordinal)
                        .Take(remainingSlots)
                        .Select(candidate => candidate.Entry)
                        .ToList();
                    rankedNonCurrentStates.AddRange(laneRepresentatives);

                    remainingSlots = boundedNonCurrentCandidateLimit
                                     - rankedNonCurrentStates.Count;
                    if (remainingSlots > 0)
                    {
                        var selectedKeys = rankedNonCurrentStates
                            .Select(entry => StateKey(entry.State))
                            .ToHashSet(StringComparer.Ordinal);
                        var fillRepresentatives = structuralCandidates
                            .Where(candidate => !selectedKeys.Contains(
                                StateKey(candidate.Entry.State)))
                            .DistinctBy(candidate => LoadoutDiversityKey(candidate.Entry.State),
                                StringComparer.Ordinal)
                            .Take(remainingSlots)
                            .Select(candidate => candidate.Entry);
                        rankedNonCurrentStates.AddRange(fillRepresentatives);
                    }
                }

                if (rankedNonCurrentStates.Count > 1)
                {
                    // Keep the raw-score leader first, but make the next exact
                    // comparison exercise a genuinely new, usable set threshold
                    // before another near-identical no-set stat variant. The
                    // planning window can otherwise expire after two no-set
                    // candidates even though a relevant 4-piece lane was safely
                    // preserved in the bounded pool. Set identities and piece
                    // counts remain entirely data-derived.
                    var scoreLeader = rankedNonCurrentStates[0];
                    var leaderSelectedLanes = GetActiveSetLaneKeys(
                            scoreLeader.State,
                            profile,
                            EffectRelevanceScope.SelectedJointPlan,
                            selectedPlanSetFacts)
                        .ToHashSet(StringComparer.Ordinal);
                    var leaderSelectableLanes = GetActiveSetLaneKeys(
                            scoreLeader.State,
                            profile,
                            EffectRelevanceScope.SelectableJointPlan,
                            selectableSetFacts)
                        .ToHashSet(StringComparer.Ordinal);
                    rankedNonCurrentStates = rankedNonCurrentStates
                        .DistinctBy(entry => StateKey(entry.State))
                        .Select((entry, index) => new
                        {
                            Entry = entry,
                            Index = index,
                            NewSelectedLanes = GetActiveSetLaneKeys(
                                    entry.State,
                                    profile,
                                    EffectRelevanceScope.SelectedJointPlan,
                                    selectedPlanSetFacts)
                                .Count(lane => !leaderSelectedLanes.Contains(lane)),
                            NewSelectableLanes = GetActiveSetLaneKeys(
                                    entry.State,
                                    profile,
                                    EffectRelevanceScope.SelectableJointPlan,
                                    selectableSetFacts)
                                .Count(lane => !leaderSelectableLanes.Contains(lane))
                        })
                        .OrderBy(candidate => candidate.Index == 0 ? 0 : 1)
                        .ThenByDescending(candidate => candidate.NewSelectedLanes)
                        .ThenByDescending(candidate => candidate.NewSelectableLanes)
                        .ThenBy(candidate => candidate.Index)
                        .Take(boundedNonCurrentCandidateLimit)
                        .Select(candidate => candidate.Entry)
                        .ToList();
                }
#if PATHOFIDLE_RUNTIME_TEST
                foreach (var picked in rankedNonCurrentStates.Select((entry, index) => (entry, index)))
                {
                    var selectedSetLanes = string.Join(",", GetActiveSetLaneKeys(
                        picked.entry.State,
                        profile,
                        EffectRelevanceScope.SelectedJointPlan,
                        selectedPlanSetFacts));
                    var selectableSetLanes = string.Join(",", GetActiveSetLaneKeys(
                        picked.entry.State,
                        profile,
                        EffectRelevanceScope.SelectableJointPlan,
                        selectableSetFacts));
                    var pickedItems = string.Join(",", picked.entry.State.Items.Select(item =>
                        $"{item.Part}:{item.DefinitionId}:set{item.SetId}"));
                    Plugin.DiagInfo(
                        $"AUTO-GEAR BOUNDED PICK|rank={picked.index + 1}|coarse={picked.entry.Evaluation.Score:0.###}|selectedSetLanes={selectedSetLanes}|selectableSetLanes={selectableSetLanes}|items={pickedItems}");
                }
#endif
                var comparisonProgressTotal = rankedNonCurrentStates.Count
                                              + (currentState is null ? 0 : 1);
                var comparisonProgress = 0;
                ReportAutoBuildProgress(
                    AutoBuildStep.StructuralScreen,
                    comparisonProgress,
                    comparisonProgressTotal);

                if (rankedNonCurrentStates.Count == 0)
                {
                    if (alternativeCandidatesDiscovered > 0)
                    {
                        message = UiText.L(
                            "비현재 8부위 후보를 제한형 고정 스킬안/네이티브 장비 비교로 보낼 수 없어 장비를 변경하지 않았습니다.",
                            "No non-current 8-slot candidate reached the bounded fixed-plan/native gear comparison, so no gear was changed.",
                            "没有非当前候选进入有界固定技能方案/原生装备比较，因此未更换装备。",
                            "沒有非目前候選進入有界固定技能方案/原生裝備比較，因此未更換裝備。")
                            + $"\n{ComparisonAudit()}";
                        return false;
                    }
                    if (currentState is null)
                    {
                        message = UiText.L(
                            "비교할 완성 8부위 장비 조합이 없어 장비를 변경하지 않았습니다.",
                            "No complete 8-slot loadout was available for comparison, so no gear was changed.",
                            "No complete 8-slot loadout was available for comparison, so no gear was changed.",
                            "No complete 8-slot loadout was available for comparison, so no gear was changed.")
                            + $"\n{ComparisonAudit()}";
                        return false;
                    }
                    if (AutoBuildSearchDeadlineReached()) goto DeadlineWithoutComplete;
                    var onlyCurrentEvaluation = EvaluateCompleteLoadout(
                        currentState.Items, hero, profile, currentItems,
                        false, false, false, true,
                        incomingPressure);
                    if (!onlyCurrentEvaluation.IsValid || !double.IsFinite(onlyCurrentEvaluation.Score))
                    {
                        message = UiText.L(
                            "유일한 현재 8부위 기준안의 고정 스킬안/네이티브 장비 계산에 실패해 장비를 변경하지 않았습니다.",
                            "The only current baseline failed the fixed-plan/native gear evaluation, so no gear was changed.",
                            "当前基准的固定技能方案/原生装备计算失败，因此未更换装备。",
                            "目前基準的固定技能方案/原生裝備計算失敗，因此未更換裝備。")
                            + $"\n{ComparisonAudit()}";
                        return false;
                    }
                    currentIncumbent = (currentState, onlyCurrentEvaluation);
                    ConsiderApplicationReady(currentState, onlyCurrentEvaluation);
                    honestComparisonReady = true;
                    winner = bestApplicationReady!.Value;
                    winnerApplicationReady = true;
                    goto WinnerSelected;
                }

                // Establish the current fixed-plan/native score once before
                // challengers. This is a bounded base-skill comparison, not the
                // old full current-loadout refinement. It gives every later valid
                // challenger an immediately comparable baseline even when an
                // earlier challenger is rejected near the deadline.
                if (currentState is not null)
                {
                    if (AutoBuildSearchDeadlineReached()) goto DeadlineWithoutComplete;
                    ReportAutoBuildProgress(
                        AutoBuildStep.StructuralScreen,
                        ++comparisonProgress,
                        comparisonProgressTotal);
                    var currentEvaluation = EvaluateCompleteLoadout(
                        currentState.Items, hero, profile, currentItems,
                        false, false, false, true,
                        incomingPressure);
                    if (!currentEvaluation.IsValid || !double.IsFinite(currentEvaluation.Score))
                    {
                        var failure = string.IsNullOrWhiteSpace(currentEvaluation.Failure)
                            ? "native evaluation failed"
                            : currentEvaluation.Failure;
                        message = UiText.L(
                            $"현재 기준안의 고정 스킬안/네이티브 장비 계산에 실패해 장비를 변경하지 않았습니다: {failure}",
                            $"The current baseline failed the fixed-plan/native gear evaluation, so no gear was changed: {failure}",
                            $"当前基准的固定技能方案/原生装备计算失败，因此未更换装备：{failure}",
                            $"目前基準的固定技能方案/原生裝備計算失敗，因此未更換裝備：{failure}")
                            + $"\n{ComparisonAudit()}";
                        return false;
                    }
                    currentIncumbent = (currentState, currentEvaluation);
                    ConsiderApplicationReady(currentState, currentEvaluation);
#if PATHOFIDLE_RUNTIME_TEST
                    Plugin.DiagInfo(
                        $"AUTO-GEAR BOUNDED RESULT|current=true|score={currentEvaluation.Score:0.###}|focus={currentEvaluation.Profile.Focus.Key}|sets={DescribeSetPlan(currentState.Items, currentEvaluation.Profile)}");
#endif
                }

                foreach (var challenger in rankedNonCurrentStates)
                {
                    if (AutoBuildSearchDeadlineReached())
                    {
                        if (!honestComparisonReady || bestApplicationReady is null)
                            goto DeadlineWithoutComplete;
                        winner = bestApplicationReady.Value;
                        winnerApplicationReady = true;
                        goto WinnerSelected;
                    }
                    ReportAutoBuildProgress(
                        AutoBuildStep.StructuralScreen,
                        ++comparisonProgress,
                        comparisonProgressTotal);
                    alternativeComparisonsAttempted++;
                    var challengerStartedTimestamp = Stopwatch.GetTimestamp();
                    var challengerEvaluation = EvaluateCompleteLoadout(
                        challenger.State.Items, hero, profile, currentItems,
                        false, false, true, false,
                        incomingPressure);
                    var challengerElapsedSeconds = Math.Max(
                        0d,
                        Stopwatch.GetTimestamp() - challengerStartedTimestamp)
                        / Stopwatch.Frequency;
                    if (!challengerEvaluation.IsValid || !double.IsFinite(challengerEvaluation.Score))
                    {
                        alternativeComparisonsRejected++;
#if PATHOFIDLE_RUNTIME_TEST
                        if (alternativeComparisonRejectionReasons.Count < 6)
                        {
                            var compactFailure = Regex.Replace(
                                    challengerEvaluation.Failure ?? string.Empty,
                                    @"\s+",
                                    " ")
                                .Trim();
                            if (compactFailure.Length > 650)
                                compactFailure = compactFailure[..647] + "...";
                            alternativeComparisonRejectionReasons.Add(
                                string.IsNullOrWhiteSpace(compactFailure)
                                    ? "native evaluation failed without a reason"
                                    : compactFailure);
                        }
#endif
                        Plugin.DiagWarning(
                            $"AUTO-GEAR BOUNDED CANDIDATE REJECTED|state={StateKey(challenger.State)}|reason={challengerEvaluation.Failure}");
                        if (AutoBuildSearchDeadlineReached())
                        {
                            if (!honestComparisonReady || bestApplicationReady is null)
                                goto DeadlineWithoutComplete;
                            winner = bestApplicationReady.Value;
                            winnerApplicationReady = true;
                            goto WinnerSelected;
                        }
                        continue;
                    }

                    alternativeComparisonsValid++;
                    ConsiderApplicationReady(challenger.State, challengerEvaluation);
                    honestComparisonReady = true;
#if PATHOFIDLE_RUNTIME_TEST
                    Plugin.DiagInfo(
                        $"AUTO-GEAR BOUNDED RESULT|current=false|score={challengerEvaluation.Score:0.###}|focus={challengerEvaluation.Profile.Focus.Key}|sets={DescribeSetPlan(challenger.State.Items, challengerEvaluation.Profile)}");
#endif
                    var boundedOperation = MainThreadNativeGateway.CurrentWorkerOperation;
                    if (comparisonProgress < comparisonProgressTotal
                        && boundedOperation is { HasPlanningLimit: true }
                        && boundedOperation.PlanningElapsedSeconds
                           + challengerElapsedSeconds + 0.5d
                           >= boundedOperation.PlanningLimitSeconds)
                    {
                        // Do not start another equally expensive comparison when
                        // the measured first challenger cannot fit in the user's
                        // remaining search window. The current loadout and one
                        // non-current loadout are already exact and comparable.
                        Plugin.DiagInfo(
                            $"AUTO-GEAR ADAPTIVE CUTOFF|elapsed={boundedOperation.PlanningElapsedSeconds:0.000}|last={challengerElapsedSeconds:0.000}|limit={boundedOperation.PlanningLimitSeconds}");
                        winner = bestApplicationReady!.Value;
                        winnerApplicationReady = true;
                        goto WinnerSelected;
                    }
                    // After one challenger and the current baseline have both
                    // completed, use any remaining search budget on the second
                    // pre-ranked challenger. This keeps a deadline safe incumbent
                    // while avoiding a one-challenger result when time remains.
                    if (AutoBuildSearchDeadlineReached())
                    {
                        winner = bestApplicationReady!.Value;
                        winnerApplicationReady = true;
                        goto WinnerSelected;
                    }
                }

                if (honestComparisonReady && bestApplicationReady is not null)
                {
                    winner = bestApplicationReady.Value;
                    winnerApplicationReady = true;
                    goto WinnerSelected;
                }

                message = UiText.L(
                    "제한 내 비현재 후보가 고정 스킬안/네이티브 장비 비교를 통과하지 못해 장비를 변경하지 않았습니다.",
                    "No bounded non-current candidate passed the fixed-plan/native gear comparison, so no gear was changed.",
                    "有界非当前候选未通过固定技能方案/原生装备比较，因此未更换装备。",
                    "有界非目前候選未通過固定技能方案/原生裝備比較，因此未更換裝備。")
                    + $"\n{ComparisonAudit()}";
                return false;
            }

            // `coarseSetLaneStates` already reserved every bounded real set
            // threshold before score leaders. Reuse those stable identities
            // instead of repeatedly rebuilding feature tokens for every
            // loadout; that redundant diversity walk could consume the rest of
            // the configured budget without evaluating a single candidate.
            const int structuralLoadoutLimit = 6;
            const int structuralLeaderCount = 2;
            const int structuralSetLaneCount = 3;
            var coarseSetLaneStateKeys = coarseSetLaneStates
                .Select(StateKey).ToHashSet(StringComparer.Ordinal);
            var structuralEntries = coarseFinalists
                .Where(entry => !IsCurrentState(entry.State))
                .Take(1)
                .Concat(coarseFinalists.Take(structuralLeaderCount))
                .Concat(coarseFinalists
                    .Where(entry => coarseSetLaneStateKeys.Contains(StateKey(entry.State)))
                    .Take(structuralSetLaneCount))
                .Concat(coarseFinalists)
                .DistinctBy(entry => StateKey(entry.State))
                .Take(structuralLoadoutLimit)
                .ToList();
            var exactCandidateStates = structuralEntries
                .Select(entry => entry.State)
                .OrderBy(state => IsCurrentState(state) ? 1 : 0)
                .ToList();
            // Rebuild native mastery choices for every retained structural
            // finalist, but use one deterministic exact-budget vector for this
            // screening pass. Running the point-by-point nonlinear allocator for
            // every loadout × skill-package pair was the dominant UI stall.
            var structuralProgressIndex = 0;
            ReportAutoBuildProgress(
                AutoBuildStep.StructuralScreen,
                0,
                exactCandidateStates.Count);
            var screenedFinalists = new List<(LoadoutState State, LoadoutEvaluation Evaluation)>();
            foreach (var state in exactCandidateStates)
            {
                ReportAutoBuildProgress(
                    AutoBuildStep.StructuralScreen,
                    ++structuralProgressIndex,
                    exactCandidateStates.Count);
                var evaluation = EvaluateCompleteLoadout(
                    state.Items, hero, profile, currentItems,
                    true, false, true, false,
                    incomingPressure);
                screenedFinalists.Add((state, evaluation));
                if (AutoBuildSearchDeadlineReached())
                {
                    if (bestApplicationReady is null) goto DeadlineWithoutComplete;
                    winner = bestApplicationReady.Value;
                    winnerApplicationReady = true;
                    goto WinnerSelected;
                }
            }
            var validScreenedFinalists = screenedFinalists
                .Where(entry => entry.Evaluation.IsValid && double.IsFinite(entry.Evaluation.Score))
                .OrderByDescending(entry => entry.Evaluation.Score)
                .ThenBy(entry => entry.State, StableLoadoutStateComparer.Instance)
                .ThenBy(entry => StateKey(entry.State), StringComparer.Ordinal)
                .ToList();
            if (validScreenedFinalists.Count == 0)
            {
                var failure = screenedFinalists.Select(entry => entry.Evaluation.Failure)
                    .FirstOrDefault(value => !string.IsNullOrWhiteSpace(value)) ?? "native preview failed";
                message = UiText.L(
                    $"장비·스킬 공동 계산을 완료하지 못해 장비를 변경하지 않았습니다: {failure}",
                    $"The joint gear/skill evaluation could not be completed, so no gear was changed: {failure}",
                    $"无法完成装备与技能联合计算，因此未更换装备：{failure}",
                    $"無法完成裝備與技能聯合計算，因此未更換裝備：{failure}");
                return false;
            }
            if (AutoBuildSearchDeadlineReached()) goto DeadlineWithoutComplete;

            var validAlternativeScreened = validScreenedFinalists
                .Where(entry => !IsCurrentState(entry.State))
                .ToList();
            if (alternativeCandidatesDiscovered > 0 && validAlternativeScreened.Count == 0)
            {
                alternativeComparisonsRejected += screenedFinalists.Count(entry =>
                    !IsCurrentState(entry.State)
                    && (!entry.Evaluation.IsValid || !double.IsFinite(entry.Evaluation.Score)));
                message = UiText.L(
                    "비현재 8부위 후보가 정밀 비교 조건을 통과하지 못해 장비를 변경하지 않았습니다.",
                    "No non-current 8-slot candidate passed exact comparison screening, so no gear was changed.",
                    "没有非当前 8 部位候选通过精确比较筛选，因此未更换装备。",
                    "沒有非目前 8 部位候選通過精確比較篩選，因此未更換裝備。")
                    + $"\n{ComparisonAudit()}";
                Plugin.DiagWarning($"AUTO-GEAR COMPARISON REJECTED|{ComparisonAudit()}");
                return false;
            }

            // If the search genuinely produced no complete non-current state,
            // current gear is the only candidate and may be fully evaluated on
            // its own. This is distinct from a deadline or rejected challenger.
            if (alternativeCandidatesDiscovered == 0)
            {
                if (currentState is null)
                {
                    message = UiText.L(
                        "비교할 완성 8부위 장비 조합이 없어 장비를 변경하지 않았습니다.",
                        "No complete 8-slot loadout was available for comparison, so no gear was changed.",
                        "没有可用于比较的完整 8 部位装备组合，因此未更换装备。",
                        "沒有可用於比較的完整 8 部位裝備組合，因此未更換裝備。")
                        + $"\n{ComparisonAudit()}";
                    return false;
                }
                if (AutoBuildSearchDeadlineReached()) goto DeadlineWithoutComplete;
                var onlyCurrentEvaluation = EvaluateCompleteLoadout(
                    currentState.Items, hero, profile, currentItems,
                    true, true, true, false,
                    incomingPressure);
                if (!onlyCurrentEvaluation.IsValid || !double.IsFinite(onlyCurrentEvaluation.Score))
                {
                    message = UiText.L(
                        "유일한 현재 8부위 기준안의 정밀 계산에 실패해 장비를 변경하지 않았습니다.",
                        "The only current 8-slot baseline failed full evaluation, so no gear was changed.",
                        "唯一的当前 8 部位基准方案未通过完整评估，因此未更换装备。",
                        "唯一的目前 8 部位基準方案未通過完整評估，因此未更換裝備。")
                        + $"\n{ComparisonAudit()}";
                    return false;
                }
                currentIncumbent = (currentState, onlyCurrentEvaluation);
                bestApplicationReady = currentIncumbent;
                honestComparisonReady = true;
                winner = currentIncumbent.Value;
                winnerApplicationReady = true;
                goto WinnerSelected;
            }

            // Fully refine the two global leaders, then reserve one best path for
            // each still-uncovered active-set, selected-variant and selected
            // granted-skill category. Local-swap refinement makes five nonlinear
            // allocations a bounded cost while preventing one feature category
            // from consuming the only structural slot.
            const int nonlinearRefinementLimit = 5;
            var fullRefinementEntries = validAlternativeScreened
                .DistinctBy(entry => StateKey(entry.State))
                .Take(2)
                .ToList();
            var fullSelectedKeys = fullRefinementEntries.Select(entry => StateKey(entry.State))
                .ToHashSet(StringComparer.Ordinal);
            HashSet<string> FullFeatures(LoadoutState? state, HeroEffectProfile? tokenProfile)
            {
                var features = new HashSet<string>(StringComparer.Ordinal);
                if (state is null || state.Items is null || tokenProfile is null) return features;

                // Set lanes remain exact SelectedJointPlan features: an inactive
                // or skill-irrelevant threshold is not a refinement reservation.
                foreach (var lane in GetActiveSetLaneKeys(
                             state, tokenProfile, EffectRelevanceScope.SelectedJointPlan))
                    features.Add($"set:{lane}");

                var selectedSkills = tokenProfile.SkillIds;
                if (selectedSkills is null || selectedSkills.Count == 0) return features;
                foreach (var item in state.Items)
                {
                    if (item?.SelectableFacts is not { } facts) continue;
                    if (facts.VariantIds is not null)
                        foreach (var skillId in facts.VariantIds
                                     .Where(id => id > 0 && selectedSkills.Contains(id)))
                            features.Add($"variant:{skillId}");
                    if (facts.GrantedSkillLevels is null) continue;
                    foreach (var entry in facts.GrantedSkillLevels)
                    {
                        const string prefix = "extra-skill:";
                        if (string.IsNullOrEmpty(entry.Key)
                            || !entry.Key.StartsWith(prefix, StringComparison.Ordinal)
                            || !int.TryParse(
                                entry.Key.Substring(prefix.Length),
                                NumberStyles.Integer,
                                CultureInfo.InvariantCulture,
                                out var skillId)
                            || skillId <= 0
                            || !selectedSkills.Contains(skillId)) continue;
                        features.Add($"grant:{entry.Key}");
                    }
                }
                return features;
            }
            var fullCoveredFeatures = fullRefinementEntries
                .SelectMany(entry => FullFeatures(entry.State, entry.Evaluation.Profile))
                .ToHashSet(StringComparer.Ordinal);

            // Category reservations are score-first and stable-key deterministic.
            // A category is skipped when the leaders (or an earlier reservation)
            // already cover every real selected-plan feature in that category.
            foreach (var categoryPrefix in new[] { "set:", "variant:", "grant:" })
            {
                if (fullRefinementEntries.Count >= nonlinearRefinementLimit) break;
                var categoryCandidate = validAlternativeScreened
                    .Where(entry => !fullSelectedKeys.Contains(StateKey(entry.State)))
                    .Select(entry => new
                    {
                        Entry = entry,
                        Features = FullFeatures(entry.State, entry.Evaluation.Profile)
                    })
                    .Where(candidate => candidate.Features.Any(token =>
                        token.StartsWith(categoryPrefix, StringComparison.Ordinal)
                        && !fullCoveredFeatures.Contains(token)))
                    .OrderByDescending(candidate => candidate.Entry.Evaluation.Score)
                    .ThenBy(candidate => candidate.Entry.State, StableLoadoutStateComparer.Instance)
                    .ThenBy(candidate => StateKey(candidate.Entry.State), StringComparer.Ordinal)
                    .FirstOrDefault();
                if (categoryCandidate is null) continue;
                fullRefinementEntries.Add(categoryCandidate.Entry);
                fullSelectedKeys.Add(StateKey(categoryCandidate.Entry.State));
                fullCoveredFeatures.UnionWith(categoryCandidate.Features);
            }

            // Any remaining capacity covers the largest number of new exact
            // features, with score and stable state identity as deterministic
            // tie-breakers. Zero-new-feature entries remain valid fallbacks when
            // fewer than five distinct structural paths exist.
            while (fullRefinementEntries.Count < nonlinearRefinementLimit)
            {
                var next = validAlternativeScreened
                    .Where(entry => !fullSelectedKeys.Contains(StateKey(entry.State)))
                    .Select(entry => new
                    {
                        Entry = entry,
                        NewFeatures = FullFeatures(entry.State, entry.Evaluation.Profile)
                            .Count(token => !fullCoveredFeatures.Contains(token))
                    })
                    .OrderByDescending(candidate => candidate.NewFeatures)
                    .ThenByDescending(candidate => candidate.Entry.Evaluation.Score)
                    .ThenBy(candidate => candidate.Entry.State, StableLoadoutStateComparer.Instance)
                    .ThenBy(candidate => StateKey(candidate.Entry.State), StringComparer.Ordinal)
                    .FirstOrDefault();
                if (next is null) break;
                fullRefinementEntries.Add(next.Entry);
                fullSelectedKeys.Add(StateKey(next.Entry.State));
                fullCoveredFeatures.UnionWith(FullFeatures(next.Entry.State, next.Entry.Evaluation.Profile));
            }
            var fullRefineProgressIndex = 0;
            ReportAutoBuildProgress(
                AutoBuildStep.FinalRefinement,
                0,
                fullRefinementEntries.Count);
            var refinedFinalists = new List<(LoadoutState State, LoadoutEvaluation Evaluation)>();
            foreach (var screened in fullRefinementEntries)
            {
                ThrowIfAutoBuildCancellationRequested();
                ReportAutoBuildProgress(
                    AutoBuildStep.FinalRefinement,
                    ++fullRefineProgressIndex,
                    fullRefinementEntries.Count);
                alternativeComparisonsAttempted++;
                var refined = EvaluateCompleteLoadout(
                    screened.State.Items,
                    hero,
                    screened.Evaluation.Profile,
                    currentItems,
                    true,
                    true,
                    true,
                    false,
                    incomingPressure);
                refinedFinalists.Add((screened.State, refined));
                if (refined.IsValid && double.IsFinite(refined.Score))
                {
                    alternativeComparisonsValid++;
                    ConsiderApplicationReady(screened.State, refined);

                    // The first valid challenger is always refined before the
                    // current loadout. Only after both sides have a valid full
                    // result may either one become an apply-ready incumbent.
                    if (!honestComparisonReady)
                    {
                        if (currentState is not null)
                        {
                            if (AutoBuildSearchDeadlineReached()) goto DeadlineWithoutComplete;
                            var currentEvaluation = EvaluateCompleteLoadout(
                                currentState.Items,
                                hero,
                                profile,
                                currentItems,
                                true,
                                true,
                                true,
                                false,
                                incomingPressure);
                            if (!currentEvaluation.IsValid || !double.IsFinite(currentEvaluation.Score))
                            {
                                message = UiText.L(
                                    "비현재 후보는 유효했지만 현재 8부위 기준안의 정밀 계산에 실패해 장비를 변경하지 않았습니다.",
                                    "A non-current candidate was valid, but the current 8-slot baseline failed full evaluation, so no gear was changed.",
                                    "非当前候选有效，但当前 8 部位基准方案未通过完整评估，因此未更换装备。",
                                    "非目前候選有效，但目前 8 部位基準方案未通過完整評估，因此未更換裝備。")
                                    + $"\n{ComparisonAudit()}";
                                Plugin.DiagWarning($"AUTO-GEAR CURRENT COMPARISON REJECTED|{ComparisonAudit()}");
                                return false;
                            }
                            currentIncumbent = (currentState, currentEvaluation);
                            ConsiderApplicationReady(currentState, currentEvaluation);
                        }
                        honestComparisonReady = true;
                    }
                }
                else
                {
                    alternativeComparisonsRejected++;
                }
                if (AutoBuildSearchDeadlineReached())
                {
                    if (!honestComparisonReady || bestApplicationReady is null)
                        goto DeadlineWithoutComplete;
                    comparisonDeadlineExits++;
                    winner = bestApplicationReady.Value;
                    winnerApplicationReady = true;
                    goto WinnerSelected;
                }
            }
            var validRefinedFinalists = refinedFinalists
                .Where(entry => entry.Evaluation.IsValid && double.IsFinite(entry.Evaluation.Score))
                .OrderByDescending(entry => entry.Evaluation.Score)
                .ThenBy(entry => entry.State, StableLoadoutStateComparer.Instance)
                .ThenBy(entry => StateKey(entry.State), StringComparer.Ordinal)
                .ToList();
            if (validRefinedFinalists.Count == 0 || !honestComparisonReady)
            {
                var failure = refinedFinalists.Select(entry => entry.Evaluation.Failure)
                    .FirstOrDefault(value => !string.IsNullOrWhiteSpace(value)) ?? "native refinement failed";
                message = UiText.L(
                    $"최종 장비·스킬 포인트 계산을 완료하지 못해 장비를 변경하지 않았습니다: {failure}",
                    $"The final joint gear/skill point allocation could not be completed, so no gear was changed: {failure}",
                    $"无法完成最终装备与技能点联合分配，因此未更换装备：{failure}",
                    $"無法完成最終裝備與技能點聯合分配，因此未更換裝備：{failure}")
                    + $"\n{ComparisonAudit()}";
                return false;
            }
            if (bestApplicationReady is null) goto DeadlineWithoutComplete;
            winner = bestApplicationReady.Value;
            winnerApplicationReady = true;
            goto WinnerSelected;
            }
        DeadlineWithoutComplete:
            comparisonDeadlineExits++;
            var planningLimitSeconds = MainThreadNativeGateway.CurrentWorkerOperation?.PlanningLimitSeconds
                                       ?? Plugin.NormalizeAutoBuildPlanningSeconds(
                                           Plugin.AutoBuildPlanningSeconds.Value);
            message = UiText.L(
                $"{planningLimitSeconds:N0}초 안에 비현재 8부위 후보와 현재 장비의 제한형 고정 스킬안/네이티브 장비 비교를 완료하지 못해 장비를 변경하지 않았습니다.",
                $"The bounded fixed-plan/native gear comparison between a non-current 8-slot candidate and the current gear did not finish within {planningLimitSeconds:N0} seconds, so no gear was changed.",
                $"{planningLimitSeconds:N0} 秒内未能完成非当前 8 部位候选与当前装备的有界固定技能方案/原生装备比较，因此未更换装备。",
                $"{planningLimitSeconds:N0} 秒內未能完成非目前 8 部位候選與目前裝備的有界固定技能方案/原生裝備比較，因此未更換裝備。")
                + $"\n{ComparisonAudit()}";
            Plugin.DiagWarning($"AUTO-GEAR COMPARISON DEADLINE|{ComparisonAudit()}");
            return false;

        WinnerSelected:
            if (!winnerApplicationReady)
                throw new InvalidOperationException(
                    "The selected loadout did not complete the bounded fixed-plan/native gear evaluation and cannot be applied.");
            if (slots.Count != 8)
                throw new InvalidOperationException($"Auto Build requires exactly 8 equipment slots, but found {slots.Count}.");
            if (winner.State.Items.Count != slots.Count)
                throw new InvalidOperationException(
                    $"The selected loadout is incomplete ({winner.State.Items.Count}/{slots.Count}).");
            for (var slotIndex = 0; slotIndex < slots.Count; slotIndex++)
            {
                if (winner.State.Items[slotIndex].Part != slots[slotIndex].Part)
                    throw new InvalidOperationException(
                        $"The selected item for {slots[slotIndex].Label} belongs to a different slot.");
            }
            if (winner.State.Items.Select(candidate => candidate.Key)
                    .Distinct(StringComparer.Ordinal).Count() != slots.Count)
                throw new InvalidOperationException("The selected loadout references the same item more than once.");
            if (winner.State.Items.Count(candidate => candidate.Record.Quality == 5) > maxMythic)
                throw new InvalidOperationException("The selected loadout exceeds the native Mythic equipment limit.");
            if (HasLegendMythWeaponConflict(winner.State.Items))
                throw new InvalidOperationException("The selected loadout contains a conflicting Legendary/Mythic weapon pair.");
            if (!winner.Evaluation.IsValid || !double.IsFinite(winner.Evaluation.Score))
                throw new InvalidOperationException("The selected loadout does not have a valid complete evaluation.");
            if (!honestComparisonReady)
                throw new InvalidOperationException(
                    "The selected loadout was not produced by a complete current-versus-challenger comparison.");
            var winnerStateKey = string.Join("|", winner.State.Items.Select(item => item.Key));
            var winnerIsCurrent = currentState is not null
                                  && string.Equals(winnerStateKey, currentStateKey, StringComparison.Ordinal);
            if (winnerIsCurrent && alternativeCandidatesDiscovered > 0
                                && alternativeComparisonsValid == 0)
                throw new InvalidOperationException(
                    "The current loadout cannot win before a valid non-current full comparison.");
            if (winnerIsCurrent && currentIncumbent is null)
                throw new InvalidOperationException(
                    "The current loadout was selected without a valid bounded fixed-plan/native gear evaluation.");
            if (!winnerIsCurrent && currentIncumbent is { } comparableCurrent
                                 && !CanCandidateReplaceCurrentUnderCoverage(
                                     comparableCurrent.Evaluation.Score,
                                     comparableCurrent.Evaluation.UnmodeledRelevantSetEffectIds,
                                     winner.Evaluation.Score,
                                     winner.Evaluation.ActiveRelevantSetEffectIds,
                                     out var coverageFailure))
                throw new InvalidOperationException(
                    $"The selected challenger failed the incumbent model-coverage guard: {coverageFailure}");
            Plugin.DiagInfo($"AUTO-GEAR COMPARISON|winnerCurrent={winnerIsCurrent}|{ComparisonAudit()}");

            var winnerProfile = winner.Evaluation.Profile;
            var winnerTalentRows = GetHeroSkillTalentRows(hero);
            var missingPlannedSkills = winnerProfile.PlannedSkills.ActiveSkillIds
                .Where(skillId => !winnerTalentRows.Any(row =>
                    IsTransformableSkillDefinition(row)
                    && (ReadNullableInt(row, "skillId") ?? 0) == skillId
                    && winnerProfile.PlannedSkills.TargetSavedLevels.GetValueOrDefault(
                        ReadNullableInt(row, "id") ?? 0) > 0))
                .OrderBy(id => id).ToList();
            if (missingPlannedSkills.Count > 0)
                throw new InvalidOperationException(
                    $"The compared skill package has no paid native talent target for {string.Join(',', missingPlannedSkills)}. No gear was changed.");
            if (!IsLoadoutWeaponCompatible(winner.State.Items, winnerProfile))
                throw new InvalidOperationException(
                    "The selected joint skill package is incompatible with the selected weapons.");

#if PATHOFIDLE_RUNTIME_TEST
            if (previewOnly)
            {
                var previewSkillDescription = DescribeJointSkillSelection(
                    winnerProfile.PreviewBaseSkillId,
                    winnerProfile.SkillIds
                        .Where(id => id > 0 && id != winnerProfile.PreviewBaseSkillId)
                        .OrderBy(id => id)
                        .ToList(),
                    winner.State.Items);
                var targetSavedLevels = winnerProfile.PlannedSkills.TargetSavedLevels
                    .OrderBy(entry => entry.Key)
                    .ToList();
                if (!winnerProfile.PlannedSkills.TargetSavedLevels.TryGetValue(
                        winnerProfile.PlannedSkills.BaseTalentId, out var baseSavedLevel)
                    || baseSavedLevel < 1)
                    throw new InvalidOperationException(
                        "The read-only plan lost the native free base-skill level.");
                var materializedTalentPointTotal = targetSavedLevels.Sum(entry => entry.Value);
                var paidTalentPointTotal = checked(materializedTalentPointTotal - 1);
                var talentPointBudget = winnerProfile.PlannedSkills.TotalTalentPointBudget;
                var unspentTalentPoints = checked(talentPointBudget - paidTalentPointTotal);
                if (paidTalentPointTotal != talentPointBudget || unspentTalentPoints != 0)
                    throw new InvalidOperationException(
                        $"The read-only plan leaves talent points unspent ({paidTalentPointTotal}/{talentPointBudget}, remaining {unspentTalentPoints}).");
                message = $"Read-only Auto Build result · focus={focus.English} · "
                          + $"score={winner.Evaluation.Score:0.######} · "
                          + $"current={winnerIsCurrent.ToString().ToLowerInvariant()} · "
                          + $"gear={string.Join(';', slots.Select((slot, index) => $"{slot.Label}:{winner.State.Items[index].Record.Name}#{winner.State.Items[index].DefinitionId}"))} · "
                          + $"skills={previewSkillDescription} · "
                          + $"points={paidTalentPointTotal}/{talentPointBudget}/{unspentTalentPoints} · "
                          + $"levels={string.Join(',', targetSavedLevels.Select(entry => $"{entry.Key}:{entry.Value}"))} · "
                          + $"sets={DescribeSetPlan(winner.State.Items, winnerProfile)} · "
                          + ComparisonAudit();
                return true;
            }
#endif

            var selectedMythics = winner.State.Items.Count(candidate => candidate.Record.Quality == 5);
            Plugin.DiagInfo($"AUTO-GEAR MYTHIC RESULT|limit={maxMythic}|selected={selectedMythics}|available={candidates.Count(candidate => candidate.Record.Quality == 5)}");
            foreach (var slot in slots)
            {
                var topMythics = candidates.Where(candidate => candidate.Part == slot.Part && candidate.Record.Quality == 5)
                    .OrderByDescending(candidate => candidate.Score + candidate.NumericScore * 0.1d)
                    .Take(3)
                    .Select(candidate => $"{candidate.Record.Name}:{candidate.Score:0.0}/{candidate.NumericScore:0.0}");
                var selected = winner.State.Items[slots.IndexOf(slot)];
                Plugin.DiagInfo($"AUTO-GEAR MYTHIC SLOT|slot={slot.Label}|selected={selected.Record.Name}:Q{selected.Record.Quality}|top={string.Join(',', topMythics)}");
            }

            Plugin.DiagInfo($"AUTO-GEAR PLAN|focus={focus.English}|score={winner.Evaluation.Score:0.0}|skills={winnerProfile.JointSkillReason}|" +
                                  string.Join(" ; ", slots.Select((slot, index) =>
                                  {
                                      var choice = winner.State.Items[index];
                                       return $"{slot.Label}={choice.Record.Name} Q{choice.Record.Quality} Lv{choice.Record.Level ?? 0} itemScore={choice.Score:0.0} numeric={choice.NumericScore:0.0} direct={choice.DirectMatches} theme={choice.ThemeMatches} set={choice.SetId} effectPolicy={GetNonStackingEffectSignature(choice.NonStackingEffectKeys)}";
                                  })));
            Plugin.DiagInfo($"AUTO-GEAR SET PLAN|focus={focus.English}|{DescribeSetPlan(winner.State.Items, winnerProfile)}");

            // Apply ordinary replacements first so an outgoing Mythic or a
            // conflicting weapon can be removed before a restricted item is
            // inserted. Failed moves are retried after the other slots settle.
            var pending = slots.Select((slot, index) => (Slot: slot, Candidate: winner.State.Items[index]))
                .Where(entry => !NativeEquals(GetEquippedItem(hero, entry.Slot.Part, entry.Slot.MainWeapon), entry.Candidate.Record.ItemData))
                .OrderBy(entry => entry.Candidate.Record.Quality == 5 ? 1 : 0)
                .ThenBy(entry => entry.Slot.Part == 1 ? 1 : 0)
                .ToList();
            if (winnerIsCurrent != (pending.Count == 0))
                throw new InvalidOperationException(
                    $"Winner/current invariant failed (winnerCurrent={winnerIsCurrent}, plannedChanges={pending.Count}).");
            var targetItems = winner.State.Items.Select(candidate => candidate.Record.ItemData).ToList();
            var treasureTargetItems = winner.State.Items.Where(candidate => candidate.Record.StorageSource == StorageSource.Treasure)
                .Select(candidate => candidate.Record.ItemData).ToList();
            var pendingVaultMoves = pending.Count(entry =>
                entry.Candidate.Record.StorageSource == StorageSource.Treasure);
            if (combinedFlow && pendingVaultMoves > 0)
            {
                // Rollback deliberately uses ordinary Warehouse fields instead
                // of reinserting several items into Vault, a native path that can
                // block the game. Reserve a conservative margin for bridge and
                // conflicting-weapon staging before the first live mutation.
                var emptyWarehouseFields = MainThreadNativeGateway.Invoke(() =>
                    CountEmptyWarehouseEquipmentFields(seasonData));
                var requiredRollbackFields = pendingVaultMoves + pending.Count + 2;
                if (emptyWarehouseFields < requiredRollbackFields)
                {
                    transactionalVaultCandidatesSkipped = pendingVaultMoves;
                    message = UiText.L(
                        $"Vault 장비 {pendingVaultMoves}개를 안전하게 장착하려면 일반 창고 빈칸 {requiredRollbackFields}개가 필요하지만 {emptyWarehouseFields}개뿐이라 장비를 변경하지 않았습니다.",
                        $"Equipping {pendingVaultMoves} Vault item(s) safely requires {requiredRollbackFields} empty ordinary-Warehouse slots for rollback, but only {emptyWarehouseFields} are available. No gear was changed.",
                        $"安全装备 {pendingVaultMoves} 件宝库装备需要 {requiredRollbackFields} 个普通仓库空位用于回滚，但目前只有 {emptyWarehouseFields} 个。未更换装备。",
                        $"安全裝備 {pendingVaultMoves} 件寶庫裝備需要 {requiredRollbackFields} 個普通倉庫空位用於復原，但目前只有 {emptyWarehouseFields} 個。未更換裝備。")
                        + $"\n{ComparisonAudit()}";
                    return false;
                }
                Plugin.DiagInfo($"AUTO-GEAR VAULT ROLLBACK CAPACITY|selected={pendingVaultMoves}|required={requiredRollbackFields}|emptyWarehouse={emptyWarehouseFields}");
            }
            pending = pending
                .OrderByDescending(entry => InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", entry.Candidate.Record.ItemData) is not null)
                .ThenBy(entry => entry.Candidate.Record.StorageSource == StorageSource.Treasure ? 1 : 0)
                .ToList();
            var initialGearMoveCount = pending.Count;
            var appliedGearMoveCount = 0;
            ReportAutoBuildProgress(
                AutoBuildStep.ApplyingGear,
                0,
                initialGearMoveCount);
            var hadPendingGearMoves = pending.Count > 0;
            if (hadPendingGearMoves) BeginLiveMutation(hero, originalGearFingerprint, originalSkillFingerprint);
            Plugin.DiagInfo("AUTO-GEAR APPLY|stage=mutation-ready");
            var lastFailures = new Dictionary<string, (int Code, string Reason)>(StringComparer.Ordinal);
            var stagedConflictingWeapon = false;
            Plugin.DiagInfo("AUTO-GEAR APPLY|stage=checking-bag-space");
            if (pending.Any(entry => entry.Candidate.Record.StorageSource == StorageSource.Treasure)
                && FindEmptyEquipmentBagField(seasonData) is null)
            {
                // Only a field pointer and its item are needed here. Calling
                // ReadAll(false) described every bag item and, during exclusive
                // mutation, turned each reflected property into a separate
                // rendered-frame request. Scan the authoritative fields in one
                // native batch instead.
                var bridgeRecord = MainThreadNativeGateway.Invoke(() =>
                {
                    var lordDataForBridge = Read(seasonData, "lordData");
                    var bagDataForBridge = Read(lordDataForBridge, "lordBagData");
                    var equipmentTypeForBridge = CreateEnum("EItemType", 2);
                    if (bagDataForBridge is null || equipmentTypeForBridge is null)
                        return (Field: (object?)null, Item: (object?)null);
                    var fields = InvokeRequiredInstance(
                        bagDataForBridge, "GetFieldList", equipmentTypeForBridge);
                    foreach (var field in ReadList(fields))
                    {
                        var item = Read(field, "itemData");
                        if (!IsEquipmentItem(item)
                            || targetItems.Any(target => NativeEquals(target, item))) continue;
                        return (Field: (object?)field, Item: item);
                    }
                    return (Field: (object?)null, Item: (object?)null);
                });
                var bridgeFailure = "The bag is full and no non-target equipment can be staged for Vault access.";
                if (bridgeRecord.Field is null || bridgeRecord.Item is null
                    || !TryClearBridgeBagField(bridgeRecord.Field, bridgeRecord.Item, seasonData, moveJournal, out bridgeFailure))
                {
                    throw new InvalidOperationException(string.IsNullOrWhiteSpace(bridgeFailure)
                        ? "The bag is full and no non-target equipment can be staged for Vault access."
                        : bridgeFailure);
                }
                Plugin.DiagInfo("AUTO-GEAR BRIDGE|staged one non-target bag equipment item to storage");
            }
            Plugin.DiagInfo("AUTO-GEAR APPLY|stage=bag-space-ready");

            // CheckAddItem counts the incoming Mythic before ItemSys performs
            // the swap. A legal Mythic-for-Mythic replacement can therefore be
            // rejected as a transient third Mythic even though the final plan
            // stays at the native cap. Stage only the outgoing Mythics from
            // those exact target slots first. Every staging move is journaled,
            // so combined Auto Build can still roll the transaction back.
            var mythicReplacementSlots = pending
                .Where(entry => entry.Candidate.Record.Quality == 5)
                .Where(entry =>
                {
                    var outgoing = GetEquippedItem(
                        hero, entry.Slot.Part, entry.Slot.MainWeapon);
                    return outgoing is not null
                           && (ReadNullableInt(Read(outgoing, "saveItemData"), "quality") ?? 0) == 5
                           && !NativeEquals(outgoing, entry.Candidate.Record.ItemData);
                })
                .Select(entry => entry.Slot)
                .ToList();
            foreach (var slot in mythicReplacementSlots)
            {
                if (!TryStageEquippedItem(
                        hero,
                        slot,
                        seasonData,
                        moveJournal,
                        preserveBagSpace: treasureTargetItems.Count > 0,
                        out var stageFailure))
                    throw new InvalidOperationException(
                        $"Could not stage the outgoing Mythic in {slot.Label}: {stageFailure}");
                Plugin.DiagInfo(
                    $"AUTO-GEAR STAGE|slot={slot.Label}|moved outgoing Mythic before capped replacement");
            }
            for (var pass = 0; pass < 3 && pending.Count > 0; pass++)
            {
                var retry = new List<(GearSlot Slot, GearCandidate Candidate)>();
                foreach (var entry in pending)
                {
                    if (TryEquipCandidate(hero, entry.Candidate, entry.Slot, seasonData, moveJournal, targetItems, treasureTargetItems, out var moveCode, out var failure))
                    {
                        lastFailures.Remove(entry.Slot.Label);
                        ReportAutoBuildProgress(
                            AutoBuildStep.ApplyingGear,
                            ++appliedGearMoveCount,
                            initialGearMoveCount,
                            entry.Slot.Label);
                        continue;
                    }
                    lastFailures[entry.Slot.Label] = (moveCode, failure);
                    retry.Add(entry);
                }
                if (retry.Count == pending.Count && pass > 0)
                {
                    var conflict = retry.FirstOrDefault(entry => entry.Slot.Part == 1
                        && lastFailures.TryGetValue(entry.Slot.Label, out var detail) && detail.Code == 7);
                    var stageFailure = string.Empty;
                    var oppositeSlot = conflict.Slot is null
                        ? null
                        : slots.FirstOrDefault(slot => slot.Part == 1 && slot.MainWeapon != conflict.Slot.MainWeapon);
                    if (!stagedConflictingWeapon && oppositeSlot is not null
                        && TryStageEquippedItem(
                            hero,
                            oppositeSlot,
                            seasonData,
                            moveJournal,
                            preserveBagSpace: treasureTargetItems.Count > 0,
                            out stageFailure))
                    {
                        stagedConflictingWeapon = true;
                        Plugin.DiagInfo($"AUTO-GEAR STAGE|slot={oppositeSlot.Label}|moved the opposite conflicting weapon to bag");
                    }
                    else
                    {
                        if (!string.IsNullOrWhiteSpace(stageFailure))
                            Plugin.DiagWarning($"AUTO-GEAR STAGE FAILED|reason={stageFailure}");
                        break;
                    }
                }
                pending = retry
                    .OrderByDescending(entry => InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", entry.Candidate.Record.ItemData) is not null)
                    .ThenBy(entry => entry.Candidate.Record.StorageSource == StorageSource.Treasure ? 1 : 0)
                    .ToList();
            }

            var attemptFailures = lastFailures.Select(entry => $"{entry.Key}: {entry.Value.Reason}").ToList();
            foreach (var entry in lastFailures)
                Plugin.DiagWarning($"AUTO-GEAR MOVE FAILED|slot={entry.Key}|code={entry.Value.Code}|reason={entry.Value.Reason}");

            // All eight destination/ownership checks and the selected-plan
            // effect scan describe one immutable post-move state. Read that
            // state in one Unity-thread batch instead of paying one rendered
            // frame for every small reflection call during exclusive mutation.
            var appliedGearState = MainThreadNativeGateway.Invoke(() =>
            {
                var verifiedSlots = 0;
                var changedSlots = 0;
                var unchangedSlots = 0;
                var changedThemeMatches = 0;
                for (var index = 0; index < slots.Count; index++)
                {
                    var slot = slots[index];
                    var candidate = winner.State.Items[index];
                    var destination = GetEquipDestinationField(hero, slot);
                    if (destination is null
                        || !IsVerifiedHeroEquipField(hero, candidate.Record.ItemData, destination)) continue;
                    var actual = Read(destination, "itemData");
                    verifiedSlots++;
                    if (NativeEquals(currentBySlot[slot], actual)) unchangedSlots++;
                    else
                    {
                        changedSlots++;
                        changedThemeMatches += candidate.ThemeMatches;
                    }
                }
                return (
                    FinalMatches: verifiedSlots,
                    Changed: changedSlots,
                    Unchanged: unchangedSlots,
                    ThemeMatches: changedThemeMatches,
                    DirectMatches: CountEffectiveDirectMatches(
                        winner.State.Items, winnerProfile,
                        EffectRelevanceScope.SelectedJointPlan));
            });
            var finalMatches = appliedGearState.FinalMatches;
            var changed = appliedGearState.Changed;
            var unchanged = appliedGearState.Unchanged;
            var themeMatches = appliedGearState.ThemeMatches;
            var directMatches = appliedGearState.DirectMatches;

            var failed = slots.Count - finalMatches;
            if (failed > 0)
            {
                var firstFailure = attemptFailures.FirstOrDefault() ?? UiText.L("일부 목표 슬롯이 최종 장비와 일치하지 않음", "some target slots did not match the final loadout", "部分目标栏位与最终装备不一致", "部分目標欄位與最終裝備不一致");
                if (combinedFlow)
                {
                    var rollback = RollbackUncommittedCombinedGear(
                        hero, gearTalentData, moveJournal, originalGearFingerprint, abilityBaseline);
                    pendingGearCommit = null;
                    gearCommitted = false;
                    message = rollback.IsRecovered
                        ? UiText.L(
                            $"장비 적용 미완료 · 확인 {finalMatches}/8 · 원래 장비로 복구 및 검증 완료 · {firstFailure}",
                            $"Gear apply incomplete · verified {finalMatches}/8 · original equipment restored and verified · {firstFailure}",
                            $"装备应用未完成 · 已验证 {finalMatches}/8 · 已恢复并验证原装备 · {firstFailure}",
                            $"裝備套用未完成 · 已驗證 {finalMatches}/8 · 已還原並驗證原裝備 · {firstFailure}")
                          + DescribeGearRollbackStorage(rollback)
                        : UiText.L(
                            $"장비 적용 미완료 · 원래 장비 복구 검증 실패({rollback.Detail}) · {firstFailure}",
                            $"Gear apply incomplete · original-equipment rollback verification failed ({rollback.Detail}) · {firstFailure}",
                            $"装备应用未完成 · 原装备回滚验证失败 ({rollback.Detail}) · {firstFailure}",
                            $"裝備套用未完成 · 原裝備回復驗證失敗 ({rollback.Detail}) · {firstFailure}");
                    return false;
                }
                if (gearTalentData is not null)
                {
                    try { InvokeRequiredInstance(gearTalentData, "ReapplySkillVariantsFromEquippedItems"); }
                    catch (Exception refreshError) { Plugin.DiagWarning($"AUTO-GEAR VARIANT REFRESH FAILED|{refreshError.GetBaseException().Message}"); }
                }
                message = UiText.L(
                    $"장비 적용 미완료 · 확인 {finalMatches}/8 · 현재까지 적용된 상태 유지 · {firstFailure}",
                    $"Gear apply incomplete · verified {finalMatches}/8 · changes applied so far were kept · {firstFailure}",
                    $"装备应用未完成 · 已验证 {finalMatches}/8 · 保留目前已应用的状态 · {firstFailure}",
                    $"裝備套用未完成 · 已驗證 {finalMatches}/8 · 保留目前已套用的狀態 · {firstFailure}");
                moveJournal.Clear();
                return false;
            }

            // Equipment affixes are the game's source of truth for skill
            // transformations. Verify them while the move journal can still
            // restore the previous loadout. Storage normalization can move
            // outgoing items again, so it deliberately runs only after this
            // rollback-capable postcondition.
            var variantRefreshFailed = false;
            var gearEffectVerificationFailed = false;
            var unusableSkillFailed = false;
            try
            {
                if (!hadPendingGearMoves) BeginLiveMutation(hero, originalGearFingerprint, originalSkillFingerprint);
                ReportAutoBuildProgress(AutoBuildStep.Verifying);
                var effectState = MainThreadNativeGateway.Invoke(() =>
                {
                    var verifiedTalentData = gearTalentData
                        ?? throw new InvalidOperationException("Talent data is unavailable.");
                    InvokeRequiredInstance(verifiedTalentData, "ReapplySkillVariantsFromEquippedItems");
                    // At this stage a combined build has not transformed or
                    // learned its target skills yet. Verify only variants for
                    // skills already present; Auto Skills verifies the complete
                    // selected package after its matching allocation commits.
                    var variants = VerifyEquippedSkillVariants(
                        hero, verifiedTalentData, "AUTO-GEAR");
                    var effects = VerifyCommittedGearEffects(
                        hero, verifiedTalentData, abilityBaseline, "AUTO-GEAR");
                    return (
                        VariantFailed: !variants.IsExact,
                        EffectFailed: !effects.IsVerified,
                        UnusableSkill: ReadBool(InvokeRequiredInstance(
                            verifiedTalentData, "IsHasUnusableSkill")));
                });
                variantRefreshFailed = effectState.VariantFailed;
                gearEffectVerificationFailed = effectState.EffectFailed;
                unusableSkillFailed = effectState.UnusableSkill;
                if (unusableSkillFailed)
                    Plugin.DiagWarning("AUTO-GEAR SKILL USABILITY FAILED|at least one learned skill cannot be used by the committed weapons");
            }
            catch (Exception refreshError)
            {
                variantRefreshFailed = true;
                gearEffectVerificationFailed = true;
                Plugin.DiagWarning($"AUTO-GEAR VARIANT REFRESH FAILED|{refreshError.GetBaseException().Message}");
            }
            if (variantRefreshFailed || gearEffectVerificationFailed)
            {
                if (combinedFlow)
                {
                    var rollback = RollbackUncommittedCombinedGear(
                        hero, gearTalentData, moveJournal, originalGearFingerprint, abilityBaseline);
                    pendingGearCommit = null;
                    gearCommitted = false;
                    message = rollback.IsRecovered
                        ? UiText.L(
                            "장비 특수 효과 검증 실패 · 원래 장비로 복구 및 검증 완료",
                            "Gear special-effect verification failed · original equipment restored and verified",
                            "装备特殊效果验证失败 · 已恢复并验证原装备",
                            "裝備特殊效果驗證失敗 · 已還原並驗證原裝備")
                          + DescribeGearRollbackStorage(rollback)
                        : UiText.L(
                            $"장비 특수 효과 검증 실패 · 원래 장비 복구 검증도 실패({rollback.Detail})",
                            $"Gear special-effect verification failed · original-equipment rollback verification also failed ({rollback.Detail})",
                            $"装备特殊效果验证失败 · 原装备回滚验证也失败 ({rollback.Detail})",
                            $"裝備特殊效果驗證失敗 · 原裝備回復驗證也失敗 ({rollback.Detail})");
                    return false;
                }
                try
                {
                    InvokeRequiredInstance(gearTalentData ?? throw new InvalidOperationException("Talent data is unavailable."), "ReapplySkillVariantsFromEquippedItems");
                }
                catch (Exception refreshError)
                {
                    Plugin.DiagWarning($"AUTO-GEAR VARIANT ROLLBACK REFRESH FAILED|{refreshError.GetBaseException().Message}");
                }
                message = UiText.L(
                    "장비 특수 효과 검증 실패 · 적용된 장비 상태는 유지함",
                    "Gear special-effect verification failed · the applied gear state was kept",
                    "装备特殊效果验证失败 · 保留已应用的装备状态",
                    "裝備特殊效果驗證失敗 · 保留已套用的裝備狀態");
                moveJournal.Clear();
                return false;
            }

            // Standalone Auto Gear keeps its existing immediate commit behavior.
            // Combined Auto Build retains every reversible move until the skill
            // mutation and final joint verifier both succeed; only then may
            // storage normalization make the transaction irreversible.
            var storageNormalizationFailures = 0;
            var pendingHeroKey = combinedFlow
                ? MainThreadNativeGateway.Invoke(() => GetJointSkillPlanHeroKey(hero))
                : string.Empty;
            if (combinedFlow)
            {
                pendingGearCommit = new PendingGearCommit(
                    hero,
                    pendingHeroKey,
                    originalGearFingerprint,
                    moveJournal,
                    seasonData,
                    targetItems,
                    abilityBaseline);
            }
            else
            {
                ReportAutoBuildProgress(AutoBuildStep.FinalizingStorage);
                irreversibleStorageNormalizationStarted = true;
                storageNormalizationFailures = NormalizeCommittedStorage(moveJournal, seasonData, targetItems);
                moveJournal.Clear();
            }
            // Remembering the selected skill package and formatting its effect/
            // set audit both traverse native objects. Keep them in one gateway
            // item so final verification does not spend one rendered frame per
            // reflected property after the gear has already been applied.
            var completionDetails = MainThreadNativeGateway.Invoke(() =>
            {
                RememberJointSkillPlan(hero, winnerProfile);
                return (
                    ItemScoreBreakdown: DescribeSelectedItemScoreBreakdown(
                        slots, winner.State.Items, winner.Evaluation),
                    SetThresholdBreakdown: DescribeSetThresholdBreakdown(
                        winner.State.Items, winnerProfile));
            });
            jointPlanRemembered = true;
            gearCommitted = true;
            // A combined Auto Build intentionally equips the jointly selected
            // weapons before it transforms and reallocates skills. The temporary
            // old-skill mismatch is rechecked as a hard postcondition by the
            // skill stage, so do not present that transient state as a final
            // warning after a successful combined transaction.
            var reportUnusableSkill = unusableSkillFailed && !combinedFlow;
            var commitWarningKo = (storageNormalizationFailures, reportUnusableSkill) switch
            {
                (> 0, true) => " · 장비는 적용됐지만 보관 정리 실패 및 기존 학습 스킬 무기 불일치(스킬 자동 배분 실행)",
                (> 0, false) => " · 장비는 적용됐지만 보관 정리 일부 실패(수동 확인 필요)",
                (0, true) => " · 장비는 적용됐지만 기존 학습 스킬이 현재 무기와 불일치(스킬 자동 배분 실행)",
                _ => string.Empty
            };
            var commitWarningEn = (storageNormalizationFailures, reportUnusableSkill) switch
            {
                (> 0, true) => " · gear applied, but storage cleanup failed and old learned skills mismatch the weapons (run Auto Skills)",
                (> 0, false) => " · gear applied, but some storage cleanup failed (manual review needed)",
                (0, true) => " · gear applied, but old learned skills mismatch the weapons (run Auto Skills)",
                _ => string.Empty
            };
            var commitWarningZhCn = (storageNormalizationFailures, reportUnusableSkill) switch
            {
                (> 0, true) => " · 装备已应用，但存储整理失败且旧技能与武器不匹配（请运行自动技能）",
                (> 0, false) => " · 装备已应用，但部分存储整理失败（需要手动检查）",
                (0, true) => " · 装备已应用，但旧技能与武器不匹配（请运行自动技能）",
                _ => string.Empty
            };
            var commitWarningZhTw = (storageNormalizationFailures, reportUnusableSkill) switch
            {
                (> 0, true) => " · 裝備已套用，但儲存整理失敗且舊技能與武器不符（請執行自動技能）",
                (> 0, false) => " · 裝備已套用，但部分儲存整理失敗（需要手動檢查）",
                (0, true) => " · 裝備已套用，但舊技能與武器不符（請執行自動技能）",
                _ => string.Empty
            };

            var skillReason = winnerProfile.JointSkillReason;
            var itemScoreBreakdown = completionDetails.ItemScoreBreakdown;
            var setThresholdBreakdown = completionDetails.SetThresholdBreakdown;
            message = changed > 0
                ? UiText.L($"8부위 실제 장착 완료 · {focus.Localized} · 교체 {changed}개 · 계획 스킬 효과 일치 {directMatches} · 테마 키워드 일치 {themeMatches} · Mythic {selectedMythics}/{maxMythic} · 유지 {unchanged}개 · 공동 평가: {skillReason}{commitWarningKo}", $"All 8 slots equipped · {focus.English} · changed {changed} · planned-skill effect matches {directMatches} · theme-keyword matches {themeMatches} · Mythic {selectedMythics}/{maxMythic} · kept {unchanged} · joint evaluation: {skillReason}{commitWarningEn}", $"8部位已实际装备 · {focus.Localized} · 更换 {changed} · 计划技能效果匹配 {directMatches} · 主题关键词匹配 {themeMatches} · 神话 {selectedMythics}/{maxMythic} · 保留 {unchanged} · 联合评估：{skillReason}{commitWarningZhCn}", $"8部位已實際裝備 · {focus.Localized} · 更換 {changed} · 計畫技能效果相符 {directMatches} · 主題關鍵字符合 {themeMatches} · 神話 {selectedMythics}/{maxMythic} · 保留 {unchanged} · 聯合評估：{skillReason}{commitWarningZhTw}")
                : UiText.L($"평가한 후보 중 현재 8부위의 {focus.Localized} 추천 점수가 가장 높습니다. · 공동 평가: {skillReason}{commitWarningKo}", $"The current 8-slot loadout has the highest {focus.English} recommendation score among the evaluated candidates. · joint evaluation: {skillReason}{commitWarningEn}", $"在已评估候选中，当前 8 部位的 {focus.Localized} 推荐评分最高。 · 联合评估：{skillReason}{commitWarningZhCn}", $"在已評估候選中，目前 8 部位的 {focus.Localized} 推薦評分最高。 · 聯合評估：{skillReason}{commitWarningZhTw}");
            var nativePackageSkillIds = winnerProfile.PlannedSkills.ThemePackageSkillIds
                                        ?? new HashSet<int>();
            var selectedNativeSkillIds = winnerProfile.SkillIds
                .Append(winnerProfile.PreviewBaseSkillId)
                .Where(id => id > 0).ToHashSet();
            var nativePackageCoverage = nativePackageSkillIds.Count(selectedNativeSkillIds.Contains);
            var nativePackageRequired = Math.Max(
                0, winnerProfile.PlannedSkills.RequiredThemeSkillCount);
            var nativeContractSummary = nativePackageRequired > 0
                ? UiText.L(
                    $"공식 빌드 연계 스킬 {nativePackageCoverage}개 확인 (최소 {nativePackageRequired}개)",
                    $"official build-linked skills: {nativePackageCoverage} selected (minimum {nativePackageRequired})",
                    $"官方构筑关联技能已选 {nativePackageCoverage} 个（至少 {nativePackageRequired} 个）",
                    $"官方構築關聯技能已選 {nativePackageCoverage} 個（至少 {nativePackageRequired} 個）")
                : UiText.L(
                    "네이티브 스킬 계획 검증",
                    "native skill plan verified",
                    "原生技能方案已验证",
                    "原生技能方案已驗證");
            message = nativeContractSummary + " · " + message;
            // Keep the audit trail in the on-screen result/status instead of
            // adding release log spam. It makes an apparently off-theme Unique
            // explainable: its special can be zero while strong independent
            // stats still win the item comparison.
            message += UiText.L(
                $"\n아이템 점수 분해: {itemScoreBreakdown}\n세트 임계값: {setThresholdBreakdown}",
                $"\nItem score breakdown: {itemScoreBreakdown}\nSet thresholds: {setThresholdBreakdown}",
                $"\n装备评分明细：{itemScoreBreakdown}\n套装阈值：{setThresholdBreakdown}",
                $"\n裝備評分明細：{itemScoreBreakdown}\n套裝門檻：{setThresholdBreakdown}");
            message += $"\n{ComparisonAudit()}";
            // Storage tidy-up and the old learned-skill compatibility check run
            // after the target gear is committed. A compatibility warning is
            // actionable by Auto Skills and may be expected during a theme
            // switch, but it must not be reported as a verified success.
            return storageNormalizationFailures == 0 && (!unusableSkillFailed || combinedFlow);
        }
        catch (Exception error)
        {
            if (combinedFlow && !irreversibleStorageNormalizationStarted
                && rollbackHero is not null && rollbackGearFingerprint is not null
                && rollbackAbilityBaseline is not null)
            {
                var rememberedHeroKey = pendingGearCommit?.HeroKey;
                var rollback = RollbackUncommittedCombinedGear(
                    rollbackHero, gearTalentData, moveJournal, rollbackGearFingerprint, rollbackAbilityBaseline);
                if (jointPlanRemembered && !string.IsNullOrEmpty(rememberedHeroKey))
                    JointSkillPlansByHero.Remove(rememberedHeroKey);
                pendingGearCommit = null;
                gearCommitted = false;
                message = rollback.IsRecovered
                    ? UiText.L(
                        $"장비 자동 장착 실패: {error.GetBaseException().Message} · 원래 장비로 복구 및 검증 완료",
                        $"Auto-equip failed: {error.GetBaseException().Message} · original equipment restored and verified",
                        $"自动装备失败：{error.GetBaseException().Message} · 已恢复并验证原装备",
                        $"自動裝備失敗：{error.GetBaseException().Message} · 已還原並驗證原裝備")
                      + DescribeGearRollbackStorage(rollback)
                    : UiText.L(
                        $"장비 자동 장착 실패: {error.GetBaseException().Message} · 원래 장비 복구 검증 실패({rollback.Detail})",
                        $"Auto-equip failed: {error.GetBaseException().Message} · original-equipment rollback verification failed ({rollback.Detail})",
                        $"自动装备失败：{error.GetBaseException().Message} · 原装备回滚验证失败 ({rollback.Detail})",
                        $"自動裝備失敗：{error.GetBaseException().Message} · 原裝備回復驗證失敗 ({rollback.Detail})");
                return false;
            }
            var hadMoves = moveJournal.Count > 0;
            if (gearTalentData is not null)
            {
                try { InvokeRequiredInstance(gearTalentData, "ReapplySkillVariantsFromEquippedItems"); }
                catch (Exception refreshError) { Plugin.DiagWarning($"AUTO-GEAR VARIANT REFRESH FAILED|{refreshError.GetBaseException().Message}"); }
            }
            moveJournal.Clear();
            var keptNote = !hadMoves ? string.Empty : UiText.L(
                " · 현재까지 적용된 상태 유지",
                " · changes applied so far were kept",
                " · 保留目前已应用的状态",
                " · 保留目前已套用的狀態");
            message = UiText.L(
                $"장비 자동 장착 실패: {error.GetBaseException().Message}{keptNote}",
                $"Auto-equip failed: {error.GetBaseException().Message}{keptNote}",
                $"自动装备失败：{error.GetBaseException().Message}{keptNote}",
                $"自動裝備失敗：{error.GetBaseException().Message}{keptNote}");
            return false;
        }
    }

    public static bool TryOptimizeSelectedHeroBuild(bool includeStorage, out string message)
    {
        JointSkillRollbackSnapshot skillRollbackSnapshot;
        try
        {
            // Capture both the talent topology and the persistent currencies /
            // progress counters before the gear transaction starts. Any later
            // skill-stage failure can therefore restore the complete joint
            // build instead of leaving a partially reset hero behind.
            skillRollbackSnapshot = CaptureJointSkillRollbackSnapshot();
        }
        catch (Exception error)
        {
            message = UiText.L(
                $"공동 자동 빌드의 안전 복구 지점을 만들지 못했습니다. 장비·스킬을 변경하지 않았습니다: {error.GetBaseException().Message}",
                $"Could not capture a safe joint auto-build rollback point. Gear and skills were not changed: {error.GetBaseException().Message}",
                $"无法创建联合自动构筑的安全回滚点。未更改装备与技能：{error.GetBaseException().Message}",
                $"無法建立聯合自動配置的安全復原點。未變更裝備與技能：{error.GetBaseException().Message}");
            return false;
        }

        var gearSucceeded = TryOptimizeSelectedHeroGear(
            includeStorage,
            true,
            out var gearCommitted,
            out var pendingGearCommit,
            out var gearMessage);
        if (!gearCommitted)
        {
            message = gearMessage;
            return false;
        }
        if (pendingGearCommit is null)
        {
            message = UiText.L(
                "공동 자동 빌드 장비 트랜잭션을 찾지 못했습니다. 안전을 위해 스킬을 변경하지 않았습니다.",
                "The joint auto-build gear transaction is unavailable. Skills were not changed for safety.",
                "找不到联合自动构筑的装备事务。为安全起见未更改技能。",
                "找不到聯合自動配置的裝備交易。為安全起見未變更技能。");
            return false;
        }

        if (!TryOptimizeSkillsWithBloodLedger(true, skillRollbackSnapshot, out var skillMessage))
        {
            var rollback = RollbackJointBuild(pendingGearCommit, skillRollbackSnapshot);
            message = UiText.L(
                $"공동 자동 빌드 스킬 단계 미완료 · {skillMessage}",
                $"Joint auto-build skill step incomplete · {skillMessage}",
                $"联合自动构筑的技能步骤未完成 · {skillMessage}",
                $"聯合自動配置的技能步驟未完成 · {skillMessage}")
                + DescribeJointRollback(rollback);
            return false;
        }

        bool jointVerified;
        string verification;
        try
        {
            ReportAutoBuildProgress(AutoBuildStep.Verifying);
            jointVerified = VerifyRememberedJointBuild(
                pendingGearCommit.AbilityBaseline,
                out verification);
#if PATHOFIDLE_RUNTIME_TEST
            if (RuntimeRejectJointBuildAfterSkills)
            {
                jointVerified = false;
                verification = "injected verification failure after skills";
            }
#endif
        }
        catch (Exception error)
        {
            jointVerified = false;
            verification = $"final joint verification could not complete: {error.GetBaseException().Message}";
        }
        if (!jointVerified)
        {
            var rollback = RollbackJointBuild(pendingGearCommit, skillRollbackSnapshot);
            message = UiText.L(
                $"공동 자동 빌드 검증 실패 · {verification}",
                $"Joint auto-build verification failed · {verification}",
                $"联合自动构筑验证失败 · {verification}",
                $"聯合自動配置驗證失敗 · {verification}")
                + DescribeJointRollback(rollback);
            return false;
        }

        MainThreadNativeGateway.Invoke(() =>
        {
            var appliedHero = GetSelectedHero();
            if (appliedHero is null) return;
            var key = GetJointSkillPlanHeroKey(appliedHero);
            if (JointSkillPlansByHero.TryGetValue(key, out var appliedPlan))
                JointSkillPlansByHero[key] = appliedPlan with
                {
                    SkillFingerprint = GetSkillStateFingerprint(appliedHero)
                };
        });

        if (!gearSucceeded)
        {
            var rollback = RollbackJointBuild(pendingGearCommit, skillRollbackSnapshot);
            message = UiText.L(
                $"공동 자동 빌드 장비 단계 경고 · {gearMessage}",
                $"Joint auto-build gear-step warning · {gearMessage}",
                $"联合自动构筑装备步骤警告 · {gearMessage}",
                $"聯合自動配置裝備步驟警告 · {gearMessage}")
                + DescribeJointRollback(rollback);
            return false;
        }

        // The equipment journal remains reversible through both skill mutation
        // and the exact joint verifier. Storage tidy-up is the commit boundary.
        int storageNormalizationFailures;
        try
        {
            ReportAutoBuildProgress(AutoBuildStep.FinalizingStorage);
            storageNormalizationFailures = NormalizeCommittedStorage(
                pendingGearCommit.MoveJournal,
                pendingGearCommit.SeasonData,
                pendingGearCommit.TargetItems);
        }
        catch (Exception error)
        {
            // Normalization is the irreversible commit boundary: one or more
            // staged items may already have reached their native destination.
            // Do not attempt a journal rollback or discard the receipts when
            // the cleanup itself throws. Report the already-applied build and
            // leave the journal intact for the rest of this call's diagnostics.
            var detail = error.GetBaseException().Message;
            Plugin.DiagWarning($"AUTO-BUILD STORAGE COMMIT FAILED|{detail}");
            message = UiText.L(
                $"장비+스킬 공동 계획은 검증·적용됐지만 보관 정리가 예기치 않게 중단됐습니다. 적용 상태는 유지되며 보관함을 수동으로 확인해야 합니다: {detail} · {skillMessage}",
                $"The joint gear + skill plan was verified and applied, but storage cleanup stopped unexpectedly. The applied build remains in place; manually review storage: {detail} · {skillMessage}",
                $"装备与技能联合方案已验证并应用，但存储整理意外中断。已应用的方案会保留，请手动检查存储：{detail} · {skillMessage}",
                $"裝備與技能聯合方案已驗證並套用，但儲存整理意外中斷。已套用的方案會保留，請手動檢查儲存：{detail} · {skillMessage}");
            return false;
        }
        pendingGearCommit.MoveJournal.Clear();
        if (storageNormalizationFailures > 0)
        {
            message = UiText.L(
                $"장비+스킬 공동 계획은 검증·적용됐지만 보관 정리 {storageNormalizationFailures}건이 실패했습니다. 수동 확인이 필요합니다 · {skillMessage}",
                $"The joint gear + skill plan was verified and applied, but {storageNormalizationFailures} storage cleanup operation(s) failed. Manual review is required · {skillMessage}",
                $"装备与技能联合方案已验证并应用，但有 {storageNormalizationFailures} 项存储整理失败，需要手动检查 · {skillMessage}",
                $"裝備與技能聯合方案已驗證並套用，但有 {storageNormalizationFailures} 項儲存整理失敗，需要手動檢查 · {skillMessage}");
            return false;
        }

        // Preserve the gear-stage result. In particular, a deadline fallback to
        // the current loadout must not be hidden behind a generic joint-success
        // message while only the skills were actually rewritten.
        message = UiText.L(
            $"장비+스킬 공동 자동 빌드 검증 완료 · 장비: {gearMessage} · 스킬: {skillMessage}",
            $"Joint gear + skill auto-build verified · gear: {gearMessage} · skills: {skillMessage}",
            $"装备与技能联合自动构筑验证完成 · 装备：{gearMessage} · 技能：{skillMessage}",
            $"裝備與技能聯合自動配置驗證完成 · 裝備：{gearMessage} · 技能：{skillMessage}");
        return true;
    }

    private static JointSkillRollbackSnapshot CaptureJointSkillRollbackSnapshot()
    {
        var hero = GetSelectedHeroAfterAutoBuildWait()
                   ?? throw new InvalidOperationException("No hero is selected.");
        var saveHero = Read(hero, "saveHeroData")
                       ?? throw new InvalidOperationException("SaveHeroData is unavailable.");
        var talentData = Read(hero, "heroTalentData")
                         ?? throw new InvalidOperationException("HeroTalentData is unavailable.");
        var seasonData = Read(ReadStatic("Game", "dataMgr"), "nowSeasonData")
                         ?? throw new InvalidOperationException("SeasonData is unavailable.");
        var townData = Read(seasonData, "townData")
                       ?? throw new InvalidOperationException("TownData is unavailable.");
        var statData = Read(seasonData, "statData")
                       ?? throw new InvalidOperationException("StatData is unavailable.");
        var saveStatData = Read(statData, "saveStatData")
                           ?? throw new InvalidOperationException("SaveStatData is unavailable.");
        var bloodType = CreateEnum("EResType", 2)
                        ?? throw new InvalidOperationException("Blood resource type is unavailable.");
        var blood = Convert.ToInt32(
            InvokeRequiredInstance(townData, "GetRes", bloodType)
            ?? throw new InvalidOperationException("Blood amount is unavailable."),
            CultureInfo.InvariantCulture);
        var talents = CaptureSaveTalentRollbackStates(saveHero);
        var baseSkillId = ReadRequiredIntProperty(saveHero, "baseSkillId");
        if (baseSkillId <= 0)
            throw new InvalidOperationException(
                "The starting hero has no selected base skill, so an exact native rollback cannot be guaranteed.");
        var baseRow = talents.SingleOrDefault(state =>
            state.DictionaryKey == baseSkillId && state.Id == baseSkillId);
        var baseDefinition = InvokeStatic("TableData", "getTTalentData", baseSkillId);
        if (baseRow is null || baseRow.Level <= 0
            || baseDefinition is null || !IsBaseSkillDefinition(baseDefinition)
            || (ReadNullableInt(baseDefinition, "skillId") ?? 0) <= 0)
            throw new InvalidOperationException(
                $"The starting base-skill row {baseSkillId} is not present as an active native talent row.");
        var likeTalentIds = ReadTalentLikesRequired(townData);
        var heroKey = GetJointSkillPlanHeroKey(hero);
        var gearFingerprint = GetCurrentGearFingerprint(hero);
        return new JointSkillRollbackSnapshot(
            hero,
            heroKey,
            gearFingerprint,
            saveHero,
            talentData,
            townData,
            saveStatData,
            bloodType,
            blood,
            baseSkillId,
            ReadRequiredIntProperty(saveHero, "talentRemainPoint"),
            ReadRequiredIntProperty(saveHero, "talentStickPoint"),
            ReadRequiredIntProperty(saveHero, "blessTalentPoint"),
            ReadRequiredIntProperty(saveStatData, "changeBaseSkillCount"),
            ReadRequiredIntProperty(saveStatData, "washHeroCount"),
            ReadRequiredIntProperty(saveStatData, "learnNewSkillCount"),
            likeTalentIds,
            talents);
    }

    private static string GetSkillStateFingerprint(object hero)
    {
        var saveHero = Read(hero, "saveHeroData")
                       ?? throw new InvalidOperationException("SaveHeroData is unavailable while capturing the skill-state token.");
        return ComposeHeroSkillStateFingerprint(
            ReadRequiredIntProperty(saveHero, "baseSkillId"),
            CaptureSaveTalentRollbackStates(saveHero));
    }

    private static string GetSkillStateFingerprint(JointSkillRollbackSnapshot snapshot)
        => ComposeHeroSkillStateFingerprint(
            snapshot.BaseSkillId,
            snapshot.Talents);

    private static string ComposeHeroSkillStateFingerprint(
        int baseSkillId,
        IEnumerable<SaveTalentRollbackState> talents)
    {
        var rows = string.Join(";", talents.OrderBy(state => state.DictionaryKey).Select(state => string.Join(",",
            state.DictionaryKey,
            state.Id,
            state.Level,
            state.PosId,
            state.IsFixed ? 1 : 0,
            state.IsInspired ? 1 : 0,
            state.IsInspiredLocked ? 1 : 0,
            state.InspireBaseLevel,
            state.InspireRow,
            state.InspireCol,
            state.InspireMaxLevel,
            state.IsAlien ? 1 : 0)));
        return $"base={baseSkillId}|talents={rows}";
    }

    private static List<SaveTalentRollbackState> CaptureSaveTalentRollbackStates(object saveHero)
    {
        var talentDictionary = ReadRequiredProperty(saveHero, "talentDic")
                               ?? throw new InvalidOperationException("SaveHeroData.talentDic is unavailable.");
        var result = new List<SaveTalentRollbackState>();
        foreach (var entry in ReadEntries(talentDictionary))
        {
            var dictionaryKey = ReadRequiredIntProperty(entry, "Key");
            var saveTalent = ReadRequiredProperty(entry, "Value")
                             ?? throw new InvalidOperationException($"SaveTalentData for key {dictionaryKey} is unavailable.");
            result.Add(CaptureSaveTalentRollbackState(dictionaryKey, saveTalent));
        }
        if (result.Count == 0)
            throw new InvalidOperationException("SaveHeroData.talentDic is empty.");
        if (result.Select(entry => entry.DictionaryKey).Distinct().Count() != result.Count)
            throw new InvalidOperationException("SaveHeroData.talentDic contains duplicate keys.");
        var saveTalentIdentities = new HashSet<string>(StringComparer.Ordinal);
        foreach (var state in result)
        {
            if (!saveTalentIdentities.Add(NativeReferenceIdentity(state.SaveTalent)))
                throw new InvalidOperationException(
                    $"SaveHeroData.talentDic binds the same SaveTalentData object to more than one key (duplicate at {state.DictionaryKey}).");
        }
        return result.OrderBy(entry => entry.DictionaryKey).ToList();
    }

    private static SaveTalentRollbackState CaptureSaveTalentRollbackState(int dictionaryKey, object saveTalent)
        => new(
            dictionaryKey,
            saveTalent,
            ReadRequiredIntProperty(saveTalent, "id"),
            ReadRequiredIntProperty(saveTalent, "level"),
            ReadRequiredIntProperty(saveTalent, "posId"),
            ReadRequiredBoolProperty(saveTalent, "isFixed"),
            ReadRequiredBoolProperty(saveTalent, "isInspired"),
            ReadRequiredBoolProperty(saveTalent, "isInspiredLocked"),
            ReadRequiredIntProperty(saveTalent, "inspireBaseLevel"),
            ReadRequiredIntProperty(saveTalent, "inspireRow"),
            ReadRequiredIntProperty(saveTalent, "inspireCol"),
            ReadRequiredIntProperty(saveTalent, "inspireMaxLevel"),
            ReadRequiredBoolProperty(saveTalent, "isAlien"));

    private static JointBuildRollbackResult RollbackJointBuild(
        PendingGearCommit pendingGearCommit,
        JointSkillRollbackSnapshot snapshot)
    {
        var failures = new List<string>();
        var gearMoveRollback = RollbackMoveJournal(pendingGearCommit.MoveJournal);
        var gearMoveFailures = gearMoveRollback.Failures;
        if (gearMoveFailures > 0)
            failures.Add($"equipment reverse moves failed {gearMoveFailures}");

        var gearFingerprintRestored = false;
        try
        {
            gearFingerprintRestored = string.Equals(
                GetCurrentGearFingerprint(pendingGearCommit.Hero),
                pendingGearCommit.OriginalGearFingerprint,
                StringComparison.Ordinal);
            if (!gearFingerprintRestored)
                failures.Add("original equipment fingerprint was not restored");
        }
        catch (Exception error)
        {
            failures.Add($"equipment rollback verification failed: {error.GetBaseException().Message}");
        }

        var skillStateRestored = false;
        var progressStateRestored = false;
        var bloodRestored = false;
        var selectedHero = GetSelectedHero();
        var sameHero = selectedHero is not null
                       && string.Equals(GetJointSkillPlanHeroKey(selectedHero), snapshot.HeroKey, StringComparison.Ordinal)
                       && NativeEquals(selectedHero, snapshot.Hero)
                       && NativeEquals(Read(selectedHero, "saveHeroData"), snapshot.SaveHero)
                       && NativeEquals(Read(selectedHero, "heroTalentData"), snapshot.TalentData)
                       && string.Equals(pendingGearCommit.HeroKey, snapshot.HeroKey, StringComparison.Ordinal);
        if (!sameHero)
        {
            failures.Add("selected hero changed before the skill rollback");
        }
        else
        {
            try
            {
                var saveHero = Read(selectedHero, "saveHeroData")
                               ?? throw new InvalidOperationException("SaveHeroData is unavailable during rollback.");
                var talentData = Read(selectedHero, "heroTalentData")
                                 ?? throw new InvalidOperationException("HeroTalentData is unavailable during rollback.");
                RestoreSaveTalentRollbackStates(saveHero, snapshot.Talents);
                Write(saveHero, "baseSkillId", snapshot.BaseSkillId);
                Write(saveHero, "talentRemainPoint", snapshot.TalentRemainPoint);
                Write(saveHero, "talentStickPoint", snapshot.TalentStickPoint);
                Write(saveHero, "blessTalentPoint", snapshot.BlessTalentPoint);

                // Rehydrate the live TalentData graph from the exact restored
                // save rows. ReCreateTalent is intentionally forbidden here:
                // the native method rerolls replaceable shrine rows instead of
                // merely rebuilding their runtime wrappers.
                // Native CreateTalentDic starts by clearing the old talent
                // effects and live dictionary itself. Calling either operation
                // ahead of it would risk subtracting an effect twice.
                InvokeRequiredInstance(talentData, "CreateTalentDic");
                // FloorData caches references to TalentData nodes, so it must
                // follow the dictionary rebuild before effects are reapplied.
                InvokeRequiredInstance(talentData, "CreateTalentFloorDic");
                // CreateTalentDic restores the chosen SkillData flag, but the
                // native base-skill setter also refreshes the hero's derived
                // base-attack attribute. Its statistic increment is restored
                // from the snapshot below before Stele progress is rebuilt.
                InvokeRequiredInstance(talentData, "ChangeBaseSkill", snapshot.BaseSkillId);
                InvokeRequiredInstance(talentData, "ReapplySkillVariantsFromEquippedItems");
                VerifyJointSkillRollbackState(selectedHero!, talentData, saveHero, snapshot);
                skillStateRestored = true;
            }
            catch (Exception error)
            {
                failures.Add($"skill rollback failed: {error.GetBaseException().Message}");
            }

        }

        // Base-skill selection, shrine washing, and first-time skill learning
        // each update a persistent SaveStatData counter. They also recalculate
        // Stele claimability from those counters. Restore the counters and the
        // temporary Codex preference list, then run that same native derivation
        // once so the live Stele UI cannot retain rolled-back progress.
        try
        {
            var currentSeason = Read(ReadStatic("Game", "dataMgr"), "nowSeasonData")
                                ?? throw new InvalidOperationException("SeasonData is unavailable during progress rollback.");
            var currentTownData = Read(currentSeason, "townData")
                                  ?? throw new InvalidOperationException("TownData is unavailable during progress rollback.");
            if (!NativeEquals(currentTownData, snapshot.TownData))
                throw new InvalidOperationException("the active TownData changed before progress rollback");
            var currentStatData = Read(currentSeason, "statData")
                                  ?? throw new InvalidOperationException("StatData is unavailable during progress rollback.");
            var currentSaveStatData = Read(currentStatData, "saveStatData")
                                      ?? throw new InvalidOperationException("SaveStatData is unavailable during progress rollback.");
            if (!NativeEquals(currentSaveStatData, snapshot.SaveStatData))
                throw new InvalidOperationException("the active SaveStatData changed before progress rollback");

            RestoreTalentLikes(snapshot.TownData, snapshot.LikeTalentIds);
            Write(currentSaveStatData, "changeBaseSkillCount", snapshot.ChangeBaseSkillCount);
            Write(currentSaveStatData, "washHeroCount", snapshot.WashHeroCount);
            Write(currentSaveStatData, "learnNewSkillCount", snapshot.LearnNewSkillCount);
            InvokeRequiredInstance(snapshot.TownData, "UpdateSteleProgress");
            VerifyJointProgressRollbackState(currentSaveStatData, snapshot);
            progressStateRestored = true;
        }
        catch (Exception error)
        {
            failures.Add($"progress rollback failed: {error.GetBaseException().Message}");
        }

        // Refund only this transaction's measured debit. Other parties keep
        // earning Blood while gear is being planned; their income is neither a
        // rollback failure nor currency owned by this transaction.
        try
        {
            if (!snapshot.BloodAccountingVerified)
                throw new InvalidOperationException("The skill transaction's Blood debit could not be verified.");
            MainThreadNativeGateway.Invoke(() =>
            {
                var bloodNow = Convert.ToInt32(
                    InvokeRequiredInstance(snapshot.TownData, "GetRes", snapshot.BloodType)
                    ?? throw new InvalidOperationException("Blood amount is unavailable during rollback."),
                    CultureInfo.InvariantCulture);
                var expectedBlood = checked(bloodNow + snapshot.ConsumedBlood);
                if (snapshot.ConsumedBlood > 0)
                    InvokeRequiredInstance(snapshot.TownData, "AddRes", snapshot.BloodType, snapshot.ConsumedBlood);
                var bloodAfter = Convert.ToInt32(
                    InvokeRequiredInstance(snapshot.TownData, "GetRes", snapshot.BloodType)
                    ?? throw new InvalidOperationException("Blood amount is unavailable after refund."),
                    CultureInfo.InvariantCulture);
                if (bloodAfter != expectedBlood)
                    throw new InvalidOperationException($"Blood mismatch after refund ({bloodAfter}/{expectedBlood}).");
                snapshot.ConsumedBlood = 0;
            });
            bloodRestored = true;
        }
        catch (Exception error)
        {
            failures.Add($"Blood refund failed: {error.GetBaseException().Message}");
        }

        JointSkillPlansByHero.Remove(snapshot.HeroKey);
        return new JointBuildRollbackResult(
            gearMoveFailures,
            gearMoveRollback.VaultRelocations,
            gearFingerprintRestored,
            skillStateRestored,
            progressStateRestored,
            bloodRestored,
            failures);
    }

    private static void RestoreSaveTalentRollbackStates(
        object saveHero,
        IReadOnlyCollection<SaveTalentRollbackState> expected)
    {
        var talentDictionary = ReadRequiredProperty(saveHero, "talentDic")
                               ?? throw new InvalidOperationException("SaveHeroData.talentDic is unavailable during rollback.");
        if (expected.Count == 0)
            throw new InvalidOperationException("the starting talent dictionary snapshot is empty");
        if (expected.Select(state => state.DictionaryKey).Distinct().Count() != expected.Count)
            throw new InvalidOperationException("the starting talent dictionary snapshot contains duplicate keys");
        var expectedList = expected.ToList();
        var expectedIdentities = new HashSet<string>(StringComparer.Ordinal);
        foreach (var state in expectedList)
        {
            if (!expectedIdentities.Add(NativeReferenceIdentity(state.SaveTalent)))
                throw new InvalidOperationException(
                    $"the starting talent dictionary snapshot binds one SaveTalentData object to more than one key (duplicate at {state.DictionaryKey})");
        }

        // Shrine washing may replace both the keys and the SaveTalentData
        // values in the save dictionary. Restore the original objects while
        // the snapshot still owns strong references to them, then rebuild the
        // exact key/value topology before the native runtime graph is created.
        foreach (var state in expectedList)
        {
            var saveTalent = state.SaveTalent;
            Write(saveTalent, "id", state.Id);
            Write(saveTalent, "level", state.Level);
            Write(saveTalent, "posId", state.PosId);
            Write(saveTalent, "isFixed", state.IsFixed);
            Write(saveTalent, "isInspired", state.IsInspired);
            Write(saveTalent, "isInspiredLocked", state.IsInspiredLocked);
            Write(saveTalent, "inspireBaseLevel", state.InspireBaseLevel);
            Write(saveTalent, "inspireRow", state.InspireRow);
            Write(saveTalent, "inspireCol", state.InspireCol);
            Write(saveTalent, "inspireMaxLevel", state.InspireMaxLevel);
            Write(saveTalent, "isAlien", state.IsAlien);
        }

        InvokeRequiredInstance(talentDictionary, "Clear");
        foreach (var state in expectedList)
            InvokeRequiredInstance(talentDictionary, "Add", state.DictionaryKey, state.SaveTalent);

        VerifySaveTalentRollbackStates(
            CaptureSaveTalentRollbackStates(saveHero),
            expectedList,
            "restored saved talent dictionary");
    }

    private static bool SaveTalentRollbackValuesEqual(
        SaveTalentRollbackState actual,
        SaveTalentRollbackState expected)
        => actual.DictionaryKey == expected.DictionaryKey
           && actual.Id == expected.Id
           && actual.Level == expected.Level
           && actual.PosId == expected.PosId
           && actual.IsFixed == expected.IsFixed
           && actual.IsInspired == expected.IsInspired
           && actual.IsInspiredLocked == expected.IsInspiredLocked
           && actual.InspireBaseLevel == expected.InspireBaseLevel
           && actual.InspireRow == expected.InspireRow
           && actual.InspireCol == expected.InspireCol
           && actual.InspireMaxLevel == expected.InspireMaxLevel
           && actual.IsAlien == expected.IsAlien;

    private static void VerifySaveTalentRollbackStates(
        IReadOnlyCollection<SaveTalentRollbackState> actual,
        IReadOnlyCollection<SaveTalentRollbackState> expected,
        string scope)
    {
        if (actual.Count != expected.Count)
            throw new InvalidOperationException(
                $"{scope} entry count differs from the starting snapshot ({actual.Count}/{expected.Count})");

        var actualByKey = actual.ToDictionary(state => state.DictionaryKey);
        foreach (var expectedState in expected)
        {
            if (!actualByKey.TryGetValue(expectedState.DictionaryKey, out var actualState))
                throw new InvalidOperationException(
                    $"{scope} is missing starting key {expectedState.DictionaryKey}");
            if (!NativeEquals(actualState.SaveTalent, expectedState.SaveTalent))
                throw new InvalidOperationException(
                    $"{scope} key {expectedState.DictionaryKey} is not bound to its original SaveTalentData object");
            if (!SaveTalentRollbackValuesEqual(actualState, expectedState))
                throw new InvalidOperationException(
                    $"{scope} fields differ for starting key {expectedState.DictionaryKey}");
        }
    }

    private static void VerifyJointSkillRollbackState(
        object hero,
        object talentData,
        object saveHero,
        JointSkillRollbackSnapshot expected)
    {
        var actualTalents = CaptureSaveTalentRollbackStates(saveHero);
        VerifySaveTalentRollbackStates(actualTalents, expected.Talents, "saved talent dictionary");
        if (ReadRequiredIntProperty(saveHero, "baseSkillId") != expected.BaseSkillId
            || ReadRequiredIntProperty(saveHero, "talentRemainPoint") != expected.TalentRemainPoint
            || ReadRequiredIntProperty(saveHero, "talentStickPoint") != expected.TalentStickPoint
            || ReadRequiredIntProperty(saveHero, "blessTalentPoint") != expected.BlessTalentPoint)
            throw new InvalidOperationException("saved base-skill or talent-point fields do not match the starting snapshot");

        var expectedBaseDefinition = expected.BaseSkillId > 0
            ? InvokeStatic("TableData", "getTTalentData", expected.BaseSkillId)
            : null;
        var expectedBaseSkillId = ReadNullableInt(expectedBaseDefinition, "skillId") ?? 0;
        if (expected.BaseSkillId > 0 && expectedBaseSkillId <= 0)
            throw new InvalidOperationException($"starting base talent {expected.BaseSkillId} no longer resolves to a skill");
        var liveBaseSkill = InvokeRequiredInstance(hero, "GetNowBaseSkillData");
        var liveBaseSkillId = ReadNullableInt(Read(liveBaseSkill, "tSkillData"), "id") ?? 0;
        if (liveBaseSkillId != expectedBaseSkillId)
            throw new InvalidOperationException(
                $"live base skill does not match the starting snapshot ({liveBaseSkillId}/{expectedBaseSkillId})");

        var runtimeDictionary = ReadRequiredProperty(talentData, "talentDic")
                                ?? throw new InvalidOperationException("HeroTalentData.talentDic is unavailable after rollback.");
        var runtimeByKey = ReadEntries(runtimeDictionary).ToDictionary(
            entry => ReadRequiredIntProperty(entry, "Key"),
            entry => ReadRequiredProperty(entry, "Value")
                     ?? throw new InvalidOperationException("TalentData is unavailable after rollback."));
        if (runtimeByKey.Count != expected.Talents.Count
            || expected.Talents.Any(state => !runtimeByKey.ContainsKey(state.DictionaryKey)))
            throw new InvalidOperationException("live talent dictionary keys do not match the starting snapshot");

        var restoredSkillIds = new HashSet<int>();
        foreach (var state in expected.Talents)
        {
            var runtimeTalent = runtimeByKey[state.DictionaryKey];
            var runtimeSave = ReadRequiredProperty(runtimeTalent, "saveTalentData")
                              ?? throw new InvalidOperationException(
                                  $"live talent {state.DictionaryKey} has no SaveTalentData after rollback");
            if (!NativeEquals(runtimeSave, state.SaveTalent))
                throw new InvalidOperationException(
                    $"live talent {state.DictionaryKey} is not bound to its original SaveTalentData object");
            var runtimeState = CaptureSaveTalentRollbackState(state.DictionaryKey, runtimeSave);
            if (!SaveTalentRollbackValuesEqual(runtimeState, state))
                throw new InvalidOperationException(
                    $"live talent {state.DictionaryKey} is not bound to the restored SaveTalentData fields");

            var definition = ReadRequiredProperty(runtimeTalent, "tTalentData")
                             ?? throw new InvalidOperationException(
                                 $"live talent {state.DictionaryKey} has no talent definition after rollback");
            var definitionId = ReadRequiredIntProperty(definition, "id");
            if (definitionId != state.Id)
                throw new InvalidOperationException(
                    $"live talent definition differs after rollback ({definitionId}/{state.Id})");

            var savedLevel = GetSavedTalentLevel(runtimeTalent);
            if (savedLevel != Math.Max(0, state.Level))
                throw new InvalidOperationException(
                    $"live saved talent level differs after rollback for {state.Id} ({savedLevel}/{state.Level})");
            var expectedEffective = GetExpectedTalentEffectiveLevel(runtimeTalent, savedLevel);
            var effectiveLevel = GetTalentLevel(runtimeTalent);
            if (!IsExpectedTalentEffectiveLevel(runtimeTalent, savedLevel, effectiveLevel))
                throw new InvalidOperationException(
                    $"live effective talent level differs after rollback for {state.Id} ({effectiveLevel}/{expectedEffective})");

            var skillId = ReadNullableInt(definition, "skillId") ?? 0;
            if (skillId > 0
                && (IsBaseSkillDefinition(definition)
                    ? state.Id == expected.BaseSkillId
                    : IsTransformableSkillDefinition(definition) && savedLevel > 0))
                restoredSkillIds.Add(skillId);
        }

        // Every native base-skill row keeps a saved level of one even when it
        // is not the selected base attack. Require only the selected base row,
        // genuinely learned active rows, and equipment-granted skills. This
        // still detects a learned skill missing from the rebuilt live graph
        // without treating an inactive base candidate (for example 1401 while
        // baseSkillId is 1403) as a missing variant.
        foreach (var grantedSkillId in GetCurrentGrantedSkillLevels(hero).Keys)
            restoredSkillIds.Add(grantedSkillId);
        var variants = VerifyEquippedSkillVariants(
            hero, talentData, "AUTO-BUILD ROLLBACK", restoredSkillIds);
        if (!variants.IsExact)
            throw new InvalidOperationException(
                $"equipped skill variants differ after rollback (-{string.Join(',', variants.Missing)} +{string.Join(',', variants.Unexpected)})");
    }

    private static void VerifyJointProgressRollbackState(
        object saveStatData,
        JointSkillRollbackSnapshot expected)
    {
        if (ReadRequiredIntProperty(saveStatData, "changeBaseSkillCount") != expected.ChangeBaseSkillCount
            || ReadRequiredIntProperty(saveStatData, "washHeroCount") != expected.WashHeroCount
            || ReadRequiredIntProperty(saveStatData, "learnNewSkillCount") != expected.LearnNewSkillCount)
            throw new InvalidOperationException(
                "saved base-skill, shrine-wash, or learned-skill progress counters do not match the starting snapshot");

        var actualLikes = ReadTalentLikesRequired(expected.TownData);
        if (!actualLikes.SequenceEqual(expected.LikeTalentIds))
            throw new InvalidOperationException(
                $"saved talent preference order differs after rollback (expected {string.Join(',', expected.LikeTalentIds)}, got {string.Join(',', actualLikes)})");
    }

    private static string DescribeJointRollback(JointBuildRollbackResult rollback, int language)
    {
        if (rollback.IsExact)
        {
            return language switch
            {
                0 => " · 변경 전 장비·스킬·피·진행도·스킬 선호 복구 검증 완료",
                1 => " · original gear, skills, Blood, progress, and skill preferences restored and verified",
                2 => " · 已恢复并验证原装备、技能、鲜血、进度与技能偏好",
                _ => " · 已復原並驗證原裝備、技能、鮮血、進度與技能偏好"
            };
        }

        if (rollback.IsRecovered)
        {
            return language switch
            {
                0 => $" · 변경 전 장비·스킬·피·진행도·스킬 선호 복구 검증 완료 · 꺼낸 Vault 장비 {rollback.VaultRelocations}개는 일반 창고에 보존",
                1 => $" · original gear, skills, Blood, progress, and skill preferences restored and verified · {rollback.VaultRelocations} extracted Vault item(s) preserved in ordinary Warehouse",
                2 => $" · 已恢复并验证原装备、技能、鲜血、进度与技能偏好 · {rollback.VaultRelocations} 件已取出的宝库装备保存在普通仓库",
                _ => $" · 已復原並驗證原裝備、技能、鮮血、進度與技能偏好 · {rollback.VaultRelocations} 件已取出的寶庫裝備保存在普通倉庫"
            };
        }

        var detail = rollback.Failures.Count == 0
            ? "unknown rollback mismatch"
            : string.Join("; ", rollback.Failures);
        return language switch
        {
            0 => $" · 복구 실패: {detail}",
            1 => $" · rollback failed: {detail}",
            2 => $" · 回滚失败：{detail}",
            _ => $" · 復原失敗：{detail}"
        };
    }

    private static string DescribeJointRollback(JointBuildRollbackResult rollback)
        => DescribeJointRollback(rollback, UiText.LanguageCode switch
        {
            "ko" => 0,
            "zh-cn" => 2,
            "zh-tw" => 3,
            _ => 1
        });

    private static bool VerifyRememberedJointBuild(
        GearAbilityBaseline? abilityBaseline,
        out string failure)
    {
        var verifiedFailure = string.Empty;
        var verified = MainThreadNativeGateway.Invoke(() =>
            VerifyRememberedJointBuildCore(abilityBaseline, out verifiedFailure));
        failure = verifiedFailure;
        return verified;
    }

    private static bool VerifyRememberedJointBuildCore(
        GearAbilityBaseline? abilityBaseline,
        out string failure)
    {
        if (abilityBaseline is null)
        {
            failure = "the committed gear ability baseline is unavailable";
            return false;
        }
        var hero = GetSelectedHero();
        if (hero is null)
        {
            failure = "selected hero is unavailable";
            return false;
        }
        var key = GetJointSkillPlanHeroKey(hero);
        if (!JointSkillPlansByHero.TryGetValue(key, out var remembered))
        {
            failure = "the remembered joint plan is unavailable";
            return false;
        }
        if (string.IsNullOrWhiteSpace(remembered.PlanToken))
        {
            failure = "the remembered joint plan has an empty plan token";
            return false;
        }
        if (!string.Equals(remembered.GearFingerprint, GetCurrentGearFingerprint(hero), StringComparison.Ordinal))
        {
            failure = "the equipped items no longer match the remembered joint plan";
            return false;
        }

        var talentData = Read(hero, "heroTalentData");
        var saveHero = Read(hero, "saveHeroData");
        if (talentData is null || saveHero is null)
        {
            failure = "hero talent data is unavailable";
            return false;
        }
        var talents = ReadValues(Read(talentData, "talentDic"))
            .DistinctBy(value => NativeObjectKey(value, value)).ToList();
        var expectedActive = remembered.ActiveSkillIds.ToHashSet();
        var learnedActive = talents
            .Where(talent => IsTransformableSkillDefinition(Read(talent, "tTalentData")))
            .Where(talent => GetSavedTalentLevel(talent) > 0)
            .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "skillId") ?? 0)
            .Where(id => id > 0).ToHashSet();
        if (!learnedActive.SetEquals(expectedActive))
        {
            failure = $"active skills differ ({string.Join(',', learnedActive.OrderBy(id => id))}/{string.Join(',', expectedActive.OrderBy(id => id))})";
            return false;
        }

        var actualBase = InvokeRequiredInstance(hero, "GetNowBaseSkillData");
        var actualBaseId = ReadNullableInt(Read(actualBase, "tSkillData"), "id") ?? 0;
        if (actualBaseId != remembered.BaseSkillId)
        {
            failure = $"base skill differs ({actualBaseId}/{remembered.BaseSkillId})";
            return false;
        }
        // Native GetSkillList enumerates learned active and equipment-granted
        // skills, but the chosen base attack is exposed separately through
        // GetNowBaseSkillData. Recheck its weapon contract here instead of
        // incorrectly requiring it to appear in GetSkillList.
        if (!IsSkillCompatibleWithEquippedWeapons(hero, remembered.BaseSkillId))
        {
            failure = $"base skill {remembered.BaseSkillId} is incompatible with the committed weapons";
            return false;
        }
        var usableSkillRows = ReadList(InvokeRequiredInstance(talentData, "GetSkillList"));
        var usableSkills = usableSkillRows
            .Select(skill => ReadNullableInt(Read(skill, "tSkillData"), "id") ?? 0)
            .Where(id => id > 0).ToHashSet();
        var currentGrantedSkillLevels = GetCurrentGrantedSkillLevels(hero);
        if (currentGrantedSkillLevels.Count != remembered.GrantedSkillLevels.Count
            || remembered.GrantedSkillLevels.Any(entry =>
                currentGrantedSkillLevels.GetValueOrDefault(entry.Key) != entry.Value))
        {
            failure = "equipment-granted skills differ from the remembered combat package";
            return false;
        }
        var actualActivePackage = learnedActive.Concat(currentGrantedSkillLevels.Keys)
            .Where(id => id > 0).ToHashSet();
        var hasManualThemeContract = remembered.RequiredBaseSkillIds.Count > 0
                                     || remembered.RequiredActiveSkillIds.Count > 0
                                     || remembered.RequiredThemeSkillCount > 0;
        var satisfiesManualThemeContract = SatisfiesThemeSkillContract(
            actualBaseId,
            learnedActive,
            currentGrantedSkillLevels.Keys,
            remembered.RequiredBaseSkillIds,
            remembered.RequiredActiveSkillIds,
            remembered.ThemePackageSkillIds,
            remembered.RequiredThemeSkillCount);
        if (hasManualThemeContract && !satisfiesManualThemeContract)
        {
            var actualThemeCount = actualActivePackage.Append(actualBaseId)
                .Where(remembered.ThemePackageSkillIds.Contains).Distinct().Count();
            failure = $"the skill package does not satisfy its native theme contract (core base={string.Join(',', remembered.RequiredBaseSkillIds.OrderBy(id => id))}; core active={string.Join(',', remembered.RequiredActiveSkillIds.OrderBy(id => id))}; coverage={actualThemeCount}/{remembered.RequiredThemeSkillCount})";
            return false;
        }
        var expectedUsableSkills = remembered.ActiveSkillIds
            .Concat(remembered.GrantedSkillLevels.Keys)
            .Where(id => id > 0).ToHashSet();
        var expectedPackageSkills = expectedUsableSkills
            .Append(remembered.BaseSkillId).Where(id => id > 0).ToHashSet();
        var missingSkills = expectedUsableSkills
            .Where(id => id > 0 && !usableSkills.Contains(id)).Distinct().OrderBy(id => id).ToList();
        var underleveledGrantedSkills = remembered.GrantedSkillLevels.Where(entry =>
            usableSkillRows.Where(skill =>
                    (ReadNullableInt(Read(skill, "tSkillData"), "id") ?? 0) == entry.Key)
                .Select(skill => ReadNullableInt(skill, "level") ?? 0)
                .DefaultIfEmpty(0).Max() < entry.Value)
            .Select(entry => $"{entry.Key}:{entry.Value}").OrderBy(value => value).ToList();
        if (missingSkills.Count > 0 || underleveledGrantedSkills.Count > 0
                                    || ReadBool(InvokeRequiredInstance(talentData, "IsHasUnusableSkill")))
        {
            failure = $"planned skills are unavailable with the committed gear (missing {string.Join(',', missingSkills)}; granted levels {string.Join(',', underleveledGrantedSkills)})";
            return false;
        }

        var talentById = BuildTalentGridById(talents);
        var resolvedTargets = new Dictionary<int, (object Talent, int Target)>();
        var levelFailures = new List<string>();

        // TargetSavedLevels is the exact materialized save vector. Native
        // ChangeBaseSkill contributes one saved level without reducing
        // talentRemainPoint, while TotalTalentPointBudget contains only normal
        // paid points. Keep that distinction explicit so a 54-point plan with a
        // free base level is verified as 55 saved levels, not mistaken for an
        // over-allocation (or silently accepted as a 53-point plan).
        var rememberedBaseTargets = remembered.TargetSavedLevels
            .Where(entry => IsBaseSkillDefinition(InvokeStatic("TableData", "getTTalentData", entry.Key)))
            .ToList();
        if (rememberedBaseTargets.Count != 1 || rememberedBaseTargets[0].Value < 1)
        {
            failure = "the remembered joint plan has no single materialized base-skill level";
            return false;
        }
        var materializedTargetTotal = remembered.TargetSavedLevels.Values.Sum();
        var rememberedPaidPointTotal = checked(materializedTargetTotal - 1);
        if (rememberedPaidPointTotal != remembered.TotalTalentPointBudget)
        {
            failure = $"joint target budget differs (paid {rememberedPaidPointTotal}/{remembered.TotalTalentPointBudget}; materialized {materializedTargetTotal})";
            return false;
        }
        var rememberedRemainingPoints = ReadNullableInt(saveHero, "talentRemainPoint") ?? -1;
        if (rememberedRemainingPoints != 0)
        {
            failure = $"joint target left unspent talent points ({rememberedRemainingPoints})";
            return false;
        }

        string DescribeTalentLevel(object talent, int target, string? prefix = null)
        {
            var definition = Read(talent, "tTalentData");
            var talentId = ReadNullableInt(definition, "id") ?? 0;
            var skillId = ReadNullableInt(definition, "skillId") ?? 0;
            var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
            var skillRow = skillId > 0 ? InvokeStatic("TableData", "getTSkillData", skillId) : null;
            var masteryRow = masteryId > 0 ? InvokeStatic("TableData", "getTMasteryData", masteryId) : null;
            var name = FirstNonEmpty(
                Clean(ReadString(skillRow, "name") ?? EnglishName(skillRow, string.Empty) ?? string.Empty),
                Clean(ReadString(masteryRow, "name") ?? EnglishName(masteryRow, string.Empty) ?? string.Empty),
                Clean(ReadString(definition, "name") ?? EnglishName(definition, string.Empty) ?? string.Empty),
                "talent");
            var nativeId = skillId > 0 ? skillId : talentId;
            var saved = GetSavedTalentLevel(talent);
            var effective = GetTalentLevel(talent);
            var cap = GetTalentLevelCap(talent);
            return $"{prefix}{name}#{nativeId} talent={talentId} saved={saved}/{target} effective={effective}/{Math.Min(cap, GetTalentBaseLevelRequired(talent) + target)} cap={cap} plan={remembered.PlanToken}";
        }

        foreach (var targetEntry in remembered.TargetSavedLevels.OrderBy(entry => entry.Key))
        {
            var plannedDefinition = InvokeStatic("TableData", "getTTalentData", targetEntry.Key);
            object? actualTalent = null;
            if (IsTransformableSkillDefinition(plannedDefinition))
            {
                // Shrine transformation replaces the talent row ID. The native
                // skill ID is the stable identity for active-skill targets.
                var skillId = ReadNullableInt(plannedDefinition, "skillId") ?? 0;
                actualTalent = talentById.Values
                    .Where(talent => IsTransformableSkillDefinition(Read(talent, "tTalentData")))
                    .Where(talent => (ReadNullableInt(Read(talent, "tTalentData"), "skillId") ?? 0) == skillId)
                    .OrderByDescending(talent => GetSavedTalentLevel(talent))
                    .ThenBy(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? int.MaxValue)
                    .FirstOrDefault();
            }
            else
            {
                // Base-skill and mastery nodes are not shrine-row aliases and
                // must retain the exact planned talent ID.
                talentById.TryGetValue(targetEntry.Key, out actualTalent);
            }
            if (actualTalent is null)
            {
                var skillId = ReadNullableInt(plannedDefinition, "skillId") ?? 0;
                var skillRow = skillId > 0 ? InvokeStatic("TableData", "getTSkillData", skillId) : null;
                var name = FirstNonEmpty(Clean(ReadString(skillRow, "name") ?? EnglishName(skillRow, string.Empty) ?? string.Empty), "talent");
                levelFailures.Add($"missing {name}#{(skillId > 0 ? skillId : targetEntry.Key)} talent={targetEntry.Key} saved=?/{targetEntry.Value} effective=? cap=? plan={remembered.PlanToken}");
                continue;
            }
            var actualTalentId = ReadNullableInt(Read(actualTalent, "tTalentData"), "id") ?? 0;
            if (!resolvedTargets.TryAdd(actualTalentId, (actualTalent, targetEntry.Value)))
            {
                levelFailures.Add(DescribeTalentLevel(actualTalent, targetEntry.Value, "duplicate target "));
                continue;
            }
            var cap = GetTalentLevelCap(actualTalent);
            var expectedEffective = GetExpectedTalentEffectiveLevel(actualTalent, targetEntry.Value);
            if (GetSavedTalentLevel(actualTalent) != targetEntry.Value
                || !IsExpectedTalentEffectiveLevel(actualTalent, targetEntry.Value, GetTalentLevel(actualTalent)))
                levelFailures.Add(DescribeTalentLevel(actualTalent, targetEntry.Value));
        }

        // ResetTalentPoint clears every ordinary resettable node. Verify that no
        // stale point survived outside the exact deterministic target. Fixed and
        // alien nodes are intentionally excluded because the native reset keeps
        // them outside the spendable ledger.
        foreach (var talent in talentById.Values
                     .Where(IsNormalTalentNode)
                     // Every native base-skill row retains its materialized
                     // level-one save state; baseSkillId selects which one is
                     // active. Only the selected base row belongs to the paid
                     // target vector, so inactive base rows are not stale spend.
                     .Where(talent => !IsBaseSkillDefinition(Read(talent, "tTalentData")))
                     .Where(talent => !IsTalentUnreplaceable(talent)))
        {
            var talentId = ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0;
            if (resolvedTargets.ContainsKey(talentId) || GetSavedTalentLevel(talent) == 0) continue;
            levelFailures.Add(DescribeTalentLevel(talent, 0, "unexpected point "));
        }
        if (levelFailures.Count > 0)
        {
            failure = $"joint target levels differ: {string.Join("; ", levelFailures)}";
            return false;
        }
        var variants = VerifyEquippedSkillVariants(
            hero, talentData, "AUTO-BUILD", expectedPackageSkills);
        if (!variants.IsExact)
        {
            failure = $"gear skill variants differ (-{string.Join(',', variants.Missing)} +{string.Join(',', variants.Unexpected)})";
            return false;
        }
        var gearEffects = VerifyCommittedGearEffects(
            hero,
            talentData,
            abilityBaseline,
            "AUTO-BUILD FINAL",
            verifyStableNonGearAbilities: false);
        if (!gearEffects.IsVerified)
        {
            failure = "gear, set, or Unique effects differ after the skill plan was committed"
                      + $" (abilities -{string.Join(',', gearEffects.MissingAbilities)} +{string.Join(',', gearEffects.UnexpectedAbilities)}"
                      + $"; extra talents -{string.Join(',', gearEffects.MissingExtraTalents)} +{string.Join(',', gearEffects.UnexpectedExtraTalents)}"
                      + $"; set effects -{string.Join(',', gearEffects.MissingSetEffects)} +{string.Join(',', gearEffects.UnexpectedSetEffects)})";
            return false;
        }
        failure = string.Empty;
        return true;
    }

    public static bool TryOptimizeSelectedHeroSkills(out string message)
    {
        // The skill transaction performs thousands of short IL2CPP reads and
        // writes. Running each one as a separate gateway item costs roughly one
        // rendered frame per call and made a healthy build look frozen for tens
        // of seconds. Execute the complete, already-bounded skill transaction in
        // one main-thread item; nested gateway calls then run directly. This is
        // also the transaction's natural atomic boundary: gameplay is paused and
        // rollback is captured before the first destructive write.
        if (!MainThreadNativeGateway.IsMainThread)
        {
            ReportAutoBuildProgress(
                AutoBuildStep.ApplyingSkills,
                detail: UiText.L(
                    "스킬 계획 사전 검증",
                    "Validating the skill plan",
                    "验证技能方案",
                    "驗證技能方案"));
            var mainThreadOutcome = MainThreadNativeGateway.Invoke(() =>
            {
                var succeeded = TryOptimizeSelectedHeroSkills(out var nestedMessage);
                return (Succeeded: succeeded, Message: nestedMessage);
            });
            message = mainThreadOutcome.Message;
            return mainThreadOutcome.Succeeded;
        }

        JointSkillRollbackSnapshot rollbackSnapshot;
        try
        {
            rollbackSnapshot = CaptureJointSkillRollbackSnapshot();
        }
        catch (Exception error)
        {
            message = UiText.L(
                $"스킬 자동 빌드의 안전 복구 지점을 만들지 못했습니다. 스킬을 변경하지 않았습니다: {error.GetBaseException().Message}",
                $"Could not capture a safe Auto Skills rollback point. Skills were not changed: {error.GetBaseException().Message}",
                $"无法创建自动技能的安全回滚点。未更改技能：{error.GetBaseException().Message}",
                $"無法建立自動技能的安全復原點。未變更技能：{error.GetBaseException().Message}");
            return false;
        }

        var succeeded = TryOptimizeSkillsWithBloodLedger(
            false, rollbackSnapshot, out var skillMessage);
        if (succeeded)
        {
            message = skillMessage;
            return true;
        }

        var rollbackCommit = new PendingGearCommit(
            rollbackSnapshot.Hero,
            rollbackSnapshot.HeroKey,
            rollbackSnapshot.GearFingerprint,
            new List<MoveReceipt>(),
            null,
            new List<object>(),
            null);
        var rollback = RollbackJointBuild(rollbackCommit, rollbackSnapshot);
        message = UiText.L(
            $"스킬 자동 빌드 미완료 · {skillMessage}",
            $"Auto Skills incomplete · {skillMessage}",
            $"自动技能未完成 · {skillMessage}",
            $"自動技能未完成 · {skillMessage}")
            + DescribeJointRollback(rollback);
        return false;
    }

    private static bool IsStandaloneSkillSnapshotCurrent(JointSkillRollbackSnapshot snapshot)
    {
        var selectedHero = GetSelectedHero();
        return selectedHero is not null
               && NativeEquals(selectedHero, snapshot.Hero)
               && string.Equals(GetJointSkillPlanHeroKey(selectedHero), snapshot.HeroKey, StringComparison.Ordinal)
               && NativeEquals(Read(selectedHero, "saveHeroData"), snapshot.SaveHero)
               && NativeEquals(Read(selectedHero, "heroTalentData"), snapshot.TalentData)
               && string.Equals(GetCurrentGearFingerprint(selectedHero), snapshot.GearFingerprint, StringComparison.Ordinal)
               && string.Equals(GetSkillStateFingerprint(selectedHero), GetSkillStateFingerprint(snapshot), StringComparison.Ordinal);
    }

    private static bool TryOptimizeSkillsWithBloodLedger(
        bool requireRememberedJointPlan,
        JointSkillRollbackSnapshot snapshot,
        out string message)
    {
        // Skill mutations already execute synchronously on Unity's main thread.
        // Measure their debit inside that same callback, not across planning or
        // rollback frames during which unrelated battles can award currency.
        try
        {
            var outcome = MainThreadNativeGateway.Invoke(() =>
            {
                var before = Convert.ToInt32(
                    InvokeRequiredInstance(snapshot.TownData, "GetRes", snapshot.BloodType)
                    ?? throw new InvalidOperationException("Blood amount is unavailable before skill application."),
                    CultureInfo.InvariantCulture);
                snapshot.BloodAccountingVerified = false;
                try
                {
                    var success = TryOptimizeSelectedHeroSkills(requireRememberedJointPlan, out var detail);
                    return (Success: success, Message: detail);
                }
                finally
                {
                    var after = Convert.ToInt32(
                        InvokeRequiredInstance(snapshot.TownData, "GetRes", snapshot.BloodType)
                        ?? throw new InvalidOperationException("Blood amount is unavailable after skill application."),
                        CultureInfo.InvariantCulture);
                    snapshot.ConsumedBlood = checked(snapshot.ConsumedBlood + Math.Max(0, before - after));
                    snapshot.BloodAccountingVerified = true;
                }
            });
            message = outcome.Message;
            return outcome.Success;
        }
        catch (Exception error)
        {
            // Return through the caller's rollback path even if accounting or
            // the gateway itself fails; never strand already-applied equipment.
            message = $"Skill transaction accounting failed: {error.GetBaseException().Message}";
            return false;
        }
    }

    private static bool TryOptimizeSelectedHeroSkills(
        bool requireRememberedJointPlan,
        out string message)
    {
        if (!MainThreadNativeGateway.IsMainThread)
        {
            ReportAutoBuildProgress(
                AutoBuildStep.ApplyingSkills,
                detail: UiText.L(
                    "선택한 스킬 계획 적용",
                    "Applying the selected skill plan",
                    "应用所选技能方案",
                    "套用所選技能方案"));
            var mainThreadOutcome = MainThreadNativeGateway.Invoke(() =>
            {
                var succeeded = TryOptimizeSelectedHeroSkills(
                    requireRememberedJointPlan, out var nestedMessage);
                return (Succeeded: succeeded, Message: nestedMessage);
            });
            message = mainThreadOutcome.Message;
            return mainThreadOutcome.Succeeded;
        }

        var journalTransformAttempts = 0;
        var journalTransformBlood = 0;
        var journalResetInvoked = false;
        var journalResetSucceeded = false;
        var journalResetPrice = 0;
        var journalBaseChanged = false;
        var journalAllocationStart = -1;
        object? journalSaveHero = null;
        try
        {
            var hero = GetSelectedHeroAfterAutoBuildWait();
            if (hero is null)
            {
                message = UiText.L("선택된 영웅이 없습니다.", "No hero is selected.", "未选择英雄。", "未選擇英雄。");
                return false;
            }
            var talentData = Read(hero, "heroTalentData");
            var saveHero = Read(hero, "saveHeroData");
            journalSaveHero = saveHero;
            var dataManager = ReadStatic("Game", "dataMgr");
            var seasonData = Read(dataManager, "nowSeasonData");
            var townData = Read(seasonData, "townData");
            if (talentData is null || saveHero is null || townData is null) throw new InvalidOperationException("Talent data is unavailable.");
            var skillGearFingerprint = GetCurrentGearFingerprint(hero);
            var originalSkillFingerprint = GetSkillStateFingerprint(hero);

            // Only the native talent grid spends normal talent points. Inspired,
            // alien and runeword entries in extraTalentList have separate rules.
            var talents = ReadValues(Read(talentData, "talentDic"))
                .DistinctBy(value => NativeObjectKey(value, value)).ToList();
            if (talents.Count == 0)
            {
                message = UiText.L("현재 영웅의 스킬·특성 표를 찾지 못했습니다.", "The selected hero's skill grid is unavailable.", "找不到当前英雄的技能天赋表。", "找不到目前英雄的技能天賦表。");
                return false;
            }

            // Resolve the build before resetting. Resetting removes the active
            // skill evidence that Auto uses to identify the intended archetype.
            var focus = ResolveHeroFocus(hero, GetHeroBuildTheme(hero));
            var spentBefore = GetResettableTalentPointCount(talentData, talents);
            var totalTalentPoints = PreviewExactTalentPointBudget(talentData, saveHero, talents, spentBefore);
            PreferredTalentPlan preferred;
            RememberedJointSkillPlan? requiredJointPlan = null;
            if (requireRememberedJointPlan)
            {
                var planKey = GetJointSkillPlanHeroKey(hero);
                if (!JointSkillPlansByHero.TryGetValue(planKey, out requiredJointPlan))
                    throw new InvalidOperationException("The gear step did not leave an exact joint skill plan.");
                if (!string.Equals(requiredJointPlan.FocusKey, focus.Key, StringComparison.Ordinal))
                    throw new InvalidOperationException(
                        $"The remembered joint focus changed ({requiredJointPlan.FocusKey}/{focus.Key}).");
                if (!string.Equals(requiredJointPlan.GearFingerprint, GetCurrentGearFingerprint(hero), StringComparison.Ordinal))
                    throw new InvalidOperationException("The equipped items changed after the joint gear plan was committed.");
                var currentGrantedSkillLevels = GetCurrentGrantedSkillLevels(hero);
                if (currentGrantedSkillLevels.Count != requiredJointPlan.GrantedSkillLevels.Count
                    || requiredJointPlan.GrantedSkillLevels.Any(entry =>
                        currentGrantedSkillLevels.GetValueOrDefault(entry.Key) != entry.Value))
                    throw new InvalidOperationException(
                        "The equipment-granted skill package changed after the joint gear plan was committed.");
                if (string.IsNullOrWhiteSpace(requiredJointPlan.PlanToken))
                    throw new InvalidOperationException("The exact joint plan token is empty.");

                // Combined Auto Build must apply the immutable plan selected while
                // comparing gear. Re-evaluating here could overwrite plan A with
                // plan B and then verify only B, which would make a sequential
                // gear/skill result look joint even when the two optimizers drifted.
                preferred = new PreferredTalentPlan(
                    null, new List<int>(), new List<int>(), new HashSet<int>(),
                    UiText.L("장비 공동 계획", "Joint gear plan", "装备联合方案", "裝備聯合方案"));
                preferred = ApplyRememberedJointSkillPlan(hero, focus, preferred);
                if (!string.Equals(preferred.PlanToken, requiredJointPlan.PlanToken, StringComparison.Ordinal))
                    throw new InvalidOperationException("The remembered joint plan could not be materialized exactly.");
            }
            else
            {
                // Standalone Auto Skills has no preceding gear transaction. Build
                // a fresh joint plan from the equipment that is actually worn.
                preferred = GetPerformanceTalentPlan(hero, focus, totalTalentPoints);
                preferred = ApplyCurrentGearJointSkillPlan(hero, focus, preferred);
            }

            // Validate the computed performance plan before choosing the subset
            // that fits the hero's currently unlocked rows. Invalid rows must
            // not be silently discarded and reported as a successful plan.
            var invalidGuideSkillTalentIds = preferred.SkillTalentIds.Where(id =>
            {
                var definition = InvokeStatic("TableData", "getTTalentData", id);
                if (definition is null || (ReadNullableInt(definition, "type") ?? 0) != 1) return true;
                return (ReadNullableInt(definition, "skillId") ?? 0) <= 0;
            }).ToList();
            var invalidGuideMasteryTalentIds = preferred.MasteryTalentIds.Where(id =>
            {
                var definition = InvokeStatic("TableData", "getTTalentData", id);
                return definition is null || (ReadNullableInt(definition, "type") ?? 0) != 2
                       || (ReadNullableInt(definition, "masteryId") ?? 0) <= 0;
            }).ToList();
            if (invalidGuideSkillTalentIds.Count > 0 || invalidGuideMasteryTalentIds.Count > 0)
            {
                message = UiText.L(
                    $"성능 계획 데이터가 불완전합니다 · 스킬 {string.Join(',', invalidGuideSkillTalentIds)} · 마스터리 {string.Join(',', invalidGuideMasteryTalentIds)}. 초기화하지 않았습니다.",
                    $"The performance plan is incomplete · skills {string.Join(',', invalidGuideSkillTalentIds)} · masteries {string.Join(',', invalidGuideMasteryTalentIds)}. No reset was performed.",
                    $"性能方案数据不完整 · 技能 {string.Join(',', invalidGuideSkillTalentIds)} · 专精 {string.Join(',', invalidGuideMasteryTalentIds)}。未执行重置。",
                    $"效能方案資料不完整 · 技能 {string.Join(',', invalidGuideSkillTalentIds)} · 專精 {string.Join(',', invalidGuideMasteryTalentIds)}。未執行重設。");
                return false;
            }
            // A guide can list more active skills than the hero currently has
            // unlocked shrine rows. Pick the actual row-sized loadout before
            // washing; otherwise any arbitrary N matching skills make the wash
            // look complete and a build-defining skill can never be rolled.
            preferred = SelectPreferredActiveSkillTargets(hero, talentData, preferred, focus);
            if (requiredJointPlan is not null)
            {
                var selectedBaseSkillId = preferred.SkillTalentIds
                    .Select(id => InvokeStatic("TableData", "getTTalentData", id))
                    .Where(IsBaseSkillDefinition)
                    .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                    .FirstOrDefault(id => id > 0);
                var selectedJointActiveSkillIds = preferred.SkillTalentIds
                    .Select(id => InvokeStatic("TableData", "getTTalentData", id))
                    .Where(IsTransformableSkillDefinition)
                    .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                    .Where(id => id > 0).ToHashSet();
                if (selectedBaseSkillId != requiredJointPlan.BaseSkillId
                    || !selectedJointActiveSkillIds.SetEquals(requiredJointPlan.ActiveSkillIds)
                    || !string.Equals(preferred.PlanToken, requiredJointPlan.PlanToken, StringComparison.Ordinal))
                    throw new InvalidOperationException(
                        "The unlocked talent rows cannot materialize the exact gear-selected skill package.");
            }
            // ApplyCurrentGearJointSkillPlan already rebuilt masteries against the
            // exact committed gear, skill package and per-hero theme. Rebuilding
            // again on a gear-neutral AttrData would silently replace that joint
            // winner with a different mastery branch.
            var gridById = BuildTalentGridById(talents);
            if (gridById.Count == 0)
            {
                message = UiText.L("배분 가능한 스킬·특성이 없습니다.", "No skills or talents can receive points.", "没有可分配点数的技能或天赋。", "沒有可分配點數的技能或天賦。");
                return false;
            }
            var selectedActiveDefinitions = preferred.SkillTalentIds
                .Select(id => InvokeStatic("TableData", "getTTalentData", id))
                .Where(IsTransformableSkillDefinition).ToList();
            // A native joint package may legitimately be base-only. Do not force
            // every unlocked shrine row into the plan when all optional active
            // skills reduce the shared-time objective.
            var incompatibleSkillIds = selectedActiveDefinitions
                .Select(definition => ReadNullableInt(definition, "skillId") ?? 0)
                .Where(id => id > 0 && !IsSkillCompatibleWithEquippedWeapons(hero, id))
                .Distinct().ToList();
            var desiredBaseTalentForPreflight = preferred.SkillTalentIds
                .FirstOrDefault(id => IsBaseSkillDefinition(InvokeStatic("TableData", "getTTalentData", id)));
            if (desiredBaseTalentForPreflight > 0)
            {
                if (!gridById.ContainsKey(desiredBaseTalentForPreflight))
                {
                    message = UiText.L(
                        $"추천 기본 스킬 {desiredBaseTalentForPreflight}을 현재 특성표에서 찾지 못했습니다. 초기화하지 않았습니다.",
                        $"Recommended base skill {desiredBaseTalentForPreflight} is absent from the current talent grid. No reset was performed.",
                        $"当前天赋表中没有推荐基础技能 {desiredBaseTalentForPreflight}，未执行重置。",
                        $"目前天賦表中沒有推薦基礎技能 {desiredBaseTalentForPreflight}，未執行重設。");
                    return false;
                }
                var desiredBaseDefinitionForPreflight = InvokeStatic("TableData", "getTTalentData", desiredBaseTalentForPreflight);
                var desiredBaseSkillForPreflight = ReadNullableInt(desiredBaseDefinitionForPreflight, "skillId") ?? 0;
                if (desiredBaseSkillForPreflight > 0 && !IsSkillCompatibleWithEquippedWeapons(hero, desiredBaseSkillForPreflight))
                    incompatibleSkillIds.Add(desiredBaseSkillForPreflight);
            }
            incompatibleSkillIds = incompatibleSkillIds.Distinct().ToList();
            if (incompatibleSkillIds.Count > 0)
            {
                message = UiText.L(
                    $"현재 무기로 추천 스킬을 사용할 수 없습니다 ({string.Join(',', incompatibleSkillIds)}). 먼저 장비 자동 장착을 실행하세요. 초기화하지 않았습니다.",
                    $"The current weapons cannot use the recommended skills ({string.Join(',', incompatibleSkillIds)}). Run Auto Gear first. No reset was performed.",
                    $"当前武器无法使用推荐技能（{string.Join(',', incompatibleSkillIds)}）。请先运行自动装备，未执行重置。",
                    $"目前武器無法使用推薦技能（{string.Join(',', incompatibleSkillIds)}）。請先執行自動裝備，未執行重設。");
                return false;
            }

            var selectedActiveSkillIds = selectedActiveDefinitions
                .Select(definition => ReadNullableInt(definition, "skillId") ?? 0)
                .Where(id => id > 0).Distinct().ToHashSet();
            var currentUnlockedActiveSkillIds = GetTransformableTalents(talentData)
                .Where(talent => !IsTalentLockedRequired(talent))
                .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "skillId") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var missingBeforeTransform = selectedActiveSkillIds
                .Where(id => !currentUnlockedActiveSkillIds.Contains(id)).ToList();
            if (missingBeforeTransform.Count > 0
                && (!AutoTransformSkillsEnabled || AutoTransformAttemptLimit <= 0))
            {
                message = UiText.L(
                    $"추천 스킬 변환이 필요합니다 ({string.Join(',', missingBeforeTransform)}). 스킬 변환을 켜거나 직접 변환하세요. 초기화하지 않았습니다.",
                    $"Recommended skills require transformation ({string.Join(',', missingBeforeTransform)}). Enable skill transformation or transform them manually. No reset was performed.",
                    $"推荐技能需要转换（{string.Join(',', missingBeforeTransform)}）。请启用技能转换或手动转换，未执行重置。",
                    $"推薦技能需要轉換（{string.Join(',', missingBeforeTransform)}）。請啟用技能轉換或手動轉換，未執行重設。");
                return false;
            }

            var desiredGuideMasteryIds = preferred.MasteryTalentIds.Distinct().ToList();
            var missingGuideMasteryIds = desiredGuideMasteryIds.Where(id => !gridById.ContainsKey(id)).ToList();
            if (missingGuideMasteryIds.Count > 0)
            {
                message = UiText.L(
                    $"추천 마스터리 노드를 현재 특성표에서 찾지 못했습니다 ({string.Join(',', missingGuideMasteryIds)}). 변환·초기화하지 않았습니다.",
                    $"Guide mastery nodes are missing from the current talent grid ({string.Join(',', missingGuideMasteryIds)}). No transformation or reset was performed.",
                    $"当前天赋树中缺少推荐专精节点（{string.Join(',', missingGuideMasteryIds)}）。未执行转换或重置。",
                    $"目前天賦樹中缺少推薦專精節點（{string.Join(',', missingGuideMasteryIds)}）。未執行轉換或重設。");
                return false;
            }

            // The exact native point budget was previewed before the performance
            // plan, so mastery selection and the mutation preflight use the same
            // milestone-adjusted total.
            var preResetGuideMasteryIds = desiredGuideMasteryIds
                .Where(id => !IsTalentLockedRequired(gridById[id]))
                .ToList();
            // Every selected active skill and mastery is part of the committed
            // plan. Reserve one real saved point for each before any destructive
            // reset; an effective/base bonus alone is not proof that the plan was
            // learned by this hero.
            var minimumRequiredPoints = selectedActiveSkillIds.Count + preResetGuideMasteryIds.Count;
            if (totalTalentPoints < minimumRequiredPoints)
            {
                message = UiText.L(
                    $"추천 스킬·마스터리 최소 배분 포인트가 부족합니다 · 필요 {minimumRequiredPoints:N0} / 보유 {totalTalentPoints:N0}. 변환·초기화하지 않았습니다.",
                    $"Not enough talent points for the minimum guide package · need {minimumRequiredPoints:N0} / have {totalTalentPoints:N0}. No transformation or reset was performed.",
                    $"推荐技能与专精的最低分配点数不足 · 需要 {minimumRequiredPoints:N0} / 拥有 {totalTalentPoints:N0}。未执行转换或重置。",
                    $"推薦技能與專精的最低分配點數不足 · 需要 {minimumRequiredPoints:N0} / 擁有 {totalTalentPoints:N0}。未執行轉換或重設。");
                return false;
            }

            var resetPrice = Convert.ToInt32(InvokeRequiredInstance(talentData, "GetResetTalentPrice") ?? throw new InvalidOperationException("Talent reset price is unavailable."), CultureInfo.InvariantCulture);
            journalResetPrice = resetPrice;
            var bloodType = CreateEnum("EResType", 2) ?? throw new InvalidOperationException("Blood resource type is unavailable.");
            var bloodBefore = Convert.ToInt32(InvokeInstance(townData, "GetRes", bloodType) ?? 0, CultureInfo.InvariantCulture);
            if (spentBefore > 0 && bloodBefore < resetPrice)
            {
                message = UiText.L($"초기화 재화 부족 · 필요 피 {resetPrice:N0} / 보유 {bloodBefore:N0}", $"Not enough Blood to reset · need {resetPrice:N0} / have {bloodBefore:N0}", $"重置资源不足 · 需要鲜血 {resetPrice:N0} / 持有 {bloodBefore:N0}", $"重設資源不足 · 需要鮮血 {resetPrice:N0} / 持有 {bloodBefore:N0}");
                return false;
            }

            ReportAutoBuildProgress(
                AutoBuildStep.ApplyingSkills,
                detail: UiText.L(
                    "스킬 변환 준비",
                    "Preparing skill transformations",
                    "准备技能转换",
                    "準備技能轉換"));
            BeginLiveMutation(hero, skillGearFingerprint, originalSkillFingerprint);
            ReportAutoBuildProgress(
                AutoBuildStep.ApplyingSkills,
                detail: UiText.L(
                    "스킬 변환 준비",
                    "Preparing skill transformations",
                    "准备技能转换",
                    "準備技能轉換"));
            var transform = AutoTransformSkillsEnabled && AutoTransformAttemptLimit > 0
                ? TransformMissingPreferredSkills(hero, talentData, townData, preferred, spentBefore > 0 ? resetPrice : 0, AutoTransformAttemptLimit)
                : new SkillTransformResult(0, 0, 0, 0, string.Empty, true);
            journalTransformAttempts = transform.Attempts;
            journalTransformBlood = transform.SpentBlood;
            var transformBloodText = transform.SpentBlood >= 0
                ? transform.SpentBlood.ToString("N0", CultureInfo.CurrentCulture)
                : UiText.L("확인 불가", "unknown", "未知", "未知");
            talents = ReadValues(Read(talentData, "talentDic"))
                .DistinctBy(value => NativeObjectKey(value, value)).ToList();
            if (!transform.ExecutionSucceeded)
            {
                Plugin.DiagWarning($"AUTO-SKILLS TRANSFORM ERROR|attempts={transform.Attempts}|matched={transform.Matched}|target={transform.Target}|spentBlood={transform.SpentBlood}|cleanup={transform.CleanupSucceeded}|reason={transform.Note}");
                message = UiText.L(
                    $"스킬 변환 중 오류가 발생해 특성 초기화를 중단했습니다 · 성공 변환 {transform.Attempts}회 · 변환 피 {transformBloodText} · 현재 스킬 행은 이미 바뀌었을 수 있습니다{(string.IsNullOrWhiteSpace(transform.Note) ? string.Empty : $" · {transform.Note}")}",
                    $"Talent reset was stopped after a skill-transformation error · {transform.Attempts} successful transform(s) · transform Blood {transformBloodText} · current skill rows may already have changed{(string.IsNullOrWhiteSpace(transform.Note) ? string.Empty : $" · {transform.Note}")}",
                    $"技能转换出错，已停止天赋重置 · 成功转换 {transform.Attempts} 次 · 转换鲜血 {transformBloodText} · 当前技能行可能已发生变化{(string.IsNullOrWhiteSpace(transform.Note) ? string.Empty : $" · {transform.Note}")}",
                    $"技能轉換發生錯誤，已停止天賦重設 · 成功轉換 {transform.Attempts} 次 · 轉換鮮血 {transformBloodText} · 目前技能列可能已變更{(string.IsNullOrWhiteSpace(transform.Note) ? string.Empty : $" · {transform.Note}")}");
                return false;
            }
            if (AutoTransformSkillsEnabled && transform.Target > 0 && transform.Matched < transform.Target)
            {
                Plugin.DiagWarning($"AUTO-SKILLS TRANSFORM INCOMPLETE|attempts={transform.Attempts}|matched={transform.Matched}|target={transform.Target}|spentBlood={transform.SpentBlood}|reason={transform.Note}");
                message = UiText.L(
                    $"추천 스킬 변환이 완료되지 않아 특성 초기화를 중단했습니다 · {transform.Matched}/{transform.Target} · 변환 피 {transform.SpentBlood:N0}{(string.IsNullOrWhiteSpace(transform.Note) ? string.Empty : $" · {transform.Note}")}",
                    $"Talent reset was stopped because skill transformation was incomplete · {transform.Matched}/{transform.Target} · transform Blood {transform.SpentBlood:N0}{(string.IsNullOrWhiteSpace(transform.Note) ? string.Empty : $" · {transform.Note}")}",
                    $"技能转换未完成，已停止天赋重置 · {transform.Matched}/{transform.Target} · 转换鲜血 {transform.SpentBlood:N0}{(string.IsNullOrWhiteSpace(transform.Note) ? string.Empty : $" · {transform.Note}")}",
                    $"技能轉換未完成，已停止天賦重設 · {transform.Matched}/{transform.Target} · 轉換鮮血 {transform.SpentBlood:N0}{(string.IsNullOrWhiteSpace(transform.Note) ? string.Empty : $" · {transform.Note}")}");
                return false;
            }
            if (!transform.CleanupSucceeded)
            {
                message = UiText.L(
                    $"스킬 변환 임시 설정을 완전히 복구하지 못해 특성 초기화를 중단했습니다 · 성공 변환 {transform.Attempts}회 · 변환 피 {transformBloodText} · 현재 스킬 행은 이미 바뀌었을 수 있습니다.",
                    $"Talent reset was stopped because temporary transformation settings were not restored · {transform.Attempts} successful transform(s) · transform Blood {transformBloodText} · current skill rows may already have changed.",
                    $"未能完整恢复技能转换临时设置，已停止天赋重置 · 成功转换 {transform.Attempts} 次 · 转换鲜血 {transformBloodText} · 当前技能行可能已发生变化。",
                    $"未能完整復原技能轉換暫存設定，已停止天賦重設 · 成功轉換 {transform.Attempts} 次 · 轉換鮮血 {transformBloodText} · 目前技能列可能已變更。");
                return false;
            }

            // Transformation changes the active rows. Resolve the real post-wash
            // nodes and ensure each required node can accept at least one saved
            // point before consuming the reset cost.
            gridById = BuildTalentGridById(talents);
            var postTransformActive = ResolvePreferredActiveSkills(preferred, gridById);
            var postTransformActiveSkillIds = postTransformActive
                .Select(entry => entry.SkillId).Where(id => id > 0).ToHashSet();
            var unresolvedAfterTransform = selectedActiveSkillIds
                .Where(id => !postTransformActiveSkillIds.Contains(id)).ToList();
            var postTransformMasteryIds = preResetGuideMasteryIds
                .Where(gridById.ContainsKey)
                .Where(id => !IsTalentLockedRequired(gridById[id]))
                .ToList();
            var noPointCapacityIds = postTransformActive.Select(entry => entry.Talent)
                .Concat(postTransformMasteryIds.Select(id => gridById[id]))
                .Where(talent => GetTalentLevelCap(talent) - GetTalentBaseLevelRequired(talent) < 1)
                .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
                .Where(id => id > 0).Distinct().ToList();
            var transformPostconditionExact = postTransformActiveSkillIds.SetEquals(selectedActiveSkillIds)
                                              && (transform.Target <= 0
                                                  || (transform.Matched == postTransformActiveSkillIds.Count
                                                      && transform.Target == selectedActiveSkillIds.Count));
            if (!transformPostconditionExact || postTransformMasteryIds.Count != preResetGuideMasteryIds.Count || noPointCapacityIds.Count > 0)
            {
                message = UiText.L(
                    $"추천 노드 사전 검증 실패 · 미확인 스킬 {string.Join(',', unresolvedAfterTransform)} · 포인트 불가 {string.Join(',', noPointCapacityIds)}. 특성 초기화하지 않았습니다. 변환 피 {transform.SpentBlood:N0}",
                    $"Guide-node preflight failed · unresolved skills {string.Join(',', unresolvedAfterTransform)} · cannot receive points {string.Join(',', noPointCapacityIds)}. Talent reset was not performed. Transform Blood {transform.SpentBlood:N0}",
                    $"推荐节点预检失败 · 未确认技能 {string.Join(',', unresolvedAfterTransform)} · 无法加点 {string.Join(',', noPointCapacityIds)}。未重置天赋。转换鲜血 {transform.SpentBlood:N0}",
                    $"推薦節點預檢失敗 · 未確認技能 {string.Join(',', unresolvedAfterTransform)} · 無法加點 {string.Join(',', noPointCapacityIds)}。未重設天賦。轉換鮮血 {transform.SpentBlood:N0}");
                return false;
            }

            journalResetInvoked = spentBefore > 0;
            ReportAutoBuildProgress(
                AutoBuildStep.ApplyingSkills,
                detail: UiText.L(
                    "특성 초기화",
                    "Resetting talents",
                    "重置天赋",
                    "重設天賦"));
            var resetResult = journalResetInvoked
                ? Convert.ToInt32(InvokeRequiredInstance(talentData, "ResetTalentPoint") ?? 1, CultureInfo.InvariantCulture)
                : 0;
            if (resetResult != 0)
            {
                message = UiText.L($"특성 초기화 실패 · 필요 피 {resetPrice:N0} / 보유 {bloodBefore:N0}", $"Talent reset failed · need {resetPrice:N0} Blood / have {bloodBefore:N0}", $"天赋重置失败 · 需要鲜血 {resetPrice:N0} / 持有 {bloodBefore:N0}", $"天賦重設失敗 · 需要鮮血 {resetPrice:N0} / 持有 {bloodBefore:N0}")
                          + DescribeSkillMutationJournal(journalTransformAttempts, journalTransformBlood, journalResetInvoked, false, journalResetPrice, false, -1, journalSaveHero);
                return false;
            }
            journalResetSucceeded = journalResetInvoked;
            var remainAfterReset = ReadNullableInt(saveHero, "talentRemainPoint") ?? 0;
            journalAllocationStart = remainAfterReset;
            talents = ReadValues(Read(talentData, "talentDic"))
                .DistinctBy(value => NativeObjectKey(value, value)).ToList();
            gridById = BuildTalentGridById(talents);
            var spentAfter = GetResettableTalentPointCount(talentData, talents);
            if (spentBefore > 0 && spentAfter != 0)
            {
                message = UiText.L("초기화 함수는 성공을 반환했지만 일부 포인트가 남았습니다.", "The reset function returned success, but invested points remain.", "重置函数返回成功，但仍有已投入点数。", "重設函式回傳成功，但仍有已投入點數。")
                          + DescribeSkillMutationJournal(journalTransformAttempts, journalTransformBlood, journalResetInvoked, journalResetSucceeded, journalResetPrice, journalBaseChanged, journalAllocationStart, journalSaveHero);
                return false;
            }
            // Native ResetTalentPoint recalculates blessTalentPoint from the
            // current milestone state, then SaveHeroData.ResetTalentPoint sets
            // talentRemainPoint to GetTotalTalentPoint().  The old
            // remainBefore + spentBefore check could therefore reject a valid
            // reset after it had already consumed Blood.  Verify against the
            // same native total that the reset itself uses.
            var expectedRemainAfterReset = Convert.ToInt32(
                InvokeRequiredInstance(saveHero, "GetTotalTalentPoint")
                ?? throw new InvalidOperationException("The native total talent point value is unavailable."),
                CultureInfo.InvariantCulture);
            if (remainAfterReset != expectedRemainAfterReset)
            {
                message = UiText.L(
                    $"특성 초기화 포인트 검증 실패 · 예상 {expectedRemainAfterReset:N0} / 실제 {remainAfterReset:N0}",
                    $"Talent reset point verification failed · expected {expectedRemainAfterReset:N0} / actual {remainAfterReset:N0}",
                    $"天赋重置点数验证失败 · 预期 {expectedRemainAfterReset:N0} / 实际 {remainAfterReset:N0}",
                    $"天賦重設點數驗證失敗 · 預期 {expectedRemainAfterReset:N0} / 實際 {remainAfterReset:N0}")
                          + DescribeSkillMutationJournal(journalTransformAttempts, journalTransformBlood, journalResetInvoked, journalResetSucceeded, journalResetPrice, journalBaseChanged, journalAllocationStart, journalSaveHero);
                return false;
            }

            var baseSkillChanged = ApplyPreferredBaseSkill(talentData, saveHero, preferred, out var baseSkillName);
            journalBaseChanged = baseSkillChanged;
            talents = ReadValues(Read(talentData, "talentDic"))
                .DistinctBy(value => NativeObjectKey(value, value)).ToList();
            gridById = BuildTalentGridById(talents);

            var beforeAllocation = remainAfterReset;
            var allocatedByPlan = 0;
            ReportAutoBuildProgress(
                AutoBuildStep.ApplyingSkills,
                0,
                Math.Max(0, beforeAllocation),
                UiText.L(
                    "특성 포인트 배분",
                    "Allocating talent points",
                    "分配天赋点",
                    "分配天賦點"));
            var failedNodes = new HashSet<int>();
            var previewFailedNodes = new HashSet<int>();
            var desiredActiveSkillIds = preferred.SkillTalentIds
                .Select(id => InvokeStatic("TableData", "getTTalentData", id))
                .Where(IsTransformableSkillDefinition)
                .Select(definition => ReadNullableInt(definition, "skillId") ?? 0)
                .Where(id => id > 0).Distinct().ToList();
            var activeSkills = ResolvePreferredActiveSkills(preferred, gridById);
            var activeSkillTalentIds = activeSkills.Select(entry => entry.TalentId).ToList();
            var availableActiveSkillIds = activeSkills.Select(entry => entry.SkillId).ToHashSet();
            var availableBaseSkillTalentIds = preferred.SkillTalentIds
                .Where(id => IsBaseSkillDefinition(InvokeStatic("TableData", "getTTalentData", id)))
                .Where(gridById.ContainsKey).ToList();
            var availableBaseSkillIds = availableBaseSkillTalentIds
                .Select(id => ReadNullableInt(InvokeStatic("TableData", "getTTalentData", id), "skillId") ?? 0)
                .Where(id => id > 0);
            var availablePreferredSkillIds = availableActiveSkillIds.Concat(availableBaseSkillIds).ToHashSet();
            var unresolvedPreferredSkillIds = desiredActiveSkillIds.Where(id => !availableActiveSkillIds.Contains(id)).ToList();
            LogPreferredActiveSkillState("RESOLVED", activeSkills, unresolvedPreferredSkillIds);
            var relevantMasteryTalentIds = preferred.MasteryTalentIds
                .Where(id => (ReadNullableInt(InvokeStatic("TableData", "getTTalentData", id), "type") ?? 0) == 2)
                .Where(gridById.ContainsKey)
                .Where(id => !IsTalentLockedRequired(gridById[id]))
                .ToList();
            var effectivePreferred = preferred with
            {
                SkillTalentIds = availableBaseSkillTalentIds.Concat(activeSkillTalentIds).Distinct().ToList(),
                MasteryTalentIds = relevantMasteryTalentIds,
                PreferredSkillIds = availablePreferredSkillIds
            };

            // Snapshot every saved/effective level after reset and base-skill
            // selection. Each successful native AddTalentPoint call advances this
            // ledger; the final state must match it node-for-node.
            var expectedSavedLevels = gridById.ToDictionary(
                entry => entry.Key, entry => GetSavedTalentLevel(entry.Value));
            void RecordExpectedSpend(int talentId, int spent)
            {
                if (spent <= 0) return;
                if (!expectedSavedLevels.TryGetValue(talentId, out var before))
                    throw new InvalidOperationException($"Allocated talent {talentId} is absent from the post-reset ledger.");
                expectedSavedLevels[talentId] = checked(before + spent);
            }

            var requiredTalentIds = activeSkillTalentIds
                .Concat(relevantMasteryTalentIds).Distinct().ToList();
            var exactTargetLevels = new Dictionary<int, int>();
            var exactRedistributedPoints = 0;
            var rawTargetLevels = effectivePreferred.TargetSavedLevels;
            if (rawTargetLevels is not null)
            {
                foreach (var talentId in availableBaseSkillTalentIds.Concat(relevantMasteryTalentIds).Distinct())
                    if (gridById.ContainsKey(talentId) && rawTargetLevels.TryGetValue(talentId, out var target))
                        exactTargetLevels[talentId] = target;
                // Shrine transformation can materialize the requested skill in
                // a position-specific TTalent row with a different talent ID.
                // The shared plan is keyed by its guide row before washing, so
                // transfer that exact saved-level target to the resolved native
                // row by the already-verified skill identity.
                foreach (var active in activeSkills)
                {
                    if (rawTargetLevels.TryGetValue(active.TalentId, out var target)
                        || rawTargetLevels.TryGetValue(active.GuideTalentId, out target))
                        exactTargetLevels[active.TalentId] = target;
                }
            }
            if (exactTargetLevels.Count > 0)
            {
                var missingRequiredTargets = requiredTalentIds.Where(id =>
                    !exactTargetLevels.TryGetValue(id, out var target) || target <= 0).ToList();
                if (missingRequiredTargets.Count > 0)
                    throw new InvalidOperationException(
                        $"The shared gear/skill plan has no learnable target for required talents {string.Join(',', missingRequiredTargets)}.");
                var availablePointTotal = ReadNullableInt(saveHero, "talentRemainPoint") ?? 0;
                // The selected base skill is materialized by ChangeBaseSkill with
                // one free saved level. Compare only the additional native point
                // calls still required from the post-change state; summing raw
                // targets would count that free level against the spendable pool.
                var materializedBaseTargets = availableBaseSkillTalentIds
                    .Where(exactTargetLevels.ContainsKey)
                    .Select(id => exactTargetLevels[id])
                    .ToList();
                if (materializedBaseTargets.Count != 1 || materializedBaseTargets[0] < 1)
                    throw new InvalidOperationException(
                        "The shared gear/skill plan has no single materialized base-skill level.");
                var materializedTargetTotal = exactTargetLevels.Values.Sum();
                var plannedPaidPointTotal = checked(materializedTargetTotal - 1);
                if (plannedPaidPointTotal != availablePointTotal)
                    throw new InvalidOperationException(
                        $"The shared gear/skill plan paid-point budget differs ({plannedPaidPointTotal}/{availablePointTotal}; materialized {materializedTargetTotal}).");
                var requiredAdditionalPoints = exactTargetLevels.Sum(entry =>
                    Math.Max(0, entry.Value - GetSavedTalentLevel(gridById[entry.Key])));
                if (requiredAdditionalPoints > availablePointTotal)
                    throw new InvalidOperationException(
                        $"The shared gear/skill plan requires {requiredAdditionalPoints} additional points, but only {availablePointTotal} are available after reset.");

                foreach (var entry in exactTargetLevels.OrderBy(entry =>
                             ReadNullableInt(Read(gridById[entry.Key], "tTalentData"), "floor") ?? int.MaxValue)
                         .ThenBy(entry => entry.Key))
                {
                    var talent = gridById[entry.Key];
                    var cap = GetTalentLevelCap(talent);
                    var baseLevel = Math.Min(GetTalentBaseLevelRequired(talent), cap);
                    var maxSaved = Math.Max(0, cap - baseLevel);
                    if (entry.Value < 0 || entry.Value > maxSaved)
                        throw new InvalidOperationException(
                            $"Talent {entry.Key} target {entry.Value} exceeds native cap {cap} (base {baseLevel}).");
                    var currentSaved = GetSavedTalentLevel(talent);
                    var requested = entry.Value - currentSaved;
                    if (requested < 0)
                        throw new InvalidOperationException(
                            $"Talent {entry.Key} is already above the exact target ({currentSaved}/{entry.Value}).");
                    if (requested == 0) continue;
                    var targetSpent = 0;
                    var remainBeforeBulk = ReadNullableInt(saveHero, "talentRemainPoint") ?? 0;
                    var levelBeforeBulk = GetTalentLevel(talent);
                    // AddTalentPoint natively accepts a count. Apply the exact
                    // per-node target in one main-thread transaction and keep
                    // the same three-way postcondition used for one point.
                    // This removes one frame/gateway round trip per talent point.
                    if (requested > 1)
                    {
                        if (TrySpendTalentPoints(
                                talentData, saveHero, talent, requested, out var bulkSpent)
                            && bulkSpent > 0)
                        {
                            RecordExpectedSpend(entry.Key, bulkSpent);
                            allocatedByPlan += bulkSpent;
                            targetSpent += bulkSpent;
                        }
                        else
                        {
                            // A bulk request may be rejected even though a one-point
                            // request is legal. Fall back only when the rejected
                            // call proved that it changed absolutely no native state;
                            // any partial/inconsistent write must enter rollback.
                            var remainAfterBulk = ReadNullableInt(saveHero, "talentRemainPoint") ?? remainBeforeBulk;
                            var levelAfterBulk = GetTalentLevel(talent);
                            var savedAfterBulk = GetSavedTalentLevel(talent);
                            if (remainAfterBulk != remainBeforeBulk
                                || levelAfterBulk != levelBeforeBulk
                                || savedAfterBulk != currentSaved)
                                throw new InvalidOperationException(
                                    $"Talent {entry.Key} bulk write changed partial state without a verified result.");
                        }
                    }
                    while (targetSpent < requested)
                    {
                        // Only a proven no-op bulk rejection reaches this bounded
                        // one-point compatibility fallback.
                        if (!TrySpendTalentPoints(talentData, saveHero, talent, 1, out var spent)
                            || spent != 1)
                        {
                            failedNodes.Add(entry.Key);
                            break;
                        }
                        RecordExpectedSpend(entry.Key, spent);
                        allocatedByPlan += spent;
                        targetSpent += spent;
                    }
                    if (targetSpent > 0)
                        ReportAutoBuildProgress(
                            AutoBuildStep.ApplyingSkills,
                            Math.Min(beforeAllocation, allocatedByPlan),
                            Math.Max(0, beforeAllocation),
                            UiText.L("특성 포인트 배분", "Allocating talent points", "分配天赋点", "分配天賦點"));
                }

                // If one exact target is rejected, do not leave otherwise usable
                // points idle. Keep the fallback strictly inside the selected
                // joint plan/theme, rank feasible nodes by their live marginal
                // value when available, and still attempt a deterministic selected
                // node when preview scoring itself is unavailable. The original
                // targets remain unchanged so final verification reports the exact
                // deviation instead of disguising it as the planned vector.
                var exactPlanCandidateIds = effectivePreferred.SkillTalentIds
                    .Concat(effectivePreferred.MasteryTalentIds)
                    .Where(gridById.ContainsKey)
                    .Distinct().ToList();
                var redistributionGuard = 0;
                while ((ReadNullableInt(saveHero, "talentRemainPoint") ?? 0) > 0
                       && redistributionGuard++ < 2048)
                {
                    var eligible = exactPlanCandidateIds
                        .Where(id => !failedNodes.Contains(id))
                        .Select(id => gridById[id])
                        .Where(talent => CanAutoAllocateTalent(talent, hero, effectivePreferred))
                        .ToList();
                    if (eligible.Count == 0) break;

                    var ranked = eligible.Select(talent =>
                        {
                            var talentId = ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0;
                            try
                            {
                                return (Talent: talent, TalentId: talentId, Gain: ScoreTalentPointMarginalGain(
                                    hero, talentData, talent, focus, effectivePreferred));
                            }
                            catch
                            {
                                if (talentId > 0) previewFailedNodes.Add(talentId);
                                return (Talent: talent, TalentId: talentId, Gain: double.NegativeInfinity);
                            }
                        })
                        .OrderByDescending(entry => double.IsFinite(entry.Gain))
                        .ThenByDescending(entry => entry.Gain)
                        .ThenByDescending(entry =>
                            effectivePreferred.ObjectiveScores?.GetValueOrDefault(entry.TalentId)
                            ?? double.NegativeInfinity)
                        .ThenBy(entry => ReadNullableInt(Read(entry.Talent, "tTalentData"), "floor") ?? int.MaxValue)
                        .ThenBy(entry => entry.TalentId)
                        .ToList();
                    var bestFallback = ranked[0];
                    if (!TrySpendTalentPoints(talentData, saveHero, bestFallback.Talent, 1, out var spent)
                        || spent != 1)
                    {
                        if (bestFallback.TalentId > 0) failedNodes.Add(bestFallback.TalentId);
                        continue;
                    }

                    RecordExpectedSpend(bestFallback.TalentId, spent);
                    allocatedByPlan += spent;
                    exactRedistributedPoints += spent;
                    ReportAutoBuildProgress(
                        AutoBuildStep.ApplyingSkills,
                        Math.Min(beforeAllocation, allocatedByPlan),
                        Math.Max(0, beforeAllocation),
                        UiText.L("남은 특성 포인트 재분배", "Redistributing remaining talent points", "重新分配剩余天赋点", "重新分配剩餘天賦點"));
                }
            }
            else
            {
                // Compatibility fallback for a plan created before exact target
                // vectors were introduced. New joint plans always use the branch
                // above, so Auto Gear and Auto Skills cannot independently drift.
                foreach (var talentId in requiredTalentIds)
                {
                    if ((ReadNullableInt(saveHero, "talentRemainPoint") ?? 0) <= 0) break;
                    var talent = gridById[talentId];
                    if (GetSavedTalentLevel(talent) > 0) continue;
                    if (!TrySpendTalentPoints(talentData, saveHero, talent, 1, out var spent)) failedNodes.Add(talentId);
                    else RecordExpectedSpend(talentId, spent);
                    allocatedByPlan += spent;
                    ReportAutoBuildProgress(
                        AutoBuildStep.ApplyingSkills,
                        Math.Min(beforeAllocation, allocatedByPlan),
                        Math.Max(0, beforeAllocation),
                        UiText.L("특성 포인트 배분", "Allocating talent points", "分配天赋点", "分配天賦點"));
                }

                var marginalCandidateIds = availableBaseSkillTalentIds
                    .Concat(activeSkillTalentIds)
                    .Concat(relevantMasteryTalentIds)
                    .Where(gridById.ContainsKey)
                    .Distinct().ToList();
                var guard = 0;
                while ((ReadNullableInt(saveHero, "talentRemainPoint") ?? 0) > 0 && guard++ < 2048)
                {
                    var best = marginalCandidateIds
                        .Where(id => !failedNodes.Contains(id))
                        .Select(id => gridById[id])
                        .Where(talent => CanAutoAllocateTalent(talent, hero, effectivePreferred))
                        .Select(talent =>
                        {
                            try
                            {
                                return (Talent: talent, Gain: ScoreTalentPointMarginalGain(
                                    hero, talentData, talent, focus, effectivePreferred));
                            }
                            catch (Exception error)
                            {
                                var id = ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0;
                                if (id > 0) previewFailedNodes.Add(id);
                                Plugin.DiagDebug($"AUTO-SKILLS MARGINAL PREVIEW FAILED|talent={id}|{error.GetBaseException().Message}");
                                return (Talent: talent, Gain: double.NegativeInfinity);
                            }
                        })
                        .Where(entry => double.IsFinite(entry.Gain) && entry.Gain > 0.000001d)
                        .OrderByDescending(entry => entry.Gain)
                        .ThenBy(entry => ReadNullableInt(Read(entry.Talent, "tTalentData"), "floor") ?? int.MaxValue)
                        .ThenBy(entry => ReadNullableInt(Read(entry.Talent, "tTalentData"), "id") ?? int.MaxValue)
                        .Select(entry => entry.Talent)
                        .FirstOrDefault();
                    if (best is null) break;
                    var talentId = ReadNullableInt(Read(best, "tTalentData"), "id") ?? 0;
                    if (!TrySpendTalentPoints(talentData, saveHero, best, 1, out var spent))
                        failedNodes.Add(talentId);
                    else RecordExpectedSpend(talentId, spent);
                    allocatedByPlan += spent;
                    ReportAutoBuildProgress(
                        AutoBuildStep.ApplyingSkills,
                        Math.Min(beforeAllocation, allocatedByPlan),
                        Math.Max(0, beforeAllocation),
                        UiText.L("특성 포인트 배분", "Allocating talent points", "分配天赋点", "分配天賦點"));
                }

                // The objective loop above intentionally stops when every next
                // point has a zero/negative marginal gain. Auto allocation still
                // promises to spend every point that the native grid can accept,
                // so finish with the least-bad finite marginal target instead of
                // silently leaving points unused. Locked, capped, incompatible,
                // preview-failed, and native AddTalentPoint failures remain hard
                // constraints and are reported below.
                var completionGuard = 0;
                while ((ReadNullableInt(saveHero, "talentRemainPoint") ?? 0) > 0
                       && completionGuard++ < 2048)
                {
                    var bestCompletion = marginalCandidateIds
                        .Where(id => !failedNodes.Contains(id))
                        .Select(id => gridById[id])
                        .Where(talent => CanAutoAllocateTalent(talent, hero, effectivePreferred))
                        .Select(talent =>
                        {
                            try
                            {
                                return (Talent: talent, Gain: ScoreTalentPointMarginalGain(
                                    hero, talentData, talent, focus, effectivePreferred));
                            }
                            catch
                            {
                                var id = ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0;
                                if (id > 0) previewFailedNodes.Add(id);
                                return (Talent: talent, Gain: double.NegativeInfinity);
                            }
                        })
                        .Where(entry => double.IsFinite(entry.Gain))
                        .OrderByDescending(entry => entry.Gain)
                        .ThenBy(entry => ReadNullableInt(Read(entry.Talent, "tTalentData"), "floor") ?? int.MaxValue)
                        .ThenBy(entry => ReadNullableInt(Read(entry.Talent, "tTalentData"), "id") ?? int.MaxValue)
                        .Select(entry => entry.Talent)
                        .FirstOrDefault();
                    if (bestCompletion is null) break;
                    var talentId = ReadNullableInt(Read(bestCompletion, "tTalentData"), "id") ?? 0;
                    if (!TrySpendTalentPoints(talentData, saveHero, bestCompletion, 1, out var spent))
                        failedNodes.Add(talentId);
                    else
                        RecordExpectedSpend(talentId, spent);
                    allocatedByPlan += spent;
                    ReportAutoBuildProgress(
                        AutoBuildStep.ApplyingSkills,
                        Math.Min(beforeAllocation, allocatedByPlan),
                        Math.Max(0, beforeAllocation),
                        UiText.L("남은 특성 포인트 배분", "Allocating remaining talent points", "分配剩余天赋点", "分配剩餘天賦點"));
                }
            }

            // A native rebuild or an effective-level bonus must never make a
            // recommended skill look learned while its saved point remains zero.
            // Retry with any remaining point, then record exact state for support.
            foreach (var entry in activeSkills.Where(entry => GetSavedTalentLevel(entry.Talent) <= 0))
            {
                if ((ReadNullableInt(saveHero, "talentRemainPoint") ?? 0) <= 0) break;
                if (!TrySpendTalentPoints(talentData, saveHero, entry.Talent, 1, out var spent)) failedNodes.Add(entry.TalentId);
                else RecordExpectedSpend(entry.TalentId, spent);
                allocatedByPlan += spent;
                ReportAutoBuildProgress(
                    AutoBuildStep.ApplyingSkills,
                    Math.Min(beforeAllocation, allocatedByPlan),
                    Math.Max(0, beforeAllocation),
                    UiText.L("특성 포인트 배분", "Allocating talent points", "分配天赋点", "分配天賦點"));
            }
            var unlearnedPreferredSkillIds = activeSkills
                .Where(entry => GetSavedTalentLevel(entry.Talent) <= 0)
                .Select(entry => entry.SkillId).ToList();
            var missingPreferredSkillIds = unresolvedPreferredSkillIds
                .Concat(unlearnedPreferredSkillIds).Where(id => id > 0).Distinct().ToList();
            LogPreferredActiveSkillState("ALLOCATED", activeSkills, unresolvedPreferredSkillIds);
            if (unlearnedPreferredSkillIds.Count > 0)
                Plugin.DiagWarning($"AUTO-SKILLS ACTIVE UNLEARNED|skills={string.Join(',', unlearnedPreferredSkillIds)}|remaining={ReadNullableInt(saveHero, "talentRemainPoint") ?? 0}");

            var remaining = ReadNullableInt(saveHero, "talentRemainPoint") ?? 0;
            var allocated = Math.Max(0, beforeAllocation - remaining);
            var unspentPointConstraint = remaining > 0
                ? DescribeUnspentPointConstraint(
                    talents,
                    hero,
                    effectivePreferred,
                    failedNodes,
                    previewFailedNodes,
                    exactTargetLevels.Count > 0)
                : string.Empty;
            if (allocated <= 0 && beforeAllocation > 0)
            {
                message = UiText.L("초기화는 완료됐지만 현재 레벨에서 배분 가능한 특성이 없습니다.", "Reset completed, but no talent can receive points at the current level.", "重置已完成，但当前等级没有可分配的天赋。", "重設已完成，但目前等級沒有可分配的天賦。")
                          + DescribeSkillMutationJournal(journalTransformAttempts, journalTransformBlood, journalResetInvoked, journalResetSucceeded, journalResetPrice, journalBaseChanged, journalAllocationStart, journalSaveHero);
                return false;
            }

            ReportAutoBuildProgress(AutoBuildStep.Verifying);
            // Reapply, then read the complete saved/effective skill ledger from
            // one immutable post-allocation state on Unity's thread. Splitting
            // these checks into hundreds of gateway requests made verification
            // take many seconds even though the native work itself is bounded.
            var verificationState = MainThreadNativeGateway.Invoke(() =>
            {
                InvokeRequiredInstance(talentData, "ReapplySkillVariantsFromEquippedItems");
                var verifiedUsableSkillIds = ReadList(InvokeRequiredInstance(talentData, "GetSkillList"))
                    .Select(skill => ReadNullableInt(Read(skill, "tSkillData"), "id") ?? 0)
                    .Where(id => id > 0).ToHashSet();
                var verifiedLearnedActiveSkillIds = activeSkills
                    .Where(entry => GetSavedTalentLevel(entry.Talent) > 0)
                    .Select(entry => entry.SkillId).Where(id => id > 0).ToHashSet();
                var verifiedActiveExact = verifiedLearnedActiveSkillIds.SetEquals(desiredActiveSkillIds);
                var learnedButUnavailableSkillIds = activeSkills
                    .Where(entry => GetSavedTalentLevel(entry.Talent) > 0
                                    && !verifiedUsableSkillIds.Contains(entry.SkillId))
                    .Select(entry => entry.SkillId).Distinct().ToList();
                var verifiedMissingPreferred = missingPreferredSkillIds
                    .Concat(learnedButUnavailableSkillIds).Distinct().ToList();
                if (learnedButUnavailableSkillIds.Count > 0)
                    Plugin.DiagWarning($"AUTO-SKILLS ACTIVE UNAVAILABLE|skills={string.Join(',', learnedButUnavailableSkillIds)}");
                var verifiedHasUnusable = ReadBool(InvokeRequiredInstance(talentData, "IsHasUnusableSkill"));
                var verifiedVariants = VerifyEquippedSkillVariants(
                    hero, talentData, "AUTO-SKILLS", effectivePreferred.PreferredSkillIds);
                var verifiedDesiredBaseTalentId = preferred.SkillTalentIds
                    .FirstOrDefault(id => IsBaseSkillDefinition(InvokeStatic("TableData", "getTTalentData", id)));
                var verifiedActualBaseTalentId = ReadNullableInt(saveHero, "baseSkillId") ?? 0;
                var desiredBaseDefinition = verifiedDesiredBaseTalentId > 0
                    ? InvokeStatic("TableData", "getTTalentData", verifiedDesiredBaseTalentId)
                    : null;
                var verifiedDesiredBaseSkillId = ReadNullableInt(desiredBaseDefinition, "skillId") ?? 0;
                var actualBaseSkill = InvokeRequiredInstance(hero, "GetNowBaseSkillData");
                var verifiedActualBaseSkillId = ReadNullableInt(Read(actualBaseSkill, "tSkillData"), "id") ?? 0;
                var verifiedDesiredBaseSavedLevel = verifiedDesiredBaseTalentId > 0
                                                    && gridById.TryGetValue(
                                                        verifiedDesiredBaseTalentId,
                                                        out var desiredBaseTalent)
                    ? GetSavedTalentLevel(desiredBaseTalent)
                    : 0;
                var verifiedBaseSkill = verifiedDesiredBaseTalentId <= 0
                                        || (verifiedActualBaseTalentId == verifiedDesiredBaseTalentId
                                            && verifiedDesiredBaseSkillId > 0
                                            && verifiedActualBaseSkillId == verifiedDesiredBaseSkillId);
                if (!verifiedBaseSkill)
                    Plugin.DiagWarning($"AUTO-SKILLS BASE MISMATCH|talent={verifiedActualBaseTalentId}/{verifiedDesiredBaseTalentId}|skill={verifiedActualBaseSkillId}/{verifiedDesiredBaseSkillId}|savedLevel={verifiedDesiredBaseSavedLevel}");
                var verifiedUnlearnedMasteries = relevantMasteryTalentIds
                    .Where(id => gridById.TryGetValue(id, out var talent)
                                 && GetSavedTalentLevel(talent) <= 0)
                    .Distinct().ToList();
                if (verifiedUnlearnedMasteries.Count > 0)
                    Plugin.DiagWarning($"AUTO-SKILLS MASTERY UNLEARNED|talents={string.Join(',', verifiedUnlearnedMasteries)}|remaining={remaining}");
                var verifiedTalentMismatches = expectedSavedLevels.Select(entry =>
                    {
                        if (!gridById.TryGetValue(entry.Key, out var talent))
                            return $"{entry.Key}:missing";
                        var actualSaved = GetSavedTalentLevel(talent);
                        var expectedEffective = GetExpectedTalentEffectiveLevel(talent, entry.Value);
                        var actualEffective = GetTalentLevel(talent);
                        return actualSaved == entry.Value
                               && IsExpectedTalentEffectiveLevel(talent, entry.Value, actualEffective)
                            ? string.Empty
                            : $"{entry.Key}:{actualSaved}/{entry.Value}@{actualEffective}/{expectedEffective}";
                    })
                    .Where(value => value.Length > 0).ToList();
                if (verifiedTalentMismatches.Count > 0)
                    Plugin.DiagWarning($"AUTO-SKILLS LEVEL MISMATCH|{string.Join(',', verifiedTalentMismatches)}");
                var verifiedExactTargetMismatches = exactTargetLevels.Select(entry =>
                    {
                        if (!gridById.TryGetValue(entry.Key, out var talent)) return $"{entry.Key}:missing";
                        var actualSaved = GetSavedTalentLevel(talent);
                        return actualSaved == entry.Value ? string.Empty : $"{entry.Key}:{actualSaved}/{entry.Value}";
                    })
                    .Where(value => value.Length > 0).ToList();
                var verifiedSkillLevelStates = availableBaseSkillTalentIds.Concat(activeSkillTalentIds)
                    .Where(gridById.ContainsKey).Distinct()
                    .Select(talentId =>
                    {
                        var talent = gridById[talentId];
                        var definition = Read(talent, "tTalentData");
                        var skillId = ReadNullableInt(definition, "skillId") ?? 0;
                        var skillRow = skillId > 0 ? InvokeStatic("TableData", "getTSkillData", skillId) : null;
                        var name = Clean(ReadString(skillRow, "name")
                                         ?? EnglishName(skillRow, string.Empty)
                                         ?? $"skill#{skillId}");
                        return $"{name}#{skillId}:saved={GetSavedTalentLevel(talent)}/effective={GetTalentLevel(talent)}/cap={GetTalentLevelCap(talent)}";
                    }).ToList();
                var verifiedMasteryLevelStates = relevantMasteryTalentIds
                    .Where(gridById.ContainsKey).Distinct()
                    .Select(talentId =>
                    {
                        var talent = gridById[talentId];
                        var definition = Read(talent, "tTalentData");
                        var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
                        var masteryRow = masteryId > 0
                            ? InvokeStatic("TableData", "getTMasteryData", masteryId)
                            : null;
                        var name = FirstNonEmpty(
                            Clean(ReadString(masteryRow, "name")
                                  ?? EnglishName(masteryRow, string.Empty)
                                  ?? string.Empty),
                            Clean(ReadString(definition, "name")
                                  ?? EnglishName(definition, string.Empty)
                                  ?? string.Empty),
                            "mastery");
                        return $"{name}#{masteryId}:talent={talentId}/saved={GetSavedTalentLevel(talent)}/effective={GetTalentLevel(talent)}/cap={GetTalentLevelCap(talent)}";
                    }).ToList();
                if (verifiedExactTargetMismatches.Count > 0)
                    Plugin.DiagWarning($"AUTO-SKILLS TARGET LEVEL MISMATCH|plan={effectivePreferred.PlanToken}|{string.Join(',', verifiedExactTargetMismatches)}");
                var totalSpentBlood = Math.Max(0, bloodBefore - Convert.ToInt32(
                    InvokeRequiredInstance(townData, "GetRes", bloodType) ?? bloodBefore,
                    CultureInfo.InvariantCulture));
                var verifiedResetSpentBlood = Math.Max(0, totalSpentBlood - transform.SpentBlood);
                return new
                {
                    UsableSkillIds = verifiedUsableSkillIds,
                    LearnedActiveSkillIds = verifiedLearnedActiveSkillIds,
                    ActiveSkillPostconditionExact = verifiedActiveExact,
                    MissingPreferredSkillIds = verifiedMissingPreferred,
                    HasUnusableSkill = verifiedHasUnusable,
                    VariantVerification = verifiedVariants,
                    DesiredBaseTalentId = verifiedDesiredBaseTalentId,
                    ActualBaseTalentId = verifiedActualBaseTalentId,
                    DesiredBaseSkillId = verifiedDesiredBaseSkillId,
                    ActualBaseSkillId = verifiedActualBaseSkillId,
                    DesiredBaseSavedLevel = verifiedDesiredBaseSavedLevel,
                    BaseSkillVerified = verifiedBaseSkill,
                    UnlearnedMasteryTalentIds = verifiedUnlearnedMasteries,
                    TalentLevelMismatches = verifiedTalentMismatches,
                    ExactTargetMismatches = verifiedExactTargetMismatches,
                    SkillLevelStates = verifiedSkillLevelStates,
                    MasteryLevelStates = verifiedMasteryLevelStates,
                    ResetSpentBlood = verifiedResetSpentBlood
                };
            });
            var usableSkillIds = verificationState.UsableSkillIds;
            var learnedActiveSkillIds = verificationState.LearnedActiveSkillIds;
            var activeSkillPostconditionExact = verificationState.ActiveSkillPostconditionExact;
            missingPreferredSkillIds = verificationState.MissingPreferredSkillIds;
            var hasUnusableSkill = verificationState.HasUnusableSkill;
            var variantVerification = verificationState.VariantVerification;
            var variantSkillIds = variantVerification.Actual;
            var desiredBaseTalentId = verificationState.DesiredBaseTalentId;
            var actualBaseTalentId = verificationState.ActualBaseTalentId;
            var desiredBaseSkillId = verificationState.DesiredBaseSkillId;
            var actualBaseSkillId = verificationState.ActualBaseSkillId;
            var desiredBaseSavedLevel = verificationState.DesiredBaseSavedLevel;
            var baseSkillVerified = verificationState.BaseSkillVerified;
            var unlearnedMasteryTalentIds = verificationState.UnlearnedMasteryTalentIds;
            var talentLevelMismatches = verificationState.TalentLevelMismatches;
            var exactTargetMismatches = verificationState.ExactTargetMismatches;
            var skillLevelStates = verificationState.SkillLevelStates;
            var masteryLevelStates = verificationState.MasteryLevelStates;
            var transformComplete = transform.Matched >= transform.Target;
            // The action is advertised as automatic allocation, so any unspent
            // point makes the result partial—even if the only remaining native
            // targets are active skills deliberately excluded from this guide.
            // Do not report a focused subset as a fully completed allocation.
            var unspentPointsRemain = remaining > 0;
            var allocationLedgerExact = allocated == allocatedByPlan;
            var resetSpentBlood = verificationState.ResetSpentBlood;
            var resetBloodVerified = spentBefore > 0 ? resetSpentBlood == resetPrice : resetSpentBlood == 0;
            Plugin.DiagInfo($"AUTO-SKILLS PLAN|token={effectivePreferred.PlanToken}|focus={focus.English}|build={preferred.BuildName}|transform={transform.Attempts}:{transform.Matched}/{transform.Target}|transformNote={transform.Note}|baseSkillChanged={baseSkillChanged}:{baseSkillName}|baseTalent={actualBaseTalentId}/{desiredBaseTalentId}|baseSkill={actualBaseSkillId}/{desiredBaseSkillId}|baseSaved={desiredBaseSavedLevel}|skills={string.Join(';', skillLevelStates)}|masteries={string.Join(';', masteryLevelStates)}|learnedActive={string.Join(',', learnedActiveSkillIds.OrderBy(id => id))}|activeExact={activeSkillPostconditionExact}|usableSkills={string.Join(',', usableSkillIds.OrderBy(id => id))}|hasUnusableSkill={hasUnusableSkill}|variants={string.Join(',', variantSkillIds)}|variantExact={variantVerification.IsExact}|allocated={allocated}|planned={allocatedByPlan}|redistributed={exactRedistributedPoints}|ledgerExact={allocationLedgerExact}|levelMismatches={string.Join(',', talentLevelMismatches)}|targetMismatches={string.Join(',', exactTargetMismatches)}|remaining={remaining}|unspent={unspentPointsRemain}|resetBlood={resetSpentBlood}/{(spentBefore > 0 ? resetPrice : 0)}|unlearnedMasteries={string.Join(',', unlearnedMasteryTalentIds)}|failedNodes={string.Join(',', failedNodes)}");
            var transformKo = transform.Target > 0 ? $" · 스킬 변환{(transform.Matched < transform.Target ? " 일부" : string.Empty)} {transform.Attempts}회({transform.Matched}/{transform.Target})" : string.Empty;
            var transformEn = transform.Target > 0 ? $" · {(transform.Matched < transform.Target ? "partially " : string.Empty)}transformed {transform.Attempts}× ({transform.Matched}/{transform.Target})" : string.Empty;
            var transformZh = transform.Target > 0 ? $" · 技能{(transform.Matched < transform.Target ? "部分" : string.Empty)}转换 {transform.Attempts} 次（{transform.Matched}/{transform.Target}）" : string.Empty;
            var variantKo = variantVerification.Expected.Count > 0 || variantSkillIds.Count > 0 ? $" · 장비 변환형 {variantSkillIds.Count}/{variantVerification.Expected.Count} 확인" : string.Empty;
            var variantEn = variantVerification.Expected.Count > 0 || variantSkillIds.Count > 0 ? $" · gear variants verified {variantSkillIds.Count}/{variantVerification.Expected.Count}" : string.Empty;
            var variantZh = variantVerification.Expected.Count > 0 || variantSkillIds.Count > 0 ? $" · 装备变体验证 {variantSkillIds.Count}/{variantVerification.Expected.Count}" : string.Empty;
            var transformNote = LocalizeTransformNote(transform.Note);
            var transformNoteSuffix = string.IsNullOrWhiteSpace(transformNote) ? string.Empty : $" · {transformNote}";
            var incompleteKo = new List<string>();
            var incompleteEn = new List<string>();
            var incompleteZhCn = new List<string>();
            var incompleteZhTw = new List<string>();
            if (missingPreferredSkillIds.Count > 0)
            {
                incompleteKo.Add($"추천 액티브 미학습 {string.Join(',', missingPreferredSkillIds)}");
                incompleteEn.Add($"active skills not learned {string.Join(',', missingPreferredSkillIds)}");
                incompleteZhCn.Add($"主动技能未学习 {string.Join(',', missingPreferredSkillIds)}");
                incompleteZhTw.Add($"主動技能未學習 {string.Join(',', missingPreferredSkillIds)}");
            }
            if (!activeSkillPostconditionExact)
            {
                incompleteKo.Add($"액티브 스킬 최종 검증 불일치 {string.Join(',', learnedActiveSkillIds.OrderBy(id => id))}/{string.Join(',', desiredActiveSkillIds.OrderBy(id => id))}");
                incompleteEn.Add($"active-skill final state mismatch {string.Join(',', learnedActiveSkillIds.OrderBy(id => id))}/{string.Join(',', desiredActiveSkillIds.OrderBy(id => id))}");
                incompleteZhCn.Add($"主动技能最终状态不匹配 {string.Join(',', learnedActiveSkillIds.OrderBy(id => id))}/{string.Join(',', desiredActiveSkillIds.OrderBy(id => id))}");
                incompleteZhTw.Add($"主動技能最終狀態不符 {string.Join(',', learnedActiveSkillIds.OrderBy(id => id))}/{string.Join(',', desiredActiveSkillIds.OrderBy(id => id))}");
            }
            if (!transformComplete)
            {
                incompleteKo.Add($"변환 목표 {transform.Matched}/{transform.Target}");
                incompleteEn.Add($"transform target {transform.Matched}/{transform.Target}");
                incompleteZhCn.Add($"转换目标 {transform.Matched}/{transform.Target}");
                incompleteZhTw.Add($"轉換目標 {transform.Matched}/{transform.Target}");
            }
            if (!baseSkillVerified)
            {
                incompleteKo.Add($"기본 스킬 {actualBaseTalentId}/{desiredBaseTalentId}");
                incompleteEn.Add($"base skill {actualBaseTalentId}/{desiredBaseTalentId}");
                incompleteZhCn.Add($"基础技能 {actualBaseTalentId}/{desiredBaseTalentId}");
                incompleteZhTw.Add($"基礎技能 {actualBaseTalentId}/{desiredBaseTalentId}");
            }
            if (unlearnedMasteryTalentIds.Count > 0)
            {
                incompleteKo.Add($"추천 마스터리 미학습 {string.Join(',', unlearnedMasteryTalentIds)}");
                incompleteEn.Add($"masteries not learned {string.Join(',', unlearnedMasteryTalentIds)}");
                incompleteZhCn.Add($"专精未学习 {string.Join(',', unlearnedMasteryTalentIds)}");
                incompleteZhTw.Add($"專精未學習 {string.Join(',', unlearnedMasteryTalentIds)}");
            }
            if (!variantVerification.IsExact)
            {
                incompleteKo.Add($"장비 변환형 불일치 -{string.Join(',', variantVerification.Missing)} +{string.Join(',', variantVerification.Unexpected)}");
                incompleteEn.Add($"gear variant mismatch -{string.Join(',', variantVerification.Missing)} +{string.Join(',', variantVerification.Unexpected)}");
                incompleteZhCn.Add($"装备变体不匹配 -{string.Join(',', variantVerification.Missing)} +{string.Join(',', variantVerification.Unexpected)}");
                incompleteZhTw.Add($"裝備變體不符 -{string.Join(',', variantVerification.Missing)} +{string.Join(',', variantVerification.Unexpected)}");
            }
            if (hasUnusableSkill)
            {
                incompleteKo.Add("현재 무기로 사용할 수 없는 학습 스킬 있음");
                incompleteEn.Add("a learned skill is unusable with the current weapons");
                incompleteZhCn.Add("当前武器无法使用某个已学习技能");
                incompleteZhTw.Add("目前武器無法使用某個已學習技能");
            }
            if (failedNodes.Count > 0)
            {
                incompleteKo.Add($"포인트 적용 실패 {string.Join(',', failedNodes)}");
                incompleteEn.Add($"point application failed {string.Join(',', failedNodes)}");
                incompleteZhCn.Add($"点数应用失败 {string.Join(',', failedNodes)}");
                incompleteZhTw.Add($"點數套用失敗 {string.Join(',', failedNodes)}");
            }
            if (previewFailedNodes.Count > 0)
            {
                incompleteKo.Add($"성능 미리보기 실패 {string.Join(',', previewFailedNodes)}");
                incompleteEn.Add($"performance preview failed {string.Join(',', previewFailedNodes)}");
                incompleteZhCn.Add($"性能预览失败 {string.Join(',', previewFailedNodes)}");
                incompleteZhTw.Add($"效能預覽失敗 {string.Join(',', previewFailedNodes)}");
            }
            if (!allocationLedgerExact)
            {
                incompleteKo.Add($"포인트 원장 불일치 {allocated}/{allocatedByPlan}");
                incompleteEn.Add($"point ledger mismatch {allocated}/{allocatedByPlan}");
                incompleteZhCn.Add($"点数记录不匹配 {allocated}/{allocatedByPlan}");
                incompleteZhTw.Add($"點數記錄不符 {allocated}/{allocatedByPlan}");
            }
            if (talentLevelMismatches.Count > 0)
            {
                incompleteKo.Add($"특성 레벨 검증 불일치 {string.Join(',', talentLevelMismatches)}");
                incompleteEn.Add($"talent-level verification mismatch {string.Join(',', talentLevelMismatches)}");
                incompleteZhCn.Add($"天赋等级验证不匹配 {string.Join(',', talentLevelMismatches)}");
                incompleteZhTw.Add($"天賦等級驗證不符 {string.Join(',', talentLevelMismatches)}");
            }
            if (exactTargetMismatches.Count > 0)
            {
                incompleteKo.Add($"공동 계획 목표 레벨 불일치 {string.Join(',', exactTargetMismatches)}");
                incompleteEn.Add($"shared-plan target-level mismatch {string.Join(',', exactTargetMismatches)}");
                incompleteZhCn.Add($"联合方案目标等级不匹配 {string.Join(',', exactTargetMismatches)}");
                incompleteZhTw.Add($"聯合方案目標等級不符 {string.Join(',', exactTargetMismatches)}");
            }
            if (!resetBloodVerified)
            {
                incompleteKo.Add($"초기화 피 검증 실패 {resetSpentBlood}/{(spentBefore > 0 ? resetPrice : 0)}");
                incompleteEn.Add($"reset Blood mismatch {resetSpentBlood}/{(spentBefore > 0 ? resetPrice : 0)}");
                incompleteZhCn.Add($"重置鲜血不匹配 {resetSpentBlood}/{(spentBefore > 0 ? resetPrice : 0)}");
                incompleteZhTw.Add($"重設鮮血不符 {resetSpentBlood}/{(spentBefore > 0 ? resetPrice : 0)}");
            }
            if (unspentPointsRemain)
            {
                incompleteKo.Add($"미사용 포인트 {remaining} ({unspentPointConstraint})");
                incompleteEn.Add($"{remaining} points remain unspent ({unspentPointConstraint})");
                incompleteZhCn.Add($"仍有 {remaining} 点未分配（{unspentPointConstraint}）");
                incompleteZhTw.Add($"仍有 {remaining} 點未分配（{unspentPointConstraint}）");
            }
            if (!transform.CleanupSucceeded)
            {
                incompleteKo.Add("임시 신전 설정 복구 실패");
                incompleteEn.Add("temporary shrine settings were not restored");
                incompleteZhCn.Add("临时神殿设置未恢复");
                incompleteZhTw.Add("臨時神殿設定未復原");
            }
            var verifiedComplete = incompleteEn.Count == 0;
            var completionKo = verifiedComplete ? "스킬 집중 분배 검증 완료" : $"일부 적용 · {string.Join("; ", incompleteKo)}";
            var completionEn = verifiedComplete ? "Focused skill allocation verified" : $"Partially applied · {string.Join("; ", incompleteEn)}";
            var completionZhCn = verifiedComplete ? "技能集中分配验证完成" : $"部分应用 · {string.Join("; ", incompleteZhCn)}";
            var completionZhTw = verifiedComplete ? "技能集中分配驗證完成" : $"部分套用 · {string.Join("; ", incompleteZhTw)}";
            var skillLevelSummary = string.Join(" · ", skillLevelStates);
            var planTokenSuffix = string.IsNullOrWhiteSpace(effectivePreferred.PlanToken)
                ? string.Empty
                : $" · plan {effectivePreferred.PlanToken}";
            message = UiText.L(
                $"{completionKo} · {focus.Localized} · {preferred.BuildName}{transformKo}{variantKo} · {allocated:N0}포인트 · {skillLevelSummary}{planTokenSuffix} · 변환 피 {transform.SpentBlood:N0} / 초기화 피 {resetSpentBlood:N0}{(remaining > 0 ? $" · 미사용 {remaining:N0}" : string.Empty)}{transformNoteSuffix}",
                $"{completionEn} · {focus.English} · {preferred.BuildName}{transformEn}{variantEn} · {allocated:N0} points · {skillLevelSummary}{planTokenSuffix} · transform Blood {transform.SpentBlood:N0} / reset Blood {resetSpentBlood:N0}{(remaining > 0 ? $" · {remaining:N0} unspent" : string.Empty)}{transformNoteSuffix}",
                $"{completionZhCn} · {focus.Localized} · {preferred.BuildName}{transformZh}{variantZh} · {allocated:N0} 点 · {skillLevelSummary}{planTokenSuffix} · 转换鲜血 {transform.SpentBlood:N0} / 重置鲜血 {resetSpentBlood:N0}{(remaining > 0 ? $" · 剩余 {remaining:N0}" : string.Empty)}{transformNoteSuffix}",
                $"{completionZhTw} · {focus.Localized} · {preferred.BuildName}{transformZh}{variantZh} · {allocated:N0} 點 · {skillLevelSummary}{planTokenSuffix} · 轉換鮮血 {transform.SpentBlood:N0} / 重設鮮血 {resetSpentBlood:N0}{(remaining > 0 ? $" · 剩餘 {remaining:N0}" : string.Empty)}{transformNoteSuffix}");
            if (verifiedComplete)
            {
                // A successful standalone skill application changes the skill
                // fingerprint while leaving the remembered gear fingerprint
                // intact. Advance the cache to the verified post-state so Auto
                // can reuse this exact plan, while any later manual skill edit
                // still invalidates it.
                var appliedPlanKey = GetJointSkillPlanHeroKey(hero);
                if (JointSkillPlansByHero.TryGetValue(appliedPlanKey, out var appliedPlan))
                    JointSkillPlansByHero[appliedPlanKey] = appliedPlan with
                    {
                        SkillFingerprint = GetSkillStateFingerprint(hero)
                    };
            }
            return verifiedComplete;
        }
        catch (Exception error)
        {
            message = UiText.L($"스킬 자동 분배 실패: {error.GetBaseException().Message}", $"Skill allocation failed: {error.GetBaseException().Message}", $"技能自动分配失败：{error.GetBaseException().Message}", $"技能自動分配失敗：{error.GetBaseException().Message}")
                      + DescribeSkillMutationJournal(journalTransformAttempts, journalTransformBlood, journalResetInvoked, journalResetSucceeded, journalResetPrice, journalBaseChanged, journalAllocationStart, journalSaveHero);
            return false;
        }
    }

    private static string DescribeSkillMutationJournal(int transformAttempts, int transformBlood, bool resetInvoked,
        bool resetSucceeded, int resetPrice, bool baseChanged, int allocationStart, object? saveHero)
    {
        var allocated = allocationStart >= 0 && saveHero is not null
            ? Math.Max(0, allocationStart - (ReadNullableInt(saveHero, "talentRemainPoint") ?? allocationStart))
            : 0;
        if (transformAttempts <= 0 && !resetInvoked && !baseChanged && allocated <= 0) return string.Empty;
        var transformText = transformBlood >= 0 ? transformBlood.ToString("N0", CultureInfo.CurrentCulture) : UiText.L("확인 불가", "unknown", "未知", "未知");
        return UiText.L(
            $" · 변경 기록: 스킬 변환 {transformAttempts}회/피 {transformText}, 초기화 {(resetInvoked ? resetSucceeded ? $"성공(예상 피 {resetPrice:N0})" : "호출됨·성공 미확인" : "안 함")}, 기본 스킬 {(baseChanged ? "변경" : "유지")}, 확인된 배분 {allocated:N0}포인트",
            $" · mutation record: transforms {transformAttempts}/Blood {transformText}, reset {(resetInvoked ? resetSucceeded ? $"succeeded (expected Blood {resetPrice:N0})" : "invoked; success unverified" : "not run")}, base skill {(baseChanged ? "changed" : "unchanged")}, verified allocation {allocated:N0} point(s)",
            $" · 变更记录：技能转换 {transformAttempts} 次/鲜血 {transformText}，重置 {(resetInvoked ? resetSucceeded ? $"成功（预计鲜血 {resetPrice:N0}）" : "已调用·成功未确认" : "未执行")}，基础技能{(baseChanged ? "已更改" : "未更改")}，已确认分配 {allocated:N0} 点",
            $" · 變更記錄：技能轉換 {transformAttempts} 次/鮮血 {transformText}，重設 {(resetInvoked ? resetSucceeded ? $"成功（預計鮮血 {resetPrice:N0}）" : "已呼叫·成功未確認" : "未執行")}，基礎技能{(baseChanged ? "已變更" : "未變更")}，已確認分配 {allocated:N0} 點");
    }

#if PATHOFIDLE_RUNTIME_TEST
    internal static bool RuntimeRejectJointBuildAfterSkills { get; set; }

    internal static string CaptureRuntimeJointBuildPostState()
    {
        try
        {
            var hero = GetSelectedHero();
            if (hero is null) return "unavailable:selected hero is not loaded";

            var equipped = GetGearSlots().Select(slot =>
            {
                var item = GetEquippedItem(hero, slot.Part, slot.MainWeapon);
                if (item is null) return $"{slot.Label}=empty";
                var saveItem = Read(item, "saveItemData");
                var definition = Read(Read(item, "itemEquipData"), "tEquipData");
                var itemId = ReadNullableInt(saveItem, "id") ?? 0;
                var definitionId = ReadNullableInt(definition, "id") ?? 0;
                var setId = ReadNullableInt(Read(Read(item, "itemEquipData"), "tEquipSetsData"), "id")
                            ?? ReadNullableInt(definition, "setsId") ?? 0;
                return $"{slot.Label}=item:{itemId}/definition:{definitionId}/set:{setId}";
            }).ToList();
            var setCounts = GetGearSlots()
                .Select(slot => GetEquippedItem(hero, slot.Part, slot.MainWeapon))
                .Where(item => item is not null).Cast<object>()
                .Select(item =>
                {
                    var equip = Read(item, "itemEquipData");
                    return new
                    {
                        SetId = ReadNullableInt(Read(equip, "tEquipSetsData"), "id")
                                ?? ReadNullableInt(Read(equip, "tEquipData"), "setsId") ?? 0,
                        DefinitionId = ReadNullableInt(Read(equip, "tEquipData"), "id") ?? 0
                    };
                })
                .Where(entry => entry.SetId > 0 && entry.DefinitionId > 0)
                .GroupBy(entry => entry.SetId)
                .OrderBy(group => group.Key)
                .Select(group => $"{group.Key}:{group.Select(entry => entry.DefinitionId).Distinct().Count()}");

            var talentData = Read(hero, "heroTalentData");
            var baseSkill = InvokeRequiredInstance(hero, "GetNowBaseSkillData");
            var baseSkillId = ReadNullableInt(Read(baseSkill, "tSkillData"), "id") ?? 0;
            // GetNowBaseSkillData/GetSkillList return SkillData. Their effective
            // combat level lives on SkillData.level; saveTalentData belongs to
            // the owning TalentData and must not be read from SkillData.
            var baseSkillLevel = Math.Max(0, ReadNullableInt(baseSkill, "level") ?? 0);
            var activeSkills = talentData is null
                ? new List<string>()
                : ReadList(InvokeRequiredInstance(talentData, "GetSkillList"))
                    .Select(skill => new
                    {
                        Id = ReadNullableInt(Read(skill, "tSkillData"), "id") ?? 0,
                        Level = Math.Max(0, ReadNullableInt(skill, "level") ?? 0)
                    })
                    .Where(skill => skill.Id > 0)
                    .GroupBy(skill => skill.Id)
                    .OrderBy(group => group.Key)
                    .Select(group => $"{group.Key}:{group.Max(skill => skill.Level)}")
                    .ToList();

            return $"equipped[{string.Join(';', equipped)}] "
                   + $"set_counts[{string.Join(',', setCounts)}] "
                   + $"base[{baseSkillId}:{baseSkillLevel}] "
                   + $"active[{string.Join(',', activeSkills)}]";
        }
        catch (Exception error)
        {
            return $"unavailable:{error.GetBaseException().Message}";
        }
    }

    internal static bool TryGetRuntimeJointBuildTestReadiness(out string reason)
    {
        try
        {
            // Use the same readiness contract as production Auto Build. The
            // harness does not click Continue or alter adventure/Auto state.
            return TryGetAutoBuildReadinessCore(null, out reason);
        }
        catch (Exception error)
        {
            reason = error.GetBaseException().Message;
            return false;
        }
    }

    internal static IReadOnlyList<string> GetRuntimeControlledEntityKinds(int skillId)
    {
        var kinds = GetNativeControlledEntityKindsForSkillCore(skillId);
        var result = new List<string>();
        if (kinds.HasFlag(NativeControlledEntityKind.Minion)) result.Add("minion");
        if (kinds.HasFlag(NativeControlledEntityKind.Ally)) result.Add("ally");
        if (kinds.HasFlag(NativeControlledEntityKind.Totem)) result.Add("totem");
        if (kinds.HasFlag(NativeControlledEntityKind.OtherSummon)) result.Add("other-summon");
        return result;
    }

