    private static object? GetSelectedHero()
    {
        var dataManager = ReadStatic("Game", "dataMgr");
        var seasonData = Read(dataManager, "nowSeasonData");
        return Read(Read(seasonData, "lordData"), "nowHeroData");
    }

    private sealed record HeroFocus(string Key, string Localized, string English, string[] Keywords, bool IsManual = false);
    private sealed record NativeDamageThemeRule(HashSet<int> DamageTypes);

    private static readonly object NativeDamageTypeNameSync = new();
    private static readonly Dictionary<int, string> NativeDamageTypeNames = new()
    {
        [1] = "blunt",
        [2] = "slash",
        [3] = "pierce",
        [4] = "fire",
        [5] = "frost",
        [6] = "lightning",
        [7] = "bleed",
        [8] = "corrosion"
    };

    private static bool TryParseDynamicDamageTheme(string? value, out int damageType)
    {
        damageType = 0;
        var normalized = (value ?? string.Empty).Trim().ToLowerInvariant();
        const string prefix = "damage:";
        return normalized.StartsWith(prefix, StringComparison.Ordinal)
               && int.TryParse(normalized[prefix.Length..], NumberStyles.Integer,
                   CultureInfo.InvariantCulture, out damageType)
               && damageType > 0;
    }

    private static void RememberNativeDamageTypeName(int damageType, object? nativeKey)
    {
        if (damageType <= 0 || nativeKey is null) return;
        var discovered = new Dictionary<int, string>();
        void Add(object value)
        {
            var id = ToInt(value);
            var name = NormalizeSkillDependencyText(value.ToString() ?? string.Empty);
            if (id > 0 && name.Length > 0 && !int.TryParse(name, out _))
                discovered[id] = name;
        }
        Add(nativeKey);
        // The first observed PowerData dictionary key reveals the game's native
        // damage enum. Register every member at once so a newly added type gets
        // a stable `damage:<id>` rule even before it appears on equipped gear.
        try
        {
            var enumType = nativeKey.GetType();
            if (enumType.IsEnum)
                foreach (var value in Enum.GetValues(enumType)) Add(value!);
        }
        catch
        {
            // The observed key itself remains sufficient on interop builds that
            // do not expose managed enum enumeration.
        }
        if (discovered.Count == 0) return;
        lock (NativeDamageTypeNameSync)
            foreach (var entry in discovered)
                NativeDamageTypeNames[entry.Key] = entry.Value;
    }

    private static string GetNativeDamageTypeName(int damageType)
    {
        lock (NativeDamageTypeNameSync)
            return NativeDamageTypeNames.TryGetValue(damageType, out var name)
                ? name
                : $"damage type {damageType}";
    }

    private static int InferNativeDamageTypeFromText(string? source)
    {
        var text = NormalizeSkillDependencyText(source);
        if (text.Length == 0) return 0;

        // Prefer names discovered from the game's live damage enum. This makes
        // a newly added, plainly named damage type usable by text-only legacy
        // effects without waiting for a plugin release. Known aliases below are
        // only compatibility names for the current pinyin enum members.
        List<KeyValuePair<int, string>> discovered;
        lock (NativeDamageTypeNameSync)
            discovered = NativeDamageTypeNames
                .Where(entry => entry.Key > 0 && entry.Value.Length >= 3)
                .OrderByDescending(entry => entry.Value.Length)
                .ThenBy(entry => entry.Key)
                .ToList();
        foreach (var entry in discovered)
        {
            var name = NormalizeSkillDependencyText(entry.Value);
            if (name.Length >= 3 && text.Contains(name, StringComparison.Ordinal))
                return entry.Key;
        }

        // Assembly-CSharp's current native EDamageType contract is
        // 1=JiDa (Blunt), 2=PiKan (Slash), 3=ChuanCi (Pierce), followed by
        // Fire/Frost/Lightning/Bleed/Corrosion. Keep display-language aliases
        // separate from the discovered registry so a future enum member can
        // still win above by its own native name.
        if (text.Contains("blunt", StringComparison.Ordinal)) return 1;
        if (text.Contains("slash", StringComparison.Ordinal)) return 2;
        if (text.Contains("pierce", StringComparison.Ordinal)
            || text.Contains("piercing", StringComparison.Ordinal)) return 3;
        if (text.Contains("fire", StringComparison.Ordinal)) return 4;
        if (text.Contains("frost", StringComparison.Ordinal)
            || text.Contains("ice damage", StringComparison.Ordinal)
            || text.Contains("cold damage", StringComparison.Ordinal)) return 5;
        if (text.Contains("lightning", StringComparison.Ordinal)) return 6;
        if (text.Contains("bleed", StringComparison.Ordinal)) return 7;
        if (text.Contains("corrosion", StringComparison.Ordinal)) return 8;
        return 0;
    }

    private static bool IsPeriodicDamageType(int damageType)
    {
        if (damageType is 7 or 8) return true;
        var name = GetNativeDamageTypeName(damageType);
        return new[]
        {
            "bleed", "wound", "corrosion", "poison", "toxic", "venom",
            "damage over time", "periodic", "dot"
        }.Any(token => name.Contains(token, StringComparison.OrdinalIgnoreCase));
    }

    private static NativeDamageThemeRule? GetNativeDamageThemeRule(HeroFocus focus)
    {
        HashSet<int>? types = focus.Key switch
        {
            "physical" => new HashSet<int> { 1, 2, 3 },
            "elemental" => new HashSet<int> { 4, 5, 6 },
            "fire" => new HashSet<int> { 4 },
            "ice" => new HashSet<int> { 5 },
            "lightning" => new HashSet<int> { 6 },
            "bleed" => new HashSet<int> { 7 },
            "corrosion" => new HashSet<int> { 8 },
            _ => TryParseDynamicDamageTheme(focus.Key, out var dynamicType)
                ? new HashSet<int> { dynamicType }
                : null
        };
        if (types is null) return null;

        // This is a lane-presence contract, not a purity cutoff. A class can
        // have unavoidable off-theme damage on its base/support skills. Theme
        // priority already weights the measured 30-second aligned output, so a
        // second share/skill-count gate only makes valid Lightning/Ice/etc.
        // packages impossible and prevents their remaining points from ever
        // reaching useful passives such as Spell Speed.
        return new NativeDamageThemeRule(types);
    }

    private static bool HasFocusedRoleConstraint(HeroFocus focus)
        => !string.Equals(focus.Key, "hybrid", StringComparison.Ordinal);

    private static int GetActiveThemePriority()
        => Plugin.NormalizeAutoBuildThemePriority(
            MainThreadNativeGateway.CurrentWorkerOperation?.ThemePriority
            ?? Plugin.AutoBuildThemePriority.Value);

    private static double Lerp(double from, double to, double amount)
        => from + (to - from) * Math.Clamp(amount, 0d, 1d);

    // Priority 50 is deliberately the compatibility point. Lower values move
    // toward general output while higher values move toward the selected lane;
    // the endpoints are explicit without silently changing existing saves.
    private static double BlendThemePriority(
        HeroFocus focus,
        double general,
        double balanced,
        double themed)
    {
        if (focus.Key == "hybrid") return balanced;
        var priority = GetActiveThemePriority();
        return priority <= 50
            ? Lerp(general, balanced, priority / 50d)
            : Lerp(balanced, themed, (priority - 50d) / 50d);
    }

    public static string NormalizeBuildTheme(string? value)
    {
        var normalized = (value ?? string.Empty).Trim().ToLowerInvariant();
        return normalized is "auto" or "physical" or "elemental" or "fire" or "ice" or "lightning" or "minion" or "bleed" or "corrosion" or "crit" or "support" or "defense"
               || TryParseDynamicDamageTheme(normalized, out _)
            ? normalized
            : "auto";
    }

    public static string GetSelectedHeroBuildTheme()
    {
        try
        {
            var hero = GetSelectedHero();
            return hero is null ? NormalizeBuildTheme(Plugin.AutoBuildTheme.Value) : GetHeroBuildTheme(hero);
        }
        catch
        {
            return NormalizeBuildTheme(Plugin.AutoBuildTheme.Value);
        }
    }

    public static void SetSelectedHeroBuildTheme(string? value)
    {
        var normalized = NormalizeBuildTheme(value);
        var hero = GetSelectedHero();
        if (hero is null)
        {
            Plugin.AutoBuildTheme.Value = normalized;
            return;
        }
        var uniqueId = ReadNullableInt(Read(hero, "saveHeroData"), "uniqueId") ?? 0;
        JointSkillPlansByHero.Remove(GetJointSkillPlanHeroKey(hero));
        if (uniqueId <= 0)
        {
            Plugin.AutoBuildTheme.Value = normalized;
            return;
        }

        var themes = ParseHeroBuildThemes(Plugin.AutoBuildHeroThemes.Value);
        themes[uniqueId] = normalized;
        Plugin.AutoBuildHeroThemes.Value = string.Join(";", themes.OrderBy(entry => entry.Key)
            .Select(entry => $"{entry.Key.ToString(CultureInfo.InvariantCulture)}={entry.Value}"));
    }

    private static string GetHeroBuildTheme(object hero)
    {
        var uniqueId = ReadNullableInt(Read(hero, "saveHeroData"), "uniqueId") ?? 0;
        var operation = MainThreadNativeGateway.CurrentWorkerOperation;
        var encodedThemes = operation?.HeroThemes ?? Plugin.AutoBuildHeroThemes.Value;
        var defaultTheme = operation?.DefaultTheme ?? Plugin.AutoBuildTheme.Value;
        if (uniqueId > 0 && ParseHeroBuildThemes(encodedThemes).TryGetValue(uniqueId, out var saved))
            return NormalizeBuildTheme(saved);
        return NormalizeBuildTheme(defaultTheme);
    }

    private static Dictionary<int, string> ParseHeroBuildThemes(string? encoded)
    {
        var result = new Dictionary<int, string>();
        foreach (var entry in (encoded ?? string.Empty).Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var separator = entry.IndexOf('=');
            if (separator <= 0 || separator >= entry.Length - 1) continue;
            if (!int.TryParse(entry[..separator], NumberStyles.Integer, CultureInfo.InvariantCulture, out var uniqueId) || uniqueId <= 0) continue;
            result[uniqueId] = NormalizeBuildTheme(entry[(separator + 1)..]);
        }
        return result;
    }

    private static HeroFocus ResolveHeroFocus(object hero, string? requestedTheme)
    {
        var normalized = NormalizeBuildTheme(requestedTheme);
        if (normalized == "auto"
            && JointSkillPlansByHero.TryGetValue(GetJointSkillPlanHeroKey(hero), out var remembered)
            && string.Equals(remembered.GearFingerprint, GetCurrentGearFingerprint(hero), StringComparison.Ordinal)
            && string.Equals(remembered.SkillFingerprint, GetSkillStateFingerprint(hero), StringComparison.Ordinal))
            return remembered.FocusKey == "hybrid"
                ? new HeroFocus("hybrid", UiText.L("균형·혼합", "Balanced / Hybrid", "均衡/混合", "均衡/混合"),
                    "Balanced / Hybrid", PhysicalWords.Concat(ElementalWords).ToArray())
                : ResolveHeroFocus(hero, remembered.FocusKey) with { IsManual = false };
        if (TryParseDynamicDamageTheme(normalized, out var dynamicDamageType))
        {
            var nativeName = GetNativeDamageTypeName(dynamicDamageType);
            var label = string.IsNullOrWhiteSpace(nativeName)
                ? $"Damage type {dynamicDamageType}"
                : CultureInfo.InvariantCulture.TextInfo.ToTitleCase(nativeName);
            return new HeroFocus(
                normalized,
                label,
                label,
                nativeName.Split(new[] { ' ', '-', '_', '/' },
                    StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries),
                true);
        }
        return normalized switch
        {
            "physical" => new HeroFocus("physical", UiText.L("물리·무예", "Physical / Martial", "物理/武技", "物理/武技"), "Physical / Martial", PhysicalWords, true),
            "elemental" => new HeroFocus("elemental", UiText.L("원소·주문", "Elemental / Spell", "元素/法术", "元素/法術"), "Elemental / Spell", ElementalWords, true),
            "fire" => new HeroFocus("fire", UiText.L("화염·연소", "Fire / Burn", "火焰/燃烧", "火焰/燃燒"), "Fire / Burn", FireWords, true),
            "ice" => new HeroFocus("ice", UiText.L("냉기·빙결", "Ice / Freeze", "冰霜/冻结", "冰霜/凍結"), "Ice / Freeze", IceWords, true),
            "lightning" => new HeroFocus("lightning", UiText.L("번개·감전", "Lightning / Shock", "闪电/感电", "閃電/感電"), "Lightning / Shock", LightningWords, true),
            "minion" => new HeroFocus("minion", UiText.L("소환수·하수인", "Minion / Summon", "召唤物/仆从", "召喚物/僕從"), "Minion / Summon", MinionWords, true),
            "bleed" => new HeroFocus("bleed", UiText.L("출혈·상처", "Bleed / Wound", "流血/创伤", "流血/創傷"), "Bleed / Wound", BleedWords, true),
            "corrosion" => new HeroFocus("corrosion", UiText.L("부식·중독", "Corrosion / Poison", "腐蚀/中毒", "腐蝕/中毒"), "Corrosion / Poison", CorrosionWords, true),
            "crit" => new HeroFocus("crit", UiText.L("치명타", "Critical Strike", "暴击", "暴擊"), "Critical Strike", CriticalWords, true),
            "support" => new HeroFocus("support", UiText.L("지원·오라", "Support / Aura", "辅助/光环", "輔助/光環"), "Support / Aura", SupportWords, true),
            "defense" => new HeroFocus("defense", UiText.L("생존·방어", "Defense / Survival", "防御/生存", "防禦/生存"), "Defense / Survival", TankWords, true),
            _ => DetermineHeroFocus(hero)
        };
    }

    private static HeroFocus DetermineHeroFocus(object hero)
    {
        var job = Read(hero, "tHeroJobData");
        var saveHero = Read(hero, "saveHeroData");
        var jobId = ReadNullableInt(saveHero, "jobId")
                    ?? ReadNullableInt(job, "id")
                    ?? 0;
        var heroLevel = ReadNullableInt(saveHero, "level") ?? 0;
        var roleTextParts = new List<string>
        {
            ReadString(job, "name") ?? string.Empty,
            ReadString(job, "des") ?? string.Empty,
            EnglishName(job, string.Empty) ?? string.Empty,
            EnglishText(job, "_des", string.Empty) ?? string.Empty
        };
        var nativeRoles = new List<(int SkillId, bool IsBase, HashSet<int> Tags, NativeSkillRoleProfile Role)>();
        var seenSkillIds = new HashSet<int>();
        void AddNativeRole(object? skill, int fallbackLevel, bool isBase)
        {
            if (skill is null) return;
            var row = Read(skill, "tSkillData") ?? skill;
            var skillId = ReadNullableInt(row, "id") ?? 0;
            if (skillId <= 0 || !seenSkillIds.Add(skillId)) return;
            var level = Math.Max(1, ReadNullableInt(skill, "level") ?? fallbackLevel);
            var info = Read(skill, "tSkillInfoData")
                       ?? (ReadNullableInt(row, "infoId") is > 0 and var infoId
                           ? InvokeStatic("TableData", "getTSkillInfoData", infoId)
                           : null);
            var tags = ReadSequence(Read(info, "tagArr"))
                .Select(ToInt).Where(value => value > 0).ToHashSet();
            try
            {
                var role = ReadNativeSkillRoleProfile(hero, skillId, level);
                nativeRoles.Add((skillId, isBase, tags, role));
            }
            catch (Exception error)
            {
                // Auto inference is read-only. An unavailable native preview is
                // absence of evidence, never permission to infer an element from
                // a translated verb such as "fire".
                Plugin.DiagDebug($"AUTO-FOCUS SKILL PREVIEW SKIPPED|skill={skillId}|{error.GetBaseException().Message}");
            }
        }

        var currentBaseSkill = InvokeInstance(hero, "GetNowBaseSkillData");
        AddNativeRole(currentBaseSkill, 1, true);
        try
        {
            // Auto must classify the build from the complete legal shrine pool,
            // not only from the six skills currently rolled on the hero. The old
            // incumbent-only census could never discover Ballista Sentry (or an
            // equivalent unrolled Aura/Totem/element skill), so Auto simply kept
            // repeating the existing build even though transformation was on.
            var availableActiveRows = ReadValues(ReadStatic("TableData", "TTalentDict"))
                .Where(IsTransformableSkillDefinition).Cast<object>()
                .Where(row => (ReadNullableInt(row, "jobId") ?? 0) == jobId)
                .Where(row => heroLevel > 1 || (ReadNullableInt(row, "floor") ?? 0) == 1)
                .GroupBy(row => ReadNullableInt(row, "skillId") ?? 0)
                .Where(group => group.Key > 0)
                .Select(group => group.OrderBy(row => ReadNullableInt(row, "index") ?? int.MaxValue)
                    .ThenBy(row => ReadNullableInt(row, "id") ?? int.MaxValue).First())
                .ToList();
            foreach (var row in availableActiveRows)
            {
                var skillId = ReadNullableInt(row, "skillId") ?? 0;
                if (skillId <= 0) continue;
                var skillRow = InvokeStatic("TableData", "getTSkillData", skillId);
                AddNativeRole(skillRow, 1, false);
                roleTextParts.Add(EnglishName(row, string.Empty) ?? string.Empty);
                roleTextParts.Add(EnglishName(skillRow, string.Empty) ?? string.Empty);
            }
        }
        catch (Exception error)
        {
            Plugin.DiagDebug(
                $"AUTO-FOCUS AVAILABLE SKILL CENSUS SKIPPED|job={jobId}|{error.GetBaseException().Message}");
        }
        try
        {
            var talentData = Read(hero, "heroTalentData");
            var activeTalents = ReadValues(Read(talentData, "talentDic")).Concat(
                    ReadList(Read(talentData, "extraTalentList")).Where(talent => !ReadBool(Read(talent, "isRuneWords"))))
                .DistinctBy(value => NativeObjectKey(value, value));
            foreach (var talent in activeTalents)
            {
                if (Convert.ToInt32(InvokeInstance(talent, "GetLevel") ?? 0, CultureInfo.InvariantCulture) <= 0) continue;
                var definition = Read(talent, "tTalentData");
                var skill = Read(talent, "skillData");
                var skillRow = Read(skill, "tSkillData");
                var info = Read(skill, "tSkillInfoData");
                var masteryData = Read(talent, "masteryData");
                var mastery = Read(masteryData, "tMasteryData");
                // Text is retained only as secondary evidence for role themes.
                // Elemental themes are derived exclusively from native damage
                // types below, so ordinary UI verbs cannot become Fire/Ice/etc.
                roleTextParts.Add(EnglishName(definition, string.Empty) ?? string.Empty);
                roleTextParts.Add(EnglishName(skillRow, string.Empty) ?? string.Empty);
                roleTextParts.Add(EnglishText(info, "_des", string.Empty) ?? string.Empty);
                roleTextParts.Add(EnglishName(mastery, string.Empty) ?? string.Empty);
                foreach (var affix in ReadList(Read(masteryData, "affixList")))
                {
                    var effectType = ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0;
                    if (effectType is 1 or 3) roleTextParts.Add(GetAffixSearchText(affix));
                }
            }
        }
        catch { }

        HeroFocus AutoFocus(string key) => ResolveHeroFocus(hero, key) with { IsManual = false };
        var nativeTags = nativeRoles.SelectMany(entry => entry.Tags).ToHashSet();
        var availableRoles = nativeRoles.Select(entry => entry.Role).ToList();
        var authoredPackages = new List<(int BuildId, string Name, NativeSkillRoleProfile Role)>();
        try
        {
            var heroAttr = Read(hero, "attrData")
                           ?? throw new InvalidOperationException("Hero AttrData is unavailable.");
            foreach (var build in ReadValues(ReadStatic("TableData", "TBuildsDict"))
                         .Where(build => (ReadNullableInt(build, "jobId") ?? 0) == jobId)
                         .Where(build => !ReadRequiredBoolProperty(build, "isLock")))
            {
                try
                {
                    var definitions = ReadRequiredSequenceProperty(build, "skillArr")
                        .Select(ToInt).Where(id => id > 0).Distinct()
                        .Select(id => InvokeStatic("TableData", "getTTalentData", id))
                        .Where(row => (ReadNullableInt(row, "skillId") ?? 0) > 0)
                        .Cast<object>().ToList();
                    var baseSkillId = definitions.Where(IsBaseSkillDefinition)
                        .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                        .FirstOrDefault(id => id > 0);
                    var activeSkillIds = definitions.Where(IsTransformableSkillDefinition)
                        .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                        .Where(id => id > 0).Distinct().ToList();
                    var packageSkillIds = activeSkillIds.Append(baseSkillId)
                        .Where(id => id > 0).Distinct().ToList();
                    if (packageSkillIds.Count == 0) continue;
                    var packageAttr = CreateStrictSkillPackageAdjustedAttr(
                        hero,
                        packageSkillIds.Select(id => (SkillId: id, Level: 1)),
                        heroAttr,
                        false,
                        null,
                        out _);
                    NativeSkillRoleProfile PackageRole(int skillId)
                        => skillId <= 0
                            ? EmptyNativeSkillRole()
                            : ReadNativeSkillRoleProfile(
                                hero, skillId, 1, packageAttr, false,
                                null, true, false);
                    var package = BuildSharedSkillPackage(
                        PackageRole(baseSkillId), activeSkillIds.Select(PackageRole));
                    if (!HasProvenNativeRoleSignal(package) && !package.Summon) continue;
                    authoredPackages.Add((
                        ReadNullableInt(build, "id") ?? ReadNullableInt(build, "index") ?? 0,
                        Clean(EnglishName(build, ReadString(build, "name") ?? string.Empty)
                              ?? string.Empty),
                        package));
                }
                catch (Exception error)
                {
                    Plugin.DiagDebug(
                        $"AUTO-FOCUS BUILD PACKAGE SKIPPED|job={jobId}|build={ReadNullableInt(build, "id") ?? ReadNullableInt(build, "index") ?? 0}|{error.GetBaseException().Message}");
                }
            }
        }
        catch (Exception error)
        {
            Plugin.DiagDebug(
                $"AUTO-FOCUS BUILD CENSUS SKIPPED|job={jobId}|{error.GetBaseException().Message}");
        }
        // Official build rows are the game's authored relationship graph. They
        // keep Aura/Warcry/Minion helpers attached to the attacks they modify,
        // while the strict package AttrData applies their always-on effects
        // before the 30-second package is measured. Fall back to individual
        // candidates only when no unlocked authored package is available.
        var autoComparisonRoles = authoredPackages.Count > 0
            ? authoredPackages.Select(entry => entry.Role).ToList()
            : availableRoles;
#if PATHOFIDLE_RUNTIME_TEST
        Plugin.DiagInfo(
            $"AUTO-FOCUS TAG CENSUS|job={jobId}|skills={string.Join(";", nativeRoles.OrderBy(entry => entry.SkillId).Select(entry => $"{entry.SkillId}[{string.Join(",", entry.Tags.OrderBy(id => id))}]"))}");
        Plugin.DiagInfo(
            $"AUTO-FOCUS BUILD CENSUS|job={jobId}|builds={string.Join(";", authoredPackages.OrderBy(entry => entry.BuildId).Select(entry => $"{entry.BuildId}:{entry.Name}"))}");
        Plugin.DiagInfo(
            $"AUTO-FOCUS BUILD ROLES|job={jobId}|packages={string.Join(";", authoredPackages.OrderBy(entry => entry.BuildId).Select(entry => $"{entry.BuildId}:damage={entry.Role.DamageByType.Values.Where(double.IsFinite).Sum():0.###},heal={entry.Role.Heal:0.###},selfHeal={entry.Role.SelfHeal:0.###},shield={entry.Role.Shield:0.###},selfShield={entry.Role.SelfShield:0.###},support={entry.Role.AbilitySupport:0.###},defense={entry.Role.AbilityDefense:0.###},minion={entry.Role.AbilityMinion:0.###},summonDef={entry.Role.Summon},summonDamage={entry.Role.SummonDamage:0.###},summonSurvival={entry.Role.SummonSurvival:0.###},summonAttack={(entry.Role.SummonAttackByType?.Values.Where(double.IsFinite).Sum() ?? 0d):0.###},complete={entry.Role.IsComplete},failure={entry.Role.Failure.Replace('|', '/')}"))}");
#endif
        // TSkillInfo.tagArr and TSkillTag are the game's own classification
        // contract. Use them to choose the role lane; action/effect previews below
        // only validate and rank candidates within that native lane.
        var nativeMinionLane = autoComparisonRoles.Any(role =>
            role.ControlledEntityKinds != NativeControlledEntityKind.None);
        var nativeSupportLane = HasNativeSkillTag(
            nativeTags,
            "support", "utility", "buff", "debuff", "affliction",
            "aura", "ally", "totem", "curse");
        var roleText = Clean(string.Join(" ", roleTextParts)).ToLowerInvariant();
        // Compare complete candidates at the same abstraction level. Summing the
        // strongest Fire, Ice, Lightning and three physical damage types from
        // different skills fabricated an impossible super-skill and drowned out
        // a real Minion/Support candidate such as Ballista Sentry.
        var directDamage = autoComparisonRoles.Select(role => role.DamageByType.Values
                .Where(value => double.IsFinite(value) && value > 0d).Sum())
            .DefaultIfEmpty(0d).Max() * PerformanceTimeLinearNormalization;
        var damageSignal = Math.Log10(1d + directDamage);
        var minionNative = autoComparisonRoles.Select(role => Math.Max(0d,
                role.ControlledEntityDamage * PerformanceTimeLinearNormalization
                + role.ControlledEntitySurvival * 0.35d
                + role.ControlledEntityUtility))
            .DefaultIfEmpty(0d).Max();
        var supportNative = autoComparisonRoles.Select(role => Math.Max(0d,
                role.Heal * PerformanceTimeLinearNormalization * 1.4d
                + role.Shield * PerformanceTimeLinearNormalization + role.AbilitySupport))
            .DefaultIfEmpty(0d).Max();
        var defenseNative = autoComparisonRoles.Select(role => Math.Max(0d,
                role.SelfShield * PerformanceTimeLinearNormalization * 1.5d
                + role.SelfHeal * PerformanceTimeLinearNormalization + role.AbilityDefense))
            .DefaultIfEmpty(0d).Max();
        var minionSignal = Math.Log10(1d + minionNative);
        var supportSignal = Math.Log10(1d + supportNative);
        var defenseSignal = Math.Log10(1d + defenseNative);
        if (authoredPackages.Count == 0)
        {
            // Text is a last-resort hint only when the game exposes no authored
            // build graph. Otherwise the result must not depend on which skills
            // happened to be equipped before Auto Build started.
            minionSignal += Math.Min(1.5d, KeywordScore(roleText, MinionWords) * 0.18d);
            supportSignal += Math.Min(1.25d, KeywordScore(roleText, SupportWords) * 0.15d);
            defenseSignal += Math.Min(1.25d, KeywordScore(roleText, TankWords) * 0.15d);
        }
#if PATHOFIDLE_RUNTIME_TEST
        Plugin.DiagInfo(
            $"AUTO-FOCUS SIGNALS|job={jobId}|direct={directDamage:0.###}/{damageSignal:0.###}|minionTag={nativeMinionLane}|minion={minionNative:0.###}/{minionSignal:0.###}|supportTag={nativeSupportLane}|support={supportNative:0.###}/{supportSignal:0.###}|defense={defenseNative:0.###}/{defenseSignal:0.###}");
#endif
        var bestRole = new[]
        {
            (Key: "minion", Score: minionSignal, Native: nativeMinionLane && minionNative > 0d),
            (Key: "support", Score: supportSignal, Native: nativeSupportLane && supportNative > 0d),
            (Key: "defense", Score: defenseSignal, Native: nativeSupportLane && defenseNative > 0d)
        }.Where(entry => entry.Native)
            .OrderByDescending(entry => entry.Score).ThenBy(entry => entry.Key).FirstOrDefault();
        // Native package quantities are compared on the same logarithmic scale.
        // Keep damage as the conservative default for near-ties, but do not
        // require a role package to be almost three times stronger before it can
        // win. A 20% measured advantage is enough to select that native lane.
        const double autoRoleMinimumAdvantageRatio = 1.20d;
        if (bestRole.Score > 0.75d
            && bestRole.Score >= damageSignal + Math.Log10(autoRoleMinimumAdvantageRatio))
            return AutoFocus(bestRole.Key);

        // Discover native damage lanes from the actual PowerData keys. Known
        // lanes keep friendly labels, while a new game damage type remains a
        // first-class `damage:<id>` focus instead of being silently discarded
        // until this plugin is updated.
        var nativeDamageByType = autoComparisonRoles
            .SelectMany(role => role.DamageByType)
            .Where(entry => entry.Key > 0 && double.IsFinite(entry.Value) && entry.Value > 0d)
            .GroupBy(entry => entry.Key)
            .ToDictionary(group => group.Key, group => group.Max(entry => entry.Value));
        var nativeDamage = new Dictionary<string, double>
        {
            ["physical"] = autoComparisonRoles.Select(role => Enumerable.Range(1, 3)
                    .Sum(id => role.DamageByType.GetValueOrDefault(id)))
                .DefaultIfEmpty(0d).Max(),
            ["fire"] = nativeDamageByType.GetValueOrDefault(4),
            ["ice"] = nativeDamageByType.GetValueOrDefault(5),
            ["lightning"] = nativeDamageByType.GetValueOrDefault(6),
            ["bleed"] = nativeDamageByType.GetValueOrDefault(7),
            ["corrosion"] = nativeDamageByType.GetValueOrDefault(8)
        };
        var rankedNativeTypes = nativeDamageByType
            .OrderByDescending(entry => entry.Value)
            .ThenBy(entry => entry.Key)
            .ToList();
        if (rankedNativeTypes.Count > 0 && rankedNativeTypes[0].Key > 8)
        {
            var runnerUpTypeDamage = rankedNativeTypes.Skip(1)
                .Select(entry => entry.Value).DefaultIfEmpty(0d).First();
            if (rankedNativeTypes[0].Value >= runnerUpTypeDamage * 1.10d)
                return AutoFocus($"damage:{rankedNativeTypes[0].Key}");
        }
        var rankedDamage = nativeDamage.Where(entry => entry.Value > 0d)
            .OrderByDescending(entry => entry.Value).ThenBy(entry => entry.Key).ToList();
        if (rankedDamage.Count > 0)
        {
            var best = rankedDamage[0];
            var runnerUp = rankedDamage.Skip(1).Select(entry => entry.Value).DefaultIfEmpty(0d).First();
            if (best.Value >= runnerUp * 1.10d) return AutoFocus(best.Key);
            var elementalDamage = nativeDamage["fire"] + nativeDamage["ice"] + nativeDamage["lightning"];
            if (elementalDamage > nativeDamage["physical"])
                return AutoFocus("elemental");
            if (nativeDamage["physical"] > 0d) return AutoFocus("physical");
        }

        // No native damage row means no element claim. In particular, generic
        // English verbs are deliberately not an elemental fallback.
        return new HeroFocus("hybrid", UiText.L("균형·혼합", "Balanced / Hybrid", "均衡/混合", "均衡/混合"), "Balanced / Hybrid", PhysicalWords.Concat(ElementalWords).ToArray());
    }

    private static readonly object NativeSkillTagNameSync = new();
    private static Dictionary<int, string>? nativeSkillTagNames;

    private static bool HasNativeSkillTag(IEnumerable<int> tagIds, params string[] authoritativeNames)
    {
        var names = GetNativeSkillTagNames();
        var expected = authoritativeNames
            .Select(NormalizeSkillDependencyText)
            .Where(name => name.Length > 0)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        return tagIds.Any(id => names.TryGetValue(id, out var name) && expected.Contains(name));
    }

    private static bool SkillHasNativeTagCore(int skillId, params string[] authoritativeNames)
    {
        if (skillId <= 0) return false;
        var row = InvokeStatic("TableData", "getTSkillData", skillId);
        var infoId = ReadNullableInt(row, "infoId") ?? 0;
        var info = infoId > 0 ? InvokeStatic("TableData", "getTSkillInfoData", infoId) : null;
        var tags = ReadSequence(Read(info, "tagArr")).Select(ToInt).Where(value => value > 0);
        return HasNativeSkillTag(tags, authoritativeNames);
    }

    private static NativeControlledEntityKind ClassifyNativeSummonType(int summonType)
        => summonType switch
        {
            1 => NativeControlledEntityKind.Minion,
            2 => NativeControlledEntityKind.Ally,
            > 0 => NativeControlledEntityKind.OtherSummon,
            _ => NativeControlledEntityKind.None
        };

    private static NativeControlledEntityKind GetNativeControlledEntityKindsForSkillCore(int skillId)
    {
        if (skillId <= 0) return NativeControlledEntityKind.None;
        var skill = InvokeStatic("TableData", "getTSkillData", skillId);
        var infoId = ReadNullableInt(skill, "infoId") ?? 0;
        var info = infoId > 0 ? InvokeStatic("TableData", "getTSkillInfoData", infoId) : null;
        return info is null
            ? NativeControlledEntityKind.None
            : GetNativeControlledEntityKindsForSkillInfoCore(info);
    }

    private static NativeControlledEntityKind GetNativeControlledEntityKindsForSkillInfoCore(object info)
    {
        var result = NativeControlledEntityKind.None;
        var tagIds = ReadSequence(Read(info, "tagArr")).Select(ToInt).Where(id => id > 0).ToHashSet();
        var actionId = ReadNullableInt(info, "actionId") ?? 0;
        var action = actionId > 0 ? InvokeStatic("TableData", "getTActionData", actionId) : null;
        if (action is not null
            && (ReadNullableInt(action, "type") ?? 0) == 3
            && (ReadNullableInt(action, "emitterId") ?? 0) > 0
            && HasNativeSkillTag(tagIds, "totem"))
            result |= NativeControlledEntityKind.Totem;

        var produceIds = new HashSet<int>();
        var actionProduceId = ReadNullableInt(action, "produceId") ?? 0;
        if (actionProduceId > 0) produceIds.Add(actionProduceId);
        // CombatUnit.CreateBuddyProduce(SkillData) is the native no-action
        // companion path. Validate every otherParam against TProduce's native
        // summon tuple below instead of requiring an English tag first. An
        // unrelated parameter has no valid TProduce/6001/6002 relationship and
        // is therefore discarded without becoming a summon.
        if (actionId <= 0)
            produceIds.UnionWith(ReadSequence(Read(info, "otherParam"))
                .Select(ToInt).Where(id => id > 0));

        foreach (var produceId in produceIds)
        {
            var produce = InvokeStatic("TableData", "getTProduceData", produceId);
            if (produce is null) continue;
            var rows = ReadFloatMatrixRows(Read(produce, "attrArr"), 2);
            var summonId = rows.Where(row => row.Length >= 2
                                             && Convert.ToInt32(row[0], CultureInfo.InvariantCulture) == 6001)
                .Select(row => Convert.ToInt32(row[1], CultureInfo.InvariantCulture))
                .FirstOrDefault(id => id > 0);
            var summonCount = rows.Where(row => row.Length >= 2
                                                && Convert.ToInt32(row[0], CultureInfo.InvariantCulture) == 6002)
                .Select(row => Convert.ToInt32(row[1], CultureInfo.InvariantCulture))
                .FirstOrDefault(value => value > 0);
            if (summonId <= 0 || summonCount <= 0) continue;
            var summon = InvokeStatic("TableData", "getTSummonData", summonId);
            result |= ClassifyNativeSummonType(ReadNullableInt(summon, "type") ?? 0);
        }
        return result;
    }

    private static NativeControlledEntityKind GetNativeControlledEntityKindsForSkillsCore(
        IEnumerable<int> skillIds)
    {
        var result = NativeControlledEntityKind.None;
        foreach (var skillId in skillIds.Where(id => id > 0).Distinct())
            result |= GetNativeControlledEntityKindsForSkillCore(skillId);
        return result;
    }

    private static Dictionary<int, string> GetNativeSkillTagNames()
    {
        lock (NativeSkillTagNameSync)
        {
            if (nativeSkillTagNames is not null) return nativeSkillTagNames;
            nativeSkillTagNames = ReadValues(ReadStatic("TableData", "TSkillTagDict"))
                .Select(row => (Id: ReadNullableInt(row, "id") ?? 0,
                    Name: NormalizeSkillDependencyText(
                        EnglishName(row, ReadString(row, "name") ?? string.Empty) ?? string.Empty)))
                .Where(entry => entry.Id > 0 && entry.Name.Length > 0)
                .GroupBy(entry => entry.Id)
                .ToDictionary(group => group.Key, group => group.First().Name,
                    EqualityComparer<int>.Default);
            return nativeSkillTagNames;
        }
    }

    private static void AddSkillText(object? skill, List<string> parts)
    {
        if (skill is null) return;
        var row = Read(skill, "tSkillData") ?? skill;
        var info = Read(skill, "tSkillInfoData")
                   ?? (ReadNullableInt(row, "infoId") is > 0 and var infoId ? InvokeStatic("TableData", "getTSkillInfoData", infoId) : null);
        parts.Add(ReadString(row, "name") ?? string.Empty);
        parts.Add(EnglishName(row, string.Empty) ?? string.Empty);
        parts.Add(ReadString(info, "des") ?? string.Empty);
        parts.Add(EnglishText(info, "_des", string.Empty) ?? string.Empty);
    }

    private static object? GetPreferredBuild(object hero, HeroFocus? focus = null)
    {
        var jobId = ReadNullableInt(Read(hero, "saveHeroData"), "jobId") ?? ReadNullableInt(Read(hero, "tHeroJobData"), "id") ?? 0;
        focus ??= DetermineHeroFocus(hero);
        var builds = ReadValues(ReadStatic("TableData", "TBuildsDict"))
            .Where(build => ReadNullableInt(build, "jobId") == jobId).ToList();
        if (builds.Count == 0) return null;
        var unlocked = builds.Where(build => !ReadRequiredBoolProperty(build, "isLock")).ToList();
        // A locked guide can describe skills, rows or equipment the current
        // hero cannot legally use. Never select one merely because no guide is
        // unlocked yet.
        builds = unlocked;
        if (builds.Count == 0) return null;

        var saveHero = Read(hero, "saveHeroData");
        var baseTalentId = ReadNullableInt(saveHero, "baseSkillId") ?? 0;
        var invested = ReadValues(Read(Read(hero, "heroTalentData"), "talentDic"))
            .Where(talent => GetSpentTalentPoints(talent) > 0 || GetTalentLevel(talent) > 0)
            .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
            .Where(id => id > 0).ToHashSet();

        var ranked = builds.Select(build =>
            {
                var skillIds = ReadRequiredSequenceProperty(build, "skillArr").Select(ToInt).Where(id => id > 0).ToList();
                var masteryIds = ReadRequiredSequenceProperty(build, "masteryArr").Select(ToInt).Where(id => id > 0).ToList();
                var guideIds = skillIds.Concat(masteryIds).ToHashSet();
                var textParts = new List<string>
                {
                    ReadString(build, "name") ?? string.Empty,
                    ReadString(build, "des") ?? string.Empty,
                    EnglishName(build, string.Empty) ?? string.Empty,
                    EnglishText(build, "_des", string.Empty) ?? string.Empty
                };
                foreach (var talentId in guideIds)
                    textParts.Add(GetTalentDefinitionText(InvokeStatic("TableData", "getTTalentData", talentId)));
                var text = Clean(string.Join(" ", textParts)).ToLowerInvariant();
                var themeEvidence = KeywordScore(text, focus.Keywords);
                var score = themeEvidence * (focus.IsManual ? 1500d : 520d);
                // A manually selected theme is an instruction to change builds.
                // Letting the currently invested nodes dominate here creates a
                // circular choice (for example, an old Lightning setup keeps
                // winning after the user explicitly selects Fire). In Auto mode
                // the existing build remains useful evidence for choosing among
                // otherwise similar guides.
                if (!focus.IsManual) score += guideIds.Count(invested.Contains) * 1150d;
                var buildBaseIds = skillIds.Where(id => IsBaseSkillDefinition(InvokeStatic("TableData", "getTTalentData", id))).ToHashSet();
                if (!focus.IsManual && baseTalentId > 0 && buildBaseIds.Contains(baseTalentId)) score += 3600d;
                else if (!focus.IsManual && baseTalentId > 0 && buildBaseIds.Count > 0) score -= 2600d;
                score -= (ReadNullableInt(build, "index") ?? 0) * 0.01d;
                return (Build: build, Score: score, ThemeEvidence: themeEvidence);
            })
            .OrderByDescending(entry => entry.Score)
            .ThenBy(entry => ReadNullableInt(entry.Build, "index") ?? int.MaxValue)
            .ToList();
        var winner = ranked.FirstOrDefault();
        // A manual theme is an explicit constraint. Returning the first guide
        // on a zero-keyword tie used to label unrelated guides as Fire/Defense
        // and then reset the hero around a build that did not support the
        // selected theme.
        if (winner.Build is null || (focus.IsManual && winner.ThemeEvidence <= 0)) return null;
        return winner.Build;
    }

    private static PreferredTalentPlan GetPreferredTalentPlan(object hero, HeroFocus focus)
    {
        var build = GetPreferredBuild(hero, focus);
        var skillTalentIds = build is null
            ? new List<int>()
            : ReadRequiredSequenceProperty(build, "skillArr").Select(ToInt).Where(id => id > 0).Distinct().ToList();
        var masteryTalentIds = build is null
            ? new List<int>()
            : ReadRequiredSequenceProperty(build, "masteryArr").Select(ToInt).Where(id => id > 0).Distinct().ToList();
        var preferredSkillIds = skillTalentIds
            .Select(id => InvokeStatic("TableData", "getTTalentData", id))
            .Select(row => ReadNullableInt(row, "skillId") ?? 0)
            .Where(id => id > 0).ToHashSet();
        var buildName = build is null
            ? UiText.L("사용자 빌드", "Custom build", "自定义流派", "自訂流派")
            : Clean(ReadString(build, "name") ?? EnglishName(build, UiText.L("추천 빌드", "Recommended build", "推荐流派", "推薦流派")) ?? UiText.L("추천 빌드", "Recommended build", "推荐流派", "推薦流派"));
        return new PreferredTalentPlan(build, skillTalentIds, masteryTalentIds, preferredSkillIds, buildName);
    }

    private static PreferredTalentPlan GetPerformanceTalentPlan(
        object hero,
        HeroFocus focus,
        int totalTalentPoints,
        bool includeInitialMasteryScores = true)
    {
        // Capture the native talent census and neutral AttrData in one coherent
        // Unity-thread snapshot. Performing each property/table read as a
        // separate gateway request previously spent tens of seconds waiting for
        // frames before the first skill candidate was even evaluated.
        var setup = MainThreadNativeGateway.Invoke(() =>
        {
            var capturedSaveHero = ReadRequiredProperty(hero, "saveHeroData")
                                   ?? throw new InvalidOperationException("SaveHeroData is unavailable.");
            var capturedJobId = ReadRequiredIntProperty(capturedSaveHero, "jobId");
            if (capturedJobId <= 0)
                throw new InvalidOperationException("The hero job ID is unavailable.");
            var capturedTalentData = ReadRequiredProperty(hero, "heroTalentData")
                                     ?? throw new InvalidOperationException("HeroTalentData is unavailable.");
            var capturedGridTalents = ReadValues(ReadRequiredProperty(capturedTalentData, "talentDic"))
                .DistinctBy(talent => NativeObjectKey(talent, talent)).ToList();

            // The native shrine pool is every same-job, type-1, non-base TTalent.
            // Do not narrow that pool with the current loadout, current skills,
            // names, or official build rows before the common native preview.
            var capturedBaseRows = capturedGridTalents
                .Where(talent => !IsTalentLockedRequired(talent))
                .Select(talent => Read(talent, "tTalentData"))
                .Where(IsBaseSkillDefinition).Cast<object>()
                .DistinctBy(row => ReadNullableInt(row, "id") ?? 0)
                .ToList();
            var capturedCurrentActiveTalents = GetTransformableTalents(capturedTalentData)
                .Where(talent => !IsTalentLockedRequired(talent)).ToList();
            var currentActiveTalentIds = capturedCurrentActiveTalents
                .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var preservedTalentIds = GetTransformableTalents(capturedTalentData)
                .Where(IsTalentUnreplaceable)
                .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var heroLevel = ReadRequiredIntProperty(capturedSaveHero, "level");
            var capturedActiveRows = ReadValues(ReadStatic("TableData", "TTalentDict"))
                .Where(IsTransformableSkillDefinition).Cast<object>()
                .Where(row => (ReadNullableInt(row, "jobId") ?? 0) == capturedJobId)
                .Where(row =>
                {
                    var id = ReadNullableInt(row, "id") ?? 0;
                    if (id <= 0 || (preservedTalentIds.Contains(id)
                                   && !currentActiveTalentIds.Contains(id))) return false;
                    return heroLevel > 1 || currentActiveTalentIds.Contains(id)
                                         || (ReadNullableInt(row, "floor") ?? 0) == 1;
                })
                .GroupBy(row => ReadNullableInt(row, "skillId") ?? 0)
                .Where(group => group.Key > 0)
                .Select(group => group.OrderBy(row => ReadNullableInt(row, "index") ?? int.MaxValue)
                    .ThenBy(row => ReadNullableInt(row, "id") ?? int.MaxValue).First())
                .ToList();
            var capturedObjectiveAttr = CreateGearAndTalentNeutralObjectiveAttr(
                hero, capturedGridTalents);
            return new
            {
                SaveHero = capturedSaveHero,
                JobId = capturedJobId,
                TalentData = capturedTalentData,
                GridTalents = capturedGridTalents,
                BaseRows = capturedBaseRows,
                ActiveRows = capturedActiveRows,
                CurrentActiveTalents = capturedCurrentActiveTalents,
                ObjectiveAttr = capturedObjectiveAttr
            };
        });
        var saveHero = setup.SaveHero;
        var jobId = setup.JobId;
        var talentData = setup.TalentData;
        var gridTalents = setup.GridTalents;
        var baseRows = setup.BaseRows;
        var activeRows = setup.ActiveRows;
        var currentActiveTalents = setup.CurrentActiveTalents;
        if (baseRows.Count == 0 || activeRows.Count == 0)
            throw new InvalidOperationException($"No compatible unlocked performance skill pool is available (base={baseRows.Count}, active={activeRows.Count}).");

        var objectiveAttr = setup.ObjectiveAttr;
        const int defaultSkillLevel = 1;
        var objectiveScores = new Dictionary<int, double>();
        var nativeRolesByTalentId = new Dictionary<int, NativeSkillRoleProfile>();
        var rankableRows = new List<object>();
#if PATHOFIDLE_RUNTIME_TEST
        const int runtimeRejectionDetailLimit = 2200;
        var runtimeBaseTalentIds = baseRows
            .Select(row => ReadNullableInt(row, "id") ?? 0)
            .Where(id => id > 0).ToHashSet();
        var runtimeRejectionDetails = new StringBuilder();
        var runtimeOmittedRejections = 0;
#endif
        void RecordCandidateRejection(int talentId, int skillId, string reason, bool? previewComplete = null)
        {
#if PATHOFIDLE_RUNTIME_TEST
            var compactFailure = Regex.Replace(reason, @"\s+", " ").Trim();
            if (compactFailure.Length > 180) compactFailure = compactFailure[..177] + "...";
            var rejection = $"{(runtimeBaseTalentIds.Contains(talentId) ? "base" : "active")}:talent={talentId},skill={skillId},reason={compactFailure}";
            var separatorLength = runtimeRejectionDetails.Length == 0 ? 0 : 3;
            if (runtimeRejectionDetails.Length + separatorLength + rejection.Length <= runtimeRejectionDetailLimit)
            {
                if (separatorLength > 0) runtimeRejectionDetails.Append(" | ");
                runtimeRejectionDetails.Append(rejection);
            }
            else
            {
                runtimeOmittedRejections++;
            }
#endif
            Plugin.DiagDebug(
                $"AUTO-SKILLS PERFORMANCE CANDIDATE REJECTED|talent={talentId}|skill={skillId}|rankable=false|previewComplete={previewComplete?.ToString() ?? "unavailable"}|{reason}");
        }

        // Build a neutral census of every compatible native skill before ranking
        // packages. This bounded job pool is mandatory: stopping after the current
        // loadout would make an incumbent skill win merely because it was visited
        // first, even when an unvisited alternative has the better 30-second result.
        var nativeSummonTalentIds = focus.Key == "minion"
            ? MainThreadNativeGateway.Invoke(() => activeRows
                .Where(row => HasNativeSummonDefinitionCore(
                    hero,
                    ReadNullableInt(row, "skillId") ?? 0,
                    defaultSkillLevel,
                    objectiveAttr,
                    false,
                    null))
                .Select(row => ReadNullableInt(row, "id") ?? 0)
                .Where(id => id > 0).ToHashSet())
            : new HashSet<int>();
        var performanceRows = baseRows.Concat(activeRows)
            .OrderByDescending(row => nativeSummonTalentIds.Contains(
                ReadNullableInt(row, "id") ?? 0))
            .ThenByDescending(IsBaseSkillDefinition)
            .ThenBy(row => ReadNullableInt(row, "index") ?? int.MaxValue)
            .ThenBy(row => ReadNullableInt(row, "id") ?? int.MaxValue)
            .ToList();
        const int performanceSkillNativeBatchSize = 1;
        for (var offset = 0; offset < performanceRows.Count; offset += performanceSkillNativeBatchSize)
        {
            ThrowIfAutoBuildCancellationRequested();
            var batch = performanceRows.Skip(offset).Take(performanceSkillNativeBatchSize).ToList();
            var batchResults = MainThreadNativeGateway.Invoke(() =>
            {
                var results = new List<(object Row, int TalentId, int SkillId, double Score, NativeSkillRoleProfile? Role, string? Failure, bool? Complete)>();
                foreach (var row in batch)
                {
                    var talentId = 0;
                    var skillId = 0;
                    try
                    {
                        talentId = ReadNullableInt(row, "id") ?? 0;
                        skillId = ReadNullableInt(row, "skillId") ?? 0;
                        if (talentId <= 0 || skillId <= 0) continue;
                        var isNativeSummon = nativeSummonTalentIds.Contains(talentId);
                        var role = ReadNativeSkillRoleProfile(
                            hero, skillId, defaultSkillLevel, objectiveAttr, false);
                        var hasRequiredManualRole = HasFocusedRoleConstraint(focus)
                                                    && HasRequiredManualSkillRoleSignal(role, focus, row);
                        var hasNativePackageEvidence = HasFocusedRoleConstraint(focus)
                                                       && (HasProvenNativeRoleSignal(role)
                                                           || SkillHasNativeTagCore(
                                                               skillId,
                                                               "martial", "spell", "utility", "support",
                                                               "buff", "debuff", "affliction", "minion", "ally", "aura",
                                                               "warcry", "curse", "totem", "archery"));
                        if (!IsNativeRoleRankable(role, focus) && !isNativeSummon
                                                                  && !hasRequiredManualRole
                                                                  && !hasNativePackageEvidence)
                        {
                            results.Add((row, talentId, skillId, double.NegativeInfinity, role,
                                role.Failure ?? "no proven native output", role.IsComplete));
                            continue;
                        }
                        var score = ScoreNativeSkillRoleObjective(role, focus) * 10000d;
                        if (double.IsFinite(score))
                            results.Add((row, talentId, skillId, Math.Max(0d, score), role, null, role.IsComplete));
                        else if (isNativeSummon)
                            results.Add((row, talentId, skillId, 0d, role, null, role.IsComplete));
                        else
                            results.Add((row, talentId, skillId, double.NegativeInfinity, role,
                                "native objective is not finite", role.IsComplete));
                    }
                    catch (Exception error)
                    {
                        // The action -> produce -> summon identity is sufficient to
                        // keep the candidate. A numeric preview gap changes only its score.
                        if (nativeSummonTalentIds.Contains(talentId))
                            results.Add((row, talentId, skillId, 0d, null, null, false));
                        else
                            results.Add((row, talentId, skillId, double.NegativeInfinity, null,
                                error.GetBaseException().Message, null));
                    }
                }
                return results;
            });
            foreach (var result in batchResults)
            {
                if (result.Failure is not null)
                {
                    RecordCandidateRejection(
                        result.TalentId, result.SkillId, result.Failure, result.Complete);
                    continue;
                }
                objectiveScores[result.TalentId] = result.Score;
                if (result.Role is not null)
                    nativeRolesByTalentId[result.TalentId] = result.Role;
                rankableRows.Add(result.Row);
            }
            ReportAutoBuildProgress(
                AutoBuildStep.CollectingCandidates,
                Math.Min(offset + batch.Count, performanceRows.Count),
                performanceRows.Count,
                UiText.L("스킬 후보 계산 중", "Evaluating skill candidates", "正在计算技能候选", "正在計算技能候選"));
        }
        baseRows = baseRows.Where(row => rankableRows.Contains(row)).ToList();
        activeRows = activeRows.Where(row => rankableRows.Contains(row)).ToList();
        if (baseRows.Count == 0 || activeRows.Count == 0)
#if PATHOFIDLE_RUNTIME_TEST
        {
            if (runtimeOmittedRejections > 0)
                runtimeRejectionDetails.Append($" | +{runtimeOmittedRejections} omitted");
            throw new InvalidOperationException(
                $"No rankable native performance preview remains (base={baseRows.Count}, active={activeRows.Count}); rejected=[{runtimeRejectionDetails}].");
        }
#else
            throw new InvalidOperationException(
                $"No rankable native performance preview remains (base={baseRows.Count}, active={activeRows.Count}).");
#endif
        // Ranking still uses every completed native preview, but all row/table
        // reads belong to one immutable post-census snapshot rather than dozens
        // of frame-separated gateway requests.
        var skillSelection = MainThreadNativeGateway.Invoke(() =>
        {
            bool HasRequiredThemeSignal(object row)
            {
                var talentId = ReadNullableInt(row, "id") ?? 0;
                if (nativeRolesByTalentId.TryGetValue(talentId, out var role)
                    && HasRequiredManualSkillRoleSignal(role, focus, row))
                    return true;
                // A combat-AI numeric preview can fail after the native graph
                // has already proven an Ally/Totem/Minion spawn. Keep that
                // structural fact in the theme contract with a zero lower-bound
                // score; later complete-package evaluation still decides rank.
                return focus.Key == "minion"
                       && nativeSummonTalentIds.Contains(talentId);
            }

            var themeBaseRows = HasFocusedRoleConstraint(focus)
                ? baseRows.Where(HasRequiredThemeSignal).ToList()
                : new List<object>();
            var themeActiveRows = HasFocusedRoleConstraint(focus)
                ? activeRows.Where(HasRequiredThemeSignal).ToList()
                : new List<object>();
            if (HasFocusedRoleConstraint(focus) && themeBaseRows.Count == 0 && themeActiveRows.Count == 0)
                throw new InvalidOperationException(
                    $"No native {focus.English} skill signal is available for this hero; the selected theme was not applied.");
            var capturedRequiredBaseSkillIds = themeBaseRows
                .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var capturedRequiredActiveSkillIds = themeActiveRows
                .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                .Where(id => id > 0).ToHashSet();
            // Native tags/output identify the theme's core skills. Then use the
            // game's own unlocked build table as a relationship graph: skills
            // listed beside a core skill are its authored support package. This
            // is substantially safer than treating translated item/skill words
            // as synergy, and it prevents a one-summon-plus-four-unrelated-skills
            // result while still letting the numerical preview rank alternatives.
            var capturedThemePackageSkillIds = new HashSet<int>();
            var capturedThemeGuideName = string.Empty;
            if (HasFocusedRoleConstraint(focus))
            {
                var coreTalentIds = themeBaseRows.Concat(themeActiveRows)
                    .Select(row => ReadNullableInt(row, "id") ?? 0)
                    .Where(id => id > 0).ToHashSet();
                var guide = ReadValues(ReadStatic("TableData", "TBuildsDict"))
                    .Where(build => (ReadNullableInt(build, "jobId") ?? 0) == jobId)
                    .Where(build => !ReadRequiredBoolProperty(build, "isLock"))
                    .Select(build =>
                    {
                        var ids = ReadRequiredSequenceProperty(build, "skillArr")
                            .Select(ToInt).Where(id => id > 0).Distinct().ToList();
                        var coreIds = ids.Where(coreTalentIds.Contains).ToList();
                        var coreScore = coreIds.Sum(id => Math.Max(0d,
                            objectiveScores.GetValueOrDefault(id)));
                        var packageScore = ids.Sum(id => Math.Max(0d,
                            objectiveScores.GetValueOrDefault(id)));
                        return (Build: build, Ids: ids, CoreIds: coreIds,
                            CoreScore: coreScore, PackageScore: packageScore);
                    })
                    .Where(entry => entry.CoreIds.Count > 0)
                    .OrderByDescending(entry => entry.CoreScore)
                    .ThenByDescending(entry => entry.CoreIds.Count)
                    .ThenByDescending(entry => entry.PackageScore)
                    .ThenBy(entry => ReadNullableInt(entry.Build, "index") ?? int.MaxValue)
                    .FirstOrDefault();
                if (guide.Build is not null)
                {
                    capturedThemeGuideName = Clean(
                        EnglishName(guide.Build, ReadString(guide.Build, "name") ?? string.Empty)
                        ?? string.Empty);
                    foreach (var talentId in guide.Ids)
                    {
                        var guideRow = InvokeStatic("TableData", "getTTalentData", talentId);
                        var guideSkillId = ReadNullableInt(guideRow, "skillId") ?? 0;
                        if (guideSkillId > 0) capturedThemePackageSkillIds.Add(guideSkillId);
                    }
                }
            }
            // If the game has no unlocked authored package for this native core,
            // fall back to the core set itself. When a guide does exist, do not
            // let another same-tag skill count as one of that guide's synergy
            // slots (for example Iron Guard cannot stand in for the Archer Guard
            // build's Motivational Warcry relationship).
            if (capturedThemePackageSkillIds.Count == 0)
                capturedThemePackageSkillIds.UnionWith(
                    capturedRequiredBaseSkillIds.Concat(capturedRequiredActiveSkillIds));
            // A focused damage theme uses a native-aligned base whenever the
            // job exposes one. Previously the highest isolated base could stay
            // off-theme while a single active skill was used as the token core.
            var selectedBasePool = themeBaseRows.Count > 0 ? themeBaseRows : baseRows;
            var selectedBase = selectedBasePool
                .OrderByDescending(row => objectiveScores[ReadNullableInt(row, "id") ?? 0])
                .ThenBy(row => ReadNullableInt(row, "index") ?? int.MaxValue)
                .First();
            var capturedSelectedBaseId = ReadNullableInt(selectedBase, "id") ?? 0;
            var capturedOrderedActiveRows = activeRows
                .OrderByDescending(row => objectiveScores[ReadNullableInt(row, "id") ?? 0])
                .ThenBy(row => ReadNullableInt(row, "index") ?? int.MaxValue)
                .ToList();
            var capturedSkillTalentIds = new[] { capturedSelectedBaseId }
                .Concat(capturedOrderedActiveRows.Select(row => ReadNullableInt(row, "id") ?? 0))
                .Where(id => id > 0).Distinct().ToList();
            var capturedSkillIds = capturedSkillTalentIds
                .Select(id => InvokeStatic("TableData", "getTTalentData", id))
                .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var capturedObjectiveSkillIds = new[] { ReadNullableInt(selectedBase, "skillId") ?? 0 }
                .Concat(capturedOrderedActiveRows
                    .Take(Math.Max(1, currentActiveTalents.Count))
                    .Select(row => ReadNullableInt(row, "skillId") ?? 0))
                .Where(id => id > 0).Distinct().ToList();
            return new
            {
                RequiredBaseSkillIds = capturedRequiredBaseSkillIds,
                RequiredActiveSkillIds = capturedRequiredActiveSkillIds,
                ThemePackageSkillIds = capturedThemePackageSkillIds,
                ThemeGuideName = capturedThemeGuideName,
                SelectedBaseId = capturedSelectedBaseId,
                OrderedActiveRows = capturedOrderedActiveRows,
                SkillTalentIds = capturedSkillTalentIds,
                SkillIds = capturedSkillIds,
                ObjectiveSkillIds = capturedObjectiveSkillIds
            };
        });
        var requiredBaseSkillIds = skillSelection.RequiredBaseSkillIds;
        var requiredActiveSkillIds = skillSelection.RequiredActiveSkillIds;
        var themePackageSkillIds = skillSelection.ThemePackageSkillIds;
        var themeGuideName = skillSelection.ThemeGuideName;
        var selectedBaseId = skillSelection.SelectedBaseId;
        var orderedActiveRows = skillSelection.OrderedActiveRows;
        var skillTalentIds = skillSelection.SkillTalentIds;
        var skillIds = skillSelection.SkillIds;
        var objectiveSkillIds = skillSelection.ObjectiveSkillIds;

        var masteryTalentIds = new List<int>();
        if (includeInitialMasteryScores)
        {
            var masteryRows = gridTalents
                .Where(talent => !IsTalentLockedRequired(talent))
                .Where(talent => (ReadNullableInt(Read(talent, "tTalentData"), "type") ?? 0) == 2)
                .Where(talent => (ReadNullableInt(Read(talent, "tTalentData"), "masteryId") ?? 0) > 0)
                .Where(talent => GetTalentLevelCap(talent) - GetTalentBaseLevelRequired(talent) > 0)
                .ToList();
            // The unchanged package baseline is identical for every mastery in
            // this first-pass plan. Reusing it keeps the exact native objective
            // while avoiding one complete skill-package rebuild per mastery.
            var baselineSkillIds = objectiveSkillIds.ToList();
            var masteryBaselinePackageScore = MainThreadNativeGateway.Invoke(() =>
                ScoreSkillPackageObjective(
                    hero, baselineSkillIds, objectiveAttr, focus, null));
            const int performanceMasteryNativeBatchSize = 4;
            var scoredMasteries = new List<(int Id, double Score, int Floor)>();
            for (var offset = 0; offset < masteryRows.Count; offset += performanceMasteryNativeBatchSize)
            {
                ThrowIfAutoBuildCancellationRequested();
                var batch = masteryRows.Skip(offset).Take(performanceMasteryNativeBatchSize).ToList();
                var batchScores = ScoreMasteryTalentCandidateBatchForObjective(
                    hero, batch, focus, objectiveAttr, objectiveSkillIds, null,
                    masteryBaselinePackageScore);
                foreach (var entry in batchScores)
                {
                    objectiveScores[entry.Id] = entry.Score;
                    scoredMasteries.Add(entry);
                }
                ReportAutoBuildProgress(
                    AutoBuildStep.CollectingCandidates,
                    Math.Min(offset + batch.Count, masteryRows.Count),
                    masteryRows.Count,
                    UiText.L("스킬·마스터리 계산 중", "Evaluating skills and masteries", "正在计算技能与专精", "正在計算技能與專精"));
            }
            var positiveMasteries = scoredMasteries
                // A zero/negative mastery is not merely a low priority: it does
                // not lead the ranking for this hero's selected objective.
                .Where(entry => entry.Id > 0 && double.IsFinite(entry.Score) && entry.Score > 0.000001d)
                .OrderByDescending(entry => entry.Score)
                .ThenBy(entry => entry.Floor)
                .ToList();
            // Keep a bounded reserve of legal rows even when their isolated
            // delta is zero or negative. The exact nonlinear allocator uses
            // them only if the preferred skills/masteries cannot absorb the
            // entire paid budget, avoiding an otherwise impossible N-1/N plan.
            masteryTalentIds = positiveMasteries
                .Concat(scoredMasteries
                    .Where(entry => entry.Id > 0 && double.IsFinite(entry.Score))
                    .OrderByDescending(entry => entry.Score)
                    .ThenBy(entry => entry.Floor)
                    .ThenBy(entry => entry.Id))
                .DistinctBy(entry => entry.Id)
                .Take(Math.Min(8, Math.Max(0,
                    totalTalentPoints - objectiveSkillIds.Count)))
                .Select(entry => entry.Id)
                .ToList();
        }
        var label = UiText.L("성능 목표", "Performance objective", "性能目标", "效能目標");
        Plugin.DiagInfo($"AUTO-SKILLS PERFORMANCE POOL|job={jobId}|focus={focus.English}|base={selectedBaseId}|activeCandidates={activeRows.Count}|nativeGuide={themeGuideName}|core={string.Join(',', requiredBaseSkillIds.Concat(requiredActiveSkillIds).OrderBy(id => id))}|package={string.Join(',', themePackageSkillIds.OrderBy(id => id))}|summonDetails={string.Join(';', nativeRolesByTalentId.Where(entry => entry.Value.Summon).Select(entry => $"{ReadNullableInt(InvokeStatic("TableData", "getTTalentData", entry.Key), "skillId") ?? 0}[damage={entry.Value.SummonDamage:0.###},survival={entry.Value.SummonSurvival:0.###},attack={string.Join(',', (entry.Value.SummonAttackByType ?? new Dictionary<int, double>()).OrderBy(value => value.Key).Select(value => $"{value.Key}:{value.Value:0.##}"))},complete={entry.Value.IsComplete},failure={entry.Value.Failure.Replace('|', '/')}]"))}|scores={string.Join(',', skillTalentIds.Take(12).Select(id => $"{id}:{objectiveScores[id]:0.0}"))}");
        return new PreferredTalentPlan(
            null, skillTalentIds, masteryTalentIds, skillIds, label, objectiveScores,
            RequiredActiveSkillIds: requiredActiveSkillIds,
            RequiredBaseSkillIds: requiredBaseSkillIds,
            ThemePackageSkillIds: themePackageSkillIds,
            NativeRolesBySkillId: nativeRolesByTalentId
                .Select(entry => (
                    SkillId: ReadNullableInt(
                        InvokeStatic("TableData", "getTTalentData", entry.Key),
                        "skillId") ?? 0,
                    entry.Value))
                .Where(entry => entry.SkillId > 0)
                .GroupBy(entry => entry.SkillId)
                .ToDictionary(group => group.Key, group => group.First().Value));
    }

    private static PreferredTalentPlan RebuildMasteryPlanForSelectedSkills(
        object hero,
        HeroFocus focus,
        int totalTalentPoints,
        PreferredTalentPlan preferred,
        object? objectiveAttrOverride = null,
        IReadOnlyCollection<GearCandidate>? candidateItems = null)
    {
        var talentData = ReadRequiredProperty(hero, "heroTalentData")
                         ?? throw new InvalidOperationException("HeroTalentData is unavailable.");
        var gridTalents = ReadValues(ReadRequiredProperty(talentData, "talentDic"))
            .DistinctBy(talent => NativeObjectKey(talent, talent)).ToList();
        var selectedSkillIds = preferred.PreferredSkillIds.Where(id => id > 0).Distinct().ToList();
        if (selectedSkillIds.Count == 0) return preferred with { MasteryTalentIds = new List<int>() };
        var mandatoryActivePointCount = preferred.SkillTalentIds
            .Select(id => InvokeStatic("TableData", "getTTalentData", id))
            .Where(IsTransformableSkillDefinition)
            .Select(row => ReadNullableInt(row, "skillId") ?? 0)
            .Where(id => id > 0).Distinct().Count();

        var objectiveAttr = objectiveAttrOverride ?? CreateGearAndTalentNeutralObjectiveAttr(hero, gridTalents);
        var objectiveScores = preferred.ObjectiveScores is null
            ? new Dictionary<int, double>()
            : new Dictionary<int, double>(preferred.ObjectiveScores);
        // The unchanged package baseline is identical for every mastery row in
        // this package. Compute its native 30-second objective once instead of
        // rebuilding the same strict skill graph for every candidate mastery.
        var masteryCandidates = gridTalents
            .Where(talent => !IsTalentLockedRequired(talent))
            .Where(talent => (ReadNullableInt(Read(talent, "tTalentData"), "type") ?? 0) == 2)
            .Where(talent => (ReadNullableInt(Read(talent, "tTalentData"), "masteryId") ?? 0) > 0)
            .Where(talent => GetTalentLevelCap(talent) - GetTalentBaseLevelRequired(talent) > 0)
            .OrderByDescending(talent => GetSavedTalentLevel(talent) > 0)
            .ThenByDescending(GetSavedTalentLevel)
            .ThenBy(talent => ReadNullableInt(Read(talent, "tTalentData"), "floor") ?? int.MaxValue)
            .ThenBy(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? int.MaxValue)
            .ToList();
        ReportAutoBuildProgress(
            AutoBuildStep.CollectingCandidates,
            0,
            masteryCandidates.Count,
            UiText.L("선택 스킬 기준값 계산 중", "Evaluating the selected skill baseline", "正在计算所选技能基准", "正在計算所選技能基準"));
        var baselineSkillIds = selectedSkillIds.ToList();
        var baselineItems = candidateItems?.ToList();
        var baselinePackageScore = MainThreadNativeGateway.Invoke(() =>
            ScoreSkillPackageObjective(
                hero, baselineSkillIds, objectiveAttr, focus, baselineItems));
        const int masteryNativeBatchSize = 1;
        var scoredMasteries = new List<(int Id, double Score, int Floor)>();
        for (var offset = 0; offset < masteryCandidates.Count; offset += masteryNativeBatchSize)
        {
            ThrowIfAutoBuildCancellationRequested();
            var batch = masteryCandidates.Skip(offset).Take(masteryNativeBatchSize).ToList();
            var batchScores = ScoreMasteryTalentCandidateBatchForObjective(
                hero, batch, focus, objectiveAttr, selectedSkillIds, candidateItems,
                baselinePackageScore);
            foreach (var entry in batchScores)
            {
                objectiveScores[entry.Id] = entry.Score;
                scoredMasteries.Add(entry);
            }
            ReportAutoBuildProgress(
                AutoBuildStep.CollectingCandidates,
                Math.Min(offset + batch.Count, masteryCandidates.Count),
                masteryCandidates.Count,
                UiText.L("마스터리 시너지 계산 중", "Evaluating mastery synergy", "正在计算专精协同", "正在計算專精協同"));
            if (scoredMasteries.Count > 0 && AutoBuildSearchDeadlineReached()) break;
        }
        var rankedRows = scoredMasteries
            .Where(entry => entry.Id > 0 && double.IsFinite(entry.Score) && entry.Score > 0.000001d)
            .OrderByDescending(entry => entry.Score)
            .ThenBy(entry => entry.Floor)
            .ToList();
        var legalReserveRows = scoredMasteries
            .Where(entry => entry.Id > 0 && double.IsFinite(entry.Score))
            .OrderByDescending(entry => entry.Score)
            .ThenBy(entry => entry.Floor)
            .ThenBy(entry => entry.Id)
            .ToList();
        // Native cap previews rank the mastery pool for this exact gear/skill
        // package. Bound the expensive joint level search while retaining floor
        // diversity so one branch cannot occupy every slot in the shortlist.
        // Base and equipment-granted skills participate in scoring but do not
        // consume a mandatory saved point; reserve only real shrine actives.
        var masteryLimit = Math.Min(8, Math.Max(0, totalTalentPoints - mandatoryActivePointCount));
        var ranked = rankedRows.Take(Math.Max(0, masteryLimit - 2))
            .Concat(rankedRows.GroupBy(entry => entry.Floor)
                .Select(group => group.OrderByDescending(entry => entry.Score)
                    .ThenBy(entry => entry.Id).First()))
            .Concat(rankedRows)
            // Fill unused bounded slots with the least harmful legal rows. They
            // are capacity insurance, not positive recommendations; exact
            // native package scoring still decides whether they receive points.
            .Concat(legalReserveRows)
            .DistinctBy(entry => entry.Id)
            .Take(masteryLimit)
            .Select(entry => entry.Id)
            .ToList();
        if (AutoBuildSearchDeadlineReached() && ranked.Count < masteryLimit)
        {
            // At the deadline, fill the bounded mastery pool with the hero's
            // already-invested legal rows first. The ensuing complete-vector
            // native score still decides whether this fallback is rankable; no
            // unscored partial vector is ever applied.
            ranked = ranked.Concat(masteryCandidates
                    .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
                    .Where(id => id > 0))
                .Distinct()
                .Take(masteryLimit)
                .ToList();
        }
        return preferred with { MasteryTalentIds = ranked, ObjectiveScores = objectiveScores };
    }

    private static TalentLevelPlan BuildDeterministicTalentLevelPlan(
        object hero,
        HeroFocus focus,
        IReadOnlyCollection<int> skillTalentIds,
        IReadOnlyCollection<int> masteryTalentIds,
        int totalTalentPoints,
        object objectiveAttr,
        IReadOnlyCollection<GearCandidate>? candidateItems = null,
        int milestoneSeedLimit = -1,
        IReadOnlyDictionary<int, int>? preferredSavedLevels = null,
        bool fastDeterministicCompletion = false,
        bool scoreFastCompletion = true)
    {
        ThrowIfAutoBuildCancellationRequested();
        // Build one immutable per-plan topology snapshot on Unity's main thread.
        // Keeping these native wrappers only for this calculation avoids the
        // thousands of tiny worker/main-thread round trips that used to dominate
        // level allocation, while never retaining scene-bound IL2CPP objects in a
        // cross-run cache.
        var setup = MainThreadNativeGateway.Invoke(() =>
        {
        var talentData = ReadRequiredProperty(hero, "heroTalentData")
                         ?? throw new InvalidOperationException("HeroTalentData is unavailable.");
        var gridTalents = ReadValues(ReadRequiredProperty(talentData, "talentDic"))
            .DistinctBy(talent => NativeObjectKey(talent, talent)).ToList();
        var gridById = BuildTalentGridById(gridTalents);
        var activeSlots = GetTransformableTalents(talentData)
            .Where(talent => !IsTalentLockedRequired(talent))
            .OrderBy(talent => ReadNullableInt(Read(talent, "tTalentData"), "floor") ?? int.MaxValue)
            .ThenBy(talent => ReadNullableInt(Read(talent, "tTalentData"), "index") ?? int.MaxValue)
            .ThenBy(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? int.MaxValue)
            .ToList();
        var usedActiveSlots = new HashSet<string>(StringComparer.Ordinal);

        object ResolvePlanningTalent(object definition, int talentId)
        {
            if (gridById.TryGetValue(talentId, out var exact))
            {
                if (IsTransformableSkillDefinition(definition))
                {
                    var exactKey = NativeObjectKey(exact, exact);
                    if (!usedActiveSlots.Add(exactKey))
                        throw new InvalidOperationException(
                            $"Several planned active skills resolve to the same native slot ({talentId}).");
                }
                return exact;
            }
            if (!IsTransformableSkillDefinition(definition))
                throw new InvalidOperationException($"Planned talent {talentId} is absent from the native talent grid.");

            var skillId = ReadNullableInt(definition, "skillId") ?? 0;
            var floor = ReadNullableInt(definition, "floor") ?? int.MinValue;
            var index = ReadNullableInt(definition, "index") ?? int.MinValue;
            var slot = activeSlots.FirstOrDefault(candidate =>
            {
                var key = NativeObjectKey(candidate, candidate);
                return !usedActiveSlots.Contains(key)
                       && (ReadNullableInt(Read(candidate, "tTalentData"), "skillId") ?? 0) == skillId;
            }) ?? activeSlots.FirstOrDefault(candidate =>
            {
                var row = Read(candidate, "tTalentData");
                var key = NativeObjectKey(candidate, candidate);
                return !usedActiveSlots.Contains(key)
                       && !IsTalentUnreplaceable(candidate)
                       && (ReadNullableInt(row, "floor") ?? int.MinValue) == floor
                       && (ReadNullableInt(row, "index") ?? int.MinValue) == index;
            }) ?? activeSlots.FirstOrDefault(candidate =>
                !IsTalentUnreplaceable(candidate)
                && !usedActiveSlots.Contains(NativeObjectKey(candidate, candidate)));
            if (slot is null)
                throw new InvalidOperationException($"No unlocked native active-skill slot can host talent {talentId}.");
            usedActiveSlots.Add(NativeObjectKey(slot, slot));
            return slot;
        }

        var definitions = skillTalentIds.Concat(masteryTalentIds).Distinct()
            .Select(id => (Id: id, Definition: InvokeStatic("TableData", "getTTalentData", id)))
            .Where(entry => entry.Id > 0 && entry.Definition is not null)
            // Claim rows that already exist in the hero grid first. Otherwise a
            // transformed candidate processed earlier can borrow that physical
            // slot as a fallback and collide when its real fixed/current talent
            // is resolved later in the same plan.
            .OrderByDescending(entry => gridById.ContainsKey(entry.Id))
            .ThenBy(entry => entry.Id)
            .Select(entry => (entry.Id, Definition: entry.Definition!, Talent: ResolvePlanningTalent(entry.Definition!, entry.Id)))
            .ToList();
        var missing = skillTalentIds.Concat(masteryTalentIds).Where(id => id > 0)
            .Except(definitions.Select(entry => entry.Id)).Distinct().ToList();
        if (missing.Count > 0)
            throw new InvalidOperationException($"Planned talent definitions are unavailable ({string.Join(',', missing)}).");

        var bindings = definitions.Select(entry =>
        {
            var type = ReadNullableInt(entry.Definition, "type") ?? 0;
            var baseLevel = Math.Min(GetTalentBaseLevelRequired(entry.Talent), GetTalentLevelCap(entry.Talent));
            var cap = GetTalentLevelCap(entry.Talent);
            // ChangeBaseSkill materializes the selected base-skill row with one
            // saved level without consuming a normal talent point. Keep the
            // optimizer's vector in paid-point space, then add this native free
            // level only when producing the exact save target.
            var implicitSaved = IsBaseSkillDefinition(entry.Definition)
                ? Math.Min(1, Math.Max(0, cap - baseLevel))
                : 0;
            return (entry.Id, entry.Definition, entry.Talent, Type: type, Base: baseLevel,
                Cap: cap, ImplicitSaved: implicitSaved,
                MaxSaved: Math.Max(0, cap - baseLevel - implicitSaved),
                SkillId: ReadNullableInt(entry.Definition, "skillId") ?? 0,
                MasteryId: ReadNullableInt(entry.Definition, "masteryId") ?? 0,
                Floor: ReadNullableInt(entry.Definition, "floor") ?? int.MaxValue);
        }).Where(entry => entry.Type is 1 or 2).ToList();
        var skillBindings = bindings.Where(entry => entry.Type == 1 && entry.SkillId > 0).ToList();
        var masteryBindings = bindings.Where(entry => entry.Type == 2 && entry.MasteryId > 0).ToList();
        if (skillBindings.Count == 0)
            throw new InvalidOperationException("The performance plan contains no native skill talent.");
        var baseSkillBindings = skillBindings
            .Where(entry => IsBaseSkillDefinition(entry.Definition)).ToList();
        if (baseSkillBindings.Count != 1)
            throw new InvalidOperationException("The performance plan must contain exactly one native base-skill talent.");
        if (baseSkillBindings[0].ImplicitSaved != 1)
            throw new InvalidOperationException("The native base-skill talent cannot materialize its free saved level.");

        var levels = bindings.ToDictionary(entry => entry.Id, _ => 0);
        foreach (var entry in skillBindings.Where(entry => IsTransformableSkillDefinition(entry.Definition)))
        {
            if (entry.MaxSaved <= 0)
                throw new InvalidOperationException($"Active skill talent {entry.Id} has no investable level.");
            levels[entry.Id] = 1;
        }
        var committed = levels.Values.Sum();
        if (committed > totalTalentPoints)
            throw new InvalidOperationException($"The exact talent budget cannot learn the selected package ({committed}/{totalTalentPoints}).");

        Dictionary<int, int> grantedLevels = candidateItems is null
            ? new Dictionary<int, int>()
            : skillBindings.Select(entry => entry.SkillId).Distinct()
                .ToDictionary(id => id, id => GetGrantedSkillLevel(candidateItems, id));
        var learnedSkillIds = skillBindings.Select(entry => entry.SkillId).ToHashSet();
        var grantedOnlySkillIds = candidateItems is null
            ? new List<int>()
            : candidateItems.SelectMany(candidate => GetGrantedExtraSkillLevels(candidate.Record.ItemData))
                .Select(entry =>
                {
                    const string prefix = "extra-skill:";
                    return entry.Key.StartsWith(prefix, StringComparison.Ordinal)
                           && int.TryParse(entry.Key.Substring(prefix.Length), NumberStyles.Integer,
                               CultureInfo.InvariantCulture, out var id)
                        ? id
                        : 0;
                })
                .Where(id => id > 0 && !learnedSkillIds.Contains(id))
                .Distinct().OrderBy(id => id).ToList();
            return (
                Bindings: bindings,
                SkillBindings: skillBindings,
                MasteryBindings: masteryBindings,
                BaseSkillBindings: baseSkillBindings,
                Levels: levels,
                Committed: committed,
                GrantedLevels: grantedLevels,
                GrantedOnlySkillIds: grantedOnlySkillIds);
        });
        var bindings = setup.Bindings;
        var skillBindings = setup.SkillBindings;
        var masteryBindings = setup.MasteryBindings;
        var baseSkillBindings = setup.BaseSkillBindings;
        var levels = setup.Levels;
        var committed = setup.Committed;
        var grantedLevels = setup.GrantedLevels;
        var grantedOnlySkillIds = setup.GrantedOnlySkillIds;

        NativeSkillRoleProfile RoleFor((int Id, object Definition, object Talent, int Type, int Base, int Cap,
            int ImplicitSaved, int MaxSaved, int SkillId, int MasteryId, int Floor) entry, int saved, object attr)
        {
            var grantedLevel = grantedLevels.TryGetValue(entry.SkillId, out var value) ? value : 0;
            var effective = Math.Max(1, Math.Max(entry.Base + entry.ImplicitSaved + saved, grantedLevel));
            var role = ReadNativeSkillRoleProfile(
                hero, entry.SkillId, effective, attr, false, candidateItems, true, false);
            var hasRequiredManualRole = HasFocusedRoleConstraint(focus)
                                        && HasRequiredManualSkillRoleSignal(role, focus, entry.Definition);
            var isNativeTaggedManualPackageMember = HasFocusedRoleConstraint(focus)
                                                     && SkillHasNativeTagCore(
                                                         entry.SkillId,
                                                         "martial", "spell", "utility", "support",
                                                         "buff", "debuff", "minion", "ally", "aura",
                                                         "warcry", "curse", "totem", "archery");
            if (!IsNativeRoleRankable(role, focus)
                && !hasRequiredManualRole
                && !isNativeTaggedManualPackageMember
                && !IsTalentUnreplaceable(entry.Talent))
                throw new InvalidOperationException(
                    $"Skill {entry.SkillId} level {effective} has no rankable native output: {role.Failure}");
            return role;
        }

        var packageScoreCache = new Dictionary<string, double>(StringComparer.Ordinal);
#if PATHOFIDLE_RUNTIME_TEST
        const int runtimeTalentFailureLimit = 2200;
        var runtimeTalentFailures = new StringBuilder();
        void RecordRuntimeTalentFailure(string context, Exception error)
        {
            var detail = Regex.Replace(error.GetBaseException().Message, @"\s+", " ").Trim();
            if (detail.Length > 220) detail = detail[..217] + "...";
            var entry = $"{context}:{detail}";
            if (runtimeTalentFailures.Length + (runtimeTalentFailures.Length == 0 ? 0 : 3) + entry.Length
                > runtimeTalentFailureLimit) return;
            if (runtimeTalentFailures.Length > 0) runtimeTalentFailures.Append(" | ");
            runtimeTalentFailures.Append(entry);
        }
#endif
        string VectorKey(IReadOnlyDictionary<int, int> savedLevels) => string.Join(",",
            savedLevels.OrderBy(entry => entry.Key).Select(entry => $"{entry.Key}={entry.Value}"));

        double PackageScore(IReadOnlyDictionary<int, int> savedLevels)
        {
            var vectorKey = VectorKey(savedLevels);
            if (packageScoreCache.TryGetValue(vectorKey, out var cached)) return cached;
            var vector = new Dictionary<int, int>(savedLevels);
            var score = MainThreadNativeGateway.Invoke(() => PackageScoreCore(vector, vectorKey));
            packageScoreCache[vectorKey] = score;
            return score;
        }

        double PackageScoreCore(IReadOnlyDictionary<int, int> savedLevels, string vectorKey)
        {
            // Every trial must use one coherent AttrData snapshot. Applying all
            // mastery levels before rebuilding the skill package preserves both
            // mastery/mastery and mastery/skill-level interactions.
            var attr = InvokeRequiredStaticMany("AttrData", "copyCreate", objectiveAttr)
                       ?? throw new InvalidOperationException("Talent level-plan AttrData copy failed.");
            var masteryPreviews = new List<object>(masteryBindings.Count);
            foreach (var mastery in masteryBindings)
            {
                if (mastery.Base > 0)
                    ApplyMasteryAttributePreview(attr, mastery.MasteryId, mastery.Base, mastery.Cap, false);
                var effectiveMastery = mastery.Base + savedLevels.GetValueOrDefault(mastery.Id);
                if (effectiveMastery > 0)
                {
                    var preview = ApplyMasteryAttributePreview(
                        attr, mastery.MasteryId, effectiveMastery, mastery.Cap, true);
                    if (preview is not null) masteryPreviews.Add(preview);
                }
            }

            var baseBinding = baseSkillBindings[0];
            var packageAttr = CreateStrictSkillPackageAdjustedAttr(
                hero,
                skillBindings.Select(entry => (
                    SkillId: entry.SkillId,
                    Level: Math.Max(1, Math.Max(
                        entry.Base + entry.ImplicitSaved + savedLevels.GetValueOrDefault(entry.Id),
                        grantedLevels.GetValueOrDefault(entry.SkillId)))))
                    .Concat(grantedOnlySkillIds.Select(skillId => (
                        SkillId: skillId,
                        Level: Math.Max(1, GetGrantedSkillLevel(candidateItems!, skillId))))),
                attr,
                false,
                candidateItems,
                out _);
            var baseRole = RoleFor(baseBinding, savedLevels.GetValueOrDefault(baseBinding.Id), packageAttr);
            var activeRoles = skillBindings.Where(entry => entry.Id != baseBinding.Id)
                .Select(entry => RoleFor(entry, savedLevels.GetValueOrDefault(entry.Id), packageAttr)).ToList();
            foreach (var grantedSkillId in grantedOnlySkillIds)
            {
                var grantedLevel = Math.Max(1, GetGrantedSkillLevel(candidateItems!, grantedSkillId));
                var grantedRole = ReadNativeSkillRoleProfile(
                    hero, grantedSkillId, grantedLevel, packageAttr, false, candidateItems, true, false);
                // Gear-granted skills cannot be removed from this loadout. A
                // returned partial preview contributes only its proven lower
                // bound and does not invalidate independent package output. A
                // hard strict-preview failure still rejects this trial upstream.
                activeRoles.Add(grantedRole);
            }
            var package = BuildSharedSkillPackage(baseRole, activeRoles);
            if (!IsNativePackageRankable(package, focus))
                throw new InvalidOperationException($"The shared skill package has no rankable native output: {package.Failure}");
            if (!SatisfiesNativeThemeOutputContract(
                    focus, baseRole, activeRoles, package, out var themeFailure))
                throw new InvalidOperationException(
                    $"The shared skill package violates the native theme output contract: {themeFailure}");
            var score = ScoreHeroAttrObjective(packageAttr, focus, package.ControlledEntityKinds)
                        + ScoreNativeSkillRoleObjective(package, focus)
                        + ScoreMasteryAbilityObjective(masteryPreviews, focus, packageAttr);
            if (!double.IsFinite(score))
                throw new InvalidOperationException($"Talent vector {vectorKey} returned a non-finite objective.");
            return score;
        }

        TalentLevelPlan FinalizePlan(Dictionary<int, int> finalLevels)
        {
            var paidPointTotal = finalLevels.Values.Sum();
            if (paidPointTotal != totalTalentPoints)
                throw new InvalidOperationException(
                    $"The finalized paid talent budget differs ({paidPointTotal}/{totalTalentPoints}).");
            foreach (var entry in bindings)
            {
                var paid = finalLevels.GetValueOrDefault(entry.Id, -1);
                if (paid < 0 || paid > entry.MaxSaved)
                    throw new InvalidOperationException(
                        $"The finalized paid target for talent {entry.Id} is outside its native range ({paid}/{entry.MaxSaved}).");
            }
            var materializedSavedLevels = bindings.ToDictionary(
                entry => entry.Id,
                entry => checked(finalLevels[entry.Id] + entry.ImplicitSaved));
            var implicitSavedTotal = bindings.Sum(entry => entry.ImplicitSaved);
            if (materializedSavedLevels.Values.Sum() != checked(paidPointTotal + implicitSavedTotal))
                throw new InvalidOperationException("The finalized materialized talent vector lost an implicit base-skill level.");
            var effectiveSkillLevels = skillBindings.ToDictionary(
                entry => entry.SkillId,
                entry => Math.Max(1, Math.Max(
                    entry.Base + materializedSavedLevels[entry.Id],
                    grantedLevels.GetValueOrDefault(entry.SkillId))));
            var tokenBody = $"{focus.Key}|{totalTalentPoints}|" + string.Join(",",
                materializedSavedLevels.OrderBy(entry => entry.Key).Select(entry => $"{entry.Key}={entry.Value}"));
            ulong tokenHash = 1469598103934665603UL;
            foreach (var character in tokenBody)
            {
                tokenHash ^= character;
                tokenHash *= 1099511628211UL;
            }
            return new TalentLevelPlan(
                materializedSavedLevels,
                effectiveSkillLevels,
                $"{focus.Key}-{totalTalentPoints}-{tokenHash:x16}");
        }

        Dictionary<int, int> BuildProjectedPreferredVector()
        {
            var projected = new Dictionary<int, int>(levels);
            var projectedCommitted = projected.Values.Sum();
            foreach (var entry in bindings.OrderBy(entry => entry.Floor).ThenBy(entry => entry.Id))
            {
                if (projectedCommitted >= totalTalentPoints) break;
                var materializedPreferred = preferredSavedLevels?.GetValueOrDefault(entry.Id)
                                            ?? checked(projected[entry.Id] + entry.ImplicitSaved);
                var preferred = Math.Max(0, materializedPreferred - entry.ImplicitSaved);
                var target = Math.Clamp(preferred, projected[entry.Id], entry.MaxSaved);
                var add = Math.Min(target - projected[entry.Id], totalTalentPoints - projectedCommitted);
                if (add <= 0) continue;
                projected[entry.Id] += add;
                projectedCommitted += add;
            }
            var completionOrder = bindings
                .OrderBy(entry => entry.Type == 1 ? 0 : 1)
                .ThenBy(entry => entry.Floor)
                .ThenBy(entry => entry.Id)
                .ToList();
            while (projectedCommitted < totalTalentPoints)
            {
                var progressed = false;
                foreach (var entry in completionOrder)
                {
                    if (projectedCommitted >= totalTalentPoints) break;
                    if (projected[entry.Id] >= entry.MaxSaved) continue;
                    projected[entry.Id]++;
                    projectedCommitted++;
                    progressed = true;
                }
                if (!progressed)
                    throw new InvalidOperationException(
                        $"The projected talent vector cannot spend the exact point budget ({projectedCommitted}/{totalTalentPoints}).");
            }
            return projected;
        }

        if (fastDeterministicCompletion)
        {
            // Coarse gear screening must never run the point-by-point native
            // optimizer hundreds of times. Project the already verified target
            // vector onto this skill combination, then spend any points whose
            // original node was replaced in a deterministic round-robin. This
            // vector is evaluated once and is never applied to the save; every
            // surviving finalist is rebuilt by the full nonlinear allocator.
            var coarse = BuildProjectedPreferredVector();
            // Joint loadout refinement immediately evaluates this exact vector
            // against the candidate AttrData. It can skip this identical inner
            // package score; initial global planning still validates it here.
            if (scoreFastCompletion)
            {
                ThrowIfAutoBuildSearchDeadlineReached();
                _ = PackageScore(coarse);
            }
            return FinalizePlan(coarse);
        }

        // Evaluate a bounded set of complete nonlinear allocations. Each seed is
        // still scored by the full native mastery + skill + gear package above;
        // the bound changes only how many complete vectors we simulate. The old
        // point-by-point search evaluated thousands of nearly identical vectors
        // and could not finish within the transaction's configured safety limit.
        var skillPriority = skillTalentIds.Where(id => id > 0).Distinct()
            .Select((id, index) => (id, index))
            .ToDictionary(entry => entry.id, entry => entry.index);
        var masteryPriority = masteryTalentIds.Where(id => id > 0).Distinct()
            .Select((id, index) => (id, index))
            .ToDictionary(entry => entry.id, entry => entry.index);
        var concentratedLimit = milestoneSeedLimit > 0
            ? Math.Clamp(milestoneSeedLimit, 1, 4)
            : 8;
        var priorityBindings = bindings
            .OrderBy(entry => entry.Type == 1 ? 0 : 1)
            .ThenBy(entry => entry.Type == 1
                ? skillPriority.GetValueOrDefault(entry.Id, int.MaxValue)
                : masteryPriority.GetValueOrDefault(entry.Id, int.MaxValue))
            .ThenBy(entry => entry.Floor)
            .ThenBy(entry => entry.Id)
            .Take(concentratedLimit)
            .ToList();
        var completionOrder = bindings
            .OrderBy(entry => entry.Type == 1 ? 0 : 1)
            .ThenBy(entry => entry.Floor)
            .ThenBy(entry => entry.Id)
            .ToList();

        Dictionary<int, int> BuildConcentratedVector(int? priorityTalentId)
        {
            var vector = new Dictionary<int, int>(levels);
            var vectorCommitted = vector.Values.Sum();
            if (priorityTalentId is > 0)
            {
                var priority = bindings.First(entry => entry.Id == priorityTalentId.Value);
                var add = Math.Min(
                    priority.MaxSaved - vector[priority.Id],
                    totalTalentPoints - vectorCommitted);
                if (add > 0)
                {
                    vector[priority.Id] += add;
                    vectorCommitted += add;
                }
            }
            while (vectorCommitted < totalTalentPoints)
            {
                var progressed = false;
                foreach (var entry in completionOrder)
                {
                    if (vectorCommitted >= totalTalentPoints) break;
                    if (vector[entry.Id] >= entry.MaxSaved) continue;
                    vector[entry.Id]++;
                    vectorCommitted++;
                    progressed = true;
                }
                if (!progressed)
                    throw new InvalidOperationException(
                        $"The bounded talent vector cannot spend the exact point budget ({vectorCommitted}/{totalTalentPoints}).");
            }
            return vector;
        }

        var seedVectors = new List<Dictionary<int, int>>();
        var seedKeys = new HashSet<string>(StringComparer.Ordinal);
        var priorityByVectorKey = new Dictionary<string, int>(StringComparer.Ordinal);
        void AddCompleteSeed(Dictionary<int, int> vector, int priorityTalentId = 0)
        {
            var key = VectorKey(vector);
            if (!seedKeys.Add(key)) return;
            seedVectors.Add(vector);
            if (priorityTalentId > 0) priorityByVectorKey[key] = priorityTalentId;
        }

        if (preferredSavedLevels is not null)
            AddCompleteSeed(BuildProjectedPreferredVector());
        AddCompleteSeed(BuildConcentratedVector(null));
        foreach (var entry in priorityBindings)
            AddCompleteSeed(BuildConcentratedVector(entry.Id), entry.Id);

        List<(Dictionary<int, int> Levels, double Score)> ScoreCompleteVectors(
            IReadOnlyCollection<Dictionary<int, int>> vectors,
            string detail)
        {
            const int completeVectorNativeBatchSize = 1;
            var source = vectors.ToList();
            var scored = new List<(Dictionary<int, int> Levels, double Score)>();
            for (var offset = 0; offset < source.Count; offset += completeVectorNativeBatchSize)
            {
                if (scored.Count > 0 && AutoBuildSearchDeadlineReached()) break;
                ThrowIfAutoBuildSearchDeadlineReached();
                ThrowIfAutoBuildCancellationRequested();
                var batch = source.Skip(offset).Take(completeVectorNativeBatchSize).ToList();
                ReportAutoBuildProgress(
                    AutoBuildStep.FinalRefinement,
                    Math.Min(offset + batch.Count, source.Count),
                    source.Count,
                    detail);
                var batchResults = MainThreadNativeGateway.Invoke(() =>
                {
                    var results = new List<(Dictionary<int, int> Levels, double Score)>();
                    foreach (var vector in batch)
                    {
                        try
                        {
                            results.Add((vector, PackageScore(vector)));
                        }
                        catch (InvalidOperationException error)
                        {
#if PATHOFIDLE_RUNTIME_TEST
                            RecordRuntimeTalentFailure($"vector={VectorKey(vector)}", error);
#else
                            _ = error;
#endif
                        }
                    }
                    return results;
                });
                scored.AddRange(batchResults);
            }
            return scored;
        }

        var completedSeeds = ScoreCompleteVectors(
            seedVectors,
            UiText.L("완성 스킬 배분 비교 중", "Comparing complete skill allocations", "正在比较完整技能分配", "正在比較完整技能分配"));
        if (completedSeeds.Count == 0)
            throw new InvalidOperationException(
                $"No rankable native talent package can spend the exact point budget ({committed}/{totalTalentPoints})"
#if PATHOFIDLE_RUNTIME_TEST
                + $"; rejected=[{runtimeTalentFailures}]"
#endif
                + ".");

        var currentResult = completedSeeds
            .OrderByDescending(result => result.Score)
            .ThenBy(result => VectorKey(result.Levels), StringComparer.Ordinal)
            .First();

        // One bounded native exchange pass recovers nearby mixed allocations.
        // Endpoint scores choose receiver order; an unscored/weak endpoint is
        // tried first as a donor. This keeps the search data-driven without the
        // former all-pairs explosion.
        var endpointScores = completedSeeds
            .Select(result => (Key: VectorKey(result.Levels), result.Score))
            .Where(result => priorityByVectorKey.ContainsKey(result.Key))
            .GroupBy(result => priorityByVectorKey[result.Key])
            .ToDictionary(group => group.Key, group => group.Max(result => result.Score));
        var receiverOrder = priorityBindings
            .OrderByDescending(entry => endpointScores.GetValueOrDefault(entry.Id, double.NegativeInfinity))
            .ThenBy(entry => entry.Id)
            .ToList();
        var donorOrder = bindings
            .OrderBy(entry => endpointScores.GetValueOrDefault(entry.Id, double.NegativeInfinity))
            .ThenByDescending(entry => currentResult.Levels[entry.Id] - levels[entry.Id])
            .ThenBy(entry => entry.Id)
            .ToList();
        var refinementLimit = milestoneSeedLimit > 0 ? 4 : 8;
        var exchangeVectors = new List<Dictionary<int, int>>();
        var exchangeKeys = new HashSet<string>(StringComparer.Ordinal);
        foreach (var receiver in receiverOrder)
        {
            if (exchangeVectors.Count >= refinementLimit) break;
            if (currentResult.Levels[receiver.Id] >= receiver.MaxSaved) continue;
            var donor = donorOrder.FirstOrDefault(entry =>
                entry.Id != receiver.Id
                && currentResult.Levels[entry.Id] > levels[entry.Id]);
            if (donor.Id <= 0) continue;
            var exchanged = new Dictionary<int, int>(currentResult.Levels)
            {
                [donor.Id] = currentResult.Levels[donor.Id] - 1,
                [receiver.Id] = currentResult.Levels[receiver.Id] + 1
            };
            if (exchangeKeys.Add(VectorKey(exchanged))) exchangeVectors.Add(exchanged);
        }
        if (exchangeVectors.Count > 0 && !AutoBuildSearchDeadlineReached())
        {
            var exchanges = ScoreCompleteVectors(
                exchangeVectors,
                UiText.L("스킬 시너지 미세 조정 중", "Refining skill synergy", "正在微调技能协同", "正在微調技能協同"));
            var improved = exchanges
                .Where(result => result.Score > currentResult.Score + 0.000000001d)
                .OrderByDescending(result => result.Score)
                .ThenBy(result => VectorKey(result.Levels), StringComparer.Ordinal)
                .FirstOrDefault();
            if (improved.Levels is not null) currentResult = improved;
        }

        levels = currentResult.Levels;
        committed = levels.Values.Sum();
        return FinalizePlan(levels);
    }

    private static PlannedSkillTarget BuildPlannedSkillTarget(object hero, HeroFocus focus)
    {
        var talentData = ReadRequiredProperty(hero, "heroTalentData")
                         ?? throw new InvalidOperationException("HeroTalentData is unavailable.");
        var saveHero = ReadRequiredProperty(hero, "saveHeroData")
                       ?? throw new InvalidOperationException("SaveHeroData is unavailable.");
        var talents = ReadValues(ReadRequiredProperty(talentData, "talentDic"))
            .DistinctBy(talent => NativeObjectKey(talent, talent)).ToList();
        var spent = GetResettableTalentPointCount(talentData, talents);
        var total = PreviewExactTalentPointBudget(talentData, saveHero, talents, spent);
        var plan = SelectPreferredActiveSkillTargets(hero, talentData,
            // BuildPlannedSkillTarget immediately re-scores masteries against the
            // final row-limited skill package below. Skipping the otherwise
            // discarded first mastery pass preserves the exact final result.
            GetPerformanceTalentPlan(hero, focus, total, includeInitialMasteryScores: false), focus);
        plan = RebuildMasteryPlanForSelectedSkills(hero, focus, total, plan);
        ReportAutoBuildProgress(
            AutoBuildStep.CollectingCandidates,
            detail: UiText.L("스킬 계획 데이터 정리 중", "Preparing skill-plan metadata", "正在整理技能方案数据", "正在整理技能方案資料"));
        var metadata = MainThreadNativeGateway.Invoke(() =>
        {
            var planRows = plan.SkillTalentIds
                .Select(id => InvokeStatic("TableData", "getTTalentData", id))
                .Where(row => row is not null).Cast<object>().ToList();
            var baseRow = planRows.FirstOrDefault(IsBaseSkillDefinition);
            var resolvedBaseTalentId = ReadNullableInt(baseRow, "id") ?? 0;
            var resolvedBaseSkillId = ReadNullableInt(baseRow, "skillId") ?? 0;
            var resolvedActiveSkillIds = planRows.Where(IsTransformableSkillDefinition)
                .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var jobId = ReadRequiredIntProperty(saveHero, "jobId");
            var baseCandidateRows = talents
                .Where(talent => !IsTalentLockedRequired(talent))
                .Select(talent => Read(talent, "tTalentData"))
                .Where(IsBaseSkillDefinition)
                .Where(row => row is not null).Cast<object>()
                .ToList();
            var resolvedBaseCandidateSkillIds = baseCandidateRows
                .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                .Where(id => id > 0)
                .ToHashSet();
            var currentActiveTalents = GetTransformableTalents(talentData)
                .Where(talent => !IsTalentLockedRequired(talent)).ToList();
            var currentActiveTalentIds = currentActiveTalents
                .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var preservedTalentIds = GetTransformableTalents(talentData)
                .Where(IsTalentUnreplaceable)
                .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var heroLevel = ReadRequiredIntProperty(saveHero, "level");
            var allTalentRows = ReadValues(ReadStatic("TableData", "TTalentDict")).ToList();
            var activeCandidateRows = allTalentRows
                .Where(IsTransformableSkillDefinition)
                .Where(row => (ReadNullableInt(row, "jobId") ?? 0) == jobId)
                .Where(row =>
                {
                    var id = ReadNullableInt(row, "id") ?? 0;
                    if (id <= 0 || (preservedTalentIds.Contains(id) && !currentActiveTalentIds.Contains(id))) return false;
                    return heroLevel > 1 || currentActiveTalentIds.Contains(id) || (ReadNullableInt(row, "floor") ?? 0) == 1;
                })
                .ToList();
            var resolvedActiveCandidateSkillIds = activeCandidateRows
                .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                .Where(id => id > 0).ToHashSet();
            // Selectable relevance mirrors the hero's real unlocked grid.
            var selectableMasteryRows = talents
                .Where(talent => !IsTalentLockedRequired(talent))
                .Where(talent => (ReadNullableInt(Read(talent, "tTalentData"), "type") ?? 0) == 2)
                .Where(talent => (ReadNullableInt(Read(talent, "tTalentData"), "masteryId") ?? 0) > 0)
                .Where(talent => GetTalentLevelCap(talent) - GetTalentBaseLevelRequired(talent) > 0)
                .ToList();
            var resolvedSelectableTalentIds = baseCandidateRows.Concat(activeCandidateRows)
                .Select(row => ReadNullableInt(row, "id") ?? 0)
                .Concat(selectableMasteryRows.Select(talent =>
                    ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0))
                .Where(id => id > 0).ToHashSet();
            var resolvedSelectableMasteryIds = selectableMasteryRows
                .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "masteryId") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var resolvedObjectiveBySkillId = new Dictionary<int, double>();
            foreach (var skillId in resolvedBaseCandidateSkillIds.Concat(resolvedActiveCandidateSkillIds))
            {
                var value = allTalentRows
                    .Where(candidate => (ReadNullableInt(candidate, "skillId") ?? 0) == skillId)
                    .Select(candidate => plan.ObjectiveScores?.GetValueOrDefault(
                        ReadNullableInt(candidate, "id") ?? 0) ?? double.NegativeInfinity)
                    .DefaultIfEmpty(double.NegativeInfinity)
                    .Max();
                if (double.IsFinite(value)) resolvedObjectiveBySkillId[skillId] = value;
            }
            return (
                BaseTalentId: resolvedBaseTalentId,
                BaseSkillId: resolvedBaseSkillId,
                ActiveSkillIds: resolvedActiveSkillIds,
                BaseCandidateSkillIds: resolvedBaseCandidateSkillIds,
                ActiveCandidateSkillIds: resolvedActiveCandidateSkillIds,
                SelectableTalentIds: resolvedSelectableTalentIds,
                SelectableMasteryIds: resolvedSelectableMasteryIds,
                CurrentActiveCount: currentActiveTalents.Count,
                ObjectiveBySkillId: resolvedObjectiveBySkillId);
        });
        var baseTalentId = metadata.BaseTalentId;
        var baseSkillId = metadata.BaseSkillId;
        var activeSkillIds = metadata.ActiveSkillIds;
        var baseCandidateSkillIds = metadata.BaseCandidateSkillIds;
        var activeCandidateSkillIds = metadata.ActiveCandidateSkillIds;
        var selectableTalentIds = metadata.SelectableTalentIds;
        var selectableMasteryIds = metadata.SelectableMasteryIds;
        var objectiveBySkillId = metadata.ObjectiveBySkillId;
        ReportAutoBuildProgress(
            AutoBuildStep.FinalRefinement,
            detail: UiText.L("스킬 배분 기준 생성 중", "Preparing skill allocation", "正在准备技能分配", "正在準備技能分配"));
        var objectiveAttr = MainThreadNativeGateway.Invoke(() =>
            CreateGearAndTalentNeutralObjectiveAttr(hero, talents));
        var currentSavedTargets = MainThreadNativeGateway.Invoke(() => talents
            .Where(IsNormalTalentNode)
            .Select(talent => (
                Id: ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0,
                Level: GetSavedTalentLevel(talent)))
            .Where(entry => entry.Id > 0)
            .GroupBy(entry => entry.Id)
            .ToDictionary(group => group.Key, group => group.Max(entry => entry.Level)));
        // This is the seed used while equipment candidates are collected. One
        // complete native-scored vector is sufficient here; surviving loadouts
        // run the nonlinear multi-seed allocator during final refinement. The
        // former full seed search could consume the entire soft deadline before
        // the current 8-slot incumbent had even been established.
        var levelPlan = BuildDeterministicTalentLevelPlan(
            hero,
            focus,
            plan.SkillTalentIds,
            plan.MasteryTalentIds,
            total,
            objectiveAttr,
            preferredSavedLevels: currentSavedTargets,
            fastDeterministicCompletion: true);
        var selectedMasteryTalentIds = plan.MasteryTalentIds
            .Where(id => levelPlan.SavedLevels.GetValueOrDefault(id) > 0)
            .Distinct().ToList();
        plan = plan with
        {
            MasteryTalentIds = selectedMasteryTalentIds,
            TargetSavedLevels = new Dictionary<int, int>(levelPlan.SavedLevels),
            PlanToken = levelPlan.Token
        };
        var baseSavedTarget = baseTalentId > 0
            ? levelPlan.SavedLevels.GetValueOrDefault(baseTalentId)
            : 0;
        var baseTalent = baseTalentId > 0 && BuildTalentGridById(talents).TryGetValue(baseTalentId, out var resolvedBaseTalent)
            ? resolvedBaseTalent
            : null;
        var baseEffectiveTarget = baseTalent is null
            ? levelPlan.EffectiveSkillLevels.GetValueOrDefault(baseSkillId, 1)
            : Math.Max(1, GetTalentBaseLevelRequired(baseTalent) + baseSavedTarget);
        return new PlannedSkillTarget(
            baseTalentId,
            baseSkillId,
            baseEffectiveTarget,
            activeSkillIds,
            plan.SkillTalentIds.ToHashSet(),
            selectedMasteryTalentIds.ToHashSet(),
            baseCandidateSkillIds,
            activeCandidateSkillIds,
            selectableTalentIds,
            selectableMasteryIds,
            metadata.CurrentActiveCount,
            objectiveBySkillId,
            objectiveAttr,
            total,
            new Dictionary<int, int>(levelPlan.SavedLevels),
            levelPlan.Token,
            plan.RequiredActiveSkillIds?.ToHashSet(),
            plan.RequiredBaseSkillIds?.ToHashSet(),
            plan.ThemePackageSkillIds?.ToHashSet(),
            plan.RequiredThemeSkillCount);
    }

    private static double ScoreSkillDefinitionForObjective(object hero, object definition, HeroFocus focus,
        int previewLevel, object objectiveAttr)
    {
        var talentId = ReadNullableInt(definition, "id") ?? 0;
        var skillId = ReadNullableInt(definition, "skillId") ?? 0;
        if (talentId <= 0 || skillId <= 0)
            throw new InvalidOperationException($"Invalid skill objective row (talent={talentId}, skill={skillId}).");
        var nativeRole = ReadNativeSkillRoleProfile(hero, skillId, Math.Max(1, previewLevel), objectiveAttr, false);
        // Preview failures must abort before shrine transformation/reset, not
        // become a zero that silently selects a different hero personality.
        return ScoreNativeSkillRoleObjective(nativeRole, focus) * 10000d;
    }

    private static bool MatchesManualSkillTheme(object hero, object definition, HeroFocus focus)
    {
        if (!HasFocusedRoleConstraint(focus)) return true;
        var skillId = ReadNullableInt(definition, "skillId") ?? 0;
        if (skillId <= 0) return false;
        var text = GetTalentDefinitionText(definition).ToLowerInvariant();
        var role = ReadNativeSkillRoleProfile(hero, skillId, 1);
        var damageRule = GetNativeDamageThemeRule(focus);
        if (damageRule is not null)
            return GetTypedDamage(role, damageRule.DamageTypes) > 0d
                   || damageRule.DamageTypes.All(IsPeriodicDamageType)
                   && GetHostileStatusThemeOutput(role, focus) > 0d;

        return focus.Key switch
        {
            "minion" => role.ControlledEntityKinds != NativeControlledEntityKind.None,
            "crit" => HasNativeCriticalSkillSignal(definition),
            "defense" => role.SelfHeal > 0d || role.SelfShield > 0d || role.AbilityDefense > 0d,
            "support" => role.Heal > 0d || role.Shield > 0d || role.AbilitySupport > 0d,
            _ => KeywordScore(text, focus.Keywords) > 0
        };
    }

    private static double GetManualDamageAmount(IReadOnlyDictionary<int, double> damageByType, HeroFocus focus)
    {
        var total = damageByType.Values.Where(value => value > 0d).Sum();
        var rule = GetNativeDamageThemeRule(focus);
        if (rule is null) return total;
        var aligned = damageByType
            .Where(entry => rule.DamageTypes.Contains(entry.Key) && entry.Value > 0d)
            .Sum(entry => entry.Value);
        // A manual element is an objective weight, not a hard-coded skill list.
        // Priority 0 values every native damage type equally, 50 retains the
        // established 18% off-theme weight, and 100 values only aligned output.
        var balanced = aligned + Math.Max(0d, total - aligned) * 0.18d;
        return BlendThemePriority(focus, total, balanced, aligned);
    }

    private static bool HasRequiredManualSkillRoleSignal(
        NativeSkillRoleProfile role,
        HeroFocus focus,
        object? definition = null)
    {
        if (!HasFocusedRoleConstraint(focus)) return true;
        // A captured native role is sufficient for Defense/Minion and for
        // tag-free Support fallbacks. Avoid crossing the Unity gateway merely
        // to read a null optional definition (also keeps the structural audit
        // executable outside the game process).
        var skillId = definition is null
            ? 0
            : ReadNullableInt(definition, "skillId") ?? 0;
        bool HasTags(params string[] names)
            => skillId > 0 && SkillHasNativeTagCore(skillId, names);
        var damageRule = GetNativeDamageThemeRule(focus);
        if (damageRule is not null)
        {
            if (GetTypedDamage(role, damageRule.DamageTypes) > 0d) return true;
            // Wound/poison/etc. may be native hostile stack applications rather
            // than PowerData damage types. Match their TAttr identity to the
            // requested theme only after the action graph proved an application.
            return damageRule.DamageTypes.All(IsPeriodicDamageType)
                   && GetHostileStatusThemeOutput(role, focus) > 0d;
        }
        return focus.Key switch
        {
            // Role output validates what the skill actually does; native tags
            // identify the game's intended lane. Text translations are not a
            // build contract and are deliberately absent here.
            "defense" => role.SelfHeal > 0d || role.SelfShield > 0d || role.AbilityDefense > 0d,
            "support" => (role.Heal > 0d || role.Shield > 0d || role.AbilitySupport > 0d)
                           && (HasTags(
                                   "support", "utility", "buff", "debuff", "affliction",
                                   "ally", "aura", "totem", "curse")
                               || skillId <= 0),
            // The native action/produce/emitter graph is the authoritative
            // parent relationship. Tags refine its subtype but cannot erase a
            // proven Minion, Ally, Totem, or other controlled entity.
            "minion" => role.ControlledEntityKinds != NativeControlledEntityKind.None,
            // Generic damage is not a Critical theme contract. The native
            // table must explicitly describe an offensive critical mechanic;
            // defensive Crit Resistance text is deliberately not sufficient.
            "crit" => HasNativeCriticalSkillSignal(definition),
            _ => HasProvenNativeRoleSignal(role)
        };
    }

    private static double GetTypedDamage(
        NativeSkillRoleProfile role,
        IReadOnlySet<int>? allowedTypes = null)
    {
        static double Positive(double value)
            => double.IsFinite(value) && value > 0d ? value : 0d;
        var direct = role.DamageByType
            .Where(entry => allowedTypes is null || allowedTypes.Contains(entry.Key))
            .Sum(entry => Positive(entry.Value));
        var summon = (role.SummonAttackByType ?? new Dictionary<int, double>())
            .Where(entry => allowedTypes is null || allowedTypes.Contains(entry.Key))
            .Sum(entry => Positive(entry.Value));
        return direct + summon;
    }

    private static readonly object NativeHostileStatusNameSync = new();
    private static readonly Dictionary<int, string> NativeHostileStatusNames = new();

    private static string GetNativeHostileStatusName(int attrId)
    {
        if (attrId <= 0) return string.Empty;
        lock (NativeHostileStatusNameSync)
            if (NativeHostileStatusNames.TryGetValue(attrId, out var cached)) return cached;

        var row = InvokeStatic("TableData", "getTAttrData", attrId);
        var enumType = GameType("EAttrType");
        var enumName = string.Empty;
        try
        {
            if (enumType?.IsEnum == true)
                enumName = Enum.ToObject(enumType, attrId).ToString() ?? string.Empty;
        }
        catch
        {
            // TAttr's localized/native names below remain authoritative.
        }
        var name = NormalizeSkillDependencyText(string.Join(" ", new[]
        {
            EnglishName(row, ReadString(row, "name") ?? string.Empty) ?? string.Empty,
            ReadString(row, "showName") ?? string.Empty,
            enumName
        }));
        lock (NativeHostileStatusNameSync)
            NativeHostileStatusNames[attrId] = name;
        return name;
    }

    private static double GetHostileStatusThemeOutput(
        NativeSkillRoleProfile role,
        HeroFocus focus)
    {
        var applications = role.HostileStatusApplications;
        if (applications is null || applications.Count == 0) return 0d;
        var terms = focus.Keywords.Append(focus.Key)
            .Select(NormalizeSkillDependencyText)
            .Where(value => value.Length >= 3)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        return applications.Where(entry =>
                entry.Key > 0 && double.IsFinite(entry.Value) && entry.Value > 0d
                && terms.Any(term => GetNativeHostileStatusName(entry.Key)
                    .Contains(term, StringComparison.OrdinalIgnoreCase)))
            .Sum(entry => entry.Value);
    }

    private static double GetAllHostileStatusOutput(NativeSkillRoleProfile role)
        => role.HostileStatusApplications?.Values
               .Where(value => double.IsFinite(value) && value > 0d).Sum() ?? 0d;

    private static bool HasIndependentNonDamageRoleOutput(NativeSkillRoleProfile role)
        => Math.Max(0d, role.Heal) > 0d
           || Math.Max(0d, role.Shield) > 0d
           || Math.Max(0d, role.AbilitySupport) > 0d
           || Math.Max(0d, role.AbilityDefense) > 0d;

    // An avoidable off-theme attack is derived from the native role graph, not
    // from a skill id or translated name. It has measured damage, contributes
    // neither requested damage/status output nor independent measured healing,
    // shielding, support, or defense output. Merely creating a durable summon
    // is not a cross-element support role; its native attack type still owns the
    // damage-theme classification. This definition therefore applies to
    // every current and future damage theme resolved by GetNativeDamageThemeRule.
    private static bool IsAvoidableOffThemeActiveAttack(
        NativeSkillRoleProfile role,
        HeroFocus focus,
        NativeDamageThemeRule damageRule)
    {
        if (GetTypedDamage(role) <= 0d) return false;
        if (GetTypedDamage(role, damageRule.DamageTypes) > 0d) return false;
        if (damageRule.DamageTypes.All(IsPeriodicDamageType)
            && GetHostileStatusThemeOutput(role, focus) > 0d) return false;
        return !HasIndependentNonDamageRoleOutput(role);
    }

    private static int CountAvoidableOffThemeActiveAttacks(
        HeroFocus focus,
        IEnumerable<NativeSkillRoleProfile> activeRoles)
    {
        var damageRule = GetNativeDamageThemeRule(focus);
        return damageRule is null
            ? 0
            : activeRoles.Count(role =>
                IsAvoidableOffThemeActiveAttack(role, focus, damageRule));
    }

    // Apply the same parent role rule to non-damage themes. A pure attack that
    // contributes neither the requested native role nor any independently
    // proven healing/shielding/support/defense output is avoidably off-theme.
    // Definition metadata is used only where the native role itself cannot
    // express the contract (currently Critical); no skill id or translated
    // name is special-cased.
    private static bool IsAvoidableOffThemeActiveSkill(
        NativeSkillRoleProfile role,
        HeroFocus focus,
        object? definition = null)
    {
        var damageRule = GetNativeDamageThemeRule(focus);
        if (damageRule is not null)
            return IsAvoidableOffThemeActiveAttack(role, focus, damageRule);
        if (HasRequiredManualSkillRoleSignal(role, focus, definition)) return false;
        if (GetTypedDamage(role) <= 0d) return false;
        return !HasIndependentNonDamageRoleOutput(role);
    }

    private static double GetNativeThemeAlignedDamageShare(
        HeroFocus focus,
        NativeSkillRoleProfile package)
    {
        var damageRule = GetNativeDamageThemeRule(focus);
        if (damageRule is null) return 0d;
        var total = GetTypedDamage(package);
        if (total <= 0d)
            return damageRule.DamageTypes.All(IsPeriodicDamageType)
                   && GetHostileStatusThemeOutput(package, focus) > 0d
                ? 1d
                : 0d;
        return Math.Clamp(GetTypedDamage(package, damageRule.DamageTypes) / total, 0d, 1d);
    }

    private static bool SatisfiesNativeThemeOutputContract(
        HeroFocus focus,
        NativeSkillRoleProfile baseRole,
        IEnumerable<NativeSkillRoleProfile> activeRoles,
        NativeSkillRoleProfile package,
        out string reason)
    {
        var active = activeRoles.ToList();
        var damageRule = GetNativeDamageThemeRule(focus);
        if (damageRule is not null)
        {
            var totalDamage = GetTypedDamage(package);
            var alignedDamage = GetTypedDamage(package, damageRule.DamageTypes);
            var periodicStatusOutput = damageRule.DamageTypes.All(IsPeriodicDamageType)
                ? GetHostileStatusThemeOutput(package, focus)
                : 0d;
            var alignedShare = totalDamage > 0d ? alignedDamage / totalDamage : 0d;
            var offThemeActive = active.Count(role =>
                GetTypedDamage(role) > 0d
                && GetTypedDamage(role, damageRule.DamageTypes) <= 0d);
            var avoidableOffThemeActive = CountAvoidableOffThemeActiveAttacks(focus, active);
            reason = $"damage={string.Join('+', damageRule.DamageTypes.OrderBy(id => id))};aligned={alignedDamage:0.###};status={periodicStatusOutput:0.###};total={totalDamage:0.###};share={alignedShare:P1};off-theme-active={offThemeActive};avoidable-off-theme-active={avoidableOffThemeActive}";
            // Require proof that the requested lane exists. Relative purity is
            // optimized continuously by GetManualDamageAmount/BlendThemePriority
            // instead of being used as an all-or-nothing rejection threshold.
            return alignedDamage > 0d || periodicStatusOutput > 0d;
        }

        if (focus.Key == "minion")
        {
            var roles = new[] { baseRole }.Concat(active).ToList();
            var summonOutput = roles.Sum(role =>
                Math.Max(0d, role.ControlledEntityDamage)
                + Math.Max(0d, role.ControlledEntityUtility)
                + Math.Max(0d, role.ControlledEntitySurvival) * 0.35d);
            var controlledEmitterDamage = roles
                .Where(role => role.ControlledEntityKinds.HasFlag(NativeControlledEntityKind.Totem))
                .Sum(role => role.DamageByType.Values
                    .Where(value => double.IsFinite(value) && value > 0d).Sum());
            var directOutput = Math.Max(0d, package.DamageByType.Values
                .Where(value => double.IsFinite(value) && value > 0d).Sum()
                - controlledEmitterDamage);
            var share = summonOutput + directOutput > 0d
                ? summonOutput / (summonOutput + directOutput)
                : 0d;
            // Theme priority belongs in the continuous objective, not in a
            // second binary share cutoff. A hero can have unavoidable direct
            // output from its fixed/base skill while still having the strongest
            // available controlled-entity build. Lane integrity is already
            // enforced by the native spawn/emitter relation, positive controlled
            // output, and the authored-package coverage contract.
            reason = $"controlled={package.ControlledEntityKinds};output={summonOutput:0.###};direct={directOutput:0.###};share={share:P1}";
            return package.ControlledEntityKinds != NativeControlledEntityKind.None
                   && summonOutput > 0d;
        }

        if (focus.Key == "defense")
        {
            var value = Math.Max(0d, package.SelfHeal) + Math.Max(0d, package.SelfShield)
                        + Math.Max(0d, package.AbilityDefense);
            reason = $"defense-output={value:0.###}";
            return value > 0d;
        }

        if (focus.Key == "support")
        {
            var value = Math.Max(0d, package.Heal) + Math.Max(0d, package.Shield)
                        + Math.Max(0d, package.AbilitySupport);
            reason = $"support-output={value:0.###}";
            return value > 0d;
        }

        reason = "no additional native output constraint";
        return true;
    }

    private static bool SatisfiesNativeThemeOutputContract(
        HeroFocus focus,
        NativeSkillRoleProfile baseRole,
        IEnumerable<NativeSkillRoleProfile> activeRoles,
        out NativeSkillRoleProfile package,
        out string reason)
    {
        var active = activeRoles.ToList();
        package = BuildSharedSkillPackage(baseRole, active);
        return SatisfiesNativeThemeOutputContract(
            focus, baseRole, active, package, out reason);
    }

    private static bool SatisfiesThemeSkillContract(
        int baseSkillId,
        IEnumerable<int> activeSkillIds,
        IEnumerable<int> grantedSkillIds,
        HashSet<int>? requiredBaseSkillIds,
        HashSet<int>? requiredActiveSkillIds,
        HashSet<int>? themePackageSkillIds,
        int requiredThemeSkillCount)
    {
        var active = activeSkillIds.Where(id => id > 0).ToHashSet();
        active.UnionWith(grantedSkillIds.Where(id => id > 0));
        // If the job exposes a native base skill for the selected lane, using an
        // unrelated base and one token active skill is not a valid themed build.
        // Jobs without such a base satisfy the core through an active skill.
        if (requiredBaseSkillIds is { Count: > 0 })
        {
            if (!requiredBaseSkillIds.Contains(baseSkillId)) return false;
        }
        else if (requiredActiveSkillIds is { Count: > 0 }
                 && !active.Any(requiredActiveSkillIds.Contains)) return false;

        if (requiredThemeSkillCount <= 0) return true;
        var packageIds = themePackageSkillIds is { Count: > 0 }
            ? themePackageSkillIds
            : (requiredBaseSkillIds ?? new HashSet<int>())
                .Concat(requiredActiveSkillIds ?? new HashSet<int>())
                .ToHashSet();
        if (packageIds.Count == 0) return false;
        var present = active.Append(baseSkillId)
            .Where(id => id > 0 && packageIds.Contains(id))
            .Distinct()
            .Count();
        return present >= requiredThemeSkillCount;
    }

    private static bool HasNativeCriticalSkillSignal(object? definition)
    {
        if (definition is null) return false;
        var skillId = ReadNullableInt(definition, "skillId") ?? 0;
        var skill = skillId > 0 ? InvokeStatic("TableData", "getTSkillData", skillId) : null;
        var infoId = ReadNullableInt(skill, "infoId") ?? 0;
        var info = infoId > 0 ? InvokeStatic("TableData", "getTSkillInfoData", infoId) : null;
        if (info is not null)
        {
            var tagIds = ReadSequence(Read(info, "tagArr")).Select(ToInt).Where(id => id > 0);
            if (HasNativeSkillTag(tagIds, "crit", "critical", "critical strike")) return true;

            var abilityIds = new HashSet<int>(
                ReadSequence(Read(info, "otherParam")).Select(ToInt).Where(id => id > 0));
            foreach (var explainId in ReadSequence(Read(info, "infoArr")).Select(ToInt).Where(id => id > 0))
            {
                var explain = InvokeStatic("TableData", "getTSkillExplainData", explainId);
                if ((ReadNullableInt(explain, "type") ?? -1) is not (3 or 4 or 103)) continue;
                var abilityId = ReadSequence(Read(explain, "typeParam")).Select(ToInt).FirstOrDefault();
                if (abilityId > 0) abilityIds.Add(abilityId);
            }
            if (abilityIds.Any(abilityId => HasPositiveNativeCriticalAttribute(
                    ResolveAbilityTableRow(abilityId, 1)))) return true;
        }

        // Some guaranteed-critical mechanics are implemented by battle hooks
        // rather than result301. Retain explicit offensive wording only as the
        // final fallback, after native tags and signed ability attributes.
        var text = GetTalentDefinitionText(definition);
        return !string.IsNullOrWhiteSpace(text)
               && Regex.IsMatch(
                   text,
                   @"\b(?:guaranteed\s+(?:crit|critical)|(?:crit|critical)\s+(?:chance|damage|value|against)|increased\s+(?:crit|critical)(?!\s+(?:resistance|resist))|critical\s+strike(?!\s+(?:resistance|resist)))\b",
                   RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    }

    private static bool HasPositiveNativeCriticalAttribute(object? ability)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        if (row is null) return false;
        static bool IsCriticalAttribute(int id) => id is 31 or 33 or 37;
        foreach (var entry in ReadEntries(Read(Read(ability, "resultData"), "combatAttrFinalDic")))
        {
            var attrId = ToInt(Read(entry, "Key") ?? 0);
            double value;
            try { value = Convert.ToDouble(Read(entry, "Value") ?? 0d, CultureInfo.InvariantCulture); }
            catch { continue; }
            if (IsCriticalAttribute(attrId) && double.IsFinite(value) && value > 0d) return true;
        }

        var result = ReadSequence(Read(row, "resultArr")).Select(ToInt).ToList();
        if (result.Count == 0 || result[0] != 301) return false;
        for (var index = 1; index + 1 < result.Count; index += 2)
            if (IsCriticalAttribute(result[index]) && result[index + 1] > 0) return true;
        return false;
    }

    private static List<int[]> ParseNativeConditionClauses(string? rawCondition)
    {
        var result = new List<int[]>();
        foreach (var rawClause in Clean(rawCondition ?? string.Empty)
                     .Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var values = rawClause.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            var parsed = new int[values.Length];
            var valid = values.Length > 0;
            for (var index = 0; index < values.Length; index++)
                valid &= int.TryParse(values[index], NumberStyles.Integer,
                    CultureInfo.InvariantCulture, out parsed[index]);
            if (valid) result.Add(parsed);
        }
        return result;
    }

    private static bool TryReadNativeConditionProbability(string? rawCondition, out double probability)
    {
        probability = 1d;
        var found = false;
        foreach (var clause in ParseNativeConditionClauses(rawCondition))
        {
            // TriggerConditonData condition type 1 is the table-authored percent
            // roll. Current data stores values such as "1,30" for a 30% roll.
            if (clause.Length < 2 || clause[0] != 1 || clause[1] is < 0 or > 100) continue;
            probability *= clause[1] / 100d;
            found = true;
        }
        probability = Math.Clamp(probability, 0d, 1d);
        return found;
    }

    private static bool TryReadPureNativeChanceCondition(string? rawCondition, out double probability)
    {
        probability = 1d;
        var clauses = ParseNativeConditionClauses(rawCondition);
        if (clauses.Count == 0 || clauses.Any(clause => clause.Length < 2 || clause[0] != 1))
            return false;
        foreach (var clause in clauses)
        {
            if (clause[1] is < 0 or > 100) return false;
            probability *= clause[1] / 100d;
        }
        probability = Math.Clamp(probability, 0d, 1d);
        return true;
    }

    private static bool TryReadTextChanceProbability(string? source, out double probability)
    {
        probability = 1d;
        var text = NormalizeSkillDependencyText(source);
        if (text.Length == 0) return false;
        var match = Regex.Match(text,
            @"(?<!\d)(\d+(?:\.\d+)?)\s*%\s*(?:chance|probability)\b",
            RegexOptions.CultureInvariant);
        if (!match.Success)
            match = Regex.Match(text,
                @"\b(?:chance|probability)\b[^.;]{0,24}?(\d+(?:\.\d+)?)\s*%",
                RegexOptions.CultureInvariant);
        if (!match.Success
            || !double.TryParse(match.Groups[1].Value, NumberStyles.Float,
                CultureInfo.InvariantCulture, out var percent)
            || !double.IsFinite(percent) || percent is < 0d or > 100d)
            return false;
        probability = percent / 100d;
        return true;
    }

    private static int ParseNativeTriggerTargetType(string? targetParam)
    {
        var normalized = Clean(targetParam ?? string.Empty);
        if (normalized.Length == 0) return 0;
        var separator = normalized.IndexOf(',');
        var token = separator >= 0 ? normalized[..separator] : normalized;
        return int.TryParse(token, NumberStyles.Integer, CultureInfo.InvariantCulture, out var value)
            && value > 0
            ? value
            : 0;
    }

    private static bool IsGuaranteedSelfPowerTarget(int targetType)
    {
        if (targetType <= 0) return false;
        lock (NativeSelfPowerTargetSync)
        {
            if (nativeSelfPowerTargetTypes is null)
            {
                gameAssembly ??= AppDomain.CurrentDomain.GetAssemblies()
                    .FirstOrDefault(assembly =>
                        assembly.GetName().Name == "Assembly-CSharp");
                var enumType = gameAssembly?.GetType(
                    "ETriggerTargetType", false, false);
                if (enumType?.IsEnum != true) return false;
                var resolved = new HashSet<int>();
                foreach (var name in new[]
                         {
                             "bulletOwnCombat", "skillOwnCombat", "actionOwnCombat"
                         })
                {
                    try
                    {
                        var field = enumType.GetField(
                            name, BindingFlags.Public | BindingFlags.Static);
                        if (field?.GetRawConstantValue() is { } raw)
                            resolved.Add(Convert.ToInt32(raw, CultureInfo.InvariantCulture));
                    }
                    catch
                    {
                        // An unknown/native enum shape is not proof of a self
                        // recipient. Keep the recovery out of survival scoring.
                    }
                }
                if (resolved.Count == 0) return false;
                nativeSelfPowerTargetTypes = resolved;
            }
            return nativeSelfPowerTargetTypes.Contains(targetType);
        }
    }

    private static int ResolveNativeTriggerTargetTypeValue(string name)
    {
        if (string.IsNullOrWhiteSpace(name)) return 0;
        lock (NativeSelfPowerTargetSync)
        {
            if (NativeTriggerTargetTypeValues.TryGetValue(name, out var cached))
                return cached;
            gameAssembly ??= AppDomain.CurrentDomain.GetAssemblies()
                .FirstOrDefault(assembly => assembly.GetName().Name == "Assembly-CSharp");
            var enumType = gameAssembly?.GetType("ETriggerTargetType", false, false);
            if (enumType?.IsEnum != true) return 0;
            try
            {
                var field = enumType.GetField(name, BindingFlags.Public | BindingFlags.Static);
                if (field?.GetRawConstantValue() is not { } raw) return 0;
                var resolved = Convert.ToInt32(raw, CultureInfo.InvariantCulture);
                if (resolved <= 0) return 0;
                NativeTriggerTargetTypeValues[name] = resolved;
                return resolved;
            }
            catch
            {
                return 0;
            }
        }
    }

    private static bool IsSelfRecoveryPowerTargetUnderPressure(
        int targetType,
        string? targetParam)
    {
        if (IsGuaranteedSelfPowerTarget(targetType)) return true;

        // Native GetTargetCombat forwards the third actionLowHpFriend target
        // parameter to AdvBattleData.GetLowHpFriendList(combat, isSelf). When
        // it is 1, the caster is part of the health-sorted friendly pool. The
        // survival preview applies pressure to this caster, so after damage it
        // is the lowest-health eligible recipient. Random friends explicitly
        // exclude the caster; front-friend selection remains position-dependent.
        var lowHealthFriendType = ResolveNativeTriggerTargetTypeValue(
            "actionLowHpFriend");
        if (lowHealthFriendType <= 0 || targetType != lowHealthFriendType)
            return false;
        var tokens = Clean(targetParam ?? string.Empty)
            .Split(',', StringSplitOptions.TrimEntries);
        return tokens.Length >= 3
               && int.TryParse(tokens[2], NumberStyles.Integer,
                   CultureInfo.InvariantCulture, out var includeSelf)
               && includeSelf == 1;
    }

    private static NativeSkillExecutionGraph ResolveNativeSkillExecutionGraph(
        object skillPreview,
        object skillInfo,
        int level,
        IReadOnlyCollection<int> displayedPowerIds)
    {
        var powers = new List<NativePowerInvocation>();
        var abilities = new List<NativeAbilityInvocation>();
        var summons = new List<NativeSummonInvocation>();
        // Classification comes from the authoritative skill -> action/produce
        // relationship before any numeric preview is attempted. A later native
        // factory/AI failure may make output unknown, but it must not erase the
        // fact that the object is an Ally, Minion, Totem, or other summon.
        var controlledEntityKinds = GetNativeControlledEntityKindsForSkillInfoCore(skillInfo);
        var failures = new HashSet<string>(StringComparer.Ordinal);
        var emitterStack = new HashSet<int>();
        var expandedEdges = 0;
        object? rootActionAttr = null;
        object? rootActionData = null;

        void Fail(string reason)
        {
            if (!string.IsNullOrWhiteSpace(reason)) failures!.Add(reason);
        }

        double BoundEvents(double events, string edge)
        {
            if (!double.IsFinite(events) || events <= 0d)
            {
                Fail($"invalid {edge} event count {events:0.###}");
                return 0d;
            }
            if (events <= MaximumPerformancePreviewEvents) return events;
            Fail($"{edge} event count exceeded the safe preview bound");
            return MaximumPerformancePreviewEvents;
        }

        List<NativeTimedEvent> BoundTimeline(IEnumerable<NativeTimedEvent> rawEvents, string edge)
        {
            const double previewWindowSeconds = PerformancePreviewWindowSeconds;
            const double maximumTimelineEvents = MaximumPerformancePreviewEvents;
            var ordered = new List<NativeTimedEvent>();
            foreach (var entry in rawEvents)
            {
                if (!double.IsFinite(entry.OffsetSeconds) || entry.OffsetSeconds < 0d
                    || !double.IsFinite(entry.Count) || entry.Count <= 0d)
                {
                    Fail($"invalid {edge} timed event {entry.OffsetSeconds:0.###}:{entry.Count:0.###}");
                    continue;
                }
                // Per-cast offsets at or beyond the preview horizon can never
                // fall inside its global half-open objective, even for cast one.
                if (entry.OffsetSeconds >= previewWindowSeconds) continue;
                ordered.Add(entry);
            }

            var result = new List<NativeTimedEvent>();
            var acceptedEvents = 0d;
            foreach (var entry in ordered.OrderBy(value => value.OffsetSeconds))
            {
                var remaining = maximumTimelineEvents - acceptedEvents;
                if (remaining <= 0d)
                {
                    Fail($"{edge} timed event count exceeded the safe preview bound");
                    break;
                }
                var accepted = Math.Min(entry.Count, remaining);
                if (accepted < entry.Count)
                    Fail($"{edge} timed event count exceeded the safe preview bound");
                if (result.Count > 0
                    && Math.Abs(result[^1].OffsetSeconds - entry.OffsetSeconds) <= 0.000000001d)
                {
                    var previous = result[^1];
                    result[^1] = previous with { Count = previous.Count + accepted };
                }
                else result.Add(new NativeTimedEvent(entry.OffsetSeconds, accepted));
                acceptedEvents += accepted;
                if (accepted < entry.Count) break;
            }
            return result;
        }

        static double TimelineEventCount(IEnumerable<NativeTimedEvent> timeline)
            => timeline.Sum(entry => entry.Count);

        List<NativeTimedEvent> ScaleTimeline(
            IReadOnlyList<NativeTimedEvent> timeline, double multiplier, string edge)
            => BoundTimeline(
                timeline.Select(entry => new NativeTimedEvent(entry.OffsetSeconds, entry.Count * multiplier)), edge);

        List<NativeTimedEvent> ExpandEmitterTimeline(
            IReadOnlyList<NativeTimedEvent> starts,
            IReadOnlyList<double> shotOffsets,
            int bulletCount,
            string edge)
        {
            const double previewWindowSeconds = PerformancePreviewWindowSeconds;
            const double maximumTimelineEvents = MaximumPerformancePreviewEvents;
            var queue = new PriorityQueue<(int StartIndex, int ShotIndex), double>();
            for (var startIndex = 0; startIndex < starts.Count; startIndex++)
            {
                if (shotOffsets.Count == 0) break;
                var firstOffset = starts[startIndex].OffsetSeconds + shotOffsets[0];
                if (firstOffset < previewWindowSeconds)
                    queue.Enqueue((startIndex, 0), firstOffset);
            }

            var result = new List<NativeTimedEvent>();
            var acceptedEvents = 0d;
            while (queue.TryDequeue(out var node, out var eventOffset))
            {
                var start = starts[node.StartIndex];
                var eventCount = start.Count * bulletCount;
                if (!double.IsFinite(eventCount) || eventCount <= 0d)
                {
                    Fail($"invalid {edge} expanded event count {eventCount:0.###}");
                    continue;
                }
                var remaining = maximumTimelineEvents - acceptedEvents;
                var accepted = Math.Min(eventCount, Math.Max(0d, remaining));
                if (accepted > 0d)
                {
                    if (result.Count > 0
                        && Math.Abs(result[^1].OffsetSeconds - eventOffset) <= 0.000000001d)
                    {
                        var previous = result[^1];
                        result[^1] = previous with { Count = previous.Count + accepted };
                    }
                    else result.Add(new NativeTimedEvent(eventOffset, accepted));
                    acceptedEvents += accepted;
                }

                var nextShotIndex = node.ShotIndex + 1;
                if (nextShotIndex < shotOffsets.Count)
                {
                    var nextOffset = start.OffsetSeconds + shotOffsets[nextShotIndex];
                    if (nextOffset < previewWindowSeconds)
                        queue.Enqueue((node.StartIndex, nextShotIndex), nextOffset);
                }
                if (accepted < eventCount || (acceptedEvents >= maximumTimelineEvents && queue.Count > 0))
                {
                    Fail($"{edge} timed event count exceeded the safe preview bound");
                    break;
                }
            }
            return result;
        }

        void AddPower(int powerId, double events, object triggerData, object sourceAttr,
            IReadOnlyList<NativeTimedEvent>? eventTimeline = null,
            int targetType = 0,
            string targetParam = "")
        {
            if (eventTimeline is not null)
            {
                eventTimeline = BoundTimeline(eventTimeline, $"power {powerId}");
                events = TimelineEventCount(eventTimeline);
                if (events <= 0d) return;
            }
            events = BoundEvents(events, $"power {powerId}");
            if (powerId <= 0 || events <= 0d)
            {
                Fail($"invalid power edge {powerId}:{events:0.###}");
                return;
            }
            try
            {
                var power = InvokeRequiredStaticMany("PowerData", "CreateByTrigger", powerId, level, triggerData);
                if (power is null)
                    throw new InvalidOperationException($"PowerData.CreateByTrigger({powerId}) returned no power.");
                powers.Add(new NativePowerInvocation(
                    powerId, level, events, sourceAttr, triggerData, power, eventTimeline,
                    targetType, targetParam));
            }
            catch (Exception error)
            {
                // CreateByShow would silently replace the action/bullet source
                // with the root SkillData attributes, so an unavailable trigger
                // preview is an unknown zero lower bound rather than a fallback.
                Fail($"power {powerId} trigger preview failed: {error.GetBaseException().Message}");
            }
        }

        void AddAbility(int abilityId, double events, object triggerData, object sourceAttr,
            IReadOnlyList<NativeTimedEvent>? eventTimeline = null,
            bool directUnconditionalActionTrigger = false)
        {
            if (eventTimeline is not null)
            {
                eventTimeline = BoundTimeline(eventTimeline, $"ability {abilityId}");
                events = TimelineEventCount(eventTimeline);
                if (events <= 0d) return;
            }
            events = BoundEvents(events, $"ability {abilityId}");
            if (abilityId <= 0 || events <= 0d)
            {
                Fail($"invalid ability edge {abilityId}:{events:0.###}");
                return;
            }
            abilities.Add(new NativeAbilityInvocation(
                abilityId, level, events, sourceAttr, triggerData, eventTimeline,
                DirectUnconditionalActionTrigger: directUnconditionalActionTrigger));
        }

        void AddSummon(int summonId, int count, object produceAttr, bool passiveSpawn = false)
        {
            if (summonId <= 0 || count <= 0)
            {
                Fail($"invalid summon edge {summonId}:{count}");
                return;
            }
            if (count > MaximumPerformancePreviewEvents)
            {
                Fail($"summon {summonId} count exceeded the safe preview bound");
                count = MaximumPerformancePreviewEvents;
            }
            var summonRow = InvokeStatic("TableData", "getTSummonData", summonId);
            if (summonRow is null)
            {
                Fail($"summon {summonId} table row is unavailable");
                return;
            }
            var nativeSummonType = ReadNullableInt(summonRow, "type") ?? 0;
            var kind = ClassifyNativeSummonType(nativeSummonType);
            if (kind == NativeControlledEntityKind.None)
            {
                Fail($"summon {summonId} has no native summon type");
                return;
            }
            controlledEntityKinds |= kind;
            summons.Add(new NativeSummonInvocation(
                summonId, level, count, produceAttr, nativeSummonType, passiveSpawn));
        }

        object? CreateTriggerPreview(int triggerId, string source, object sourceData)
        {
            try
            {
                var createType = CreateEnum("ETriggerCreateType", source == "action" ? 3 : 2)
                                 ?? throw new InvalidOperationException($"{source} trigger enum is unavailable.");
                var triggerData = InvokeRequiredStaticMany(
                    "TriggerData", "Create", triggerId, level, createType, sourceData);
                if (triggerData is null)
                    throw new InvalidOperationException($"TriggerData.Create({triggerId}) returned no trigger.");
                if (Read(triggerData, "inAttrData") is null || Read(triggerData, "skillData") is null)
                    throw new InvalidOperationException($"TriggerData.Create({triggerId}) lost its source attributes or skill.");
                return triggerData;
            }
            catch (Exception error)
            {
                Fail($"{source} trigger {triggerId} preview failed: {error.GetBaseException().Message}");
                return null;
            }
        }

        void VisitEmitter(int emitterId, double emitterEvents, int depth, object parentAttr, object? sourceBullet,
            IReadOnlyList<NativeTimedEvent>? emitterStartTimeline = null)
        {
            if (depth > 16 || ++expandedEdges > 2048)
            {
                Fail("skill trigger graph exceeded its safe expansion limit");
                return;
            }
            if (emitterId <= 0 || emitterEvents <= 0d)
            {
                Fail($"invalid emitter edge {emitterId}:{emitterEvents:0.###}");
                return;
            }
            // A shared emitter reached from two independent trigger branches must
            // contribute twice. Only an emitter already on the current recursion
            // path is a cycle.
            if (!emitterStack.Add(emitterId))
            {
                Fail($"cyclic emitter {emitterId}");
                return;
            }
            try
            {
                var emitterRow = InvokeStatic("TableData", "getTEmitterData", emitterId);
                var emitterAttrRows = Read(emitterRow, "attrArr");
                var emitterOwner = CreateEnum("EAttrOwnType", 4);
                if (emitterRow is null || emitterAttrRows is null || emitterOwner is null)
                {
                    Fail($"emitter table/attribute input {emitterId} unavailable");
                    return;
                }
                object? emitterData;
                object? emitterAttr;
                if (sourceBullet is null)
                {
                    emitterAttr = InvokeRequiredStaticMany(
                        "AttrData", "Create", emitterOwner, parentAttr, emitterAttrRows);
                    emitterData = InvokeRequiredStaticMany(
                        "EmitterData", "CreateByShow", emitterId, level, skillPreview);
                    if (emitterData is not null && emitterAttr is not null)
                    {
                        Write(emitterData, "attrData", emitterAttr);
                        if (rootActionData is not null) Write(emitterData, "ownActionData", rootActionData);
                    }
                    // Native InitByAction runs a small battle-state extra-effect
                    // hook for these table rows. Calling it without CombatData can
                    // crash, so retain only the raw lower bound and fail closed.
                    if (emitterId is 35051 or 36091 or 36111)
                        Fail($"emitter {emitterId} requires a live extra-effect context");
                }
                else
                {
                    emitterData = InvokeRequiredStaticMany(
                        "EmitterData", "CreateByBullet", emitterId, level, sourceBullet);
                    emitterAttr = Read(emitterData, "attrData");
                }
                if (emitterData is null || emitterAttr is null)
                {
                    Fail($"emitter {emitterId} native preview failed");
                    return;
                }
                InvokeRequiredInstance(emitterData, "createShotData");
                var shotAttr = Read(emitterData, "shotData");
                if (shotAttr is null)
                {
                    Fail($"emitter {emitterId} shot attributes unavailable");
                    return;
                }
                var bulletId = ReadIntAttrRequired(shotAttr, 4001);
                var bullet = bulletId > 0
                    ? InvokeRequiredStaticMany("BulletData", "CreateByShow", bulletId, Math.Max(1, level), shotAttr)
                    : null;
                var bulletRow = Read(bullet, "tBulletData");
                if (bullet is null || bulletRow is null)
                {
                    Fail($"emitter {emitterId} has no preview bullet {bulletId}");
                    return;
                }

                var bulletAttr = Read(bullet, "attrData");
                if (bulletAttr is null)
                {
                    Fail($"emitter {emitterId} attributes unavailable");
                    return;
                }
                Write(bullet, "ownEmitterData", emitterData);
                var bulletCount = ReadIntAttrRequired(shotAttr, 4002);
                var emitterLifeTime = (float)ReadAttrRequired(shotAttr, 4006);
                var shotInterval = (float)ReadAttrRequired(shotAttr, 4007);
                var shotLimit = (float)ReadAttrRequired(shotAttr, 4008);
                if (bulletCount <= 0)
                {
                    Fail($"emitter {emitterId} has no proven bullet count ({bulletCount})");
                    return;
                }
                if (!float.IsFinite(emitterLifeTime) || emitterLifeTime < 0f
                    || !float.IsFinite(shotInterval) || shotInterval < 0f
                    || !float.IsFinite(shotLimit))
                {
                    Fail($"emitter {emitterId} has an invalid native shot schedule "
                         + $"(life={emitterLifeTime:0.###}, interval={shotInterval:0.###}, max={shotLimit:0.###})");
                    return;
                }
                var shotSchedule = BuildNativeEmitterShotOffsets(emitterLifeTime, shotInterval, shotLimit);
                if (!shotSchedule.IsComplete && !string.IsNullOrWhiteSpace(shotSchedule.Failure))
                    Fail($"emitter {emitterId} {shotSchedule.Failure}");
                if (shotSchedule.Offsets.Count == 0) return;
                var hitTimes = ReadIntAttrRequired(bulletAttr, 5002);
                var starts = emitterStartTimeline is null
                    ? BoundTimeline(new[] { new NativeTimedEvent(0d, emitterEvents) }, $"emitter {emitterId} start")
                    : BoundTimeline(emitterStartTimeline, $"emitter {emitterId} start");
                var createdTimeline = ExpandEmitterTimeline(
                    starts, shotSchedule.Offsets, bulletCount, $"emitter {emitterId}");
                var createdBullets = TimelineEventCount(createdTimeline);
                if (createdBullets <= 0d) return;
                VisitTriggers(
                    ReadSequence(Read(bulletRow, "triggerArr")).Select(ToInt).Where(id => id > 0),
                    "bullet", bullet, createdBullets, hitTimes, depth + 1, createdTimeline);
            }
            catch (Exception error)
            {
                Fail($"emitter {emitterId} preview failed: {error.GetBaseException().Message}");
            }
            finally
            {
                emitterStack.Remove(emitterId);
            }
        }

        void VisitTriggers(IEnumerable<int> triggerIds, string source, object sourceData,
            double sourceEvents, int hitTimes = 0, int depth = 0,
            IReadOnlyList<NativeTimedEvent>? sourceTimeline = null)
        {
            foreach (var triggerId in triggerIds)
            {
                if (depth > 16 || ++expandedEdges > 2048)
                {
                    Fail("skill trigger graph exceeded its safe expansion limit");
                    return;
                }
                var trigger = InvokeStatic("TableData", "getTTriggerData", triggerId);
                if (trigger is null)
                {
                    Fail($"trigger {triggerId} unavailable");
                    continue;
                }
                var rawCondition = Clean(ReadString(trigger, "condition") ?? string.Empty);
                var conditionProbability = 1d;
                if (rawCondition.Length > 0)
                {
#if PATHOFIDLE_RUNTIME_TEST
                    Plugin.DiagInfo(
                        $"AUTO-SKILLS TRIGGER CONDITION|id={triggerId}"
                        + $"|source={source}"
                        + $"|moment={ReadNullableInt(trigger, "moment") ?? 0}"
                        + $"|index={ReadNullableInt(trigger, "index") ?? 0}"
                        + $"|level={ReadNullableInt(trigger, "level") ?? 0}"
                        + $"|condition={rawCondition.Replace('|', '/')}"
                        + $"|target={Clean(ReadString(trigger, "targetParam") ?? string.Empty).Replace('|', '/')}");
#endif
                    // A condition made solely from native percent-roll clauses
                    // needs no live battle state. Represent its expectation as a
                    // fractional event count over the fixed preview window. Any
                    // additional state predicate still fails closed.
                    if (!TryReadPureNativeChanceCondition(rawCondition, out conditionProbability))
                    {
                        Fail($"trigger {triggerId} has an unsupported battle condition '{rawCondition}'");
                        continue;
                    }
                }
                var moment = ReadNullableInt(trigger, "moment") ?? 0;
                double resultEvents;
                IReadOnlyList<NativeTimedEvent>? resultTimeline = null;
                if (source == "action")
                {
                    if (moment != 2)
                    {
                        Fail($"action trigger {triggerId} uses moment {moment}");
                        continue;
                    }
                    resultEvents = sourceEvents;
                }
                else
                {
                    if (sourceTimeline is null)
                    {
                        Fail($"bullet trigger {triggerId} has no proven event timeline");
                        continue;
                    }
                    if (moment == 1 && hitTimes <= 0)
                    {
                        Fail($"bullet trigger {triggerId} has no proven hit count ({hitTimes})");
                        continue;
                    }
                    resultTimeline = moment switch
                    {
                        1 => ScaleTimeline(sourceTimeline, hitTimes, $"trigger {triggerId}"),
                        4 or 6 => BoundTimeline(sourceTimeline, $"trigger {triggerId}"),
                        _ => Array.Empty<NativeTimedEvent>()
                    };
                    resultEvents = TimelineEventCount(resultTimeline);
                    if (resultEvents <= 0d)
                    {
                        Fail($"bullet trigger {triggerId} uses conditional moment {moment}");
                        continue;
                    }
                }
                if (conditionProbability < 1d)
                {
                    resultEvents *= conditionProbability;
                    if (resultTimeline is not null)
                        resultTimeline = ScaleTimeline(
                            resultTimeline, conditionProbability, $"trigger {triggerId} chance");
#if PATHOFIDLE_RUNTIME_TEST
                    Plugin.DiagInfo(
                        $"AUTO-SKILLS EXPECTED TRIGGER|id={triggerId}"
                        + $"|opportunities={(conditionProbability > 0d ? resultEvents / conditionProbability : 0d):0.###}"
                        + $"|probability={conditionProbability:0.######}"
                        + $"|expected={resultEvents:0.###}"
                        + $"|window={PerformancePreviewWindowSeconds:0.###}");
#endif
                }
                resultEvents = BoundEvents(resultEvents, $"trigger {triggerId}");
                if (resultEvents <= 0d) continue;

                List<int[]> rows;
                try { rows = ReadIntMatrixRows(Read(trigger, "resultArrArr"), 2); }
                catch (Exception error)
                {
                    Fail($"trigger {triggerId} result matrix failed: {error.GetBaseException().Message}");
                    continue;
                }
                if (rows.Count == 0)
                {
                    Fail($"trigger {triggerId} has no results");
                    continue;
                }
                var triggerData = rows.Any(row => row[0] is 1 or 2)
                    ? CreateTriggerPreview(triggerId, source, sourceData)
                    : null;
                var nativeTargetParams = Clean(ReadString(trigger, "targetParam") ?? string.Empty)
                    .Split(';', StringSplitOptions.TrimEntries);
#if PATHOFIDLE_DIAGNOSTICS
                var nativeSkillIdForDiagnostics =
                    ReadNullableInt(Read(skillPreview, "tSkillData"), "id") ?? 0;
#endif
                for (var rowIndex = 0; rowIndex < rows.Count; rowIndex++)
                {
                    var row = rows[rowIndex];
                    var resultType = row[0];
                    var payloadId = row[1];
#if PATHOFIDLE_DIAGNOSTICS
                    Plugin.DiagInfo(
                        $"AUTO-SKILL TRIGGER RESULT|skill={nativeSkillIdForDiagnostics}|trigger={triggerId}|row={rowIndex}|resultType={resultType}|payload={payloadId}|target={(rowIndex < nativeTargetParams.Length ? nativeTargetParams[rowIndex] : string.Empty)}|allTargets={string.Join(';', nativeTargetParams)}");
#endif
                    switch (resultType)
                    {
                        case 1:
                            if (triggerData is null) break;
                            var nativeTargetParam = rowIndex < nativeTargetParams.Length
                                ? nativeTargetParams[rowIndex]
                                : string.Empty;
                            AddPower(payloadId, resultEvents, triggerData,
                                Read(triggerData, "inAttrData")!, resultTimeline,
                                ParseNativeTriggerTargetType(nativeTargetParam),
                                nativeTargetParam);
                            break;
                        case 2:
                            if (triggerData is null) break;
                            AddAbility(payloadId, resultEvents, triggerData,
                                Read(triggerData, "inAttrData")!, resultTimeline,
                                directUnconditionalActionTrigger: source == "action"
                                                                  && rawCondition.Length == 0);
                            break;
                        case 3:
                            if (source != "bullet")
                                Fail($"trigger {triggerId} creates emitter {payloadId} outside bullet context");
                            else
                                VisitEmitter(payloadId, resultEvents, depth + 1,
                                    Read(sourceData, "attrData")!, sourceData, resultTimeline);
                            break;
                        default:
                            Fail($"trigger {triggerId} has unknown result type {resultType}");
                            break;
                    }
                }
            }
        }

        var actionId = ReadNullableInt(skillInfo, "actionId") ?? 0;
        var action = actionId > 0 ? InvokeStatic("TableData", "getTActionData", actionId) : null;
        if (action is null || (ReadNullableInt(action, "type") ?? 0) != 3)
        {
            bool HasNativeSummonTuple(int produceId)
            {
                var produce = InvokeStatic("TableData", "getTProduceData", produceId);
                if (produce is null) return false;
                var rows = ReadFloatMatrixRows(Read(produce, "attrArr"), 2);
                var summonId = rows.Where(row => row.Length >= 2
                                                  && Convert.ToInt32(
                                                      row[0], CultureInfo.InvariantCulture) == 6001)
                    .Select(row => Convert.ToInt32(row[1], CultureInfo.InvariantCulture))
                    .FirstOrDefault(id => id > 0);
                var summonCount = rows.Where(row => row.Length >= 2
                                                     && Convert.ToInt32(
                                                         row[0], CultureInfo.InvariantCulture) == 6002)
                    .Select(row => Convert.ToInt32(row[1], CultureInfo.InvariantCulture))
                    .FirstOrDefault(value => value > 0);
                return summonId > 0 && summonCount > 0;
            }
            var passiveProduceIds = actionId <= 0
                ? ReadSequence(Read(skillInfo, "otherParam"))
                    .Select(ToInt).Where(id => id > 0)
                    .Where(HasNativeSummonTuple)
                    .Distinct().ToList()
                : new List<int>();
            var passiveSummonsBefore = summons.Count;
            foreach (var produceId in passiveProduceIds)
            {
                try
                {
                    // CombatUnit.CreateBuddyProduce uses ProduceData.CreateBySkill.
                    // Use that same native factory so inherited attributes and a
                    // future table shape are interpreted by the game, not copied
                    // by a plugin-specific rule.
                    var fieldIndex = ReadNullableInt(skillPreview, "fieldIndex") ?? 0;
                    object? produceAttr = null;
                    string? nativeFactoryFailure = null;
                    try
                    {
                        var produceData = InvokeRequiredStaticMany(
                            "ProduceData", "CreateBySkill",
                            fieldIndex, produceId, Vector3.zero, skillPreview);
                        produceAttr = Read(produceData, "attrData");
                        if (produceData is null || produceAttr is null)
                            nativeFactoryFailure = "returned no produce attributes";
                    }
                    catch (Exception error)
                    {
                        nativeFactoryFailure = error.GetBaseException().Message;
                    }

                    if (produceAttr is null)
                    {
                        // CreateBySkill needs a live owner on some companion
                        // skills. Reconstruct exactly the data-only portion of
                        // that factory through the same native AttrData.Create
                        // path used by action-owned produces. The TProduce row
                        // and owner enum remain authoritative; no item/skill id
                        // or translated text is involved.
                        var produceRow = InvokeStatic("TableData", "getTProduceData", produceId);
                        var produceOwner = CreateEnum("EAttrOwnType", 6);
                        var parentAttr = Read(skillPreview, "attrData");
                        var produceAttrRows = Read(produceRow, "attrArr");
                        if (produceRow is null || produceOwner is null
                            || parentAttr is null || produceAttrRows is null)
                            throw new InvalidOperationException(
                                $"passive companion produce {produceId} native factory failed ({nativeFactoryFailure}); table fallback inputs are unavailable");
                        produceAttr = InvokeRequiredStaticMany(
                            "AttrData", "Create", produceOwner, parentAttr, produceAttrRows);
                        if (produceAttr is null)
                            throw new InvalidOperationException(
                                $"passive companion produce {produceId} native factory failed ({nativeFactoryFailure}); AttrData fallback returned no attributes");
                    }
                    var summonId = ReadIntAttrRequired(produceAttr, 6001);
                    var summonCount = ReadIntAttrRequired(produceAttr, 6002);
                    if (summonId <= 0 || summonCount <= 0)
                    {
                        Fail($"passive companion produce {produceId} has an incomplete summon tuple {summonId}:{summonCount}");
                        continue;
                    }
                    AddSummon(summonId, summonCount, produceAttr, passiveSpawn: true);
                }
                catch (Exception error)
                {
                    Fail($"passive companion produce {produceId} failed: {error.GetBaseException().Message}");
                }
            }
            if (summons.Count == passiveSummonsBefore)
                Fail($"skill action {actionId} unavailable or not a skill action");
        }
        else
        {
            var skillAttr = Read(skillPreview, "attrData");
            var actionOwner = CreateEnum("EAttrOwnType", 3);
            if (skillAttr is null || actionOwner is null)
            {
                Fail($"skill action {actionId} attributes unavailable");
            }
            else
            {
                rootActionAttr = InvokeRequiredStaticMany("AttrData", "Create", actionOwner, skillAttr, (object)null!);
                if (rootActionAttr is null) Fail($"skill action {actionId} attribute preview failed");
            }
            if (rootActionAttr is not null)
            {
                try
                {
                    rootActionData = MainThreadNativeGateway.Invoke(() =>
                    {
                        var actionType = GameType("ActionData")
                                         ?? throw new InvalidOperationException("ActionData type is unavailable.");
                        return Activator.CreateInstance(actionType)
                               ?? throw new InvalidOperationException("ActionData preview allocation failed.");
                    });
                    Write(rootActionData, "fieldIndex", 0);
                    Write(rootActionData, "level", level);
                    Write(rootActionData, "tActionData", action);
                    Write(rootActionData, "ownSkillData", skillPreview);
                    Write(rootActionData, "attrData", rootActionAttr);
                }
                catch (Exception error)
                {
                    rootActionData = null;
                    Fail($"skill action {actionId} source preview failed: {error.GetBaseException().Message}");
                }
                if (rootActionData is not null)
                    VisitTriggers(ReadSequence(Read(action, "triggerArr")).Select(ToInt).Where(id => id > 0),
                        "action", rootActionData, 1d);
                var emitterId = ReadNullableInt(action, "emitterId") ?? 0;
                if (emitterId > 0)
                {
                    VisitEmitter(emitterId, 1d, 0, rootActionAttr, null);
                    var tagIds = ReadSequence(Read(skillInfo, "tagArr"))
                        .Select(ToInt).Where(id => id > 0);
                    if (HasNativeSkillTag(tagIds, "totem"))
                        controlledEntityKinds |= NativeControlledEntityKind.Totem;
                }

                var produceId = ReadNullableInt(action, "produceId") ?? 0;
                if (produceId > 0)
                {
                    var produceRow = InvokeStatic("TableData", "getTProduceData", produceId);
                    var produceOwner = CreateEnum("EAttrOwnType", 6);
                    var produceAttrRows = Read(produceRow, "attrArr");
                    if (produceRow is null || produceOwner is null || produceAttrRows is null)
                        Fail($"produce {produceId} table/attributes unavailable");
                    else
                    {
                        var produceAttr = InvokeRequiredStaticMany(
                            "AttrData", "Create", produceOwner, rootActionAttr, produceAttrRows);
                        if (produceAttr is null) Fail($"produce {produceId} attribute preview failed");
                        else
                        {
                            var summonId = ReadIntAttrRequired(produceAttr, 6001);
                            var summonCount = ReadIntAttrRequired(produceAttr, 6002);
                            if (summonId > 0 || summonCount > 0)
                            {
                                if (summonId <= 0 || summonCount <= 0)
                                    Fail($"produce {produceId} has an incomplete summon tuple {summonId}:{summonCount}");
                                else
                                    AddSummon(summonId, summonCount, produceAttr);
                            }
                        }
                    }
                }
            }
        }

        var reachedPowerIds = powers.Select(invocation => invocation.PowerId).ToHashSet();
        var unreachableDisplayed = displayedPowerIds.Where(id => id > 0 && !reachedPowerIds.Contains(id)).Distinct().ToList();
        if (unreachableDisplayed.Count > 0)
            Fail($"display powers are unreachable: {string.Join(',', unreachableDisplayed)}");
        return new NativeSkillExecutionGraph(
            powers,
            abilities,
            summons,
            controlledEntityKinds,
            failures.Count == 0,
            string.Join("; ", failures.OrderBy(value => value)));
    }

    private static (List<double> Offsets, bool IsComplete, string Failure)
        BuildNativeEmitterShotOffsets(float lifeTime, float interval, float maximumShots)
    {
        const double previewWindowSeconds = PerformancePreviewWindowSeconds;
        const int maximumPreviewEvents = MaximumPerformancePreviewEvents;
        if (!float.IsFinite(lifeTime) || lifeTime < 0f
            || !float.IsFinite(interval) || interval < 0f
            || !float.IsFinite(maximumShots))
            return (new List<double>(), false, "has an invalid native shot schedule");

        // Native OnInit calls shot() immediately for a zero interval. It does
        // not enter Update's attr4008 comparison on that path, so even a zero or
        // negative maximum still produces this one native initialization shot.
        if (interval == 0f) return (new List<double> { 0d }, true, string.Empty);

        // In Update, zero means unlimited. A negative maximum rejects the first
        // scheduled update shot. A positive fractional maximum is compared with
        // the integer completed-shot count and therefore permits ceil(maximum).
        if (maximumShots < 0f) return (new List<double>(), true, string.Empty);

        // The native lifetime comparison is `nowLifeTime > lifeTime`, so an
        // event exactly on the lifetime boundary is still allowed. The preview
        // objective is half-open: an event exactly at its horizon is outside it.
        var duration = Math.Min((double)lifeTime, Math.BitDecrement(previewWindowSeconds));
        var initialAccumulator = interval * 0.6f;
        var firstDelay = (double)interval - initialAccumulator;
        if (duration < firstDelay) return (new List<double>(), true, string.Empty);

        var maximumByAttr = maximumShots > 0f
            ? Math.Ceiling((double)maximumShots)
            : double.PositiveInfinity;
        var offsets = new List<double>(Math.Min(maximumPreviewEvents,
            maximumByAttr >= maximumPreviewEvents ? maximumPreviewEvents : (int)maximumByAttr));
        var wasCapped = false;
        for (var index = 0; index <= maximumPreviewEvents; index++)
        {
            if (index >= maximumByAttr) break;
            var offset = firstDelay + index * (double)interval;
            if (offset > duration) break;
            if (offsets.Count >= maximumPreviewEvents)
            {
                wasCapped = true;
                break;
            }
            offsets.Add(offset);
        }
        return (offsets, !wasCapped,
            wasCapped ? "shot schedule exceeded the safe preview bound" : string.Empty);
    }

    private static double CountNativeTimedEventsInPreviewWindow(
        IReadOnlyList<NativeTimedEvent> rawTimeline,
        double castOpportunities,
        double cycleSeconds,
        double firstCastOffsetSeconds)
    {
        const double previewWindowSeconds = PerformancePreviewWindowSeconds;
        if (!double.IsFinite(castOpportunities) || castOpportunities <= 0d
            || !double.IsFinite(cycleSeconds) || cycleSeconds <= 0d
            || !double.IsFinite(firstCastOffsetSeconds) || firstCastOffsetSeconds < 0d)
            return 0d;

        var timeline = rawTimeline
            .Where(entry => double.IsFinite(entry.OffsetSeconds) && entry.OffsetSeconds >= 0d
                            && entry.OffsetSeconds < previewWindowSeconds
                            && double.IsFinite(entry.Count) && entry.Count > 0d)
            .OrderBy(entry => entry.OffsetSeconds)
            .ToList();
        if (timeline.Count == 0) return 0d;

        var prefixCounts = new double[timeline.Count + 1];
        for (var index = 0; index < timeline.Count; index++)
            prefixCounts[index + 1] = prefixCounts[index] + timeline[index].Count;
        var castCount = Math.Min(MaximumPerformancePreviewEvents, Math.Max(0,
            Convert.ToInt32(Math.Floor(castOpportunities + 0.0000001d), CultureInfo.InvariantCulture)));
        var total = 0d;
        for (var castIndex = 0; castIndex < castCount; castIndex++)
        {
            var castTime = firstCastOffsetSeconds + castIndex * cycleSeconds;
            if (castTime >= previewWindowSeconds) break;
            var remaining = previewWindowSeconds - castTime;
            // Upper-bound search for offsets strictly below the remaining time;
            // an event exactly at t=60 is outside the half-open objective.
            var low = 0;
            var high = timeline.Count;
            while (low < high)
            {
                var middle = low + (high - low) / 2;
                if (timeline[middle].OffsetSeconds < remaining) low = middle + 1;
                else high = middle;
            }
            total += prefixCounts[low];
        }
        return double.IsFinite(total) ? total : 0d;
    }

    private static NativeSkillAlwaysOnPreview ReadNativeSkillAlwaysOnPreview(
        object skillPreview,
        object skillInfo,
        int level,
        NativeSkillExecutionGraph executionGraph)
    {
        var failures = new HashSet<string>(StringComparer.Ordinal);
        var contributions = new List<NativeStrictAbilityContribution>();
        var previewAttr = Read(skillPreview, "attrData");
        if (previewAttr is null)
            return new NativeSkillAlwaysOnPreview(contributions, false, "skill ability attributes are unavailable");

        // Preserve the native TSkillInfo.infoArr order. A static result301 is
        // acquired once and its signed delta is applied before the package is
        // re-previewed; it is not iterated to a fabricated fixed point.
        var displayedLevels = new Dictionary<int, int>();
        var displayedOrder = new List<int>();
        foreach (var explainId in ReadSequence(Read(skillInfo, "infoArr")).Select(ToInt).Where(id => id > 0))
        {
            var explain = InvokeStatic("TableData", "getTSkillExplainData", explainId);
            if ((ReadNullableInt(explain, "type") ?? -1) is not (3 or 4 or 103)) continue;
            var parameters = ReadSequence(Read(explain, "typeParam")).Select(ToInt).Where(value => value > 0).ToList();
            if (parameters.Count == 0) continue;
            var abilityId = parameters[0];
            var abilityLevel = parameters.Count > 1 ? Math.Max(1, parameters[1]) : Math.Max(1, level);
            if (!displayedLevels.ContainsKey(abilityId)) displayedOrder.Add(abilityId);
            displayedLevels[abilityId] = Math.Max(displayedLevels.GetValueOrDefault(abilityId), abilityLevel);
        }

        var triggeredIds = executionGraph.AbilityInvocations.Select(invocation => invocation.AbilityId).ToHashSet();
        foreach (var abilityId in displayedOrder)
        {
            if (triggeredIds.Contains(abilityId)) continue;
            var abilityLevel = displayedLevels[abilityId];
            var preview = InvokeStaticMany("AbilityData", "CreateByShow", abilityId, abilityLevel, previewAttr);
            var row = Read(preview, "tAbilityData") ?? ResolveAbilityTableRow(abilityId, abilityLevel);
            if (row is null)
            {
                failures.Add($"display ability {abilityId} is unavailable");
                continue;
            }
            var candidate = preview ?? row;
            if (!IsStrictAlwaysOnSelfAbility(candidate)) continue;
            if (preview is null)
            {
                failures.Add($"strict result301 ability {abilityId} has no side-effect-free preview");
                continue;
            }
            var deltas = ReadNativeAbilityResultAttrDeltas(preview);
            if (deltas.Count == 0)
            {
                failures.Add($"strict result301 ability {abilityId} produced no readable signed deltas");
                continue;
            }
            var resolvedId = ReadNullableInt(row, "id") ?? ReadNullableInt(preview, "id") ?? abilityId;
            var stackLimit = Math.Max(1, ReadNullableInt(row, "stack") ?? 1);
            contributions.Add(new NativeStrictAbilityContribution(resolvedId, stackLimit, deltas));
        }
        return new NativeSkillAlwaysOnPreview(
            contributions,
            failures.Count == 0,
            string.Join("; ", failures.OrderBy(value => value)));
    }

    private static object CreateStrictSkillPackageAdjustedAttr(
        object hero,
        IEnumerable<(int SkillId, int Level)> packageSkills,
        object attrData,
        bool applyCurrentEquipmentVariant,
        IEnumerable<GearCandidate>? candidateItems,
        out bool applied,
        IReadOnlyDictionary<int, int>? preAppliedAbilityCounts = null,
        IDictionary<(int SkillId, int Level), NativeSkillAlwaysOnPreview>? previewCache = null)
    {
        var skills = packageSkills.ToList();
        var items = candidateItems?.ToList();
        var result = MainThreadNativeGateway.Invoke(() =>
        {
            var adjusted = CreateStrictSkillPackageAdjustedAttrCore(
                hero, skills, attrData, applyCurrentEquipmentVariant, items,
                out var localApplied, preAppliedAbilityCounts, previewCache);
            return (Adjusted: adjusted, Applied: localApplied);
        });
        applied = result.Applied;
        return result.Adjusted;
    }

    private static object CreateStrictSkillPackageAdjustedAttrCore(
        object hero,
        IEnumerable<(int SkillId, int Level)> packageSkills,
        object attrData,
        bool applyCurrentEquipmentVariant,
        IEnumerable<GearCandidate>? candidateItems,
        out bool applied,
        IReadOnlyDictionary<int, int>? preAppliedAbilityCounts = null,
        IDictionary<(int SkillId, int Level), NativeSkillAlwaysOnPreview>? previewCache = null)
    {
        const int maxAbilityApplications = 256;
        var contributions = new List<NativeStrictAbilityContribution>();
        foreach (var entry in packageSkills
                     .Where(entry => entry.SkillId > 0)
                     .Select(entry => (entry.SkillId, Level: Math.Max(1, entry.Level)))
                     .Distinct()
                     .Take(maxAbilityApplications + 1))
        {
            if (contributions.Count >= maxAbilityApplications)
                throw new InvalidOperationException("The selected skill package exceeded the strict ability preview bound.");
            NativeSkillAlwaysOnPreview abilityPreview;
            if (previewCache is not null
                && previewCache.TryGetValue((entry.SkillId, entry.Level), out var cachedPreview))
            {
                abilityPreview = cachedPreview;
            }
            else
            {
                var preview = InvokeRequiredStaticMany("SkillData", "CreatePreview", entry.SkillId, entry.Level, attrData)
                              ?? throw new InvalidOperationException($"SkillData.CreatePreview({entry.SkillId}) returned no skill.");
                var variantEnabled = (candidateItems is not null && CandidateEnablesSkillVariant(candidateItems, entry.SkillId))
                                     || (applyCurrentEquipmentVariant && CurrentEquipmentEnablesSkillVariant(hero, entry.SkillId));
                if (variantEnabled) InvokeRequiredInstance(preview, "SetVariant", true);
                var info = Read(preview, "tSkillInfoData")
                           ?? throw new InvalidOperationException($"Skill {entry.SkillId} info is unavailable.");
                var displayedPowerIds = ReadSequence(Read(info, "infoArr")).Select(ToInt).Where(id => id > 0)
                    .Select(id => InvokeStatic("TableData", "getTSkillExplainData", id))
                    .Where(row => (ReadNullableInt(row, "type") ?? -1) == 2)
                    .Select(row => ReadSequence(Read(row, "typeParam")).Select(ToInt).FirstOrDefault())
                    .Where(id => id > 0).Distinct().ToList();
                var graph = ResolveNativeSkillExecutionGraph(preview, info, entry.Level, displayedPowerIds);
                abilityPreview = ReadNativeSkillAlwaysOnPreview(preview, info, entry.Level, graph);
                if (previewCache is not null)
                    previewCache[(entry.SkillId, entry.Level)] = abilityPreview;
            }
            if (!abilityPreview.IsComplete)
                throw new InvalidOperationException(
                    $"Skill {entry.SkillId} strict ability preview is incomplete: {abilityPreview.Failure}");
            contributions.AddRange(abilityPreview.Contributions);
        }

        return ApplyStrictAbilityContributions(
            attrData, contributions, out applied, preAppliedAbilityCounts);
    }

    private static object ApplyStrictAbilityContributions(
        object attrData,
        IEnumerable<NativeStrictAbilityContribution> rawContributions,
        out bool applied,
        IReadOnlyDictionary<int, int>? preAppliedAbilityCounts = null)
    {
        const int maxAbilityApplications = 256;
        var contributions = rawContributions.ToList();
        applied = false;
        if (contributions.Count == 0) return attrData;
        var adjusted = InvokeRequiredStaticMany("AttrData", "copyCreate", attrData)
                       ?? throw new InvalidOperationException("Skill ability-adjusted AttrData copy failed.");
        var appliedCounts = preAppliedAbilityCounts is null
            ? new Dictionary<int, int>()
            : new Dictionary<int, int>(preAppliedAbilityCounts);
        var applicationCount = 0;
        foreach (var contribution in contributions)
        {
            if (appliedCounts.GetValueOrDefault(contribution.AbilityId) >= contribution.StackLimit) continue;
            if (++applicationCount > maxAbilityApplications)
                throw new InvalidOperationException("The selected skill package exceeded the strict ability application bound.");
            foreach (var delta in contribution.AttrDeltas.OrderBy(entry => entry.Key))
            {
                var attrType = CreateEnum("EAttrType", delta.Key)
                               ?? throw new InvalidOperationException($"Unknown skill ability result attribute {delta.Key}.");
                InvokeRequiredInstance(adjusted, "ChangeAttr", attrType,
                    Convert.ToSingle(delta.Value, CultureInfo.InvariantCulture));
            }
            appliedCounts[contribution.AbilityId] = appliedCounts.GetValueOrDefault(contribution.AbilityId) + 1;
            applied = true;
        }
        return applied ? adjusted : attrData;
    }

    private static int GetPlannedSkillEffectiveLevel(
        object hero,
        PlannedSkillTarget planned,
        int skillId,
        IEnumerable<GearCandidate> candidateItems)
    {
        var granted = Math.Max(0, GetGrantedSkillLevel(candidateItems, skillId));
        if (skillId == planned.BaseSkillId)
            return Math.Max(1, Math.Max(planned.BaseSkillLevel, granted));
        var talentId = planned.TalentIds
            .Where(id => (ReadNullableInt(InvokeStatic("TableData", "getTTalentData", id), "skillId") ?? 0) == skillId)
            .OrderBy(id => id)
            .FirstOrDefault();
        var savedTarget = talentId > 0 ? planned.TargetSavedLevels.GetValueOrDefault(talentId) : 0;
        var runtimeTalent = ReadValues(Read(Read(hero, "heroTalentData"), "talentDic"))
            .FirstOrDefault(talent => (ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0) == talentId);
        var baseLevel = runtimeTalent is null ? 0 : GetTalentBaseLevelRequired(runtimeTalent);
        return Math.Max(1, Math.Max(baseLevel + savedTarget, granted));
    }

    private static object CreateNativeSummonAttr(object summonRow, int summonLevel, object produceAttr)
    {
        var inheritParameters = ReadSequence(Read(summonRow, "attrInheritParam"))
            .Select(value => Convert.ToDouble(value, CultureInfo.InvariantCulture)).ToList();
        if (inheritParameters.Count < 3 || inheritParameters.Take(3).Any(value => !double.IsFinite(value)))
            throw new InvalidOperationException("TSummon.attrInheritParam does not contain three finite coefficients.");

        var extraRates = ReadFloatMatrixRows(Read(summonRow, "extraAttrInheritRateArr"), 2);
        var summonType = ReadNullableInt(summonRow, "type") ?? 0;
        var baseRate = Convert.ToDouble(Read(summonRow, "attrInheritRate") ?? 0d, CultureInfo.InvariantCulture);
        if (!double.IsFinite(baseRate))
            throw new InvalidOperationException("TSummon.attrInheritRate is not finite.");
        var levelValue = summonLevel * (double)summonLevel * inheritParameters[0]
                         + summonLevel * inheritParameters[1]
                         + inheritParameters[2];
        if (!double.IsFinite(levelValue))
            throw new InvalidOperationException("TSummon inheritance level polynomial is not finite.");

        var rates = new Dictionary<int, float>();
        foreach (var attrRow in ReadValues(ReadStatic("TableData", "TAttrDict")))
        {
            var attrId = ReadNullableInt(attrRow, "id") ?? 0;
            var inheritType = ReadNullableInt(attrRow, "inheritType") ?? 0;
            if (attrId <= 0 || inheritType <= 0 || inheritType > summonType) continue;
            var extra = extraRates
                .Where(row => row.Length >= 2 && Convert.ToInt32(row[0], CultureInfo.InvariantCulture) == attrId)
                .Select(row => row[1]).FirstOrDefault();
            var rate = (baseRate + extra) * levelValue / 100d;
            if (!double.IsFinite(rate) || rate < float.MinValue || rate > float.MaxValue)
                throw new InvalidOperationException($"Summon inheritance rate for attribute {attrId} is invalid.");
            rates[attrId] = (float)rate;
        }

        var summonAttr = MainThreadNativeGateway.Invoke(() =>
        {
            var attrDataType = GameType("AttrData")
                               ?? throw new InvalidOperationException("AttrData type is unavailable.");
            var createPercent = attrDataType.GetMethods(BindingFlags.Public | BindingFlags.Static)
                .SingleOrDefault(method => method.Name == "CreatePercent" && method.GetParameters().Length == 4)
                                ?? throw new MissingMethodException("AttrData", "CreatePercent");
            var dictionaryType = createPercent.GetParameters()[2].ParameterType;
            var nativeRates = Activator.CreateInstance(dictionaryType)
                              ?? throw new InvalidOperationException("Native summon inheritance dictionary allocation failed.");
            var addMethod = dictionaryType.GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(method => method.Name == "Add" && method.GetParameters().Length == 2
                                          && method.GetParameters()[1].ParameterType == typeof(float))
                            ?? throw new MissingMethodException(dictionaryType.FullName, "Add");
            foreach (var entry in rates.OrderBy(entry => entry.Key))
            {
                var attrType = CreateEnum("EAttrType", entry.Key)
                               ?? throw new InvalidOperationException($"Unknown inherited attribute {entry.Key}.");
                addMethod.Invoke(nativeRates, new object[] { attrType, entry.Value });
            }

            var summonAttrRows = Read(summonRow, "attrArr")
                                 ?? throw new InvalidOperationException("TSummon.attrArr is unavailable.");
            var ownerType = CreateEnum("EAttrOwnType", 1)
                            ?? throw new InvalidOperationException("Summon body owner type is unavailable.");
            try
            {
                return createPercent.Invoke(null, new[] { ownerType, produceAttr, nativeRates, summonAttrRows })
                       ?? throw new InvalidOperationException("AttrData.CreatePercent returned no summon attributes.");
            }
            catch (TargetInvocationException error) when (error.InnerException is not null)
            {
                throw new InvalidOperationException($"AttrData.CreatePercent failed: {error.InnerException.Message}", error.InnerException);
            }
        });

        foreach (var row in ReadFloatMatrixRows(Read(summonRow, "levelAttrArr"), 2))
        {
            if (row.Length < 2 || !double.IsFinite(row[0]) || !double.IsFinite(row[1]))
                throw new InvalidOperationException("TSummon.levelAttrArr contains an invalid row.");
            var attrId = Convert.ToInt32(row[0], CultureInfo.InvariantCulture);
            if (attrId <= 0) throw new InvalidOperationException($"TSummon.levelAttrArr contains attribute {attrId}.");
            var attrType = CreateEnum("EAttrType", attrId)
                           ?? throw new InvalidOperationException($"Unknown summon level attribute {attrId}.");
            var delta = summonLevel * row[1];
            if (!double.IsFinite(delta) || delta < float.MinValue || delta > float.MaxValue)
                throw new InvalidOperationException($"Summon level attribute {attrId} is invalid.");
            InvokeRequiredInstance(summonAttr, "ChangeAttr", attrType, (float)delta);
        }
        return summonAttr;
    }

    private static (List<List<int>> Conditions, bool IsComplete, string Failure) ReadNativeSkillCastConditions(
        object skillPreview,
        string rawCastCondition)
    {
        var conditions = new List<List<int>>();
        try
        {
            foreach (var rawCondition in ReadList(Read(skillPreview, "conditionList")))
            {
                var parsed = ReadSequence(rawCondition).Select(ToInt).ToList();
                if (parsed.Count > 0) conditions.Add(parsed);
            }
        }
        catch (Exception error)
        {
            return (conditions, false,
                $"the native condition list could not be parsed ({error.GetBaseException().Message})");
        }
        if (conditions.Count > 0 || string.IsNullOrWhiteSpace(rawCastCondition))
            return (conditions, true, string.Empty);

        // Current IL2CPP previews leave conditionList empty even though the
        // authoritative TSkillInfo row retains a simple summon-count gate such
        // as "2,12004". Accept only that exact two-integer encoding. More
        // complicated condition strings remain unknown instead of being guessed.
        var parts = rawCastCondition.Split(',');
        if (parts.Length == 2
            && int.TryParse(parts[0].Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out var type)
            && int.TryParse(parts[1].Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out var target))
        {
            conditions.Add(new List<int> { type, target });
            return (conditions, true, string.Empty);
        }
        return (conditions, false,
            $"raw cast condition '{rawCastCondition}' is not an exact two-integer gate");
    }

    private static (List<double> Durations, bool IsComplete, string Failure) BuildSummonActiveDurations(
        object parentSkillPreview,
        string parentCastCondition,
        NativeSummonInvocation invocation,
        object summonRow,
        double castOpportunities,
        double cycleSeconds,
        double spawnOffsetSeconds)
    {
        var failures = new HashSet<string>(StringComparer.Ordinal);
        var hasCountGate = false;
        var parsedConditions = ReadNativeSkillCastConditions(parentSkillPreview, parentCastCondition);
        if (!parsedConditions.IsComplete && !string.IsNullOrWhiteSpace(parsedConditions.Failure))
            failures.Add(parsedConditions.Failure);
        foreach (var condition in parsedConditions.Conditions)
        {
            if (condition.Count == 0) continue;
            if (condition.Count >= 2 && condition[0] == 2 && condition[1] == invocation.SummonId)
            {
                hasCountGate = true;
                continue;
            }
            failures.Add($"summon {invocation.SummonId} has an unsupported cast condition");
        }
        if (castOpportunities <= 0d)
            failures.Add($"summon {invocation.SummonId} has no proven parent cast opportunity");
        if (!double.IsFinite(cycleSeconds) || cycleSeconds <= 0d)
            failures.Add($"summon {invocation.SummonId} has no proven parent cast cycle");
        if (!double.IsFinite(spawnOffsetSeconds) || spawnOffsetSeconds < 0d)
            failures.Add($"summon {invocation.SummonId} has no proven spawn offset");
        if (failures.Count > 0)
            return (new List<double>(), false,
                string.Join("; ", failures.OrderBy(value => value)));

        var rawLifeTime = Convert.ToDouble(Read(summonRow, "lifeTime") ?? 0d, CultureInfo.InvariantCulture);
        if (!double.IsFinite(rawLifeTime))
            return (new List<double>(), false, $"summon {invocation.SummonId} lifetime is invalid");
        var lifeTime = double.PositiveInfinity;
        if (rawLifeTime > 0d)
        {
            var lifeAttr = CreateEnum("EAttrType", 190)
                           ?? throw new InvalidOperationException("minionTimeUp attribute is unavailable.");
            var lifeRate = Convert.ToDouble(
                InvokeRequiredInstance(invocation.ProduceAttr, "GetAttrUpRate", lifeAttr) ?? 0d,
                CultureInfo.InvariantCulture);
            if (!double.IsFinite(lifeRate) || lifeRate < 0d)
                return (new List<double>(), false, $"summon {invocation.SummonId} lifetime rate is invalid");
            lifeTime = rawLifeTime * lifeRate;
        }

        var castCount = Math.Min(MaximumPerformancePreviewEvents, Math.Max(0,
            Convert.ToInt32(Math.Floor(castOpportunities + 0.0000001d), CultureInfo.InvariantCulture)));
        var maxCount = ReadNullableInt(summonRow, "maxCount") ?? 0;
        if (hasCountGate && maxCount <= 0)
            return (new List<double>(), false,
                $"summon {invocation.SummonId} has a count gate without a positive native maxCount");
        var expiries = new List<double>();
        var durations = new List<double>();
        for (var castIndex = 0; castIndex < castCount; castIndex++)
        {
            var spawnTime = castIndex * cycleSeconds + Math.Max(0d, spawnOffsetSeconds);
            if (spawnTime >= PerformancePreviewWindowSeconds) break;
            expiries.RemoveAll(expiry => expiry <= spawnTime + 0.0000001d);
            if (hasCountGate && expiries.Count >= maxCount) continue;
            for (var index = 0; index < invocation.CountPerCast; index++)
            {
                if (durations.Count >= MaximumPerformancePreviewEvents)
                {
                    failures.Add($"summon {invocation.SummonId} preview exceeded the instance bound");
                    break;
                }
                var expiry = double.IsPositiveInfinity(lifeTime) ? double.PositiveInfinity : spawnTime + lifeTime;
                expiries.Add(expiry);
                durations.Add(Math.Max(0d, Math.Min(PerformancePreviewWindowSeconds, expiry) - spawnTime));
            }
            if (durations.Count >= MaximumPerformancePreviewEvents) break;
        }
        return (durations, failures.Count == 0,
            string.Join("; ", failures.OrderBy(value => value)));
    }

    private static bool IsSupportedSummonCountCastCondition(
        object skillPreview,
        string rawCastCondition,
        NativeSkillExecutionGraph executionGraph,
        out string failure)
    {
        var summonIds = executionGraph.SummonInvocations
            .Select(invocation => invocation.SummonId)
            .Where(id => id > 0)
            .Distinct()
            .ToHashSet();
        if (summonIds.Count == 0)
        {
            failure = "no native summon invocation matches the cast condition";
            return false;
        }

        var parsedConditions = ReadNativeSkillCastConditions(skillPreview, rawCastCondition);
        if (!parsedConditions.IsComplete)
        {
            failure = parsedConditions.Failure;
            return false;
        }
        if (parsedConditions.Conditions.Count == 0)
        {
            failure = "the native and raw condition lists are empty";
            return false;
        }

        foreach (var condition in parsedConditions.Conditions)
        {
            // Condition type 2 is the game's summon-count gate. Nothing else is
            // safe to treat as an automatic preview-window cast opportunity because it
            // may depend on a target, battle phase, resource, or transient state.
            if (condition.Count != 2 || condition[0] != 2 || !summonIds.Contains(condition[1]))
            {
                failure = $"condition [{string.Join(',', condition)}] is not a matching summon-count gate";
                return false;
            }

            var summonRow = InvokeStatic("TableData", "getTSummonData", condition[1]);
            var maxCount = ReadNullableInt(summonRow, "maxCount") ?? 0;
            if (summonRow is null || maxCount <= 0)
            {
                failure = $"summon {condition[1]} has no positive native maxCount";
                return false;
            }
        }

        failure = string.Empty;
        return true;
    }

    private static NativeSummonEvaluation EvaluateNativeSummonInvocation(
        object hero,
        object parentSkillPreview,
        string parentCastCondition,
        NativeSummonInvocation invocation,
        double parentCastOpportunities,
        double parentCycleSeconds,
        double spawnOffsetSeconds)
    {
        var failures = new HashSet<string>(StringComparer.Ordinal);
        try
        {
            var summonRow = InvokeStatic("TableData", "getTSummonData", invocation.SummonId)
                            ?? throw new InvalidOperationException($"TSummon {invocation.SummonId} is unavailable.");
            var summonAttr = CreateNativeSummonAttr(summonRow, invocation.Level, invocation.ProduceAttr);
            var active = BuildSummonActiveDurations(
                parentSkillPreview, parentCastCondition, invocation, summonRow,
                parentCastOpportunities, parentCycleSeconds, spawnOffsetSeconds);
            if (!active.IsComplete && !string.IsNullOrWhiteSpace(active.Failure)) failures.Add(active.Failure);
            var averageActiveCount = active.Durations
                .Where(value => double.IsFinite(value) && value > 0d)
                .Sum() / PerformancePreviewWindowSeconds;

            var directActions = ReadSequence(Read(summonRow, "actionArr")).Select(ToInt).Where(id => id > 0).ToList();
            foreach (var actionId in directActions)
            {
                var action = InvokeStatic("TableData", "getTActionData", actionId);
                var hasCombatEffect = (ReadNullableInt(action, "emitterId") ?? 0) > 0
                                      || (ReadNullableInt(action, "produceId") ?? 0) > 0
                                      || ReadSequence(Read(action, "triggerArr")).Select(ToInt).Any(id => id > 0);
                if (hasCombatEffect)
                    failures.Add($"summon {invocation.SummonId} direct action {actionId} requires combat AI");
            }
            if (ReadSequence(Read(summonRow, "abilityArr")).Select(ToInt).Any(id => id > 0))
                failures.Add($"summon {invocation.SummonId} native abilities require activation state");

            var skillEntries = new List<(int Index, object Preview, NativeSkillRoleProfile Role)>();
            var skillIndex = 0;
            foreach (var summonSkillId in ReadSequence(Read(summonRow, "skillArr")).Select(ToInt).Where(id => id > 0))
            {
                var summonSkillPreview = InvokeRequiredStaticMany(
                    "SkillData", "CreatePreview", summonSkillId, invocation.Level, summonAttr)
                    ?? throw new InvalidOperationException($"Summon skill {summonSkillId} preview failed.");
                var role = ReadNativeSkillRoleProfile(
                    hero, summonSkillId, invocation.Level, summonAttr, false, null, false);
                if (!role.IsComplete && !string.IsNullOrWhiteSpace(role.Failure)) failures.Add(role.Failure);
                skillEntries.Add((skillIndex++, summonSkillPreview, role));
            }
            // Even when the parent spawn cadence or the summon AI cannot be
            // reconstructed, every nested SkillData preview still exposes its
            // native damage type and inherited AttrData scaling. Preserve that
            // one-action value as a structural ranking proxy; it is never labeled
            // or added as 30-second DPS.
            var attackByType = new Dictionary<int, double>();
            foreach (var entry in skillEntries)
            {
                var divisor = entry.Role.CastOpportunities > 0d
                    ? entry.Role.CastOpportunities
                    : 1d;
                foreach (var damageEntry in entry.Role.DamageByType.Where(pair =>
                             pair.Key > 0 && double.IsFinite(pair.Value) && pair.Value > 0d))
                    attackByType[damageEntry.Key] = attackByType.GetValueOrDefault(damageEntry.Key)
                                                        + damageEntry.Value / divisor;
            }
            if (active.Durations.Count == 0)
                return new NativeSummonEvaluation(0d, 0d, 0d, 0d, 0d,
                    failures.Count == 0, string.Join("; ", failures), attackByType,
                    averageActiveCount);
            skillEntries.Sort((left, right) =>
            {
                var main = (ReadNullableInt(left.Preview, "skillMainType") ?? 0)
                           .CompareTo(ReadNullableInt(right.Preview, "skillMainType") ?? 0);
                if (main != 0) return main;
                var leftAttr = Read(left.Preview, "attrData");
                var rightAttr = Read(right.Preview, "attrData");
                if (leftAttr is null || rightAttr is null) return left.Index.CompareTo(right.Index);
                var cooldownOrder = Convert.ToInt32(Math.Round(
                    (ReadAttrRequired(leftAttr, 2001) - ReadAttrRequired(rightAttr, 2001)) * 100d,
                    MidpointRounding.ToEven), CultureInfo.InvariantCulture);
                return cooldownOrder != 0 ? cooldownOrder : left.Index.CompareTo(right.Index);
            });

            double SkillDamagePerCast(NativeSkillRoleProfile role)
                => role.CastOpportunities > 0d
                    ? role.DamageByType.Values.Where(value => value > 0d).Sum() / role.CastOpportunities
                    : 0d;
            var survivalCapacity = Math.Max(0d,
                ReadAttrRequired(summonAttr, 5)
                + (ReadAttrRequired(summonAttr, 3) + ReadAttrRequired(summonAttr, 4)) * 2d
                + ReadAttrRequired(summonAttr, 7) * 4d
                + (ReadAttrRequired(summonAttr, 32) + ReadAttrRequired(summonAttr, 85)
                   + ReadAttrRequired(summonAttr, 86)) * 2d
                + Enumerable.Range(61, 6).Sum(id => Math.Max(0d, ReadAttrRequired(summonAttr, id))) * 1.5d);
            var passiveSupport = skillEntries.Select(entry => entry.Role.AbilitySupport).DefaultIfEmpty(0d).Max();
            var passiveDefense = skillEntries.Select(entry => entry.Role.AbilityDefense).DefaultIfEmpty(0d).Max();
            var passiveMinion = skillEntries.Select(entry => entry.Role.AbilityMinion).DefaultIfEmpty(0d).Max();
            var totalDamage = 0d;
            var totalSurvival = 0d;
            var totalSupport = 0d;
            var totalDefense = 0d;
            var totalMinion = 0d;
            var schedulerEvents = 0;
            var schedulerExhausted = false;
            foreach (var duration in active.Durations.Where(value => value > 0d))
            {
                totalSurvival += survivalCapacity * Math.Min(1d, duration / PerformancePreviewWindowSeconds);
                totalSupport += passiveSupport * Math.Min(1d, duration / PerformancePreviewWindowSeconds);
                totalDefense += passiveDefense * Math.Min(1d, duration / PerformancePreviewWindowSeconds);
                totalMinion += passiveMinion * Math.Min(1d, duration / PerformancePreviewWindowSeconds);
                if (skillEntries.Count == 0 || schedulerExhausted) continue;

                var nextReady = new double[skillEntries.Count];
                var disabled = new bool[skillEntries.Count];
                var time = 0d;
                for (var guard = 0; guard < MaximumPerformancePreviewEvents && time < duration; guard++)
                {
                    if (++schedulerEvents > MaximumPerformancePackageEvents)
                    {
                        schedulerExhausted = true;
                        failures.Add($"summon {invocation.SummonId} shared scheduler exceeded its package event bound");
                        break;
                    }
                    var selected = -1;
                    for (var index = 0; index < skillEntries.Count; index++)
                    {
                        if (!disabled[index] && nextReady[index] <= time + 0.0000001d)
                        {
                            selected = index;
                            break;
                        }
                    }
                    if (selected < 0)
                    {
                        var next = Enumerable.Range(0, skillEntries.Count)
                            .Where(index => !disabled[index])
                            .Select(index => nextReady[index]).DefaultIfEmpty(double.PositiveInfinity).Min();
                        if (!double.IsFinite(next) || next >= duration) break;
                        time = Math.Max(time, next);
                        continue;
                    }

                    var role = skillEntries[selected].Role;
                    if (role.CastOpportunities <= 0d || role.ActionSecondsPerCast <= 0d
                        || !double.IsFinite(role.ActionSecondsPerCast)
                        || role.HpCostPerCast > 0d || role.MpCostPerCast > 0d)
                    {
                        disabled[selected] = true;
                        failures.Add($"summon {invocation.SummonId} skill action requires an unmodeled cast resource or timing");
                        continue;
                    }
                    if (time + role.ActionSecondsPerCast > duration) break;
                    var cycle = PerformancePreviewWindowSeconds / role.CastOpportunities;
                    if (!double.IsFinite(cycle) || cycle <= 0d)
                    {
                        disabled[selected] = true;
                        failures.Add($"summon {invocation.SummonId} skill cycle is invalid");
                        continue;
                    }
                    totalDamage += SkillDamagePerCast(role);
                    nextReady[selected] = time + cycle;
                    time += role.ActionSecondsPerCast;
                    if (guard == MaximumPerformancePreviewEvents - 1)
                        failures.Add($"summon {invocation.SummonId} shared scheduler exceeded its event bound");
                }
            }
            return new NativeSummonEvaluation(
                totalDamage, totalSurvival, totalSupport, totalDefense, totalMinion,
                failures.Count == 0, string.Join("; ", failures.OrderBy(value => value)),
                attackByType, averageActiveCount);
        }
        catch (Exception error)
        {
            failures.Add($"summon {invocation.SummonId} preview failed: {error.GetBaseException().Message}");
            return new NativeSummonEvaluation(0d, 0d, 0d, 0d, 0d, false,
                string.Join("; ", failures.OrderBy(value => value)));
        }
    }

    private static NativeSkillRoleProfile ReadNativeSkillRoleProfile(object hero, int skillId, int level,
        object? attrOverride = null, bool applyCurrentEquipmentVariant = true,
        IEnumerable<GearCandidate>? candidateItems = null, bool includeSummonDetails = true,
        bool applyOwnAlwaysOnAbilityAttrs = true)
    {
        var items = candidateItems?.ToList();
        return MainThreadNativeGateway.Invoke(() =>
        {
            try
            {
                return ReadNativeSkillRoleProfileCore(
                    hero, skillId, level, attrOverride, applyCurrentEquipmentVariant,
                    items, includeSummonDetails, applyOwnAlwaysOnAbilityAttrs);
            }
            catch (Exception error)
            {
                // A downstream combat-AI preview failure does not change the
                // action graph's structural fact that this skill creates a summon.
                if (!HasNativeSummonDefinitionCore(
                        hero, skillId, level, attrOverride,
                        applyCurrentEquipmentVariant, items)) throw;
                return new NativeSkillRoleProfile(
                    new Dictionary<int, double>(), 0d, 0d, true,
                    0d, 0d, 0d, 0d, 0d, 0d, 1d,
                    IsComplete: false,
                    Failure: error.GetBaseException().Message,
                    Confidence: 0d,
                    SkillId: skillId,
                    ControlledEntityKinds: GetNativeControlledEntityKindsForSkillCore(skillId));
            }
        });
    }

    private static NativeSkillRoleProfile ReadNativeSkillRoleProfileCore(object hero, int skillId, int level,
        object? attrOverride = null, bool applyCurrentEquipmentVariant = true,
        IEnumerable<GearCandidate>? candidateItems = null, bool includeSummonDetails = true,
        bool applyOwnAlwaysOnAbilityAttrs = true)
    {
        var damage = new Dictionary<int, double>();
        if (skillId <= 0) return new NativeSkillRoleProfile(damage, 0d, 0d, false, 0d, 0d, 0d, 0d, 0d, 0d, 1d);
        var attr = attrOverride ?? Read(hero, "attrData") ?? throw new InvalidOperationException("Hero AttrData is unavailable.");
        var preview = InvokeRequiredStaticMany("SkillData", "CreatePreview", skillId, Math.Max(1, level), attr)
                      ?? throw new InvalidOperationException($"SkillData.CreatePreview({skillId}) returned no skill.");
        var variantEnabled = (candidateItems is not null && CandidateEnablesSkillVariant(candidateItems, skillId))
                             || (applyCurrentEquipmentVariant && CurrentEquipmentEnablesSkillVariant(hero, skillId));
        if (variantEnabled)
            InvokeRequiredInstance(preview, "SetVariant", true);
        var info = Read(preview, "tSkillInfoData") ?? throw new InvalidOperationException($"Skill {skillId} info is unavailable.");
        var explainRows = ReadSequence(Read(info, "infoArr")).Select(ToInt).Where(id => id > 0)
            .Select(id => InvokeStatic("TableData", "getTSkillExplainData", id))
            .Where(row => row is not null).Cast<object>().ToList();
        var powerIds = explainRows
            .Where(explain => (ReadNullableInt(explain, "type") ?? -1) == 2)
            .Select(explain => ReadSequence(Read(explain, "typeParam")).Select(ToInt).FirstOrDefault())
            .Where(id => id > 0).Distinct().ToList();
        var executionGraph = ResolveNativeSkillExecutionGraph(preview, info, Math.Max(1, level), powerIds);
        if (applyOwnAlwaysOnAbilityAttrs)
        {
            var alwaysOn = ReadNativeSkillAlwaysOnPreview(
                preview, info, Math.Max(1, level), executionGraph);
            if (!alwaysOn.IsComplete)
                throw new InvalidOperationException(
                    $"Skill {skillId} strict ability preview is incomplete: {alwaysOn.Failure}");
            var adjusted = ApplyStrictAbilityContributions(attr, alwaysOn.Contributions, out var applied);
            if (applied)
            {
                // Exactly one recursion is permitted: the first pass extracts
                // native signed result301 deltas; the guarded second pass
                // recomputes PowerData/cooldown/summons against that AttrData.
                return ReadNativeSkillRoleProfileCore(
                    hero, skillId, level, adjusted, applyCurrentEquipmentVariant,
                    candidateItems, includeSummonDetails, false);
            }
        }
        var roleFailures = new HashSet<string>(StringComparer.Ordinal);
        if (!executionGraph.IsComplete && !string.IsNullOrWhiteSpace(executionGraph.Failure))
            roleFailures.Add(executionGraph.Failure);
        var heal = 0d;
        var shield = 0d;
        var selfHeal = 0d;
        var selfShield = 0d;
        var abilitySupport = 0d;
        var abilityDefense = 0d;
        var abilityMinion = 0d;
        var untimedHitEventsPerCast = 0d;
        var timedPowerInvocations = new List<NativePowerInvocation>();
        foreach (var invocation in executionGraph.PowerInvocations
                     .OrderBy(entry => entry.PowerId).ThenBy(entry => entry.EventsPerCast))
        {
            if (invocation.EventTimeline is not null)
            {
                // Emitter-origin power events retain their per-cast offsets until
                // the native cast cycle below is known. Multiplying a full emitter
                // lifetime by every cast would overcount the tail of the preview window.
                timedPowerInvocations.Add(invocation);
                continue;
            }
            var powerId = invocation.PowerId;
            var eventsPerCast = invocation.EventsPerCast;
            var power = invocation.PowerPreview;
            var powerType = ReadNullableInt(Read(power, "tPowerData"), "type") ?? 0;
#if PATHOFIDLE_DIAGNOSTICS
            if (powerType is 2 or 3)
                Plugin.DiagInfo(
                    $"AUTO-SKILL POWER TARGET|skill={skillId}|power={powerId}|type={powerType}|timed=False|targetType={invocation.TargetType}|self={IsSelfRecoveryPowerTargetUnderPressure(invocation.TargetType, invocation.TargetParam)}|scope={ReadNullableInt(preview, "skillScopeType") ?? 0}|triggerTarget={invocation.TargetParam}|description={Clean(EnglishText(info, "_des", string.Empty) ?? string.Empty).Replace('|', '/')}");
#endif
            if (powerType == 1)
            {
                var hasPositiveDamage = false;
                foreach (var entry in ReadEntries(Read(power, "dmgPowerDic")))
                {
                    var nativeDamageType = Read(entry, "Key");
                    var type = ToInt(nativeDamageType ?? 0);
                    var value = Convert.ToDouble(Read(entry, "Value") ?? 0d, CultureInfo.InvariantCulture);
                    if (type <= 0 || !double.IsFinite(value) || value <= 0d) continue;
                    RememberNativeDamageTypeName(type, nativeDamageType);
                    hasPositiveDamage = true;
                    damage[type] = damage.GetValueOrDefault(type) + value * eventsPerCast;
                }
                if (hasPositiveDamage) untimedHitEventsPerCast += eventsPerCast;
            }
            else if (powerType == 2)
            {
                var value = Convert.ToDouble(Read(power, "power") ?? 0d, CultureInfo.InvariantCulture);
                if (double.IsFinite(value) && value > 0d)
                {
                    var amount = value * eventsPerCast;
                    heal += amount;
                    if (IsSelfRecoveryPowerTargetUnderPressure(
                            invocation.TargetType, invocation.TargetParam))
                        selfHeal += amount;
                }
            }
            else if (powerType == 3)
            {
                var value = Convert.ToDouble(Read(power, "power") ?? 0d, CultureInfo.InvariantCulture);
                if (double.IsFinite(value) && value > 0d)
                {
                    var amount = value * eventsPerCast;
                    shield += amount;
                    if (IsSelfRecoveryPowerTargetUnderPressure(
                            invocation.TargetType, invocation.TargetParam))
                        selfShield += amount;
                }
            }
            else roleFailures.Add($"power {powerId} uses unsupported type {powerType}");
        }
        var previewAttr = Read(preview, "attrData") ?? attr;
        var displayedAbilityLevels = new Dictionary<int, int>();
        var graphTriggeredRoleAbilities = new List<(object Ability, NativeAbilityInvocation Invocation)>();
        foreach (var explain in explainRows.Where(row => (ReadNullableInt(row, "type") ?? -1) is 3 or 4 or 103))
        {
            var parameters = ReadSequence(Read(explain, "typeParam")).Select(ToInt).Where(value => value > 0).ToList();
            if (parameters.Count == 0) continue;
            var abilityId = parameters[0];
            var abilityLevel = parameters.Count > 1 ? Math.Max(1, parameters[1]) : Math.Max(1, level);
            displayedAbilityLevels[abilityId] = Math.Max(displayedAbilityLevels.GetValueOrDefault(abilityId), abilityLevel);
        }
        foreach (var entry in displayedAbilityLevels.OrderBy(entry => entry.Key))
        {
            var abilityId = entry.Key;
            var abilityLevel = entry.Value;
            var abilityPreview = InvokeStaticMany("AbilityData", "CreateByShow", abilityId, abilityLevel, previewAttr);
            var abilityRow = Read(abilityPreview, "tAbilityData") ?? ResolveAbilityTableRow(abilityId, abilityLevel);
            if (abilityRow is null)
                throw new InvalidOperationException($"AbilityData.CreateByShow({abilityId}) returned no ability.");
            var graphInvocations = executionGraph.AbilityInvocations
                .Where(invocation => invocation.AbilityId == abilityId).ToList();
            var provenInvocations = graphInvocations
                .Where(invocation => invocation.DirectUnconditionalActionTrigger
                                     || invocation.EventTimeline is { Count: > 0 })
                .ToList();
            if (provenInvocations.Count > 0)
            {
                // The execution graph proved either an unconditional root-action
                // edge or a deterministic timed emitter/bullet edge. Defer its
                // finite-duration result301 value until the native cast cycle is
                // known below; unresolved battle-state triggers remain zero.
                var merged = provenInvocations[0] with
                {
                    EventsPerCast = provenInvocations.Sum(invocation => invocation.EventsPerCast)
                };
                var directPreview = InvokeStaticMany(
                    "AbilityData", "CreateByShow", abilityId, abilityLevel, merged.SourceAttr);
                graphTriggeredRoleAbilities.Add((directPreview ?? abilityPreview ?? abilityRow, merged));
                if (provenInvocations.Count != graphInvocations.Count)
                    roleFailures.Add($"ability {abilityId} also has a battle-state trigger");
            }
            else if (graphInvocations.Count == 0
                     && IsUnconditionalAcquireAbility(abilityPreview ?? abilityRow))
            {
                var utility = GetNativeAbilityRoleUtility(abilityPreview ?? abilityRow);
                abilitySupport += utility.Support;
                abilityDefense += utility.Defense;
                abilityMinion += utility.Minion;
            }
            else if (graphInvocations.Count == 0
                     && IsContinuousNativeAuraRoleAbility(abilityPreview ?? abilityRow))
            {
                // Aura filters identify recipients; they are not an activation
                // condition. Count only the native result301 role value and never
                // apply the filtered attributes to the previewing hero itself.
                var utility = GetNativeAbilityRoleUtilityCore(abilityPreview ?? abilityRow);
                abilitySupport += utility.Support;
                abilityDefense += utility.Defense;
                abilityMinion += utility.Minion;
            }
            else
            {
                roleFailures.Add($"display ability {abilityId} is conditional or dynamic");
            }
        }
        foreach (var group in executionGraph.AbilityInvocations
                     .Where(invocation => !displayedAbilityLevels.ContainsKey(invocation.AbilityId))
                     .GroupBy(invocation => invocation.AbilityId))
        {
            var provenInvocations = group
                .Where(invocation => invocation.DirectUnconditionalActionTrigger
                                     || invocation.EventTimeline is { Count: > 0 })
                .ToList();
            if (provenInvocations.Count == 0)
            {
                roleFailures.Add($"triggered ability {group.Key} has no exact display preview");
                continue;
            }
            var merged = provenInvocations[0] with
            {
                EventsPerCast = provenInvocations.Sum(invocation => invocation.EventsPerCast)
            };
            var abilityPreview = InvokeStaticMany(
                "AbilityData", "CreateByShow", group.Key, Math.Max(1, level), merged.SourceAttr);
            var abilityRow = Read(abilityPreview, "tAbilityData")
                             ?? ResolveAbilityTableRow(group.Key, Math.Max(1, level));
            if (abilityRow is null)
            {
                roleFailures.Add($"graph-triggered ability {group.Key} has no exact preview");
                continue;
            }
            graphTriggeredRoleAbilities.Add((abilityPreview ?? abilityRow, merged));
            if (provenInvocations.Count != group.Count())
                roleFailures.Add($"ability {group.Key} also has a battle-state trigger");
        }
        var nativeSpeed = Convert.ToDouble(
            InvokeRequiredInstance(previewAttr, "GetSkillSpeedRate", (object)null!)
            ?? throw new InvalidOperationException($"Skill {skillId} returned no native speed."),
            CultureInfo.InvariantCulture);
        if (!double.IsFinite(nativeSpeed) || nativeSpeed <= 0d)
            throw new InvalidOperationException($"Skill {skillId} returned an invalid native speed ({nativeSpeed}).");
        nativeSpeed = Math.Clamp(nativeSpeed, 0.05d, 20d);
        var actionId = ReadNullableInt(info, "actionId") ?? 0;
        var actionRow = actionId > 0 ? InvokeStatic("TableData", "getTActionData", actionId) : null;
        var actionTimingValues = ReadSequence(Read(actionRow, "typeInfo"))
            .Take(2)
            .Select(value =>
            {
                try { return Convert.ToDouble(value, CultureInfo.InvariantCulture); }
                catch { return 0d; }
            })
            .ToList();
        var validAction = actionRow is not null && (ReadNullableInt(actionRow, "type") ?? 0) == 3
                                             && actionTimingValues.Count == 2
                                             && actionTimingValues.All(value => double.IsFinite(value) && value >= 0d)
                                             && actionTimingValues.Sum() > 0d;
        var passiveCompanionSpawn = executionGraph.SummonInvocations.Count > 0
                                    && executionGraph.SummonInvocations.All(invocation => invocation.PassiveSpawn);
        if (!validAction && !passiveCompanionSpawn)
            roleFailures.Add($"skill action {actionId} has no proven cast timing");
        var nativeActionSeconds = validAction ? actionTimingValues.Sum() : 0d;
        var actionSecondsPerCast = passiveCompanionSpawn
            ? 0.01d
            : validAction
            ? Math.Clamp(nativeActionSeconds / nativeSpeed, 0.01d, PerformancePreviewWindowSeconds)
            : PerformancePreviewWindowSeconds;
        var cooldown = Math.Max(0d, ReadAttrRequired(previewAttr, 2001));
        if (ReadAttrRequired(previewAttr, 3001) > 0d) cooldown = 0d;
        var cooldownSeconds = cooldown > 0.01d ? cooldown / nativeSpeed : 0d;
        var cycleSeconds = passiveCompanionSpawn
            ? PerformancePreviewWindowSeconds
            : Math.Max(actionSecondsPerCast, cooldownSeconds);
        var spawnOffsetSeconds = passiveCompanionSpawn
            ? 0d
            : validAction
            ? Math.Clamp(actionTimingValues[0] / nativeSpeed, 0d, PerformancePreviewWindowSeconds)
            : PerformancePreviewWindowSeconds;
        var castOpportunities = passiveCompanionSpawn
            ? 1d
            : validAction && spawnOffsetSeconds < PerformancePreviewWindowSeconds
            ? Math.Clamp(1d + Math.Floor(
                Math.Max(0d, PerformancePreviewWindowSeconds - spawnOffsetSeconds - 0.0000001d)
                / Math.Max(0.01d, cycleSeconds)), 0d, MaximumPerformancePreviewEvents)
            : 0d;
        var castCondition = Clean(ReadString(info, "castCondition") ?? string.Empty);
        if (castCondition.Length > 0
            && !IsSupportedSummonCountCastCondition(
                preview, castCondition, executionGraph, out var castConditionFailure))
        {
            roleFailures.Add($"skill cast condition '{castCondition}' is unsupported: {castConditionFailure}");
            castOpportunities = 0d;
        }
        foreach (var entry in graphTriggeredRoleAbilities)
        {
            if (!TryGetGraphTriggeredAbilityRoleUtility(
                    entry.Ability,
                    entry.Invocation,
                    castOpportunities,
                    cycleSeconds,
                    out var utility))
            {
                roleFailures.Add(
                    $"graph-triggered ability {entry.Invocation.AbilityId} has no proven result301 role value");
                continue;
            }
            abilitySupport += utility.Support;
            abilityDefense += utility.Defense;
            abilityMinion += utility.Minion;
        }

        // Preserve the identity and expected stack count of graph-proven hostile
        // status applications. Wound, poison, paralysis, and future ailments are
        // native TAttr relations, not necessarily EDamageType lanes. Pure chance
        // clauses have already scaled the invocation timeline in VisitTriggers.
        var hostileStatusApplications = new Dictionary<int, double>();
        foreach (var invocation in executionGraph.AbilityInvocations)
        {
            var proven = invocation.DirectUnconditionalActionTrigger
                         || invocation.EventTimeline is { Count: > 0 };
            if (!proven) continue;
            var eventCount = invocation.EventTimeline is { Count: > 0 }
                ? CountNativeTimedEventsInPreviewWindow(
                    invocation.EventTimeline, castOpportunities, cycleSeconds, spawnOffsetSeconds)
                : Math.Max(0d, invocation.EventsPerCast * castOpportunities);
            if (!double.IsFinite(eventCount) || eventCount <= 0d) continue;
            var abilityPreview = InvokeStaticMany(
                "AbilityData", "CreateByShow",
                invocation.AbilityId, Math.Max(1, invocation.Level), invocation.SourceAttr);
            var ability = abilityPreview
                          ?? ResolveAbilityTableRow(invocation.AbilityId, Math.Max(1, invocation.Level));
            var row = Read(ability, "tAbilityData") ?? ability;
            if (row is null) continue;
            var abilityType = ReadNullableInt(row, "type") ?? 0;
            var deltas = abilityPreview is null
                ? new Dictionary<int, double>()
                : ReadNativeAbilityResultAttrDeltas(abilityPreview);
            if (deltas.Count == 0)
            {
                var raw = ReadSequence(Read(row, "resultArr")).Select(ToInt).ToList();
                if (raw.Count > 0 && raw[0] == 301)
                    for (var index = 1; index + 1 < raw.Count; index += 2)
                        if (raw[index] > 0 && raw[index + 1] != 0)
                            deltas[raw[index]] = deltas.GetValueOrDefault(raw[index]) + raw[index + 1];
            }
            foreach (var delta in deltas)
            {
                if (!IsNativeHostileStatusResult(
                        abilityType, delta.Key, delta.Value)) continue;
                hostileStatusApplications[delta.Key] =
                    hostileStatusApplications.GetValueOrDefault(delta.Key)
                    + Math.Abs(delta.Value) * eventCount;
            }
        }

        var timedDamage = new Dictionary<int, double>();
        var timedHeal = 0d;
        var timedShield = 0d;
        var timedSelfHeal = 0d;
        var timedSelfShield = 0d;
        var timedHitOpportunities = 0d;
        foreach (var invocation in timedPowerInvocations)
        {
            var eventCount = CountNativeTimedEventsInPreviewWindow(
                invocation.EventTimeline!, castOpportunities, cycleSeconds, spawnOffsetSeconds);
            if (eventCount <= 0d) continue;
            var powerId = invocation.PowerId;
            var power = invocation.PowerPreview;
            var powerType = ReadNullableInt(Read(power, "tPowerData"), "type") ?? 0;
#if PATHOFIDLE_DIAGNOSTICS
            if (powerType is 2 or 3)
                Plugin.DiagInfo(
                    $"AUTO-SKILL POWER TARGET|skill={skillId}|power={powerId}|type={powerType}|timed=True|targetType={invocation.TargetType}|self={IsSelfRecoveryPowerTargetUnderPressure(invocation.TargetType, invocation.TargetParam)}|scope={ReadNullableInt(preview, "skillScopeType") ?? 0}|triggerTarget={invocation.TargetParam}|description={Clean(EnglishText(info, "_des", string.Empty) ?? string.Empty).Replace('|', '/')}");
#endif
            if (powerType == 1)
            {
                var hasPositiveDamage = false;
                foreach (var entry in ReadEntries(Read(power, "dmgPowerDic")))
                {
                    var nativeDamageType = Read(entry, "Key");
                    var type = ToInt(nativeDamageType ?? 0);
                    var value = Convert.ToDouble(Read(entry, "Value") ?? 0d, CultureInfo.InvariantCulture);
                    if (type <= 0 || !double.IsFinite(value) || value <= 0d) continue;
                    RememberNativeDamageTypeName(type, nativeDamageType);
                    hasPositiveDamage = true;
                    // Periodic stacks/ticks are not modeled. Preserve one proven
                    // application per independently reached native power branch.
                    var multiplier = IsPeriodicDamageType(type) ? 1d : eventCount;
                    timedDamage[type] = timedDamage.GetValueOrDefault(type) + value * multiplier;
                }
                if (hasPositiveDamage) timedHitOpportunities += eventCount;
            }
            else if (powerType == 2)
            {
                var value = Convert.ToDouble(Read(power, "power") ?? 0d, CultureInfo.InvariantCulture);
                if (double.IsFinite(value) && value > 0d)
                {
                    var amount = value * eventCount;
                    timedHeal += amount;
                    if (IsSelfRecoveryPowerTargetUnderPressure(
                            invocation.TargetType, invocation.TargetParam))
                        timedSelfHeal += amount;
                }
            }
            else if (powerType == 3)
            {
                var value = Convert.ToDouble(Read(power, "power") ?? 0d, CultureInfo.InvariantCulture);
                if (double.IsFinite(value) && value > 0d)
                {
                    var amount = value * eventCount;
                    timedShield += amount;
                    if (IsSelfRecoveryPowerTargetUnderPressure(
                            invocation.TargetType, invocation.TargetParam))
                        timedSelfShield += amount;
                }
            }
            else roleFailures.Add($"power {powerId} uses unsupported type {powerType}");
        }

        var critChance = Math.Clamp(PercentRate(ReadAttrRequired(attr, 31)), 0d, 1d);
        var critDamage = Math.Max(0.5d, 0.5d + PercentRate(ReadAttrRequired(attr, 37)));
        foreach (var type in damage.Keys.ToList())
        {
            var periodic = IsPeriodicDamageType(type);
            var critFactor = periodic ? 1d : Math.Max(0.1d, 1d + critChance * critDamage);
            if (periodic)
            {
                // Stack/refresh/tick rules require battle state. Preserve only
                // one proven application as a conservative lower bound.
                roleFailures.Add($"periodic damage type {type} requires stack/tick simulation");
                damage[type] *= castOpportunities > 0d ? 1d : 0d;
            }
            else damage[type] *= castOpportunities * critFactor;
        }
        foreach (var entry in timedDamage)
        {
            var type = entry.Key;
            var periodic = IsPeriodicDamageType(type);
            var critFactor = periodic ? 1d : Math.Max(0.1d, 1d + critChance * critDamage);
            if (periodic)
                roleFailures.Add($"periodic damage type {type} requires stack/tick simulation");
            damage[type] = damage.GetValueOrDefault(type) + entry.Value * critFactor;
        }
        // Periodic damage lanes are deliberately one-application lower bounds rather
        // than time-linear totals. Consumers normalize all preview damage to the
        // established 60-second score reference, so pre-scale these invariant
        // bounds to prevent that normalization from doubling them.
        foreach (var periodicType in damage.Keys.Where(IsPeriodicDamageType).ToList())
            damage[periodicType] *= PerformancePreviewWindowSeconds
                                    / PerformanceScoreReferenceSeconds;
        heal = heal * castOpportunities + timedHeal;
        shield = shield * castOpportunities + timedShield;
        selfHeal = selfHeal * castOpportunities + timedSelfHeal;
        selfShield = selfShield * castOpportunities + timedSelfShield;
        var summon = executionGraph.ControlledEntityKinds != NativeControlledEntityKind.None;
        var summonDamage = 0d;
        var summonSurvival = 0d;
        var controlledEntityCount = 0d;
        var summonAttackByType = new Dictionary<int, double>();
        if (summon && !includeSummonDetails)
        {
            roleFailures.Add("nested summon execution is not expanded in a summon-skill preview");
        }
        else if (summon)
        {
            foreach (var invocation in executionGraph.SummonInvocations)
            {
                var evaluation = EvaluateNativeSummonInvocation(
                    hero, preview, castCondition, invocation,
                    castOpportunities, cycleSeconds, spawnOffsetSeconds);
                summonDamage += evaluation.Damage;
                summonSurvival += evaluation.Survival;
                controlledEntityCount += Math.Max(0d, evaluation.AverageActiveCount);
                foreach (var entry in evaluation.AttackByType ?? new Dictionary<int, double>())
                    summonAttackByType[entry.Key] = summonAttackByType.GetValueOrDefault(entry.Key)
                                                        + entry.Value;
                abilitySupport += evaluation.Support;
                abilityDefense += evaluation.Defense;
                abilityMinion += evaluation.Minion;
                if (!evaluation.IsComplete && !string.IsNullOrWhiteSpace(evaluation.Failure))
                    roleFailures.Add(evaluation.Failure);
            }
        }
        var noCostRate = Math.Clamp(PercentRate(ReadAttrRequired(attr, 181)), 0d, 1d);
        var hpCostPerCast = Math.Max(0d, ReadAttrRequired(previewAttr, 2002)) * (1d - noCostRate);
        var mpCostPerCast = Math.Max(0d, ReadAttrRequired(previewAttr, 2003)) * (1d - noCostRate);
        var hpBudgetWindow = Math.Max(0d, ReadAttrRequired(attr, 5) * 0.90d
                                          + ReadAttrRequired(attr, 7) * NativeRateFactor(ReadAttrRequired(attr, 9))
                                          * PerformancePreviewWindowSeconds);
        var mpBudgetWindow = Math.Max(0d, ReadAttrRequired(attr, 6)
                                          + ReadAttrRequired(attr, 8) * NativeRateFactor(ReadAttrRequired(attr, 10))
                                          * PerformancePreviewWindowSeconds);
        var structuralSummonAttack = summonAttackByType.Values
            .Where(value => double.IsFinite(value) && value > 0d).Sum();
        var controlledEntityDamage = Math.Max(Math.Max(0d, summonDamage), structuralSummonAttack);
        var controlledEntityUtility = Math.Max(0d, abilityMinion);
        var controlledEntitySurvival = Math.Max(0d, summonSurvival);
        if (executionGraph.ControlledEntityKinds.HasFlag(NativeControlledEntityKind.Totem))
        {
            // A Totem is the reached root emitter, not a TSummon. Its native
            // emitter powers and abilities are therefore represented in the
            // parent role's direct lanes. Attribute them to the controlled
            // object here while preserving the original lanes for non-theme DPS.
            controlledEntityDamage += damage.Values
                .Where(value => double.IsFinite(value) && value > 0d).Sum();
            controlledEntityUtility += Math.Max(0d, heal) + Math.Max(0d, shield)
                                       + Math.Max(0d, abilitySupport)
                                       + Math.Max(0d, abilityDefense);
            try
            {
                var emitterId = ReadNullableInt(actionRow, "emitterId") ?? 0;
                var emitter = emitterId > 0
                    ? InvokeStaticMany("EmitterData", "CreateByShow", emitterId,
                        Math.Max(1, level), preview)
                    : null;
                var shotAttr = Read(emitter, "shotData");
                var lifeTime = shotAttr is null
                    ? 0d
                    : Math.Max(0d, ReadAttrRequired(shotAttr, 4006));
                if (lifeTime <= 0d)
                {
                    roleFailures.Add($"totem emitter {emitterId} has no proven lifetime");
                }
                else
                {
                    var castCount = Math.Min(
                        MaximumPerformancePreviewEvents,
                        Math.Max(0, Convert.ToInt32(
                            Math.Floor(castOpportunities + 0.0000001d),
                            CultureInfo.InvariantCulture)));
                    var activeSeconds = 0d;
                    for (var castIndex = 0; castIndex < castCount; castIndex++)
                    {
                        var start = castIndex * cycleSeconds + spawnOffsetSeconds;
                        if (!double.IsFinite(start)
                            || start >= PerformancePreviewWindowSeconds) break;
                        activeSeconds += Math.Max(0d,
                            Math.Min(PerformancePreviewWindowSeconds, start + lifeTime)
                            - Math.Max(0d, start));
                    }
                    controlledEntityCount += Math.Max(
                        0d, activeSeconds / PerformancePreviewWindowSeconds);
                }
            }
            catch (Exception error)
            {
                roleFailures.Add(
                    $"totem active-count preview failed: {error.GetBaseException().Message}");
            }
        }
        return new NativeSkillRoleProfile(
            damage, heal, shield, summon, summonDamage, summonSurvival,
            abilitySupport, abilityDefense, abilityMinion, castOpportunities, actionSecondsPerCast,
            hpCostPerCast, mpCostPerCast, hpBudgetWindow, mpBudgetWindow,
            roleFailures.Count == 0,
            string.Join("; ", roleFailures.OrderBy(value => value)),
            roleFailures.Count == 0 ? 1d : 0.70d,
            summonAttackByType,
            SkillId: skillId,
            HitOpportunities: Math.Max(0d,
                untimedHitEventsPerCast * castOpportunities + timedHitOpportunities),
            ControlledEntityKinds: executionGraph.ControlledEntityKinds,
            ControlledEntityDamage: controlledEntityDamage,
            ControlledEntityUtility: controlledEntityUtility,
            ControlledEntitySurvival: controlledEntitySurvival,
            HostileStatusApplications: hostileStatusApplications,
            ControlledEntityCount: controlledEntityCount,
            SelfHeal: selfHeal,
            SelfShield: selfShield);
    }

    private static double ScoreMasteryTalentForObjective(object hero, object talent, HeroFocus focus,
        object objectiveAttr, IReadOnlyCollection<int> objectiveSkillIds,
        IReadOnlyCollection<GearCandidate>? candidateItems = null,
        double? baselinePackageScore = null)
    {
        var definition = Read(talent, "tTalentData") ?? throw new InvalidOperationException("Mastery talent definition is unavailable.");
        var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
        if (masteryId <= 0) return double.NegativeInfinity;
        var cap = Math.Max(1, GetTalentLevelCap(talent));
        var preview = InvokeRequiredStaticMany("MasteryData", "CreateByShow", masteryId, cap, cap)
                      ?? throw new InvalidOperationException($"MasteryData.CreateByShow({masteryId}) returned no mastery.");
        var simulated = InvokeRequiredStaticMany("AttrData", "copyCreate", objectiveAttr)
                        ?? throw new InvalidOperationException("AttrData mastery copy failed.");
        var baseLevel = Math.Min(GetTalentBaseLevelRequired(talent), cap);
        if (baseLevel > 0)
        {
            var basePreview = InvokeRequiredStaticMany(
                                  "MasteryData", "CreateByShow", masteryId, baseLevel, cap)
                              ?? throw new InvalidOperationException(
                                  $"MasteryData.CreateByShow({masteryId}) returned no base mastery.");
            foreach (var affix in ReadList(Read(basePreview, "affixList")))
            {
                var effectType = ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0;
                if (effectType == 1)
                    InvokeRequiredInstance(affix, "SetActiveAttrData", simulated, false);
            }
        }
        foreach (var affix in ReadList(Read(preview, "affixList")))
        {
            var effectType = ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0;
            if (effectType == 1)
                InvokeRequiredInstance(affix, "SetActiveAttrData", simulated, true);
        }
        var numericDelta = ScoreSkillPackageObjective(
                               hero, objectiveSkillIds, simulated, focus, candidateItems)
                           - (baselinePackageScore ?? ScoreSkillPackageObjective(
                               hero, objectiveSkillIds, objectiveAttr, focus, candidateItems));
        return (numericDelta + ScoreMasteryAbilityObjective(preview, focus, simulated)) * 1000d;
    }

    private static double ScoreMasteryTalentCandidateForObjective(
        object hero,
        object talent,
        HeroFocus focus,
        object objectiveAttr,
        IReadOnlyCollection<int> objectiveSkillIds,
        IReadOnlyCollection<GearCandidate>? candidateItems = null,
        double? baselinePackageScore = null)
    {
        try
        {
            var skillIds = objectiveSkillIds.ToList();
            var items = candidateItems?.ToList();
            return MainThreadNativeGateway.Invoke(() =>
                ScoreMasteryTalentForObjective(
                    hero, talent, focus, objectiveAttr, skillIds, items,
                    baselinePackageScore));
        }
        catch (Exception error)
        {
            var definition = Read(talent, "tTalentData");
            var talentId = ReadNullableInt(definition, "id") ?? 0;
            var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
            // Masteries are independent candidates. One unavailable strict
            // preview must not discard the otherwise usable skill pool.
            Plugin.DiagDebug(
                $"AUTO-SKILLS MASTERY CANDIDATE REJECTED|talent={talentId}|mastery={masteryId}|{error.GetBaseException().Message}");
            return double.NegativeInfinity;
        }
    }

    private static List<(int Id, double Score, int Floor)> ScoreMasteryTalentCandidateBatchForObjective(
        object hero,
        IReadOnlyCollection<object> talents,
        HeroFocus focus,
        object objectiveAttr,
        IReadOnlyCollection<int> objectiveSkillIds,
        IReadOnlyCollection<GearCandidate>? candidateItems = null,
        double? baselinePackageScore = null)
    {
        var candidates = talents.ToList();
        var skillIds = objectiveSkillIds.ToList();
        var items = candidateItems?.ToList();
        return MainThreadNativeGateway.Invoke(() =>
        {
            var results = new List<(int Id, double Score, int Floor)>(candidates.Count);
            foreach (var talent in candidates)
            {
                var definition = Read(talent, "tTalentData");
                var talentId = ReadNullableInt(definition, "id") ?? 0;
                var floor = ReadNullableInt(definition, "floor") ?? int.MaxValue;
                try
                {
                    var score = ScoreMasteryTalentForObjective(
                        hero, talent, focus, objectiveAttr, skillIds, items,
                        baselinePackageScore);
                    results.Add((talentId, score, floor));
                }
                catch (Exception error)
                {
                    var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
                    // Preserve independent candidate rejection while amortizing
                    // the worker/main-thread handoff across this small batch.
                    Plugin.DiagDebug(
                        $"AUTO-SKILLS MASTERY CANDIDATE REJECTED|talent={talentId}|mastery={masteryId}|{error.GetBaseException().Message}");
                    results.Add((talentId, double.NegativeInfinity, floor));
                }
            }
            return results;
        });
    }

    private static double ScoreMasteryAbilityObjective(
        object masteryPreview,
        HeroFocus focus,
        object attrData)
        => ScoreMasteryAbilityObjective(new[] { masteryPreview }, focus, attrData);

    private static double ScoreMasteryAbilityObjective(
        IEnumerable<object> masteryPreviews,
        HeroFocus focus,
        object attrData)
    {
        var support = 0d;
        var defense = 0d;
        var minion = 0d;
        var offense = 0d;
        var appliedAbilityCounts = new Dictionary<int, int>();
        foreach (var masteryPreview in masteryPreviews)
        foreach (var rawAffix in ReadList(Read(masteryPreview, "affixList")))
        {
            var affix = ResolveRuntimeAffix(rawAffix);
            var definition = Read(affix, "tAffixData");
            if ((ReadNullableInt(definition, "effectType") ?? 0) != 3) continue;
            var save = Read(affix, "saveData");
            var tableAbility = Read(affix, "tAbilityData");
            var abilityId = ReadNullableInt(save, "abilityId")
                            ?? ReadNullableInt(tableAbility, "id")
                            ?? ReadSequence(Read(definition, "effectParam")).Select(ToInt).FirstOrDefault();
            var abilityLevel = Math.Max(0, ReadNullableInt(save, "level") ?? 0);
            var ability = InvokeStaticMany("AbilityData", "CreateByShow", abilityId, abilityLevel, attrData)
                          ?? tableAbility
                          ?? ResolveAbilityTableRow(abilityId, abilityLevel);
            if (ability is null)
                throw new InvalidOperationException(
                    $"Mastery ability {abilityId} level {abilityLevel} produced no native preview.");
            var row = Read(ability, "tAbilityData") ?? ability;
            var resolvedAbilityId = ReadNullableInt(row, "id")
                                    ?? ReadNullableInt(ability, "id")
                                    ?? abilityId;
            if (resolvedAbilityId <= 0)
                throw new InvalidOperationException("A mastery ability has no valid native id.");
            var stackLimit = Math.Max(1, ReadNullableInt(row, "stack") ?? 1);
            var appliedCount = appliedAbilityCounts.GetValueOrDefault(resolvedAbilityId);
            if (appliedCount >= stackLimit) continue;
            appliedAbilityCounts[resolvedAbilityId] = appliedCount + 1;
            var utility = GetNativeAbilityRoleUtility(ability);
            support += utility.Support;
            defense += utility.Defense;
            minion += utility.Minion;
            if (ability is not null) offense += ScoreNativeAbilityResultOffense(ability, focus);
        }
        return focus.Key switch
        {
            "defense" => Math.Log10(1d + defense) * 4.5d,
            "support" => Math.Log10(1d + support) * 4.5d,
            "minion" => Math.Log10(1d + minion) * 3.2d,
            _ => Math.Log10(1d + offense) * 4d
        };
    }

    private static double ScoreSkillPackageObjective(
        object hero,
        IEnumerable<int> skillIds,
        object attrData,
        HeroFocus focus,
        IReadOnlyCollection<GearCandidate>? candidateItems = null)
    {
        var selected = skillIds.Where(id => id > 0).Distinct().ToList();
        if (selected.Count == 0) return ScoreHeroAttrObjective(attrData, focus);
        var baseSkillIds = ReadValues(ReadStatic("TableData", "TTalentDict"))
            .Where(IsBaseSkillDefinition)
            .Select(row => ReadNullableInt(row, "skillId") ?? 0).Where(id => id > 0).ToHashSet();
        var baseSkillId = selected.FirstOrDefault(baseSkillIds.Contains);
        if (baseSkillId <= 0) baseSkillId = selected[0];
        var packageAttr = CreateStrictSkillPackageAdjustedAttr(
            hero, selected.Select(id => (SkillId: id, Level: 1)), attrData, false,
            candidateItems, out _);
        var baseRole = ReadNativeSkillRoleProfile(hero, baseSkillId, 1, packageAttr, false,
            candidateItems, true, false);
        var activeRoles = selected.Where(id => id != baseSkillId)
            .Select(id => ReadNativeSkillRoleProfile(hero, id, 1, packageAttr, false,
                candidateItems, true, false));
        return ScoreHeroAttrObjective(
                   packageAttr, focus,
                   GetNativeControlledEntityKindsForSkillsCore(selected))
               + ScoreSharedSkillPackage(baseRole, activeRoles, focus);
    }

    private static double ScoreNativeSkillRoleObjective(NativeSkillRoleProfile role, HeroFocus focus)
    {
        // Confidence is a conservative output-retention ratio: unknown branches
        // contribute zero, while the independently proven lower bound remains.
        // Scale native quantities before the logarithmic objective so a single
        // role and the same role inside BuildSharedSkillPackage rank identically.
        var confidence = Math.Clamp(role.Confidence, 0d, 1d);
        // The preview is shorter for speed. Convert time-linear totals back to
        // the established 60-second reference before logarithmic weighting so
        // this optimization does not silently rebalance offense versus defense.
        var damage = GetManualDamageAmount(role.DamageByType, focus)
                     * PerformanceTimeLinearNormalization * confidence;
        var heal = role.Heal * PerformanceTimeLinearNormalization * confidence;
        var shield = role.Shield * PerformanceTimeLinearNormalization * confidence;
        var selfHeal = role.SelfHeal * PerformanceTimeLinearNormalization * confidence;
        var selfShield = role.SelfShield * PerformanceTimeLinearNormalization * confidence;
        var summonDamage = role.SummonDamage * PerformanceTimeLinearNormalization * confidence;
        var summonSurvival = role.SummonSurvival * confidence;
        var summonAttack = (role.SummonAttackByType?.Values
                                .Where(value => double.IsFinite(value) && value > 0d).Sum() ?? 0d)
                           * confidence;
        var abilitySupport = role.AbilitySupport * confidence;
        var abilityDefense = role.AbilityDefense * confidence;
        var abilityMinion = role.AbilityMinion * confidence;
        var controlledDamage = role.ControlledEntityDamage
                               * PerformanceTimeLinearNormalization * confidence;
        var controlledUtility = role.ControlledEntityUtility * confidence;
        var controlledSurvival = role.ControlledEntitySurvival * confidence;
        var allHostileStatus = GetAllHostileStatusOutput(role) * confidence;
        var themedHostileStatus = GetHostileStatusThemeOutput(role, focus) * confidence;
        var periodicTheme = GetNativeDamageThemeRule(focus)?.DamageTypes.All(IsPeriodicDamageType) == true;
        var general = Math.Log10(1d + damage) * 2d
                      + Math.Log10(1d + allHostileStatus) * 0.20d;
        var balanced = focus.Key switch
        {
            "defense" => Math.Log10(1d + selfShield * 1.5d + selfHeal + abilityDefense) * 4.5d
                         + Math.Log10(1d + damage) * 0.12d,
            "support" => Math.Log10(1d + heal * 1.4d + shield + abilitySupport) * 4.5d
                         + Math.Log10(1d + damage) * 0.10d,
            "minion" => Math.Log10(1d + summonDamage) * 3.5d
                         + Math.Log10(1d + summonSurvival) * 1.4d
                         + Math.Log10(1d + abilityMinion) * 3.2d
                         // A lower-weight, per-action structural proxy keeps the
                         // minion's native physical/elemental scaling visible when
                         // its later combat-AI cadence is not reproducible.
                         + Math.Log10(1d + summonAttack) * 1.25d
                         + Math.Log10(1d + controlledDamage) * 1.25d
                         + Math.Log10(1d + controlledUtility) * 1.10d
                         + Math.Log10(1d + controlledSurvival) * 0.55d
                         + Math.Log10(1d + damage) * 0.10d,
            _ when periodicTheme => Math.Log10(1d + damage) * 1.2d
                                    + Math.Log10(1d + themedHostileStatus) * 3.6d,
            _ => general
        };
        var themed = focus.Key switch
        {
            "defense" => Math.Log10(1d + selfShield * 1.5d + selfHeal + abilityDefense) * 5.4d,
            "support" => Math.Log10(1d + heal * 1.4d + shield + abilitySupport) * 5.4d,
            "minion" => Math.Log10(1d + controlledDamage) * 5d
                         + Math.Log10(1d + controlledUtility) * 3.8d
                         + Math.Log10(1d + controlledSurvival) * 2.2d,
            _ when periodicTheme => Math.Log10(1d + damage) * 0.45d
                                    + Math.Log10(1d + themedHostileStatus) * 5.4d,
            _ => balanced
        };
        var raw = BlendThemePriority(focus, general, balanced, themed);
        return double.IsFinite(raw) ? raw : double.NegativeInfinity;
    }

    private static double ScoreNativeSkillRoleObjectiveWithConditional(
        NativeSkillRoleProfile role,
        ExpectedConditionalPackage expected,
        HeroFocus focus)
    {
        var confidence = Math.Clamp(role.Confidence, 0d, 1d);
        var damage = (GetManualDamageAmount(role.DamageByType, focus) * confidence
                      + expected.Damage) * PerformanceTimeLinearNormalization;
        var heal = (role.Heal * confidence + expected.Heal)
                   * PerformanceTimeLinearNormalization;
        var shield = (role.Shield * confidence + expected.Shield)
                     * PerformanceTimeLinearNormalization;
        var selfHeal = (role.SelfHeal * confidence + expected.SelfHeal)
                       * PerformanceTimeLinearNormalization;
        var selfShield = (role.SelfShield * confidence + expected.SelfShield)
                         * PerformanceTimeLinearNormalization;
        var summonDamage = role.SummonDamage * PerformanceTimeLinearNormalization * confidence;
        var summonSurvival = role.SummonSurvival * confidence;
        var summonAttack = (role.SummonAttackByType?.Values
                                .Where(value => double.IsFinite(value) && value > 0d).Sum() ?? 0d)
                           * confidence;
        var abilitySupport = role.AbilitySupport * confidence + expected.Support;
        var abilityDefense = role.AbilityDefense * confidence + expected.Defense;
        var abilityMinion = role.AbilityMinion * confidence + expected.Minion;
        var controlledDamage = role.ControlledEntityDamage
                               * PerformanceTimeLinearNormalization * confidence;
        var controlledUtility = role.ControlledEntityUtility * confidence + expected.Minion;
        var controlledSurvival = role.ControlledEntitySurvival * confidence;
        var allHostileStatus = GetAllHostileStatusOutput(role) * confidence;
        var themedHostileStatus = GetHostileStatusThemeOutput(role, focus) * confidence;
        var periodicTheme = GetNativeDamageThemeRule(focus)?.DamageTypes.All(IsPeriodicDamageType) == true;
        var general = Math.Log10(1d + damage) * 2d
                      + Math.Log10(1d + allHostileStatus) * 0.20d;
        var balanced = focus.Key switch
        {
            "defense" => Math.Log10(1d + selfShield * 1.5d + selfHeal + abilityDefense) * 4.5d
                         + Math.Log10(1d + damage) * 0.12d,
            "support" => Math.Log10(1d + heal * 1.4d + shield + abilitySupport) * 4.5d
                         + Math.Log10(1d + damage) * 0.10d,
            "minion" => Math.Log10(1d + summonDamage) * 3.5d
                         + Math.Log10(1d + summonSurvival) * 1.4d
                         + Math.Log10(1d + abilityMinion) * 3.2d
                         + Math.Log10(1d + summonAttack) * 1.25d
                         + Math.Log10(1d + controlledDamage) * 1.25d
                         + Math.Log10(1d + controlledUtility) * 1.10d
                         + Math.Log10(1d + controlledSurvival) * 0.55d
                         + Math.Log10(1d + damage) * 0.10d,
            _ when periodicTheme => Math.Log10(1d + damage) * 1.2d
                                    + Math.Log10(1d + themedHostileStatus) * 3.6d,
            _ => general
        };
        var themed = focus.Key switch
        {
            "defense" => Math.Log10(1d + selfShield * 1.5d + selfHeal + abilityDefense) * 5.4d,
            "support" => Math.Log10(1d + heal * 1.4d + shield + abilitySupport) * 5.4d,
            "minion" => Math.Log10(1d + controlledDamage) * 5d
                         + Math.Log10(1d + controlledUtility) * 3.8d
                         + Math.Log10(1d + controlledSurvival) * 2.2d,
            _ when periodicTheme => Math.Log10(1d + damage) * 0.45d
                                    + Math.Log10(1d + themedHostileStatus) * 5.4d,
            _ => balanced
        };
        var raw = BlendThemePriority(focus, general, balanced, themed);
        return double.IsFinite(raw) ? raw : double.NegativeInfinity;
    }

    private static bool HasNativeSummonDefinition(
        object hero,
        int skillId,
        int level = 1,
        object? attrOverride = null,
        bool applyCurrentEquipmentVariant = true,
        IEnumerable<GearCandidate>? candidateItems = null)
    {
        var items = candidateItems?.ToList();
        try
        {
            return MainThreadNativeGateway.Invoke(() => HasNativeSummonDefinitionCore(
                hero, skillId, level, attrOverride, applyCurrentEquipmentVariant, items));
        }
        catch
        {
            return false;
        }
    }

    private static bool HasNativeSummonDefinitionCore(
        object hero,
        int skillId,
        int level,
        object? attrOverride,
        bool applyCurrentEquipmentVariant,
        IReadOnlyCollection<GearCandidate>? candidateItems)
    {
        if (skillId <= 0) return false;
        var attr = attrOverride ?? Read(hero, "attrData");
        if (attr is null) return false;
        var preview = InvokeRequiredStaticMany(
            "SkillData", "CreatePreview", skillId, Math.Max(1, level), attr);
        if (preview is null) return false;
        var variantEnabled = (candidateItems is not null && CandidateEnablesSkillVariant(candidateItems, skillId))
                             || (applyCurrentEquipmentVariant && CurrentEquipmentEnablesSkillVariant(hero, skillId));
        if (variantEnabled) InvokeRequiredInstance(preview, "SetVariant", true);
        var info = Read(preview, "tSkillInfoData");
        return info is not null
               && GetNativeControlledEntityKindsForSkillInfoCore(info)
               != NativeControlledEntityKind.None;
    }

    private static bool HasProvenNativeRoleSignal(NativeSkillRoleProfile role)
        => role.DamageByType.Any(entry => entry.Key > 0 && double.IsFinite(entry.Value) && entry.Value > 0d)
           || double.IsFinite(role.Heal) && role.Heal > 0d
           || double.IsFinite(role.Shield) && role.Shield > 0d
           || double.IsFinite(role.SummonDamage) && role.SummonDamage > 0d
           || double.IsFinite(role.SummonSurvival) && role.SummonSurvival > 0d
           || role.SummonAttackByType?.Any(entry => entry.Key > 0
                                                    && double.IsFinite(entry.Value)
                                                    && entry.Value > 0d) == true
           || double.IsFinite(role.AbilitySupport) && role.AbilitySupport > 0d
           || double.IsFinite(role.AbilityDefense) && role.AbilityDefense > 0d
           || double.IsFinite(role.AbilityMinion) && role.AbilityMinion > 0d
           || role.HostileStatusApplications?.Any(entry => entry.Key > 0
                                                            && double.IsFinite(entry.Value)
                                                            && entry.Value > 0d) == true;

    private static bool IsNativeRoleRankable(NativeSkillRoleProfile role, HeroFocus focus)
    {
        // The controlled-object category is a structural fact from the native
        // action/produce/emitter graph. Missing combat-AI numbers lower its
        // score but must not collapse Minion, Ally or Totem into plain support.
        if (focus.Key == "minion"
            && role.ControlledEntityKinds != NativeControlledEntityKind.None) return true;
        if (!HasProvenNativeRoleSignal(role)) return false;
        var score = ScoreNativeSkillRoleObjective(role, focus);
        return double.IsFinite(score) && score > 0.000000001d;
    }

    private static bool IsNativePackageRankable(NativeSkillRoleProfile role, HeroFocus focus)
    {
        if (!IsNativeRoleRankable(role, focus)) return false;
        // A controlled-object package must actually contain a game-defined
        // Minion/Ally spawn or Totem emitter.
        return focus.Key != "minion"
               || role.ControlledEntityKinds != NativeControlledEntityKind.None;
    }

    private static double ScoreCurrentPreferredSkillPackage(object hero, object talentData,
        PreferredTalentPlan preferred, object attrData, HeroFocus focus)
        => ScorePreferredSharedSkillPackage(hero, talentData, preferred, attrData, focus, 0, -1);

    private static double ScorePreferredSharedSkillPackage(
        object hero,
        object talentData,
        PreferredTalentPlan preferred,
        object attrData,
        HeroFocus focus,
        int overrideSkillId,
        int overrideLevel)
    {
        var definitions = preferred.SkillTalentIds
            .Select(id => InvokeStatic("TableData", "getTTalentData", id))
            .Where(row => (ReadNullableInt(row, "skillId") ?? 0) > 0).Cast<object>().ToList();
        var baseSkillId = definitions.Where(IsBaseSkillDefinition)
            .Select(row => ReadNullableInt(row, "skillId") ?? 0).FirstOrDefault(id => id > 0);
        var activeSkillIds = definitions.Where(IsTransformableSkillDefinition)
            .Select(row => ReadNullableInt(row, "skillId") ?? 0).Where(id => id > 0).Distinct().ToList();
        if (baseSkillId <= 0) return ScoreHeroAttrObjective(attrData, focus);
        var selectedSkillIds = activeSkillIds.Append(baseSkillId).ToHashSet();
        var runtimeLevels = ReadValues(Read(talentData, "talentDic"))
            .Where(talent => selectedSkillIds.Contains(ReadNullableInt(Read(talent, "tTalentData"), "skillId") ?? 0))
            .GroupBy(talent => ReadNullableInt(Read(talent, "tTalentData"), "skillId") ?? 0)
            .Where(group => group.Key > 0)
            .ToDictionary(group => group.Key, group => Math.Max(1, group.Max(GetTalentLevel)));
        int EffectiveLevel(int skillId)
            => skillId == overrideSkillId ? overrideLevel : runtimeLevels.GetValueOrDefault(skillId, 1);
        var packageAttr = CreateStrictSkillPackageAdjustedAttr(
            hero,
            selectedSkillIds.Select(skillId => (SkillId: skillId, Level: EffectiveLevel(skillId)))
                .Where(entry => entry.Level > 0),
            attrData,
            true,
            null,
            out _);
        NativeSkillRoleProfile RoleFor(int skillId)
        {
            var level = EffectiveLevel(skillId);
            return level <= 0
                ? EmptyNativeSkillRole()
                : ReadNativeSkillRoleProfile(hero, skillId, level, packageAttr, true,
                    null, true, false);
        }
        return ScoreHeroAttrObjective(
                   packageAttr, focus,
                   GetNativeControlledEntityKindsForSkillsCore(selectedSkillIds))
               + ScoreSharedSkillPackage(RoleFor(baseSkillId), activeSkillIds.Select(RoleFor), focus);
    }

    private static NativeSkillRoleProfile EmptyNativeSkillRole()
        => new(new Dictionary<int, double>(), 0d, 0d, false, 0d, 0d, 0d, 0d, 0d, 0d, 1d);

    private static object? ApplyMasteryAttributePreview(
        object attrData,
        int masteryId,
        int level,
        int cap,
        bool active)
    {
        if (masteryId <= 0 || level <= 0) return null;
        var preview = InvokeRequiredStaticMany("MasteryData", "CreateByShow", masteryId, level, cap)
                      ?? throw new InvalidOperationException($"MasteryData.CreateByShow({masteryId}) returned no mastery.");
        foreach (var affix in ReadList(Read(preview, "affixList")))
        {
            if ((ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0) != 1) continue;
            InvokeRequiredInstance(affix, "SetActiveAttrData", attrData, active);
        }
        return preview;
    }

    private static double ScoreTalentPointMarginalGain(object hero, object talentData, object talent,
        HeroFocus focus, PreferredTalentPlan preferred)
    {
        var definition = Read(talent, "tTalentData")
                         ?? throw new InvalidOperationException("Talent definition is unavailable.");
        var type = ReadNullableInt(definition, "type") ?? 0;
        var currentLevel = Math.Max(0, GetTalentLevel(talent));
        var nextLevel = currentLevel + 1;
        if (nextLevel > GetTalentLevelCap(talent)) return double.NegativeInfinity;
        var heroAttr = Read(hero, "attrData") ?? throw new InvalidOperationException("Hero AttrData is unavailable.");

        if (type == 1)
        {
            var skillId = ReadNullableInt(definition, "skillId") ?? 0;
            if (skillId <= 0 || !preferred.PreferredSkillIds.Contains(skillId)) return double.NegativeInfinity;
            var before = ScorePreferredSharedSkillPackage(
                hero, talentData, preferred, heroAttr, focus, skillId, currentLevel);
            var after = ScorePreferredSharedSkillPackage(
                hero, talentData, preferred, heroAttr, focus, skillId, nextLevel);
            return after - before;
        }

        if (type == 2)
        {
            var talentId = ReadNullableInt(definition, "id") ?? 0;
            if (!preferred.MasteryTalentIds.Contains(talentId)) return double.NegativeInfinity;
            var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
            if (masteryId <= 0) return double.NegativeInfinity;
            var baseline = InvokeRequiredStaticMany("AttrData", "copyCreate", heroAttr)
                           ?? throw new InvalidOperationException("AttrData mastery baseline copy failed.");
            var simulated = InvokeRequiredStaticMany("AttrData", "copyCreate", heroAttr)
                            ?? throw new InvalidOperationException("AttrData mastery simulation copy failed.");
            var cap = GetTalentLevelCap(talent);
            ApplyMasteryAttributePreview(simulated, masteryId, currentLevel, cap, false);
            ApplyMasteryAttributePreview(simulated, masteryId, nextLevel, cap, true);
            var numericDelta = ScoreCurrentPreferredSkillPackage(hero, talentData, preferred, simulated, focus)
                               - ScoreCurrentPreferredSkillPackage(hero, talentData, preferred, baseline, focus);
            var beforeAbility = 0d;
            if (currentLevel > 0)
            {
                var beforePreview = InvokeRequiredStaticMany("MasteryData", "CreateByShow", masteryId, currentLevel, cap)
                                    ?? throw new InvalidOperationException($"MasteryData.CreateByShow({masteryId}) returned no current preview.");
                beforeAbility = ScoreMasteryAbilityObjective(beforePreview, focus, baseline);
            }
            var afterPreview = InvokeRequiredStaticMany("MasteryData", "CreateByShow", masteryId, nextLevel, cap)
                               ?? throw new InvalidOperationException($"MasteryData.CreateByShow({masteryId}) returned no next preview.");
            return numericDelta + ScoreMasteryAbilityObjective(afterPreview, focus, simulated) - beforeAbility;
        }

        return double.NegativeInfinity;
    }

    private static object CreateTalentNeutralObjectiveAttr(object hero, IEnumerable<object> gridTalents)
    {
        var live = Read(hero, "attrData") ?? throw new InvalidOperationException("Hero AttrData is unavailable.");
        var clean = InvokeRequiredStaticMany("AttrData", "copyCreate", live)
                    ?? throw new InvalidOperationException("AttrData talent-neutral copy failed.");
        foreach (var talent in gridTalents)
        {
            var definition = Read(talent, "tTalentData");
            if ((ReadNullableInt(definition, "type") ?? 0) != 2 || GetSavedTalentLevel(talent) <= 0) continue;
            foreach (var affix in ReadList(Read(Read(talent, "masteryData"), "affixList")))
            {
                if ((ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0) != 1) continue;
                InvokeRequiredInstance(affix, "SetActiveAttrData", clean, false);
            }
            // Reset removes only the saved investment. Equipment/inspiration
            // baseLevel remains active, so restore that exact post-reset layer
            // after removing the current effective mastery.
            var baseLevel = Math.Min(GetTalentBaseLevelRequired(talent), GetTalentLevelCap(talent));
            var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
            if (baseLevel <= 0 || masteryId <= 0) continue;
            var basePreview = InvokeRequiredStaticMany("MasteryData", "CreateByShow", masteryId, baseLevel, GetTalentLevelCap(talent))
                              ?? throw new InvalidOperationException($"MasteryData.CreateByShow({masteryId}) returned no base-level mastery.");
            foreach (var affix in ReadList(Read(basePreview, "affixList")))
            {
                if ((ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0) != 1) continue;
                InvokeRequiredInstance(affix, "SetActiveAttrData", clean, true);
            }
        }
        return clean;
    }

    private static object CreateGearAndTalentNeutralObjectiveAttr(
        object hero,
        IEnumerable<object> gridTalents)
    {
        var clean = CreateTalentNeutralObjectiveAttr(hero, gridTalents);
        // The global skill census must not inherit the incumbent equipment's
        // element/skill bonuses. Otherwise the old gear can select its own skill
        // and then use that selection to prove that the same gear is best.
        foreach (var slot in GetGearSlots())
        {
            var item = GetEquippedItem(hero, slot.Part, slot.MainWeapon);
            if (item is not null)
                ApplyEquipmentToAttr(clean, item, false, includeForgeBonuses: true);
        }
        return clean;
    }

    private static double ScoreHeroAttrObjective(
        object attrData,
        HeroFocus focus,
        NativeControlledEntityKind controlledEntityKinds = NativeControlledEntityKind.None)
    {
        double Positive(int attrId) => Math.Max(0d, ReadAttrRequired(attrData, attrId));
        double Sum(params int[] attrIds) => attrIds.Sum(Positive);

        var physical = Positive(1);
        var elemental = Positive(2);
        var attack = focus.Key is "physical" or "bleed" ? physical
            : focus.Key is "elemental" or "fire" or "ice" or "lightning" or "corrosion" ? elemental
            : Math.Max(physical, elemental);
        var crit = Sum(31, 37);
        var hp = Positive(5);
        var defence = Sum(3, 4);
        var sustain = Sum(7, 220, 222, 224);
        var avoidance = Sum(32, 34, 36, 85, 86);
        var resistance = Sum(61, 62, 63, 64, 65, 66, 130, 131, 132);
        var preventionFlags = new[] { 151, 152, 153, 154, 155, 156, 157, 158, 184, 188, 202 }
            .Sum(id => Math.Min(1d, Positive(id)));
        var defensePenalty = Math.Min(1d, Positive(200)) + Math.Min(1d, Positive(201));
        var support = Sum(81, 82, 83, 84, 91, 92, 93, 94, 185, 191);
        // Native type ownership is decisive: buddyMaxCount is Ally-only, while
        // minionTimeUp changes finite TSummon Minions. Totems are emitters and
        // receive neither stat unless a native ability explicitly targets them.
        var minion = (controlledEntityKinds.HasFlag(NativeControlledEntityKind.Ally)
                          ? Positive(25) * 50d
                          : 0d)
                     + (controlledEntityKinds.HasFlag(NativeControlledEntityKind.Minion)
                         ? Positive(190)
                         : 0d);
        // HP/defence/regen are native final GetAttrValue outputs. Their up-rate
        // and conversion buckets must not be added a second time.
        var survival = hp + defence * 2d + sustain * 4d + avoidance * 2d
                       + resistance * 1.5d;
        var general = Math.Log10(1d + attack) * 2d + Math.Log10(1d + crit);
        var balanced = focus.Key switch
        {
            "defense" => Math.Log10(1d + survival) * 3.2d + preventionFlags * 0.65d
                         - defensePenalty * 2.5d + Math.Log10(1d + attack) * 0.35d,
            "support" => Math.Log10(1d + support * 10d) * 3.2d
                         + Math.Log10(1d + survival) * 0.8d - defensePenalty,
            "minion" => Math.Log10(1d + minion) * 3d + Math.Log10(1d + attack),
            "crit" => Math.Log10(1d + attack) * 2d + Math.Log10(1d + crit) * 2d,
            _ => general
        };
        var themed = focus.Key switch
        {
            "defense" => Math.Log10(1d + survival) * 4d + preventionFlags * 0.8d
                         - defensePenalty * 3d,
            "support" => Math.Log10(1d + support * 10d) * 4d
                         + Math.Log10(1d + survival) * 0.45d - defensePenalty,
            "minion" => Math.Log10(1d + minion) * 4.5d,
            "crit" => Math.Log10(1d + attack) * 1.4d + Math.Log10(1d + crit) * 3d,
            _ => balanced
        };
        return BlendThemePriority(focus, general, balanced, themed);
    }

    private static PreferredTalentPlan SelectPreferredActiveSkillTargets(object hero, object talentData, PreferredTalentPlan preferred, HeroFocus focus)
    {
        var desiredRows = preferred.SkillTalentIds
            .Select((talentId, index) => (TalentId: talentId, Index: index, Definition: InvokeStatic("TableData", "getTTalentData", talentId)))
            .Where(entry => IsTransformableSkillDefinition(entry.Definition))
            .Select(entry => (entry.TalentId, entry.Index, Definition: entry.Definition!, SkillId: ReadNullableInt(entry.Definition, "skillId") ?? 0))
            .Where(entry => entry.SkillId > 0)
            .GroupBy(entry => entry.SkillId)
            .Select(group => group.OrderBy(entry => entry.Index).First())
            .ToList();
        var nativeSummonSkillIds = new HashSet<int>();
        if (focus.Key == "minion")
        {
            var saveHero = Read(hero, "saveHeroData");
            var jobId = ReadNullableInt(saveHero, "jobId") ?? 0;
            var existingSkillIds = desiredRows.Select(entry => entry.SkillId).ToHashSet();
            var summonDefinitions = MainThreadNativeGateway.Invoke(() =>
                ReadValues(ReadStatic("TableData", "TTalentDict"))
                    .Where(IsTransformableSkillDefinition)
                    .Where(row => (ReadNullableInt(row, "jobId") ?? 0) == jobId)
                    .Where(row => GetNativeControlledEntityKindsForSkillCore(
                                      ReadNullableInt(row, "skillId") ?? 0)
                                  != NativeControlledEntityKind.None)
                    .OrderBy(row => ReadNullableInt(row, "index") ?? int.MaxValue)
                    .ThenBy(row => ReadNullableInt(row, "id") ?? int.MaxValue)
                    .ToList());
            foreach (var definition in summonDefinitions)
            {
                var talentId = ReadNullableInt(definition, "id") ?? 0;
                var skillId = ReadNullableInt(definition, "skillId") ?? 0;
                if (talentId <= 0 || skillId <= 0) continue;
                nativeSummonSkillIds.Add(skillId);
                if (existingSkillIds.Add(skillId))
                    desiredRows.Add((talentId, int.MaxValue, definition, skillId));
            }
        }
        if (desiredRows.Count == 0) return preferred;
        var desiredDefinitionsByTalentId = desiredRows
            .ToDictionary(entry => entry.TalentId, entry => entry.Definition);

        // ShrineWashData.WashHero delegates to HeroTalentData.ReCreateTalent.
        // It can replace only currently unlocked, non-fixed active-skill rows;
        // the number of usable rows grows with hero level and must be measured
        // every run instead of being treated as a fixed four-slot loadout.
        var current = GetTransformableTalents(talentData).ToList();
        var unlocked = current.Where(talent => !IsTalentLockedRequired(talent)).ToList();
        var allDesiredSkillIds = desiredRows.Select(entry => entry.SkillId).ToHashSet();
        var fixedCurrentSkillIds = unlocked
            .Where(IsTalentUnreplaceable)
            .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "skillId") ?? 0)
            .Where(id => id > 0).ToHashSet();
        var fixedUnwantedRows = unlocked.Count(talent =>
        {
            if (!IsTalentUnreplaceable(talent)) return false;
            var skillId = ReadNullableInt(Read(talent, "tTalentData"), "skillId") ?? 0;
            return !allDesiredSkillIds.Contains(skillId);
        });
        var capacity = Math.Min(desiredRows.Count, Math.Max(0, unlocked.Count - fixedUnwantedRows));

        var ranked = desiredRows.Select(entry =>
        {
            return (entry.TalentId, entry.Index, entry.SkillId,
                Fixed: fixedCurrentSkillIds.Contains(entry.SkillId),
                Objective: preferred.ObjectiveScores?.GetValueOrDefault(entry.TalentId) ?? 0d);
        }).ToList();

        var selectedRows = ranked
            // Never discard a matching skill that the user explicitly fixed.
            .OrderByDescending(entry => entry.Fixed)
            .ThenByDescending(entry => entry.Objective)
            .ThenBy(entry => entry.Index)
            .ThenBy(entry => entry.TalentId)
            .Take(capacity)
            .ToList();
        var selectedBaseSkillId = preferred.SkillTalentIds
            .Select(talentId => InvokeStatic("TableData", "getTTalentData", talentId))
            .Where(IsBaseSkillDefinition)
            .Select(definition => ReadNullableInt(definition, "skillId") ?? 0)
            .FirstOrDefault(skillId => skillId > 0);
        var requiredCoreActiveSkillIds = (preferred.RequiredActiveSkillIds ?? new HashSet<int>())
            .Concat(focus.Key == "minion" ? nativeSummonSkillIds : Enumerable.Empty<int>())
            .Where(id => id > 0).ToHashSet();
        var baseSatisfiesCore = preferred.RequiredBaseSkillIds?.Contains(
            selectedBaseSkillId) == true;
        var requiredCoreRows = ranked
            .Where(entry => requiredCoreActiveSkillIds.Contains(entry.SkillId))
            .OrderByDescending(entry => entry.Fixed)
            .ThenByDescending(entry => entry.Objective)
            .ThenBy(entry => entry.Index)
            .ThenBy(entry => entry.TalentId)
            .ToList();
        if (!baseSatisfiesCore
            && requiredCoreActiveSkillIds.Count > 0
            && requiredCoreRows.Count == 0)
            throw new InvalidOperationException(
                $"No unlocked active row can satisfy the required native {focus.English} core.");

        var themePackageSkillIds = preferred.ThemePackageSkillIds is { Count: > 0 }
            ? preferred.ThemePackageSkillIds.Where(id => id > 0).ToHashSet()
            : (preferred.RequiredBaseSkillIds ?? new HashSet<int>())
                .Concat(requiredCoreActiveSkillIds)
                .Where(id => id > 0).ToHashSet();
        var availableThemeRows = ranked
            .Where(entry => themePackageSkillIds.Contains(entry.SkillId))
            .OrderByDescending(entry => entry.Fixed)
            .ThenByDescending(entry => entry.Objective)
            .ThenBy(entry => entry.Index)
            .ThenBy(entry => entry.TalentId)
            .ToList();
        var availableThemeSkillCount = availableThemeRows.Select(entry => entry.SkillId)
            .Append(themePackageSkillIds.Contains(selectedBaseSkillId) ? selectedBaseSkillId : 0)
            .Where(id => id > 0).Distinct().Count();
        var requiredThemeSkillCount = !HasFocusedRoleConstraint(focus) || availableThemeSkillCount == 0
            ? 0
            : preferred.RequiredThemeSkillCount > 0
                ? Math.Min(preferred.RequiredThemeSkillCount, availableThemeSkillCount)
                // Require roughly half of the usable active rows to come from one
                // native-tag/official-guide lane. This prevents a token one-skill
                // match without forcing every slot into the selected theme.
                : Math.Min(availableThemeSkillCount, Math.Max(1, (capacity + 1) / 2));

        void IncludeRequiredRow(
            (int TalentId, int Index, int SkillId, bool Fixed, double Objective) required,
            string failure)
        {
            if (selectedRows.Any(entry => entry.SkillId == required.SkillId)) return;
            if (selectedRows.Count < capacity)
            {
                selectedRows.Add(required);
                return;
            }

            var replacement = selectedRows
                .Select((entry, index) => (Entry: entry, Index: index))
                .Where(candidate => !candidate.Entry.Fixed)
                .OrderBy(candidate => themePackageSkillIds.Contains(candidate.Entry.SkillId) ? 1 : 0)
                .ThenBy(candidate => requiredCoreActiveSkillIds.Contains(candidate.Entry.SkillId) ? 1 : 0)
                .ThenBy(candidate => candidate.Entry.Objective)
                .ThenByDescending(candidate => candidate.Entry.Index)
                .FirstOrDefault();
            if (replacement.Entry == default)
                throw new InvalidOperationException(failure);
            selectedRows[replacement.Index] = required;
        }

        if (!baseSatisfiesCore
            && requiredCoreRows.Count > 0
            && selectedRows.All(entry => !requiredCoreActiveSkillIds.Contains(entry.SkillId)))
        {
            IncludeRequiredRow(
                requiredCoreRows[0],
                $"Unlocked/non-replaceable active rows leave no slot for the native {focus.English} core.");
        }

        int SelectedThemeCount()
            => selectedRows.Select(entry => entry.SkillId)
                .Append(themePackageSkillIds.Contains(selectedBaseSkillId) ? selectedBaseSkillId : 0)
                .Where(id => id > 0 && themePackageSkillIds.Contains(id))
                .Distinct().Count();
        while (SelectedThemeCount() < requiredThemeSkillCount)
        {
            var nextThemeRow = availableThemeRows.FirstOrDefault(candidate =>
                selectedRows.All(entry => entry.SkillId != candidate.SkillId));
            if (nextThemeRow == default)
                throw new InvalidOperationException(
                    $"The unlocked rows cannot form the required {focus.English} native skill package ({SelectedThemeCount()}/{requiredThemeSkillCount}).");
            IncludeRequiredRow(
                nextThemeRow,
                $"Unlocked/non-replaceable active rows leave no room for the required {focus.English} package ({SelectedThemeCount()}/{requiredThemeSkillCount}).");
        }

        // Isolated skill scores order the pool, but do not prove that the final
        // group is a coherent build. When the neutral native census covers the
        // complete pool, exhaust the small unlocked combination space and keep
        // the strongest package that satisfies both the authored relationship
        // and its actual output contract. New native damage/role mechanics use
        // this same path without named skill or item exceptions.
        var cachedRoles = preferred.NativeRolesBySkillId;
        if (capacity > 0
            && cachedRoles is { Count: > 0 }
            && cachedRoles.TryGetValue(selectedBaseSkillId, out var cachedBaseRole)
            && ranked.All(entry => cachedRoles.ContainsKey(entry.SkillId)))
        {
            var fixedRows = ranked.Where(entry => entry.Fixed)
                .DistinctBy(entry => entry.SkillId).ToList();
            if (fixedRows.Count > capacity)
                throw new InvalidOperationException(
                    $"The fixed active-skill rows exceed the unlocked package capacity ({fixedRows.Count}/{capacity}).");
            var fixedSkillIds = fixedRows.Select(entry => entry.SkillId).ToHashSet();
            var optionalRows = ranked.Where(entry => !fixedSkillIds.Contains(entry.SkillId)).ToList();
            var optionalByTalentId = optionalRows.ToDictionary(entry => entry.TalentId);
            var choose = capacity - fixedRows.Count;
            // Native definition/tag reads cross the IL2CPP reflection boundary.
            // Doing them inside every C(n, k) package comparison turned twelve
            // candidates into thousands of identical native reads (and could
            // consume the entire planning deadline).  Role alignment is an
            // immutable property of this already-captured candidate census, so
            // resolve it once and keep the exhaustive package comparison purely
            // managed.  This preserves the exact 30-second objective while
            // removing the newly introduced combinatorial UI-thread cost.
            var alignedByTalentId = ranked.ToDictionary(
                entry => entry.TalentId,
                entry => HasRequiredManualSkillRoleSignal(
                    cachedRoles[entry.SkillId],
                    focus,
                    desiredDefinitionsByTalentId.GetValueOrDefault(entry.TalentId)));
            var avoidableOffThemeByTalentId = ranked.ToDictionary(
                entry => entry.TalentId,
                entry => IsAvoidableOffThemeActiveSkill(
                    cachedRoles[entry.SkillId],
                    focus,
                    desiredDefinitionsByTalentId.GetValueOrDefault(entry.TalentId)));
            List<(int TalentId, int Index, int SkillId, bool Fixed, double Objective)>? bestRows = null;
            var bestThemeCompatibility = int.MinValue;
            var bestAlignedActiveCount = int.MinValue;
            var bestAvoidableOffThemeCount = int.MaxValue;
            var bestPackageScore = double.NegativeInfinity;
            var bestAlignedShare = double.NegativeInfinity;
            var bestIndividualScore = double.NegativeInfinity;
            var bestStableKey = string.Empty;
#if PATHOFIDLE_RUNTIME_TEST
            var runtimePackageRejections = new List<string>();
            var runtimeSkillContractRejections = 0;
            var runtimeNativeContractRejections = 0;
            var runtimeUnrankableRejections = 0;
            void RecordPackageRejection(string value)
            {
                value = Regex.Replace(value, @"\s+", " ").Trim();
                if (value.Length > 240) value = value[..237] + "...";
                var category = value.EndsWith(":skill-contract", StringComparison.Ordinal)
                    ? "skill"
                    : value.Contains(":unrankable:", StringComparison.Ordinal)
                        ? "unrankable"
                        : "native";
                if (category == "skill") runtimeSkillContractRejections++;
                else if (category == "unrankable") runtimeUnrankableRejections++;
                else runtimeNativeContractRejections++;
                // Keep representative failures from every stage. Recording only
                // the first combinations hid the later native-output failure when
                // early lexicographic combinations missed package coverage.
                if (runtimePackageRejections.Count(existing =>
                        category == "skill"
                            ? existing.EndsWith(":skill-contract", StringComparison.Ordinal)
                            : category == "unrankable"
                                ? existing.Contains(":unrankable:", StringComparison.Ordinal)
                                : !existing.EndsWith(":skill-contract", StringComparison.Ordinal)
                                  && !existing.Contains(":unrankable:", StringComparison.Ordinal)) >= 3)
                    return;
                runtimePackageRejections.Add(value);
            }
#endif
            if (choose <= optionalRows.Count)
            {
                foreach (var ids in EnumerateSkillCombinations(
                             optionalRows.Select(entry => entry.TalentId).ToList(), choose))
                {
                    var rows = fixedRows.Concat(ids.Select(id => optionalByTalentId[id]))
                        .DistinctBy(entry => entry.SkillId).ToList();
                    if (rows.Count != capacity) continue;
                    if (!SatisfiesThemeSkillContract(
                            selectedBaseSkillId,
                            rows.Select(entry => entry.SkillId),
                            Array.Empty<int>(),
                            preferred.RequiredBaseSkillIds,
                            requiredCoreActiveSkillIds,
                            themePackageSkillIds,
                            requiredThemeSkillCount))
                    {
#if PATHOFIDLE_RUNTIME_TEST
                        RecordPackageRejection(
                            $"skills=[{string.Join(',', rows.Select(entry => entry.SkillId).OrderBy(id => id))}]:skill-contract");
#endif
                        continue;
                    }
                    var roles = rows.Select(entry => cachedRoles[entry.SkillId]).ToList();
                    if (!SatisfiesNativeThemeOutputContract(
                            focus, cachedBaseRole, roles, out var package, out var packageFailure))
                    {
#if PATHOFIDLE_RUNTIME_TEST
                        RecordPackageRejection(
                            $"skills=[{string.Join(',', rows.Select(entry => entry.SkillId).OrderBy(id => id))}]:{packageFailure}");
#endif
                        continue;
                    }
                    if (!IsNativePackageRankable(package, focus))
                    {
#if PATHOFIDLE_RUNTIME_TEST
                        RecordPackageRejection(
                            $"skills=[{string.Join(',', rows.Select(entry => entry.SkillId).OrderBy(id => id))}]:unrankable:{package.Failure}");
#endif
                        continue;
                    }
                    var packageScore = ScoreNativeSkillRoleObjective(package, focus);
                    if (!double.IsFinite(packageScore)) continue;
                    // Theme priority 100 is a lexicographic preference, not a
                    // rejection gate: prefer a package without avoidable pure
                    // off-theme attacks whenever one exists, but retain the best
                    // complete fallback when fixed rows or the native skill pool
                    // make that impossible. That preserves exact point spending
                    // instead of aborting the whole skill transaction.
                    var alignedActiveCount = rows.Count(entry =>
                        alignedByTalentId.GetValueOrDefault(entry.TalentId));
                    var avoidableOffThemeCount = rows.Count(entry =>
                        avoidableOffThemeByTalentId.GetValueOrDefault(entry.TalentId));
                    var maximumPriority = GetActiveThemePriority() == 100;
                    var damageTheme = GetNativeDamageThemeRule(focus) is not null;
                    // At the explicit 100 endpoint, non-damage themes now get
                    // the same lexicographic lane protection as damage themes.
                    // First avoid pure off-theme attacks, then prefer broader
                    // proven role coverage. Lower priorities retain continuous
                    // native-output scoring and are not forced into a theme.
                    var themeCompatibility = !maximumPriority
                        ? 0
                        : (avoidableOffThemeCount == 0 ? 1000 : 0)
                          + alignedActiveCount - avoidableOffThemeCount * 1000;
                    var alignedShare = damageTheme
                        ? GetNativeThemeAlignedDamageShare(focus, package)
                        : roles.Count == 0
                            ? 0d
                            : alignedActiveCount / (double)roles.Count;
                    var individualScore = rows.Sum(entry => entry.Objective);
                    var stableKey = string.Join(",", rows.Select(entry => entry.TalentId)
                        .OrderBy(id => id));
                    const double packageComparisonEpsilon = 0.000000001d;
                    var better = bestRows is null;
                    if (!better && themeCompatibility != bestThemeCompatibility)
                        better = themeCompatibility > bestThemeCompatibility;
                    else if (!better && maximumPriority
                             && Math.Abs(alignedShare - bestAlignedShare)
                             > packageComparisonEpsilon)
                        // At the explicit maximum, native theme share owns the
                        // comparison before general package strength. Priorities
                        // below 100 remain continuous and score-first.
                        better = alignedShare > bestAlignedShare;
                    else if (!better
                             && Math.Abs(packageScore - bestPackageScore)
                             > packageComparisonEpsilon)
                        better = packageScore > bestPackageScore;
                    else if (!better && !maximumPriority
                             && Math.Abs(alignedShare - bestAlignedShare)
                             > packageComparisonEpsilon)
                        better = alignedShare > bestAlignedShare;
                    else if (!better
                             && Math.Abs(individualScore - bestIndividualScore)
                             > packageComparisonEpsilon)
                        better = individualScore > bestIndividualScore;
                    else if (!better)
                        better = string.CompareOrdinal(stableKey, bestStableKey) < 0;
                    if (!better) continue;
                    bestRows = rows;
                    bestThemeCompatibility = themeCompatibility;
                    bestAlignedActiveCount = alignedActiveCount;
                    bestAvoidableOffThemeCount = avoidableOffThemeCount;
                    bestPackageScore = packageScore;
                    bestAlignedShare = alignedShare;
                    bestIndividualScore = individualScore;
                    bestStableKey = stableKey;
                }
            }
            if (bestRows is null)
                throw new InvalidOperationException(
                    $"No unlocked active-skill combination satisfies the native {focus.English} output contract."
#if PATHOFIDLE_RUNTIME_TEST
                    + (runtimePackageRejections.Count == 0
                        ? " No candidate reached a rejection-reporting stage."
                        : $" Rejections=[{string.Join(" | ", runtimePackageRejections)}]"
                          + $" Counts=[skill={runtimeSkillContractRejections},native={runtimeNativeContractRejections},unrankable={runtimeUnrankableRejections}]"
                          + $" Context=[base={selectedBaseSkillId};capacity={capacity};core={string.Join(',', requiredCoreActiveSkillIds.OrderBy(id => id))};package={string.Join(',', themePackageSkillIds.OrderBy(id => id))};required={requiredThemeSkillCount};controlled={string.Join('|', cachedRoles.Where(entry => entry.Value.ControlledEntityKinds != NativeControlledEntityKind.None).OrderBy(entry => entry.Key).Select(entry => $"{entry.Key}:{entry.Value.ControlledEntityKinds}/damage={entry.Value.ControlledEntityDamage:0.###}/utility={entry.Value.ControlledEntityUtility:0.###}/survival={entry.Value.ControlledEntitySurvival:0.###}/complete={entry.Value.IsComplete}/failure={Regex.Replace(entry.Value.Failure ?? string.Empty, @"\s+", " ")}"))}]")
#endif
                );
            selectedRows = bestRows;
            Plugin.DiagInfo(
                $"AUTO-SKILLS PACKAGE CHOICE|focus={focus.Key}|themePriority={GetActiveThemePriority()}|compatible={bestThemeCompatibility}|alignedActive={bestAlignedActiveCount}/{selectedRows.Count}|avoidableOffTheme={bestAvoidableOffThemeCount}|alignedShare={bestAlignedShare:P1}|score={bestPackageScore:0.######}|skills={string.Join(',', selectedRows.Select(entry => entry.SkillId).OrderBy(id => id))}");
#if PATHOFIDLE_DIAGNOSTICS
            Plugin.DiagInfo(
                $"AUTO-SKILLS PACKAGE ROLES|focus={focus.Key}|"
                + string.Join("|", selectedRows.OrderBy(entry => entry.SkillId).Select(entry =>
                {
                    var role = cachedRoles[entry.SkillId];
                    return $"skill={entry.SkillId}/damage={GetTypedDamage(role):0.###}/heal={role.Heal:0.###}/selfHeal={role.SelfHeal:0.###}/shield={role.Shield:0.###}/selfShield={role.SelfShield:0.###}/support={role.AbilitySupport:0.###}/defense={role.AbilityDefense:0.###}/minion={role.AbilityMinion:0.###}/controlled={role.ControlledEntityKinds}";
                })));
#endif
        }
        var selectedSkillIds = selectedRows.Select(entry => entry.SkillId).ToHashSet();
        var excludedSkillIds = desiredRows.Select(entry => entry.SkillId).Where(id => !selectedSkillIds.Contains(id)).ToList();
        Plugin.DiagInfo(
            $"AUTO-SKILLS TARGETS|unlocked={unlocked.Count}|fixedUnwanted={fixedUnwantedRows}|core={string.Join(',', requiredCoreActiveSkillIds.OrderBy(id => id))}|package={string.Join(',', themePackageSkillIds.OrderBy(id => id))}|coverage={SelectedThemeCount()}/{requiredThemeSkillCount}|desired={string.Join(',', desiredRows.Select(entry => entry.SkillId))}|selected={string.Join(',', selectedRows.Select(entry => entry.SkillId))}|excluded={string.Join(',', excludedSkillIds)}");

        // Keep base/non-washable skills, then order transformable targets by the
        // same priority used above. The shrine can favorite only a limited
        // number of missing rows; preserving the original guide order here used
        // to put a cornerstone skill such as Divine Shelter last again.
        var selectedTalentIds = preferred.SkillTalentIds
            .Where(talentId => !IsTransformableSkillDefinition(InvokeStatic("TableData", "getTTalentData", talentId)))
            .Concat(selectedRows.Select(entry => entry.TalentId))
            .Distinct().ToList();
        var selectedPreferredSkillIds = selectedTalentIds
            .Select(talentId => InvokeStatic("TableData", "getTTalentData", talentId))
            .Select(definition => ReadNullableInt(definition, "skillId") ?? 0)
            .Where(skillId => skillId > 0).ToHashSet();
        return preferred with
        {
            SkillTalentIds = selectedTalentIds,
            // Keep the chosen base skill as well as the row-limited active
            // skills. Base-skill-linked masteries are part of the guide synergy
            // and must not disappear merely because the shrine cannot wash them.
            PreferredSkillIds = selectedPreferredSkillIds,
            RequiredActiveSkillIds = requiredCoreActiveSkillIds,
            ThemePackageSkillIds = themePackageSkillIds,
            RequiredThemeSkillCount = requiredThemeSkillCount
        };
    }

    private static string GetBuildGuideText(object? build)
    {
        if (build is null) return string.Empty;
        return Clean(string.Join(" ",
            ReadString(build, "name") ?? string.Empty,
            ReadString(build, "des") ?? string.Empty,
            EnglishName(build, string.Empty) ?? string.Empty,
            EnglishText(build, "_des", string.Empty) ?? string.Empty)).ToLowerInvariant();
    }

    private static bool BuildDirectlyMentionsSkill(string buildText, object skillTalentDefinition)
    {
        if (string.IsNullOrWhiteSpace(buildText)) return false;
        var skillId = ReadNullableInt(skillTalentDefinition, "skillId") ?? 0;
        var skill = skillId > 0 ? InvokeStatic("TableData", "getTSkillData", skillId) : null;
        var names = new[]
        {
            ReadString(skillTalentDefinition, "name"), EnglishName(skillTalentDefinition, string.Empty),
            ReadString(skill, "name"), EnglishName(skill, string.Empty)
        };
        return names.Select(name => Clean(name ?? string.Empty).ToLowerInvariant())
            .Where(name => name.Length >= 2).Distinct()
            .Any(buildText.Contains);
    }

    private static double ScoreTalent(object talent, HeroFocus focus, PreferredTalentPlan preferred)
    {
        var definition = Read(talent, "tTalentData");
        var skill = Read(talent, "skillData");
        var skillRow = Read(skill, "tSkillData") ?? (ReadNullableInt(definition, "skillId") is > 0 and var skillId ? InvokeStatic("TableData", "getTSkillData", skillId) : null);
        var info = Read(skill, "tSkillInfoData") ?? (ReadNullableInt(skillRow, "infoId") is > 0 and var infoId ? InvokeStatic("TableData", "getTSkillInfoData", infoId) : null);
        var masteryData = Read(talent, "masteryData");
        var mastery = Read(masteryData, "tMasteryData") ?? (ReadNullableInt(definition, "masteryId") is > 0 and var masteryId ? InvokeStatic("TableData", "getTMasteryData", masteryId) : null);
        var textParts = new List<string> { GetTalentDefinitionText(definition), EnglishName(skillRow, string.Empty) ?? string.Empty, EnglishText(info, "_des", string.Empty) ?? string.Empty, EnglishName(mastery, string.Empty) ?? string.Empty };
        foreach (var affix in ReadList(Read(masteryData, "affixList")))
        {
            var effectType = ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0;
            // Native MasteryData.GetMasteryEffect applies only attribute and
            // ability affixes. Do not let display-only type 4 metadata reorder
            // point allocation or automatic theme inference.
            if (effectType is 1 or 3) textParts.Add(GetAffixSearchText(affix));
        }
        var text = Clean(string.Join(" ", textParts)).ToLowerInvariant();
        var id = ReadNullableInt(definition, "id") ?? 0;
        var skillKey = ReadNullableInt(definition, "skillId") ?? 0;
        var objective = preferred.ObjectiveScores?.GetValueOrDefault(id) ?? 0d;
        if (objective <= 0d && skillKey > 0 && preferred.ObjectiveScores is not null)
            objective = preferred.SkillTalentIds
                .Where(talentId => (ReadNullableInt(InvokeStatic("TableData", "getTTalentData", talentId), "skillId") ?? 0) == skillKey)
                .Select(talentId => preferred.ObjectiveScores.GetValueOrDefault(talentId))
                .DefaultIfEmpty(0d).Max();
        // Objective scores are already normalized logarithmic 60-second skill
        // values or native attribute deltas. Keeping the raw ordering avoids the
        // old 5,000-point clamp that made nearly every damaging skill tie.
        var performance = Math.Max(0d, objective);
        var focusScore = KeywordScore(text, focus.Keywords) * (focus.IsManual ? 260d : 150d);
        var utility = KeywordScore(text, SupportWords) * (focus.Key == "support" ? 180d : 24d)
                      + KeywordScore(text, TankWords) * (focus.Key == "defense" ? 160d : 16d);
        var floor = ReadNullableInt(definition, "floor") ?? 0;
        return performance + focusScore + utility - floor * 0.1d;
    }

    private static string GetTalentDefinitionText(object? definition)
    {
        if (definition is null) return string.Empty;
        var skillId = ReadNullableInt(definition, "skillId") ?? 0;
        var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
        var skill = skillId > 0 ? InvokeStatic("TableData", "getTSkillData", skillId) : null;
        var infoId = ReadNullableInt(skill, "infoId") ?? 0;
        var info = infoId > 0 ? InvokeStatic("TableData", "getTSkillInfoData", infoId) : null;
        var mastery = masteryId > 0 ? InvokeStatic("TableData", "getTMasteryData", masteryId) : null;
        return Clean(string.Join(" ",
            ReadString(definition, "name") ?? string.Empty, EnglishName(definition, string.Empty) ?? string.Empty,
            ReadString(skill, "name") ?? string.Empty, EnglishName(skill, string.Empty) ?? string.Empty,
            ReadString(info, "des") ?? string.Empty, EnglishText(info, "_des", string.Empty) ?? string.Empty,
            ReadString(mastery, "name") ?? string.Empty, EnglishName(mastery, string.Empty) ?? string.Empty));
    }

    private static bool IsNormalTalentNode(object talent)
    {
        var definition = Read(talent, "tTalentData");
        return (ReadNullableInt(definition, "id") ?? 0) > 0 && !ReadBool(Read(talent, "isRuneWords"));
    }

    private static Dictionary<int, object> BuildTalentGridById(IEnumerable<object> talents)
        => MainThreadNativeGateway.Invoke(() => BuildTalentGridByIdCore(talents));

    private static Dictionary<int, object> BuildTalentGridByIdCore(IEnumerable<object> talents)
    {
        var groups = talents.Where(IsNormalTalentNode)
            .GroupBy(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
            .Where(group => group.Key > 0).ToList();
        var duplicates = groups.Where(group => group.Count() > 1).Select(group => group.Key).ToList();
        if (duplicates.Count > 0)
            Plugin.DiagWarning($"AUTO-SKILLS DUPLICATE TALENTS|ids={string.Join(',', duplicates)}");
        return groups.ToDictionary(
            group => group.Key,
            group => group.OrderBy(talent => IsTalentLockedRequired(talent) ? 1 : 0)
                .ThenByDescending(GetTalentLevel).First());
    }

    private static List<PreferredActiveSkill> ResolvePreferredActiveSkills(PreferredTalentPlan preferred, IReadOnlyDictionary<int, object> gridById)
        => MainThreadNativeGateway.Invoke(() => ResolvePreferredActiveSkillsCore(preferred, gridById));

    private static List<PreferredActiveSkill> ResolvePreferredActiveSkillsCore(PreferredTalentPlan preferred, IReadOnlyDictionary<int, object> gridById)
    {
        var result = new List<PreferredActiveSkill>();
        var resolvedSkillIds = new HashSet<int>();
        foreach (var guideTalentId in preferred.SkillTalentIds)
        {
            var guideDefinition = InvokeStatic("TableData", "getTTalentData", guideTalentId);
            if (!IsTransformableSkillDefinition(guideDefinition)) continue;
            var desiredSkillId = ReadNullableInt(guideDefinition, "skillId") ?? 0;
            if (desiredSkillId <= 0 || !resolvedSkillIds.Add(desiredSkillId)) continue;
            var talent = gridById.Values
                .Where(candidate => !IsTalentLockedRequired(candidate))
                .Where(candidate => (ReadNullableInt(Read(candidate, "tTalentData"), "skillId") ?? 0) == desiredSkillId)
                .OrderBy(candidate => (ReadNullableInt(Read(candidate, "tTalentData"), "id") ?? 0) == guideTalentId ? 0 : 1)
                .ThenBy(candidate => ReadNullableInt(Read(candidate, "tTalentData"), "id") ?? int.MaxValue)
                .FirstOrDefault();
            if (talent is null) continue;
            var talentId = ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0;
            if (talentId > 0) result.Add(new PreferredActiveSkill(guideTalentId, talentId, desiredSkillId, talent));
        }
        return result;
    }

    [Conditional("PATHOFIDLE_DIAGNOSTICS")]
    private static void LogPreferredActiveSkillState(string phase, IEnumerable<PreferredActiveSkill> activeSkills, IReadOnlyCollection<int> unresolvedSkillIds)
    {
        var states = activeSkills.Select(entry =>
            $"guide={entry.GuideTalentId}/talent={entry.TalentId}/skill={entry.SkillId}/save={GetSavedTalentLevel(entry.Talent)}/base={GetTalentBaseLevelRequired(entry.Talent)}/effective={GetTalentLevel(entry.Talent)}/cap={GetTalentLevelCap(entry.Talent)}");
        Plugin.DiagInfo($"AUTO-SKILLS ACTIVE {phase}|{string.Join(" ; ", states)}|unresolved={string.Join(',', unresolvedSkillIds)}");
    }

    private static bool IsBaseSkillDefinition(object? definition)
        => (ReadNullableInt(definition, "type") ?? 0) == 1 && (ReadNullableInt(definition, "miniType") ?? 0) == 1;

    private static bool IsTransformableSkillDefinition(object? definition)
        => (ReadNullableInt(definition, "type") ?? 0) == 1 && (ReadNullableInt(definition, "miniType") ?? 0) != 1
           && (ReadNullableInt(definition, "skillId") ?? 0) > 0;

    private static bool IsSkillCompatibleWithEquippedWeapons(object hero, int skillId)
    {
        if (skillId <= 0) return false;
        var skill = InvokeStatic("TableData", "getTSkillData", skillId)
                    ?? throw new InvalidOperationException($"Skill definition {skillId} is unavailable.");
        var weaponArr = Read(skill, "weaponArr");
        if (weaponArr is null) return true; // Native treats a null requirement as unrestricted.
        var heroEquipData = Read(hero, "heroEquipData")
                            ?? throw new InvalidOperationException("Hero equipment data is unavailable.");
        // Pass the game's native array object back to the game's own matcher.
        // It checks every equipped part-1 item (both weapon slots) and succeeds
        // when any required weapon type matches.
        return ReadBool(InvokeRequiredInstance(heroEquipData, "CheckHasWeaponTypeArr", weaponArr));
    }

    private static int GetTalentLevel(object talent)
        => Convert.ToInt32(InvokeRequiredInstance(talent, "GetLevel")
                           ?? throw new InvalidOperationException("The native talent level is unavailable."), CultureInfo.InvariantCulture);

    private static int GetSavedTalentLevel(object talent)
        => Math.Max(0, ReadRequiredIntProperty(
            ReadRequiredProperty(talent, "saveTalentData") ?? throw new InvalidOperationException("SaveTalentData is unavailable."),
            "level"));

    private static int GetTalentLevelCap(object talent)
        => Convert.ToInt32(InvokeRequiredInstance(talent, "GetTalentLevelCap")
                           ?? throw new InvalidOperationException("The native talent level cap is unavailable."), CultureInfo.InvariantCulture);

    private static int GetTalentBaseLevelRequired(object talent)
        => Math.Max(0, ReadRequiredIntProperty(talent, "baseLevel"));

    private static int GetExpectedTalentEffectiveLevel(object talent, int savedLevel)
        // Equipment and inspiration can provide a positive native baseLevel to
        // an otherwise uninvested mastery row. GetLevel includes that layer even
        // while saveTalentData.level is zero, so verification must preserve it.
        => Math.Min(GetTalentLevelCap(talent),
            GetTalentBaseLevelRequired(talent) + Math.Max(0, savedLevel));

    private static bool IsExpectedTalentEffectiveLevel(object talent, int savedLevel, int actualEffective)
    {
        var activeExpected = GetExpectedTalentEffectiveLevel(talent, savedLevel);
        // With no saved investment, the runtime legitimately exposes either the
        // equipment/inspiration base layer or zero depending on whether that
        // mastery row is currently activated by its native prerequisites.
        return savedLevel <= 0
            ? actualEffective == 0 || actualEffective == activeExpected
            : actualEffective == activeExpected;
    }

    private static bool IsTalentFixedRequired(object talent)
        => ReadRequiredBoolProperty(
            ReadRequiredProperty(talent, "saveTalentData") ?? throw new InvalidOperationException("SaveTalentData is unavailable."),
            "isFixed");

    private static bool IsTalentAlienRequired(object talent)
        => ReadRequiredBoolProperty(
            ReadRequiredProperty(talent, "saveTalentData") ?? throw new InvalidOperationException("SaveTalentData is unavailable."),
            "isAlien");

    private static bool IsTalentUnreplaceable(object talent)
        // `isFixed` is the player's Baptism roll preference, not a permanent
        // game rule. Auto Build may temporarily unlock it and restores any
        // surviving original preference afterwards. Alien rows are the actual
        // non-replaceable rows.
        => IsTalentAlienRequired(talent);

    private static int GetSpentTalentPoints(object talent)
    {
        var baseLevel = GetTalentBaseLevelRequired(talent);
        return Math.Max(0, GetTalentLevel(talent) - baseLevel);
    }

    private static int GetResettableTalentPointCount(object talentData, IReadOnlyCollection<object> talents)
    {
        _ = talents;
        // ResetTalentPoint calls this same native counter. If its contract is
        // unavailable, a save-data approximation is not a safe mutation gate.
        var native = InvokeRequiredInstance(talentData, "GetAddTalentPointExcludeStick");
        var count = Convert.ToInt32(native ?? throw new InvalidOperationException("Native talent-point count was null."), CultureInfo.InvariantCulture);
        if (count >= 0) return count;
        throw new InvalidOperationException($"Native talent-point count was negative ({count}).");
    }

    private static int PreviewExactTalentPointBudget(object talentData, object saveHero,
        IReadOnlyCollection<object> talents, int spentBefore)
    {
        _ = talents;
        if (spentBefore <= 0)
            return Math.Max(0, ReadNullableInt(saveHero, "talentRemainPoint") ?? 0);

        var blessBefore = ReadNullableInt(saveHero, "blessTalentPoint")
                          ?? throw new InvalidOperationException("The saved blessing talent-point value is unavailable.");
        int total;
        try
        {
            InvokeRequiredInstance(talentData, "RecalcBlessTalentPointByMilestones");
            total = Convert.ToInt32(
                InvokeRequiredInstance(saveHero, "GetTotalTalentPoint")
                ?? throw new InvalidOperationException("The native total talent point value is unavailable."),
                CultureInfo.InvariantCulture);
        }
        finally
        {
            Write(saveHero, "blessTalentPoint", blessBefore);
        }

        if ((ReadNullableInt(saveHero, "blessTalentPoint") ?? int.MinValue) != blessBefore)
            throw new InvalidOperationException("The blessing talent-point preview snapshot could not be restored.");
        if (total < 0)
            throw new InvalidOperationException($"The native total talent point value was negative ({total}).");
        return total;
    }

    private static bool CanAddTalentPoint(object talent)
    {
        if (GetTalentLevel(talent) >= GetTalentLevelCap(talent)) return false;
        return !IsTalentLockedRequired(talent);
    }

    private static bool IsTalentLockedRequired(object talent)
        => ReadBool(InvokeRequiredInstance(talent, "IsLock"));

    private static bool CanAutoAllocateTalent(object talent, object hero, PreferredTalentPlan preferred)
    {
        if (!CanAddTalentPoint(talent)) return false;
        var definition = Read(talent, "tTalentData");
        if ((ReadNullableInt(definition, "type") ?? 0) != 1) return true;

        // Active/base skill nodes are loadout choices, not generic places to
        // dump leftover points. Restrict them to the selected game guide and
        // prove their weapon requirement before spending anything on them.
        var talentId = ReadNullableInt(definition, "id") ?? 0;
        var skillId = ReadNullableInt(definition, "skillId") ?? 0;
        if (!preferred.SkillTalentIds.Contains(talentId)
            && (skillId <= 0 || !preferred.PreferredSkillIds.Contains(skillId))) return false;
        return skillId > 0 && IsSkillCompatibleWithEquippedWeapons(hero, skillId);
    }

    private static string DescribeUnspentPointConstraint(
        IEnumerable<object> talents,
        object hero,
        PreferredTalentPlan preferred,
        IReadOnlyCollection<int> failedNodes,
        IReadOnlyCollection<int> previewFailedNodes,
        bool exactJointPlan)
    {
        if (exactJointPlan)
        {
            var selectedIds = preferred.SkillTalentIds
                .Concat(preferred.MasteryTalentIds)
                .Where(id => id > 0)
                .ToHashSet();
            var feasible = talents
                .Where(talent =>
                {
                    var id = ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0;
                    return selectedIds.Contains(id) && !failedNodes.Contains(id)
                           && CanAutoAllocateTalent(talent, hero, preferred);
                })
                .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
                .Where(id => id > 0).Distinct().OrderBy(id => id).ToList();
            if (feasible.Count > 0)
                return $"selected joint-plan nodes remained feasible after bounded redistribution [{string.Join(',', feasible)}]";
            return failedNodes.Count > 0
                ? $"all remaining selected joint-plan writes were rejected [{string.Join(',', failedNodes.OrderBy(id => id))}]"
                : "no unlocked, weapon-compatible, non-capped selected joint-plan node remains";
        }

        var allocatable = new List<int>();
        foreach (var talent in talents)
        {
            try
            {
                if (!CanAutoAllocateTalent(talent, hero, preferred)) continue;
                var id = ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0;
                if (id > 0) allocatable.Add(id);
            }
            catch
            {
                // An unreadable native eligibility result is itself a constraint;
                // it must not be represented as an available target.
            }
        }
        if (allocatable.Count == 0)
            return "no unlocked, weapon-compatible, non-capped selected node remains";
        var failed = allocatable.Where(failedNodes.Contains).Distinct().OrderBy(id => id).ToList();
        var previewFailed = allocatable.Where(previewFailedNodes.Contains).Distinct().OrderBy(id => id).ToList();
        if (failed.Count > 0 || previewFailed.Count > 0)
            return $"native point-write failures [{string.Join(',', failed)}], preview failures [{string.Join(',', previewFailed)}]";
        return $"eligible nodes made no native progress [{string.Join(',', allocatable.Distinct().OrderBy(id => id))}]";
    }

    private static bool TrySpendTalentPoints(object talentData, object saveHero, object talent, int requested, out int spent)
    {
        // Preserve the game's one-point native write semantics, but keep its
        // complete before/write/after postcondition inside one main-thread work
        // item. Previously each helper below queued another item, turning one
        // point into roughly a dozen frame waits during exclusive mutation.
        var outcome = MainThreadNativeGateway.Invoke(() =>
        {
            var beforeRemain = ReadNullableInt(saveHero, "talentRemainPoint") ?? 0;
            var beforeLevel = GetTalentLevel(talent);
            var beforeSavedLevel = GetSavedTalentLevel(talent);
            var cap = GetTalentLevelCap(talent);
            var amount = Math.Min(Math.Max(0, requested),
                Math.Min(beforeRemain, Math.Max(0, cap - beforeLevel)));
            if (amount <= 0 || !CanAddTalentPoint(talent))
                return new TalentPointSpendOutcome(false, 0);

            var result = Convert.ToInt32(
                InvokeRequiredInstance(talentData, "AddTalentPoint", talent, amount) ?? 1,
                CultureInfo.InvariantCulture);
            var afterRemain = ReadNullableInt(saveHero, "talentRemainPoint") ?? beforeRemain;
            var afterLevel = GetTalentLevel(talent);
            var afterSavedLevel = GetSavedTalentLevel(talent);
            var remainDelta = beforeRemain - afterRemain;
            var levelDelta = afterLevel - beforeLevel;
            var savedLevelDelta = afterSavedLevel - beforeSavedLevel;
            // Native state is authoritative. Some game builds report a non-zero
            // status after applying a smaller legal prefix of a bulk request;
            // accept it only when all three independent deltas are identical.
            if (remainDelta > 0 && remainDelta <= amount
                && remainDelta == levelDelta && remainDelta == savedLevelDelta)
                return new TalentPointSpendOutcome(true, remainDelta);

            Plugin.DiagWarning($"AUTO-SKILLS ADD FAILED|talent={ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0}|code={result}|requested={amount}|remainDelta={remainDelta}|levelDelta={levelDelta}|savedLevelDelta={savedLevelDelta}");
            return new TalentPointSpendOutcome(false, 0);
        });
        spent = outcome.Spent;
        return outcome.Succeeded;
    }

    private static int SpendTalentToCap(object talentData, object saveHero, object talent, HashSet<int> failedNodes)
    {
        var talentId = ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0;
        var remain = ReadNullableInt(saveHero, "talentRemainPoint") ?? 0;
        var requested = Math.Min(remain, Math.Max(0, GetTalentLevelCap(talent) - GetTalentLevel(talent)));
        if (requested <= 0) return 0;
        if (!TrySpendTalentPoints(talentData, saveHero, talent, requested, out var spent))
        {
            if (talentId > 0) failedNodes.Add(talentId);
            return 0;
        }
        return spent;
    }

    private static bool ApplyPreferredBaseSkill(object talentData, object saveHero, PreferredTalentPlan preferred, out string skillName)
    {
        skillName = string.Empty;
        var desiredTalentId = preferred.SkillTalentIds.FirstOrDefault(id => IsBaseSkillDefinition(InvokeStatic("TableData", "getTTalentData", id)));
        if (desiredTalentId <= 0) return false;
        var definition = InvokeStatic("TableData", "getTTalentData", desiredTalentId);
        var skillId = ReadNullableInt(definition, "skillId") ?? 0;
        var skill = skillId > 0 ? InvokeStatic("TableData", "getTSkillData", skillId) : null;
        skillName = Clean(ReadString(skill, "name") ?? EnglishName(skill, $"Skill {skillId}") ?? $"Skill {skillId}");
        var current = ReadNullableInt(saveHero, "baseSkillId") ?? 0;
        var desiredTalent = ReadValues(Read(talentData, "talentDic"))
            .FirstOrDefault(talent => (ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0) == desiredTalentId);
        if (desiredTalent is null)
        {
            Plugin.DiagWarning($"AUTO-SKILLS BASE SKIPPED|talent={desiredTalentId}|reason=base skill is not present in the hero talent grid");
            return false;
        }
        // ResetTalentPoint can leave baseSkillId selected while its saved row is
        // zero. In that state the ID alone is not proof that the native free
        // level was materialized; ChangeBaseSkill must be invoked again.
        if (current == desiredTalentId && GetSavedTalentLevel(desiredTalent) > 0) return false;
        InvokeRequiredInstance(talentData, "ChangeBaseSkill", desiredTalentId);
        var applied = ReadNullableInt(saveHero, "baseSkillId") ?? 0;
        if (applied != desiredTalentId)
            throw new InvalidOperationException($"Base skill change was not applied (wanted talent {desiredTalentId}, got {applied}).");
        if (GetSavedTalentLevel(desiredTalent) < 1)
            throw new InvalidOperationException(
                $"Base skill {desiredTalentId} was selected but its native free saved level was not materialized.");
        return true;
    }

    private static SkillTransformResult TransformMissingPreferredSkills(object hero, object talentData, object townData, PreferredTalentPlan preferred, int reservedBlood, int maxAttempts)
        => MainThreadNativeGateway.Invoke(() => TransformMissingPreferredSkillsCore(
            hero, talentData, townData, preferred, reservedBlood, maxAttempts));

    private static SkillTransformResult TransformMissingPreferredSkillsCore(object hero, object talentData, object townData, PreferredTalentPlan preferred, int reservedBlood, int maxAttempts)
    {
        var desiredTalentRows = preferred.SkillTalentIds
            .Select(id => InvokeStatic("TableData", "getTTalentData", id))
            .Where(IsTransformableSkillDefinition).ToList();
        var desiredTalentIds = desiredTalentRows
            .Select(definition => ReadNullableInt(definition, "id") ?? 0)
            .Where(id => id > 0).Distinct().ToList();
        var desiredSkillIds = desiredTalentRows
            .Select(definition => ReadNullableInt(definition, "skillId") ?? 0)
            .Where(id => id > 0).Distinct().ToHashSet();
        if (desiredSkillIds.Count == 0 || maxAttempts <= 0)
            return new SkillTransformResult(0, 0, 0, 0, string.Empty, true);

        var current = GetTransformableTalents(talentData).ToList();
        var unlockedSlots = current.Count(talent => !IsTalentLockedRequired(talent));
        var originalFixedTalentIds = current
            .Where(IsTalentFixedRequired)
            .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
            .Where(id => id > 0).ToHashSet();
        var fixedUnwanted = current.Count(talent =>
        {
            var definition = Read(talent, "tTalentData");
            var skillId = ReadNullableInt(definition, "skillId") ?? 0;
            return !IsTalentLockedRequired(talent)
                   && IsTalentUnreplaceable(talent) && !desiredSkillIds.Contains(skillId);
        });
        var target = Math.Min(desiredSkillIds.Count, Math.Max(0, unlockedSlots - fixedUnwanted));
        var matched = CountPreferredTransformedSkills(current, desiredSkillIds);
        if (target <= 0 || matched >= target)
            return new SkillTransformResult(0, matched, target, 0, string.Empty, true);

        var shrineType = CreateEnum("EHouseType", 101);
        var shrineHouseData = shrineType is null ? null : InvokeInstance(townData, "GetHouse", shrineType);
        var shrineHouse = Read(shrineHouseData, "houseShrineData");
        var washData = Read(shrineHouse, "shrineWashData");
        var houseData = Read(shrineHouse, "houseData");
        if (washData is null || houseData is null)
            return new SkillTransformResult(0, matched, target, 0, "shrine unavailable", true);
        if (ReadBool(InvokeRequiredInstance(houseData, "IsLock")))
            return new SkillTransformResult(0, matched, target, 0, "shrine is locked", true);

        var bloodType = CreateEnum("EResType", 2) ?? throw new InvalidOperationException("Blood resource type is unavailable.");
        var bloodBefore = Convert.ToInt32(InvokeRequiredInstance(townData, "GetRes", bloodType) ?? throw new InvalidOperationException("Blood amount is unavailable."), CultureInfo.InvariantCulture);
        var previousSelectedHero = Read(houseData, "selectHeroData");
        var likeSnapshot = ReadTalentLikesRequired(townData);
        var attempts = 0;
        var note = string.Empty;
        var cleanupSucceeded = true;
        var executionSucceeded = true;
        try
        {
            Write(houseData, "selectHeroData", hero);
            if (!SameHeroIdentity(Read(houseData, "selectHeroData"), hero))
                throw new InvalidOperationException("The shrine could not select the target hero for skill transformation.");
            for (; attempts < maxAttempts;)
            {
                ReportAutoBuildProgress(
                    AutoBuildStep.ApplyingSkills,
                    attempts,
                    maxAttempts,
                    UiText.L("스킬 변환", "Transforming skills", "转换技能", "轉換技能"),
                    writeRuntimeProgress: false);
                current = GetTransformableTalents(talentData).ToList();
                foreach (var talent in current)
                {
                    var definition = Read(talent, "tTalentData");
                    var talentId = ReadNullableInt(definition, "id") ?? 0;
                    var skillId = ReadNullableInt(definition, "skillId") ?? 0;
                    // During Auto Build, fixed is only a roll preference. Keep
                    // locked rows untouched, unlock unwanted replaceable rows,
                    // and temporarily fix the requested rows for this roll.
                    var shouldFix = IsTalentLockedRequired(talent)
                        ? originalFixedTalentIds.Contains(talentId)
                        : !IsTalentAlienRequired(talent) && desiredSkillIds.Contains(skillId);
                    var isFixed = IsTalentFixedRequired(talent);
                    if (talentId > 0 && shouldFix != isFixed)
                        InvokeRequiredInstance(talentData, "SetTalentWashFixed", talentId, shouldFix);
                }

                matched = CountPreferredTransformedSkills(current, desiredSkillIds);
                if (matched >= target) break;
                var currentSkillIds = current
                    .Where(talent => !IsTalentLockedRequired(talent))
                    .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "skillId") ?? 0)
                    .Where(id => id > 0).ToHashSet();
                var missingTalentIds = desiredTalentRows
                    .Where(row => !currentSkillIds.Contains(ReadNullableInt(row, "skillId") ?? 0))
                    .Select(row => ReadNullableInt(row, "id") ?? 0)
                    .Where(id => id > 0).Distinct().ToList();
                // Target exactly one missing skill per roll. Native favorites are
                // weighted rather than guaranteed, but this proves the selected
                // missing row is actually in the shrine's live target list before
                // any Blood is spent and rotates to the next row once it appears.
                var rollTargetTalentIds = missingTalentIds.Take(1).ToList();
                try
                {
                    var appliedLikes = ApplyTemporaryTalentLikes(townData, rollTargetTalentIds);
                    var liveLikeIds = ReadTalentLikesRequired(townData);
                    if (rollTargetTalentIds.Count > 0
                        && (appliedLikes <= 0 || !rollTargetTalentIds.All(liveLikeIds.Contains)))
                        note = AppendTransformNote(
                            note,
                            "recommended-skill preference unavailable; continued with normal shrine odds");
                }
                catch (Exception error)
                {
                    note = AppendTransformNote(
                        note,
                        "recommended-skill preference unavailable; continued with normal shrine odds");
                    Plugin.DiagWarning($"AUTO-SKILLS LIKES OPTIONAL|{error.GetBaseException().Message}");
                }
                if (!ReadBool(InvokeRequiredInstance(washData, "IsCanWashHero")))
                {
                    note = "no transformable unlocked skill row";
                    break;
                }
                var price = Convert.ToInt32(InvokeRequiredInstance(washData, "GetWashPrice") ?? 0, CultureInfo.InvariantCulture);
                var blood = Convert.ToInt32(InvokeRequiredInstance(townData, "GetRes", bloodType) ?? throw new InvalidOperationException("Blood amount is unavailable."), CultureInfo.InvariantCulture);
                if (price < 0 || blood < price + reservedBlood)
                {
                    note = "not enough Blood after reserving the reset cost";
                    break;
                }
                var result = Convert.ToInt32(InvokeRequiredInstance(washData, "WashHero") ?? 1, CultureInfo.InvariantCulture);
                if (result != 0)
                {
                    note = $"shrine transform returned code {result}";
                    break;
                }
                var bloodAfterRoll = Convert.ToInt32(InvokeRequiredInstance(townData, "GetRes", bloodType)
                                                     ?? throw new InvalidOperationException("Blood amount is unavailable after shrine transformation."), CultureInfo.InvariantCulture);
                if (blood - bloodAfterRoll != price)
                {
                    executionSucceeded = false;
                    note = AppendTransformNote(note, $"shrine transform cost verification failed ({blood - bloodAfterRoll}/{price})");
                    break;
                }
                attempts++;
                ReportAutoBuildProgress(
                    AutoBuildStep.ApplyingSkills,
                    attempts,
                    maxAttempts,
                    UiText.L("스킬 변환", "Transforming skills", "转换技能", "轉換技能"),
                    writeRuntimeProgress: false);
            }
            current = GetTransformableTalents(talentData).ToList();
            matched = CountPreferredTransformedSkills(current, desiredSkillIds);
            if (matched < target && string.IsNullOrWhiteSpace(note) && attempts >= maxAttempts)
                note = "maximum transform attempts reached";
        }
        catch (Exception error)
        {
            executionSucceeded = false;
            note = AppendTransformNote(note, $"transform error: {error.GetBaseException().Message}");
            Plugin.DiagWarning($"AUTO-SKILLS TRANSFORM THREW|attempts={attempts}|matched={matched}/{target}|{error.GetBaseException().Message}");
        }
        finally
        {
            // Temporary locks only guide this automatic run. Preserve an
            // original fixed preference only when that same row remains part of
            // the selected build; an excluded row must stay resettable.
            foreach (var talent in GetTransformableTalents(talentData))
            {
                try
                {
                    var talentId = ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0;
                    var shouldFix = originalFixedTalentIds.Contains(talentId)
                                    && desiredTalentIds.Contains(talentId);
                    var isFixed = IsTalentFixedRequired(talent);
                    if (talentId > 0 && shouldFix != isFixed)
                        InvokeRequiredInstance(talentData, "SetTalentWashFixed", talentId, shouldFix);
                }
                catch (Exception error)
                {
                    cleanupSucceeded = false;
                    note = AppendTransformNote(note, "temporary fixed-skill state could not be fully restored");
                    Plugin.DiagWarning($"AUTO-SKILLS FIXED RESTORE FAILED|{error.GetBaseException().Message}");
                }
            }
            var restoredFixedTalentIds = GetTransformableTalents(talentData)
                .Where(IsTalentFixedRequired)
                .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var survivingTalentIds = GetTransformableTalents(talentData)
                .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var expectedRestoredFixedTalentIds = originalFixedTalentIds
                .Where(desiredTalentIds.Contains)
                .Where(survivingTalentIds.Contains).ToHashSet();
            if (!restoredFixedTalentIds.SetEquals(expectedRestoredFixedTalentIds))
            {
                cleanupSucceeded = false;
                note = AppendTransformNote(note, "temporary fixed-skill state could not be fully restored");
                Plugin.DiagWarning($"AUTO-SKILLS FIXED RESTORE MISMATCH|expected={string.Join(',', expectedRestoredFixedTalentIds)}|actual={string.Join(',', restoredFixedTalentIds)}");
            }
            try { RestoreTalentLikes(townData, likeSnapshot); }
            catch (Exception error)
            {
                cleanupSucceeded = false;
                note = AppendTransformNote(note, "skill preferences could not be fully restored");
                Plugin.DiagWarning($"AUTO-SKILLS LIKES RESTORE FAILED|{error.GetBaseException().Message}");
            }
            try
            {
                Write(houseData, "selectHeroData", previousSelectedHero);
                if (!NativeStateEquals(Read(houseData, "selectHeroData"), previousSelectedHero))
                    throw new InvalidOperationException("the previous shrine hero selection did not return");
            }
            catch (Exception error)
            {
                cleanupSucceeded = false;
                note = AppendTransformNote(note, "shrine hero selection could not be restored");
                Plugin.DiagWarning($"AUTO-SKILLS SHRINE HERO RESTORE FAILED|{error.GetBaseException().Message}");
            }
        }

        var spentBlood = -1;
        try
        {
            var bloodAfter = Convert.ToInt32(InvokeRequiredInstance(townData, "GetRes", bloodType)
                                             ?? throw new InvalidOperationException("Blood amount is unavailable after transformation."), CultureInfo.InvariantCulture);
            spentBlood = Math.Max(0, bloodBefore - bloodAfter);
        }
        catch (Exception error)
        {
            executionSucceeded = false;
            note = AppendTransformNote(note, $"transform Blood verification failed: {error.GetBaseException().Message}");
            Plugin.DiagWarning($"AUTO-SKILLS TRANSFORM BLOOD UNKNOWN|{error.GetBaseException().Message}");
        }
        return new SkillTransformResult(attempts, matched, target, spentBlood, note, cleanupSucceeded, executionSucceeded);
    }

    private static List<object> GetTransformableTalents(object talentData)
        => MainThreadNativeGateway.Invoke(() => ReadValues(Read(talentData, "talentDic"))
            .Where(talent => IsTransformableSkillDefinition(Read(talent, "tTalentData")))
            .ToList());

    private static int CountPreferredTransformedSkills(IEnumerable<object> talents, HashSet<int> desiredSkillIds)
        => talents.Where(talent => !IsTalentLockedRequired(talent))
            .Select(talent => ReadNullableInt(Read(talent, "tTalentData"), "skillId") ?? 0)
            .Where(desiredSkillIds.Contains).Distinct().Count();

    private static int ApplyTemporaryTalentLikes(object townData, IReadOnlyCollection<int> desiredTalentIds)
    {
        var codex = Read(townData, "townCodexData");
        if (codex is null) return 0;
        var maxLikes = Math.Max(0, ToInt(InvokeRequiredInstance(codex, "GetLikeTalentMax")));
        if (maxLikes <= 0) return 0;
        var desiredOrdered = desiredTalentIds.Take(maxLikes).Distinct().ToList();
        var desired = desiredOrdered.ToHashSet();
        var current = ReadTalentLikesRequired(townData);
        foreach (var talentId in current.Where(id => !desired.Contains(id)))
            SetTalentLikeState(codex, talentId, false);
        foreach (var talentId in desiredOrdered)
            SetTalentLikeState(codex, talentId, true);
        return ReadTalentLikesRequired(townData).Count(desired.Contains);
    }

    private static void RestoreTalentLikes(object townData, IReadOnlyCollection<int> snapshot)
    {
        var codex = Read(townData, "townCodexData");
        if (codex is null)
        {
            if (snapshot.Count == 0) return;
            throw new InvalidOperationException("Town Codex data is unavailable.");
        }
        var current = ReadTalentLikesRequired(townData);
        foreach (var talentId in current)
            if (!SetTalentLikeState(codex, talentId, false))
                throw new InvalidOperationException($"Could not remove temporary talent preference {talentId}.");
        foreach (var talentId in snapshot)
            if (!SetTalentLikeState(codex, talentId, true))
                throw new InvalidOperationException($"Could not restore talent preference {talentId}.");
        var restored = ReadTalentLikesRequired(townData);
        if (!restored.SequenceEqual(snapshot))
            throw new InvalidOperationException($"Talent preference order mismatch (expected {string.Join(',', snapshot)}, got {string.Join(',', restored)}).");
    }

    private static List<int> ReadTalentLikesRequired(object townData)
    {
        var saveTown = ReadRequiredProperty(townData, "saveTownData")
                       ?? throw new InvalidOperationException("SaveTownData is unavailable.");
        var values = ReadRequiredSequenceProperty(saveTown, "likeTalentList")
            .Select(value => Convert.ToInt32(value, CultureInfo.InvariantCulture)).ToList();
        if (values.Any(id => id <= 0) || values.Distinct().Count() != values.Count)
            throw new InvalidOperationException($"The saved talent preference list is invalid ({string.Join(',', values)}).");
        return values;
    }

    private static string AppendTransformNote(string current, string addition)
        => string.IsNullOrWhiteSpace(current) ? addition : $"{current}; {addition}";

    private static string LocalizeTransformNote(string note)
    {
        if (string.IsNullOrWhiteSpace(note)) return string.Empty;
        return string.Join("; ", note.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Select(part => part switch
        {
            "shrine unavailable" => UiText.L("신전을 찾을 수 없음", "shrine unavailable", "无法找到神殿", "找不到神殿"),
            "shrine is locked" => UiText.L("신전이 아직 잠겨 있음", "shrine is locked", "神殿尚未解锁", "神殿尚未解鎖"),
            "no transformable unlocked skill row" => UiText.L("변환 가능한 해금 스킬 칸이 없음", "no transformable unlocked skill row", "没有可转换的已解锁技能栏", "沒有可轉換的已解鎖技能欄"),
            "not enough Blood after reserving the reset cost" => UiText.L("초기화 비용을 남기면 피가 부족함", "not enough Blood after reserving the reset cost", "预留重置费用后鲜血不足", "保留重設費用後鮮血不足"),
            "recommended-skill preferences could not be applied" => UiText.L("추천 스킬 선호 설정을 적용할 수 없음", "recommended-skill preferences could not be applied", "无法应用推荐技能偏好", "無法套用推薦技能偏好"),
            "recommended-skill preferences unavailable" => UiText.L("추천 스킬 선호 기능을 사용할 수 없어 일반 확률로 진행", "recommended-skill preferences unavailable; using normal odds", "推荐技能偏好不可用，按普通概率继续", "推薦技能偏好不可用，按一般機率繼續"),
            "maximum transform attempts reached" => UiText.L("최대 변환 횟수에 도달함", "maximum transform attempts reached", "已达到最大转换次数", "已達到最大轉換次數"),
            "temporary fixed-skill state could not be fully restored" => UiText.L("임시 고정 상태 일부를 복구하지 못함", "temporary fixed-skill state could not be fully restored", "部分临时锁定状态未能恢复", "部分臨時鎖定狀態未能復原"),
            "skill preferences could not be fully restored" => UiText.L("스킬 선호 목록 일부를 복구하지 못함", "skill preferences could not be fully restored", "部分技能偏好未能恢复", "部分技能偏好未能復原"),
            "shrine hero selection could not be restored" => UiText.L("신전 영웅 선택을 복구하지 못함", "shrine hero selection could not be restored", "未能恢复神殿英雄选择", "未能復原神殿英雄選擇"),
            _ => part
        }));
    }

    private static bool SetTalentLikeState(object codex, int talentId, bool liked)
    {
        var showTalent = InvokeRequiredStaticMany("ShowTalentData", "Create", talentId, true)
                         ?? throw new InvalidOperationException($"ShowTalentData {talentId} could not be created.");
        var current = ReadBool(InvokeRequiredInstance(codex, "IsLikeTalent", showTalent));
        if (current == liked) return true;
        InvokeRequiredInstance(codex, "SetLikeTalent", showTalent);
        return ReadBool(InvokeRequiredInstance(codex, "IsLikeTalent", showTalent)) == liked;
    }

    private static bool SameHeroIdentity(object? left, object? right)
    {
        if (NativeEquals(left, right)) return true;
        var leftId = ReadNullableInt(Read(left, "saveHeroData"), "uniqueId") ?? 0;
        var rightId = ReadNullableInt(Read(right, "saveHeroData"), "uniqueId") ?? 0;
        return leftId > 0 && leftId == rightId;
    }

    private static HeroEffectProfile BuildHeroEffectProfile(object hero, HeroFocus focus)
    {
        // Skill selection and the profile snapshot both walk the same immutable
        // native talent/skill graph. Keep the complete read-only transaction in
        // one Unity-thread job: executing BuildPlannedSkillTarget on the worker
        // made every small reflection read wait for a later rendered frame and
        // could spend most of a 60-second search budget before gear comparison
        // began. The managed beam search still runs off the main thread.
        return MainThreadNativeGateway.Invoke(() =>
        {
            var planned = BuildPlannedSkillTarget(hero, focus);
            return BuildProfileForSkillSelection(
                hero,
                focus,
                planned,
                planned.BaseSkillId,
                planned.ActiveSkillIds,
                planned.BaseSkillLevel,
                null,
                null,
                "planned baseline");
        });
    }

    private static string GetJointSkillPlanHeroKey(object hero)
    {
        var uniqueId = ReadNullableInt(Read(hero, "saveHeroData"), "uniqueId") ?? 0;
        return uniqueId > 0 ? $"hero:{uniqueId}" : NativeObjectKey(hero, hero);
    }

    private static string GetCurrentGearFingerprint(object hero)
        => string.Join("|", GetGearSlots().Select(slot =>
        {
            var item = GetEquippedItem(hero, slot.Part, slot.MainWeapon);
            return item is null
                ? $"{slot.Part}:{slot.MainWeapon}:empty"
                : $"{slot.Part}:{slot.MainWeapon}:{NativeObjectKey(item, item)}";
        }));

    private static Dictionary<int, int> GetCurrentGrantedSkillLevels(object hero)
    {
        const string prefix = "extra-skill:";
        return GetGearSlots()
            .Select(slot => GetEquippedItem(hero, slot.Part, slot.MainWeapon))
            .Where(item => item is not null).Cast<object>()
            .DistinctBy(item => NativeObjectKey(item, item))
            .SelectMany(GetGrantedExtraSkillLevels)
            .Select(entry =>
            {
                var skillId = entry.Key.StartsWith(prefix, StringComparison.Ordinal)
                              && int.TryParse(entry.Key[prefix.Length..], NumberStyles.Integer,
                                  CultureInfo.InvariantCulture, out var parsed)
                    ? parsed
                    : 0;
                return (SkillId: skillId, Level: entry.Value);
            })
            .Where(entry => entry.SkillId > 0 && entry.Level > 0)
            .GroupBy(entry => entry.SkillId)
            .ToDictionary(group => group.Key, group => group.Max(entry => entry.Level));
    }

    private static void RememberJointSkillPlan(object hero, HeroEffectProfile profile)
    {
        if (profile.PreviewBaseSkillId <= 0) return;
        JointSkillPlansByHero[GetJointSkillPlanHeroKey(hero)] = new RememberedJointSkillPlan(
            profile.Focus.Key,
            profile.PreviewBaseSkillId,
            // Equipment-granted extra skills belong to the evaluated combat
            // package, but never to the shrine transformation/save plan.
            profile.PlannedSkills.ActiveSkillIds
                .Where(id => id > 0 && id != profile.PreviewBaseSkillId).ToHashSet(),
            GetCurrentGrantedSkillLevels(hero),
            profile.PlannedSkills.MasteryTalentIds
                .Where(id => id > 0 && profile.PlannedSkills.TargetSavedLevels.GetValueOrDefault(id) > 0)
                .ToHashSet(),
            new Dictionary<int, int>(profile.PlannedSkills.TargetSavedLevels),
            profile.PlannedSkills.TotalTalentPointBudget,
            profile.PlannedSkills.PlanToken,
            GetCurrentGearFingerprint(hero),
            GetSkillStateFingerprint(hero),
            profile.JointSkillReason,
            profile.PlannedSkills.RequiredBaseSkillIds?.ToHashSet() ?? new HashSet<int>(),
            profile.PlannedSkills.RequiredActiveSkillIds?.ToHashSet() ?? new HashSet<int>(),
            profile.PlannedSkills.ThemePackageSkillIds?.ToHashSet() ?? new HashSet<int>(),
            profile.PlannedSkills.RequiredThemeSkillCount);
    }

    private static List<object> GetHeroSkillTalentRows(object hero)
    {
        var jobId = ReadNullableInt(Read(hero, "saveHeroData"), "jobId") ?? 0;
        // The live grid is authoritative for acquired cross-job/Alien rows.
        // The job catalog only supplies legal transformations not rolled yet.
        // Equipment-granted extraTalentList entries are deliberately excluded:
        // those are combat sources, not saved talent-point/wash destinations.
        var ownedRows = ReadValues(Read(Read(hero, "heroTalentData"), "talentDic"))
            .Select(talent => Read(talent, "tTalentData"))
            .Where(row => row is not null).Cast<object>();
        return ownedRows.Concat(ReadValues(ReadStatic("TableData", "TTalentDict"))
                .Where(row => (ReadNullableInt(row, "jobId") ?? 0) == jobId))
            .Where(row => IsBaseSkillDefinition(row) || IsTransformableSkillDefinition(row))
            .Where(row => (ReadNullableInt(row, "id") ?? 0) > 0)
            .DistinctBy(row => ReadNullableInt(row, "id") ?? 0)
            .ToList();
    }

    private static PreferredTalentPlan ApplyRememberedJointSkillPlan(
        object hero,
        HeroFocus focus,
        PreferredTalentPlan preferred)
    {
        var cacheKey = GetJointSkillPlanHeroKey(hero);
        if (!JointSkillPlansByHero.TryGetValue(cacheKey, out var remembered)
            || remembered.FocusKey != focus.Key) return preferred;
        if (!string.Equals(remembered.GearFingerprint, GetCurrentGearFingerprint(hero), StringComparison.Ordinal)
            || !string.Equals(remembered.SkillFingerprint, GetSkillStateFingerprint(hero), StringComparison.Ordinal))
        {
            JointSkillPlansByHero.Remove(cacheKey);
            return preferred;
        }
        var rows = GetHeroSkillTalentRows(hero);
        var baseTalentId = rows.Where(IsBaseSkillDefinition)
            .Where(row => (ReadNullableInt(row, "skillId") ?? 0) == remembered.BaseSkillId)
            .Select(row => ReadNullableInt(row, "id") ?? 0)
            .FirstOrDefault(id => id > 0 && remembered.TargetSavedLevels.GetValueOrDefault(id) > 0);
        var activeTalentIds = remembered.ActiveSkillIds.Select(skillId => rows
                .Where(IsTransformableSkillDefinition)
                .Where(row => (ReadNullableInt(row, "skillId") ?? 0) == skillId)
                .Select(row => ReadNullableInt(row, "id") ?? 0)
                .FirstOrDefault(id => id > 0 && remembered.TargetSavedLevels.GetValueOrDefault(id) > 0))
            .Where(id => id > 0).Distinct().ToList();
        // Every remembered learned skill must have a real saved-grid destination.
        // Granted skills are stored separately and do not enter this mapping.
        if (baseTalentId <= 0 || activeTalentIds.Count != remembered.ActiveSkillIds.Count)
        {
            JointSkillPlansByHero.Remove(GetJointSkillPlanHeroKey(hero));
            return preferred;
        }
        var skillTalentIds = new[] { baseTalentId }.Concat(activeTalentIds).ToList();
        return preferred with
        {
            SkillTalentIds = skillTalentIds,
            MasteryTalentIds = remembered.MasteryTalentIds.OrderBy(id => id).ToList(),
            PreferredSkillIds = remembered.ActiveSkillIds
                .Concat(remembered.GrantedSkillLevels.Keys)
                .Append(remembered.BaseSkillId).ToHashSet(),
            BuildName = $"{preferred.BuildName} · joint gear plan",
            TargetSavedLevels = new Dictionary<int, int>(remembered.TargetSavedLevels),
            PlanToken = remembered.PlanToken,
            RequiredBaseSkillIds = remembered.RequiredBaseSkillIds.ToHashSet(),
            RequiredActiveSkillIds = remembered.RequiredActiveSkillIds.ToHashSet(),
            ThemePackageSkillIds = remembered.ThemePackageSkillIds.ToHashSet(),
            RequiredThemeSkillCount = remembered.RequiredThemeSkillCount
        };
    }

    private static PreferredTalentPlan ApplyCurrentGearJointSkillPlan(
        object hero,
        HeroFocus focus,
        PreferredTalentPlan preferred)
    {
        var baseline = BuildHeroEffectProfile(hero, focus);
        var currentItems = GetGearSlots()
            .Select(slot => GetEquippedItem(hero, slot.Part, slot.MainWeapon))
            .Where(item => item is not null).Cast<object>()
            .DistinctBy(item => NativeObjectKey(item, item))
            .ToList();
        if (currentItems.Count == 0) return preferred;

        var candidates = currentItems
            .Select(item => DescribeItem(
                item,
                UiText.L("현재 착용", "Equipped", "当前装备", "目前裝備"),
                StorageKind.Inventory,
                StorageSource.Equipped))
            .Select(record => CreateGearCandidate(record, hero, baseline))
            .Where(candidate => candidate is not null).Cast<GearCandidate>()
            .ToList();
        if (candidates.Count != currentItems.Count)
            throw new InvalidOperationException("Current equipment could not be converted to a complete joint-evaluation candidate set.");

        var evaluation = EvaluateCompleteLoadout(candidates, hero, baseline, currentItems, true, true);
        if (!evaluation.IsValid)
            throw new InvalidOperationException($"Current-equipment joint preview failed: {evaluation.Failure}");
        if (evaluation.Profile.Focus.Key != focus.Key)
            throw new InvalidOperationException("The selected hero theme changed during current-equipment evaluation.");
        RememberJointSkillPlan(hero, evaluation.Profile);
        return ApplyRememberedJointSkillPlan(hero, focus, preferred);
    }

    private static HeroEffectProfile BuildProfileForSkillSelection(
        object hero,
        HeroFocus focus,
        PlannedSkillTarget planned,
        int baseSkillId,
        IEnumerable<int> activeSkillIds,
        int baseSkillLevel,
        object? previewAttr,
        IEnumerable<GearCandidate>? candidateItems,
        string reason)
    {
        var heroSave = Read(hero, "saveHeroData");
        var jobRow = Read(hero, "tHeroJobData");
        var jobId = ReadNullableInt(heroSave, "jobId") ?? ReadNullableInt(jobRow, "id") ?? 0;
        var allowedWeapons = ReadSequence(Read(jobRow, "baseWeaponTypeArr"))
            .Select(ToInt).Where(value => value > 0).ToHashSet();
        var selectedActive = activeSkillIds.Where(id => id > 0).Distinct().ToHashSet();
        var selectedSkills = selectedActive.Append(baseSkillId).Where(id => id > 0).ToHashSet();
        var skillInfoIds = new HashSet<int>();
        var talentIds = new HashSet<int>();
        var masteryIds = new HashSet<int>();
        var terms = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var baseWeaponRequirement = new HashSet<int>();
        var skillWeaponPreferences = new List<HashSet<int>>();
        var activeSkillMainType = 0;
        var activeSkillTags = new HashSet<int>();

        void AddTerm(string? value)
        {
            var cleaned = Clean(value ?? string.Empty).ToLowerInvariant();
            if (cleaned.Length >= 2 && cleaned.Length <= 80) terms.Add(cleaned);
        }

        foreach (var skillId in selectedSkills.OrderBy(id => id == baseSkillId ? 0 : 1).ThenBy(id => id))
        {
            var row = InvokeStatic("TableData", "getTSkillData", skillId);
            if (row is null) continue;
            var infoId = ReadNullableInt(row, "infoId") ?? 0;
            var info = infoId > 0 ? InvokeStatic("TableData", "getTSkillInfoData", infoId) : null;
            if (infoId > 0) skillInfoIds.Add(infoId);
            var required = ReadSequence(Read(row, "weaponArr")).Select(ToInt).Where(value => value > 0).ToHashSet();
            try
            {
                var previewInfo = info;
                if (skillId == baseSkillId)
                {
                    baseWeaponRequirement.UnionWith(required);
                    var attr = previewAttr ?? Read(hero, "attrData");
                    var preview = attr is null ? null : InvokeStaticMany("SkillData", "CreatePreview", skillId, Math.Max(1, baseSkillLevel), attr);
                    if (preview is not null && candidateItems is not null && CandidateEnablesSkillVariant(candidateItems, skillId))
                        InvokeRequiredInstance(preview, "SetVariant", true);
                    previewInfo = Read(preview, "tSkillInfoData") ?? info;
                    activeSkillMainType = ReadNullableInt(preview, "skillMainType") ?? ReadNullableInt(row, "type") ?? 0;
                }
                activeSkillTags.UnionWith(ReadSequence(Read(previewInfo, "tagArr"))
                    .Select(ToInt).Where(value => value > 0));
            }
            catch
            {
                if (skillId == baseSkillId)
                    activeSkillMainType = ReadNullableInt(row, "type") ?? 0;
                activeSkillTags.UnionWith(ReadSequence(Read(info, "tagArr"))
                    .Select(ToInt).Where(value => value > 0));
            }
            if (skillId != baseSkillId && required.Count > 0 && !skillWeaponPreferences.Any(group => group.SetEquals(required)))
            {
                skillWeaponPreferences.Add(required);
            }
            AddTerm(ReadString(row, "name"));
            AddTerm(EnglishName(row, string.Empty));
        }

        foreach (var row in ReadValues(ReadStatic("TableData", "TTalentDict")))
        {
            var talentId = ReadNullableInt(row, "id") ?? 0;
            var skillId = ReadNullableInt(row, "skillId") ?? 0;
            if (selectedSkills.Contains(skillId) || planned.MasteryTalentIds.Contains(talentId))
            {
                if (talentId > 0) talentIds.Add(talentId);
                var masteryId = ReadNullableInt(row, "masteryId") ?? 0;
                if (masteryId > 0) masteryIds.Add(masteryId);
                AddTerm(ReadString(row, "name"));
                AddTerm(EnglishName(row, string.Empty));
                if (masteryId > 0)
                {
                    var mastery = InvokeStatic("TableData", "getTMasteryData", masteryId);
                    AddTerm(ReadString(mastery, "name"));
                    AddTerm(EnglishName(mastery, string.Empty));
                }
            }
        }

        var controlledEntityKinds = GetNativeControlledEntityKindsForSkillsCore(selectedSkills);
        return new HeroEffectProfile(
            focus,
            jobId,
            allowedWeapons,
            baseWeaponRequirement,
            skillWeaponPreferences,
            activeSkillMainType,
            activeSkillTags,
            controlledEntityKinds,
            baseSkillId,
            Math.Max(1, baseSkillLevel),
            selectedSkills,
            skillInfoIds,
            talentIds,
            masteryIds,
            new HashSet<int>(talentIds),
            new HashSet<int>(selectedSkills),
            new HashSet<int>(masteryIds),
            new HashSet<int>(),
            new HashSet<int>(),
            new HashSet<string>(StringComparer.Ordinal),
            terms.ToArray(),
            planned,
            reason,
            0d);
    }

    private static bool TryReadGearIdentity(
        ItemSearchRecord record,
        object hero,
        HeroEffectProfile profile,
        bool allowExistingEquippedItem,
        out GearIdentity identity)
    {
        identity = null!;
        var equip = Read(record.ItemData, "itemEquipData");
        var definition = Read(equip, "tEquipData");
        var save = Read(record.ItemData, "saveItemData");
        var part = ReadNullableInt(definition, "part") ?? 0;
        if (part is < 1 or > 7) return false;
        var requiredJob = ReadNullableInt(definition, "jobId") ?? 0;
        if (!allowExistingEquippedItem && requiredJob > 0 && requiredJob != profile.JobId) return false;
        var minType = ReadNullableInt(definition, "minType") ?? 0;
        var heroJobRow = Read(hero, "tHeroJobData");
        if (part == 1 && minType > 0)
        {
            if (!allowExistingEquippedItem
                && profile.AllowedWeaponTypes.Count > 0
                && !profile.AllowedWeaponTypes.Contains(minType)) return false;
        }
        else if (part >= 4 && minType > 0)
        {
            var armorType = ReadNullableInt(heroJobRow, "baseArmorType") ?? 0;
            if (!allowExistingEquippedItem && armorType > 0 && armorType != minType) return false;
        }
        var setData = Read(equip, "tEquipSetsData");
        var setJob = ReadNullableInt(setData, "jobId") ?? 0;
        if (!allowExistingEquippedItem && setJob > 0 && setJob != profile.JobId) return false;
        var setId = ReadNullableInt(setData, "id") ?? ReadNullableInt(definition, "setsId") ?? 0;
        var definitionId = ReadNullableInt(definition, "id") ?? 0;
        var quality = record.Quality;
        var level = Math.Max(0, ReadNullableInt(save, "level") ?? 0);
        var forgeLevel = Math.Max(0, ReadNullableInt(save, "forgeLevel") ?? 0);
        var mainAttrValue = Math.Max(0, ReadNullableInt(save, "mainAttrValue") ?? 0);
        var comparedForgeLevel = AutoBuildIncludesForgeBonuses ? forgeLevel : 0;
        var rawPower = mainAttrValue + level * 50d + comparedForgeLevel * 100d + quality * 250d;
        identity = new GearIdentity(
            part, setId, definitionId, minType, quality, level,
            forgeLevel, mainAttrValue, rawPower);
        return true;
    }

    private static GearPrefilterFact? CreateGearPrefilterFact(
        ItemSearchRecord record,
        object hero,
        HeroEffectProfile profile)
    {
        if (!TryReadGearIdentity(record, hero, profile, false, out var identity)) return null;
        var item = record.ItemData;
        var structuralKeys = new HashSet<string>(StringComparer.Ordinal);
        var physical = profile.Focus.Key is "physical" or "bleed";
        var elemental = profile.Focus.Key is "elemental" or "fire" or "ice" or "lightning" or "corrosion";
        var themeSignal = profile.RecommendedEquipmentIds.Contains(identity.DefinitionId) ? 1200d : 0d;
        if (identity.SetId > 0) structuralKeys.Add($"set:{identity.SetId}");

        var definition = Read(Read(item, "itemEquipData"), "tEquipData");
        if (identity.Quality == 8)
        {
            var uniqueSkillAffix = ReadNullableInt(definition, "uniqueSkillAffix") ?? 0;
            structuralKeys.Add(uniqueSkillAffix > 0
                ? $"unique:{uniqueSkillAffix}"
                : $"unique-definition:{identity.DefinitionId}");
        }

        foreach (var rawAffix in CollectEquipmentAffixes(item))
        {
            var save = Read(rawAffix, "saveData") ?? rawAffix;
            var affixId = ReadNullableInt(Read(rawAffix, "tAffixData"), "id")
                          ?? ReadNullableInt(save, "id") ?? 0;
            var affixDefinition = Read(rawAffix, "tAffixData")
                                  ?? (affixId > 0
                                      ? InvokeStatic("TableData", "getTAffixData", affixId)
                                      : null);
            if (affixDefinition is null)
            {
                structuralKeys.Add(affixId > 0
                    ? $"unknown-special:{affixId}"
                    : "unknown-special:unresolved");
                continue;
            }
            var effectType = ReadNullableInt(affixDefinition, "effectType") ?? 0;
            var effectAttrIds = ReadSequence(Read(affixDefinition, "effectParam"))
                .Select(ToInt).Where(id => id > 0).ToList();
            if (effectAttrIds.Contains(248))
            {
                // Chest-only damage must lose the cheap shortlist too; otherwise
                // its extreme stored magnitude can consume a combat candidate
                // slot before the exact evaluator has a chance to reject it.
                themeSignal -= NonCombatTargetAffixPenalty;
            }
            else if (effectType == 1)
            {
                var value = Convert.ToDouble(
                    ReadNullableInt(save, "value") ?? 0,
                    CultureInfo.InvariantCulture);
                foreach (var attrId in effectAttrIds.Where(id => !IsConversionModifierAttribute(id)))
                    themeSignal += value * GetBattleAttrPreScoreWeight(
                        attrId, profile, physical, elemental);
            }

            if (effectType == 4)
            {
                var variantSkillId = GetSkillVariantId(affixDefinition);
                if (profile.PlannedSkills.BaseCandidateSkillIds.Contains(variantSkillId)
                    || profile.PlannedSkills.ActiveCandidateSkillIds.Contains(variantSkillId))
                    themeSignal += 900d;
            }
            else if (effectType == 100)
            {
                var grantedLevel = Math.Max(0, ReadNullableInt(save, "talentLevel") ?? 0);
                var talent = Read(rawAffix, "tTalentData")
                             ?? InvokeStatic("TableData", "getTTalentData",
                                 ReadNullableInt(save, "talentId") ?? 0);
                var grantedSkillId = ReadNullableInt(talent, "skillId") ?? 0;
                if (grantedLevel > 0
                    && (profile.PlannedSkills.BaseCandidateSkillIds.Contains(grantedSkillId)
                    || profile.PlannedSkills.ActiveCandidateSkillIds.Contains(grantedSkillId))
                   )
                    themeSignal += 750d;
            }
            if (effectType is 3 or 4
                || (effectType == 100
                    && Math.Max(0, ReadNullableInt(save, "talentLevel") ?? 0) > 0))
                structuralKeys.Add($"special:{effectType}:{Math.Max(0, affixId)}");
        }

        return new GearPrefilterFact(
            record,
            identity,
            NativeObjectKey(item, record.SourceField ?? item),
            CreateStableGearOrderKey(record, identity),
            structuralKeys,
            themeSignal);
    }

    private static string CreateStableGearOrderKey(
        ItemSearchRecord record,
        GearIdentity identity)
    {
        static string StableText(string? value)
            => Clean(value ?? string.Empty).ToLowerInvariant();

        // Native IL2CPP pointers are valid object identities only for the current
        // process. They are deliberately excluded here so equal-score shortlist
        // and beam decisions remain identical after a game restart. Definition,
        // roll text and persisted numeric values still distinguish materially
        // different items; exact duplicates are interchangeable for evaluation.
        return string.Join("|",
            identity.Part.ToString("D2", CultureInfo.InvariantCulture),
            identity.DefinitionId.ToString("D10", CultureInfo.InvariantCulture),
            identity.SetId.ToString("D10", CultureInfo.InvariantCulture),
            identity.WeaponType.ToString("D6", CultureInfo.InvariantCulture),
            identity.Quality.ToString("D2", CultureInfo.InvariantCulture),
            identity.Level.ToString("D6", CultureInfo.InvariantCulture),
            identity.ForgeLevel.ToString("D6", CultureInfo.InvariantCulture),
            identity.MainAttrValue.ToString("D10", CultureInfo.InvariantCulture),
            identity.RawPower.ToString("R", CultureInfo.InvariantCulture),
            ((int)record.StorageSource).ToString("D2", CultureInfo.InvariantCulture),
            StableText(record.Name),
            StableText(record.AffixSearchText),
            StableText(record.Description));
    }

    private static List<GearPrefilterFact> SelectGearPrefilterFacts(
        IReadOnlyCollection<GearPrefilterFact> facts,
        out int structuralRetained,
        out int structuralRepresentatives)
    {
        var result = new List<GearPrefilterFact>();
        structuralRetained = 0;
        structuralRepresentatives = 0;

        static IOrderedEnumerable<GearPrefilterFact> ByRawPower(IEnumerable<GearPrefilterFact> source)
            => source.OrderByDescending(fact => fact.Identity.RawPower)
                .ThenByDescending(fact => fact.Identity.Level)
                .ThenByDescending(fact => fact.Identity.Quality)
                .ThenBy(fact => fact.StableOrderKey, StringComparer.Ordinal);

        static IOrderedEnumerable<GearPrefilterFact> ByThemeAndPower(IEnumerable<GearPrefilterFact> source)
            => source.OrderByDescending(fact => fact.ThemeSignal)
                .ThenByDescending(fact => fact.Identity.RawPower)
                .ThenByDescending(fact => fact.Identity.Level)
                .ThenBy(fact => fact.StableOrderKey, StringComparer.Ordinal);

        foreach (var partGroup in facts.GroupBy(fact => fact.Identity.Part).OrderBy(group => group.Key))
        {
            var partFacts = partGroup.ToList();
            // Full affix/ability extraction is the expensive stage. Keep a
            // bounded, tag-ranked pool while reserving every structural family
            // below. Two weapon slots need twice the ordinary slot capacity.
            var partLimit = partGroup.Key == 1 ? 28 : 14;
            const int perLane = 1;
            var selected = new Dictionary<string, GearPrefilterFact>(StringComparer.Ordinal);
            // Weapon type is a native execution contract for the skill package.
            // Preserve one owned representative of every type before the broad
            // power/theme cut, otherwise a low-stat staff or focus can vanish
            // before an alternate native base skill gets a chance to use it.
            var weaponRepresentatives = partGroup.Key == 1
                ? partFacts.Where(fact => fact.Identity.WeaponType > 0)
                    .GroupBy(fact => fact.Identity.WeaponType)
                    .OrderBy(group => group.Key)
                    .Select(group => ByThemeAndPower(group).First())
                    .ToList()
                : new List<GearPrefilterFact>();
            var representatives = partFacts
                .SelectMany(fact => fact.StructuralKeys.Select(key => (Key: key, Fact: fact)))
                .GroupBy(entry => entry.Key, StringComparer.Ordinal)
                .OrderBy(group => group.Key, StringComparer.Ordinal)
                .SelectMany(group => ByThemeAndPower(group.Select(entry => entry.Fact)).Take(perLane))
                .DistinctBy(fact => fact.Key)
                .OrderByDescending(fact => fact.StructuralKeys.Any(key =>
                    key.StartsWith("unknown-", StringComparison.Ordinal)))
                .ThenByDescending(fact => fact.ThemeSignal)
                .ThenByDescending(fact => fact.Identity.RawPower)
                .ThenBy(fact => fact.StableOrderKey, StringComparer.Ordinal)
                .ToList();
            structuralRepresentatives += weaponRepresentatives.Count + representatives.Count;
            foreach (var fact in weaponRepresentatives.Take(partLimit))
                selected.TryAdd(fact.Key, fact);
            foreach (var fact in representatives.Take(partLimit))
            {
                if (selected.Count >= partLimit) break;
                selected.TryAdd(fact.Key, fact);
            }
            structuralRetained += selected.Count;

            var themeQuota = partGroup.Key == 1 ? 14 : 7;
            var rawQuota = partGroup.Key == 1 ? 12 : 6;
            var levelQuota = partGroup.Key == 1 ? 6 : 3;
            var qualityQuota = partGroup.Key == 1 ? 6 : 3;
            var remainder = ByThemeAndPower(partFacts).Take(themeQuota)
                .Concat(ByRawPower(partFacts).Take(rawQuota))
                .Concat(partFacts.OrderByDescending(fact => fact.Identity.Level)
                    .ThenByDescending(fact => AutoBuildIncludesForgeBonuses
                        ? fact.Identity.ForgeLevel
                        : 0)
                    .ThenByDescending(fact => fact.Identity.RawPower)
                    .ThenBy(fact => fact.StableOrderKey, StringComparer.Ordinal)
                    .Take(levelQuota))
                .Concat(partFacts.OrderByDescending(fact => fact.Identity.Quality)
                    .ThenByDescending(fact => fact.Identity.RawPower)
                    .ThenBy(fact => fact.StableOrderKey, StringComparer.Ordinal)
                    .Take(qualityQuota))
                .Concat(ByRawPower(partFacts));
            foreach (var fact in remainder)
            {
                if (selected.Count >= partLimit) break;
                selected.TryAdd(fact.Key, fact);
            }
            result.AddRange(selected.Values);
        }
        return result;
    }

    private static GearCandidate? CreateGearCandidate(
        ItemSearchRecord record,
        object hero,
        HeroEffectProfile profile,
        bool allowExistingEquippedItem = false)
    {
        if (!TryReadGearIdentity(
                record,
                hero,
                profile,
                allowExistingEquippedItem,
                out var identity)) return null;
        var part = identity.Part;
        var setId = identity.SetId;
        var definitionId = identity.DefinitionId;
        var minType = identity.WeaponType;
        var rawPower = identity.RawPower;
        var score = ScoreEquipment(
            record.ItemData, profile, EffectRelevanceScope.SelectableJointPlan);
        var numericScore = EstimateEquipmentNumericScore(
            record.ItemData, profile, EffectRelevanceScope.SelectableJointPlan);
        var nonStackingEffectKeys = GetNonStackingEffectKeys(record.ItemData);
        var selectableContributions = GetDeduplicatedEffectContributions(
            record.ItemData, profile, EffectRelevanceScope.SelectableJointPlan).ToList();
        var selectableGrantedSkills = GetRelevantGrantedExtraSkillLevels(
                record.ItemData, profile, EffectRelevanceScope.SelectableJointPlan)
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var selectableVariantIds = GetRelevantItemSkillVariantIds(
                record.ItemData, profile, EffectRelevanceScope.SelectableJointPlan)
            .ToList();
        var selectableAbilityIds = GetRelevantItemNativeAbilityIds(
                record.ItemData, profile, EffectRelevanceScope.SelectableJointPlan)
            .ToList();
        var relevantHardExclusiveKeys = GetRelevantHardExclusiveEffectKeys(
            record.ItemData,
            nonStackingEffectKeys,
            profile);
        var selectableFacts = new SelectableGearFacts(
            selectableContributions,
            selectableGrantedSkills,
            selectableVariantIds,
            selectableAbilityIds,
            part == 1 && record.Quality is 4 or 5
                ? GetLegendMythWeaponFamily(record.ItemData, definitionId, record.Quality)
                : new HashSet<int>(),
            relevantHardExclusiveKeys);
        var rawScore = score.Total + numericScore * 0.08d;
        var deduplicatedScore = ScoreSingleItemWithDeduplicatedEffects(
            record.ItemData,
            profile,
            rawScore,
            EffectRelevanceScope.SelectableJointPlan,
            selectableContributions);
        var scoreBreakdown = CreateEquipmentScoreBreakdown(
            score,
            numericScore,
            deduplicatedScore);
        return new GearCandidate(
            record,
            NativeObjectKey(record.ItemData, record.SourceField ?? record.ItemData),
            CreateStableGearOrderKey(record, identity),
            part,
            setId,
            definitionId,
            minType,
            deduplicatedScore,
            numericScore,
            rawPower,
            score.DirectMatches,
            score.ThemeMatches,
            nonStackingEffectKeys,
            selectableFacts,
            scoreBreakdown);
    }

    private static EquipmentScore ScoreEquipment(
        object item,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        var save = Read(item, "saveItemData");
        var equip = Read(item, "itemEquipData");
        var definition = Read(equip, "tEquipData");
        var quality = ReadNullableInt(save, "quality") ?? 0;
        var level = ReadNullableInt(save, "level") ?? 0;
        var forge = AutoBuildIncludesForgeBonuses
            ? ReadNullableInt(save, "forgeLevel") ?? 0
            : 0;
        var main = ReadNullableInt(save, "mainAttrValue") ?? 0;
        // Quality is only a modest prior. The native AttrData simulation and
        // skill-specific effects below should decide the winner, not rarity by
        // itself.
        var qualityWeight = quality switch { 8 => 125d, 6 => 120d, 5 => 115d, 4 => 92d, 3 => 66d, 2 => 38d, _ => quality * 12d };
        var descriptions = new List<string>();
        var directMatches = 0;
        var behaviorScore = 0d;
        var activeSpecialEffectCount = 0;
        var inactiveSpecialEffects = new List<string>();
        var definitionId = ReadNullableInt(definition, "id") ?? 0;
        var runewordAffix = GetRunewordAffix(item) is { } rawRuneword ? ResolveRuntimeAffix(rawRuneword) : null;
        foreach (var affix in CollectEquipmentAffixes(item).Concat(CollectGrantedMasteryAffixes(item)))
        {
            var runtimeAffix = ResolveRuntimeAffix(affix);
            var affixDefinition = Read(runtimeAffix, "tAffixData");
            var effectType = ReadNullableInt(affixDefinition, "effectType") ?? 0;
            if (effectType == 100
                && !NativeEquals(runtimeAffix, runewordAffix)) continue;
            var affixText = GetAffixSearchText(runtimeAffix);
            var nonCombatTarget = IsNonCombatTargetAffix(runtimeAffix, affixText);
            // A mismatched skill/variant/ability suppresses only that special
            // component. It must never erase the item's base attributes, ordinary
            // rolls, socket-rune rolls, or other independent affixes.
            var componentRelevant = !nonCombatTarget && (effectType == 1
                                    || IsAffixRelevantToProfile(runtimeAffix, profile, relevanceScope));
            if (nonCombatTarget)
            {
                var affixId = ReadNullableInt(affixDefinition, "id")
                              ?? ReadNullableInt(Read(runtimeAffix, "saveData"), "id") ?? 0;
                inactiveSpecialEffects.Add($"affix#{affixId}/type{effectType}/noncombat-target");
                behaviorScore -= NonCombatTargetAffixPenalty;
                continue;
            }
            if (componentRelevant)
                descriptions.Add(affixText);
            if (IsSpecialAffixEffectType(effectType))
            {
                if (componentRelevant) activeSpecialEffectCount++;
                else
                {
                    inactiveSpecialEffects.Add(DescribeInactiveAffixComponent(
                        runtimeAffix, effectType, profile));
                    // Raw attributes still keep their full native value, but a
                    // skill-specific slot spent on a skill outside the selected
                    // joint package has a real opportunity cost. Apply it only
                    // after the skill package is fixed so the broad shortlist
                    // can still discover alternate skill/equipment pairings.
                    if (relevanceScope == EffectRelevanceScope.SelectedJointPlan)
                        behaviorScore -= InactiveSpecialOpportunityCostPenalty;
                }
            }
            if (componentRelevant)
            {
                directMatches += CountDirectAffixMatches(runtimeAffix, profile, relevanceScope);
                behaviorScore += ScoreAffixBehavior(
                    runtimeAffix, definitionId, profile, affixText, relevanceScope);
            }
        }
        var setId = ReadNullableInt(Read(equip, "tEquipSetsData"), "id")
                    ?? ReadNullableInt(definition, "setsId") ?? 0;
        // Set member flavor/description text must not act as a one-piece set
        // bonus. Individual native affixes and numeric attributes were already
        // included above; set text is scored only after a real wear threshold.
        if (setId <= 0)
            descriptions.Add(Clean(string.Join(" ", ReadString(definition, "des") ?? string.Empty, EnglishText(definition, "_des", string.Empty) ?? string.Empty)));
        var text = string.Join(" ", descriptions).ToLowerInvariant();
        var themeMatches = KeywordScore(text, profile.Focus.Keywords);
        // Text is a small discovery hint only. Skill/variant activation below is
        // decided exclusively from native IDs and native ability metadata.
        var focusBonus = themeMatches * (profile.Focus.IsManual ? 14d : 8d);
        var generalBonus = KeywordScore(text, new[] { "all attack", "all defense", "primary attribute", "crit", "speed", "cost", "resist", "health" }) * 12d;
        if (profile.Focus.Key != "hybrid")
        {
            var priorityRate = GetActiveThemePriority() / 100d;
            // At 50 this is exactly backward compatible. Moving toward zero
            // favors broad native utility; moving toward 100 reserves more of
            // the text-only discovery prior for the chosen theme. Exact native
            // simulation still makes the final decision.
            focusBonus *= priorityRate * 2d;
            generalBonus *= (1d - priorityRate) * 2d;
        }
        // Guide equipment is retained in the shortlist for comparison, but it
        // receives no score bonus. Native stats/effects decide the winner.
        const double guideBonus = 0d;
        // Direct ID matches are retained for reporting and shortlist diversity.
        // Variant/extra-skill effects are already applied by SetVariant and the
        // native granted level, so a flat match bonus would count them twice.
        var baseItemPrior = qualityWeight * 0.2d + level * 0.2d + forge * 0.5d + main * 0.002d;
        var textAffinity = focusBonus + generalBonus + guideBonus;
        var total = baseItemPrior + textAffinity + behaviorScore;
        return new EquipmentScore(
            total,
            directMatches,
            themeMatches,
            baseItemPrior,
            textAffinity,
            behaviorScore,
            activeSpecialEffectCount,
            inactiveSpecialEffects
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Distinct(StringComparer.Ordinal)
                .OrderBy(value => value, StringComparer.Ordinal)
                .ToList());
    }

    private static bool IsSpecialAffixEffectType(int effectType)
        => effectType is 3 or 4 or 100;

    private static bool IsConversionModifierAttribute(int attrId)
        => attrId is >= 700 and <= 712;

    private static bool IsNonCombatTargetAffix(object rawAffix, string? knownText = null)
    {
        var affix = ResolveRuntimeAffix(rawAffix);
        var definition = Read(affix, "tAffixData");
        // EAttrType 248 is the table's Chest-only damage flag. It must not be
        // treated as general combat damage even though its stored magnitude is
        // deliberately enormous.
        if (ReadSequence(Read(definition, "effectParam")).Select(ToInt).Any(id => id == 248))
            return true;
        var text = Clean(knownText ?? GetAffixSearchText(affix)).ToLowerInvariant();
        return text.Contains("damage to chests", StringComparison.Ordinal)
               || text.Contains("damage to chest", StringComparison.Ordinal)
               || text.Contains("chest-only", StringComparison.Ordinal)
               || text.Contains("treasure chest", StringComparison.Ordinal);
    }

    private static EquipmentScoreBreakdown CreateEquipmentScoreBreakdown(
        EquipmentScore equipmentScore,
        double numericScore,
        double finalCandidateScore)
    {
        var weightedStats = numericScore * 0.08d;
        var preDeduplicationTotal = equipmentScore.Total + weightedStats;
        return new EquipmentScoreBreakdown(
            equipmentScore.BaseItemPrior,
            weightedStats,
            equipmentScore.TextAffinity,
            equipmentScore.RelevantSpecialEffects,
            finalCandidateScore - preDeduplicationTotal,
            finalCandidateScore,
            equipmentScore.ActiveSpecialEffectCount,
            equipmentScore.InactiveSpecialEffects);
    }

    private static string DescribeInactiveAffixComponent(
        object rawAffix,
        int effectType,
        HeroEffectProfile profile)
    {
        var affix = ResolveRuntimeAffix(rawAffix);
        var definition = Read(affix, "tAffixData");
        var save = Read(affix, "saveData");
        var affixId = ReadNullableInt(definition, "id") ?? ReadNullableInt(save, "id") ?? 0;
        var talent = Read(affix, "tTalentData")
                     ?? InvokeStatic("TableData", "getTTalentData", ReadNullableInt(save, "talentId") ?? 0);
        var skillIds = new HashSet<int>();
        var explicitSkillId = effectType == 4
            ? GetSkillVariantId(definition)
            : ReadNullableInt(talent, "skillId") ?? 0;
        if (explicitSkillId > 0) skillIds.Add(explicitSkillId);
        skillIds.UnionWith(InferSkillDependenciesFromText(GetAffixSearchText(affix), profile.JobId));
        var dependency = skillIds.Count > 0
            ? $"skill={string.Join("+", skillIds.OrderBy(id => id))}"
            : (ReadNullableInt(talent, "masteryId") ?? 0) is > 0 and var masteryId
                ? $"mastery={masteryId}"
                : "target=unmatched";
        return $"affix#{affixId}/type{effectType}/{dependency}";
    }

    private static bool IsAffixRelevantToProfile(
        object rawAffix,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        var affix = ResolveRuntimeAffix(rawAffix);
        if (IsNonCombatTargetAffix(affix)) return false;
        var definition = Read(affix, "tAffixData");
        var save = Read(affix, "saveData");
        var effectType = ReadNullableInt(definition, "effectType") ?? 0;
        if (effectType == 100
            && Math.Max(0, ReadNullableInt(save, "talentLevel") ?? 0) <= 0)
            return false;
        var talent = Read(affix, "tTalentData")
                     ?? InvokeStatic("TableData", "getTTalentData", ReadNullableInt(save, "talentId") ?? 0);
        var affixJobId = ReadNullableInt(Read(affix, "tHeroJobData"), "id") ?? 0;
        var talentJobId = ReadNullableInt(talent, "jobId") ?? 0;
        if ((affixJobId > 0 && affixJobId != profile.JobId)
            || (talentJobId > 0 && talentJobId != profile.JobId)) return false;

        var talentId = ReadNullableInt(talent, "id") ?? ReadNullableInt(save, "talentId") ?? 0;
        var targetSkillId = effectType == 4
            ? GetSkillVariantId(definition)
            : ReadNullableInt(talent, "skillId") ?? 0;
        var targetMasteryId = ReadNullableInt(talent, "masteryId") ?? 0;
        if (targetSkillId > 0
            && !IsSkillTargetRelevant(
                targetSkillId,
                profile,
                relevanceScope,
                effectType == 100)) return false;
        if (targetMasteryId > 0
            && !IsMasteryTargetRelevant(targetMasteryId, profile, relevanceScope)) return false;
        if (talentId > 0 && targetSkillId <= 0 && targetMasteryId <= 0
            && !IsTalentTargetRelevant(talentId, profile, relevanceScope)) return false;

        if (effectType != 3) return true;
        var abilityId = ReadNullableInt(save, "abilityId")
                        ?? ReadNullableInt(Read(affix, "tAbilityData"), "id")
                        ?? ReadSequence(Read(definition, "effectParam")).Select(ToInt).FirstOrDefault();
        var ability = Read(affix, "tAbilityData") ?? ResolveAbilityTableRow(abilityId, 1);
        return IsNativeAbilityRelevantToProfile(ability, profile, relevanceScope)
               && AreTextSkillDependenciesRelevant(
                   GetAffixSearchText(affix), profile, relevanceScope, ability,
                   targetSkillId > 0 || targetMasteryId > 0 || talentId > 0);
    }

    private static bool IsNativeAbilityRelevantToProfile(
        object? ability,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        if (row is null) return true;

        // Current tables carry most explicit targeting on the owning AffixData.
        // Keep named fields here as a version-tolerant gate for table revisions;
        // opaque typeParam values are intentionally not guessed as IDs.
        var jobId = ReadFirstPositiveInt(row, "jobId", "targetJobId", "heroJobId");
        if (jobId > 0 && jobId != profile.JobId) return false;
        var skillId = ReadFirstPositiveInt(row, "skillId", "targetSkillId", "sourceSkillId");
        if (skillId > 0 && !IsSkillTargetRelevant(skillId, profile, relevanceScope, false)) return false;
        var talentId = ReadFirstPositiveInt(row, "talentId", "targetTalentId");
        if (talentId > 0 && !IsTalentTargetRelevant(talentId, profile, relevanceScope)) return false;
        var masteryId = ReadFirstPositiveInt(row, "masteryId", "targetMasteryId");
        if (masteryId > 0 && !IsMasteryTargetRelevant(masteryId, profile, relevanceScope)) return false;

        var requiredWeapons = new[] { "weaponArr", "weaponTypeArr", "targetWeaponArr" }
            .SelectMany(name => ReadSequence(Read(row, name)).Select(ToInt))
            .Where(id => id > 0).ToHashSet();
        return requiredWeapons.Count == 0 || profile.AllowedWeaponTypes.Count == 0
               || requiredWeapons.Overlaps(profile.AllowedWeaponTypes);
    }

    private static bool AreTextSkillDependenciesRelevant(
        string dependencyText,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope,
        object? ability = null,
        bool hasExplicitTargetMetadata = false)
    {
        var dependencies = InferSkillDependenciesFromText(dependencyText, profile.JobId);
        if (dependencies.Count > 0
            && !dependencies.All(skillId =>
                IsSkillTargetRelevant(skillId, profile, relevanceScope, false)))
            return false;
        var tagDependencies = InferSkillTagDependenciesFromText(dependencyText);
        if (relevanceScope == EffectRelevanceScope.SelectedJointPlan
            && tagDependencies.Any(tag => tag switch
            {
                "totem" => !profile.ControlledEntityKinds.HasFlag(
                    NativeControlledEntityKind.Totem),
                // Native Minion, Ally and Totem are sibling execution kinds.
                // A table-authored [Minion] dependency must not leak into a
                // Hunter Ally or a root-emitter Totem merely because all three
                // are colloquially described as summons.
                "minion" => !profile.ControlledEntityKinds.HasFlag(
                    NativeControlledEntityKind.Minion),
                "ally" => !profile.ControlledEntityKinds.HasFlag(
                    NativeControlledEntityKind.Ally),
                "summon" => (profile.ControlledEntityKinds
                             & (NativeControlledEntityKind.Minion
                                | NativeControlledEntityKind.Ally
                                | NativeControlledEntityKind.OtherSummon)) == 0,
                "mastery-or-utility" => !HasNativeSkillTag(
                    profile.ActiveSkillTags, "mastery", "utility"),
                "shield-producer" => !profile.SkillIds.Any(SkillProducesShieldCore),
                _ => !HasNativeSkillTag(profile.ActiveSkillTags, tag)
            }))
            return false;
        if (dependencies.Count > 0 || tagDependencies.Count > 0) return true;
        if (relevanceScope != EffectRelevanceScope.SelectedJointPlan) return true;

        // An explicit dependency was handled above. With no skill/talent/mastery
        // dependency in either the table row or multilingual description, this
        // ability is skill-plan agnostic: it may be conditional (on hit, kill,
        // low health, and so on), but it is still a global item component rather
        // than a bonus for a different skill. Keep it eligible and let the native
        // preview / conservative conditional scorer decide its value. A missing
        // ability row is unknown and remains zero instead of earning a text-only
        // bonus.
        return hasExplicitTargetMetadata
               || HasExplicitNativeAbilityTargetMetadata(ability)
               || ability is not null;
    }

    private static IReadOnlyList<string> InferSkillTagDependenciesFromText(string source)
    {
        var text = NormalizeSkillDependencyText(source);
        if (text.Length < 2) return Array.Empty<string>();
        var required = new List<string>();
        // Some table-authored conditions reference a native skill category
        // rather than a concrete skill name. For example [Totem] means either
        // Vortex Totem or Windfury Totem; treating the non-matching alias as a
        // global always-on effect substantially overvalues the set.
        if (ContainsDependencyName(text, "totem")) required.Add("totem");
        if (ContainsDependencyName(text, "minion")
            || ContainsDependencyName(text, "minions")
            || Regex.IsMatch(text, @"\bminions?\b", RegexOptions.CultureInvariant))
            required.Add("minion");
        // "All allies gain..." names recipients, not a Hunter Ally source.
        // Only an explicit native category phrase is a controlled-Ally skill
        // dependency; concrete names such as [Frost Wolf Ally] are already
        // resolved by InferSkillDependenciesFromText above.
        if (text.Contains("[ally]", StringComparison.Ordinal)
            || Regex.IsMatch(text,
                @"\b(?:ally|companion) skills?\b",
                RegexOptions.CultureInvariant))
            required.Add("ally");
        if (ContainsDependencyName(text, "summon")
            || ContainsDependencyName(text, "summons"))
            required.Add("summon");
        if (Regex.IsMatch(text, @"\bwarcr(?:y|ies)\b", RegexOptions.CultureInvariant))
            required.Add("warcry");
        if (Regex.IsMatch(text,
                @"\b(?:aura effects?|per aura|for each aura)\b",
                RegexOptions.CultureInvariant))
            required.Add("aura");
        if (Regex.IsMatch(text,
                @"\bwhen (?:you are )?applying (?:a )?debuff\b",
                RegexOptions.CultureInvariant))
            required.Add("debuff");
        var masteryOrUtility = text.Contains("mastery or utility skill", StringComparison.Ordinal)
                               || text.Contains("mastery/utility skill", StringComparison.Ordinal);
        if (masteryOrUtility)
            required.Add("mastery-or-utility");
        else
        {
            if (text.Contains("mastery skill", StringComparison.Ordinal)
                || text.Contains("mastery skills", StringComparison.Ordinal))
                required.Add("mastery");
            if (text.Contains("utility skill", StringComparison.Ordinal)
                || text.Contains("utility skills", StringComparison.Ordinal))
                required.Add("utility");
        }
        if (text.Contains("basic skill", StringComparison.Ordinal)
            || text.Contains("basic skills", StringComparison.Ordinal))
            required.Add("basic");
        if (text.Contains("support skill", StringComparison.Ordinal)
            || text.Contains("support skills", StringComparison.Ordinal))
            required.Add("support");
        if (text.Contains("martial skill", StringComparison.Ordinal)
            || text.Contains("martial skills", StringComparison.Ordinal)
            || Regex.IsMatch(text,
                @"\bmartial (?:speed|accuracy|damage)\b",
                RegexOptions.CultureInvariant))
            required.Add("martial");
        if (text.Contains("spell skill", StringComparison.Ordinal)
            || text.Contains("spell skills", StringComparison.Ordinal)
            || Regex.IsMatch(text,
                @"\bspell (?:speed|accuracy|damage)\b",
                RegexOptions.CultureInvariant))
            required.Add("spell");
        if (text.Contains("aura skill", StringComparison.Ordinal)
            || text.Contains("aura skills", StringComparison.Ordinal))
            required.Add("aura");
        if (text.Contains("affliction skill", StringComparison.Ordinal)
            || text.Contains("affliction skills", StringComparison.Ordinal))
            required.Add("affliction");
        if (text.Contains("while a shield is active", StringComparison.Ordinal)
            || text.Contains("while you have a shield", StringComparison.Ordinal)
            || text.Contains("each time you gain a shield", StringComparison.Ordinal))
            required.Add("shield-producer");
        return required.Distinct(StringComparer.Ordinal).ToList();
    }

    private static bool SkillProducesShieldCore(int skillId)
    {
        if (skillId <= 0) return false;
        var row = InvokeStatic("TableData", "getTSkillData", skillId);
        var infoId = ReadNullableInt(row, "infoId") ?? 0;
        var info = infoId > 0 ? InvokeStatic("TableData", "getTSkillInfoData", infoId) : null;
        var text = NormalizeSkillDependencyText(string.Join(" ",
            ReadString(row, "name"),
            EnglishName(row, string.Empty),
            ReadString(info, "des"),
            EnglishText(info, "_des", string.Empty)));
        if (!text.Contains("shield", StringComparison.Ordinal)
            && !text.Contains("barrier", StringComparison.Ordinal)) return false;
        return text.Contains("gain", StringComparison.Ordinal)
               || text.Contains("grant", StringComparison.Ordinal)
               || text.Contains("apply", StringComparison.Ordinal)
               || text.Contains("generate", StringComparison.Ordinal)
               || text.Contains("create", StringComparison.Ordinal);
    }

    private static bool HasExplicitNativeAbilityTargetMetadata(object? ability)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        return row is not null
               && (ReadFirstPositiveInt(row, "skillId", "targetSkillId", "sourceSkillId") > 0
                   || ReadFirstPositiveInt(row, "talentId", "targetTalentId") > 0
                   || ReadFirstPositiveInt(row, "masteryId", "targetMasteryId") > 0);
    }

    private static bool HasExplicitAffixTargetMetadata(object rawAffix)
    {
        var affix = ResolveRuntimeAffix(rawAffix);
        var definition = Read(affix, "tAffixData");
        var save = Read(affix, "saveData");
        var talent = Read(affix, "tTalentData")
                     ?? InvokeStatic("TableData", "getTTalentData", ReadNullableInt(save, "talentId") ?? 0);
        var effectType = ReadNullableInt(definition, "effectType") ?? 0;
        var skillId = effectType == 4
            ? GetSkillVariantId(definition)
            : ReadNullableInt(talent, "skillId") ?? 0;
        return skillId > 0
               || (ReadNullableInt(talent, "masteryId") ?? 0) > 0
               || (ReadNullableInt(talent, "id") ?? ReadNullableInt(save, "talentId") ?? 0) > 0;
    }

    private static IReadOnlyList<int> InferSkillDependenciesFromText(string source, int jobId)
    {
        var text = NormalizeSkillDependencyText(source);
        if (jobId <= 0 || text.Length < 2) return Array.Empty<int>();
        EnsureSkillDependencyNameCache();
        if (skillDependencyNamesByJob is null
            || !skillDependencyNamesByJob.TryGetValue(jobId, out var candidates))
            return Array.Empty<int>();

        return candidates
            .Where(candidate => candidate.Names.Any(name => ContainsDependencyName(text, name)))
            .Select(candidate => candidate.SkillId)
            .Distinct()
            .OrderBy(id => id)
            .ToList();
    }

    private static IReadOnlyList<int> InferOrderedSkillDependenciesFromText(string source, int jobId)
    {
        var text = NormalizeSkillDependencyText(source);
        if (jobId <= 0 || text.Length < 2) return Array.Empty<int>();
        EnsureSkillDependencyNameCache();
        if (skillDependencyNamesByJob is null
            || !skillDependencyNamesByJob.TryGetValue(jobId, out var candidates))
            return Array.Empty<int>();

        static int FirstIndex(string haystack, string rawName)
        {
            var name = NormalizeSkillDependencyText(rawName);
            if (name.Length < 2) return -1;
            return haystack.IndexOf($"[{name}]", StringComparison.Ordinal);
        }

        return candidates.Select(candidate => new
            {
                candidate.SkillId,
                Index = candidate.Names.Select(name => FirstIndex(text, name))
                    .Where(index => index >= 0).DefaultIfEmpty(-1).Min()
            })
            .Where(entry => entry.Index >= 0)
            .OrderBy(entry => entry.Index)
            .ThenBy(entry => entry.SkillId)
            .Select(entry => entry.SkillId)
            .Distinct()
            .ToList();
    }

    private static bool ContainsDependencyName(string text, string rawName)
    {
        var name = NormalizeSkillDependencyText(rawName);
        if (name.Length < 2) return false;
        var asciiOnly = name.All(character => character <= 0x7f);
        if (asciiOnly && name.Length < 4) return false;
        // Game-authored skill dependencies are bracketed in the localized and
        // English descriptions. Plain prose such as “Lightning Resistance” or
        // “trigger a shockwave” describes an element/effect, not necessarily
        // the Mage skill [Lightning] or [Shockwave]. Requiring an explicit
        // bracketed name avoids those semantic substring collisions.
        return text.Contains($"[{name}]", StringComparison.Ordinal)
               || text.Contains($"［{name}］", StringComparison.Ordinal)
               || text.Contains($"【{name}】", StringComparison.Ordinal);
    }

    private static string NormalizeSkillDependencyText(string? value)
        => new(Clean(value ?? string.Empty)
            .Where(character => CharUnicodeInfo.GetUnicodeCategory(character)
                                != UnicodeCategory.Format)
            .Select(char.ToLowerInvariant)
            .ToArray());

    private static void EnsureSkillDependencyNameCache()
    {
        if (skillDependencyNamesByJob is not null) return;
        var rows = ReadValues(ReadStatic("TableData", "TTalentDict"))
            .Where(row => (ReadNullableInt(row, "jobId") ?? 0) > 0)
            .Where(row => (ReadNullableInt(row, "skillId") ?? 0) > 0)
            .GroupBy(row => new
            {
                JobId = ReadNullableInt(row, "jobId") ?? 0,
                SkillId = ReadNullableInt(row, "skillId") ?? 0
            })
            .ToList();
        if (rows.Count == 0) return;

        skillDependencyNamesByJob = rows
            .GroupBy(group => group.Key.JobId)
            .ToDictionary(job => job.Key, job => job.Select(group =>
            {
                var talentNames = group.SelectMany(row => new[]
                {
                    ReadString(row, "name") ?? string.Empty,
                    EnglishName(row, string.Empty) ?? string.Empty
                });
                var skill = InvokeStatic("TableData", "getTSkillData", group.Key.SkillId);
                var names = talentNames.Concat(new[]
                    {
                        ReadString(skill, "name") ?? string.Empty,
                        EnglishName(skill, string.Empty) ?? string.Empty
                    })
                    .Select(name => Clean(name).ToLowerInvariant())
                    .Where(name => name.Length >= 2)
                    .Distinct(StringComparer.Ordinal)
                    .OrderByDescending(name => name.Length)
                    .ToList();
                return new SkillDependencyName(group.Key.SkillId, names);
            }).Where(entry => entry.Names.Count > 0).ToList());
    }

    private static int ReadFirstPositiveInt(object? source, params string[] names)
    {
        foreach (var name in names)
        {
            var value = ReadNullableInt(source, name) ?? 0;
            if (value > 0) return value;
        }
        return 0;
    }

    private static bool IsSkillTargetRelevant(
        int skillId,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope,
        bool grantedByEquipment)
    {
        if (skillId <= 0) return true;
        var skill = InvokeStatic("TableData", "getTSkillData", skillId);
        if (skill is null) return false;
        var skillJobId = ReadNullableInt(skill, "job") ?? 0;
        if (skillJobId > 0 && skillJobId != profile.JobId && !grantedByEquipment) return false;
        var requiredWeapons = ReadSequence(Read(skill, "weaponArr"))
            .Select(ToInt).Where(id => id > 0).ToHashSet();
        if (requiredWeapons.Count > 0 && profile.AllowedWeaponTypes.Count > 0
            && !requiredWeapons.Overlaps(profile.AllowedWeaponTypes)) return false;

        if (profile.SkillIds.Contains(skillId)) return true;
        if (relevanceScope == EffectRelevanceScope.SelectedJointPlan) return false;
        var selectable = profile.PlannedSkills.BaseCandidateSkillIds
            .Concat(profile.PlannedSkills.ActiveCandidateSkillIds)
            .Concat(profile.PlannedSkills.ActiveSkillIds)
            .Append(profile.PlannedSkills.BaseSkillId)
            .Where(id => id > 0).ToHashSet();
        if (selectable.Contains(skillId)) return true;
        return grantedByEquipment;
    }

    private static bool IsTalentTargetRelevant(
        int talentId,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        if (talentId <= 0) return true;
        var talent = InvokeStatic("TableData", "getTTalentData", talentId);
        var jobId = ReadNullableInt(talent, "jobId") ?? 0;
        if (jobId > 0 && jobId != profile.JobId) return false;
        var skillId = ReadNullableInt(talent, "skillId") ?? 0;
        if (skillId > 0) return IsSkillTargetRelevant(skillId, profile, relevanceScope, false);
        var masteryId = ReadNullableInt(talent, "masteryId") ?? 0;
        if (masteryId > 0) return IsMasteryTargetRelevant(masteryId, profile, relevanceScope);
        if (profile.TalentIds.Contains(talentId) || profile.PreferredTalentIds.Contains(talentId)) return true;
        if (relevanceScope == EffectRelevanceScope.SelectedJointPlan) return false;
        return profile.PlannedSkills.SelectableTalentIds.Contains(talentId);
    }

    private static bool IsMasteryTargetRelevant(
        int masteryId,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        if (masteryId <= 0) return true;
        var mastery = InvokeStatic("TableData", "getTMasteryData", masteryId);
        var jobId = ReadNullableInt(mastery, "jobId") ?? 0;
        if (jobId > 0 && jobId != profile.JobId) return false;
        if (profile.MasteryIds.Contains(masteryId) || profile.PreferredMasteryIds.Contains(masteryId)) return true;
        if (relevanceScope == EffectRelevanceScope.SelectedJointPlan) return false;
        return profile.PlannedSkills.SelectableMasteryIds.Contains(masteryId);
    }

    private static double ScoreAffixBehavior(
        object affix,
        int equipmentId,
        HeroEffectProfile profile,
        string affixText,
        EffectRelevanceScope relevanceScope)
    {
        if (IsNonCombatTargetAffix(affix, affixText))
            return -NonCombatTargetAffixPenalty;
        if (!IsAffixRelevantToProfile(affix, profile, relevanceScope)) return 0d;
        var definition = Read(affix, "tAffixData");
        var effectType = ReadNullableInt(definition, "effectType") ?? 0;
        if (effectType == 1) return 0d; // bodyAttr magnitude is scored numerically.

        var jobId = ReadNullableInt(Read(affix, "tHeroJobData"), "id") ?? 0;
        if (jobId > 0 && jobId != profile.JobId) return -2500d;

        if (effectType == 4)
        {
            // SkillData.SetVariant changes the real native Power/Action preview.
            // The candidate is preserved separately by target skill ID.
            return 0d;
        }

        if (effectType == 100)
        {
            // Native GetSkillList keeps the highest granted level and mastery
            // affixes are previewed directly. No additional flat score belongs
            // here; the source is preserved separately for joint evaluation.
            return 0d;
        }

        if (effectType == 3)
        {
            var ability = Read(affix, "tAbilityData");
            if (ability is null)
            {
                var abilityId = ReadSequence(Read(definition, "effectParam")).Select(ToInt).FirstOrDefault();
                ability = ResolveAbilityTableRow(abilityId, 1);
            }
            var abilityScore = ScoreNativeAbility(ability, profile, relevanceScope);
            var fallbackText = string.IsNullOrWhiteSpace(affixText)
                ? GetAffixSearchText(affix)
                : affixText;
            if (abilityScore <= 0d)
                abilityScore = ScoreOpaqueConditionalEffect(fallbackText, profile);
            if (!HasExplicitNativeAbilityTheme(ability, profile.PlannedSkills))
                abilityScore *= GetOpaqueEffectThemeWeight(fallbackText, profile.Focus);
            return abilityScore;
        }

        return 0d;
    }

    private static object? ResolveAbilityTableRow(int abilityId, int level)
    {
        if (abilityId <= 0) return null;
        var resolved = InvokeStaticMany("AbilityData", "ResolveAbilityTableId", abilityId, Math.Max(0, level));
        var resolvedId = resolved is null ? abilityId : ToInt(resolved);
        return InvokeStatic("TableData", "getTAbilityData", resolvedId)
               ?? InvokeStatic("TableData", "getTAbilityData", abilityId);
    }

    private static bool HasNativeSpecialAbilityHook(int abilityId)
    {
        if (abilityId <= 0) return false;
        return MainThreadNativeGateway.Invoke(() =>
        {
            try
            {
                lock (NativeSpecialAbilityHookSync)
                {
                    if (nativeSpecialAbilityHookIds is not null)
                        return nativeSpecialAbilityHookIds.Contains(abilityId);
                    gameAssembly ??= AppDomain.CurrentDomain.GetAssemblies()
                        .FirstOrDefault(assembly => assembly.GetName().Name == "Assembly-CSharp");
                    var abilitySys = gameAssembly?.GetType("AbilitySys", false, false);
                    // Failure to find the native hook registry is unknown, never
                    // proof that a table ability has no special implementation.
                    // Do not cache that transient failure; Assembly-CSharp may
                    // still be loading during the first UI frame.
                    if (abilitySys is null) return true;
                    var discovered = new HashSet<int>();
                    foreach (var method in abilitySys.GetMethods(
                                 BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static))
                    {
                        var match = Regex.Match(
                            method.Name,
                            @"^CheckAbility_(\d+)(?:_|$)",
                            RegexOptions.CultureInvariant);
                        if (match.Success
                            && int.TryParse(match.Groups[1].Value, NumberStyles.Integer,
                                CultureInfo.InvariantCulture, out var discoveredId)
                            && discoveredId > 0)
                            discovered.Add(discoveredId);
                    }
                    nativeSpecialAbilityHookIds = discovered;
                    return discovered.Contains(abilityId);
                }
            }
            catch
            {
                // Failure to enumerate hooks must never turn an unknown dynamic
                // effect into an invented performance bonus.
                return true;
            }
        });
    }

    private static bool IsStrictAlwaysOnSelfAbility(object ability)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        if (row is null) return false;
        var type = ReadNullableInt(row, "type") ?? 0;
        var effectiveType = ReadNullableInt(row, "effectiveType") ?? 0;
        var resultIds = ReadSequence(Read(row, "resultArr")).Select(ToInt).Where(id => id > 0).ToList();
        var filterCount = ReadSequence(Read(row, "filtArr")).Select(ToInt).Count(id => id > 0);
        var duration = Math.Max(0d, Convert.ToDouble(Read(row, "duration") ?? 0d, CultureInfo.InvariantCulture));
        var cooldown = Math.Max(0d, Convert.ToDouble(Read(row, "cdTime") ?? 0d, CultureInfo.InvariantCulture));
        var stack = Math.Max(0, ReadNullableInt(row, "stack") ?? 0);
        return type is 1 or 4 or 7
               && effectiveType == 3
               && IsUnconditionalAcquireAbility(ability)
               && resultIds.Count > 0 && resultIds[0] == 301
               && filterCount == 0
               && duration <= 0d && cooldown <= 0d && stack <= 1;
    }

    private static bool IsUnconditionalAcquireAbility(object ability)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        if (row is null) return false;
        var abilityId = ReadNullableInt(row, "id") ?? ReadNullableInt(ability, "id") ?? 0;
        var type = ReadNullableInt(row, "type") ?? 0;
        var effectiveType = ReadNullableInt(row, "effectiveType") ?? 0;
        var moments = ReadSequence(Read(row, "moment")).Select(ToInt).Where(id => id > 0).ToHashSet();
        var resultIds = ReadSequence(Read(row, "resultArr")).Select(ToInt).Where(id => id > 0).ToList();
        var filterCount = ReadSequence(Read(row, "filtArr")).Select(ToInt).Count(id => id > 0);
        var duration = Math.Max(0d, Convert.ToDouble(Read(row, "duration") ?? 0d, CultureInfo.InvariantCulture));
        var tick = Math.Max(0d, Convert.ToDouble(Read(row, "tick") ?? 0d, CultureInfo.InvariantCulture));
        var cooldown = Math.Max(0d, Convert.ToDouble(Read(row, "cdTime") ?? 0d, CultureInfo.InvariantCulture));
        var stack = Math.Max(0, ReadNullableInt(row, "stack") ?? 0);
        return abilityId > 0
               && type is 1 or 4 or 7
               && effectiveType == 3
               && moments.SetEquals(new[] { 1 })
               && Clean(ReadString(row, "condition") ?? string.Empty).Length == 0
               && !ReadSequence(Read(row, "monitorArr")).Select(ToInt).Any(id => id > 0)
               && filterCount == 0
               && duration <= 0d && tick <= 0d && cooldown <= 0d && stack <= 1
               && resultIds.Count > 0 && resultIds[0] == 301
               && !HasNativeSpecialAbilityHook(abilityId);
    }

    private static Dictionary<int, double> ReadNativeAbilityResultAttrDeltas(object ability)
    {
        var result = new Dictionary<int, double>();
        foreach (var entry in ReadEntries(Read(Read(ability, "resultData"), "combatAttrFinalDic")))
        {
            var attrId = ToInt(Read(entry, "Key") ?? 0);
            double value;
            try { value = Convert.ToDouble(Read(entry, "Value") ?? 0d, CultureInfo.InvariantCulture); }
            catch { continue; }
            if (attrId <= 0 || !double.IsFinite(value) || Math.Abs(value) <= 0d) continue;
            result[attrId] = result.GetValueOrDefault(attrId) + value;
        }
        return result;
    }

    private static Dictionary<int, double> ReadDeclaredResult301AttrDeltas(object ability)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        var values = ReadSequence(Read(row, "resultArr")).ToList();
        var result = new Dictionary<int, double>();
        if (values.Count < 3 || ToInt(values[0]) != 301) return result;
        for (var index = 1; index + 1 < values.Count; index += 2)
        {
            var attrId = ToInt(values[index]);
            double value;
            try
            {
                value = Convert.ToDouble(values[index + 1], CultureInfo.InvariantCulture);
            }
            catch
            {
                continue;
            }
            if (attrId <= 0 || CreateEnum("EAttrType", attrId) is null
                            || !double.IsFinite(value) || Math.Abs(value) <= 0d) continue;
            result[attrId] = result.GetValueOrDefault(attrId) + value;
        }
        return result;
    }

    private static IReadOnlyList<NativeConditionalAttributePayload>
        ResolveNativeConditionalAttributePayloads(
            int parentAbilityId,
            int parentAbilityLevel,
            IReadOnlyList<int>? abilityParameters,
            object attrData,
            HeroEffectProfile profile,
            string effectText)
    {
        var payloads = new List<NativeConditionalAttributePayload>();
        if (parentAbilityId <= 0) return payloads;

        object? parentRow = null;
        try
        {
            parentRow = ResolveAbilityTableRow(
                parentAbilityId, Math.Max(0, parentAbilityLevel));
        }
        catch
        {
            // The normal ability resolver below still reports a missing parent.
        }

        var candidateModes = new Dictionary<int, bool>();
        var normalizedText = NormalizeSkillDependencyText(effectText);
        var explicitlyTargetsOtherUnits = Regex.IsMatch(
            normalizedText,
            @"\b(?:allies|ally|affected targets?|minions?|sentries|totems?)\b[^.;]{0,56}\b(?:gain|gains|grant|grants|receive|receives)\b|\b(?:grant|grants|give|gives)\b[^.;]{0,56}\b(?:allies|ally|affected targets?|minions?|sentries|totems?)\b",
            RegexOptions.CultureInvariant);

        // Native special set hooks sometimes store the finite TAbility payload
        // in abilityParam. Counts and skill IDs share the same integer field, so
        // they are only candidates when the parent really has a special hook.
        // Text which explicitly targets allies/minions is not applied to the
        // hero's AttrData; those effects stay in their support/minion lane.
        if (!explicitlyTargetsOtherUnits
            && HasNativeSpecialAbilityHook(parentAbilityId)
            && abilityParameters is { Count: > 0 })
        {
            foreach (var parameterId in abilityParameters.Where(id => id > 0).Distinct())
                candidateModes.TryAdd(parameterId, false);
        }

        if (parentRow is not null)
        {
            var parentFilters = ReadSequence(Read(parentRow, "filtArr"))
                .Select(ToInt).Where(id => id > 0).ToList();
            var parentResults = ReadSequence(Read(parentRow, "resultArr"))
                .Select(ToInt).ToList();
            var parentTargetsSelf = parentFilters.Count == 1 && parentFilters[0] == 1;
            if (parentTargetsSelf && parentResults.Count > 1
                                  && parentResults[0] is 1 or 602)
            {
                // Result 1/602 calls CombatData.AddAbility in the native game.
                // Follow those table relationships instead of relying on a
                // translated description or a list of known Mythic names.
                foreach (var nestedAbilityId in parentResults.Skip(1).Where(id => id > 0))
                    candidateModes.TryAdd(nestedAbilityId, false);
            }
            else if (parentTargetsSelf && parentResults.Count >= 3
                                             && parentResults[0] == 301)
            {
                // Conditional/monitored result301 rows contain the exact signed
                // stat delta on the parent itself. Their state multiplier is
                // evaluated against the selected 30-second skill schedule.
                candidateModes.TryAdd(
                    ReadNullableInt(parentRow, "id") ?? parentAbilityId,
                    true);
            }
        }

        if (candidateModes.Count == 0) return payloads;

        foreach (var candidate in candidateModes.OrderBy(entry => entry.Key))
        {
            var parameterId = candidate.Key;
            var scaleFromParentState = candidate.Value;
            try
            {
                var row = InvokeStatic("TableData", "getTAbilityData", parameterId);
                if (row is null || (ReadNullableInt(row, "id") ?? 0) != parameterId) continue;
                var type = ReadNullableInt(row, "type") ?? 0;
                var effectiveType = ReadNullableInt(row, "effectiveType") ?? 0;
                var moments = ReadSequence(Read(row, "moment"))
                    .Select(ToInt).Where(id => id > 0).ToHashSet();
                var filters = ReadSequence(Read(row, "filtArr"))
                    .Select(ToInt).Where(id => id > 0).ToList();
                var rawResults = ReadSequence(Read(row, "resultArr")).Select(ToInt).ToList();
                var nativeCondition = Clean(ReadString(row, "condition") ?? string.Empty);
                var hasMonitor = ReadSequence(Read(row, "monitorArr"))
                    .Select(ToInt).Any(id => id > 0);
                var exactSelfFilter = filters.Count == 1 && filters[0] == 1;
                if (!exactSelfFilter
                    || rawResults.Count == 0 || rawResults[0] != 301
                    || (!scaleFromParentState
                        && HasNativeSpecialAbilityHook(parameterId))) continue;
                if (scaleFromParentState)
                {
                    // A direct self result301 row is still exact when type 9
                    // uses a native monitor to refresh it (set effects do this
                    // for active Totems). Unknown monitor relations evaluate to
                    // zero later; the signed stat payload itself is not guessed.
                    if (effectiveType is not (2 or 3)) continue;
                }
                else if (type is not (1 or 4 or 7)
                         || effectiveType != 3
                         || !moments.SetEquals(new[] { 1 })
                         || nativeCondition.Length > 0
                         || hasMonitor) continue;

                // A state payload candidate is already the resolved table row.
                // Preview from the original parent id so an affix level is
                // applied exactly once (resolvedId + level would skip ahead a
                // second time). Nested payload ids are standalone level-0 rows.
                var preview = InvokeStaticMany(
                    "AbilityData", "CreateByShow",
                    scaleFromParentState ? parentAbilityId : parameterId,
                    scaleFromParentState ? Math.Max(0, parentAbilityLevel) : 0,
                    attrData);
                var deltas = preview is null
                    ? new Dictionary<int, double>()
                    : ReadNativeAbilityResultAttrDeltas(preview);
                if (deltas.Count == 0) deltas = ReadDeclaredResult301AttrDeltas(row);
                if (deltas.Count == 0) continue;
                var duration = Convert.ToDouble(
                    Read(preview, "duration") ?? Read(row, "duration") ?? 0d,
                    CultureInfo.InvariantCulture);
                if (!double.IsFinite(duration) || Math.Abs(duration) <= 0d) continue;
                var stackLimit = Math.Max(1, ReadNullableInt(row, "stack") ?? 1);

                // Score the exact native AttrData transition for shortlist
                // retention. The final 30-second evaluator applies these same
                // signed deltas only for their measured average uptime.
                var adjusted = CreateAttributeAdjustedCopy(
                    attrData, deltas, "conditional ability payload");
                var activeObjectiveDelta = ScoreHeroAttrObjective(
                                               adjusted,
                                               profile.Focus,
                                               profile.ControlledEntityKinds)
                                           - ScoreHeroAttrObjective(
                                               attrData,
                                               profile.Focus,
                                               profile.ControlledEntityKinds);
                payloads.Add(new NativeConditionalAttributePayload(
                    parameterId,
                    duration,
                    stackLimit,
                    deltas,
                    Math.Max(0d, activeObjectiveDelta * 1000d),
                    scaleFromParentState));
            }
            catch (Exception error)
            {
                Plugin.DiagDebug(
                    $"CONDITIONAL ATTRIBUTE PAYLOAD SKIPPED|parent={parentAbilityId}"
                    + $"|parameter={parameterId}|{error.GetBaseException().Message}");
            }
        }
        return payloads;
    }

    private static object CreateAttributeAdjustedCopy(
        object attrData,
        IReadOnlyDictionary<int, double> deltas,
        string context)
    {
        var adjusted = InvokeRequiredStaticMany("AttrData", "copyCreate", attrData)
                       ?? throw new InvalidOperationException($"AttrData {context} copy failed.");
        foreach (var entry in deltas.OrderBy(entry => entry.Key))
        {
            if (!double.IsFinite(entry.Value))
                throw new InvalidOperationException(
                    $"{context} attribute {entry.Key} is not finite.");
            var attrType = CreateEnum("EAttrType", entry.Key)
                           ?? throw new InvalidOperationException(
                               $"Unknown {context} result attribute {entry.Key}.");
            InvokeRequiredInstance(
                adjusted,
                "ChangeAttr",
                attrType,
                Convert.ToSingle(entry.Value, CultureInfo.InvariantCulture));
        }
        return adjusted;
    }

    private static object CreateAbilityAdjustedAttr(object attrData, NativeAbilityPackage package)
        => CreateAttributeAdjustedCopy(
            attrData, package.AlwaysOnAttrDeltas, "ability-adjusted");

    private static object CreateExpectedConditionalAdjustedAttr(
        object attrData,
        ExpectedConditionalPackage package)
        => package.AverageAttrDeltas is { Count: > 0 }
            ? CreateAttributeAdjustedCopy(
                attrData, package.AverageAttrDeltas, "expected conditional")
            : attrData;

    private static bool IsDefensiveRoleAttribute(int attrId)
        => attrId is 3 or 4 or 5 or 7 or 9 or 26 or 27 or 32 or 34 or 36 or 43 or 44 or 45 or 47
            or 61 or 62 or 63 or 64 or 65 or 66 or 85 or 86 or 130 or 131 or 132 or 134
            or 151 or 152 or 153 or 154 or 155 or 156 or 157 or 158 or 184 or 188 or 202
            or 212 or 213 or 214 or 219;

    private static bool IsSupportRoleAttribute(int attrId)
        => attrId is 81 or 82 or 83 or 84 or 91 or 92 or 93 or 94 or 185 or 191;

    private static bool IsHostileStatusApplicationAttribute(int attrId)
    {
        if (attrId is 187 or 800 or 820 or 830 or 840) return true;
        var attrType = GameType("EAttrType");
        if (attrType is null || !attrType.IsEnum) return false;
        string name;
        try
        {
            name = NormalizeSkillDependencyText(
                Enum.ToObject(attrType, attrId).ToString() ?? string.Empty);
        }
        catch
        {
            return false;
        }
        if (name.Length == 0 || int.TryParse(name, out _)) return false;
        // Attribute names come from the game's enum, not translated display
        // text. This catches newly added control/status stacks without assigning
        // arbitrary positive combat attributes to the hostile-status lane.
        return new[]
        {
            "stack", "status", "debuff", "slow", "stun", "paraly",
            "freeze", "shock", "poison", "toxic", "bleed", "wound",
            "corrosion", "sunder", "weak", "blind", "silence", "root",
            "fear", "charm", "petrif"
        }.Any(token => name.Contains(token, StringComparison.OrdinalIgnoreCase));
    }

    private static readonly object NativeHostileStatusSync = new();
    private static readonly HashSet<int> NativeHostileStatusAttributeIds = new();

    private static bool IsNativeHostileStatusResult(
        int abilityType,
        int attrId,
        double signedValue)
    {
        if (abilityType is not (2 or 3)
            || attrId <= 0
            || !double.IsFinite(signedValue)
            || signedValue <= 0d
            || IsUnsafeRoleEvidenceAttribute(attrId)) return false;
        lock (NativeHostileStatusSync)
            if (NativeHostileStatusAttributeIds.Contains(attrId)) return true;
        if (IsHostileStatusApplicationAttribute(attrId))
        {
            lock (NativeHostileStatusSync)
                NativeHostileStatusAttributeIds.Add(attrId);
            return true;
        }

        // Type 2/3 is the game's hostile modifier lane. Ordinary debuffs use a
        // negative stat delta; a positive result in the same lane is therefore
        // a native state/counter application. Register the table relationship
        // so newly introduced poison, paralysis, and stacking ailments do not
        // require a named plugin rule.
        lock (NativeHostileStatusSync)
            NativeHostileStatusAttributeIds.Add(attrId);
        return true;
    }

    private static bool IsUnsafeRoleEvidenceAttribute(int attrId)
        => attrId == 248 || attrId is >= 700 and <= 712;

    private static (bool Support, bool Defense, bool Minion) GetProvenResult301RoleLanes(object ability)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        if (row is null) return (false, false, false);
        var results = ReadSequence(Read(row, "resultArr")).Select(ToInt).Where(id => id > 0).ToList();
        if (results.Count == 0 || results[0] != 301) return (false, false, false);

        var type = ReadNullableInt(row, "type") ?? 0;
        var support = false;
        var defense = false;
        var minion = false;
        foreach (var entry in ReadNativeAbilityResultAttrDeltas(ability))
        {
            var attrId = entry.Key;
            var value = entry.Value;
            if (IsUnsafeRoleEvidenceAttribute(attrId) || !double.IsFinite(value) || value == 0d) continue;

            // Type 6 is the native continuous ally-aura lane. Its safe positive
            // combat attributes include offensive auras such as Strike/Killing,
            // not only heal/buff-duration attributes. Type 2/3 negative deltas
            // and positive native hostile-status stack counters are proven
            // debuffs and therefore party utility.
            var hostileStatus = IsNativeHostileStatusResult(
                type, attrId, value);
            // Type 1 is the game's finite friendly-buff lane (including
            // offensive buffs such as Attack/Accuracy); type 6 is its continuous
            // aura lane. Positive, safe result301 deltas in either lane are
            // native support output even when the affected stat is offensive.
            if ((type is 1 or 6 && value > 0d)
                || (type is 2 or 3 && value < 0d)
                || hostileStatus
                || (value > 0d && IsSupportRoleAttribute(attrId)))
                support = true;
            if (value > 0d && IsDefensiveRoleAttribute(attrId))
                defense = true;
            if (value > 0d && attrId is 25 or 190 or 6001 or 6002)
                minion = true;
        }
        return (support, defense, minion);
    }

    private static bool HasProvenRoleResult301(object ability)
    {
        var lanes = GetProvenResult301RoleLanes(ability);
        return lanes.Support || lanes.Defense || lanes.Minion;
    }

    private static bool IsContinuousNativeAuraRoleAbility(object ability)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        if (row is null) return false;
        var abilityId = ReadNullableInt(row, "id") ?? ReadNullableInt(ability, "id") ?? 0;
        var moments = ReadSequence(Read(row, "moment")).Select(ToInt).Where(id => id > 0).ToHashSet();
        var rawDuration = Convert.ToDouble(
            Read(ability, "duration") ?? Read(row, "duration") ?? 0d,
            CultureInfo.InvariantCulture);
        return abilityId > 0
               && (ReadNullableInt(row, "type") ?? 0) == 6
               && (ReadNullableInt(row, "effectiveType") ?? 0) == 3
               && moments.SetEquals(new[] { 1 })
               && Clean(ReadString(row, "condition") ?? string.Empty).Length == 0
               && !ReadSequence(Read(row, "monitorArr")).Select(ToInt).Any(id => id > 0)
               && rawDuration < 0d
               && Math.Max(0d, Convert.ToDouble(Read(row, "cdTime") ?? 0d, CultureInfo.InvariantCulture)) <= 0d
               && Math.Max(0, ReadNullableInt(row, "stack") ?? 0) <= 1
               && !HasNativeSpecialAbilityHook(abilityId)
               && HasProvenRoleResult301(ability);
    }

    private static bool TryGetGraphTriggeredAbilityRoleUtility(
        object ability,
        NativeAbilityInvocation invocation,
        double castOpportunities,
        double cycleSeconds,
        out (double Support, double Defense, double Minion) utility)
    {
        utility = (0d, 0d, 0d);
        var row = Read(ability, "tAbilityData") ?? ability;
        var hasProvenTriggerTimeline = invocation.DirectUnconditionalActionTrigger
                                       || invocation.EventTimeline is { Count: > 0 };
        if (row is null || !hasProvenTriggerTimeline
                        || castOpportunities <= 0d || invocation.EventsPerCast <= 0d) return false;
        var abilityId = ReadNullableInt(row, "id") ?? ReadNullableInt(ability, "id") ?? invocation.AbilityId;
        var moments = ReadSequence(Read(row, "moment")).Select(ToInt).Where(id => id > 0).ToHashSet();
        if (abilityId <= 0
            || (ReadNullableInt(row, "effectiveType") ?? 0) != 3
            || !moments.SetEquals(new[] { 1 })
            || Clean(ReadString(row, "condition") ?? string.Empty).Length > 0
            || ReadSequence(Read(row, "monitorArr")).Select(ToInt).Any(id => id > 0)
            || HasNativeSpecialAbilityHook(abilityId)
            || !HasProvenRoleResult301(ability)) return false;

        var rawDuration = Convert.ToDouble(
            Read(ability, "duration") ?? Read(row, "duration") ?? 0d,
            CultureInfo.InvariantCulture);
        double uptime;
        if (rawDuration < 0d)
        {
            uptime = 1d;
        }
        else
        {
            if (rawDuration <= 0d || !double.IsFinite(cycleSeconds) || cycleSeconds <= 0d) return false;
            // Only graph-proven root-action or timed emitter/bullet applications
            // are counted. Coverage over the fixed 30-second window is capped at
            // one, so overlapping Totem refreshes cannot multiply the buff.
            var provenApplications = Math.Max(0d, invocation.EventsPerCast * castOpportunities);
            uptime = Math.Clamp(rawDuration * provenApplications / PerformancePreviewWindowSeconds, 0d, 1d);
        }
        if (uptime <= 0d) return false;
        var raw = GetNativeAbilityRoleUtilityCore(ability);
        utility = (raw.Support * uptime, raw.Defense * uptime, raw.Minion * uptime);
        return utility.Support > 0d || utility.Defense > 0d || utility.Minion > 0d;
    }

    private static (double Support, double Defense, double Minion) GetNativeAbilityRoleUtility(object? ability)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        if (row is null) return (0d, 0d, 0d);
        // Conditional and AbilitySys-special effects need live combat events.
        // Treat them as an unknown zero lower bound instead of fabricating uptime.
        if (!IsUnconditionalAcquireAbility(row))
            return (0d, 0d, 0d);
        return GetNativeAbilityRoleUtilityCore(ability!);
    }

    private static (double Support, double Defense, double Minion) GetNativeAbilityRoleUtilityCore(object ability)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        var type = ReadNullableInt(row, "type") ?? 0;
        var moments = ReadSequence(Read(row, "moment")).Select(ToInt).Where(id => id > 0).ToHashSet();
        var duration = Math.Max(0d, Convert.ToDouble(
            Read(ability, "duration") ?? Read(row, "duration") ?? 0d, CultureInfo.InvariantCulture));
        var cooldown = Math.Max(0d, Convert.ToDouble(
            Read(ability, "cdTime") ?? Read(row, "cdTime") ?? 0d, CultureInfo.InvariantCulture));
        var uptime = duration > 0d && cooldown > 0d ? Math.Clamp(duration / cooldown, 0.1d, 1d) : 1d;
        var lanes = GetProvenResult301RoleLanes(ability);
        var support = lanes.Support
            ? type switch { 6 => 1100d, 1 => 650d, 4 => 420d, 2 or 3 => 450d, _ => 260d }
            : 0d;
        var defense = lanes.Defense
            ? type switch { 7 => 2600d, 2 or 3 or 5 => 450d, _ => 520d }
            : 0d;
        var minion = lanes.Minion ? 1300d : 0d;
        if (lanes.Defense && moments.Overlaps(new[] { 8, 11, 13, 15, 100, 102, 104 }))
            defense += 700d;
        if (moments.Contains(1))
        {
            if (lanes.Support) support += 280d;
            if (lanes.Defense) defense += 280d;
        }
        var targetBreadth = ReadSequence(Read(row, "filtArr")).Select(ToInt).Count(value => value > 0);
        if (lanes.Support && targetBreadth > 0 && type is 1 or 2 or 3 or 4 or 6)
            support += Math.Min(500d, targetBreadth * 125d);

        // AbilityData.CreateByShow computes native-adjusted values for static
        // result code 301 in combatAttrFinalDic. Read that exact preview when it
        // exists, so equal ability types with very different magnitudes do not
        // collapse to the same role score. Dynamic result codes remain structural
        // signals only; executing them would mutate combat state.
        foreach (var entry in ReadEntries(Read(Read(ability, "resultData"), "combatAttrFinalDic")))
        {
            var resultAttrId = ToInt(Read(entry, "Key") ?? 0);
            double signedValue;
            try { signedValue = Convert.ToDouble(Read(entry, "Value") ?? 0d, CultureInfo.InvariantCulture); }
            catch { continue; }
            if (resultAttrId <= 0 || IsUnsafeRoleEvidenceAttribute(resultAttrId)
                                  || !double.IsFinite(signedValue) || Math.Abs(signedValue) <= 0d) continue;
            var magnitude = Math.Log10(1d + Math.Abs(signedValue)) * 420d;
            var hostileDebuff = type is 2 or 3
                                && (signedValue < 0d
                                    || IsNativeHostileStatusResult(
                                        type, resultAttrId, signedValue));
            if (lanes.Support
                && ((type == 6 && signedValue > 0d)
                    || hostileDebuff
                    || signedValue > 0d && IsSupportRoleAttribute(resultAttrId)))
                support += magnitude * (hostileDebuff ? 0.8d : 1d);
            if (lanes.Defense && !hostileDebuff && signedValue > 0d
                              && IsDefensiveRoleAttribute(resultAttrId))
                defense += magnitude;
            if (lanes.Minion && !hostileDebuff && signedValue > 0d
                             && resultAttrId is 25 or 190 or 6001 or 6002)
                minion += magnitude;
        }
        return (support * uptime, defense * uptime, minion * uptime);
    }

    private static double ScoreNativeAbility(
        object? ability,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        if (!IsNativeAbilityRelevantToProfile(ability, profile, relevanceScope)) return 0d;
        var row = Read(ability, "tAbilityData") ?? ability;
        if (row is null) return 0d;
        var type = ReadNullableInt(row, "type") ?? 0;
        var attrId = ReadNullableInt(row, "attrId") ?? 0;
        var moments = ReadSequence(Read(row, "moment")).Select(ToInt).Where(id => id > 0).ToHashSet();
        if (!IsUnconditionalAcquireAbility(row))
            return 0d;
        var duration = Math.Max(0d, Convert.ToDouble(Read(row, "duration") ?? 0d, CultureInfo.InvariantCulture));
        var cooldown = Math.Max(0d, Convert.ToDouble(Read(row, "cdTime") ?? 0d, CultureInfo.InvariantCulture));
        var effectiveType = ReadNullableInt(row, "effectiveType") ?? 0;
        var resultCount = ReadSequence(Read(row, "resultArr")).Select(ToInt).Count(id => id > 0);
        var defense = profile.Focus.Key == "defense";
        var support = profile.Focus.Key == "support";
        var score = type switch
        {
            7 => defense ? 2400d : 480d, // native immunity ability
            1 or 4 or 6 => defense || support ? 520d : 360d,
            2 or 3 or 5 => defense ? 600d : 260d,
            _ => 120d
        };
        if (attrId > 0)
        {
            var physical = profile.Focus.Key is "physical" or "bleed";
            var elemental = profile.Focus.Key is "elemental" or "fire" or "ice" or "lightning" or "corrosion";
            score += Math.Min(900d, Math.Max(0d,
                GetBattleAttrPreScoreWeight(attrId, profile, physical, elemental) * 28d));
            score *= GetNativeAbilityElementWeight(attrId, profile.Focus);
        }
        if (moments.Overlaps(new[] { 8, 11, 13, 15, 100, 102, 104 }))
            score += defense ? 650d : 180d;
        if (moments.Overlaps(new[] { 3, 6, 7, 9, 14 }))
            score += defense ? 120d : 360d;
        if (moments.Contains(1) || effectiveType == 3) score += defense || support ? 420d : 240d;
        score += Math.Min(300d, resultCount * 75d);
        if (duration > 0d && cooldown > 0d)
            score *= Math.Clamp(duration / cooldown, 0.15d, 1d);
        return Math.Clamp(score, 0d, defense ? 4200d : 2200d);
    }

    private static double ScoreOpaqueConditionalEffect(string effectText, HeroEffectProfile profile)
    {
        // Catalog descriptions occasionally contain zero-width formatting
        // characters (for example between "Boost" and "effects").  Use the
        // same normalized text as the dependency classifier so relation rules
        // keep working for localized/future rows without item-ID exceptions.
        var text = NormalizeSkillDependencyText(effectText);
        if (text.Length == 0) return 0d;
        // Concrete drawbacks remain part of the item instead of disappearing
        // as a zero. Mixed upside/downside effects are scored on both sides.
        var hasSelfResourceDrawback = Regex.IsMatch(
            text,
            @"\b(?:lose|loses|sacrifice|sacrifices|consume|consumes|spend|spends)\b[^.;]{0,48}\b(?:mana|health|life|shield|barrier)\b",
            RegexOptions.CultureInvariant);
        var hasCostOrCooldownDrawback = Regex.IsMatch(
            text,
            @"\b(?:mana|health|life|skill)?\s*(?:cost|cooldown)\b[^.;]{0,32}\b(?:double|doubled|increase|increased|longer)\b",
            RegexOptions.CultureInvariant);
        var hasCapabilityDrawback = Regex.IsMatch(
            text,
            @"\b(?:skills? cannot crit|cannot critically strike|does not affect allies)\b",
            RegexOptions.CultureInvariant);
        var percentages = Regex.Matches(text, @"(?<!\d)(\d+(?:\.\d+)?)\s*%")
            .Cast<Match>()
            // A roll percentage describes how often the payload happens, not
            // how strong one payload is. Its probability is applied separately
            // to the measured trigger opportunities below.
            .Where(match => !Regex.IsMatch(
                text.Substring(match.Index, Math.Min(text.Length - match.Index, match.Length + 20)),
                @"^\d+(?:\.\d+)?\s*%\s*(?:chance|probability)\b",
                RegexOptions.CultureInvariant))
            .Select(match => double.TryParse(
                match.Groups[1].Value,
                NumberStyles.Float,
                CultureInfo.InvariantCulture,
                out var parsed) ? parsed : 0d)
            .Where(value => value > 0d && double.IsFinite(value))
            .ToList();
        var seconds = Regex.Matches(text, @"(?<!\d)(\d+(?:\.\d+)?)\s*(?:s|sec|second)")
            .Cast<Match>()
            .Select(match => double.TryParse(
                match.Groups[1].Value,
                NumberStyles.Float,
                CultureInfo.InvariantCulture,
                out var parsed) ? parsed : 0d)
            .Where(value => value > 0d && double.IsFinite(value))
            .ToList();
        var magnitude = percentages.DefaultIfEmpty(0d).Max();
        var secondsMagnitude = seconds.DefaultIfEmpty(0d).Max();
        var score = 0d;
        if (hasSelfResourceDrawback)
            score -= text.Contains("health", StringComparison.Ordinal)
                     || text.Contains("life", StringComparison.Ordinal)
                ? 760d
                : text.Contains("shield", StringComparison.Ordinal)
                  || text.Contains("barrier", StringComparison.Ordinal)
                    ? 520d
                    : 380d;
        if (hasCostOrCooldownDrawback) score -= 680d;
        if (hasCapabilityDrawback) score -= 1050d;

        var damageTakenContext = Regex.IsMatch(text,
            @"\b(?:damage (?:you )?take|damage taken|incoming damage)\b",
            RegexOptions.CultureInvariant);
        if (!damageTakenContext
            && (text.Contains("damage", StringComparison.Ordinal)
                || text.Contains("dealing", StringComparison.Ordinal)
                || text.Contains("deals", StringComparison.Ordinal)))
            score += 360d + Math.Min(1400d, magnitude * 5d);
        if (damageTakenContext
            && Regex.IsMatch(text,
                @"\b(?:reduce|reduced|decrease|decreased|less|mitigat)\w*\b",
                RegexOptions.CultureInvariant))
            score += (profile.Focus.Key == "defense" ? 900d : 260d)
                     + Math.Min(760d, magnitude * 5d);
        var cooldownBenefit = Regex.IsMatch(
            text,
            @"(?:\b(?:reset|reduce|decrease|shorten|shorter|recover)\w*\b[^.;]{0,40}\bcooldown\b|\bcooldown\b[^.;]{0,40}\b(?:reset|reduce|decrease|shorten|shorter|recover)\w*\b|\bcooldown speed\b[^.;]{0,32}\b(?:increase|increased|faster)\w*\b|\bdoes not trigger (?:its )?cooldown\b)",
            RegexOptions.CultureInvariant);
        if (cooldownBenefit)
        {
            score += text.Contains("reset", StringComparison.Ordinal)
                ? 280d + Math.Min(900d, magnitude * 12d)
                : 300d + Math.Min(800d, secondsMagnitude * 320d + magnitude * 4d);
        }
        var costBenefit = Regex.IsMatch(
            text,
            @"(?:\b(?:reduce|decrease|refund)\w*\b[^.;]{0,40}\bcost\b|\bcost\b[^.;]{0,40}\b(?:reduce|decrease|refund|cannot exceed|cap(?:ped)?|limit(?:ed)?)\w*\b|\b(?:free|no cost)\b)",
            RegexOptions.CultureInvariant);
        if (costBenefit)
            score += (profile.Focus.Key == "support" ? 420d : 220d)
                     + Math.Min(500d, magnitude * 4d);
        if (text.Contains("resist", StringComparison.Ordinal)
            || text.Contains("immun", StringComparison.Ordinal))
            score += (profile.Focus.Key == "defense" ? 620d : 140d)
                     + Math.Min(500d, magnitude * 4d);
        var restorativeBenefit = Regex.IsMatch(
            text,
            @"\b(?:gain|grant|grants|generate|generates|create|creates|restore|restores)\b[^.;]{0,48}\b(?:health|life|healing|shield|barrier)\b|\bheals?\b",
            RegexOptions.CultureInvariant);
        if (restorativeBenefit)
            score += profile.Focus.Key is "support" or "defense" ? 620d : 180d;
        if (Regex.IsMatch(text,
                @"\b(?:apply|applies|inflict|inflicts|gain)\b[^.;]{0,48}\b(?:wound|slow|sunder|affliction|debuff|haste|mettle)\b",
                RegexOptions.CultureInvariant))
            score += profile.Focus.Key is "bleed" or "corrosion" ? 520d : 240d;
        if (Regex.IsMatch(text, @"\b(?:purge|purify|cleanse|dispel)\w*\b",
                RegexOptions.CultureInvariant))
            score += profile.Focus.Key is "support" or "defense" ? 480d : 140d;
        if (Regex.IsMatch(text,
                @"\b(?:summon|summons|summoning)\b[^.;]{0,48}\badditional\s+(?:minions?|one)\b",
                RegexOptions.CultureInvariant))
            score += profile.Focus.Key == "minion" ? 900d : 180d;
        var effectAmplification = Regex.IsMatch(text,
            @"(?:\b(?:gain|gains|increase|increased|more|double|doubles|improve|improves)\w*\b[^.;]{0,48}\b(?:buff |skill |aura |warcry |totem )?(?:effects?|effectiveness)\b|\b(?:buff |skill |aura |warcry |totem )?(?:effects?|effectiveness)\b[^.;]{0,48}\b(?:increase|increased|more|double|doubled|improve|improved)\w*\b)",
            RegexOptions.CultureInvariant);
        if (effectAmplification)
            score += (profile.Focus.Key is "support" or "minion" ? 560d : 300d)
                     + Math.Min(980d, magnitude * 4.5d);

        var speedBenefit = Regex.IsMatch(text,
            @"(?:\b(?:gain|gains|increase|increased|more|double|doubles)\w*\b[^.;]{0,48}\b(?:attack|cast|skill|martial|spell) speed\b|\b(?:attack|cast|skill|martial|spell) speed\b[^.;]{0,48}\b(?:increase|increased|more|double|doubled)\w*\b)",
            RegexOptions.CultureInvariant);
        if (speedBenefit)
            score += (profile.Focus.Key is "defense" or "support" ? 220d : 480d)
                     + Math.Min(860d, magnitude * 6d);

        var accuracyOrCriticalBenefit = Regex.IsMatch(text,
            @"\b(?:crit(?:ical)?(?: chance| value| damage)?|accuracy)\b[^.;]{0,52}\b(?:equal|gain|increase|increased|more|double|doubled)\w*\b|\b(?:double|doubles|doubled|increase|increased)\w*\b[^.;]{0,32}\b(?:crit(?:ical)?(?: chance| value| damage)?)\b|\b(?:always|guaranteed)\b[^.;]{0,32}\b(?:hit|hits|crit|critical(?:ly)? strike)\w*\b",
            RegexOptions.CultureInvariant);
        if (accuracyOrCriticalBenefit)
            score += profile.Focus.Key is "defense" or "support" ? 180d
                : profile.Focus.Key == "crit" ? 720d : 420d;

        var attributeBenefit = Regex.IsMatch(text,
            @"\b(?:gain|gains|grant|grants|increase|increased)\w*\b[^.;]{0,56}\b(?:primary attributes?|strength|dexterity|intelligence|all defense|physical defense|elemental defense|dodge|tenacity|crit resistance)\b",
            RegexOptions.CultureInvariant);
        if (attributeBenefit)
            score += profile.Focus.Key is "support" or "minion" ? 520d
                : profile.Focus.Key == "defense" ? 620d : 260d;

        var targetCoverageBenefit = Regex.IsMatch(text,
            @"\b(?:pierce|pierces|penetration|penetrate|additional targets?|extra targets?|up to \d+ targets?|area of effect|effect area|radius)\b",
            RegexOptions.CultureInvariant);
        if (targetCoverageBenefit)
            score += (profile.Focus.Key is "defense" or "support" ? 140d : 520d)
                     + Math.Min(420d, magnitude * 2d);

        var defensePenetrationBenefit = Regex.IsMatch(text,
            @"\b(?:ignore|ignores|bypass|bypasses|penetrate|penetrates)\b[^.;]{0,48}\b(?:physical|elemental|fire|frost|ice|lightning)?\s*(?:defense|defences|resistance)\b",
            RegexOptions.CultureInvariant);
        if (defensePenetrationBenefit)
            score += profile.Focus.Key is "defense" or "support" ? 120d : 680d;

        var hostileDefenseReduction = Regex.IsMatch(text,
            @"\b(?:lower|lowers|reduce|reduces|decrease|decreases)\b[^.;]{0,48}\b(?:the )?targets?'?s?\s+(?:physical |elemental |all )?(?:defenses|defences|defense|resistances|resistance)\b",
            RegexOptions.CultureInvariant);
        if (hostileDefenseReduction)
            score += profile.Focus.Key is "defense" or "support" ? 220d : 620d;

        var minionStatBenefit = Regex.IsMatch(text,
            @"\bminions?'?s?\b(?=[^.;]{0,72}\b(?:all defense|defense|defences|accuracy|crit value|critical|attack|damage|speed)\b)(?:[^.;]{0,32}\b(?:gain|gains|increase|increased)\w*\b[^.;]{0,40}|[^.;]{0,72}\b(?:all defense|defense|defences|accuracy|crit value|critical|attack|damage|speed)\b[^.;]{0,24}\+\s*\d)",
            RegexOptions.CultureInvariant);
        if (minionStatBenefit)
            score += profile.Focus.Key == "minion" ? 980d : 180d;

        var effectPropagation = Regex.IsMatch(text,
            @"\b(?:also applies|apply(?:ing|ies)? to|affects? (?:all|another|other)|(?:buff|boost|aura|skill) effects?\b[^.;]{0,48}\b(?:grant(?:ed)?|share(?:d)?|transfer(?:red)?) to)\b",
            RegexOptions.CultureInvariant);
        if (effectPropagation)
            score += profile.Focus.Key is "support" or "minion" ? 720d : 360d;

        var conditionBridgeBenefit = Regex.IsMatch(text,
            @"\b(?:considered|treated|counted)\b[^.;]{0,48}\b(?:state of )?(?:bloodied|wound(?:ed)?|afflicted|slowed|sundered)\b",
            RegexOptions.CultureInvariant);
        if (conditionBridgeBenefit)
            score += profile.Focus.Key is "bleed" or "corrosion" ? 680d : 220d;

        var allyStatInheritance = Regex.IsMatch(text,
            @"\ball(?:y|ies)\b[^.;]{0,64}\b(?:inherit|inherits|gain|gains|receive|receives)\b[^.;]{0,48}\b(?:attack|damage|defense|defenses|attributes?|strength|dexterity|intelligence)\b",
            RegexOptions.CultureInvariant);
        if (allyStatInheritance)
            score += profile.Focus.Key == "support" ? 820d
                : profile.Focus.Key == "minion" ? 480d : 220d;

        var healingPropagation = Regex.IsMatch(text,
            @"\b(?:heal(?:ing)?|overheal(?:ing)?)\b[^.;]{0,56}\b(?:share(?:d)?|grant(?:ed)?|transfer(?:red)?|distribut(?:e|ed))\b[^.;]{0,32}\ball(?:y|ies)\b",
            RegexOptions.CultureInvariant);
        if (healingPropagation)
            score += profile.Focus.Key == "support" ? 760d
                : profile.Focus.Key == "defense" ? 420d : 140d;

        var incomingDamageCap = damageTakenContext && Regex.IsMatch(text,
            @"\b(?:cannot exceed|cap(?:ped)? at|limit(?:ed)? to|maximum of)\b",
            RegexOptions.CultureInvariant);
        if (incomingDamageCap)
            score += (profile.Focus.Key == "defense" ? 980d : 300d)
                     + Math.Min(600d, magnitude * 4d);

        var incomingDamageTransfer = damageTakenContext && Regex.IsMatch(text,
            @"\b(?:transfer(?:red)?|redirect(?:ed)?|share(?:d)?)\b[^.;]{0,48}\ball(?:y|ies)\b",
            RegexOptions.CultureInvariant);
        if (incomingDamageTransfer)
            score += profile.Focus.Key == "defense" ? 820d
                : profile.Focus.Key == "support" ? 460d : 180d;

        var durationBenefit = Regex.IsMatch(text,
            @"(?:\b(?:gain|gains|increase|increased|more|double|doubles|extend|extends)\w*\b[^.;]{0,40}\bduration\b|\bduration\b[^.;]{0,40}\b(?:increase|increased|more|double|doubled|extend|extended)\w*\b)",
            RegexOptions.CultureInvariant);
        if (durationBenefit)
            score += (profile.Focus.Key is "support" or "minion" ? 440d : 220d)
                     + Math.Min(620d, magnitude * 3d);

        if (Regex.IsMatch(text,
                @"\b(?:gain|gains|increase|increased|double|doubles)\b[^.;]{0,48}\b(?:attack|damage)\b",
                RegexOptions.CultureInvariant))
            score += profile.Focus.Key is "defense" or "support" ? 160d : 360d;
        if (Regex.IsMatch(text,
                @"\brestore\w*\b[^.;]{0,36}\bmana\b",
                RegexOptions.CultureInvariant))
            score += profile.Focus.Key == "support" ? 380d : 180d;

        // Unknown native hooks remain a zero lower bound. Only a concrete,
        // table-described combat effect earns this conservative structural
        // estimate; no ability ID or class-specific exception is hard-coded.
        return Math.Clamp(
            score,
            -3200d,
            profile.Focus.Key == "defense" ? 3200d : 2200d);
    }

    private static bool IsExpectedConditionalEffect(object? ability, string effectText)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        if (Clean(ReadString(row, "condition") ?? string.Empty).Length > 0) return true;
        if (ReadSequence(Read(row, "monitorArr")).Select(ToInt).Any(id => id > 0))
            return true;
        var text = NormalizeSkillDependencyText(effectText);
        return Regex.IsMatch(text,
            @"\b(?:chance|probability|critically strikes?|on (?:[^.;]{0,32} )?hits?|when |each time|every \d|for each|after casting|does not trigger (?:its )?cooldown|not enter cooldown)\b",
            RegexOptions.CultureInvariant);
    }

    private static HashSet<int> ReadNativeSkillTagIdsCore(int skillId)
    {
        var skill = skillId > 0 ? InvokeStatic("TableData", "getTSkillData", skillId) : null;
        var infoId = ReadNullableInt(skill, "infoId") ?? 0;
        var info = infoId > 0 ? InvokeStatic("TableData", "getTSkillInfoData", infoId) : null;
        return ReadSequence(Read(info, "tagArr")).Select(ToInt).Where(id => id > 0).ToHashSet();
    }

    private static bool TryReadConditionalDurationSeconds(string text, out double seconds)
    {
        seconds = 0d;
        var match = Regex.Match(text,
            @"\bfor\s+(\d+(?:\.\d+)?)\s*(?:s|sec|secs|second|seconds)\b",
            RegexOptions.CultureInvariant);
        return match.Success
               && double.TryParse(match.Groups[1].Value, NumberStyles.Float,
                   CultureInfo.InvariantCulture, out seconds)
               && double.IsFinite(seconds) && seconds > 0d;
    }

    private static bool TryReadAdditionalHealingTargetCount(
        string text,
        out double additionalTargets)
    {
        additionalTargets = 0d;
        var normalized = NormalizeSkillDependencyText(text);
        // This is a relationship rule, not an item/set exception. A conditional
        // may name a specific healing skill, while a permanent modifier may say
        // only "heal N additional allied targets" and apply to every scheduled
        // healing skill. Both reuse measured per-recipient healing.
        var match = Regex.Match(
            normalized,
            @"\bheal(?:s|ed|ing)?\s+(\d+(?:\.\d+)?)\s+additional\s+(?:all(?:y|ies)|allied\s+targets?|targets?)\b",
            RegexOptions.CultureInvariant);
        return match.Success
               && double.TryParse(match.Groups[1].Value, NumberStyles.Float,
                   CultureInfo.InvariantCulture, out additionalTargets)
               && double.IsFinite(additionalTargets) && additionalTargets > 0d;
    }

    private static bool TryReadCooldownReductionSeconds(string text, out double seconds)
    {
        seconds = 0d;
        var match = Regex.Match(text,
            @"\bcooldown\b[^.;]{0,32}\b(?:reduce|reduced|decrease|decreased|shorten|shortened)\w*\b[^.;]{0,16}?(\d+(?:\.\d+)?)\s*(?:s|sec|secs|second|seconds)\b",
            RegexOptions.CultureInvariant);
        return match.Success
               && double.TryParse(match.Groups[1].Value, NumberStyles.Float,
                   CultureInfo.InvariantCulture, out seconds)
               && double.IsFinite(seconds) && seconds > 0d;
    }

    private static bool TryReadCooldownSpeedIncreasePercent(
        string text,
        out double percent)
    {
        percent = 0d;
        var normalized = NormalizeSkillDependencyText(text);
        var match = Regex.Match(
            normalized,
            @"\bcooldown speed\b[^.;]{0,32}\b(?:increase|increased|faster)\w*\b[^.;]{0,16}?(\d+(?:\.\d+)?)\s*%|(?<!\d)(\d+(?:\.\d+)?)\s*%[^.;]{0,16}\b(?:increase|increased|faster)\w*\b[^.;]{0,32}\bcooldown speed\b",
            RegexOptions.CultureInvariant);
        if (!match.Success) return false;
        var value = match.Groups[1].Success
            ? match.Groups[1].Value
            : match.Groups[2].Value;
        return double.TryParse(value, NumberStyles.Float,
                   CultureInfo.InvariantCulture, out percent)
               && double.IsFinite(percent) && percent > 0d;
    }

    private static bool TryReadCooldownReductionPercent(
        string text,
        out double percent)
    {
        percent = 0d;
        var normalized = NormalizeSkillDependencyText(text);
        var match = Regex.Match(
            normalized,
            @"\bcooldown\b[^.;]{0,32}\b(?:reduce|reduced|decrease|decreased|shorten|shortened)\w*\b[^.;]{0,16}?(\d+(?:\.\d+)?)\s*%|(?<!\d)(\d+(?:\.\d+)?)\s*%[^.;]{0,16}\b(?:reduce|reduced|decrease|decreased|shorten|shortened)\w*\b[^.;]{0,32}\bcooldown\b",
            RegexOptions.CultureInvariant);
        if (!match.Success) return false;
        var value = match.Groups[1].Success
            ? match.Groups[1].Value
            : match.Groups[2].Value;
        return double.TryParse(value, NumberStyles.Float,
                   CultureInfo.InvariantCulture, out percent)
               && double.IsFinite(percent) && percent is > 0d and < 100d;
    }

    private static double EstimateScheduledFullResourceUptime(
        NativeSkillPackageSchedule schedule,
        object attrData,
        bool mana)
    {
        var totalSpend = schedule.Skills.Values.Sum(entry =>
            Math.Max(0d, entry.Casts)
            * Math.Max(0d, mana
                ? entry.Role.MpCostPerCast
                : entry.Role.HpCostPerCast));
        if (totalSpend <= 0.000001d) return 1d;
        var regen = Math.Max(0d, ReadAttrRequired(attrData, mana ? 8 : 7))
                    * NativeRateFactor(ReadAttrRequired(attrData, mana ? 10 : 9));
        if (!double.IsFinite(regen) || regen <= 0.000001d) return 0d;
        // The deterministic target starts full and has no incoming damage.
        // Each point spent owns 1/regen seconds of non-full time; overlap only
        // makes this a conservative lower bound.
        return Math.Clamp(
            1d - totalSpend / regen / PerformancePreviewWindowSeconds,
            0d,
            1d);
    }

    private static double EstimateNativeParentStateMultiplier(
        NativeConditionalEffect effect,
        NativeSkillPackageSchedule schedule,
        object attrData,
        IReadOnlyDictionary<int, double> expectedAttrDeltas,
        int commonQualityItemCount)
    {
        var row = InvokeStatic("TableData", "getTAbilityData", effect.AbilityId);
        if (row is null) return 0d;
        double ReadCounter(int attrId)
        {
            try
            {
                return ReadAttrRequired(attrData, attrId)
                       + expectedAttrDeltas.GetValueOrDefault(attrId);
            }
            catch
            {
                return expectedAttrDeltas.GetValueOrDefault(attrId);
            }
        }
        double CountControlled(NativeControlledEntityKind kind)
            => schedule.Skills.Values
                .Where(entry => entry.Casts > 0d
                                && entry.Role.ControlledEntityKinds.HasFlag(kind))
                .Sum(entry => Math.Max(0d,
                    entry.Role.ControlledEntityCount * entry.Scale));
        double NamedStatePresence()
        {
            var description = NormalizeSkillDependencyText(
                EnglishText(row, "_des", ReadString(row, "des") ?? string.Empty)
                ?? string.Empty);
            var match = Regex.Match(
                description,
                @"\b(?:each|every|per)\s+(?:active\s+)?(?:stack\s+of\s+)?([a-z][a-z '\-]{1,30}?)(?:,|\s+(?:you|owned|active|gain|grants?|increases?|provides?)\b)",
                RegexOptions.CultureInvariant);
            if (!match.Success) return 0d;
            var stateName = Clean(match.Groups[1].Value).ToLowerInvariant();
            if (stateName.Length < 3) return 0d;
            foreach (var entry in schedule.Skills.Values.Where(entry => entry.Casts > 0d))
            {
                var skill = InvokeStatic("TableData", "getTSkillData", entry.SkillId);
                var infoId = ReadNullableInt(skill, "infoId") ?? 0;
                var info = infoId > 0
                    ? InvokeStatic("TableData", "getTSkillInfoData", infoId)
                    : null;
                var skillText = NormalizeSkillDependencyText(string.Join(" ",
                    ReadString(skill, "name"),
                    EnglishName(skill, string.Empty),
                    ReadString(info, "des"),
                    EnglishText(info, "_des", string.Empty)));
                if (skillText.Contains(stateName, StringComparison.Ordinal))
                    return 1d;
            }
            return 0d;
        }
        double InferMonitorFromDescription()
        {
            var text = NormalizeSkillDependencyText(
                EnglishText(row, "_des", ReadString(row, "des") ?? string.Empty)
                ?? string.Empty);
            if (Regex.IsMatch(text, @"\b(?:each|every|per)\b[^.;]{0,32}\bminions?\b",
                    RegexOptions.CultureInvariant))
                return CountControlled(NativeControlledEntityKind.Minion);
            if (Regex.IsMatch(text, @"\b(?:each|every|per)\b[^.;]{0,32}\btotems?\b",
                    RegexOptions.CultureInvariant))
                return CountControlled(NativeControlledEntityKind.Totem);
            if (Regex.IsMatch(text, @"\b(?:each|every|per)\b[^.;]{0,32}\baura\b",
                    RegexOptions.CultureInvariant))
                return schedule.Skills.Values.Count(entry => entry.Casts > 0d
                    && SkillHasNativeTagCore(entry.SkillId, "aura"));
            if (Regex.IsMatch(text, @"\bcommon(?:-quality)? equipment\b",
                    RegexOptions.CultureInvariant))
                return Math.Max(0, commonQualityItemCount);
            if (Regex.IsMatch(text, @"\b(?:each|every|per)\b[^.;]{0,32}\bmastery skills?\b",
                    RegexOptions.CultureInvariant))
                return schedule.Skills.Values.Count(entry => entry.Casts > 0d
                    && SkillHasNativeTagCore(entry.SkillId, "mastery"));
            return NamedStatePresence();
        }
        var multiplier = 1d;
        var monitors = ReadSequence(Read(row, "monitorArr"))
            .Select(ToInt).Where(id => id > 0).ToList();
        if (monitors.Count > 0)
        {
            multiplier = monitors[0] switch
            {
                // Time-average number of graph-proven active controlled units.
                201 => CountControlled(NativeControlledEntityKind.Totem),
                400 => CountControlled(NativeControlledEntityKind.Minion),
                // Candidate loadout relationship, not the currently equipped
                // hero state being replaced by the simulation.
                401 => Math.Max(0, commonQualityItemCount),
                // Number of selected Mastery skills.
                402 => schedule.Skills.Values.Count(entry =>
                    SkillHasNativeTagCore(entry.SkillId, "mastery")),
                // Number of selected Aura skills/effects.
                200 => schedule.Skills.Values.Count(entry =>
                    SkillHasNativeTagCore(entry.SkillId, "aura")),
                // Number of self ailments. The target-dummy preview applies no
                // incoming ailments, so its safe expectation is zero.
                403 => 0d,
                // Current native counter (Mettle/Haste/Fortitude and future
                // counters using the same monitor relation).
                404 when monitors.Count >= 2 => Math.Max(
                    0d,
                    ReadCounter(monitors[1])),
                // Fortify and future named state counters which have no exposed
                // EAttr payload retain one conservative stack only when an
                // actually scheduled skill declares that state relationship.
                405 => NamedStatePresence(),
                _ => InferMonitorFromDescription()
            };
        }

        var clauses = ParseNativeConditionClauses(effect.NativeCondition);
        foreach (var clause in clauses)
        {
            if (clause.Length == 0) continue;
            var conditionFactor = clause[0] switch
            {
                // Acquired/passive ability.
                1000 => 1d,
                // Shield-active. With no incoming damage in the target-dummy
                // model, any scheduled shield production keeps the state live.
                200 when clause.Length >= 2 && clause[1] == 1 =>
                    schedule.Skills.Values.Any(entry =>
                        entry.Casts > 0d && entry.Role.SelfShield > 0d) ? 1d : 0d,
                // Monitor 400 already supplies the active Minion count. These
                // two native clauses are its owner/type gates, not additional
                // probabilities or a second multiplier.
                400 or 401 when monitors.FirstOrDefault() == 400 =>
                    multiplier > 0d ? 1d : 0d,
                // Healthy/Full resource states use the scheduled native costs
                // and regen. Bloodied and afflicted require an incoming-combat
                // state that this deterministic preview does not fabricate.
                101 when clause.Length >= 2 && clause[1] == 2 =>
                    EstimateScheduledFullResourceUptime(schedule, attrData, false),
                101 when clause.Length >= 2 && clause[1] == 3 =>
                    EstimateScheduledFullResourceUptime(schedule, attrData, true),
                101 or 201 => 0d,
                _ => 0d
            };
            multiplier *= conditionFactor;
        }
        return double.IsFinite(multiplier)
            ? Math.Clamp(multiplier, 0d, 100d)
            : 0d;
    }

    private static bool TryReadScaledConditionalPayload(
        string source,
        object attrData,
        HeroFocus focus,
        out string payloadKind,
        out double amount)
    {
        payloadKind = string.Empty;
        amount = 0d;
        var text = NormalizeSkillDependencyText(source);
        var matches = Regex.Matches(text,
            @"(?<!\d)(\d+(?:\.\d+)?)\s*%\s*(?:of\s+)?(?:your\s+)?(physical attack|elemental attack|strength|dexterity|intelligence|crit value|max health|health|max mana|mana)\b",
            RegexOptions.CultureInvariant).Cast<Match>().ToList();
        if (matches.Count == 0) return false;
        var match = matches[^1];
        if (!double.TryParse(match.Groups[1].Value, NumberStyles.Float,
                CultureInfo.InvariantCulture, out var percent)
            || !double.IsFinite(percent) || percent <= 0d) return false;
        var sourceName = match.Groups[2].Value;
        var attrId = sourceName switch
        {
            "physical attack" => 1,
            "elemental attack" => 2,
            "strength" => 11,
            "dexterity" => 12,
            "intelligence" => 13,
            "crit value" => 31,
            "max health" or "health" => 5,
            "max mana" or "mana" => 6,
            _ => 0
        };
        if (attrId <= 0) return false;
        var rawAmount = Math.Max(0d, ReadAttrRequired(attrData, attrId)) * percent / 100d;
        if (!double.IsFinite(rawAmount) || rawAmount <= 0d) return false;

        if (text.Contains("shield", StringComparison.Ordinal)
            || text.Contains("barrier", StringComparison.Ordinal))
        {
            payloadKind = "shield";
            amount = rawAmount;
            return true;
        }
        if (text.Contains("heal", StringComparison.Ordinal)
            || Regex.IsMatch(text, @"\brestore\w*\b[^.;]{0,32}\b(?:health|life)\b",
                RegexOptions.CultureInvariant))
        {
            payloadKind = "heal";
            amount = rawAmount;
            return true;
        }
        if (!text.Contains("damage", StringComparison.Ordinal)
            && !text.Contains("dealing", StringComparison.Ordinal)
            && !text.Contains("deals", StringComparison.Ordinal)) return false;

        var damageType = InferNativeDamageTypeFromText(text);
        if (damageType <= 0)
        {
            var focusedTypes = GetNativeDamageThemeRule(focus)?.DamageTypes;
            if (focusedTypes is { Count: 1 }
                && (sourceName == "elemental attack"
                    || sourceName == "physical attack"))
                damageType = focusedTypes.First();
            else if (sourceName == "elemental attack")
                // A generic elemental payload contributes to the composite
                // elemental objective regardless of which current element owns
                // the table row. Fire is a deterministic representative only.
                damageType = 4;
            else
                // Untyped Strength/Dexterity/Health payloads in the current
                // tables are physical. Physical themes aggregate all 1..3, so
                // this fallback does not fabricate a Pierce or Blunt preference.
                damageType = 1;
        }
        payloadKind = "damage";
        amount = GetManualDamageAmount(
            new Dictionary<int, double> { [damageType] = rawAmount }, focus);
        return amount > 0d;
    }

    private static IncomingPressureProfile CaptureDefensePressureProfile(object hero)
    {
        var failures = new List<string>();
        var attrData = Read(hero, "attrData")
                       ?? throw new InvalidOperationException(
                           "The selected hero has no AttrData for the defense stress snapshot.");
        var maxHealth = Math.Max(1d, ReadAttrRequired(attrData, 5));
        var heroSave = Read(hero, "saveHeroData");
        var attackerLevel = Math.Max(1, ReadNullableInt(heroSave, "level") ?? 1);
        var baseSkill = InvokeInstance(hero, "GetNowBaseSkillData");
        var baseSkillId = ReadNullableInt(Read(baseSkill, "tSkillData"), "id") ?? 0;
        var baseSkillLevel = Math.Max(1, ReadNullableInt(baseSkill, "level") ?? 1);
        var damageByType = new Dictionary<int, double>();
        var attackOpportunities = 0d;
        var source = $"incumbent-base-skill-{baseSkillId}-resource-limited-x{DefenseStressDamageMultiplier:0.##}";
        var roleComplete = true;

        if (baseSkillId > 0)
        {
            try
            {
                var role = ReadNativeSkillRoleProfileCore(
                    hero, baseSkillId, baseSkillLevel, attrData,
                    applyCurrentEquipmentVariant: true,
                    candidateItems: null,
                    includeSummonDetails: false,
                    applyOwnAlwaysOnAbilityAttrs: true);
                var package = BuildSharedSkillPackage(
                    role, Array.Empty<NativeSkillRoleProfile>(), out var schedule);
                foreach (var entry in package.DamageByType)
                    if (entry.Key > 0 && double.IsFinite(entry.Value) && entry.Value > 0d)
                        damageByType[entry.Key] = entry.Value * DefenseStressDamageMultiplier;
                attackOpportunities = schedule.Skills.Values
                    .Select(entry => Math.Max(entry.Hits, entry.Casts))
                    .Where(value => double.IsFinite(value) && value > 0d)
                    .DefaultIfEmpty(0d)
                    .Sum();
                roleComplete = role.IsComplete && package.IsComplete;
                if (!roleComplete && !string.IsNullOrWhiteSpace(package.Failure))
                    failures.Add(package.Failure);
            }
            catch (Exception error)
            {
                roleComplete = false;
                failures.Add($"base skill preview: {error.GetBaseException().Message}");
            }
        }
        else
        {
            roleComplete = false;
            failures.Add("the current base skill is unavailable");
        }

        if (damageByType.Count == 0 || attackOpportunities <= 0d)
        {
            // A non-damaging or temporarily unavailable base-skill preview must
            // never create an invincible target dummy. Fall back to the current
            // final attack attribute, still fixed before any candidate changes.
            var physicalAttack = Math.Max(0d, ReadAttrRequired(attrData, 1));
            var elementalAttack = Math.Max(0d, ReadAttrRequired(attrData, 2));
            var preferredDefenceAttr = physicalAttack >= elementalAttack ? 3 : 4;
            var fallbackDamageType = ReadValues(ReadStatic("TableData", "TDamageTypeDict"))
                .Where(row => (ReadNullableInt(row, "defId") ?? 0) == preferredDefenceAttr)
                .Select(row => ReadNullableInt(row, "id") ?? 0)
                .Where(id => id > 0)
                .OrderBy(id => id)
                .FirstOrDefault();
            if (fallbackDamageType <= 0)
                fallbackDamageType = physicalAttack >= elementalAttack ? 1 : 4;
            attackOpportunities = Math.Max(1d, PerformancePreviewWindowSeconds);
            var attackValue = Math.Max(1d, Math.Max(physicalAttack, elementalAttack));
            damageByType.Clear();
            damageByType[fallbackDamageType] = attackValue
                                                * attackOpportunities
                                                * DefenseStressDamageMultiplier;
            source = $"incumbent-final-attack-fallback-x{DefenseStressDamageMultiplier:0.##}";
            failures.Add("resource-limited base-skill damage was unavailable; final attack fallback used");
            roleComplete = false;
        }

        attackOpportunities = Math.Clamp(
            attackOpportunities, 1d, MaximumPerformancePackageEvents);
        var rawTotal = damageByType.Values.Sum();
        var maximumRawTotal = attackOpportunities
                              * maxHealth
                              * DefenseStressMaximumRawHitHealthFraction;
        var safetyScale = rawTotal > maximumRawTotal && rawTotal > 0d
            ? maximumRawTotal / rawTotal
            : 1d;
        if (safetyScale < 0.999999d)
        {
            foreach (var damageType in damageByType.Keys.ToList())
                damageByType[damageType] *= safetyScale;
            source += $"-per-hit-cap-{DefenseStressMaximumRawHitHealthFraction:P0}";
        }

        var attrLevelRows = ReadValues(ReadStatic("TableData", "TAttrLevelDict"))
            .Where(row => (ReadNullableInt(row, "id") ?? 0) > 0)
            .OrderBy(row => Math.Abs((ReadNullableInt(row, "id") ?? attackerLevel) - attackerLevel))
            .ThenBy(row => ReadNullableInt(row, "id") ?? int.MaxValue)
            .ToList();
        var attrLevel = InvokeStatic("TableData", "getTAttrLevelData", attackerLevel)
                        ?? attrLevelRows.FirstOrDefault();
        var defenceScale = Math.Max(0d,
            Convert.ToDouble(Read(attrLevel, "defence") ?? 0d, CultureInfo.InvariantCulture));
        var dodgeScale = Math.Max(0d,
            Convert.ToDouble(Read(attrLevel, "dodgeValue") ?? 0d, CultureInfo.InvariantCulture));
        if (defenceScale <= 0d)
        {
            defenceScale = Math.Max(1d,
                Math.Max(ReadAttrRequired(attrData, 3), ReadAttrRequired(attrData, 4)));
            failures.Add("native level defence scale was unavailable");
        }
        if (dodgeScale <= 0d)
        {
            dodgeScale = Math.Max(1d, ReadAttrRequired(attrData, 32));
            failures.Add("native level dodge scale was unavailable");
        }

        var lanes = new List<IncomingDamageLane>();
        foreach (var entry in damageByType.OrderBy(entry => entry.Key))
        {
            var damageTypeRow = InvokeStatic("TableData", "getTDamageTypeData", entry.Key);
            var defenceAttrId = ReadNullableInt(damageTypeRow, "defId") ?? 0;
            var resistAttrId = ReadNullableInt(damageTypeRow, "resistId") ?? 0;
            if (damageTypeRow is null)
                failures.Add($"damage type {entry.Key} has no mitigation table row");
            var immunityAttrId = 150 + entry.Key;
            if (InvokeStatic("TableData", "getTAttrData", immunityAttrId) is null)
                immunityAttrId = 0;
            lanes.Add(new IncomingDamageLane(
                entry.Key, Math.Max(0d, entry.Value),
                defenceAttrId, resistAttrId, immunityAttrId));
        }

        var profile = new IncomingPressureProfile(
            source,
            lanes,
            attackOpportunities,
            PerformancePreviewWindowSeconds,
            defenceScale,
            dodgeScale,
            maxHealth,
            attackerLevel,
            roleComplete && failures.Count == 0,
            string.Join("; ", failures.Distinct(StringComparer.Ordinal)));
        Plugin.DiagInfo(
            $"AUTO-GEAR DEFENSE PRESSURE|source={profile.Source}|level={profile.AttackerLevel}"
            + $"|raw30={profile.RawDamage:0.###}|attacks={profile.AttackOpportunities:0.###}"
            + $"|rawPerHit={profile.RawDamage / Math.Max(1d, profile.AttackOpportunities):0.###}"
            + $"|defScale={profile.DefenceScale:0.###}|dodgeScale={profile.DodgeScale:0.###}"
            + $"|types={string.Join(',', profile.DamageLanes.Select(lane => $"{lane.DamageType}:{lane.RawDamage:0.###}/d{lane.DefenceAttrId}/r{lane.ResistAttrId}"))}"
            + $"|complete={profile.IsComplete}|failure={profile.Failure}");
        return profile;
    }

    private static double CalculateExpectedDodgeChance(
        double dodgeRating,
        double dodgeScale,
        bool loseDodge)
    {
        if (loseDodge || !double.IsFinite(dodgeRating) || dodgeRating <= 0d)
            return 0d;
        dodgeScale = double.IsFinite(dodgeScale) && dodgeScale > 0d
            ? dodgeScale
            : 1d;
        return Math.Clamp(dodgeRating / (dodgeRating + dodgeScale), 0d, 0.95d);
    }

    private static double CalculateReductionMultiplier(double rating)
    {
        if (!double.IsFinite(rating)) return 1d;
        return rating >= 0d
            ? 100d / (100d + rating)
            : (100d - rating) / 100d;
    }

    private static double CalculateDefenceMultiplier(
        double defence,
        double defenceScale,
        bool noDefence)
    {
        if (noDefence || !double.IsFinite(defence) || defence == 0d)
            return 1d;
        defenceScale = double.IsFinite(defenceScale) && defenceScale > 0d
            ? defenceScale
            : 1d;
        return defence >= 0d
            ? defenceScale / (defenceScale + defence)
            : 1d + -defence / defenceScale;
    }

    private static DefenseSimulationResult SimulateDefenseWindowCore(
        double maxHealth,
        double healthRegenPerSecond,
        double dodgeRating,
        double dodgeScale,
        double toughness,
        bool toughnessDouble,
        bool loseDodge,
        bool noDefence,
        bool noShield,
        bool noShieldDecay,
        double shieldDecayPercentPerSecond,
        double healingTotal,
        double shieldTotal,
        double deathPreventionSeconds,
        double windowSeconds,
        double attackOpportunities,
        IReadOnlyList<DefenseDamageLane> damageLanes,
        string pressureSource)
    {
        maxHealth = double.IsFinite(maxHealth) ? Math.Max(1d, maxHealth) : 1d;
        windowSeconds = double.IsFinite(windowSeconds)
            ? Math.Max(0.1d, windowSeconds)
            : PerformancePreviewWindowSeconds;
        healthRegenPerSecond = double.IsFinite(healthRegenPerSecond)
            ? Math.Max(0d, healthRegenPerSecond)
            : 0d;
        healingTotal = double.IsFinite(healingTotal) ? Math.Max(0d, healingTotal) : 0d;
        shieldTotal = double.IsFinite(shieldTotal) ? Math.Max(0d, shieldTotal) : 0d;
        deathPreventionSeconds = double.IsFinite(deathPreventionSeconds)
            ? Math.Clamp(deathPreventionSeconds, 0d, windowSeconds)
            : 0d;
        attackOpportunities = double.IsFinite(attackOpportunities)
            ? Math.Max(0d, attackOpportunities)
            : 0d;

        var rawDamage = damageLanes.Sum(lane =>
            double.IsFinite(lane.RawDamage) ? Math.Max(0d, lane.RawDamage) : 0d);
        var dodgeChance = CalculateExpectedDodgeChance(
            dodgeRating, dodgeScale, loseDodge);
        var toughnessValue = Math.Max(0d, double.IsFinite(toughness) ? toughness : 0d)
                             * (toughnessDouble ? 2d : 1d);
        var toughnessMultiplier = CalculateReductionMultiplier(toughnessValue);
        var damageAfterAvoidanceTotal = 0d;
        var mitigatedDamageTotal = 0d;
        foreach (var lane in damageLanes)
        {
            var laneRaw = double.IsFinite(lane.RawDamage)
                ? Math.Max(0d, lane.RawDamage)
                : 0d;
            var afterAvoidance = laneRaw * (1d - dodgeChance);
            damageAfterAvoidanceTotal += afterAvoidance;
            if (lane.Immune) continue;
            mitigatedDamageTotal += afterAvoidance
                                    * CalculateDefenceMultiplier(
                                        lane.Defence, lane.DefenceScale, noDefence)
                                    * CalculateReductionMultiplier(lane.Resistance)
                                    * toughnessMultiplier;
        }
        mitigatedDamageTotal = Math.Max(0d, mitigatedDamageTotal);

        var steps = Math.Max(1, (int)Math.Ceiling(
            windowSeconds * DefenseSimulationStepsPerSecond));
        var stepSeconds = windowSeconds / steps;
        var rawPerStep = rawDamage / steps;
        var afterAvoidancePerStep = damageAfterAvoidanceTotal / steps;
        var incomingPerStep = mitigatedDamageTotal / steps;
        var healPerStep = (healthRegenPerSecond * windowSeconds + healingTotal) / steps;
        var shieldPerStep = noShield ? 0d : shieldTotal / steps;
        var decayRate = noShieldDecay || noShield
            ? 0d
            : Math.Clamp(
                (double.IsFinite(shieldDecayPercentPerSecond)
                    ? Math.Max(0d, shieldDecayPercentPerSecond)
                    : 0d) / 100d,
                0d,
                1d);

        var health = maxHealth;
        var shield = 0d;
        var effectiveHealing = 0d;
        var effectiveShieldGenerated = 0d;
        var shieldAbsorbed = 0d;
        var damageTaken = 0d;
        var processedRaw = 0d;
        var processedAfterAvoidance = 0d;
        var processedMitigated = 0d;
        var bloodiedEntries = 0d;
        var lethalEvents = 0d;
        var wasBloodied = false;
        var deathPreventionUsed = false;
        var deathPreventionRemaining = 0d;
        var survived = true;
        var secondsAlive = windowSeconds;

        for (var step = 0; step < steps; step++)
        {
            if (shieldPerStep > 0d)
            {
                var added = Math.Min(shieldPerStep, Math.Max(0d, maxHealth - shield));
                shield += added;
                effectiveShieldGenerated += added;
            }
            if (healPerStep > 0d)
            {
                var healed = Math.Min(healPerStep, Math.Max(0d, maxHealth - health));
                health += healed;
                effectiveHealing += healed;
            }
            if (shield > 0d && decayRate > 0d)
                shield = Math.Max(0d, shield - shield * decayRate * stepSeconds);

            processedRaw += rawPerStep;
            processedAfterAvoidance += afterAvoidancePerStep;
            processedMitigated += incomingPerStep;
            var remainingDamage = incomingPerStep;
            if (remainingDamage > 0d && shield > 0d)
            {
                var absorbed = Math.Min(shield, remainingDamage);
                shield -= absorbed;
                remainingDamage -= absorbed;
                shieldAbsorbed += absorbed;
            }
            if (remainingDamage > 0d)
            {
                health -= remainingDamage;
                damageTaken += remainingDamage;
            }

            var isBloodied = health > 0d
                             && health <= maxHealth * BloodiedHealthFraction;
            if (isBloodied && !wasBloodied) bloodiedEntries += 1d;
            wasBloodied = isBloodied;

            if (health <= 0d)
            {
                if (deathPreventionRemaining > 0d)
                {
                    health = 1d;
                }
                else if (!deathPreventionUsed && deathPreventionSeconds > 0d)
                {
                    lethalEvents += 1d;
                    deathPreventionUsed = true;
                    deathPreventionRemaining = deathPreventionSeconds;
                    health = 1d;
                    wasBloodied = true;
                }
                else
                {
                    lethalEvents += 1d;
                    health = 0d;
                    survived = false;
                    secondsAlive = Math.Min(windowSeconds, (step + 1) * stepSeconds);
                    break;
                }
            }
            if (deathPreventionRemaining > 0d)
                deathPreventionRemaining = Math.Max(
                    0d, deathPreventionRemaining - stepSeconds);
        }

        var timeRatio = Math.Clamp(secondsAlive / windowSeconds, 0d, 1d);
        var reserveRatio = survived
            ? Math.Clamp((health + shield) / maxHealth, 0d, 2d)
            : 0d;
        var prevented = Math.Max(0d, processedRaw - processedMitigated);
        var handledRatio = processedRaw > 0d
            ? Math.Clamp(
                (prevented + shieldAbsorbed + effectiveHealing)
                / processedRaw,
                0d,
                1.5d)
            : 0d;
        // Finishing the complete window is deliberately discontinuous: a
        // loadout that is alive at 30 seconds must always outrank one that died
        // just before it. Reserve and actually consumed recovery then order
        // survivors without rewarding unused overheal or over-shield.
        var objective = timeRatio * 80d
                        + (survived ? 100d : 0d)
                        + reserveRatio * 30d
                        + handledRatio * 20d;
        var hitOpportunities = attackOpportunities
                               * (1d - dodgeChance)
                               * timeRatio;
        return new DefenseSimulationResult(
            survived,
            secondsAlive,
            Math.Max(0d, health),
            Math.Max(0d, shield),
            processedRaw,
            processedAfterAvoidance,
            Math.Max(0d, damageTaken),
            prevented,
            Math.Max(0d, shieldAbsorbed),
            Math.Max(0d, effectiveHealing),
            Math.Max(0d, effectiveShieldGenerated),
            bloodiedEntries,
            lethalEvents,
            Math.Max(0d, hitOpportunities),
            Math.Max(0d, objective),
            pressureSource ?? string.Empty);
    }

    private static DefenseSimulationResult SimulateDefenseWindow(
        object attrData,
        IncomingPressureProfile pressure,
        double healingTotal,
        double shieldTotal,
        double deathPreventionSeconds)
    {
        var noDefence = ReadAttrRequired(attrData, 200) > 0d;
        var lanes = pressure.DamageLanes.Select(lane => new DefenseDamageLane(
            lane.DamageType,
            lane.RawDamage,
            lane.DefenceAttrId > 0 ? ReadAttrRequired(attrData, lane.DefenceAttrId) : 0d,
            lane.ResistAttrId > 0 ? ReadAttrRequired(attrData, lane.ResistAttrId) : 0d,
            pressure.DefenceScale,
            lane.ImmunityAttrId > 0 && ReadAttrRequired(attrData, lane.ImmunityAttrId) > 0d))
            .ToList();
        return SimulateDefenseWindowCore(
            ReadAttrRequired(attrData, 5),
            ReadAttrRequired(attrData, 7),
            ReadAttrRequired(attrData, 32),
            pressure.DodgeScale,
            ReadAttrRequired(attrData, 86),
            ReadAttrRequired(attrData, 202) > 0d,
            ReadAttrRequired(attrData, 187) > 0d,
            noDefence,
            ReadAttrRequired(attrData, 201) > 0d,
            ReadAttrRequired(attrData, 188) > 0d,
            ReadAttrRequired(attrData, 26),
            healingTotal,
            shieldTotal,
            deathPreventionSeconds,
            pressure.WindowSeconds,
            pressure.AttackOpportunities,
            lanes,
            pressure.Source);
    }

    private static DefenseTriggerState BuildDefenseTriggerState(
        object attrData,
        IncomingPressureProfile pressure,
        double survivalFraction = 1d,
        double bloodiedEntries = 0d,
        double lethalEvents = 0d)
    {
        survivalFraction = Math.Clamp(
            double.IsFinite(survivalFraction) ? survivalFraction : 0d,
            0d,
            1d);
        var dodgeChance = CalculateExpectedDodgeChance(
            ReadAttrRequired(attrData, 32),
            pressure.DodgeScale,
            ReadAttrRequired(attrData, 187) > 0d);
        var attacked = Math.Max(0d, pressure.AttackOpportunities) * survivalFraction;
        var hits = attacked * (1d - dodgeChance);
        var damageEvents = pressure.RawDamage > 0d ? hits : 0d;
        return new DefenseTriggerState(
            attacked,
            hits,
            damageEvents,
            Math.Max(0d, bloodiedEntries),
            Math.Max(0d, lethalEvents));
    }

    private static bool DefenseTriggerStateApproximatelyEquals(
        DefenseTriggerState left,
        DefenseTriggerState right)
        => Math.Abs(left.AttackedOpportunities - right.AttackedOpportunities) < 0.000001d
           && Math.Abs(left.HitOpportunities - right.HitOpportunities) < 0.000001d
           && Math.Abs(left.DamageEvents - right.DamageEvents) < 0.000001d
           && Math.Abs(left.BloodiedEntries - right.BloodiedEntries) < 0.000001d
           && Math.Abs(left.LethalEvents - right.LethalEvents) < 0.000001d;

    private static DefenseWindowEvaluation EvaluateDefenseWindow(
        object baseAttr,
        NativeAbilityPackage abilities,
        NativeSkillPackageSchedule schedule,
        HeroEffectProfile profile,
        IncomingPressureProfile pressure,
        double baseSelfHealing,
        double baseSelfShield)
    {
        var triggers = BuildDefenseTriggerState(baseAttr, pressure);
        var conditional = new ExpectedConditionalPackage(
            0d, 0d, 0d, 0d, 0d, 0d, 0d);
        var adjustedAttr = baseAttr;
        var simulation = SimulateDefenseWindow(
            adjustedAttr, pressure, baseSelfHealing, baseSelfShield, 0d);
        // Incoming-state effects can change the state that triggers them. Three
        // bounded deterministic passes are enough to feed hit, Bloodied and
        // lethal events back into the same 30-second window without an
        // unbounded retry loop.
        for (var pass = 0; pass < 3; pass++)
        {
            conditional = EvaluateExpectedConditionalPackage(
                abilities, schedule, baseAttr, profile, triggers);
            adjustedAttr = CreateExpectedConditionalAdjustedAttr(
                baseAttr, conditional);
            simulation = SimulateDefenseWindow(
                adjustedAttr,
                pressure,
                Math.Max(0d, baseSelfHealing + conditional.SelfHeal),
                Math.Max(0d, baseSelfShield + conditional.SelfShield),
                conditional.DeathPreventionSeconds);
            var next = BuildDefenseTriggerState(
                adjustedAttr,
                pressure,
                simulation.SecondsAlive / Math.Max(0.1d, pressure.WindowSeconds),
                simulation.BloodiedEntries,
                simulation.LethalEvents);
            if (DefenseTriggerStateApproximatelyEquals(triggers, next))
            {
                triggers = next;
                break;
            }
            triggers = next;
        }
        return new DefenseWindowEvaluation(
            conditional, adjustedAttr, simulation, triggers);
    }

    private static bool TryReadDeathPreventionSeconds(
        string normalizedText,
        out double seconds)
    {
        seconds = 0d;
        if (!Regex.IsMatch(
                normalizedText,
                @"\b(?:resist\w*\s+death|prevent\w*\s+death|cannot\s+die|can't\s+die|death\s+immun\w*)\b",
                RegexOptions.CultureInvariant)) return false;
        var match = Regex.Match(
            normalizedText,
            @"\b(?:for\s+)?(\d+(?:\.\d+)?)\s*(?:s|sec|secs|second|seconds)\b",
            RegexOptions.CultureInvariant);
        return match.Success
               && double.TryParse(match.Groups[1].Value, NumberStyles.Float,
                   CultureInfo.InvariantCulture, out seconds)
               && double.IsFinite(seconds)
               && seconds > 0d;
    }

    private static bool IsExplicitSelfRecoveryPayload(
        string normalizedText,
        string payloadKind,
        bool wearerTriggered)
    {
        if (payloadKind is not ("heal" or "shield")) return false;
        var text = NormalizeSkillDependencyText(normalizedText);
        if (text.Length == 0) return false;
        var includesSelf = Regex.IsMatch(
            text,
            @"\b(?:self|yourself|your\s+(?:health|shield)|heal\w*\s+you|restore\w*\s+(?:you|your)|recover\w*\s+(?:you|your)|you\s+(?:gain|gains|receive|receives))\b",
            RegexOptions.CultureInvariant);
        if (includesSelf) return true;
        var namesOtherRecipient = Regex.IsMatch(
            text,
            @"\b(?:all(?:ied|y)\s+targets?|allies|ally|party\s+members?|minions?|summons?|companions?|additional\s+targets?)\b",
            RegexOptions.CultureInvariant);
        // An incoming-state equipment hook belongs to the wearer unless its
        // native description explicitly names another recipient. This covers
        // generic "restore X% Health when hit" effects without assuming that
        // party/ally recovery also heals the wearer.
        return wearerTriggered && !namesOtherRecipient;
    }

    private static ExpectedConditionalPackage EvaluateExpectedConditionalPackage(
        NativeAbilityPackage package,
        NativeSkillPackageSchedule schedule,
        object attrData,
        HeroEffectProfile profile,
        DefenseTriggerState? defenseTriggers = null)
    {
        var structural = 0d;
        var damage = 0d;
        var heal = 0d;
        var shield = 0d;
        var selfHeal = 0d;
        var selfShield = 0d;
        var support = 0d;
        var defense = 0d;
        var minion = 0d;
        var deathPreventionSeconds = 0d;
        var averageAttrDeltas = new Dictionary<int, double>();
        var deferredParentStatePayloads = new List<(
            NativeConditionalEffect Effect,
            NativeConditionalAttributePayload Payload)>();
        var remainingBaseTime = Math.Max(0d, schedule.BaseActionSecondsAvailable);
        var remainingBaseUsedTime = Math.Max(0d, schedule.BaseActionSecondsUsed);
        defenseTriggers ??= new DefenseTriggerState(0d, 0d, 0d, 0d, 0d);

        NativeScheduledSkill? baseScheduled = null;
        if (profile.PreviewBaseSkillId > 0)
            schedule.Skills.TryGetValue(profile.PreviewBaseSkillId, out baseScheduled);
        var baseDamagePerSecond = baseScheduled is not null
                                  && baseScheduled.Role.CastOpportunities > 0d
                                  && baseScheduled.Role.ActionSecondsPerCast > 0d
            ? GetManualDamageAmount(baseScheduled.Role.DamageByType, profile.Focus)
              / baseScheduled.Role.CastOpportunities
              * Math.Clamp(baseScheduled.Role.Confidence, 0d, 1d)
              / baseScheduled.Role.ActionSecondsPerCast
            : 0d;
        foreach (var effect in package.ConditionalEffects ?? Array.Empty<NativeConditionalEffect>())
        {
            var text = NormalizeSkillDependencyText(effect.Text);
            var clauses = ParseNativeConditionClauses(effect.NativeCondition);
            var orderedDependencies = InferOrderedSkillDependenciesFromText(effect.Text, profile.JobId);
            var tagDependencies = InferSkillTagDependenciesFromText(effect.Text);
            var expandsHealingTargets = TryReadAdditionalHealingTargetCount(
                text, out var additionalHealingTargets);
            var expandedHealingSkillId = expandsHealingTargets
                                         && orderedDependencies.Count >= 2
                ? orderedDependencies.Last()
                : 0;
            var cooldownReset = Regex.IsMatch(text,
                @"\breset\w*\b[^.;]{0,36}\bcooldown\b|\bcooldown\b[^.;]{0,36}\breset\w*\b",
                RegexOptions.CultureInvariant);
            var skipsCooldown = text.Contains("does not trigger its cooldown", StringComparison.Ordinal)
                                || text.Contains("does not trigger cooldown", StringComparison.Ordinal)
                                || text.Contains("not enter cooldown", StringComparison.Ordinal);
            var cooldownReduction = TryReadCooldownReductionSeconds(text, out var reductionSeconds);
            var cooldownReductionPercent = TryReadCooldownReductionPercent(
                text, out var cooldownReductionPercentValue);
            var cooldownSpeedIncrease = TryReadCooldownSpeedIncreasePercent(
                text, out var cooldownSpeedPercent);
            var triggersOtherSkill = orderedDependencies.Count >= 2
                                     && Regex.IsMatch(text,
                                         @"\b(?:also\s+)?trigger\w*\b",
                                         RegexOptions.CultureInvariant);
            var targetSkillId = cooldownReset || cooldownReduction
                                || cooldownReductionPercent || cooldownSpeedIncrease
                                || skipsCooldown || triggersOtherSkill
                ? orderedDependencies.LastOrDefault()
                : 0;
            var sourceSkillId = orderedDependencies.FirstOrDefault();
            if (skipsCooldown && targetSkillId > 0) sourceSkillId = targetSkillId;
            if (targetSkillId > 0
                && orderedDependencies.Count == 1
                && tagDependencies.Count > 0)
            {
                // "Cast a Utility Skill: reduce [Ice Barrier] cooldown" names
                // only the target. The source is the native tag group, not the
                // target skill repeated as both ends of the relationship.
                sourceSkillId = 0;
            }

            var probability = 1d;
            if (!TryReadNativeConditionProbability(effect.NativeCondition, out probability))
                TryReadTextChanceProbability(text, out probability);
            if (text.Contains("critically strikes", StringComparison.Ordinal)
                || Regex.IsMatch(text, @"\bon [^.;]{0,24}\bcrit\b", RegexOptions.CultureInvariant))
                probability *= Math.Clamp(PercentRate(ReadAttrRequired(attrData, 31)), 0d, 1d);
            foreach (var clause in clauses)
            {
                if (clause.Length == 0) continue;
                probability *= clause[0] switch
                {
                    101 when clause.Length >= 2 && clause[1] == 1 =>
                        defenseTriggers.BloodiedEntries > 0d ? 1d : 0d,
                    101 when clause.Length >= 2 && clause[1] == 2 =>
                        EstimateScheduledFullResourceUptime(schedule, attrData, false),
                    101 when clause.Length >= 2 && clause[1] == 3 =>
                        EstimateScheduledFullResourceUptime(schedule, attrData, true),
                    200 when clause.Length >= 2 && clause[1] == 1 =>
                        schedule.Skills.Values.Any(entry =>
                            entry.Casts > 0d && entry.Role.SelfShield > 0d) ? 1d : 0d,
                    201 => 0d,
                    _ => 1d
                };
            }
            probability = Math.Clamp(probability, 0d, 1d);

            var nativeCast = clauses.Any(clause => clause.Length > 0 && clause[0] == 300);
            var nativeHit = clauses.Any(clause => clause.Length > 0 && clause[0] == 601);
            var nativeAcquire = clauses.Any(clause => clause.Length > 0 && clause[0] == 1000);
            var incomingAttacked = Regex.IsMatch(text,
                @"\b(?:when|after|whenever|each time)\s+(?:you\s+are\s+)?attacked\b",
                RegexOptions.CultureInvariant);
            var incomingHit = Regex.IsMatch(text,
                @"\b(?:when|after|whenever|each time)\s+(?:you\s+are\s+)?hit\b",
                RegexOptions.CultureInvariant);
            var incomingDamageEvent = Regex.IsMatch(text,
                @"\b(?:when|after|whenever|each time)\s+you\s+(?:take|takes|taking)\s+damage\b",
                RegexOptions.CultureInvariant)
                                      || clauses.Any(clause =>
                                          clause.Length > 0 && clause[0] == 800);
            var minionHitEvent = Regex.IsMatch(text,
                @"\bminions?'?s?\s+hits?\b|\bwhen\s+(?:your\s+)?minions?\b[^.;]{0,24}\bhits?\b",
                RegexOptions.CultureInvariant);
            var textHit = text.Contains("critically strikes", StringComparison.Ordinal)
                          || Regex.IsMatch(text,
                              @"\b(?:on|when|each time)\b[^.;]{0,52}\bhits?\b|\bhits?\b[^.;]{0,36}\bchance\b",
                              RegexOptions.CultureInvariant);
            var textCast = Regex.IsMatch(text,
                @"\b(?:cast|casts|casting|use)\b", RegexOptions.CultureInvariant);
            var summonEvent = Regex.IsMatch(text,
                @"\b(?:summon|summons|summoning)\b[^.;]{0,32}\bminions?\b",
                RegexOptions.CultureInvariant)
                              || clauses.Any(clause => clause.Length > 0 && clause[0] == 400);
            var totemPlacementEvent = Regex.IsMatch(text,
                @"\b(?:when|whenever|each time|after)\b[^.;]{0,36}\b(?:place|places|placing|plant|plants|planting)\w*\b[^.;]{0,20}\btotems?\b",
                RegexOptions.CultureInvariant);
            var shieldGainEvent = Regex.IsMatch(text,
                @"\b(?:when|whenever|each time|after)\b[^.;]{0,36}\b(?:you\s+)?(?:gain|gains|gaining|receive|receives)\b[^.;]{0,20}\b(?:a\s+)?(?:shield|barrier)\b",
                RegexOptions.CultureInvariant);
            var namedStateGainEvent = sourceSkillId > 0
                                      && sourceSkillId != targetSkillId
                                      && Regex.IsMatch(text,
                                          @"\bwhen\b[^.;]{0,36}\b(?:gain|gains|gaining|receive|receives)\b",
                                          RegexOptions.CultureInvariant);
            var hasSkillBoundAttributePayload = sourceSkillId > 0
                                                && (effect.AttributePayloads
                                                    ?? Array.Empty<NativeConditionalAttributePayload>())
                                                .Any(payload => !payload.ScaleFromParentState);

            IEnumerable<NativeScheduledSkill> eligible = schedule.Skills.Values;
            if (sourceSkillId > 0)
                eligible = schedule.Skills.TryGetValue(sourceSkillId, out var explicitSource)
                    ? new[] { explicitSource }
                    : Array.Empty<NativeScheduledSkill>();
            else
            {
                var categories = clauses
                    .Where(clause => clause.Length >= 2 && clause[0] is 303 or 602)
                    .SelectMany(clause => clause.Skip(1))
                    .Where(id => id > 0)
                    .ToHashSet();
                var nativeTags = clauses
                    .Where(clause => clause.Length >= 2 && clause[0] is 304 or 603)
                    .SelectMany(clause => clause.Skip(1))
                    .Where(id => id > 0)
                    .ToHashSet();
                if (categories.Count > 0 || nativeTags.Count > 0)
                    eligible = eligible.Where(entry =>
                    {
                        var tags = ReadNativeSkillTagIdsCore(entry.SkillId);
                        return (categories.Count == 0 || tags.Overlaps(categories))
                               && (nativeTags.Count == 0 || tags.Overlaps(nativeTags));
                    });
                else
                {
                    foreach (var tag in tagDependencies)
                        eligible = tag switch
                        {
                            "mastery-or-utility" => eligible.Where(entry =>
                                SkillHasNativeTagCore(entry.SkillId, "mastery", "utility")),
                            "shield-producer" => eligible.Where(entry => entry.Role.Shield > 0d),
                            "minion" => eligible.Where(entry => entry.Role.Summon),
                            _ => eligible.Where(entry => SkillHasNativeTagCore(entry.SkillId, tag))
                        };
                }
            }
            var eligibleSkills = eligible.ToList();

            var everySeconds = Regex.Match(text,
                @"\bevery\s+(\d+(?:\.\d+)?)\s*(?:s|sec|secs|second|seconds)\b",
                RegexOptions.CultureInvariant);
            var everyCasts = Regex.Match(text,
                @"\bevery\s+(\d+)\s+casts?\b", RegexOptions.CultureInvariant);
            var auraCount = schedule.Skills.Values.Count(entry =>
                SkillHasNativeTagCore(entry.SkillId, "aura"));
            var opportunities = 0d;
            var triggerKind = "unknown";
            var incomingThresholdStateEvent = Regex.IsMatch(text,
                @"\b(?:taking lethal damage|upon entering bloodied|when you become bloodied)\b",
                RegexOptions.CultureInvariant);
            if (cooldownSpeedIncrease)
            {
                opportunities = auraCount > 0 ? 1d : 0d;
                triggerKind = "aura-count";
            }
            else if (cooldownReductionPercent)
            {
                opportunities = 1d;
                triggerKind = "static-cooldown-reduction";
            }
            else if (incomingAttacked)
            {
                opportunities = defenseTriggers.AttackedOpportunities;
                triggerKind = "incoming-attack";
            }
            else if (incomingHit)
            {
                opportunities = defenseTriggers.HitOpportunities;
                triggerKind = "incoming-hit";
            }
            else if (incomingDamageEvent)
            {
                opportunities = defenseTriggers.DamageEvents;
                triggerKind = "incoming-damage";
            }
            else if (incomingThresholdStateEvent)
            {
                var bloodied = text.Contains("bloodied", StringComparison.Ordinal);
                opportunities = bloodied
                    ? defenseTriggers.BloodiedEntries
                    : defenseTriggers.LethalEvents;
                triggerKind = bloodied
                    ? "incoming-bloodied"
                    : "incoming-lethal";
            }
            else if (minionHitEvent)
            {
                opportunities = eligibleSkills
                    .Where(entry => entry.Role.Summon)
                    .Sum(entry => Math.Max(entry.Hits, entry.Casts));
                triggerKind = "minion-hit";
            }
            else if (everySeconds.Success
                && !Regex.IsMatch(text,
                    @"\b(?:taking lethal damage|when attacked|when you are attacked|when hit)\b",
                    RegexOptions.CultureInvariant)
                && double.TryParse(everySeconds.Groups[1].Value, NumberStyles.Float,
                    CultureInfo.InvariantCulture, out var interval)
                && double.IsFinite(interval) && interval > 0d)
            {
                opportunities = Math.Floor(
                    Math.Max(0d, PerformancePreviewWindowSeconds - 0.0000001d) / interval);
                triggerKind = "timer";
            }
            else if (summonEvent)
            {
                opportunities = eligibleSkills.Where(entry => entry.Role.Summon).Sum(entry => entry.Casts);
                triggerKind = "summon";
            }
            else if (text.Contains("dies", StringComparison.Ordinal)
                     && eligibleSkills.Any(entry => entry.Role.Summon))
            {
                opportunities = eligibleSkills.Where(entry => entry.Role.Summon)
                    .Sum(entry => entry.Casts);
                triggerKind = "summoned-entity-death";
            }
            else if (totemPlacementEvent)
            {
                opportunities = eligibleSkills
                    .Where(entry => entry.Role.ControlledEntityKinds.HasFlag(
                        NativeControlledEntityKind.Totem))
                    .Sum(entry => entry.Casts);
                triggerKind = "totem-placement";
            }
            else if (shieldGainEvent)
            {
                opportunities = schedule.Skills.Values
                    .Where(entry => entry.Role.SelfShield > 0d)
                    .Sum(entry => entry.Casts);
                triggerKind = "shield-gain";
            }
            else if (namedStateGainEvent)
            {
                opportunities = eligibleSkills.Sum(entry => entry.Casts);
                triggerKind = "named-state-gain";
            }
            else if (nativeHit || textHit)
            {
                opportunities = eligibleSkills.Sum(entry => entry.Hits);
                triggerKind = "hit";
            }
            else if (nativeCast || textCast
                     // Some table-authored set hooks use the compact form
                     // "[source skill] has a N% chance to reset [target skill]
                     // cooldown" without the word cast/use. The ordered source
                     // dependency is nevertheless an explicit per-use trigger.
                     || (sourceSkillId > 0
                         && sourceSkillId != targetSkillId
                         && (cooldownReset || cooldownReduction || triggersOtherSkill)))
            {
                opportunities = eligibleSkills.Sum(entry => entry.Casts);
                triggerKind = "cast";
            }
            else if (hasSkillBoundAttributePayload)
            {
                opportunities = eligibleSkills.Sum(entry => entry.Casts);
                triggerKind = "skill-bound-payload";
            }
            else if (expandsHealingTargets && orderedDependencies.Count < 2)
            {
                // A duration-free global recipient modifier is acquired once
                // and remains active. The measured healing expansion below is
                // applied at full coverage to all scheduled healing skills.
                opportunities = 1d;
                triggerKind = "permanent-healing-targets";
            }
            else if (probability < 0.999999d && tagDependencies.Count > 0)
            {
                // A permanent per-hit/per-cast modifier can describe its chance
                // without the word "hit" (for example, Basic skills ignoring
                // defense). One representative opportunity preserves the exact
                // probability instead of saturating it with the total hit count.
                opportunities = 1d;
                triggerKind = "tagged-chance-modifier";
            }
            else if (text.StartsWith("always ", StringComparison.Ordinal)
                     || text.Contains(" always ", StringComparison.Ordinal))
            {
                opportunities = 1d;
                triggerKind = "always";
            }
            else if (nativeAcquire
                     && !Regex.IsMatch(text,
                         @"\b(?:when|whenever|each time|every|upon|after)\b",
                         RegexOptions.CultureInvariant))
            {
                // Condition 1000 registers a passive listener; it is not by
                // itself a combat activation. Only a payload with no declared
                // event is applied once at acquisition (for example a fixed
                // permanent stack). Event-driven passives stay on their real
                // shield/cast/hit/timer branch above or remain zero.
                opportunities = 1d;
                triggerKind = "acquire";
            }

            if (everyCasts.Success
                && int.TryParse(everyCasts.Groups[1].Value, NumberStyles.Integer,
                    CultureInfo.InvariantCulture, out var castDivisor)
                && castDivisor > 0)
            {
                opportunities = Math.Floor(Math.Max(0d, opportunities) / castDivisor);
                triggerKind += $"/{castDivisor}-casts";
            }
            opportunities = Math.Max(0d, opportunities);
            var expectedActivations = opportunities * probability;
            if (effect.NativeCooldownSeconds > 0d)
                expectedActivations = Math.Min(expectedActivations,
                    Math.Ceiling(PerformancePreviewWindowSeconds / effect.NativeCooldownSeconds));
            expectedActivations = Math.Max(0d, expectedActivations);
            if (expectedActivations > 0d
                && TryReadDeathPreventionSeconds(text, out var preventionSeconds))
                deathPreventionSeconds = Math.Max(
                    deathPreventionSeconds,
                    preventionSeconds * Math.Clamp(expectedActivations, 0d, 1d));

            var exactPayload = false;
            var statePayloads = (effect.AttributePayloads
                                 ?? Array.Empty<NativeConditionalAttributePayload>())
                .Where(payload => payload.ScaleFromParentState)
                .ToList();
            foreach (var payload in statePayloads)
                deferredParentStatePayloads.Add((effect, payload));
            var exactNativeAttributePayload = statePayloads.Count > 0;
            var effectDamage = 0d;
            var effectHeal = 0d;
            var effectShield = 0d;
            var effectSelfHeal = 0d;
            var effectSelfShield = 0d;
            if (expectedActivations > 0d
                && TryReadScaledConditionalPayload(
                    effect.Text, attrData, profile.Focus, out var payloadKind, out var payloadAmount))
            {
                exactPayload = true;
                var selfRecovery = IsExplicitSelfRecoveryPayload(
                    text,
                    payloadKind,
                    incomingAttacked || incomingHit || incomingDamageEvent
                                     || incomingThresholdStateEvent);
                switch (payloadKind)
                {
                    case "damage": effectDamage += payloadAmount * expectedActivations; break;
                    case "heal":
                        effectHeal += payloadAmount * expectedActivations;
                        if (selfRecovery) effectSelfHeal += payloadAmount * expectedActivations;
                        break;
                    case "shield":
                        effectShield += payloadAmount * expectedActivations;
                        if (selfRecovery) effectSelfShield += payloadAmount * expectedActivations;
                        break;
                }
            }

            var exactSkillOutput = false;
            if (expectedActivations > 0d && targetSkillId > 0
                && schedule.Skills.TryGetValue(targetSkillId, out var target))
            {
                var extraCasts = expectedActivations;
                if (skipsCooldown && sourceSkillId == targetSkillId)
                    extraCasts = probability >= 0.999999d
                        ? double.PositiveInfinity
                        : target.Casts * probability / Math.Max(0.000001d, 1d - probability);
                else if (cooldownSpeedIncrease)
                    extraCasts = target.Casts
                                 * cooldownSpeedPercent / 100d
                                 * Math.Max(0, auraCount);
                else if (cooldownReductionPercent)
                    extraCasts = target.Casts
                                 * (1d / Math.Max(
                                     0.01d,
                                     1d - cooldownReductionPercentValue / 100d)
                                    - 1d);
                else if (cooldownReduction)
                {
                    var cycleSeconds = target.Role.CastOpportunities > 0d
                        ? PerformancePreviewWindowSeconds / target.Role.CastOpportunities
                        : PerformancePreviewWindowSeconds;
                    extraCasts = expectedActivations * reductionSeconds / Math.Max(0.01d, cycleSeconds);
                }

                var consumesActionTime = cooldownReset || cooldownReduction
                                         || cooldownReductionPercent
                                         || cooldownSpeedIncrease || skipsCooldown;
                var actionSeconds = Math.Max(0.01d, target.Role.ActionSecondsPerCast);
                var displacedBaseSeconds = 0d;
                if (consumesActionTime)
                {
                    var maximumExtra = remainingBaseTime / actionSeconds;
                    extraCasts = Math.Min(extraCasts, Math.Max(0d, maximumExtra));
                    var usedSeconds = Math.Max(0d, extraCasts * actionSeconds);
                    displacedBaseSeconds = Math.Min(remainingBaseUsedTime, usedSeconds);
                    remainingBaseTime = Math.Max(0d, remainingBaseTime - usedSeconds);
                    remainingBaseUsedTime = Math.Max(0d, remainingBaseUsedTime - displacedBaseSeconds);
                }
                if (double.IsFinite(extraCasts) && extraCasts > 0d
                    && target.Role.CastOpportunities > 0d)
                {
                    var confidence = Math.Clamp(target.Role.Confidence, 0d, 1d);
                    var divisor = target.Role.CastOpportunities;
                    effectDamage += GetManualDamageAmount(target.Role.DamageByType, profile.Focus)
                                    / divisor * confidence * extraCasts
                                    - baseDamagePerSecond * displacedBaseSeconds;
                    effectHeal += target.Role.Heal / divisor * confidence * extraCasts;
                    effectShield += target.Role.Shield / divisor * confidence * extraCasts;
                    effectSelfHeal += target.Role.SelfHeal / divisor * confidence * extraCasts;
                    effectSelfShield += target.Role.SelfShield / divisor * confidence * extraCasts;
                    support += target.Role.AbilitySupport / divisor * confidence * extraCasts;
                    defense += target.Role.AbilityDefense / divisor * confidence * extraCasts;
                    minion += (target.Role.AbilityMinion + target.Role.SummonDamage
                                                       + target.Role.SummonSurvival * 0.35d)
                              / divisor * confidence * extraCasts;
                    exactSkillOutput = true;
                    triggerKind += consumesActionTime ? "/cooldown" : "/trigger";
                }
            }

            var coverage = 0d;
            var expectedActiveStacks = 0d;
            if (expectedActivations > 0d)
            {
                var stackLimit = Math.Max(1, effect.NativeStackLimit);
                var hasTextDuration = TryReadConditionalDurationSeconds(
                    text, out var textDuration);
                var activeDuration = hasTextDuration
                    ? textDuration
                    : effect.NativeDurationSeconds > 0d
                        ? effect.NativeDurationSeconds
                        : 0d;
                if (activeDuration > 0d)
                {
                    expectedActiveStacks = Math.Min(
                        stackLimit,
                        expectedActivations * activeDuration
                        / PerformancePreviewWindowSeconds);
                }
                else if (effect.NativeDurationSeconds < 0d)
                {
                    // Permanent stacks accumulate through the window. Use the
                    // expected time-average stack count, capped by the native
                    // stack limit, instead of assigning zero or full stacks for
                    // the entire measurement.
                    expectedActiveStacks = expectedActivations <= stackLimit
                        ? expectedActivations * 0.5d
                        : stackLimit * (1d - stackLimit
                            / (2d * Math.Max(expectedActivations, 0.000001d)));
                }
                else
                {
                    // Duration-free opaque hooks retain a conservative partial
                    // activation rather than gaining a fabricated stack life.
                    expectedActiveStacks = Math.Min(
                        1d, expectedActivations / stackLimit);
                }
                expectedActiveStacks = Math.Clamp(
                    expectedActiveStacks, 0d, stackLimit);
                coverage = expectedActiveStacks / stackLimit;
                foreach (var payload in effect.AttributePayloads
                             ?? Array.Empty<NativeConditionalAttributePayload>())
                {
                    if (payload.ScaleFromParentState) continue;
                    var payloadStackLimit = Math.Max(1, payload.NativeStackLimit);
                    double payloadAverageStacks;
                    if (payload.NativeDurationSeconds > 0d)
                    {
                        payloadAverageStacks = Math.Min(
                            payloadStackLimit,
                            expectedActivations * payload.NativeDurationSeconds
                            / PerformancePreviewWindowSeconds);
                    }
                    else if (payload.NativeDurationSeconds < 0d)
                    {
                        payloadAverageStacks = triggerKind == "acquire"
                            ? Math.Min(1d, expectedActivations)
                            : expectedActivations <= payloadStackLimit
                                ? expectedActivations * 0.5d
                                : payloadStackLimit * (1d - payloadStackLimit
                                    / (2d * Math.Max(expectedActivations, 0.000001d)));
                    }
                    else
                    {
                        continue;
                    }
                    payloadAverageStacks = Math.Clamp(
                        payloadAverageStacks, 0d, payloadStackLimit);
                    if (payloadAverageStacks <= 0d) continue;
                    foreach (var entry in payload.AttrDeltas)
                        averageAttrDeltas[entry.Key] = averageAttrDeltas.GetValueOrDefault(entry.Key)
                                                       + entry.Value * payloadAverageStacks;
                    exactNativeAttributePayload = true;
                }
                if (coverage > 0d && additionalHealingTargets > 0d)
                {
                    // Role.Heal is the native 30-second output for the skill's
                    // original recipient. Scale is the shared action/resource
                    // schedule (and already contains confidence). Multiplying
                    // that measured baseline by the explicit extra-recipient
                    // count and conditional uptime models the relationship
                    // without inventing a skill-specific coefficient.
                    var scheduledBaselineHeal = expandedHealingSkillId > 0
                                                && schedule.Skills.TryGetValue(
                                                    expandedHealingSkillId,
                                                    out var expandedHealingSkill)
                        ? Math.Max(0d, expandedHealingSkill.Role.Heal)
                          * Math.Max(0d, expandedHealingSkill.Scale)
                        : schedule.Skills.Values.Sum(skill =>
                            Math.Max(0d, skill.Role.Heal)
                            * Math.Max(0d, skill.Scale));
                    var expandedHeal = scheduledBaselineHeal
                                       * additionalHealingTargets
                                       * coverage;
                    if (double.IsFinite(expandedHeal) && expandedHeal > 0d)
                    {
                        effectHeal += expandedHeal;
                        exactSkillOutput = true;
                        triggerKind += "/additional-healing-targets";
                    }
                }
                if (!exactPayload && !exactSkillOutput && !exactNativeAttributePayload)
                    structural += effect.PerActivationScore
                                  * expectedActiveStacks;
            }
            damage += effectDamage;
            heal += effectHeal;
            shield += effectShield;
            selfHeal += effectSelfHeal;
            selfShield += effectSelfShield;
#if PATHOFIDLE_RUNTIME_TEST
            Plugin.DiagInfo(
                $"AUTO-GEAR EXPECTED CONDITION|ability={effect.AbilityId}"
                + $"|trigger={triggerKind}"
                + $"|opportunities={opportunities:0.###}"
                + $"|probability={probability:0.######}"
                + $"|expected={expectedActivations:0.###}"
                + $"|activeStacks={expectedActiveStacks:0.######}/{Math.Max(1, effect.NativeStackLimit)}"
                + $"|coverage={coverage:0.######}"
                + $"|damage={effectDamage:0.###}"
                + $"|heal={effectHeal:0.###}"
                + $"|shield={effectShield:0.###}"
                + $"|selfHeal={effectSelfHeal:0.###}"
                + $"|selfShield={effectSelfShield:0.###}"
                + $"|expandedHealSkill={expandedHealingSkillId}"
                + $"|additionalHealTargets={additionalHealingTargets:0.###}"
                + $"|nativeAttrPayload={exactNativeAttributePayload}"
                + $"|deathPrevention={deathPreventionSeconds:0.###}"
                + $"|window={PerformancePreviewWindowSeconds:0.###}");
#endif
        }

        foreach (var entry in deferredParentStatePayloads
                     .OrderBy(entry => entry.Effect.AbilityId)
                     .ThenBy(entry => entry.Payload.AbilityId))
        {
            var multiplier = EstimateNativeParentStateMultiplier(
                entry.Effect, schedule, attrData, averageAttrDeltas,
                package.CommonQualityItemCount);
            if (multiplier <= 0d) continue;
            foreach (var delta in entry.Payload.AttrDeltas)
                averageAttrDeltas[delta.Key] = averageAttrDeltas.GetValueOrDefault(delta.Key)
                                                   + delta.Value * multiplier;
#if PATHOFIDLE_RUNTIME_TEST
            Plugin.DiagInfo(
                $"AUTO-GEAR NATIVE STATE ATTRIBUTE|ability={entry.Effect.AbilityId}"
                + $"|payload={entry.Payload.AbilityId}"
                + $"|multiplier={multiplier:0.######}"
                + $"|attributes={entry.Payload.AttrDeltas.Count}");
#endif
        }
        return new ExpectedConditionalPackage(
            structural, damage, heal, shield, support, defense, minion,
            averageAttrDeltas,
            deathPreventionSeconds,
            selfHeal,
            selfShield);
    }

    private static NativeAbilityPackage EvaluateNativeAbilityPackage(
        IEnumerable<GearCandidate> items,
        object hero,
        HeroEffectProfile profile,
        object attrData)
    {
        var candidates = items.ToList();
        return MainThreadNativeGateway.Invoke(() =>
            EvaluateNativeAbilityPackageCore(candidates, hero, profile, attrData));
    }

    private static NativeAbilityPackage EvaluateNativeAbilityPackageCore(
        IEnumerable<GearCandidate> items,
        object hero,
        HeroEffectProfile profile,
        object attrData)
    {
        var structural = 0d;
        var offensive = 0d;
        var support = 0d;
        var defense = 0d;
        var minion = 0d;
        var alwaysOnAttrDeltas = new Dictionary<int, double>();
        var failedAbilityIds = new HashSet<int>();
        var unmodeledAbilityIds = new HashSet<int>();
        var modeledAbilityIds = new HashSet<int>();
        var relevantSetEffectAbilities = new Dictionary<int, int>();
        var appliedAbilityCounts = new Dictionary<int, int>();
        var conditionalEffects = new List<NativeConditionalEffect>();
        var complete = true;

        void AddAbility(
            int abilityId,
            int level,
            string dependencyText,
            string themeText,
            bool hasExplicitTargetMetadata = false,
            IReadOnlyList<int>? abilityParameters = null,
            int setEffectId = 0)
        {
            if (abilityId <= 0)
            {
                complete = false;
                failedAbilityIds.Add(abilityId);
                return;
            }
            try
            {
                var preview = InvokeStaticMany(
                    "AbilityData", "CreateByShow", abilityId, Math.Max(0, level), attrData);
                var ability = preview ?? ResolveAbilityTableRow(abilityId, level);
                if (ability is null)
                    throw new InvalidOperationException($"AbilityData.CreateByShow({abilityId}) returned no ability.");
                if (!IsNativeAbilityRelevantToProfile(
                        ability, profile, EffectRelevanceScope.SelectedJointPlan)
                    || !AreTextSkillDependenciesRelevant(
                        dependencyText, profile, EffectRelevanceScope.SelectedJointPlan,
                        ability, hasExplicitTargetMetadata)) return;
                var row = Read(ability, "tAbilityData") ?? ability;
                var resolvedAbilityId = ReadNullableInt(row, "id") ?? ReadNullableInt(ability, "id") ?? abilityId;
                if (setEffectId > 0)
                    relevantSetEffectAbilities[setEffectId] = resolvedAbilityId;
                var stackLimit = Math.Max(1, ReadNullableInt(row, "stack") ?? 1);
                var appliedCount = appliedAbilityCounts.GetValueOrDefault(resolvedAbilityId);
                if (appliedCount >= stackLimit) return;
                appliedAbilityCounts[resolvedAbilityId] = appliedCount + 1;

                var resultIds = ReadSequence(Read(row, "resultArr")).Select(ToInt).Where(id => id > 0).ToList();
                if (preview is null && resultIds.Contains(301))
                    throw new InvalidOperationException($"Static result301 preview for ability {resolvedAbilityId} is unavailable.");
                var safeAcquire = IsUnconditionalAcquireAbility(ability);

                var conditionalAttributePayloads =
                    ResolveNativeConditionalAttributePayloads(
                        abilityId,
                        level,
                        abilityParameters,
                        attrData,
                        profile,
                        dependencyText);

                if (preview is not null && IsStrictAlwaysOnSelfAbility(preview))
                {
                    // Apply the complete signed delta later to a cloned AttrData.
                    // Positive-only application would hide native trade-offs.
                    var deltas = ReadNativeAbilityResultAttrDeltas(preview);
                    if (deltas.Count == 0)
                        throw new InvalidOperationException($"Static result301 ability {resolvedAbilityId} produced no readable attributes.");
                    foreach (var entry in deltas)
                        alwaysOnAttrDeltas[entry.Key] = alwaysOnAttrDeltas.GetValueOrDefault(entry.Key) + entry.Value;
                    modeledAbilityIds.Add(resolvedAbilityId);
#if PATHOFIDLE_DIAGNOSTICS
                    Plugin.DiagInfo(
                        $"AUTO-GEAR EXACT ATTRIBUTE ABILITY|ability={resolvedAbilityId}"
                        + $"|attributes={deltas.Count}|text={Clean(dependencyText)}");
#endif
                    return;
                }

                var abilityScore = ScoreNativeAbility(
                    ability, profile, EffectRelevanceScope.SelectedJointPlan);
                if (abilityScore <= 0d)
                {
                    abilityScore = ScoreOpaqueConditionalEffect(dependencyText, profile);
                    abilityScore *= GetConditionalAbilityThemeWeight(
                        ability, themeText, profile.Focus);
                }
                else if (!HasExplicitNativeAbilityTheme(ability, profile.PlannedSkills))
                    abilityScore *= GetOpaqueEffectThemeWeight(themeText, profile.Focus);
                abilityScore = Math.Max(
                    abilityScore,
                    conditionalAttributePayloads.Sum(payload => payload.PerActivationScore));
                var hasHealingTargetRelationship =
                    TryReadAdditionalHealingTargetCount(
                        dependencyText, out _);
                var expectedConditional = IsExpectedConditionalEffect(
                                              ability, dependencyText)
                                          || conditionalAttributePayloads.Count > 0
                                          || hasHealingTargetRelationship;
                var hasNativeSkillTriggerRelation = expectedConditional
                    && InferOrderedSkillDependenciesFromText(
                            dependencyText, profile.JobId).Count >= 2
                    && Regex.IsMatch(
                        NormalizeSkillDependencyText(dependencyText),
                        @"\b(?:also\s+)?trigger\w*\b",
                        RegexOptions.CultureInvariant);
                if ((abilityScore > 0d
                     || conditionalAttributePayloads.Count > 0
                     || hasNativeSkillTriggerRelation)
                    && expectedConditional)
                {
                    conditionalEffects.Add(new NativeConditionalEffect(
                        resolvedAbilityId,
                        dependencyText,
                        Clean(ReadString(row, "condition") ?? string.Empty),
                        abilityScore,
                        Convert.ToDouble(
                            Read(ability, "duration") ?? Read(row, "duration") ?? 0d,
                            CultureInfo.InvariantCulture),
                        Math.Max(0d, Convert.ToDouble(
                            Read(ability, "cdTime") ?? Read(row, "cdTime") ?? 0d,
                            CultureInfo.InvariantCulture)),
                        stackLimit,
                        conditionalAttributePayloads));
                    modeledAbilityIds.Add(resolvedAbilityId);
                }
                else
                {
                    structural += abilityScore;
                    if (safeAcquire && preview is not null)
                        modeledAbilityIds.Add(resolvedAbilityId);
                    else
                        unmodeledAbilityIds.Add(resolvedAbilityId);
#if PATHOFIDLE_DIAGNOSTICS
                    Plugin.DiagInfo(
                        $"AUTO-GEAR STRUCTURAL ABILITY|ability={resolvedAbilityId}"
                        + $"|score={abilityScore:0.###}|safeAcquire={safeAcquire}"
                        + $"|preview={preview is not null}|text={Clean(dependencyText)}");
#endif
                }
                var utility = GetNativeAbilityRoleUtility(ability);
                support += utility.Support;
                defense += utility.Defense;
                minion += utility.Minion;
                if (safeAcquire) offensive += ScoreNativeAbilityResultOffense(ability, profile);
            }
            catch (Exception error)
            {
                complete = false;
                failedAbilityIds.Add(abilityId);
                Plugin.DiagDebug($"ABILITY PREVIEW FAILED|ability={abilityId}|level={level}|{error.GetBaseException().Message}");
            }
        }

        void AddAffix(object rawAffix)
        {
            var affix = ResolveRuntimeAffix(rawAffix);
            var definition = Read(affix, "tAffixData");
            if ((ReadNullableInt(definition, "effectType") ?? 0) != 3) return;
            if (!IsAffixRelevantToProfile(
                    affix, profile, EffectRelevanceScope.SelectedJointPlan)) return;
            var save = Read(affix, "saveData");
            var abilityId = ReadNullableInt(save, "abilityId")
                            ?? ReadNullableInt(Read(affix, "tAbilityData"), "id")
                            ?? ReadSequence(Read(definition, "effectParam")).Select(ToInt).FirstOrDefault();
            var level = Math.Max(0, ReadNullableInt(save, "level") ?? 0);
            var affixText = GetAffixSearchText(affix);
            AddAbility(
                abilityId, level, affixText, affixText,
                HasExplicitAffixTargetMetadata(affix));
        }

        var candidates = items.ToList();
        foreach (var candidate in candidates)
        foreach (var affix in CollectEquipmentAffixes(candidate.Record.ItemData)
                     .Concat(CollectGrantedMasteryAffixes(candidate.Record.ItemData)))
            AddAffix(affix);

        var effectsBySet = GetSetEffectScoreRows();
        foreach (var group in candidates.Where(item => item.SetId > 0).GroupBy(item => item.SetId))
        {
            if (!effectsBySet.TryGetValue(group.Key, out var effects)) continue;
            var pieceCount = CountNativeSetPieces(group);
            foreach (var effect in effects.Where(effect => effect.Pieces > 0 && effect.Pieces <= pieceCount))
            {
#if PATHOFIDLE_DIAGNOSTICS
                Plugin.DiagInfo(
                    $"AUTO-GEAR ACTIVE SET EFFECT|set={group.Key}|pieces={pieceCount}"
                    + $"|threshold={effect.Pieces}|effect={effect.EffectId}"
                    + $"|ability={effect.AbilityId}|text={Clean(effect.Text)}");
#endif
                // Native HeroEquipData.UpdateSetsEffect removes and adds every
                // active TEquipSetsEffect with HeroData.RemoveAbility/AddAbility
                // (abilityId, 0). abilityParam is never the level; native special
                // hooks may instead use an exact parameter TAbility as their
                // finite conditional payload.
                AddAbility(
                    effect.AbilityId,
                    0,
                    effect.Text,
                    effect.Text,
                    abilityParameters: effect.AbilityParameters,
                    setEffectId: effect.EffectId);
            }
        }

        var talentData = Read(hero, "heroTalentData");
        var gridTalents = talentData is null
            ? new List<object>()
            : ReadValues(Read(talentData, "talentDic")).ToList();
        foreach (var talentId in profile.PlannedSkills.MasteryTalentIds)
        {
            var talent = gridTalents.FirstOrDefault(value =>
                (ReadNullableInt(Read(value, "tTalentData"), "id") ?? 0) == talentId);
            var definition = Read(talent, "tTalentData")
                             ?? InvokeStatic("TableData", "getTTalentData", talentId);
            var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
            if (definition is null || masteryId <= 0)
                throw new InvalidOperationException($"Planned mastery talent {talentId} is unavailable.");
            var cap = talent is null ? 1 : Math.Max(1, GetTalentLevelCap(talent));
            var baseLevel = talent is null ? 0 : Math.Min(GetTalentBaseLevelRequired(talent), cap);
            var savedTarget = profile.PlannedSkills.TargetSavedLevels.GetValueOrDefault(talentId);
            var maxSaved = Math.Max(0, cap - baseLevel);
            if (savedTarget <= 0 || savedTarget > maxSaved)
                throw new InvalidOperationException(
                    $"Planned mastery talent {talentId} saved target {savedTarget} is outside its native range 1..{maxSaved}.");
            var targetLevel = checked(baseLevel + savedTarget);
            var mastery = InvokeStaticMany("MasteryData", "CreateByShow", masteryId, targetLevel, cap)
                          ?? throw new InvalidOperationException($"MasteryData.CreateByShow({masteryId}) returned no mastery.");
            foreach (var affix in ReadList(Read(mastery, "affixList"))) AddAffix(affix);
        }
        var activeRelevantSetEffectIds = relevantSetEffectAbilities.Keys.ToHashSet();
        var unmodeledRelevantSetEffectIds = relevantSetEffectAbilities
            .Where(entry => !modeledAbilityIds.Contains(entry.Value))
            .Select(entry => entry.Key)
            .ToHashSet();
        return new NativeAbilityPackage(
            structural, offensive, support, defense, minion,
            alwaysOnAttrDeltas, new Dictionary<int, int>(appliedAbilityCounts),
            complete, failedAbilityIds, unmodeledAbilityIds,
            conditionalEffects,
            candidates.Count(candidate => candidate.Record.Quality == 1),
            activeRelevantSetEffectIds,
            unmodeledRelevantSetEffectIds);
    }

    private static double ScoreNativeAbilityResultOffense(object ability, HeroEffectProfile profile)
        => ScoreNativeAbilityResultOffenseCore(
            ability,
            attrId => Math.Max(0.08d, GetBattleAttrPreScoreWeight(
                attrId,
                profile,
                profile.Focus.Key is "physical" or "bleed",
                profile.Focus.Key is "elemental" or "fire" or "ice" or "lightning" or "corrosion")));

    private static double ScoreNativeAbilityResultOffense(object ability, HeroFocus focus)
        => ScoreNativeAbilityResultOffenseCore(ability, attrId => GetNativeAbilityResultWeight(attrId, focus));

    private static double ScoreNativeAbilityResultOffenseCore(object ability, Func<int, double> getWeight)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        var abilityType = ReadNullableInt(row, "type") ?? 0;
        var score = 0d;
        foreach (var entry in ReadEntries(Read(Read(ability, "resultData"), "combatAttrFinalDic")))
        {
            var attrId = ToInt(Read(entry, "Key") ?? 0);
            double value;
            try { value = Convert.ToDouble(Read(entry, "Value") ?? 0d, CultureInfo.InvariantCulture); }
            catch { continue; }
            if (attrId <= 0 || !double.IsFinite(value) || Math.Abs(value) <= 0d) continue;
            var positiveOffense = value > 0d && !IsConversionModifierAttribute(attrId) && attrId != 248
                && attrId is 1 or 2 or 31 or 33 or 35 or 37 or 41 or 42
                or 51 or 52 or 53 or 54 or 55 or 56 or 71 or 72 or 75 or 76 or 77 or 78
                or 99 or 100 or 101 or 102 or 106 or 107 or 108 or 110 or 111 or 112 or 113 or 114 or 115
                or 121 or 122 or 123 or 124 or 125 or 126 or 133 or 160 or 162 or 164 or 167
                or 170 or 171 or 172 or 181 or 210 or 211 or 218
                or 230 or 231 or 232 or 233 or 234 or 235 or 236 or 237
                or 240 or 241 or 242 or 245 or 246 or 247 or 250 or 251 or 252 or 253
                or 255 or 256 or 257 or 258;
            var hostileDefenseReduction = value < 0d && abilityType is 2 or 3
                && attrId is 3 or 4 or 43 or 44 or 61 or 62 or 63 or 64 or 65 or 66 or 130 or 131 or 132 or 134;
            if (!positiveOffense && !hostileDefenseReduction) continue;
            score += Math.Abs(value) * Math.Max(0.08d, getWeight(attrId));
        }
        var duration = Math.Max(0d, Convert.ToDouble(
            Read(ability, "duration") ?? Read(row, "duration") ?? 0d, CultureInfo.InvariantCulture));
        var cooldown = Math.Max(0d, Convert.ToDouble(
            Read(ability, "cdTime") ?? Read(row, "cdTime") ?? 0d, CultureInfo.InvariantCulture));
        if (duration > 0d && cooldown > 0d) score *= Math.Clamp(duration / cooldown, 0.1d, 1d);
        return score;
    }

    private static double GetNativeAbilityResultWeight(int attrId, HeroFocus focus)
        => attrId switch
        {
            248 => 0d,
            >= 700 and <= 712 => 0d,
            1 => focus.Key is "physical" or "bleed" ? 1.4d
                : focus.Key is "elemental" or "fire" or "ice" or "lightning" or "corrosion" ? 0.25d : 1d,
            2 => focus.Key is "elemental" or "fire" or "ice" or "lightning" or "corrosion" ? 1.4d
                : focus.Key is "physical" or "bleed" ? 0.25d : 1d,
            51 or 52 or 53 or 110 or 111 or 112 => GetDamageFamilyResultWeight(focus, "physical"),
            54 or 113 => GetDamageFamilyResultWeight(focus, "fire"),
            55 or 114 => GetDamageFamilyResultWeight(focus, "ice"),
            56 or 115 => GetDamageFamilyResultWeight(focus, "lightning"),
            121 or 123 or 125 => GetDamageFamilyResultWeight(focus, "bleed"),
            122 or 124 or 126 => GetDamageFamilyResultWeight(focus, "corrosion"),
            31 or 33 or 37 => focus.Key == "crit" ? 22d : focus.Key is "defense" or "support" or "minion" ? 2d : 12d,
            41 or 42 or 71 or 72 or 75 or 76 or 77 or 78 or 99 or 100 or 101 or 102
                or 106 or 107 or 108 or 133 or 160 or 162 or 164 or 167 or 170 or 171 or 172
                or 181 or 210 or 211 or 218 or 230 or 231 or 232 or 233 or 234 or 235 or 236
                or 237 or 240 or 241 or 242 or 245 or 246 or 247 or 248 or 250 or 251 or 252
                or 253 or 255 or 256 or 257 or 258 or 700 or 703 or 704 or 705 or 707 or 708
                or 709 or 710 or 711 or 712 => focus.Key is "defense" or "support" ? 3d : 16d,
            _ => 0.08d
        };

    private static double GetDamageFamilyResultWeight(HeroFocus focus, string family)
    {
        if (focus.Key is "defense" or "support" or "minion") return 2d;
        if (focus.Key is "crit" or "hybrid") return 16d;
        if (focus.Key == "elemental") return family is "fire" or "ice" or "lightning" ? 16d : 16d * 0.18d;
        if (focus.Key is "physical" or "fire" or "ice" or "lightning" or "bleed" or "corrosion")
            return focus.Key == family ? 16d : 16d * 0.18d;
        return 16d;
    }

    private static double ScoreItemAbilityHeuristics(
        IEnumerable<GearCandidate> items,
        HeroEffectProfile profile)
    {
        var score = 0d;
        foreach (var candidate in items)
        foreach (var rawAffix in CollectEquipmentAffixes(candidate.Record.ItemData)
                     .Concat(CollectGrantedMasteryAffixes(candidate.Record.ItemData)))
        {
            var affix = ResolveRuntimeAffix(rawAffix);
            if ((ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0) != 3) continue;
            score += ScoreAffixBehavior(
                affix,
                candidate.DefinitionId,
                profile,
                GetAffixSearchText(affix),
                EffectRelevanceScope.SelectedJointPlan);
        }
        return score;
    }

    private static double GetNativeAbilityElementWeight(int attrId, HeroFocus focus)
    {
        var family = attrId switch
        {
            51 or 52 or 53 or 110 or 111 or 112 => "physical",
            54 or 113 => "fire",
            55 or 114 => "ice",
            56 or 115 => "lightning",
            121 or 123 or 125 => "bleed",
            122 or 124 or 126 => "corrosion",
            _ => string.Empty
        };
        if (family.Length == 0 || focus.Key is "defense" or "support" or "minion" or "crit" or "hybrid") return 1d;
        if (focus.Key == "elemental") return family is "fire" or "ice" or "lightning" ? 1d : 0.18d;
        return family == focus.Key ? 1d : 0.18d;
    }

    private static bool HasExplicitNativeAbilityTheme(object? ability, PlannedSkillTarget _)
        => GetExplicitNativeAbilityThemeAttrIds(ability).Count > 0;

    private static IReadOnlyList<int> GetExplicitNativeAbilityThemeAttrIds(object? ability)
    {
        var row = Read(ability, "tAbilityData") ?? ability;
        if (row is null) return Array.Empty<int>();
        static bool IsDamageFamilyAttribute(int id)
            => id is 51 or 52 or 53 or 54 or 55 or 56
                or 110 or 111 or 112 or 113 or 114 or 115
                or 121 or 122 or 123 or 124 or 125 or 126;
        var result = new HashSet<int>();
        var attrId = ReadNullableInt(row, "attrId") ?? 0;
        if (IsDamageFamilyAttribute(attrId)) result.Add(attrId);
        result.UnionWith(ReadEntries(Read(Read(ability, "resultData"), "combatAttrFinalDic"))
            .Select(entry => ToInt(Read(entry, "Key") ?? 0))
            .Where(IsDamageFamilyAttribute));
        return result.OrderBy(id => id).ToList();
    }

    private static double GetConditionalAbilityThemeWeight(
        object? ability,
        string? fallbackText,
        HeroFocus focus)
    {
        var explicitAttributes = GetExplicitNativeAbilityThemeAttrIds(ability);
        // A conditional/special hook returns zero before ScoreNativeAbility can
        // apply its attr-family weight. When the native table still declares a
        // damage family, use that authoritative family on the opaque fallback.
        // Multiple declared families are treated as alternatives, matching an
        // all-element effect to any supported focus.
        return explicitAttributes.Count > 0
            ? explicitAttributes.Max(attrId => GetNativeAbilityElementWeight(attrId, focus))
            : GetOpaqueEffectThemeWeight(fallbackText, focus);
    }

    private static double GetOpaqueEffectThemeWeight(string? rawText, HeroFocus focus)
    {
        var text = Clean(rawText ?? string.Empty).ToLowerInvariant();
        if (text.Length == 0 || focus.Key is "defense" or "support" or "minion" or "crit" or "hybrid") return 1d;

        // Use only explicit damage-family words here. Broad discovery aliases
        // such as "weapon", "spell" or "crit" occur in otherwise neutral set
        // descriptions and must not turn them into Physical/Elemental sets.
        var families = new Dictionary<string, string[]>
        {
            ["physical"] = new[] { "physical", "martial", "blunt", "slash", "pierce" },
            ["fire"] = FireWords,
            ["ice"] = IceWords,
            ["lightning"] = LightningWords,
            ["bleed"] = BleedWords,
            ["corrosion"] = CorrosionWords
        };
        var accepted = focus.Key == "elemental"
            ? new HashSet<string>(new[] { "fire", "ice", "lightning" }, StringComparer.Ordinal)
            : new HashSet<string>(new[] { focus.Key }, StringComparer.Ordinal);
        var evidence = families.ToDictionary(entry => entry.Key, entry => KeywordScore(text, entry.Value));
        if (accepted.Any(key => evidence.GetValueOrDefault(key) > 0)) return 1d;
        return evidence.Any(entry => !accepted.Contains(entry.Key) && entry.Value > 0) ? 0.18d : 1d;
    }

    private static double GetRawCandidatePower(GearCandidate candidate) => candidate.RawPower;

    private static double ReadEquipmentAttrValueForOptimization(
        object equip,
        object equipAttr,
        object equipType,
        bool includeForgeBonuses)
    {
        var value = Convert.ToDouble(
            includeForgeBonuses
                ? InvokeRequiredInstance(equipAttr, "GetAttrValue", equipType, null!) ?? 0d
                : InvokeRequiredInstance(equip, "GetCoreAttrValueWithoutForge", equipType) ?? 0d,
            CultureInfo.InvariantCulture);
        if (!double.IsFinite(value))
            throw new InvalidOperationException(
                includeForgeBonuses
                    ? "The native current equipment attribute is not finite."
                    : "The native pre-forge equipment attribute is not finite.");
        return value;
    }

    private static double EstimateEquipmentNumericScore(
        object item,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        try
        {
            var equipAttr = Read(Read(item, "itemEquipData"), "equipAttrData")
                            ?? throw new InvalidOperationException("Equipment AttrData is unavailable.");
            var physical = profile.Focus.Key is "physical" or "bleed";
            var elemental = profile.Focus.Key is "elemental" or "fire" or "ice" or "lightning" or "corrosion";
            var score = 0d;
            foreach (var mapping in GetEquipAttrMappings())
            {
                if (IsConversionModifierAttribute(mapping.BattleAttrType)
                    || mapping.BattleAttrType == 248) continue;
                var equipType = CreateEnum("EEquipAttrType", mapping.EquipType)
                                ?? throw new InvalidOperationException($"Unknown equipment attribute type {mapping.EquipType}.");
                var value = ReadEquipmentAttrValueForOptimization(
                    Read(item, "itemEquipData")!, equipAttr, equipType,
                    AutoBuildIncludesForgeBonuses);
                score += value * GetBattleAttrPreScoreWeight(mapping.BattleAttrType, profile, physical, elemental);
            }

            // The runtime list already contains ordinary rolls plus the table-
            // supplied Legendary, Mythic and Unique affixes, as well as rune
            // affixes. Native AffixData.SetActiveAttrData applies a bodyAttr
            // affix by adding saveData.value to every EAttrType in effectParam.
            // Include that exact magnitude before beam pruning; previously +1
            // and +100 sub-options had the same keyword-only candidate score.
            foreach (var affix in CollectEquipmentAffixes(item).Concat(CollectGrantedMasteryAffixes(item)).Select(ResolveRuntimeAffix))
            {
                var definition = Read(affix, "tAffixData");
                if ((ReadNullableInt(definition, "effectType") ?? 0) != 1) continue;
                // bodyAttr is an independent numeric component. A different
                // special affix on the same item targeting an unused skill must
                // not suppress this ordinary/sub/rune attribute roll.
                var value = Convert.ToDouble(ReadNullableInt(Read(affix, "saveData"), "value") ?? 0, CultureInfo.InvariantCulture);
                foreach (var attrId in ReadSequence(Read(definition, "effectParam")).Select(ToInt).Where(id => id > 0))
                {
                    if (IsConversionModifierAttribute(attrId) || attrId == 248) continue;
                    score += value * GetBattleAttrPreScoreWeight(attrId, profile, physical, elemental);
                }
            }
            return score;
        }
        catch (Exception error)
        {
            if (!numericPreScoreFailureLogged)
            {
                numericPreScoreFailureLogged = true;
                Plugin.DiagWarning($"AUTO-GEAR NUMERIC PRE-SCORE FAILED|raw fallback is active|{error.GetBaseException().Message}");
            }
            return 0d;
        }
    }

    private static double GetBattleAttrPreScoreWeight(int battleAttrType, HeroEffectProfile profile, bool physical, bool elemental)
        => battleAttrType switch
        {
            1 => physical ? 1.4d : elemental ? 0.25d : 1d,
            2 => elemental ? 1.4d : physical ? 0.25d : 1d,
            3 or 4 => profile.Focus.Key == "defense" ? 0.9d : 0.32d,
            5 => profile.Focus.Key == "defense" ? 0.35d : 0.10d,
            7 or 9 => profile.Focus.Key == "defense" ? 1.2d : 0.25d,
            11 or 12 or 13 => 0.55d,
            25 => profile.ControlledEntityKinds.HasFlag(NativeControlledEntityKind.Ally)
                ? profile.Focus.Key == "minion"
                    ? BlendThemePriority(profile.Focus, 1.5d, 18d, 26d)
                    : 1.5d
                : 0d,
            190 => profile.ControlledEntityKinds.HasFlag(NativeControlledEntityKind.Minion)
                ? profile.Focus.Key == "minion"
                    ? BlendThemePriority(profile.Focus, 1.5d, 18d, 26d)
                    : 1.5d
                : 0d,
            // summonNum is a TProduce construction field, not a persistent
            // hero/equipment attribute. It is valued through the reached
            // production graph rather than as generic gear power.
            6002 => 0d,
            81 or 82 or 83 or 84 or 91 or 92 or 93 or 94 or 95 or 96 or 185 or 191
                => profile.Focus.Key == "support" ? 18d : 1.5d,
            26 or 27 or 32 or 34 or 36 or 43 or 44 or 45 or 47 or 61 or 62 or 63 or 64 or 65 or 66
                or 85 or 86 or 130 or 131 or 132 or 134 or 151 or 152 or 153 or 154
                or 155 or 156 or 157 or 158 or 184 or 188 or 202 or 212 or 213 or 214 or 219
                => profile.Focus.Key == "defense" ? 20d : 2d,
            51 or 52 or 53 or 110 or 111 or 112 => GetDamageFamilyPreScoreWeight(profile, "physical"),
            54 or 113 => GetDamageFamilyPreScoreWeight(profile, "fire"),
            55 or 114 => GetDamageFamilyPreScoreWeight(profile, "ice"),
            56 or 115 => GetDamageFamilyPreScoreWeight(profile, "lightning"),
            121 or 123 or 125 => GetDamageFamilyPreScoreWeight(profile, "bleed"),
            122 or 124 or 126 => GetDamageFamilyPreScoreWeight(profile, "corrosion"),
            31 or 33 or 37 => profile.Focus.Key == "crit" ? 22d : profile.Focus.Key is "defense" or "support" or "minion" ? 2d : 12d,
            41 => GetGeneralAttackFamilyPreScoreWeight(profile, true),
            42 => GetGeneralAttackFamilyPreScoreWeight(profile, false),
            248 => 0d,
            71 or 72 or 73 or 74 or 75 or 76 or 77 or 78
                or 99 or 100 or 101 or 102 or 103 or 104 or 105 or 106 or 107 or 108
                or 133 or 160 or 161 or 162 or 163 or 164 or 165 or 166 or 167
                or 170 or 171 or 172 or 181 or 210 or 211 or 218
                or 230 or 231 or 232 or 233 or 234 or 235 or 236 or 237 or 238 or 239
                or 240 or 241 or 242 or 243 or 244 or 245 or 246 or 247 or 248 or 249
                or 250 or 251 or 252 or 253 or 254 or 255 or 256 or 257 or 258
                => profile.Focus.Key is "defense" or "support" ? 3d : 16d,
            >= 700 and <= 712 => 0d,
            _ when battleAttrType is >= 800 and <= 924
                => profile.Focus.Key is "defense" or "support" ? 3d : 1d,
            _ => 0.08d
        };

    private static double GetGeneralAttackFamilyPreScoreWeight(HeroEffectProfile profile, bool physicalFamily)
    {
        if (profile.Focus.Key is "defense" or "support" or "minion") return 3d;
        if (profile.Focus.Key is "crit" or "hybrid") return 16d;
        var aligned = physicalFamily
            ? profile.Focus.Key is "physical" or "bleed"
            : profile.Focus.Key is "elemental" or "fire" or "ice" or "lightning" or "corrosion";
        return aligned ? 16d : 16d * 0.18d;
    }

    private static double GetDamageFamilyPreScoreWeight(HeroEffectProfile profile, string family)
    {
        var focus = profile.Focus.Key;
        if (focus is "defense" or "support" or "minion") return 2d;
        if (focus == "crit" || focus == "hybrid") return 16d;
        if (focus == "elemental") return family is "fire" or "ice" or "lightning" ? 16d : 16d * 0.18d;
        if (focus is "physical" or "fire" or "ice" or "lightning" or "bleed" or "corrosion")
            return focus == family ? 16d : 16d * 0.18d;
        return 16d;
    }

    private static List<GearSlot> GetGearSlots() => new()
    {
        new GearSlot(1, true, 0, "main weapon"),
        new GearSlot(1, false, 1, "secondary weapon"),
        new GearSlot(2, true, -1, "necklace"),
        new GearSlot(3, true, -1, "ring"),
        new GearSlot(4, true, -1, "helmet"),
        new GearSlot(5, true, -1, "chest"),
        new GearSlot(6, true, -1, "gloves"),
        new GearSlot(7, true, -1, "boots")
    };

    private static bool HasLegendMythWeaponConflict(IEnumerable<GearCandidate> items)
    {
        var restrictedWeapons = items.Where(item => item.Part == 1 && item.Record.Quality is 4 or 5).ToList();
        for (var left = 0; left < restrictedWeapons.Count - 1; left++)
        for (var right = left + 1; right < restrictedWeapons.Count; right++)
            if (restrictedWeapons[left].SelectableFacts.LegendMythWeaponFamily
                .Overlaps(restrictedWeapons[right].SelectableFacts.LegendMythWeaponFamily))
                return true;
        return false;
    }

    private static HashSet<int> GetLegendMythWeaponFamily(
        object item,
        int definitionId,
        int quality)
    {
        var result = new HashSet<int>();
        var saveId = ReadNullableInt(Read(item, "saveItemData"), "id") ?? definitionId;
        var definition = Read(Read(item, "itemEquipData"), "tEquipData");
        var upgradedMythId = ReadNullableInt(definition, "upMyth") ?? 0;
        if (saveId > 0) result.Add(saveId);
        if (upgradedMythId > 0) result.Add(upgradedMythId);
        if (quality == 5 && saveId > 0)
        {
            foreach (var row in ReadValues(ReadStatic("TableData", "TEquipDict"))
                         .Where(row => (ReadNullableInt(row, "upMyth") ?? 0) == saveId))
            {
                var id = ReadNullableInt(row, "id") ?? 0;
                if (id > 0) result.Add(id);
            }
        }
        return result;
    }

    private static SelectableSetFacts BuildSelectableSetFacts(
        HeroEffectProfile profile,
        IEnumerable<GearCandidate> candidates,
        bool allowDeadlineExit = false,
        EffectRelevanceScope relevanceScope = EffectRelevanceScope.SelectableJointPlan)
    {
        var sourceRows = GetSetEffectScoreRows();
        var result = new Dictionary<int, IReadOnlyList<SelectableSetEffectFact>>();
        foreach (var setId in candidates.Select(candidate => candidate.SetId)
                     .Where(id => id > 0).Distinct().OrderBy(id => id))
        {
            if (allowDeadlineExit && AutoBuildSearchDeadlineReached()) break;
            if (!sourceRows.TryGetValue(setId, out var effects)) continue;
            var facts = new List<SelectableSetEffectFact>();
            foreach (var effect in effects.Where(effect => effect.Pieces > 0 && effect.AbilityId > 0))
            {
                if (allowDeadlineExit && AutoBuildSearchDeadlineReached()) break;
                var ability = ResolveAbilityTableRow(effect.AbilityId, 0);
                if (!IsNativeAbilityRelevantToProfile(
                        ability, profile, relevanceScope)
                    || !AreTextSkillDependenciesRelevant(
                        effect.Text, profile, relevanceScope, ability)) continue;
                var abilityScore = ScoreNativeAbility(
                    ability, profile, relevanceScope);
                var conditionalPayloadScore = ResolveNativeConditionalAttributePayloads(
                        effect.AbilityId,
                        0,
                        effect.AbilityParameters,
                        profile.PlannedSkills.NeutralObjectiveAttr,
                        profile,
                        effect.Text)
                    .Sum(payload => payload.PerActivationScore);
                if (abilityScore <= 0d)
                {
                    abilityScore = ScoreOpaqueConditionalEffect(effect.Text, profile);
                    abilityScore *= GetConditionalAbilityThemeWeight(
                        ability, effect.Text, profile.Focus);
                }
                else if (!HasExplicitNativeAbilityTheme(ability, profile.PlannedSkills))
                    abilityScore *= GetOpaqueEffectThemeWeight(effect.Text, profile.Focus);
                abilityScore = Math.Max(abilityScore, conditionalPayloadScore);
                facts.Add(new SelectableSetEffectFact(
                    effect.EffectId,
                    effect.Pieces,
                    effect.AbilityId,
                    Math.Max(0d, abilityScore)));
            }
            if (facts.Count > 0) result[setId] = facts;
        }
        return new SelectableSetFacts(result);
    }

    private static double EstimatePartialSetSynergy(
        IEnumerable<GearCandidate> items,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope,
        SelectableSetFacts? selectableFacts = null)
    {
        var groups = items.Where(item => item.SetId > 0).GroupBy(item => item.SetId).ToList();
        if (selectableFacts is not null)
        {
            var cachedScore = 0d;
            foreach (var group in groups)
            {
                if (!selectableFacts.EffectsBySet.TryGetValue(group.Key, out var effects)) continue;
                var count = CountNativeSetPieces(group);
                foreach (var effect in effects)
                    if (effect.Pieces <= count) cachedScore += effect.PartialScore;
            }
            return cachedScore;
        }

        var score = 0d;
        var effectsBySet = GetSetEffectScoreRows();
        foreach (var group in groups)
        {
            var count = CountNativeSetPieces(group);
            if (!effectsBySet.TryGetValue(group.Key, out var effects)) continue;
            var activeEffects = effects.Where(effect => effect.Pieces > 0 && effect.Pieces <= count).ToList();
            if (activeEffects.Count == 0) continue;
            // Only native effects whose exact 2/4-piece threshold is active are
            // scored. Native ability IDs/conditions decide whether the jointly
            // planned skills can trigger them; localized descriptions do not.
            foreach (var effect in activeEffects)
            {
                // HeroEquipData.UpdateSetsEffect activates the parent set ability
                // at level zero. A parameter can name the finite TAbility applied
                // by that parent's native hook; it is never used as the level.
                var ability = ResolveAbilityTableRow(effect.AbilityId, 0);
                if (!IsNativeAbilityRelevantToProfile(
                        ability, profile, relevanceScope)
                    || !AreTextSkillDependenciesRelevant(
                        effect.Text, profile, relevanceScope, ability)) continue;
                var abilityScore = ScoreNativeAbility(ability, profile, relevanceScope);
                var conditionalPayloadScore = ResolveNativeConditionalAttributePayloads(
                        effect.AbilityId,
                        0,
                        effect.AbilityParameters,
                        profile.PlannedSkills.NeutralObjectiveAttr,
                        profile,
                        effect.Text)
                    .Sum(payload => payload.PerActivationScore);
                if (abilityScore <= 0d)
                {
                    abilityScore = ScoreOpaqueConditionalEffect(effect.Text, profile);
                    abilityScore *= GetConditionalAbilityThemeWeight(
                        ability, effect.Text, profile.Focus);
                }
                else if (!HasExplicitNativeAbilityTheme(ability, profile.PlannedSkills))
                    abilityScore *= GetOpaqueEffectThemeWeight(effect.Text, profile.Focus);
                abilityScore = Math.Max(abilityScore, conditionalPayloadScore);
                if (abilityScore <= 0d) continue;
                score += abilityScore;
            }
        }
        return score;
    }

    private static (double Penalty, int Count, string Details)
        ScoreInactiveSetThresholdOpportunityCost(
            IEnumerable<GearCandidate> items,
            HeroEffectProfile profile)
    {
        var effectsBySet = GetSetEffectScoreRows();
        var mismatches = new List<string>();
        foreach (var group in items.Where(item => item.SetId > 0)
                     .GroupBy(item => item.SetId))
        {
            if (!effectsBySet.TryGetValue(group.Key, out var effects)) continue;
            var count = CountNativeSetPieces(group);
            foreach (var effect in effects.Where(effect =>
                         effect.Pieces > 0 && effect.Pieces <= count))
            {
                var ability = ResolveAbilityTableRow(effect.AbilityId, 0);
                var abilityRow = Read(ability, "tAbilityData") ?? ability;
                var explicitDependency = InferSkillDependenciesFromText(
                                             effect.Text, profile.JobId).Count > 0
                                         || InferSkillTagDependenciesFromText(effect.Text).Count > 0
                                         || HasExplicitNativeAbilityTargetMetadata(ability)
                                         || ReadFirstPositiveInt(
                                             abilityRow, "jobId", "targetJobId", "heroJobId") > 0
                                         || new[] { "weaponArr", "weaponTypeArr", "targetWeaponArr" }
                                             .SelectMany(name => ReadSequence(Read(abilityRow, name))
                                                 .Select(ToInt)).Any(id => id > 0);
                // Opaque effects remain unknown-zero; only a proven dependency
                // on a different selected skill/tag/weapon incurs slot debt.
                if (!explicitDependency) continue;
                var relevant = IsNativeAbilityRelevantToProfile(
                                   ability, profile,
                                   EffectRelevanceScope.SelectedJointPlan)
                               && AreTextSkillDependenciesRelevant(
                                   effect.Text, profile,
                                   EffectRelevanceScope.SelectedJointPlan,
                                   ability);
                if (relevant) continue;
                mismatches.Add($"set={group.Key}/effect={effect.EffectId}/{effect.Pieces}p");
            }
        }
        return (
            -InactiveSetThresholdOpportunityCostPenalty * mismatches.Count,
            mismatches.Count,
            string.Join(",", mismatches));
    }

    private static bool HasRelevantSetThreshold(
        int setId,
        SelectableSetFacts selectableFacts)
        => setId > 0
           && selectableFacts.EffectsBySet.TryGetValue(setId, out var effects)
           && effects.Any(effect => effect.Pieces > 0 && effect.AbilityId > 0);

    // HeroEquipData.UpdateSetsEffect counts distinct native equipment
    // definitions within a set. Two copies of the same set weapon can occupy
    // both weapon slots, but they are still one set piece (the native selector
    // projects ItemData to TEquip.id before Distinct/Count). Keep every search,
    // preview, report, and postcondition on that same rule.
    private static int CountNativeSetPieces(IEnumerable<GearCandidate> items)
        => items.Select(item => item.DefinitionId)
            .Where(id => id > 0)
            .Distinct()
            .Count();

    private static int GetNativeEquipmentDefinitionId(object item)
        => ReadNullableInt(Read(Read(item, "itemEquipData"), "tEquipData"), "id") ?? 0;

    private static int GetNativeEquipmentSetId(object item)
    {
        var equip = Read(item, "itemEquipData");
        return ReadNullableInt(Read(equip, "tEquipSetsData"), "id")
               ?? ReadNullableInt(Read(equip, "tEquipData"), "setsId") ?? 0;
    }

    private static int CountNativeEquippedSetPieces(IEnumerable<object> items)
        => items.Select(GetNativeEquipmentDefinitionId)
            .Where(id => id > 0)
            .Distinct()
            .Count();

    private static IEnumerable<string> GetIncompleteSetCompletionLaneKeys(
        LoadoutState state,
        SelectableSetFacts selectableFacts)
    {
        foreach (var group in state.Items.Where(item => item.SetId > 0).GroupBy(item => item.SetId))
        {
            if (!selectableFacts.EffectsBySet.TryGetValue(group.Key, out var effects)) continue;
            var count = CountNativeSetPieces(group);
            var nextThreshold = effects
                .Where(effect => effect.Pieces > count && effect.AbilityId > 0)
                .Select(effect => effect.Pieces)
                .DefaultIfEmpty(0)
                .Min();
            if (nextThreshold > count)
                yield return $"set={group.Key}|pieces={count}|next={nextThreshold}";
        }
    }

    private static string StableLoadoutOrderKey(LoadoutState state)
        => string.Join("|", state.Items.Select(item => item.StableOrderKey));

    private sealed class StableLoadoutStateComparer : IComparer<LoadoutState>
    {
        internal static readonly StableLoadoutStateComparer Instance = new();

        public int Compare(LoadoutState? left, LoadoutState? right)
        {
            if (ReferenceEquals(left, right)) return 0;
            if (left is null) return 1;
            if (right is null) return -1;

            // Both weapon slots contribute attributes, but slot zero is the
            // native active weapon whenever it is occupied. For an otherwise
            // identical two-weapon loadout, keep the weapon with the stronger
            // profile-specific item evaluation in that active slot. This is a
            // semantic and restart-stable tie-break, unlike an IL2CPP pointer.
            var leftMain = left.Items.FirstOrDefault(item => item.Part == 1);
            var rightMain = right.Items.FirstOrDefault(item => item.Part == 1);
            var comparison = CompareDescending(
                leftMain?.Score ?? double.NegativeInfinity,
                rightMain?.Score ?? double.NegativeInfinity);
            if (comparison != 0) return comparison;
            comparison = CompareDescending(
                leftMain?.NumericScore ?? double.NegativeInfinity,
                rightMain?.NumericScore ?? double.NegativeInfinity);
            if (comparison != 0) return comparison;
            comparison = CompareDescending(
                leftMain?.RawPower ?? double.NegativeInfinity,
                rightMain?.RawPower ?? double.NegativeInfinity);
            if (comparison != 0) return comparison;
            comparison = string.Compare(
                leftMain?.StableOrderKey ?? string.Empty,
                rightMain?.StableOrderKey ?? string.Empty,
                StringComparison.Ordinal);
            if (comparison != 0) return comparison;
            return string.Compare(
                StableLoadoutOrderKey(left),
                StableLoadoutOrderKey(right),
                StringComparison.Ordinal);
        }

        private static int CompareDescending(double left, double right)
        {
            if (double.IsNaN(left)) left = double.NegativeInfinity;
            if (double.IsNaN(right)) right = double.NegativeInfinity;
            return right.CompareTo(left);
        }
    }

    private static IEnumerable<string> GetActiveSetLaneKeys(
        LoadoutState state,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope,
        SelectableSetFacts? selectableFacts = null)
    {
        // The supplied facts have already been filtered for the caller's exact
        // relevance scope. Reuse them for both the broad selectable lane and the
        // strict selected-package lane; falling through here rebuilt every native
        // set ability for every finalist (360x on a typical stash).
        if (selectableFacts is not null)
        {
            foreach (var group in state.Items.Where(item => item.SetId > 0).GroupBy(item => item.SetId))
            {
                if (!selectableFacts.EffectsBySet.TryGetValue(group.Key, out var effects)) continue;
                var count = CountNativeSetPieces(group);
                foreach (var threshold in effects
                             .Where(effect => effect.Pieces > 0 && effect.Pieces <= count)
                             .Select(effect => effect.Pieces).Distinct().OrderBy(value => value))
                    yield return $"set={group.Key}|active={threshold}";
            }
            yield break;
        }
        var effectsBySet = GetSetEffectScoreRows();
        foreach (var group in state.Items.Where(item => item.SetId > 0).GroupBy(item => item.SetId))
        {
            if (!effectsBySet.TryGetValue(group.Key, out var effects)) continue;
            var count = CountNativeSetPieces(group);
            foreach (var threshold in effects
                         .Where(effect => effect.Pieces > 0 && effect.Pieces <= count && effect.AbilityId > 0)
                         .Where(effect =>
                         {
                             var ability = ResolveAbilityTableRow(effect.AbilityId, 0);
                             return IsNativeAbilityRelevantToProfile(ability, profile, relevanceScope)
                                    && AreTextSkillDependenciesRelevant(
                                        effect.Text, profile, relevanceScope, ability);
                         })
                         .Select(effect => effect.Pieces).Distinct().OrderBy(value => value))
                yield return $"set={group.Key}|active={threshold}";
        }
    }

    private static List<LoadoutState> SelectBeamStatesWithSetCompletionLanes(
        IEnumerable<LoadoutState> states,
        HeroEffectProfile profile,
        SelectableSetFacts selectableSetFacts,
        int limit)
    {
        string StateKey(LoadoutState state)
            => string.Join("|", state.Items.Select(item => item.Key));
        double Rank(LoadoutState state)
            => state.HeuristicScore + EstimatePartialSetSynergy(
                state.Items,
                profile,
                EffectRelevanceScope.SelectableJointPlan,
                selectableSetFacts);
        string WeaponCombinationKey(LoadoutState state)
            => string.Join(",", state.Items
                .Where(item => item.Part == 1 && item.WeaponType > 0)
                .Select(item => item.WeaponType)
                .OrderBy(value => value));

        var ordered = states
            .OrderByDescending(Rank)
            .ThenBy(state => state, StableLoadoutStateComparer.Instance)
            .ThenBy(StateKey, StringComparer.Ordinal)
            .ToList();
        if (ordered.Count <= limit) return ordered;

        // Inactive 1/3-piece sets receive no effect score. Their only protection
        // from early beam pruning is this bounded structural lane, which keeps a
        // coherent path to the next real native threshold without pretending the
        // threshold is already active.
        var laneBudget = Math.Min(Math.Max(1, limit / 3), 120);
        var setReserved = ordered
            .SelectMany(state =>
            {
                // A set threshold and its weapon contract are one relational
                // lane. Grouping only by set/piece count preserved a strong but
                // unusable weapon pair and pruned the same 4-piece threshold
                // with weapons that could run the selected skill package.
                var weaponLane = WeaponCombinationKey(state);
                return GetIncompleteSetCompletionLaneKeys(state, selectableSetFacts)
                    .Concat(GetActiveSetLaneKeys(
                        state,
                        profile,
                        EffectRelevanceScope.SelectableJointPlan,
                        selectableSetFacts))
                    .Select(lane => (
                        State: state,
                        Lane: $"{lane}|weapons={weaponLane}"));
            })
            .GroupBy(entry => entry.Lane, StringComparer.Ordinal)
            .Select(group => group.First().State)
            .DistinctBy(StateKey)
            .Take(laneBudget)
            .ToList();
        // Preserve native weapon reach independently from raw item score and set
        // completion. First keep every individual type, then bounded distinct
        // two-slot combinations; a future skill/theme can therefore introduce a
        // new weapon contract without requiring an item-ID rule here.
        var weaponLaneBudget = Math.Min(Math.Max(1, limit / 6), 64);
        var weaponTypeReserved = ordered
            .SelectMany(state => state.Items
                .Where(item => item.Part == 1 && item.WeaponType > 0)
                .Select(item => (State: state, WeaponType: item.WeaponType)))
            .GroupBy(entry => entry.WeaponType)
            .OrderBy(group => group.Key)
            .Select(group => group.First().State)
            .DistinctBy(StateKey)
            .Take(weaponLaneBudget)
            .ToList();
        var weaponCombinationReserved = ordered
            .Where(state => WeaponCombinationKey(state).Length > 0)
            .GroupBy(WeaponCombinationKey, StringComparer.Ordinal)
            .Select(group => group.First())
            .DistinctBy(StateKey)
            .Take(weaponLaneBudget)
            .ToList();
        var selected = new Dictionary<string, LoadoutState>(StringComparer.Ordinal);
        foreach (var state in weaponTypeReserved
                     .Concat(setReserved)
                     .Concat(weaponCombinationReserved))
        {
            if (selected.Count >= limit) break;
            selected.TryAdd(StateKey(state), state);
        }
        foreach (var state in ordered)
        {
            if (selected.Count >= limit) break;
            selected.TryAdd(StateKey(state), state);
        }
        return selected.Values
            .OrderByDescending(Rank)
            .ThenBy(state => state, StableLoadoutStateComparer.Instance)
            .ThenBy(StateKey, StringComparer.Ordinal)
            .ToList();
    }

    private static Dictionary<int, List<SetEffectScoreRow>> GetSetEffectScoreRows()
    {
        var runtimeThresholdsAvailable = ReadEntries(ReadStatic("EquipSys", "setsEffectDic")).Any();
        if (setEffectScoreRows is not null
            && (setEffectRowsRuntimeCrossChecked || !runtimeThresholdsAvailable)) return setEffectScoreRows;
        var rawRows = ReadValues(ReadStatic("TableData", "TEquipSetsEffectDict"))
            .Select(effect => new
            {
                SetId = ReadNullableInt(effect, "sesId") ?? 0,
                EffectId = ReadNullableInt(effect, "id") ?? 0,
                Text = Clean(string.Join(" ", ReadString(effect, "des") ?? string.Empty, EnglishText(effect, "_des", string.Empty) ?? string.Empty)).ToLowerInvariant(),
                AbilityId = ReadNullableInt(effect, "abilityId") ?? 0,
                AbilityParameters = ReadSequence(Read(effect, "abilityParam")).Select(ToInt).ToList()
            })
            .Where(entry => entry.SetId > 0 && entry.EffectId > 0)
            .ToList();
        var rows = rawRows
            .GroupBy(entry => entry.SetId)
            .ToDictionary(group => group.Key, group =>
            {
                var wearCounts = GetSetEffectWearCounts(group.Key);
                // affixStr and the initialized runtime dictionary can each be
                // partial on different game builds. Merge both sources, but do
                // not invent an activation threshold from display ordering when
                // neither source knows the native wear count.
                return group
                    .Where(entry => wearCounts.TryGetValue(entry.EffectId, out var pieces)
                                    && pieces > 0)
                    .Select(entry => new SetEffectScoreRow(
                        entry.EffectId,
                        wearCounts[entry.EffectId],
                        entry.Text,
                        entry.AbilityId,
                        entry.AbilityParameters))
                    .OrderBy(entry => entry.Pieces).ToList();
            });
        if (rows.Count > 0)
        {
            setEffectScoreRows = rows;
            setEffectRowsRuntimeCrossChecked = runtimeThresholdsAvailable;
        }
        return rows;
    }

    private static Dictionary<int, int> GetSetEffectWearCounts(int setId)
    {
        var result = new Dictionary<int, int>();
        var set = InvokeStatic("TableData", "getTEquipSetsData", setId);
        var encoded = ReadString(set, "affixStr") ?? string.Empty;
        // Native InitSetsAffixDic parses semicolon-separated rows where the
        // first integer is wearCount and every remaining integer is an effect
        // id. A row can activate multiple effects at the same threshold.
        foreach (var row in encoded.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var values = row.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Select(value => int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) ? parsed : 0)
                .ToList();
            if (values.Count < 2 || values[0] <= 0) continue;
            var pieces = values[0];
            foreach (var effectId in values.Skip(1).Where(value => value > 0))
                result[effectId] = pieces;
        }

        // Merge the game's initialized runtime table even when affixStr parsed.
        // The live wearCount is authoritative on disagreement, while encoded
        // entries missing from the runtime dictionary are retained.
        foreach (var entry in ReadEntries(ReadStatic("EquipSys", "setsEffectDic")))
        {
            if (ToInt(Read(entry, "Key")) != setId) continue;
            foreach (var effectData in ReadSequence(Read(entry, "Value")))
            {
                var effectId = ReadNullableInt(Read(effectData, "tSetEffectData"), "id") ?? 0;
                var pieces = ReadNullableInt(effectData, "wearCount") ?? 0;
                if (effectId <= 0 || pieces <= 0) continue;
                if (result.TryGetValue(effectId, out var encodedPieces) && encodedPieces != pieces)
                    Plugin.DiagWarning(
                        $"AUTO-GEAR SET THRESHOLD MISMATCH|set={setId}|effect={effectId}|encoded={encodedPieces}|runtime={pieces}");
                result[effectId] = pieces;
            }
        }
        return result;
    }

    private static string GetSetThemeText(int setId, IReadOnlyCollection<SetEffectScoreRow> effects)
    {
        if (SetThemeTextCache.TryGetValue(setId, out var cached)) return cached;
        var set = InvokeStatic("TableData", "getTEquipSetsData", setId);
        var parts = new List<string>
        {
            ReadString(set, "name") ?? string.Empty,
            EnglishName(set, string.Empty) ?? string.Empty,
            ReadString(set, "des") ?? string.Empty
        };
        foreach (var member in ReadValues(ReadStatic("TableData", "TEquipDict"))
                     .Where(member => (ReadNullableInt(member, "setsId") ?? 0) == setId))
        {
            parts.Add(ReadString(member, "name") ?? string.Empty);
            parts.Add(EnglishName(member, string.Empty) ?? string.Empty);
            parts.Add(ReadString(member, "des") ?? string.Empty);
            parts.Add(EnglishText(member, "_des", string.Empty) ?? string.Empty);
        }
        parts.AddRange(effects.Select(effect => effect.Text));
        var text = Clean(string.Join(" ", parts)).ToLowerInvariant();
        if (!string.IsNullOrWhiteSpace(text)) SetThemeTextCache[setId] = text;
        return text;
    }

    private static bool IsSpecificElementFocus(string focusKey)
        => focusKey is "fire" or "ice" or "lightning";

    private static int GetOpposingElementThemeScore(string text, string focusKey)
        => focusKey switch
        {
            "fire" => Math.Max(KeywordScore(text, IceWords), KeywordScore(text, LightningWords)),
            "ice" => Math.Max(KeywordScore(text, FireWords), KeywordScore(text, LightningWords)),
            "lightning" => Math.Max(KeywordScore(text, FireWords), KeywordScore(text, IceWords)),
            _ => 0
        };

    private static string DescribeSetPlan(IEnumerable<GearCandidate> items, HeroEffectProfile profile)
    {
        var effectsBySet = GetSetEffectScoreRows();
        var parts = new List<string>();
        foreach (var group in items.Where(item => item.SetId > 0).GroupBy(item => item.SetId).OrderBy(group => group.Key))
        {
            effectsBySet.TryGetValue(group.Key, out var effects);
            effects ??= new List<SetEffectScoreRow>();
            var count = CountNativeSetPieces(group);
            var activeEffects = effects.Where(effect => effect.Pieces > 0 && effect.Pieces <= count).ToList();
            var text = Clean(string.Join(" ", activeEffects.Select(effect => effect.Text))).ToLowerInvariant();
            var active = activeEffects.Select(effect => effect.Pieces).Distinct().OrderBy(value => value);
            var guideCount = group.Where(item => profile.RecommendedEquipmentIds.Contains(item.DefinitionId))
                .Select(item => item.DefinitionId).Distinct().Count();
            parts.Add($"set={group.Key}/pieces={count}/active={string.Join(',', active)}/theme={KeywordScore(text, profile.Focus.Keywords)}/opposing={GetOpposingElementThemeScore(text, profile.Focus.Key)}/guide={guideCount}");
        }
        return parts.Count == 0 ? "none" : string.Join(" ; ", parts);
    }

    private static string DescribeSelectedItemScoreBreakdown(
        IReadOnlyList<GearSlot> slots,
        IReadOnlyList<GearCandidate> items,
        LoadoutEvaluation evaluation)
    {
        var breakdowns = evaluation.ItemScoreBreakdowns;
        var rows = new List<string>();
        for (var index = 0; index < Math.Min(slots.Count, items.Count); index++)
        {
            var candidate = items[index];
            var score = breakdowns is not null
                        && breakdowns.TryGetValue(candidate.Key, out var rescored)
                ? rescored
                : candidate.ScoreBreakdown;
            var inactive = score.InactiveSpecialEffects.Count == 0
                ? "none"
                : string.Join(",", score.InactiveSpecialEffects);
            rows.Add(
                $"{slots[index].Label}/{candidate.Record.Name}: "
                + $"prior {score.BaseItemPrior:0.0} + stats(base/sub/rune) {score.NativeAndAffixStats:0.0} "
                + $"+ affinity {score.TextAffinity:0.0} + relevant-special {score.RelevantSpecialEffects:0.0} "
                + $"+ dedup {score.DeduplicationAdjustment:0.0} = {score.Total:0.0}; "
                + $"active-special {score.ActiveSpecialEffectCount}, inactive-special [{inactive}]");
        }
        return string.Join(" | ", rows);
    }

    private static string DescribeSetThresholdBreakdown(
        IReadOnlyCollection<GearCandidate> items,
        HeroEffectProfile profile)
    {
        var effectsBySet = GetSetEffectScoreRows();
        var rows = new List<string>();
        foreach (var group in items.Where(item => item.SetId > 0)
                     .GroupBy(item => item.SetId)
                     .OrderBy(group => group.Key))
        {
            var count = CountNativeSetPieces(group);
            if (!effectsBySet.TryGetValue(group.Key, out var effects) || effects.Count == 0)
            {
                rows.Add($"set#{group.Key} {count}p/no verified threshold");
                continue;
            }

            var active = new List<string>();
            foreach (var effect in effects.Where(effect => effect.Pieces > 0 && effect.Pieces <= count))
            {
                var ability = ResolveAbilityTableRow(effect.AbilityId, 0);
                var relevant = IsNativeAbilityRelevantToProfile(
                                   ability, profile, EffectRelevanceScope.SelectedJointPlan)
                               && AreTextSkillDependenciesRelevant(
                                   effect.Text,
                                   profile,
                                   EffectRelevanceScope.SelectedJointPlan,
                                   ability);
                active.Add($"{effect.Pieces}p/effect#{effect.EffectId}={(relevant ? "active" : "0(skill mismatch)")}");
            }
            var next = effects.Where(effect => effect.Pieces > count)
                .Select(effect => effect.Pieces)
                .DefaultIfEmpty(0)
                .Min();
            rows.Add(
                $"set#{group.Key} {count}p: {(active.Count == 0 ? "no active effect" : string.Join(",", active))}"
                + (next > 0 ? $", next={next}p" : string.Empty));
        }
        return rows.Count == 0 ? "none" : string.Join(" | ", rows);
    }

    private static double InitializeFinalLoadoutScore(
        bool completeNativeEvaluation,
        double itemShortlistScore,
        double itemAbilityHeuristics,
        double nativeStructuralScore,
        double inactiveSetPenalty)
        => (completeNativeEvaluation
                ? nativeStructuralScore
                : itemShortlistScore - itemAbilityHeuristics)
           + inactiveSetPenalty;

    private static bool CanCandidateReplaceCurrentUnderCoverage(
        double currentScore,
        IReadOnlyCollection<int>? currentUnmodeledSetEffectIds,
        double candidateScore,
        IReadOnlyCollection<int>? candidateActiveSetEffectIds,
        out string reason)
    {
        if (!double.IsFinite(currentScore) || !double.IsFinite(candidateScore))
        {
            reason = "comparison score is not finite";
            return false;
        }
        // A tie is not evidence that moving eight real items is better. Keeping
        // the current loadout also avoids nondeterministic swaps when storage
        // enumeration order changes without any modeled performance gain.
        if (candidateScore <= currentScore + 0.000000001d)
        {
            reason = $"candidate score {candidateScore:0.######} does not exceed current {currentScore:0.######}";
            return false;
        }

        var candidateEffects = candidateActiveSetEffectIds is null
            ? new HashSet<int>()
            : candidateActiveSetEffectIds.Where(id => id > 0).ToHashSet();
        var missingUnmodeled = (currentUnmodeledSetEffectIds ?? Array.Empty<int>())
            .Where(id => id > 0 && !candidateEffects.Contains(id))
            .Distinct()
            .OrderBy(id => id)
            .ToList();
        if (missingUnmodeled.Count > 0)
        {
            reason = "candidate drops current active set effect(s) whose combat value is not fully modeled: "
                     + string.Join(',', missingUnmodeled);
            return false;
        }

        reason = string.Empty;
        return true;
    }

    private static LoadoutEvaluation EvaluateCompleteLoadout(
        List<GearCandidate> items,
        object hero,
        HeroEffectProfile baselineProfile,
        List<object> currentItems,
        bool rebuildMasteries = false,
        bool fullyOptimizeTalentLevels = false,
        bool resolveJointSkillProfile = true,
        bool evaluateFixedJointProfile = false,
        IncomingPressureProfile? incomingPressure = null)
    {
        try
        {
            // The caller owns the configured search window and checks before it
            // starts each candidate. Once a complete candidate evaluation has
            // begun, preserve its result even if it crosses the boundary by a
            // frame instead of discarding all work done for that candidate.
            ThrowIfAutoBuildSearchDeadlineReached();
            ThrowIfAutoBuildCancellationRequested();
            var defensePressure = incomingPressure
                                  ?? MainThreadNativeGateway.Invoke(() =>
                                      CaptureDefensePressureProfile(hero));
#if PATHOFIDLE_RUNTIME_TEST
            void TraceEvaluation(string stage)
            {
                ReportAutoBuildProgress(
                    AutoBuildStep.StructuralScreen,
                    detail: $"evaluation:{stage}");
                if (!resolveJointSkillProfile)
                    Plugin.DiagInfo($"AUTO-GEAR FAST EVAL|stage={stage}|elapsed={MainThreadNativeGateway.CurrentWorkerOperation?.PlanningElapsedSeconds ?? -1d:0.000}");
            }
            TraceEvaluation("start");
#endif
            // One finalist contains hundreds of native property reads and affix
            // applications. Execute that coherent snapshot as one short Unity
            // job instead of paying one rendered frame for every reflection call.
            // The immutable gear/talent-neutral template was already created by
            // the global skill planner, so no incumbent equipment is subtracted
            // again for every loadout.
            var simulated = MainThreadNativeGateway.Invoke(() => CreateJointLoadoutAttr(
                hero, items, currentItems, baselineProfile.PlannedSkills,
                includePlannedMasteries: !resolveJointSkillProfile
                                         || evaluateFixedJointProfile,
                neutralObjectiveAttr: baselineProfile.PlannedSkills.NeutralObjectiveAttr));
#if PATHOFIDLE_RUNTIME_TEST
            TraceEvaluation("loadout-attr");
#endif
            ThrowIfAutoBuildCancellationRequested();
            // One loadout's joint skill comparison is another immutable native
            // snapshot. Batch it just like the global plan so table/property
            // reads do not turn into hundreds of frame-spaced gateway requests.
            // The outer candidate loop and all beam/ranking work remain managed
            // worker work, and deadline/cancellation checks inside the resolver
            // remain active.
            var profile = resolveJointSkillProfile
                ? MainThreadNativeGateway.Invoke(() => ResolveJointSkillProfile(
                    items, hero, baselineProfile, simulated, defensePressure,
                    rebuildMasteries, fullyOptimizeTalentLevels))
                : baselineProfile;
#if PATHOFIDLE_RUNTIME_TEST
            TraceEvaluation("skill-profile");
#endif
            ThrowIfAutoBuildCancellationRequested();
            if (profile.Focus.Key != baselineProfile.Focus.Key)
                throw new InvalidOperationException($"Hero theme changed from {baselineProfile.Focus.Key} to {profile.Focus.Key} during evaluation.");
            if (profile.PreviewBaseSkillId <= 0 || !double.IsFinite(profile.JointSkillObjective)
                                                  || profile.JointSkillObjective < 0d)
                throw new InvalidOperationException($"Joint skill package is invalid ({profile.JointSkillReason}).");

            // The bounded gear comparison keeps the already-computed baseline
            // item scores. Re-reading every affix/effect for the same profile
            // consumed most of the search budget without changing rank.
            var completeJointEvaluation = resolveJointSkillProfile
                                          || evaluateFixedJointProfile;
            var rescoredItems = completeJointEvaluation
                ? MainThreadNativeGateway.Invoke(() =>
                    RescoreLoadoutForProfile(items, profile))
                : items.ToList();
#if PATHOFIDLE_RUNTIME_TEST
            TraceEvaluation("item-rescore");
#endif
            ThrowIfAutoBuildCancellationRequested();
            var nativeAbilities = completeJointEvaluation
                ? EvaluateNativeAbilityPackage(rescoredItems, hero, profile, simulated)
                : new NativeAbilityPackage(
                    0d, 0d, 0d, 0d, 0d,
                    new Dictionary<int, double>(),
                    new Dictionary<int, int>(),
                    true,
                    new HashSet<int>(),
                    new HashSet<int>());
#if PATHOFIDLE_RUNTIME_TEST
            TraceEvaluation("gear-abilities");
#endif
            ThrowIfAutoBuildCancellationRequested();
            if (completeJointEvaluation && !nativeAbilities.IsComplete)
                throw new InvalidOperationException(
                    $"Ability preview failed ({string.Join(',', nativeAbilities.FailedAbilityIds.OrderBy(id => id))}).");
            // Effect-type 3 and Set heuristics are useful during beam pruning, but
            // the finalist replaces them with one native AbilityData package. This
            // prevents the same conditional effect from being added twice.
            var itemScoreParts = MainThreadNativeGateway.Invoke(() =>
            {
                var inactiveSet = completeJointEvaluation
                    ? ScoreInactiveSetThresholdOpportunityCost(rescoredItems, profile)
                    : (Penalty: 0d, Count: 0, Details: string.Empty);
                return (
                    Total: ScoreItemsWithDeduplicatedEffects(
                        rescoredItems, profile, EffectRelevanceScope.SelectedJointPlan),
                    AbilityHeuristics: resolveJointSkillProfile
                        ? ScoreItemAbilityHeuristics(rescoredItems, profile)
                        : 0d,
                    InactiveSetPenalty: inactiveSet.Penalty,
                    InactiveSetCount: inactiveSet.Count,
                    InactiveSetDetails: inactiveSet.Details);
            });
            // Item scores are a fast shortlist prior only. Their raw attributes,
            // affixes, runes, and most ability outputs are already present in
            // the native AttrData/30-second performance result below. Adding the
            // prior again here double-counted them and could let a thematically
            // irrelevant loadout beat a challenger with demonstrably higher
            // native performance. Keep only ability structure that cannot be
            // represented numerically in AttrData; the final ordering is owned
            // by the common native performance calculation.
            var score = InitializeFinalLoadoutScore(
                completeJointEvaluation,
                itemScoreParts.Total,
                itemScoreParts.AbilityHeuristics,
                nativeAbilities.StructuralScore,
                itemScoreParts.InactiveSetPenalty);
            if (itemScoreParts.InactiveSetCount > 0)
                Plugin.DiagDebug(
                    $"AUTO-GEAR INACTIVE SET COST|count={itemScoreParts.InactiveSetCount}|penalty={itemScoreParts.InactiveSetPenalty:0.###}|{itemScoreParts.InactiveSetDetails}");
            // The complete native 30-second performance pass below already
            // measures the selected skill package. JointSkillObjective is used
            // inside the resolver to choose that package, but adding it here
            // would count the same combat output twice and made a repair path
            // (which deliberately reports zero) structurally lose to an
            // otherwise identical incumbent.
            // Unknown battle-only hooks receive a zero lower bound. Prefer a fully
            // modeled loadout only as a deterministic tie-break, never by an
            // invented positive bonus.
            score -= nativeAbilities.UnmodeledAbilityIds.Count * 0.000001d;
            var weaponTypes = rescoredItems.Where(item => item.Part == 1).Select(item => item.WeaponType).Where(value => value > 0).ToHashSet();
            if (profile.BaseWeaponRequirement.Count > 0
                && !profile.BaseWeaponRequirement.Overlaps(weaponTypes))
                score -= 30000d;
            foreach (var preference in profile.SkillWeaponPreferences)
                if (!preference.Overlaps(weaponTypes))
                    score -= 12000d;
            var prePerformanceScore = score;

            // Use the game's own AttrData calculations on a temporary copy. A
            // failed native performance preview invalidates this finalist instead
            // of silently retaining a heuristic-only score.
            var performanceResult = MainThreadNativeGateway.Invoke(() =>
            {
                var succeeded = TryEvaluateFinalPerformance(
                    rescoredItems, hero, profile, currentItems,
                    out var nativePerformance, out var nativeEffectiveAttr,
                    simulated, nativeAbilities,
                    baseSkillOnly: !completeJointEvaluation,
                    incomingPressure: defensePressure);
                return (Succeeded: succeeded, Performance: nativePerformance,
                    EffectiveAttr: nativeEffectiveAttr);
            });
            if (!performanceResult.Succeeded)
                throw new InvalidOperationException("The 30-second native preview produced no rankable output.");
            var performance = performanceResult.Performance;
            var effectiveAttr = performanceResult.EffectiveAttr;
#if PATHOFIDLE_RUNTIME_TEST
            TraceEvaluation("performance");
#endif
            // Callers stop starting new evaluations at the configured search
            // deadline. Preserve a complete native score when an evaluation
            // that started inside the window crosses the boundary by a frame.
            // An explicit user cancellation must still win.
            ThrowIfAutoBuildCancellationRequested();
            // Conversion sources and blockers can be supplied by gear abilities
            // or by the planned skill package. Reuse the final AttrData from the
            // native performance preview so dependency scoring observes exactly
            // the same state without repeating either expensive preview.
            var conversionResult = MainThreadNativeGateway.Invoke(() =>
            {
                var value = ScoreLoadoutConversionDependencies(
                    effectiveAttr, out var conflicts);
                return (Value: value, Conflicts: conflicts);
            });
            score += conversionResult.Value;
            var conversionConflicts = conversionResult.Conflicts;
            if (!string.IsNullOrWhiteSpace(conversionConflicts))
                Plugin.DiagDebug($"AUTO-GEAR CONVERSION CONFLICT|{conversionConflicts}");
            score += performance * 2.4d;
            if (!double.IsFinite(score)) throw new InvalidOperationException("The final loadout score is not finite.");
#if PATHOFIDLE_DIAGNOSTICS
            Plugin.DiagInfo(
                $"AUTO-GEAR FINAL SCORE|focus={profile.Focus.Key}|"
                + $"gear={string.Join(',', rescoredItems.Select(item => item.DefinitionId))}|"
                + $"itemTotal={itemScoreParts.Total:0.###}|abilityHeuristic={itemScoreParts.AbilityHeuristics:0.###}|"
                + $"nativeStructural={nativeAbilities.StructuralScore:0.###}|inactiveSetPenalty={itemScoreParts.InactiveSetPenalty:0.###}|"
                + $"activeSetEffects={string.Join(',', (nativeAbilities.ActiveRelevantSetEffectIds ?? new HashSet<int>()).OrderBy(id => id))}|"
                + $"unmodeledSetEffects={string.Join(',', (nativeAbilities.UnmodeledRelevantSetEffectIds ?? new HashSet<int>()).OrderBy(id => id))}|"
                + $"prePerformance={prePerformanceScore:0.###}|conversion={conversionResult.Value:0.###}|"
                + $"performance={performance:0.###}|performanceWeighted={performance * 2.4d:0.###}|total={score:0.###}");
#endif
            return new LoadoutEvaluation(
                score,
                profile,
                ItemScoreBreakdowns: rescoredItems
                    .GroupBy(candidate => candidate.Key, StringComparer.Ordinal)
                    .ToDictionary(
                        group => group.Key,
                        group => group.First().ScoreBreakdown,
                        StringComparer.Ordinal),
                ActiveRelevantSetEffectIds: nativeAbilities.ActiveRelevantSetEffectIds,
                UnmodeledRelevantSetEffectIds: nativeAbilities.UnmodeledRelevantSetEffectIds);
        }
        catch (Exception error)
        {
            var reason = error.GetBaseException().Message;
            Plugin.DiagDebug($"AUTO-GEAR FINALIST REJECTED|{reason}");
            return new LoadoutEvaluation(double.NegativeInfinity, baselineProfile, false, reason);
        }
    }

    private static double ScoreLoadoutConversionDependencies(object finalAttr, out string conflicts)
    {
        var rows = new List<string>();
        var penalty = 0d;
        void RequireSource(int modifierAttr, double sourceValue, params int[] blockingFlags)
        {
            var modifier = ReadAttrRequired(finalAttr, modifierAttr);
            if (!double.IsFinite(modifier) || modifier <= 0d) return;
            if (sourceValue > 0d && blockingFlags.All(flag => ReadAttrRequired(finalAttr, flag) <= 0d)) return;
            penalty -= Math.Min(2500d, 160d + Math.Abs(modifier) * 12d);
            rows.Add($"attr{modifierAttr}:source=0/blocked");
        }

        // The native final AttrData already contains each realized target stat;
        // these checks only penalize dangling source->target modifiers. They do
        // not add a second conversion bonus.
        RequireSource(702, ReadAttrRequired(finalAttr, 6));
        RequireSource(703, ReadAttrRequired(finalAttr, 6));
        RequireSource(704, ReadAttrRequired(finalAttr, 11) + ReadAttrRequired(finalAttr, 12));
        RequireSource(705, ReadAttrRequired(finalAttr, 12));
        RequireSource(707, ReadAttrRequired(finalAttr, 77));
        RequireSource(709, ReadAttrRequired(finalAttr, 7), 182);
        RequireSource(710, ReadAttrRequired(finalAttr, 78));
        RequireSource(711, ReadAttrRequired(finalAttr, 78));
        RequireSource(712, ReadAttrRequired(finalAttr, 77));
        conflicts = string.Join(",", rows);
        return penalty;
    }

    private static object CreateJointLoadoutAttr(
        object hero,
        IReadOnlyCollection<GearCandidate> items,
        IReadOnlyCollection<object> currentItems,
        PlannedSkillTarget planned,
        bool includePlannedMasteries = true,
        object? neutralObjectiveAttr = null)
    {
        var talentData = Read(hero, "heroTalentData") ?? throw new InvalidOperationException("HeroTalentData is unavailable.");
        var gridTalents = ReadValues(Read(talentData, "talentDic")).ToList();
        var simulated = neutralObjectiveAttr is null
            ? CreateTalentNeutralObjectiveAttr(hero, gridTalents)
            : InvokeRequiredStaticMany("AttrData", "copyCreate", neutralObjectiveAttr)
              ?? throw new InvalidOperationException("Neutral loadout AttrData copy failed.");
        if (neutralObjectiveAttr is null)
            foreach (var current in currentItems)
                ApplyEquipmentToAttr(simulated, current, false, includeForgeBonuses: true);
        foreach (var candidate in items)
            ApplyEquipmentToAttr(
                simulated,
                candidate.Record.ItemData,
                true,
                AutoBuildIncludesForgeBonuses);
        if (includePlannedMasteries)
            ApplyMinimumPlannedMasteryPreview(simulated, gridTalents, planned);
        return simulated;
    }

    private static void ApplyMinimumPlannedMasteryPreview(
        object attrData,
        IReadOnlyCollection<object> gridTalents,
        PlannedSkillTarget planned)
    {
        // The neutral copy intentionally removes the outgoing saved build. Give
        // every mastery selected by the native plan its first investable level so
        // finalist gear is not evaluated as if the planned masteries did nothing.
        // Exact remaining-point allocation is still performed by Auto Skills.
        foreach (var talentId in planned.MasteryTalentIds)
        {
            var talent = gridTalents.FirstOrDefault(value =>
                (ReadNullableInt(Read(value, "tTalentData"), "id") ?? 0) == talentId);
            var definition = Read(talent, "tTalentData") ?? InvokeStatic("TableData", "getTTalentData", talentId);
            var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
            if (definition is null || masteryId <= 0)
                throw new InvalidOperationException($"Planned mastery talent {talentId} is unavailable.");
            var cap = talent is null ? 1 : Math.Max(1, GetTalentLevelCap(talent));
            var baseLevel = talent is null ? 0 : Math.Min(GetTalentBaseLevelRequired(talent), cap);
            var targetLevel = Math.Min(cap, baseLevel + 1);
            if (targetLevel <= baseLevel)
                throw new InvalidOperationException($"Planned mastery talent {talentId} has no investable level.");
            ApplyMasteryAttributePreview(attrData, masteryId, targetLevel, cap, true);
        }
    }

    private static void ApplyPlannedMasteryLevelPreview(
        object attrData,
        IReadOnlyCollection<object> gridTalents,
        PlannedSkillTarget planned)
    {
        var gridById = BuildTalentGridById(gridTalents);
        foreach (var talentId in planned.MasteryTalentIds.OrderBy(id => id))
        {
            if (!gridById.TryGetValue(talentId, out var talent))
                throw new InvalidOperationException($"Planned mastery talent {talentId} is unavailable.");
            var definition = Read(talent, "tTalentData");
            var masteryId = ReadNullableInt(definition, "masteryId") ?? 0;
            var cap = GetTalentLevelCap(talent);
            var baseLevel = Math.Min(GetTalentBaseLevelRequired(talent), cap);
            var savedTarget = planned.TargetSavedLevels.GetValueOrDefault(talentId);
            if (savedTarget < 0 || savedTarget > Math.Max(0, cap - baseLevel))
                throw new InvalidOperationException(
                    $"Planned mastery talent {talentId} target {savedTarget} exceeds its native cap {cap} (base {baseLevel}).");
            if (baseLevel > 0)
                ApplyMasteryAttributePreview(attrData, masteryId, baseLevel, cap, false);
            if (baseLevel + savedTarget > 0)
                ApplyMasteryAttributePreview(attrData, masteryId, baseLevel + savedTarget, cap, true);
        }
    }

    private static List<GearCandidate> RescoreLoadoutForProfile(IEnumerable<GearCandidate> items, HeroEffectProfile profile)
        => items.Select(candidate =>
        {
            var equipmentScore = ScoreEquipment(
                candidate.Record.ItemData, profile, EffectRelevanceScope.SelectedJointPlan);
            var numericScore = EstimateEquipmentNumericScore(
                candidate.Record.ItemData, profile, EffectRelevanceScope.SelectedJointPlan);
            var rawScore = equipmentScore.Total + numericScore * 0.08d;
            var finalCandidateScore = ScoreSingleItemWithDeduplicatedEffects(
                candidate.Record.ItemData,
                profile,
                rawScore,
                EffectRelevanceScope.SelectedJointPlan);
            return candidate with
            {
                Score = finalCandidateScore,
                NumericScore = numericScore,
                DirectMatches = equipmentScore.DirectMatches,
                ThemeMatches = equipmentScore.ThemeMatches,
                ScoreBreakdown = CreateEquipmentScoreBreakdown(
                    equipmentScore,
                    numericScore,
                    finalCandidateScore)
            };
        }).ToList();

    private static HeroEffectProfile ResolveJointSkillProfile(
        IReadOnlyCollection<GearCandidate> items,
        object hero,
        HeroEffectProfile baseline,
        object simulatedAttr,
        IncomingPressureProfile incomingPressure,
        bool rebuildMasteries = false,
        bool fullyOptimizeTalentLevels = false)
    {
        var planned = baseline.PlannedSkills;
#if PATHOFIDLE_RUNTIME_TEST
        void TraceJoint(string detail)
        {
            ReportAutoBuildProgress(
                AutoBuildStep.StructuralScreen,
                detail: $"joint:{detail}");
            Plugin.DiagInfo(
                $"AUTO-SKILLS JOINT|stage={detail}|elapsed={MainThreadNativeGateway.CurrentWorkerOperation?.PlanningElapsedSeconds ?? -1d:0.000}");
        }
        var runtimeJointRejections = new List<string>();
        void RecordJointDetail(string detail)
        {
            if (runtimeJointRejections.Count >= 12) return;
            detail = Regex.Replace(detail, @"\s+", " ").Trim();
            if (detail.Length > 420) detail = detail[..417] + "...";
            runtimeJointRejections.Add(detail);
        }
        void RecordJointRejection(string stage, Exception error)
            => RecordJointDetail($"{stage}:{error.GetBaseException().Message}");
        TraceJoint("start");
#endif
        var weaponTypes = items.Where(item => item.Part == 1)
            .Select(item => item.WeaponType).Where(value => value > 0).ToHashSet();
        var setEffectRowsForJointPlan = GetSetEffectScoreRows();
        // Dependencies accumulate inside one set as its thresholds are reached,
        // but remain alternatives across different sets. Combining every set
        // into one global union can manufacture an impossible package when two
        // sets require different base skills.
        var reachedSetSkillConstraints = items
            .Where(item => item.SetId > 0)
            .GroupBy(item => item.SetId)
            .Select(group =>
            {
                if (!setEffectRowsForJointPlan.TryGetValue(group.Key, out var effects))
                    return (
                        SetId: group.Key,
                        SkillIds: new HashSet<int>(),
                        SkillTags: new HashSet<string>(StringComparer.Ordinal));
                var pieceCount = CountNativeSetPieces(group);
                var reachedEffects = effects
                    .Where(effect => effect.Pieces > 0 && effect.Pieces <= pieceCount)
                    .ToList();
                return (
                    SetId: group.Key,
                    SkillIds: reachedEffects
                    .SelectMany(effect => InferSkillDependenciesFromText(
                        effect.Text, baseline.JobId))
                    .Where(id => id > 0)
                    .ToHashSet(),
                    SkillTags: reachedEffects
                        .SelectMany(effect => InferSkillTagDependenciesFromText(effect.Text))
                        .Where(tag => tag.Length > 0)
                        .ToHashSet(StringComparer.Ordinal));
            })
            .Where(constraint => constraint.SkillIds.Count > 0 || constraint.SkillTags.Count > 0)
            .ToList();
        var reachedSetSkillDependencyGroups = reachedSetSkillConstraints
            .Where(constraint => constraint.SkillIds.Count > 0)
            .Select(constraint => constraint.SkillIds)
            .ToList();
        var reachedSetSkillTagDependencyGroups = reachedSetSkillConstraints
            .Where(constraint => constraint.SkillTags.Count > 0)
            .Select(constraint => constraint.SkillTags)
            .ToList();
        var plannedPackageWeaponMismatch =
            planned.BaseSkillId <= 0
            || !IsSkillCompatibleWithWeaponTypes(planned.BaseSkillId, weaponTypes)
            || planned.ActiveSkillIds.Any(id =>
                id > 0 && !IsSkillCompatibleWithWeaponTypes(id, weaponTypes));
        var hasRequiredThemeBaseContract = HasFocusedRoleConstraint(baseline.Focus)
                                           && planned.RequiredBaseSkillIds is { Count: > 0 };
        var plannedThemeBaseMismatch = hasRequiredThemeBaseContract
                                       && !planned.RequiredBaseSkillIds!.Contains(planned.BaseSkillId);

        var grantedActive = new HashSet<int>();
        var incompatibleGrantedActive = new HashSet<int>();
        foreach (var entry in items.SelectMany(candidate => GetGrantedExtraSkillLevels(candidate.Record.ItemData)))
        {
            const string prefix = "extra-skill:";
            if (!entry.Key.StartsWith(prefix, StringComparison.Ordinal)) continue;
            if (!int.TryParse(entry.Key.Substring(prefix.Length), NumberStyles.Integer, CultureInfo.InvariantCulture, out var skillId)
                || skillId <= 0) continue;
            if (IsSkillCompatibleWithWeaponTypes(skillId, weaponTypes))
                grantedActive.Add(skillId);
            else
                incompatibleGrantedActive.Add(skillId);
        }
        if (incompatibleGrantedActive.Count > 0) return baseline with
        {
            JointSkillObjective = -1000000d,
            JointSkillReason =
                $"candidate gear grants weapon-incompatible skills ({string.Join(',', incompatibleGrantedActive.OrderBy(id => id))})"
        };

        var talentData = Read(hero, "heroTalentData");
        var fixedGridTalentIdsBySkillId = talentData is null
            ? new Dictionary<int, int>()
            : GetTransformableTalents(talentData)
                .Where(talent => !IsTalentLockedRequired(talent) && IsTalentUnreplaceable(talent))
                .Select(talent => Read(talent, "tTalentData"))
                .Select(row => (
                    TalentId: ReadNullableInt(row, "id") ?? 0,
                    SkillId: ReadNullableInt(row, "skillId") ?? 0,
                    Floor: ReadNullableInt(row, "floor") ?? int.MaxValue,
                    Index: ReadNullableInt(row, "index") ?? int.MaxValue))
                .Where(entry => entry.TalentId > 0 && entry.SkillId > 0)
                .GroupBy(entry => entry.SkillId)
                .ToDictionary(
                    group => group.Key,
                    group => group.OrderBy(entry => entry.Floor).ThenBy(entry => entry.Index)
                        .ThenBy(entry => entry.TalentId).First().TalentId);
        var fixedGridActive = fixedGridTalentIdsBySkillId.Keys.ToHashSet();
        // Equipment-granted skills are present in native GetSkillList regardless
        // of shrine-row selection, so include them in every package without
        // consuming one of the hero's ordinary active rows.
        var packageFixedActive = fixedGridActive.Concat(grantedActive).ToHashSet();
        if (packageFixedActive.Any(id => !IsSkillCompatibleWithWeaponTypes(id, weaponTypes)))
            return baseline with
            {
                JointSkillObjective = -1000000d,
                JointSkillReason = "candidate weapons cannot use a fixed active skill"
            };

        var plannedPackageSkillIds = planned.ActiveSkillIds
            .Concat(packageFixedActive)
            .Append(planned.BaseSkillId).Where(id => id > 0).ToHashSet();
        bool SatisfiesSkillTagDependencyGroup(
            IEnumerable<int> skillIds,
            IReadOnlyCollection<string> requiredTags)
        {
            var packageSkillIds = skillIds.Where(id => id > 0).Distinct().ToList();
            return requiredTags.Count > 0 && requiredTags.All(tag =>
                packageSkillIds.Any(skillId => tag switch
                {
                    "minion" => SkillHasNativeTagCore(skillId, "minion", "summon"),
                    "mastery-or-utility" => SkillHasNativeTagCore(
                        skillId, "mastery", "utility"),
                    "shield-producer" => SkillProducesShieldCore(skillId),
                    _ => SkillHasNativeTagCore(skillId, tag)
                }));
        }
        bool SatisfiesSetSkillConstraint(
            IEnumerable<int> skillIds,
            (int SetId, HashSet<int> SkillIds, HashSet<string> SkillTags) constraint)
        {
            var packageSkillIds = skillIds.Where(id => id > 0).ToHashSet();
            return constraint.SkillIds.All(packageSkillIds.Contains)
                   && (constraint.SkillTags.Count == 0
                       || SatisfiesSkillTagDependencyGroup(packageSkillIds, constraint.SkillTags));
        }
        var unmetSetSkillConstraints = reachedSetSkillConstraints
            .Where(constraint => !SatisfiesSetSkillConstraint(
                plannedPackageSkillIds, constraint))
            .ToList();
        var unmetSetSkillDependencyGroups = unmetSetSkillConstraints
            .Where(constraint => constraint.SkillIds.Count > 0)
            .Select(constraint => constraint.SkillIds)
            .ToList();
        var unmetSetSkillTagDependencyGroups = unmetSetSkillConstraints
            .Where(constraint => constraint.SkillTags.Count > 0)
            .Select(constraint => constraint.SkillTags)
            .ToList();
        var plannedSetDependencyMismatch = unmetSetSkillConstraints.Count > 0;
        var boundedJointRepair = (plannedPackageWeaponMismatch
                                  || plannedSetDependencyMismatch
                                  || plannedThemeBaseMismatch)
                                 && MainThreadNativeGateway.CurrentWorkerOperation is not null;
        var boundedInteractivePackageSearch =
            MainThreadNativeGateway.CurrentWorkerOperation is not null
            && !fullyOptimizeTalentLevels;
        // Only the structural coverage pass explores alternate skill packages.
        // Coarse ranking and full refinement evaluate the package already chosen
        // by the preceding stage; repeating every base/active alternative there
        // turned one nominally coarse loadout into a minute-long calculation.
        // A weapon mismatch is the exception: use the already-ranked complete
        // candidate pool to substitute a compatible package before mutation.
        var coverageScreen = (rebuildMasteries && !fullyOptimizeTalentLevels)
                             || plannedPackageWeaponMismatch
                             || plannedSetDependencyMismatch
                             || plannedThemeBaseMismatch
                             || boundedInteractivePackageSearch;
        var expandBaseCandidates = (rebuildMasteries && !fullyOptimizeTalentLevels)
                                   || plannedPackageWeaponMismatch
                                   || plannedSetDependencyMismatch
                                   || plannedThemeBaseMismatch;
        // A remembered/current-gear plan can legitimately carry an older base
        // candidate census while retaining the freshly derived theme contract.
        // Recover the contract-required base from the job's native talent table;
        // RequiredBaseSkillIds itself came only from the unlocked census, so this
        // does not make an unavailable cross-job skill selectable.
        var requiredThemeBaseSource = hasRequiredThemeBaseContract
            ? ReadValues(ReadStatic("TableData", "TTalentDict"))
                .Where(IsBaseSkillDefinition)
                .Where(row => (ReadNullableInt(row, "jobId") ?? 0) == baseline.JobId)
                .Select(row => ReadNullableInt(row, "skillId") ?? 0)
                .Where(id => id > 0 && planned.RequiredBaseSkillIds!.Contains(id))
            : Enumerable.Empty<int>();
        var baseSource = (expandBaseCandidates
            ? planned.BaseCandidateSkillIds.Append(planned.BaseSkillId)
            : new[] { planned.BaseSkillId })
            .Concat(requiredThemeBaseSource);
        var baseCandidates = baseSource
            .Where(id => id > 0 && IsSkillCompatibleWithWeaponTypes(id, weaponTypes))
            .Distinct().OrderBy(id => id).ToList();
        if (hasRequiredThemeBaseContract)
        {
            // This is an invariant, not merely mismatch recovery: once the
            // selected lane exposes native base skills, every other base is
            // incapable of satisfying the contract. A separate repair reason
            // (for example a reached set dependency) may expand base candidates
            // even when the remembered base is already correct, so filter every
            // expansion before any deadline-sensitive screening.
            baseCandidates = baseCandidates
                .Where(id => planned.RequiredBaseSkillIds!.Contains(id))
                .OrderByDescending(id => planned.ObjectiveBySkillId.GetValueOrDefault(id))
                .ThenBy(id => id)
                .ToList();
        }
        if (boundedJointRepair)
        {
            // Weapon repair stays bounded to one strongest usable base. A set
            // mismatch may additionally require another base, so preserve one
            // compatible base representative per reached set dependency group.
            var primaryBase = !plannedThemeBaseMismatch
                              && baseCandidates.Contains(planned.BaseSkillId)
                ? planned.BaseSkillId
                : baseCandidates
                    .Where(id => !plannedThemeBaseMismatch
                                 || planned.RequiredBaseSkillIds?.Contains(id) == true)
                    .OrderByDescending(id => planned.ObjectiveBySkillId.GetValueOrDefault(id))
                    .ThenBy(id => id)
                    .FirstOrDefault();
            var themeBaseRepresentative = HasFocusedRoleConstraint(baseline.Focus)
                ? baseCandidates
                    .Where(id => planned.RequiredBaseSkillIds?.Contains(id) == true)
                    .OrderByDescending(id => planned.ObjectiveBySkillId.GetValueOrDefault(id))
                    .ThenBy(id => id)
                    .FirstOrDefault()
                : 0;
            var setBaseRepresentatives = plannedSetDependencyMismatch
                ? unmetSetSkillDependencyGroups.Select(group => group
                        .Where(id => planned.BaseCandidateSkillIds.Contains(id)
                                     && baseCandidates.Contains(id))
                        .OrderByDescending(id => planned.ObjectiveBySkillId.GetValueOrDefault(id))
                        .ThenBy(id => id)
                        .FirstOrDefault())
                    .Where(id => id > 0)
                : Enumerable.Empty<int>();
            var setTagBaseRepresentatives = plannedSetDependencyMismatch
                ? unmetSetSkillTagDependencyGroups.Select(group => baseCandidates
                        .Where(id => SatisfiesSkillTagDependencyGroup(new[] { id }, group))
                        .OrderByDescending(id => planned.ObjectiveBySkillId.GetValueOrDefault(id))
                        .ThenBy(id => id)
                        .FirstOrDefault())
                    .Where(id => id > 0)
                : Enumerable.Empty<int>();
            baseCandidates = new[] { themeBaseRepresentative, primaryBase }
                .Concat(setBaseRepresentatives)
                .Concat(setTagBaseRepresentatives)
                .Where(id => id > 0).Distinct().ToList();
        }
        var ordinaryActiveSource = coverageScreen
            ? planned.ActiveCandidateSkillIds.Concat(planned.ActiveSkillIds)
            : planned.ActiveSkillIds;
        var ordinaryActiveCandidates = ordinaryActiveSource
            .Where(id => id > 0 && IsSkillCompatibleWithWeaponTypes(id, weaponTypes))
            .Distinct().OrderBy(id => id).ToList();
        if (baseCandidates.Count == 0) return baseline with
        {
            JointSkillObjective = -1000000d,
            JointSkillReason = "no weapon-compatible base skill"
        };
        ordinaryActiveCandidates = ordinaryActiveCandidates.Concat(fixedGridActive)
            .Distinct().OrderBy(id => id).ToList();

        var allJobSkillRows = GetHeroSkillTalentRows(hero);
        var requiredContractSkillIds = (planned.RequiredBaseSkillIds ?? new HashSet<int>())
            .Concat(planned.RequiredActiveSkillIds ?? new HashSet<int>())
            .Concat(planned.ThemePackageSkillIds ?? new HashSet<int>())
            .Where(id => id > 0).ToHashSet();
        bool SatisfiesFocusedThemeContract(int baseSkillId, IEnumerable<int> activeSkillIds)
        {
            if (!HasFocusedRoleConstraint(baseline.Focus) || requiredContractSkillIds.Count == 0)
                return true;
            return SatisfiesThemeSkillContract(
                baseSkillId,
                activeSkillIds,
                grantedActive,
                planned.RequiredBaseSkillIds,
                planned.RequiredActiveSkillIds,
                planned.ThemePackageSkillIds,
                planned.RequiredThemeSkillCount);
        }

        var roleCache = new Dictionary<(int SkillId, int Level), NativeSkillRoleProfile>();
        var strictAbilityPreviewCache = new Dictionary<(int SkillId, int Level), NativeSkillAlwaysOnPreview>();
        bool IsStructurallyRequiredSkill(int skillId)
        {
            if (skillId <= 0) return false;
            if (requiredContractSkillIds.Contains(skillId)
                || packageFixedActive.Contains(skillId)) return true;
            if (reachedSetSkillConstraints.Any(constraint =>
                    constraint.SkillIds.Contains(skillId)
                    || constraint.SkillTags.Any(tag =>
                        SatisfiesSkillTagDependencyGroup(new[] { skillId }, new[] { tag }))))
                return true;
            return items.SelectMany(candidate => candidate.SelectableFacts.VariantIds)
                .Any(id => id == skillId);
        }
        NativeSkillRoleProfile RoleFor(
            int skillId,
            int level,
            object? roleAttr = null,
            bool applyOwnAlwaysOnAbilityAttrs = true)
        {
            roleAttr ??= simulatedAttr;
            level = Math.Max(1, Math.Max(level, GetGrantedSkillLevel(items, skillId)));
            var cacheable = ReferenceEquals(roleAttr, simulatedAttr) && applyOwnAlwaysOnAbilityAttrs;
            if (cacheable && roleCache.TryGetValue((skillId, level), out var cached)) return cached;
            var role = ReadNativeSkillRoleProfile(
                hero, skillId, level, roleAttr, false, items, true, applyOwnAlwaysOnAbilityAttrs);
            if (!IsNativeRoleRankable(role, baseline.Focus)
                && !IsStructurallyRequiredSkill(skillId))
                throw new InvalidOperationException(
                    $"Skill {skillId} level {level} has no rankable joint output: {role.Failure}");
            if (cacheable) roleCache[(skillId, level)] = role;
            return role;
        }
        NativeSkillRoleProfile SeedRoleFor(int skillId)
        {
            var level = planned.TargetSavedLevels.Count > 0
                ? planned.BaseSkillId == skillId ? planned.BaseSkillLevel : 1
                : 1;
            return RoleFor(skillId, level);
        }

        var planningGridTalents = talentData is null
            ? new List<object>()
            : ReadValues(ReadRequiredProperty(talentData, "talentDic"))
                .DistinctBy(talent => NativeObjectKey(talent, talent)).ToList();
        var planningGridById = MainThreadNativeGateway.Invoke(() => planningGridTalents
            .Select(talent => (
                Id: ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0,
                Talent: talent))
            .Where(entry => entry.Id > 0)
            .GroupBy(entry => entry.Id)
            .ToDictionary(group => group.Key, group => group.First().Talent));
        List<int> ResolveTalentIds(int baseSkillId, IEnumerable<int> activeSkillIds)
        {
            var selected = activeSkillIds.Append(baseSkillId).Where(id => id > 0).ToHashSet();
            var resolved = allJobSkillRows.Where(row => selected.Contains(ReadNullableInt(row, "skillId") ?? 0))
                .GroupBy(row => ReadNullableInt(row, "skillId") ?? 0)
                .Where(group => group.Key > 0)
                .Select(group => fixedGridTalentIdsBySkillId.TryGetValue(group.Key, out var fixedTalentId)
                    ? fixedTalentId
                    : group.OrderBy(row => group.Key == baseSkillId && IsBaseSkillDefinition(row) ? 0 : 1)
                        .ThenBy(row => ReadNullableInt(row, "index") ?? int.MaxValue)
                        .ThenBy(row => ReadNullableInt(row, "id") ?? int.MaxValue)
                        .Select(row => ReadNullableInt(row, "id") ?? 0)
                        .FirstOrDefault(id => id > 0))
                .Where(id => id > 0).ToList();
            if (resolved.Count != selected.Count)
                throw new InvalidOperationException("The joint package contains a skill with no owned or legal job talent row.");
            return resolved;
        }
        HeroEffectProfile WithCandidateJointTargets(
            IReadOnlyCollection<int> selectedSkillIds,
            IReadOnlyCollection<int> selectedTalentIds,
            IReadOnlyCollection<int> masteryTalentIds,
            PlannedSkillTarget targetPlan)
        {
            var masteryIds = masteryTalentIds
                .Select(id => ReadNullableInt(InvokeStatic("TableData", "getTTalentData", id), "masteryId") ?? 0)
                .Where(id => id > 0).ToHashSet();
            var talentIds = selectedTalentIds.Concat(masteryTalentIds)
                .Where(id => id > 0).ToHashSet();
            var candidateSkillRows = selectedSkillIds
                .Where(id => id > 0)
                .Select(id => (SkillId: id, Row: InvokeStatic("TableData", "getTSkillData", id)))
                .Where(entry => entry.Row is not null)
                .ToList();
            var candidateTags = candidateSkillRows
                .SelectMany(entry =>
                {
                    var infoId = ReadNullableInt(entry.Row, "infoId") ?? 0;
                    var info = infoId > 0
                        ? InvokeStatic("TableData", "getTSkillInfoData", infoId)
                        : null;
                    return ReadSequence(Read(info, "tagArr")).Select(ToInt);
                })
                .Where(id => id > 0).ToHashSet();
            var candidateBaseRow = candidateSkillRows
                .FirstOrDefault(entry => entry.SkillId == targetPlan.BaseSkillId).Row;
            var candidateBaseWeapons = ReadSequence(Read(candidateBaseRow, "weaponArr"))
                .Select(ToInt).Where(id => id > 0).ToHashSet();
            var candidateActiveWeaponPreferences = candidateSkillRows
                .Where(entry => entry.SkillId != targetPlan.BaseSkillId)
                .Select(entry => ReadSequence(Read(entry.Row, "weaponArr"))
                    .Select(ToInt).Where(id => id > 0).ToHashSet())
                .Where(required => required.Count > 0)
                .DistinctBy(required => string.Join(",", required.OrderBy(id => id)))
                .ToList();
            return baseline with
            {
                BaseWeaponRequirement = candidateBaseWeapons,
                SkillWeaponPreferences = candidateActiveWeaponPreferences,
                ActiveSkillMainType = ReadNullableInt(candidateBaseRow, "type") ?? 0,
                ActiveSkillTags = candidateTags,
                ControlledEntityKinds = GetNativeControlledEntityKindsForSkillsCore(selectedSkillIds),
                PreviewBaseSkillId = targetPlan.BaseSkillId,
                PreviewBaseSkillLevel = Math.Max(1, targetPlan.BaseSkillLevel),
                SkillIds = selectedSkillIds.ToHashSet(),
                TalentIds = talentIds,
                MasteryIds = masteryIds,
                PreferredSkillIds = selectedSkillIds.ToHashSet(),
                PreferredTalentIds = new HashSet<int>(talentIds),
                PreferredMasteryIds = new HashSet<int>(masteryIds),
                PlannedSkills = targetPlan
            };
        }

        var bestBase = baseCandidates[0];
        var bestActive = new List<int>();
        var bestScore = double.NegativeInfinity;
        var bestNativeRoleScore = double.NegativeInfinity;
        var bestRedundantGrantedActiveCount = int.MaxValue;
        var bestMasteryCandidateIds = new List<int>();
        TalentLevelPlan? resolvedBestLevelPlan = null;
        // Register the already complete global plan as a safe incumbent before
        // starting any optional candidate work. A deadline may stop new work,
        // but it must not turn a verified exact-budget plan into "no result".
        var fallbackActive = planned.ActiveSkillIds
            .Where(id => id > 0 && id != planned.BaseSkillId)
            .Distinct().OrderBy(id => id).ToList();
        var fallbackSkillIds = fallbackActive.Concat(grantedActive)
            .Append(planned.BaseSkillId).Where(id => id > 0).Distinct().ToList();
        // The reusable-plan check and effective-level snapshot touch the same
        // native skill/equipment graph repeatedly. Keep them in one Unity-thread
        // job; scheduling each lookup on a separate rendered frame cost roughly
        // eight seconds per loadout even though the computation itself is small.
        var reusableIncumbent = MainThreadNativeGateway.Invoke(() =>
        {
            var canReuse = baseCandidates.Contains(planned.BaseSkillId)
                           && !plannedPackageWeaponMismatch
                           && SatisfiesFocusedThemeContract(
                               planned.BaseSkillId, fallbackActive)
                           && planned.TargetSavedLevels.Values.Sum()
                           == checked(planned.TotalTalentPointBudget + 1);
            if (!canReuse)
                return (
                    CanReuse: false,
                    RedundantGranted: 0,
                    EffectiveLevels: new Dictionary<int, int>());
            return (
                CanReuse: true,
                RedundantGranted: fallbackActive.Count(id =>
                    GetGrantedSkillLevel(items, id) > 0
                    && GetPlannedSkillEffectiveLevel(hero, planned, id, items)
                    <= GetGrantedSkillLevel(items, id)),
                EffectiveLevels: fallbackSkillIds.ToDictionary(
                    id => id,
                    id => GetPlannedSkillEffectiveLevel(hero, planned, id, items)));
        });
        if (reusableIncumbent.CanReuse)
        {
            bestBase = planned.BaseSkillId;
            bestActive = fallbackActive;
            // This is an unscored fallback, not a competitor. The first fairly
            // screened package must replace it regardless of score scale.
            bestScore = double.NegativeInfinity;
            bestNativeRoleScore = Math.Max(0d, baseline.JointSkillObjective);
            bestRedundantGrantedActiveCount = reusableIncumbent.RedundantGranted;
            bestMasteryCandidateIds = planned.MasteryTalentIds
                .Distinct().OrderBy(id => id).ToList();
            resolvedBestLevelPlan = new TalentLevelPlan(
                new Dictionary<int, int>(planned.TargetSavedLevels),
                reusableIncumbent.EffectiveLevels,
                planned.PlanToken);
#if PATHOFIDLE_RUNTIME_TEST
            TraceJoint("safe-incumbent");
#endif
        }
        foreach (var baseSkillId in baseCandidates)
        {
#if PATHOFIDLE_RUNTIME_TEST
            TraceJoint($"base-{baseSkillId}-start");
#endif
            if (resolvedBestLevelPlan is not null && AutoBuildSearchDeadlineReached()) break;
            ThrowIfAutoBuildSearchDeadlineReached();
            var slotCount = Math.Max(fixedGridActive.Count,
                Math.Min(Math.Max(0, planned.ActiveSlotCount), ordinaryActiveCandidates.Count));
            // A skill supplied by equipment is already present in native
            // GetSkillList and consumes neither a shrine row nor a talent point.
            // Selecting it again as an ordinary learned skill wastes a physical
            // row and can make an otherwise valid exact point plan fail when the
            // granted effect itself is conditional-only. A genuinely fixed grid
            // row is preserved above even when equipment also grants that skill.
            var optional = ordinaryActiveCandidates
                .Where(id => !fixedGridActive.Contains(id) && !grantedActive.Contains(id))
                .ToList();
            var optionalCapacity = Math.Min(Math.Max(0, slotCount - fixedGridActive.Count), optional.Count);
            var optionalSet = optional.ToHashSet();
            var optionalByObjective = optional
                .OrderByDescending(id => planned.ObjectiveBySkillId.GetValueOrDefault(id))
                .ThenBy(id => id)
                .ToList();
            List<int>? CompleteOptionalPackage(
                IEnumerable<int> required,
                ISet<int>? forbidden = null)
            {
                var selected = required.Where(id => id > 0).Distinct().ToList();
                var hardRequired = selected.ToHashSet();
                if (selected.Any(id => !optionalSet.Contains(id))
                    || (forbidden is not null && selected.Any(forbidden.Contains))
                    || selected.Count > optionalCapacity) return null;

                for (var repair = 0;
                     repair <= optionalCapacity + 1
                     && !SatisfiesFocusedThemeContract(
                         baseSkillId, fixedGridActive.Concat(selected));
                     repair++)
                {
                    var corePresent = planned.RequiredBaseSkillIds?.Contains(baseSkillId) == true
                                      || fixedGridActive.Concat(selected).Concat(grantedActive)
                                          .Any(id => planned.RequiredActiveSkillIds?.Contains(id) == true);
                    var repairPool = corePresent
                        ? planned.ThemePackageSkillIds ?? planned.RequiredActiveSkillIds
                        : planned.RequiredActiveSkillIds;
                    var themeRepresentative = optionalByObjective.FirstOrDefault(id =>
                        repairPool?.Contains(id) == true
                        && forbidden?.Contains(id) != true
                        && !selected.Contains(id));
                    if (themeRepresentative <= 0) return null;
                    if (selected.Count >= optionalCapacity)
                    {
                        var remove = selected
                            .Select((id, index) => (Id: id, Index: index))
                            .Where(entry => !hardRequired.Contains(entry.Id))
                            .OrderBy(entry => planned.ThemePackageSkillIds?.Contains(entry.Id) == true ? 1 : 0)
                            .ThenBy(entry => planned.RequiredActiveSkillIds?.Contains(entry.Id) == true ? 1 : 0)
                            .ThenBy(entry => planned.ObjectiveBySkillId.GetValueOrDefault(entry.Id))
                            .FirstOrDefault();
                        if (remove.Id <= 0) return null;
                        selected.RemoveAt(remove.Index);
                    }
                    selected.Add(themeRepresentative);
                }
                if (!SatisfiesFocusedThemeContract(
                        baseSkillId, fixedGridActive.Concat(selected))) return null;
                foreach (var skillId in optionalByObjective)
                {
                    if (selected.Count >= optionalCapacity) break;
                    if (forbidden?.Contains(skillId) == true) continue;
                    if (!selected.Contains(skillId)) selected.Add(skillId);
                }
                if (selected.Count != optionalCapacity) return null;
                return fixedGridActive.Concat(selected)
                    .Distinct().OrderBy(id => id).ToList();
            }
            long packageCount = 0;
            for (var choose = 0; choose <= optionalCapacity && packageCount <= 512; choose++)
                packageCount += GetCombinationCount(optional.Count, choose);
            // The exact screening pass has already compared every retained skill
            // package for this loadout. Its winner is carried in `planned`; the
            // expensive nonlinear point allocator must refine that same package,
            // rather than repeating the full allocator for every alternative.
            // A failed full refinement is handled by the outer finalist fallback.
            IEnumerable<List<int>> rawCombinations = fullyOptimizeTalentLevels
                ? new[]
                {
                    fixedGridActive.Concat(optional)
                        .Distinct().OrderBy(id => id).ToList()
                }.AsEnumerable()
                : !coverageScreen
                    ? new[]
                    {
                        fixedGridActive.Concat(optional.Where(planned.ActiveSkillIds.Contains))
                            .Distinct().OrderBy(id => id).ToList()
                    }.AsEnumerable()
                : packageCount <= 512
                    ? Enumerable.Range(0, optionalCapacity + 1)
                        .SelectMany(choose => EnumerateSkillCombinations(optional, choose)
                            .Select(selected => fixedGridActive.Concat(selected).Distinct().OrderBy(id => id).ToList()))
                    : Enumerable.Range(0, optionalCapacity + 1)
                        .SelectMany(choose => EnumerateGreedySkillPackages(optional, choose, baseSkillId, SeedRoleFor, baseline.Focus)
                            .Select(selected => fixedGridActive.Concat(selected).Distinct().OrderBy(id => id).ToList()));
            if (boundedInteractivePackageSearch)
            {
                // Compare the incumbent package, a gear-neutral objective package,
                // every one-skill removal/replacement around the incumbent, and a
                // few top forced alternatives. No skill name or ID is privileged.
                // The cheap objective orders this bounded neighborhood before the
                // native 30-second screen below.
                var boundedPackages = new List<List<int>>();
                void AddBoundedPackage(List<int>? candidate)
                {
                    if (candidate is not null) boundedPackages.Add(candidate);
                }
                var plannedOptional = optional
                    .Where(planned.ActiveSkillIds.Contains)
                    .OrderByDescending(id => planned.ObjectiveBySkillId.GetValueOrDefault(id))
                    .ThenBy(id => id)
                    .Take(optionalCapacity)
                    .ToList();
                var repaired = CompleteOptionalPackage(
                    plannedOptional);
                AddBoundedPackage(repaired);
                var objectiveFallback = CompleteOptionalPackage(Array.Empty<int>());
                AddBoundedPackage(objectiveFallback);
                foreach (var excludedSkillId in plannedOptional)
                    AddBoundedPackage(CompleteOptionalPackage(
                        plannedOptional.Where(id => id != excludedSkillId),
                        new HashSet<int> { excludedSkillId }));
                foreach (var forcedSkillId in optionalByObjective
                             .Where(id => !plannedOptional.Contains(id))
                             .Take(4))
                {
                    var retained = plannedOptional
                        .Where(id => id != forcedSkillId)
                        .Take(Math.Max(0, optionalCapacity - 1));
                    AddBoundedPackage(CompleteOptionalPackage(
                        retained.Append(forcedSkillId)));
                }
                rawCombinations = boundedPackages
                    .GroupBy(selected => string.Join(",", selected), StringComparer.Ordinal)
                    .Select(group => group.First());
            }
            if (coverageScreen && reachedSetSkillConstraints.Count > 0)
            {
                foreach (var constraint in reachedSetSkillConstraints)
                {
                    var packageConstants = fixedGridActive.Concat(grantedActive)
                        .Append(baseSkillId).Where(id => id > 0).ToList();
                    var dependenciesOutsideThisPackage = constraint.SkillIds
                        .Where(id => id != baseSkillId
                                     && !fixedGridActive.Contains(id)
                                     && !grantedActive.Contains(id))
                        .ToList();
                    var tagSatisfiedByExactPackage = packageConstants
                        .Concat(dependenciesOutsideThisPackage)
                        .ToList();
                    var requiredTagRepresentatives = constraint.SkillTags
                        .Where(tag => !SatisfiesSkillTagDependencyGroup(
                            tagSatisfiedByExactPackage, new[] { tag }))
                        .Select(tag => optionalByObjective.FirstOrDefault(id =>
                            SatisfiesSkillTagDependencyGroup(new[] { id }, new[] { tag })))
                        .Where(id => id > 0)
                        .Distinct()
                        .ToList();
                    var allDependenciesSelectable = constraint.SkillIds.All(id =>
                        id == baseSkillId
                        || fixedGridActive.Contains(id)
                        || grantedActive.Contains(id)
                        || optionalSet.Contains(id));
                    var allTagsSelectable = constraint.SkillTags.All(tag =>
                        SatisfiesSkillTagDependencyGroup(
                            packageConstants.Concat(optional), new[] { tag }));
                    var setDependencyPackage = CompleteOptionalPackage(
                        dependenciesOutsideThisPackage.Concat(requiredTagRepresentatives));
                    if (allDependenciesSelectable
                        && allTagsSelectable
                        && setDependencyPackage is not null
                        && SatisfiesSetSkillConstraint(
                            setDependencyPackage.Concat(grantedActive).Append(baseSkillId),
                            constraint))
                        rawCombinations = rawCombinations.Append(setDependencyPackage);
                }

                // A mixed loadout can activate more than one named-skill set
                // threshold at once. Screening one set dependency at a time can
                // miss the only coherent package (for example one set requiring
                // a utility skill while another requires the primary attack).
                // Build one additional package from the union of every reached
                // dependency, then let the same native score decide whether it
                // beats the incumbent. No set or skill ID is privileged.
                var combinedConstants = fixedGridActive.Concat(grantedActive)
                    .Append(baseSkillId).Where(id => id > 0).Distinct().ToList();
                var combinedDependencies = reachedSetSkillConstraints
                    .SelectMany(constraint => constraint.SkillIds)
                    .Where(id => id != baseSkillId
                                 && !fixedGridActive.Contains(id)
                                 && !grantedActive.Contains(id))
                    .Distinct().ToList();
                var combinedTagRepresentatives = reachedSetSkillConstraints
                    .SelectMany(constraint => constraint.SkillTags)
                    .Distinct(StringComparer.Ordinal)
                    .Where(tag => !SatisfiesSkillTagDependencyGroup(
                        combinedConstants.Concat(combinedDependencies), new[] { tag }))
                    .Select(tag => optionalByObjective.FirstOrDefault(id =>
                        SatisfiesSkillTagDependencyGroup(new[] { id }, new[] { tag })))
                    .Where(id => id > 0)
                    .Distinct()
                    .ToList();
                var combinedDependenciesSelectable = reachedSetSkillConstraints
                    .SelectMany(constraint => constraint.SkillIds)
                    .All(id => id == baseSkillId
                               || fixedGridActive.Contains(id)
                               || grantedActive.Contains(id)
                               || optionalSet.Contains(id));
                var combinedTagsSelectable = reachedSetSkillConstraints
                    .SelectMany(constraint => constraint.SkillTags)
                    .All(tag => SatisfiesSkillTagDependencyGroup(
                        combinedConstants.Concat(optional), new[] { tag }));
                var combinedSetPackage = CompleteOptionalPackage(
                    combinedDependencies.Concat(combinedTagRepresentatives));
                if (combinedDependenciesSelectable
                    && combinedTagsSelectable
                    && combinedSetPackage is not null
                    && reachedSetSkillConstraints.All(constraint =>
                        SatisfiesSetSkillConstraint(
                            combinedSetPackage.Concat(grantedActive).Append(baseSkillId),
                            constraint)))
                    rawCombinations = rawCombinations.Append(combinedSetPackage);
            }
            rawCombinations = rawCombinations.Where(selected =>
                SatisfiesFocusedThemeContract(baseSkillId, selected));
#if PATHOFIDLE_RUNTIME_TEST
            var materializedRawCombinations = rawCombinations.ToList();
            rawCombinations = materializedRawCombinations;
            if (materializedRawCombinations.Count == 0)
            {
                static string Ids(IEnumerable<int>? values)
                    => string.Join(',', values?.Where(id => id > 0).Distinct().OrderBy(id => id)
                                      ?? Enumerable.Empty<int>());
                RecordJointDetail(
                    $"packages-empty/base={baseSkillId};slotCount={slotCount};optionalCapacity={optionalCapacity};"
                    + $"requiredBase=[{Ids(planned.RequiredBaseSkillIds)}];"
                    + $"requiredActive=[{Ids(planned.RequiredActiveSkillIds)}];"
                    + $"themePackage=[{Ids(planned.ThemePackageSkillIds)}];"
                    + $"requiredThemeCount={planned.RequiredThemeSkillCount};"
                    + $"fixed=[{Ids(fixedGridActive)}];granted=[{Ids(grantedActive)}];"
                    + $"optional=[{Ids(optional)}];planned=[{Ids(planned.ActiveSkillIds)}]");
            }
            TraceJoint($"base-{baseSkillId}-prescore");
#endif
            var preScoredCombinations = new List<(List<int> Skills, double Score, string Key)>();
            foreach (var group in rawCombinations
                         .GroupBy(selected => string.Join(",", selected), StringComparer.Ordinal))
            {
                if (AutoBuildSearchDeadlineReached())
                {
                    if (resolvedBestLevelPlan is not null) break;
                    ThrowIfAutoBuildSearchDeadlineReached();
                }
                var selected = group.First();
                var packageActive = selected.Concat(grantedActive)
                    .Where(id => id > 0 && id != baseSkillId).Distinct().OrderBy(id => id).ToList();
                try
                {
                    // Interactive repair candidates were already compared by
                    // the global native skill scan. Reuse that neutral rank
                    // here; the retained winner still receives the complete
                    // gear-adjusted exact evaluation below.
                    var score = boundedInteractivePackageSearch
                        ? planned.ObjectiveBySkillId.GetValueOrDefault(baseSkillId)
                          + packageActive.Sum(id =>
                              planned.ObjectiveBySkillId.GetValueOrDefault(id))
                        : ScoreSharedSkillPackage(
                            SeedRoleFor(baseSkillId),
                            packageActive.Select(SeedRoleFor),
                            baseline.Focus);
                    preScoredCombinations.Add((selected, score, group.Key));
                }
                catch (InvalidOperationException)
                {
                    preScoredCombinations.Add((selected, double.NegativeInfinity, group.Key));
                }
            }
#if PATHOFIDLE_RUNTIME_TEST
            TraceJoint($"base-{baseSkillId}-prescore-done-{preScoredCombinations.Count}");
#endif
            var preRankedCombinations = preScoredCombinations
                .Where(entry => double.IsFinite(entry.Score))
                .OrderByDescending(entry => entry.Score)
                .ThenBy(entry => entry.Key, StringComparer.Ordinal)
                .ToList();
            bool EnablesSetConstraint(
                IReadOnlyCollection<int> selected,
                (int SetId, HashSet<int> SkillIds, HashSet<string> SkillTags) constraint)
                => SatisfiesSetSkillConstraint(
                    selected.Concat(grantedActive).Append(baseSkillId),
                    constraint);

            // Interactive comparison reserves one native lane for the incumbent
            // and one for every single-skill replacement around it. This is a
            // bounded coordinate screen: no skill name or ID is protected, and a
            // currently selected skill can stay only after its exclusion package
            // receives the same 30-second native calculation. Extra capacity
            // retains set/variant and broader structural alternatives.
            // The global planner already compared the complete job skill pool.
            // A gear finalist only needs packages whose result can change because
            // of this loadout: the incumbent, reached set/variant lanes, and a
            // small unbiased replacement sample. Re-running one native preview
            // for every incumbent skill made one finalist take over a minute.
            const int interactiveNativeScreenPackageLimit = 5;
            var nativeScreenPackageLimit = boundedInteractivePackageSearch
                ? interactiveNativeScreenPackageLimit
                : 5;
            var nativeScreenCandidates =
                new List<(List<int> Skills, double Score, string Key)>();
            void AddNativeScreenCandidate(
                (List<int> Skills, double Score, string Key) candidate)
            {
                if (candidate.Skills is null
                    || nativeScreenCandidates.Count >= nativeScreenPackageLimit
                    || nativeScreenCandidates.Any(entry => entry.Key == candidate.Key)) return;
                nativeScreenCandidates.Add(candidate);
            }

            // The overall objective leader is always represented. Reserve real
            // set/tag and gear-variant lanes next; these are structurally capable
            // alternatives, not bonuses or forced winners.
            if (preRankedCombinations.Count > 0)
                AddNativeScreenCandidate(preRankedCombinations[0]);
            if (boundedInteractivePackageSearch)
            {
                var incumbentOptionalIds = optional
                    .Where(planned.ActiveSkillIds.Contains)
                    .Take(optionalCapacity)
                    .ToHashSet();
                var incumbentCandidate = preScoredCombinations.FirstOrDefault(entry =>
                    entry.Skills.Where(id => !fixedGridActive.Contains(id)).ToHashSet()
                        .SetEquals(incumbentOptionalIds));
                AddNativeScreenCandidate(incumbentCandidate);
            }
            if (coverageScreen)
            {
                var allSetsCandidate = preRankedCombinations.FirstOrDefault(entry =>
                    reachedSetSkillConstraints.Count > 0
                    && reachedSetSkillConstraints.All(constraint =>
                        EnablesSetConstraint(entry.Skills, constraint)));
                if (allSetsCandidate.Skills is null)
                    allSetsCandidate = preScoredCombinations.FirstOrDefault(entry =>
                        reachedSetSkillConstraints.Count > 0
                        && reachedSetSkillConstraints.All(constraint =>
                            EnablesSetConstraint(entry.Skills, constraint)));
                AddNativeScreenCandidate(allSetsCandidate);
                foreach (var constraint in reachedSetSkillConstraints)
                {
                    var candidate = preRankedCombinations.FirstOrDefault(entry =>
                        EnablesSetConstraint(entry.Skills, constraint));
                    if (candidate.Skills is null)
                        candidate = preScoredCombinations.FirstOrDefault(entry =>
                            EnablesSetConstraint(entry.Skills, constraint));
                    AddNativeScreenCandidate(candidate);
                }
            }
            var nativeScreenVariantSkillIds = coverageScreen
                ? items.SelectMany(candidate => candidate.SelectableFacts.VariantIds)
                    .Where(id => id > 0).ToHashSet()
                : new HashSet<int>();
            if (nativeScreenVariantSkillIds.Count > 0)
            {
                var candidate = preRankedCombinations.FirstOrDefault(entry =>
                    entry.Skills.Append(baseSkillId).Any(nativeScreenVariantSkillIds.Contains));
                if (candidate.Skills is null)
                    candidate = preScoredCombinations.FirstOrDefault(entry =>
                        entry.Skills.Append(baseSkillId).Any(nativeScreenVariantSkillIds.Contains));
                AddNativeScreenCandidate(candidate);
            }
            if (boundedInteractivePackageSearch)
            {
                var incumbentOptionalIds = optional
                    .Where(planned.ActiveSkillIds.Contains)
                    .Take(optionalCapacity)
                    .ToHashSet();
                // Select the best one-skill neighborhood challenge by score;
                // ordering by the removed skill ID would privilege whichever
                // skill happened to receive the lowest table ID.
                var oneSkillChallenge = preScoredCombinations
                    .Select(entry =>
                    {
                        var candidateOptionalIds = entry.Skills
                            .Where(id => !fixedGridActive.Contains(id)).ToHashSet();
                        var removedCount = incumbentOptionalIds.Except(candidateOptionalIds).Count();
                        var addedCount = candidateOptionalIds.Except(incumbentOptionalIds).Count();
                        return (Entry: entry, RemovedCount: removedCount, AddedCount: addedCount);
                    })
                    .Where(candidate => candidate.RemovedCount == 1
                                        && candidate.AddedCount <= 1)
                    .OrderByDescending(candidate => candidate.Entry.Score)
                    .ThenBy(candidate => candidate.Entry.Key, StringComparer.Ordinal)
                    .Select(candidate => candidate.Entry)
                    .FirstOrDefault();
                AddNativeScreenCandidate(oneSkillChallenge);

                var mostDifferentCandidate = preRankedCombinations
                    .OrderByDescending(entry => entry.Skills.Count(id =>
                        !fixedGridActive.Contains(id) && !planned.ActiveSkillIds.Contains(id)))
                    .ThenByDescending(entry => entry.Score)
                    .ThenBy(entry => entry.Key, StringComparer.Ordinal)
                    .FirstOrDefault();
                AddNativeScreenCandidate(mostDifferentCandidate);
            }
            foreach (var leader in preRankedCombinations.Take(
                         boundedInteractivePackageSearch ? 1 : 2))
                AddNativeScreenCandidate(leader);
            if (!coverageScreen && nativeScreenCandidates.Count == 0)
            {
                // A gear/set always-on attribute can turn a raw unrankable
                // package into a valid native 30-second package. The single
                // coarse/fully-fixed package must reach that adjusted screen
                // even when its pre-score threw or returned -infinity.
                var forcedSinglePackage = preScoredCombinations.FirstOrDefault();
                AddNativeScreenCandidate(forcedSinglePackage);
            }
            var preFixedOnly = coverageScreen ? preScoredCombinations.FirstOrDefault(entry =>
                entry.Skills.Count == fixedGridActive.Count
                && entry.Skills.All(fixedGridActive.Contains)) : default;
            AddNativeScreenCandidate(preFixedOnly);
#if PATHOFIDLE_RUNTIME_TEST
            if (nativeScreenCandidates.Count == 0)
                RecordJointDetail(
                    $"native-candidates-empty/base={baseSkillId};raw={materializedRawCombinations.Count};"
                    + $"prescored={preScoredCombinations.Count};ranked={preRankedCombinations.Count}");
            TraceJoint($"base-{baseSkillId}-native-candidates-{nativeScreenCandidates.Count}:"
                       + string.Join("|", nativeScreenCandidates.Select(entry => entry.Key)));
#endif

            // The expensive native ability/AttrData screen is bounded to two
            // score leaders, the fixed-only lane, one gear-variant lane, and
            // one package that satisfies every dependency of a reached set
            // effect. These are comparison lanes, never forced selections.
            // Gear-granted active skills are present in every package, so they do
            // not need another representative. The cheap pre-score still ranks
            // the full polynomial candidate set before these native simulations.
            var screenedCombinations = new List<(List<int> Skills, double Score, string Key)>();
#if PATHOFIDLE_RUNTIME_TEST
            var nativeScreenIndex = 0;
#endif
            foreach (var entry in nativeScreenCandidates)
            {
#if PATHOFIDLE_RUNTIME_TEST
                TraceJoint($"base-{baseSkillId}-native-{++nativeScreenIndex}/{nativeScreenCandidates.Count}");
#endif
                if ((resolvedBestLevelPlan is not null
                     || screenedCombinations.Any(candidate => double.IsFinite(candidate.Score)))
                    && AutoBuildSearchDeadlineReached()) break;
                ThrowIfAutoBuildSearchDeadlineReached();
                var selected = entry.Skills;
                var packageActive = selected.Concat(grantedActive)
                    .Where(id => id > 0 && id != baseSkillId).Distinct().OrderBy(id => id).ToList();
                var selectedIds = packageActive.Append(baseSkillId).ToHashSet();
                var cheapTalentIds = MainThreadNativeGateway.Invoke(() =>
                    ResolveTalentIds(baseSkillId, selected));
                var cheapPlan = planned with
                {
                    BaseSkillId = baseSkillId,
                    ActiveSkillIds = selected.ToHashSet(),
                    TalentIds = cheapTalentIds.ToHashSet(),
                    MasteryTalentIds = new HashSet<int>()
                };
                // The native screen is a fair structural comparison before the
                // exact point allocator. Give every selected talent the same
                // representative investment derived from the hero's actual
                // point budget, capped by that talent's native limit. Comparing
                // everything at Lv1 incorrectly rejects skills whose heal,
                // shield, summon, or status output unlocks at a later rank.
                var screeningPlan = MainThreadNativeGateway.Invoke(() =>
                {
                    var allocationNodeCount = Math.Max(
                        1,
                        planned.TargetSavedLevels.Count > 0
                            ? planned.TargetSavedLevels.Count
                            : cheapTalentIds.Count);
                    var representativeSavedLevel = Math.Max(
                        1,
                        checked(planned.TotalTalentPointBudget + 1)
                        / allocationNodeCount);
                    var targets = new Dictionary<int, int>();
                    var screeningBaseLevel = 1;
                    foreach (var talentId in cheapTalentIds)
                    {
                        var savedLevel = representativeSavedLevel;
                        var baseLevel = 0;
                        if (planningGridById.TryGetValue(talentId, out var talent))
                        {
                            var cap = Math.Max(0, GetTalentLevelCap(talent));
                            baseLevel = Math.Min(
                                Math.Max(0, GetTalentBaseLevelRequired(talent)),
                                cap);
                            savedLevel = Math.Min(
                                Math.Max(0, cap - baseLevel),
                                representativeSavedLevel);
                        }
                        targets[talentId] = savedLevel;
                        var definition = planningGridById.TryGetValue(talentId, out var runtimeTalent)
                            ? Read(runtimeTalent, "tTalentData")
                            : InvokeStatic("TableData", "getTTalentData", talentId);
                        if ((ReadNullableInt(definition, "skillId") ?? 0) == baseSkillId)
                            screeningBaseLevel = Math.Max(1, baseLevel + savedLevel);
                    }
                    return cheapPlan with
                    {
                        BaseSkillLevel = screeningBaseLevel,
                        TargetSavedLevels = targets
                    };
                });
                var cheapProfile = MainThreadNativeGateway.Invoke(() =>
                    WithCandidateJointTargets(
                        selectedIds, cheapTalentIds, Array.Empty<int>(), screeningPlan));
                try
                {
                    // Screen with the same native gear/set/Unique ability layer
                    // used by finalist evaluation. Keep each complete package in
                    // one short Unity job so hundreds of property reads do not
                    // each wait for a separate rendered frame.
                    var nativeScreenScore = MainThreadNativeGateway.Invoke(() =>
                    {
                        var gearAbilities = EvaluateNativeAbilityPackage(
                            items, hero, cheapProfile, simulatedAttr);
                        if (!gearAbilities.IsComplete)
                            throw new InvalidOperationException("Native ability screening was incomplete.");
                        var abilityAdjustedAttr = CreateAbilityAdjustedAttr(simulatedAttr, gearAbilities);
                        var screeningLevels = packageActive.Append(baseSkillId)
                            .Where(id => id > 0).Distinct()
                            .Select(id => (
                                SkillId: id,
                                Level: GetPlannedSkillEffectiveLevel(
                                    hero, screeningPlan, id, items)))
                            .ToList();
                        var screeningAttr = CreateStrictSkillPackageAdjustedAttr(
                            hero, screeningLevels, abilityAdjustedAttr, false, items, out _,
                            previewCache: new Dictionary<(int SkillId, int Level), NativeSkillAlwaysOnPreview>());
                        var screeningBase = screeningLevels.First(entry => entry.SkillId == baseSkillId);
                        var screeningRoles = screeningLevels
                            .Where(entry => entry.SkillId != baseSkillId)
                            .Select(entry => RoleFor(entry.SkillId, entry.Level, screeningAttr, false))
                            .ToList();
                        var screeningBaseRole = RoleFor(
                            baseSkillId, screeningBase.Level, screeningAttr, false);
                        var screeningPackage = BuildSharedSkillPackage(
                            screeningBaseRole,
                            screeningRoles,
                            out var screeningSchedule);
                        if (!IsNativePackageRankable(screeningPackage, baseline.Focus))
                            throw new InvalidOperationException("Native 30-second screening package was not rankable.");
                        if (!SatisfiesNativeThemeOutputContract(
                                baseline.Focus,
                                screeningBaseRole,
                                screeningRoles,
                                screeningPackage,
                                out var screeningThemeFailure))
                            throw new InvalidOperationException(
                                $"Native theme output screening failed: {screeningThemeFailure}");
                        var defenseWindow = EvaluateDefenseWindow(
                            screeningAttr,
                            gearAbilities,
                            screeningSchedule,
                            cheapProfile,
                            incomingPressure,
                            screeningPackage.SelfHeal,
                            screeningPackage.SelfShield);
                        var expectedConditional = defenseWindow.Conditional;
                        var nativeRoleScore = ScoreNativeSkillRoleObjectiveWithConditional(
                            screeningPackage, expectedConditional, baseline.Focus);
                        if (baseline.Focus.Key == "defense")
                            return defenseWindow.Simulation.ObjectiveScore
                                   + nativeRoleScore * 0.05d
                                   + (gearAbilities.StructuralScore
                                      + expectedConditional.StructuralScore) / 1000d;
                        var conditionalScreeningAttr = defenseWindow.EffectiveAttr;
                        return nativeRoleScore
                               + ScoreHeroAttrObjective(
                                   conditionalScreeningAttr, baseline.Focus,
                                   screeningPackage.ControlledEntityKinds)
                               - ScoreHeroAttrObjective(
                                   simulatedAttr, baseline.Focus,
                                   screeningPackage.ControlledEntityKinds)
                               + (gearAbilities.StructuralScore
                                  + expectedConditional.StructuralScore) / 1000d;
                    });
                    screenedCombinations.Add((selected, nativeScreenScore, entry.Key));
#if PATHOFIDLE_RUNTIME_TEST
                    TraceJoint($"base-{baseSkillId}-native-result-{entry.Key}:{nativeScreenScore:0.######}");
#endif
                }
                catch (InvalidOperationException error)
                {
                    _ = error;
                    screenedCombinations.Add((selected, double.NegativeInfinity, entry.Key));
#if PATHOFIDLE_RUNTIME_TEST
                    RecordJointRejection($"screen/{baseSkillId}/{entry.Key}", error);
                    TraceJoint($"base-{baseSkillId}-native-result-{entry.Key}:rejected:{error.GetBaseException().Message}");
#endif
                }
                if (screenedCombinations.Any(candidate => double.IsFinite(candidate.Score))
                    && AutoBuildSearchDeadlineReached()) break;
            }
            var rankedCombinations = screenedCombinations
                .Where(entry => double.IsFinite(entry.Score))
                .OrderByDescending(entry => entry.Score)
                .ThenBy(entry => entry.Key, StringComparer.Ordinal)
                .ToList();
#if PATHOFIDLE_RUNTIME_TEST
            if (rankedCombinations.Count > 0)
                TraceJoint($"base-{baseSkillId}-native-winner-{rankedCombinations[0].Key}:{rankedCombinations[0].Score:0.######}");
#endif
            // Only the much more expensive mastery rebuild and exact-budget
            // refinement are capped: two score leaders, fixed-only, one
            // gear-variant package, and one reached-set dependency package.
            // Gear-granted actives are already present in every package.
            const int exactPackageLimit = 5;
            var scoreLeaderLimit = boundedInteractivePackageSearch
                ? 1
                : boundedJointRepair ? 1 : coverageScreen ? 2 : 1;
            var retainedCombinations = rankedCombinations.Take(scoreLeaderLimit).ToList();
            var preserveExactStructuralLanes = coverageScreen && !boundedInteractivePackageSearch;
            var fixedOnly = preserveExactStructuralLanes ? rankedCombinations.FirstOrDefault(entry =>
                entry.Skills.Count == fixedGridActive.Count
                && entry.Skills.All(fixedGridActive.Contains)) : default;
            if (fixedOnly.Skills is not null
                && retainedCombinations.All(entry => entry.Key != fixedOnly.Key))
                retainedCombinations.Add(fixedOnly);
            var variantSkillIds = preserveExactStructuralLanes
                ? items.SelectMany(candidate => candidate.SelectableFacts.VariantIds)
                    .Where(id => id > 0).ToHashSet()
                : new HashSet<int>();
            var gearEnabled = preserveExactStructuralLanes && variantSkillIds.Count > 0
                ? rankedCombinations.FirstOrDefault(entry =>
                    entry.Skills.Append(baseSkillId).Any(variantSkillIds.Contains))
                : default;
            if (gearEnabled.Skills is not null
                && retainedCombinations.All(entry => entry.Key != gearEnabled.Key))
                retainedCombinations.Add(gearEnabled);
            if (preserveExactStructuralLanes)
            {
                foreach (var constraint in reachedSetSkillConstraints)
                {
                    var setEnabled = rankedCombinations.FirstOrDefault(entry =>
                        EnablesSetConstraint(entry.Skills, constraint));
                    if (setEnabled.Skills is not null
                        && retainedCombinations.All(entry => entry.Key != setEnabled.Key))
                        retainedCombinations.Add(setEnabled);
                }
            }
            retainedCombinations = retainedCombinations.Take(exactPackageLimit).ToList();
#if PATHOFIDLE_RUNTIME_TEST
            var exactPackageIndex = 0;
#endif
            foreach (var ordinarySelected in retainedCombinations.Select(entry => entry.Skills))
            {
#if PATHOFIDLE_RUNTIME_TEST
                TraceJoint($"base-{baseSkillId}-exact-{++exactPackageIndex}/{retainedCombinations.Count}-start");
#endif
                if (resolvedBestLevelPlan is not null && AutoBuildSearchDeadlineReached()) break;
                ThrowIfAutoBuildSearchDeadlineReached();
                try
                {
                    var selectedTalentIds = MainThreadNativeGateway.Invoke(() =>
                        ResolveTalentIds(baseSkillId, ordinarySelected));
                    var packageActive = ordinarySelected.Concat(grantedActive)
                        .Where(id => id > 0 && id != baseSkillId).Distinct().OrderBy(id => id).ToList();
                    var selectedIds = packageActive.Append(baseSkillId).ToHashSet();
                    var candidateTalentPlan = new PreferredTalentPlan(
                        null,
                        selectedTalentIds,
                        rebuildMasteries
                            ? new List<int>()
                            : planned.MasteryTalentIds.OrderBy(id => id).ToList(),
                        selectedIds,
                        "joint gear/skill objective",
                        RequiredActiveSkillIds: planned.RequiredActiveSkillIds?.ToHashSet(),
                        RequiredBaseSkillIds: planned.RequiredBaseSkillIds?.ToHashSet(),
                        ThemePackageSkillIds: planned.ThemePackageSkillIds?.ToHashSet(),
                        RequiredThemeSkillCount: planned.RequiredThemeSkillCount);
                    TalentLevelPlan levelPlan;
                    var reusesCompletedPlan = !rebuildMasteries
                                              && !fullyOptimizeTalentLevels
                                              && baseSkillId == planned.BaseSkillId
                                              && ordinarySelected.ToHashSet()
                                                  .SetEquals(planned.ActiveSkillIds);
                    if (reusesCompletedPlan)
                    {
                        // The global planner already produced and native-scored
                        // this exact-budget vector. Repeating the same allocation
                        // for every loadout was the main interactive bottleneck.
                        candidateTalentPlan = candidateTalentPlan with
                        {
                            MasteryTalentIds = planned.MasteryTalentIds
                                .OrderBy(id => id).ToList(),
                            TargetSavedLevels =
                                new Dictionary<int, int>(planned.TargetSavedLevels),
                            PlanToken = planned.PlanToken
                        };
                        levelPlan = new TalentLevelPlan(
                            new Dictionary<int, int>(planned.TargetSavedLevels),
                            selectedIds.ToDictionary(
                                id => id,
                                id => GetPlannedSkillEffectiveLevel(
                                    hero, planned, id, items)),
                            planned.PlanToken);
                    }
                    else
                    {
                        // Rebuild from the complete legal mastery pool only when
                        // the skill package actually changed. A zero-point
                        // mastery may then re-enter for the new package.
                        // Interactive loadout comparison must stay inside the
                        // configured search budget. Rebuilding every mastery row
                        // for current gear plus each challenger multiplies the
                        // full native package count. The dedicated refinement
                        // pass rebuilds masteries; bounded comparison projects
                        // the already native-ranked pool onto the alternate
                        // active package.
                        var plannedLevels = MainThreadNativeGateway.Invoke(() =>
                        {
                            var resolvedCandidatePlan = candidateTalentPlan;
                            if (rebuildMasteries)
                                resolvedCandidatePlan = RebuildMasteryPlanForSelectedSkills(
                                    hero,
                                    baseline.Focus,
                                    planned.TotalTalentPointBudget,
                                    resolvedCandidatePlan with { MasteryTalentIds = new List<int>() },
                                    simulatedAttr,
                                    items);
                            var resolvedLevelPlan = BuildDeterministicTalentLevelPlan(
                                hero,
                                baseline.Focus,
                                selectedTalentIds,
                                resolvedCandidatePlan.MasteryTalentIds,
                                planned.TotalTalentPointBudget,
                                simulatedAttr,
                                items,
                                fullyOptimizeTalentLevels ? 2 : 1,
                                preferredSavedLevels: fullyOptimizeTalentLevels
                                    ? planned.TargetSavedLevels
                                    : null,
                                fastDeterministicCompletion: !fullyOptimizeTalentLevels,
                                scoreFastCompletion: false);
                            return (CandidatePlan: resolvedCandidatePlan, LevelPlan: resolvedLevelPlan);
                        });
                        candidateTalentPlan = plannedLevels.CandidatePlan;
                        levelPlan = plannedLevels.LevelPlan;
                    }
#if PATHOFIDLE_RUNTIME_TEST
                    TraceJoint($"base-{baseSkillId}-exact-{exactPackageIndex}-levels");
#endif
                    if (boundedJointRepair)
                    {
                        // The interactive repair retains one ranked package.
                        // Its complete gear-adjusted 30-second simulation is the
                        // final performance pass in EvaluateCompleteLoadout.
                        // Rebuilding the same graph here doubled the cost without
                        // adding another comparison.
                        // The candidate's native objects and every gear-granted
                        // skill lookup belong to the same immutable comparison.
                        // Keep this tiny finalization in one main-thread work
                        // item; individual GetGrantedSkillLevel calls otherwise
                        // consume tens of rendered frames after the expensive
                        // comparison has already completed.
                        MainThreadNativeGateway.Invoke(() =>
                        {
                            var selectionScore = retainedCombinations
                                .First(entry => ReferenceEquals(entry.Skills, ordinarySelected)
                                                || entry.Key == string.Join(",", ordinarySelected))
                                .Score;
                            if (selectionScore <= bestScore) return;
                            bestScore = selectionScore;
                            bestNativeRoleScore = 0d;
                            bestBase = baseSkillId;
                            bestActive = ordinarySelected.ToList();
                            bestRedundantGrantedActiveCount = ordinarySelected.Count(id =>
                                GetGrantedSkillLevel(items, id) > 0
                                && levelPlan.EffectiveSkillLevels.GetValueOrDefault(id)
                                <= GetGrantedSkillLevel(items, id));
                            bestMasteryCandidateIds = candidateTalentPlan.MasteryTalentIds
                                .Distinct().OrderBy(id => id).ToList();
                            resolvedBestLevelPlan = levelPlan;
                        });
#if PATHOFIDLE_RUNTIME_TEST
                        TraceJoint($"base-{baseSkillId}-exact-{exactPackageIndex}-done");
#endif
                        continue;
                    }
                    // This exact package is a single immutable native snapshot.
                    // Running each reflection-heavy substep as a separate worker
                    // gateway request added 20-30 seconds of frame scheduling for
                    // Ice even though the native computation was small.
                    MainThreadNativeGateway.Invoke(() =>
                    {
                    var candidateAttr = InvokeRequiredStaticMany("AttrData", "copyCreate", simulatedAttr)
                                        ?? throw new InvalidOperationException("Joint candidate AttrData copy failed.");
                    var candidatePlanned = planned with
                    {
                        BaseSkillId = baseSkillId,
                        ActiveSkillIds = ordinarySelected.ToHashSet(),
                        TalentIds = selectedTalentIds.ToHashSet(),
                        MasteryTalentIds = candidateTalentPlan.MasteryTalentIds
                            .Where(id => levelPlan.SavedLevels.GetValueOrDefault(id) > 0).ToHashSet(),
                        TargetSavedLevels = new Dictionary<int, int>(levelPlan.SavedLevels),
                        PlanToken = levelPlan.Token
                    };
                    var candidateProfile = WithCandidateJointTargets(
                        selectedIds,
                        selectedTalentIds,
                        candidatePlanned.MasteryTalentIds,
                        candidatePlanned);
                    ApplyPlannedMasteryLevelPreview(candidateAttr, planningGridTalents, candidatePlanned);
                    var baseLevel = levelPlan.EffectiveSkillLevels.GetValueOrDefault(
                        baseSkillId, Math.Max(1, GetGrantedSkillLevel(items, baseSkillId)));
                    var packageLevels = packageActive
                        .Select(id => (SkillId: id, Level: levelPlan.EffectiveSkillLevels.GetValueOrDefault(
                            id, Math.Max(1, GetGrantedSkillLevel(items, id)))))
                        .Append((SkillId: baseSkillId, Level: baseLevel))
                        .ToList();
                    var candidateStrictAbilityPreviewCache =
                        new Dictionary<(int SkillId, int Level), NativeSkillAlwaysOnPreview>();
                    var packageAttr = CreateStrictSkillPackageAdjustedAttr(
                        hero, packageLevels, candidateAttr, false, items, out _,
                        previewCache: candidateStrictAbilityPreviewCache);
                    var activeRoles = packageLevels.Where(entry => entry.SkillId != baseSkillId)
                        .Select(entry => RoleFor(entry.SkillId, entry.Level, packageAttr, false)).ToList();
                    var packageBaseRole = RoleFor(
                        baseSkillId, baseLevel, packageAttr, false);
                    var package = BuildSharedSkillPackage(
                        packageBaseRole, activeRoles,
                        out var packageSchedule);
                    if (!IsNativePackageRankable(package, baseline.Focus))
                        throw new InvalidOperationException($"The joint level-plan has no rankable native output: {package.Failure}");
                    if (!SatisfiesNativeThemeOutputContract(
                            baseline.Focus,
                            packageBaseRole,
                            activeRoles,
                            package,
                            out var packageThemeFailure))
                        throw new InvalidOperationException(
                            $"The joint level-plan violates the native theme output contract: {packageThemeFailure}");
                    var gearAbilities = EvaluateNativeAbilityPackage(
                        items, hero, candidateProfile, packageAttr);
                    if (!gearAbilities.IsComplete)
                        throw new InvalidOperationException("The exact conditional ability package was incomplete.");
                    var defenseWindow = EvaluateDefenseWindow(
                        packageAttr,
                        gearAbilities,
                        packageSchedule,
                        candidateProfile,
                        incomingPressure,
                        package.SelfHeal,
                        package.SelfShield);
                    var expectedConditional = defenseWindow.Conditional;
                    var nativeRoleScore = ScoreNativeSkillRoleObjectiveWithConditional(
                        package, expectedConditional, baseline.Focus);
                    var conditionalPackageAttr = defenseWindow.EffectiveAttr;
                    var strictAbilityAttrDelta = baseline.Focus.Key == "defense"
                        ? 0d
                        : ScoreHeroAttrObjective(
                              conditionalPackageAttr, baseline.Focus,
                              package.ControlledEntityKinds)
                          - ScoreHeroAttrObjective(
                              simulatedAttr, baseline.Focus,
                              package.ControlledEntityKinds);
                    var packageScore = baseline.Focus.Key == "defense"
                        ? defenseWindow.Simulation.ObjectiveScore
                          + nativeRoleScore * 0.05d
                          + (gearAbilities.StructuralScore
                             + expectedConditional.StructuralScore) / 1000d
                        : nativeRoleScore
                          + strictAbilityAttrDelta
                          + (gearAbilities.StructuralScore
                             + expectedConditional.StructuralScore) / 1000d;
                    var packageTie = planned.ObjectiveBySkillId.GetValueOrDefault(baseSkillId)
                                     + ordinarySelected.Sum(id => planned.ObjectiveBySkillId.GetValueOrDefault(id));
                    var bestTie = planned.ObjectiveBySkillId.GetValueOrDefault(bestBase)
                                  + bestActive.Sum(id => planned.ObjectiveBySkillId.GetValueOrDefault(id));
                    var redundantGrantedActiveCount = ordinarySelected.Count(id =>
                        GetGrantedSkillLevel(items, id) > 0
                        && levelPlan.EffectiveSkillLevels.GetValueOrDefault(id)
                        <= GetGrantedSkillLevel(items, id));
                    if (packageScore > bestScore
                        || (Math.Abs(packageScore - bestScore) < 0.000001d
                            && (redundantGrantedActiveCount < bestRedundantGrantedActiveCount
                                || (redundantGrantedActiveCount == bestRedundantGrantedActiveCount
                                    && packageTie > bestTie))))
                    {
                        bestScore = packageScore;
                        bestNativeRoleScore = baseline.Focus.Key == "defense"
                            ? packageScore
                            : nativeRoleScore + strictAbilityAttrDelta;
                        bestBase = baseSkillId;
                        bestActive = ordinarySelected.ToList();
                        bestRedundantGrantedActiveCount = redundantGrantedActiveCount;
                        bestMasteryCandidateIds = candidateTalentPlan.MasteryTalentIds
                            .Distinct().OrderBy(id => id).ToList();
                        resolvedBestLevelPlan = levelPlan;
                    }
                    });
#if PATHOFIDLE_RUNTIME_TEST
                    TraceJoint($"base-{baseSkillId}-exact-{exactPackageIndex}-done");
#endif
                }
                catch (InvalidOperationException error)
                {
                    _ = error;
                    // A rejected skill/level vector invalidates only this native
                    // package. Other skill packages for the same equipment set
                    // must still be compared before the loadout itself is rejected.
#if PATHOFIDLE_RUNTIME_TEST
                    RecordJointRejection($"exact/{baseSkillId}/{exactPackageIndex}", error);
#endif
                }
                if (resolvedBestLevelPlan is not null && AutoBuildSearchDeadlineReached()) break;
            }
            if (resolvedBestLevelPlan is not null && AutoBuildSearchDeadlineReached()) break;
        }

        if (resolvedBestLevelPlan is null)
            throw new InvalidOperationException(
                "No complete joint skill level plan could be evaluated."
#if PATHOFIDLE_RUNTIME_TEST
                + (runtimeJointRejections.Count == 0
                    ? " No native package reached a rejection-reporting stage."
                    : $" Rejections=[{string.Join(" | ", runtimeJointRejections)}]")
#endif
            );
#if PATHOFIDLE_RUNTIME_TEST
        TraceJoint("winner-plan");
#endif
        // Winner materialization is one coherent native snapshot. Batching it
        // removes gateway/frame latency while preserving the same exact level
        // vector, mastery effects, strict skill package, and returned profile.
        return MainThreadNativeGateway.Invoke(() =>
        {
            var resolvedTalentIds = ResolveTalentIds(bestBase, bestActive);
            var resolvedBaseTalentId = allJobSkillRows
                .Where(IsBaseSkillDefinition)
                .Where(row => (ReadNullableInt(row, "skillId") ?? 0) == bestBase)
                .Select(row => ReadNullableInt(row, "id") ?? 0)
                .FirstOrDefault(id => id > 0);
            var selectedMasteryTalentIds = bestMasteryCandidateIds
                .Where(id => resolvedBestLevelPlan.SavedLevels.GetValueOrDefault(id) > 0)
                .ToHashSet();
            var resolvedPlanned = planned with
            {
                BaseTalentId = resolvedBaseTalentId > 0 ? resolvedBaseTalentId : planned.BaseTalentId,
                BaseSkillId = bestBase,
                ActiveSkillIds = bestActive.ToHashSet(),
                TalentIds = resolvedTalentIds.ToHashSet(),
                MasteryTalentIds = selectedMasteryTalentIds,
                TargetSavedLevels = new Dictionary<int, int>(resolvedBestLevelPlan.SavedLevels),
                PlanToken = resolvedBestLevelPlan.Token,
                BaseSkillLevel = resolvedBestLevelPlan.EffectiveSkillLevels.GetValueOrDefault(bestBase, 1)
            };
            // The simulated attribute copy starts mastery-neutral whenever this
            // resolver is used. Materialize the exact winning mastery vector once
            // for every caller so the returned profile, final ability layer, and
            // performance score all describe the same state.
            ApplyPlannedMasteryLevelPreview(simulatedAttr, planningGridTalents, resolvedPlanned);
#if PATHOFIDLE_RUNTIME_TEST
            TraceJoint("winner-mastery");
#endif
            if (rebuildMasteries)
            {
            // Every skill combination above was already evaluated with its own
            // mastery candidate set and exact point vector. Apply the winning
            // vector to the finalist AttrData, then repeat the strict package
            // preview once so all later gear/ability scoring sees that same plan.
            roleCache.Clear();
            strictAbilityPreviewCache.Clear();
            var exactLevels = bestActive.Concat(grantedActive)
                .Where(id => id > 0 && id != bestBase).Distinct().Select(id => (
                    SkillId: id,
                    Level: resolvedBestLevelPlan.EffectiveSkillLevels.GetValueOrDefault(
                        id, Math.Max(1, GetGrantedSkillLevel(items, id)))))
                .Append((SkillId: bestBase, Level: resolvedPlanned.BaseSkillLevel))
                .ToList();
            var exactPackageAttr = CreateStrictSkillPackageAdjustedAttr(
                hero, exactLevels, simulatedAttr, false, items, out _,
                previewCache: strictAbilityPreviewCache);
            var exactBaseRole = RoleFor(
                bestBase, resolvedPlanned.BaseSkillLevel, exactPackageAttr, false);
            var exactActiveRoles = exactLevels.Where(entry => entry.SkillId != bestBase)
                .Select(entry => RoleFor(entry.SkillId, entry.Level, exactPackageAttr, false)).ToList();
            var exactPackage = BuildSharedSkillPackage(exactBaseRole, exactActiveRoles);
            if (!IsNativePackageRankable(exactPackage, baseline.Focus))
                throw new InvalidOperationException($"The rebuilt joint level-plan has no rankable native output: {exactPackage.Failure}");
            if (!SatisfiesNativeThemeOutputContract(
                    baseline.Focus,
                    exactBaseRole,
                    exactActiveRoles,
                    exactPackage,
                    out var exactThemeFailure))
                throw new InvalidOperationException(
                    $"The rebuilt joint level-plan violates the native theme output contract: {exactThemeFailure}");
            if (baseline.Focus.Key != "defense")
                bestNativeRoleScore = ScoreNativeSkillRoleObjective(exactPackage, baseline.Focus)
                                      + ScoreHeroAttrObjective(
                                          exactPackageAttr, baseline.Focus,
                                          exactPackage.ControlledEntityKinds)
                                      - ScoreHeroAttrObjective(
                                          simulatedAttr, baseline.Focus,
                                          exactPackage.ControlledEntityKinds);
            }

            var packageBestActive = bestActive.Concat(grantedActive)
                .Where(id => id > 0 && id != bestBase).Distinct().OrderBy(id => id).ToList();
            var reason = DescribeJointSkillSelection(bestBase, packageBestActive, items);
#if PATHOFIDLE_RUNTIME_TEST
            TraceJoint("return");
#endif
            return BuildProfileForSkillSelection(
                hero,
                baseline.Focus,
                resolvedPlanned,
                bestBase,
                packageBestActive,
                resolvedPlanned.BaseSkillLevel,
                simulatedAttr,
                items,
                reason)
                with { JointSkillObjective = Math.Max(0d, bestNativeRoleScore) };
        });
    }

    private static long GetCombinationCount(int count, int choose)
    {
        if (choose < 0 || choose > count) return 0;
        choose = Math.Min(choose, count - choose);
        long value = 1;
        for (var index = 1; index <= choose; index++)
        {
            if (value > 20000) return 20001;
            value = value * (count - choose + index) / index;
        }
        return value;
    }

    private static IEnumerable<List<int>> EnumerateSkillCombinations(IReadOnlyList<int> values, int choose)
    {
        var buffer = new List<int>(choose);
        return Walk(0, choose);

        IEnumerable<List<int>> Walk(int start, int remaining)
        {
            if (remaining == 0)
            {
                yield return buffer.ToList();
                yield break;
            }
            for (var index = start; index <= values.Count - remaining; index++)
            {
                buffer.Add(values[index]);
                foreach (var result in Walk(index + 1, remaining - 1)) yield return result;
                buffer.RemoveAt(buffer.Count - 1);
            }
        }
    }

    private static IEnumerable<List<int>> EnumerateGreedySkillPackages(
        IReadOnlyCollection<int> values,
        int choose,
        int baseSkillId,
        Func<int, NativeSkillRoleProfile> roleFor,
        HeroFocus focus)
    {
        if (choose == 0)
        {
            yield return new List<int>();
            yield break;
        }

        // When exhaustive enumeration is too large, keep both the unconstrained
        // greedy result and one greedily completed package forced through every
        // available skill. This bounds the search while preventing a skill with a
        // weak one-step score (but a strong level/set milestone) from disappearing
        // before the exact joint planner can evaluate it.
        var orderedValues = values.Where(id => id > 0).Distinct().OrderBy(id => id).ToList();
        foreach (var seedSkillId in new[] { 0 }.Concat(orderedValues))
        {
            var selected = seedSkillId > 0
                ? new List<int> { seedSkillId }
                : new List<int>();
            while (selected.Count < choose)
            {
                var next = orderedValues.Where(id => !selected.Contains(id))
                    .Select(id =>
                    {
                        try
                        {
                            var score = ScoreSharedSkillPackage(
                                roleFor(baseSkillId), selected.Append(id).Select(roleFor), focus);
                            return (Id: id, Score: score, IsValid: double.IsFinite(score));
                        }
                        catch (InvalidOperationException error)
                        {
                            // One optional skill with no provable native output
                            // must not invalidate every equipment loadout while
                            // the bounded greedy package list is being ordered.
                            // Fixed and equipment-granted skills are handled by
                            // the caller's mandatory-skill policy.
                            Plugin.DiagDebug(
                                $"AUTO-SKILLS GREEDY OPTIONAL SKIPPED|skill={id}|{error.GetBaseException().Message}");
                            return (Id: id, Score: double.NegativeInfinity, IsValid: false);
                        }
                    })
                    .Where(entry => entry.IsValid)
                    .OrderByDescending(entry => entry.Score)
                    .ThenBy(entry => entry.Id)
                    .Select(entry => entry.Id)
                    .FirstOrDefault();
                if (next <= 0) break;
                selected.Add(next);
            }
            if (selected.Count == choose)
                yield return selected.OrderBy(id => id).ToList();
        }
    }

    private static double ScoreNativeConditionalPackage(
        IEnumerable<GearCandidate> items,
        HeroEffectProfile profile)
    {
        var candidates = items.ToList();
        var score = EstimatePartialSetSynergy(
            candidates, profile, EffectRelevanceScope.SelectedJointPlan);
        foreach (var candidate in candidates)
        foreach (var rawAffix in CollectEquipmentAffixes(candidate.Record.ItemData)
                     .Concat(CollectGrantedMasteryAffixes(candidate.Record.ItemData)))
        {
            var affix = ResolveRuntimeAffix(rawAffix);
            var effectType = ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0;
            if (effectType != 3) continue;
            score += ScoreAffixBehavior(
                affix,
                candidate.DefinitionId,
                profile,
                string.Empty,
                EffectRelevanceScope.SelectedJointPlan);
        }
        return score;
    }

    private static double ScoreSharedSkillPackage(
        NativeSkillRoleProfile baseRole,
        IEnumerable<NativeSkillRoleProfile> activeRoles,
        HeroFocus focus)
    {
        var active = activeRoles.ToList();
        var package = BuildSharedSkillPackage(baseRole, active);
        if (!IsNativePackageRankable(package, focus)
            || !SatisfiesNativeThemeOutputContract(
                focus, baseRole, active, package, out _))
            return double.NegativeInfinity;
        return ScoreNativeSkillRoleObjective(package, focus);
    }

    private static NativeSkillRoleProfile BuildSharedSkillPackage(
        NativeSkillRoleProfile baseRole,
        IEnumerable<NativeSkillRoleProfile> activeRoles)
        => BuildSharedSkillPackage(baseRole, activeRoles, out _);

    private static NativeSkillRoleProfile BuildSharedSkillPackage(
        NativeSkillRoleProfile baseRole,
        IEnumerable<NativeSkillRoleProfile> activeRoles,
        out NativeSkillPackageSchedule schedule)
    {
        const double windowSeconds = PerformancePreviewWindowSeconds;
        var active = activeRoles.ToList();
        var demand = active.Sum(role => Math.Max(0d, role.CastOpportunities) * Math.Max(0.01d, role.ActionSecondsPerCast));
        var hpBudget = new[] { baseRole }.Concat(active)
            .Select(role => role.HpBudgetWindow).Where(double.IsFinite).DefaultIfEmpty(double.MaxValue).Min();
        var mpBudget = new[] { baseRole }.Concat(active)
            .Select(role => role.MpBudgetWindow).Where(double.IsFinite).DefaultIfEmpty(double.MaxValue).Min();
        var requestedActiveHp = active.Sum(role => Math.Max(0d, role.CastOpportunities) * role.HpCostPerCast);
        var requestedActiveMp = active.Sum(role => Math.Max(0d, role.CastOpportunities) * role.MpCostPerCast);
        static double BudgetScale(double budget, double requested)
            => requested <= 0.000001d ? 1d : Math.Clamp(budget / requested, 0d, 1d);
        var activeScale = Math.Min(
            demand > windowSeconds ? windowSeconds / demand : 1d,
            Math.Min(BudgetScale(hpBudget, requestedActiveHp), BudgetScale(mpBudget, requestedActiveMp)));
        var remaining = Math.Max(0d, windowSeconds - demand * activeScale);
        var remainingHp = Math.Max(0d, hpBudget - requestedActiveHp * activeScale);
        var remainingMp = Math.Max(0d, mpBudget - requestedActiveMp * activeScale);
        var baseTimeScale = remaining / windowSeconds;
        var requestedBaseHp = Math.Max(0d, baseRole.CastOpportunities) * baseRole.HpCostPerCast * baseTimeScale;
        var requestedBaseMp = Math.Max(0d, baseRole.CastOpportunities) * baseRole.MpCostPerCast * baseTimeScale;
        var baseScale = baseTimeScale * Math.Min(
            BudgetScale(remainingHp, requestedBaseHp), BudgetScale(remainingMp, requestedBaseMp));
        var damage = new Dictionary<int, double>();
        var heal = 0d;
        var shield = 0d;
        var selfHeal = 0d;
        var selfShield = 0d;
        var summon = false;
        var controlledEntityKinds = NativeControlledEntityKind.None;
        var summonDamage = 0d;
        var summonSurvival = 0d;
        var summonAttackByType = new Dictionary<int, double>();
        var controlledEntityDamage = 0d;
        var controlledEntityUtility = 0d;
        var controlledEntitySurvival = 0d;
        var controlledEntityCount = 0d;
        var hostileStatusApplications = new Dictionary<int, double>();
        var abilitySupport = 0d;
        var abilityDefense = 0d;
        var abilityMinion = 0d;
        var scheduledSkills = new Dictionary<int, NativeScheduledSkill>();
        var complete = baseRole.IsComplete && active.All(role => role.IsComplete);
        var failures = new[] { baseRole }.Concat(active)
            .Where(role => !role.IsComplete && !string.IsNullOrWhiteSpace(role.Failure))
            .Select(role => role.Failure)
            .Distinct(StringComparer.Ordinal)
            .OrderBy(value => value)
            .ToList();

        void AddRole(NativeSkillRoleProfile role, double scale)
        {
            var participates = scale > 0d;
            scale *= Math.Clamp(role.Confidence, 0d, 1d);
            if (role.SkillId > 0)
            {
                var casts = Math.Max(0d, role.CastOpportunities * scale);
                var hits = Math.Max(0d, role.HitOpportunities * scale);
                if (scheduledSkills.TryGetValue(role.SkillId, out var previous))
                {
                    scheduledSkills[role.SkillId] = previous with
                    {
                        Scale = previous.Scale + scale,
                        Casts = previous.Casts + casts,
                        Hits = previous.Hits + hits
                    };
                }
                else
                    scheduledSkills[role.SkillId] = new NativeScheduledSkill(
                        role.SkillId, role, scale, casts, hits);
            }
            foreach (var entry in role.DamageByType)
                damage[entry.Key] = damage.GetValueOrDefault(entry.Key) + entry.Value * scale;
            heal += role.Heal * scale;
            shield += role.Shield * scale;
            selfHeal += role.SelfHeal * scale;
            selfShield += role.SelfShield * scale;
            summon |= role.Summon && participates;
            if (participates) controlledEntityKinds |= role.ControlledEntityKinds;
            summonDamage += role.SummonDamage * scale;
            summonSurvival += role.SummonSurvival * scale;
            foreach (var entry in role.SummonAttackByType ?? new Dictionary<int, double>())
                summonAttackByType[entry.Key] = summonAttackByType.GetValueOrDefault(entry.Key)
                                                    + entry.Value * scale;
            controlledEntityDamage += role.ControlledEntityDamage * scale;
            controlledEntityUtility += role.ControlledEntityUtility * scale;
            controlledEntitySurvival += role.ControlledEntitySurvival * scale;
            controlledEntityCount += role.ControlledEntityCount * scale;
            foreach (var entry in role.HostileStatusApplications ?? new Dictionary<int, double>())
                hostileStatusApplications[entry.Key] =
                    hostileStatusApplications.GetValueOrDefault(entry.Key) + entry.Value * scale;
            abilitySupport += role.AbilitySupport * scale;
            abilityDefense += role.AbilityDefense * scale;
            abilityMinion += role.AbilityMinion * scale;
        }

        AddRole(baseRole, baseScale);
        foreach (var role in active) AddRole(role, activeScale);
        schedule = new NativeSkillPackageSchedule(
            scheduledSkills,
            remaining,
            Math.Max(0d, baseRole.CastOpportunities * baseScale
                          * Math.Max(0.01d, baseRole.ActionSecondsPerCast)));
        return new NativeSkillRoleProfile(
            damage, heal, shield, summon, summonDamage, summonSurvival,
            abilitySupport, abilityDefense, abilityMinion, 0d, 1d,
            IsComplete: complete,
            Failure: string.Join("; ", failures),
            // Component lower bounds were already discounted once in AddRole.
            // Keeping the package confidence at one prevents double penalties.
            Confidence: 1d,
            SummonAttackByType: summonAttackByType,
            ControlledEntityKinds: controlledEntityKinds,
            ControlledEntityDamage: controlledEntityDamage,
            ControlledEntityUtility: controlledEntityUtility,
            ControlledEntitySurvival: controlledEntitySurvival,
            HostileStatusApplications: hostileStatusApplications,
            ControlledEntityCount: controlledEntityCount,
            SelfHeal: selfHeal,
            SelfShield: selfShield);
    }

    private static bool IsSkillCompatibleWithWeaponTypes(int skillId, IReadOnlySet<int> weaponTypes)
    {
        var row = InvokeStatic("TableData", "getTSkillData", skillId);
        if (row is null) return false;
        var required = ReadSequence(Read(row, "weaponArr")).Select(ToInt).Where(id => id > 0).ToHashSet();
        return required.Count == 0 || required.Overlaps(weaponTypes);
    }

    private static int GetGrantedSkillLevel(IEnumerable<GearCandidate> items, int skillId)
    {
        var key = $"extra-skill:{skillId}";
        return items.SelectMany(candidate => GetGrantedExtraSkillLevels(candidate.Record.ItemData))
            .Where(entry => entry.Key == key)
            .Select(entry => entry.Value)
            .DefaultIfEmpty(0).Max();
    }

    private static string DescribeJointSkillSelection(int baseSkillId, IReadOnlyCollection<int> activeSkillIds, IReadOnlyCollection<GearCandidate> items)
    {
        string SkillLabel(int id)
        {
            var row = InvokeStatic("TableData", "getTSkillData", id);
            var name = ReadString(row, "name") ?? EnglishName(row, string.Empty) ?? string.Empty;
            return string.IsNullOrWhiteSpace(name) ? $"skill#{id}" : $"{Clean(name)}#{id}";
        }

        var selected = activeSkillIds.Append(baseSkillId).ToHashSet();
        var variants = items.SelectMany(candidate => CollectEquipmentAffixes(candidate.Record.ItemData))
            .Select(ResolveRuntimeAffix)
            .Select(affix => Read(affix, "tAffixData"))
            .Where(definition => (ReadNullableInt(definition, "effectType") ?? 0) == 4)
            .Select(GetSkillVariantId)
            .Where(id => selected.Contains(id)).Distinct().OrderBy(id => id).Select(SkillLabel).ToList();
        var sets = new List<string>();
        var effectsBySet = GetSetEffectScoreRows();
        foreach (var group in items.Where(item => item.SetId > 0).GroupBy(item => item.SetId).OrderBy(group => group.Key))
        {
            if (!effectsBySet.TryGetValue(group.Key, out var effects)) continue;
            var count = CountNativeSetPieces(group);
            var activeEffects = effects.Where(effect => effect.Pieces > 0 && effect.Pieces <= count)
                .Select(effect => effect.EffectId).OrderBy(id => id).ToList();
            if (activeEffects.Count > 0) sets.Add($"{group.Key}:{count}p[{string.Join(',', activeEffects)}]");
        }
        return $"base={SkillLabel(baseSkillId)}; active={string.Join(',', activeSkillIds.Select(SkillLabel))}; variant={(variants.Count == 0 ? "none" : string.Join(',', variants))}; sets={(sets.Count == 0 ? "none" : string.Join(',', sets))}";
    }

    private static bool IsLoadoutWeaponCompatible(IEnumerable<GearCandidate> items, HeroEffectProfile profile)
    {
        var weaponTypes = items.Where(item => item.Part == 1)
            .Select(item => item.WeaponType).Where(value => value > 0).ToHashSet();
        if (profile.BaseWeaponRequirement.Count > 0
            && !profile.BaseWeaponRequirement.Overlaps(weaponTypes)) return false;
        return profile.SkillWeaponPreferences
            .Where(requirement => requirement.Count > 0)
            .All(requirement => requirement.Overlaps(weaponTypes));
    }

    private static bool TryEvaluateFinalPerformance(
        List<GearCandidate> items,
        object hero,
        HeroEffectProfile profile,
        List<object> currentItems,
        out double score,
        out object effectiveAttr,
        object? preparedAttr = null,
        NativeAbilityPackage? preparedAbilities = null,
        bool baseSkillOnly = false,
        IncomingPressureProfile? incomingPressure = null)
    {
        score = 0d;
        effectiveAttr = null!;
        try
        {
#if PATHOFIDLE_RUNTIME_TEST
            void TraceFastPreview(string stage)
            {
                if (baseSkillOnly)
                    Plugin.DiagInfo($"AUTO-GEAR FAST PREVIEW|stage={stage}|elapsed={MainThreadNativeGateway.CurrentWorkerOperation?.PlanningElapsedSeconds ?? -1d:0.000}");
            }
            TraceFastPreview("start");
#endif
            var simulated = preparedAttr ?? CreateJointLoadoutAttr(hero, items, currentItems, profile.PlannedSkills);
            var nativeAbilities = preparedAbilities
                                  ?? EvaluateNativeAbilityPackage(items, hero, profile, simulated);
            if (!nativeAbilities.IsComplete) return false;
            var defensePressure = incomingPressure
                                  ?? CaptureDefensePressureProfile(hero);
            effectiveAttr = CreateAbilityAdjustedAttr(simulated, nativeAbilities);
#if PATHOFIDLE_RUNTIME_TEST
            TraceFastPreview("effective-attr");
#endif
            var candidateItems = items.ToList();
            if (!baseSkillOnly)
            {
                var plannedSkillLevels = profile.SkillIds.Where(id => id > 0)
                    .Append(profile.PreviewBaseSkillId)
                    .Where(id => id > 0).Distinct()
                    .Select(id => (SkillId: id, Level: GetPlannedSkillEffectiveLevel(
                        hero, profile.PlannedSkills, id, candidateItems)))
                    .ToList();
                effectiveAttr = CreateStrictSkillPackageAdjustedAttr(
                    hero,
                    plannedSkillLevels,
                    effectiveAttr,
                    false,
                    candidateItems,
                    out _,
                    nativeAbilities.AppliedAbilityCounts);
            }
#if PATHOFIDLE_RUNTIME_TEST
            TraceFastPreview("strict-skills");
#endif

            // Prefer the same preview path used by the game UI. PowerData resolves
            // the selected base skill's own physical/elemental mix, damage types,
            // attribute coefficients and class scaling against this temporary
            // AttrData. Nothing on the real hero or save is changed.
            var previewDamage = 0d;
            var previewHeal = 0d;
            var previewShield = 0d;
            var jointRole = new NativeSkillRoleProfile(
                new Dictionary<int, double>(), 0d, 0d, false, 0d, 0d, 0d, 0d, 0d, 0d, 1d);
            var skillSchedule = new NativeSkillPackageSchedule(
                new Dictionary<int, NativeScheduledSkill>(), 0d, 0d);
            bool previewRankable;
            if (baseSkillOnly && profile.Focus.Key == "defense")
            {
                var actualSkill = InvokeInstance(hero, "GetNowBaseSkillData");
                var skillId = profile.PreviewBaseSkillId > 0
                    ? profile.PreviewBaseSkillId
                    : ReadNullableInt(Read(actualSkill, "tSkillData"), "id") ?? 0;
                var level = Math.Max(1, profile.PreviewBaseSkillLevel > 0
                    ? profile.PreviewBaseSkillLevel
                    : ReadNullableInt(actualSkill, "level") ?? 1);
                if (skillId <= 0)
                    throw new InvalidOperationException(
                        "The Defense base-skill preview has no skill ID.");
                var baseRole = ReadNativeSkillRoleProfile(
                    hero, skillId, level, effectiveAttr, false, candidateItems,
                    true, false);
                jointRole = BuildSharedSkillPackage(
                    baseRole, Array.Empty<NativeSkillRoleProfile>(), out skillSchedule);
                previewDamage = GetManualDamageAmount(jointRole.DamageByType, profile.Focus);
                previewHeal = Math.Max(0d, jointRole.Heal);
                previewShield = Math.Max(0d, jointRole.Shield);
                previewRankable = HasProvenNativeRoleSignal(jointRole);
            }
            else
            {
                previewRankable = baseSkillOnly
                    ? TryEvaluateNativeBaseSkillSustainedDamage(
                        effectiveAttr, hero, profile, items, out previewDamage)
                    : TryEvaluateJointSkillSustainedPerformance(
                        effectiveAttr, hero, profile, items, out previewDamage, out previewHeal,
                        out previewShield, out jointRole, out skillSchedule);
            }
#if PATHOFIDLE_RUNTIME_TEST
            TraceFastPreview("skill-preview");
#endif
            if (!previewRankable) return false;
            var defenseWindow = EvaluateDefenseWindow(
                effectiveAttr,
                nativeAbilities,
                skillSchedule,
                profile,
                defensePressure,
                jointRole.SelfHeal,
                jointRole.SelfShield);
            var expectedConditional = baseSkillOnly
                ? new ExpectedConditionalPackage(0d, 0d, 0d, 0d, 0d, 0d, 0d)
                : defenseWindow.Conditional;
            previewDamage = Math.Max(0d, previewDamage + expectedConditional.Damage);
            previewHeal = Math.Max(0d, previewHeal + expectedConditional.Heal);
            previewShield = Math.Max(0d, previewShield + expectedConditional.Shield);

            // C# forbids capturing an out parameter in a local function. Keep
            // the exact final AttrData instance in a normal local; the caller
            // still receives that same object through effectiveAttr.
            var scoredAttr = baseSkillOnly
                ? effectiveAttr
                : defenseWindow.EffectiveAttr;
            effectiveAttr = scoredAttr;
            double Positive(int attrId) => Math.Max(0d, ReadAttrRequired(scoredAttr, attrId));
            double Sum(params int[] attrIds) => attrIds.Sum(Positive);
            var hp = Positive(5);
            var defence = Sum(3, 4);
            // GetAttrValue already folds the corresponding up-rate/conversion
            // buckets into the final HP/defence/regen values. Score each final
            // output once; keep avoidance/resistance as separate EHP dimensions.
            var sustain = Sum(7, 91, 92, 93, 94, 220, 222, 224);
            var skillSustain = Math.Max(0d,
                (previewHeal + previewShield * 1.25d) * PerformanceTimeLinearNormalization);
            var avoidanceRate = Sum(32, 34, 36, 85, 86);
            var resistance = Sum(61, 62, 63, 64, 65, 66, 130, 131, 132);
            var protectionFlags = new[] { 151, 152, 153, 154, 155, 156, 157, 158, 184, 188, 202 }
                .Count(id => Positive(id) > 0d);
            var defensePenalty = (Positive(200) > 0d ? 1d : 0d) + (Positive(201) > 0d ? 1d : 0d);
            var staticSurvival = hp + defence * 2d + sustain * 4d + skillSustain
                                 + jointRole.AbilityDefense + nativeAbilities.Defense
                                 + expectedConditional.Defense
                                 + hp * Math.Clamp(avoidanceRate / 100d, 0d, 4d)
                                 + defence * Math.Clamp(resistance / 100d, 0d, 4d)
                                 + protectionFlags * Math.Max(250d, hp * 0.12d)
                                - defensePenalty * Math.Max(500d, (hp + defence) * 0.35d);
            var simulatedSurvival = defenseWindow.Simulation.RemainingHealth
                                    + defenseWindow.Simulation.RemainingShield
                                    + defenseWindow.Simulation.DamagePrevented
                                    + defenseWindow.Simulation.ShieldAbsorbed
                                    + defenseWindow.Simulation.EffectiveHealing;
            var effectiveSurvival = profile.Focus.Key == "defense"
                ? simulatedSurvival
                : staticSurvival;
            effectiveSurvival = Math.Max(0d, effectiveSurvival);
            var support = Math.Max(0d, Sum(81, 82, 83, 84, 91, 92, 93, 94, 95, 96, 185, 191)
                                                + jointRole.AbilitySupport + nativeAbilities.Support
                                                + expectedConditional.Support);
            var controlledAttr = (jointRole.ControlledEntityKinds.HasFlag(NativeControlledEntityKind.Ally)
                                      ? Positive(25) * 50d
                                      : 0d)
                                 + (jointRole.ControlledEntityKinds.HasFlag(NativeControlledEntityKind.Minion)
                                     ? Positive(190)
                                     : 0d);
            var minion = Math.Max(0d, controlledAttr
                                               + jointRole.ControlledEntityDamage * PerformanceTimeLinearNormalization
                                               + jointRole.ControlledEntitySurvival * 0.35d
                                               + jointRole.ControlledEntityUtility
                                               + nativeAbilities.Minion
                                               + expectedConditional.Minion);
            var roleTheme = profile.Focus.Key is "support" or "defense" or "minion";
            var damageWeight = BlendThemePriority(
                profile.Focus,
                1700d,
                roleTheme ? 280d : 1700d,
                profile.Focus.Key is "support" or "defense" or "minion" ? 80d : 1700d);
            var survivalWeight = BlendThemePriority(
                profile.Focus,
                420d,
                profile.Focus.Key is "defense" ? 1300d : 420d,
                profile.Focus.Key == "defense" ? 1800d
                    : profile.Focus.Key == "support" ? 500d
                    : profile.Focus.Key == "minion" ? 350d : 420d);
            var utilityWeight = BlendThemePriority(
                profile.Focus,
                180d,
                profile.Focus.Key == "support" ? 1550d : 180d,
                profile.Focus.Key == "support" ? 2200d : 100d);
            var minionWeight = BlendThemePriority(
                profile.Focus,
                120d,
                profile.Focus.Key == "minion" ? 1550d : 120d,
                profile.Focus.Key == "minion" ? 2200d : 80d);
            var damageScore = Math.Log10(1d
                                         + previewDamage * PerformanceTimeLinearNormalization)
                              * damageWeight;
            damageScore += Math.Log10(1d + Math.Max(0d, nativeAbilities.OffensiveAttrValue))
                           * BlendThemePriority(
                               profile.Focus,
                               720d,
                               roleTheme ? 120d : 720d,
                               roleTheme ? 60d : 720d);
            var survivalScore = profile.Focus.Key == "defense"
                ? defenseWindow.Simulation.ObjectiveScore
                  * survivalWeight / 20d
                : Math.Log10(1d + effectiveSurvival) * survivalWeight;
            var utilityScore = Math.Log10(1d + support * 10d) * utilityWeight;
            var minionScore = Math.Log10(1d + minion) * minionWeight;
            // This method's aggregate is multiplied by 2.4 by the caller. Keep
            // the deferred structural expectation in the original score units.
            score = damageScore + survivalScore + utilityScore + minionScore
                    + expectedConditional.StructuralScore / 2.4d;
#if PATHOFIDLE_DIAGNOSTICS
            Plugin.DiagInfo(
                $"AUTO-GEAR PERFORMANCE BREAKDOWN|focus={profile.Focus.Key}|"
                + $"damage={previewDamage:0.###}|heal={previewHeal:0.###}|selfHeal={jointRole.SelfHeal + expectedConditional.SelfHeal:0.###}|shield={previewShield:0.###}|selfShield={jointRole.SelfShield + expectedConditional.SelfShield:0.###}|"
                + $"survival={effectiveSurvival:0.###}|support={support:0.###}|minion={minion:0.###}|"
                + $"pressure={defenseWindow.Simulation.PressureSource}|pressureRaw={defensePressure.RawDamage:0.###}|"
                + $"survived={defenseWindow.Simulation.Survived}|alive={defenseWindow.Simulation.SecondsAlive:0.###}/{defensePressure.WindowSeconds:0.###}|"
                + $"remainingHp={defenseWindow.Simulation.RemainingHealth:0.###}|remainingShield={defenseWindow.Simulation.RemainingShield:0.###}|"
                + $"taken={defenseWindow.Simulation.DamageTaken:0.###}|prevented={defenseWindow.Simulation.DamagePrevented:0.###}|"
                + $"shieldAbsorbed={defenseWindow.Simulation.ShieldAbsorbed:0.###}|effectiveHeal={defenseWindow.Simulation.EffectiveHealing:0.###}|"
                + $"bloodied={defenseWindow.Simulation.BloodiedEntries:0.###}|lethal={defenseWindow.Simulation.LethalEvents:0.###}|"
                + $"damageScore={damageScore:0.###}|survivalScore={survivalScore:0.###}|"
                + $"utilityScore={utilityScore:0.###}|minionScore={minionScore:0.###}|"
                + $"conditionalStructural={expectedConditional.StructuralScore:0.###}|performance={score:0.###}");
#endif
            return true;
        }
        catch (Exception error)
        {
            if (!performanceSimulationFailureLogged)
            {
                performanceSimulationFailureLogged = true;
                Plugin.DiagWarning($"AUTO-GEAR ATTR SIMULATION FAILED|heuristic fallback is active|{error.GetBaseException().Message}");
            }
            return false;
        }
    }

    private static bool TryEvaluateJointSkillSustainedPerformance(
        object attrData,
        object hero,
        HeroEffectProfile profile,
        IEnumerable<GearCandidate> items,
        out double previewDamage,
        out double previewHeal,
        out double previewShield,
        out NativeSkillRoleProfile jointRole,
        out NativeSkillPackageSchedule schedule)
    {
        previewDamage = 0d;
        previewHeal = 0d;
        previewShield = 0d;
        jointRole = new NativeSkillRoleProfile(new Dictionary<int, double>(), 0d, 0d, false, 0d, 0d, 0d, 0d, 0d, 0d, 1d);
        schedule = new NativeSkillPackageSchedule(
            new Dictionary<int, NativeScheduledSkill>(), 0d, 0d);
        try
        {
            var candidates = items.ToList();
            var baseLevel = GetPlannedSkillEffectiveLevel(
                hero, profile.PlannedSkills, profile.PreviewBaseSkillId, candidates);
            var baseRole = ReadNativeSkillRoleProfile(
                hero, profile.PreviewBaseSkillId, baseLevel, attrData, false, candidates, true, false);
            var activeRoles = profile.SkillIds.Where(id => id > 0 && id != profile.PreviewBaseSkillId)
                .Select(id => ReadNativeSkillRoleProfile(
                    hero, id, GetPlannedSkillEffectiveLevel(hero, profile.PlannedSkills, id, candidates),
                    attrData, false, candidates, true, false))
                .ToList();
            var package = BuildSharedSkillPackage(baseRole, activeRoles, out schedule);
            jointRole = package;
            previewDamage = Math.Max(0d, GetManualDamageAmount(package.DamageByType, profile.Focus));
            previewHeal = Math.Max(0d, package.Heal);
            previewShield = Math.Max(0d, package.Shield);
            // Unknown conditional branches keep a conservative zero lower
            // bound. The preview remains usable only when some independent
            // native damage/heal/shield/summon/utility signal was proven.
            if (!IsNativePackageRankable(package, profile.Focus)) return false;
            if (SatisfiesNativeThemeOutputContract(
                    profile.Focus, baseRole, activeRoles, package,
                    out var themeFailure)) return true;
            Plugin.DiagDebug(
                $"AUTO-GEAR 30S THEME OUTPUT REJECTED|focus={profile.Focus.Key}|{themeFailure}");
            return false;
        }
        catch (Exception error)
        {
            if (!nativeSkillPreviewFailureLogged)
            {
                nativeSkillPreviewFailureLogged = true;
                Plugin.DiagWarning($"AUTO-GEAR 30S JOINT SKILL PREVIEW FAILED|attribute fallback is active|{error.GetBaseException().Message}");
            }
            return false;
        }
    }

    private static bool TryEvaluateNativeBaseSkillSustainedDamage(object attrData, object hero, HeroEffectProfile profile, IEnumerable<GearCandidate> items, out double previewDamage, bool includeCurrentEquipmentVariant = false)
    {
        const double windowSeconds = PerformancePreviewWindowSeconds;
        previewDamage = 0d;
        try
        {
            var actualSkill = InvokeInstance(hero, "GetNowBaseSkillData");
            // When a guide targets a different base skill, compare candidate gear
            // against that target instead of silently previewing the currently
            // equipped (outgoing) base skill with the target skill's tags.
            var skillId = profile.PreviewBaseSkillId > 0
                ? profile.PreviewBaseSkillId
                : ReadNullableInt(Read(actualSkill, "tSkillData"), "id") ?? 0;
            if (skillId <= 0) throw new InvalidOperationException("The active base skill ID is unavailable.");
            var level = Math.Max(1, profile.PreviewBaseSkillLevel > 0
                ? profile.PreviewBaseSkillLevel
                : ReadNullableInt(actualSkill, "level") ?? 1);
            var preview = InvokeRequiredStaticMany("SkillData", "CreatePreview", skillId, level, attrData)
                          ?? throw new InvalidOperationException("SkillData.CreatePreview returned no skill.");

            // The live skill may be variant-enabled by the currently equipped
            // loadout. Do not copy that state into every candidate. Apply only a
            // variant supplied by the candidate loadout being evaluated.
            if (CandidateEnablesSkillVariant(items, skillId)
                || (includeCurrentEquipmentVariant && CurrentEquipmentEnablesSkillVariant(hero, skillId)))
                InvokeRequiredInstance(preview, "SetVariant", true);

            var skillInfo = Read(preview, "tSkillInfoData")
                            ?? throw new InvalidOperationException("The preview skill info is unavailable.");
            var powerIds = new HashSet<int>();
            foreach (var explainId in ReadSequence(Read(skillInfo, "infoArr")).Select(ToInt).Where(id => id > 0))
            {
                var explain = InvokeStatic("TableData", "getTSkillExplainData", explainId);
                if ((ReadNullableInt(explain, "type") ?? -1) != 2) continue;
                var powerId = ReadSequence(Read(explain, "typeParam")).Select(ToInt).FirstOrDefault();
                if (powerId > 0) powerIds.Add(powerId);
            }
            if (powerIds.Count == 0) return false;

            var directDamagePerEvent = 0d;
            var periodicDamagePerEvent = 0d;
            var damageRows = 0;
            foreach (var powerId in powerIds)
            {
                var power = InvokeRequiredStaticMany("PowerData", "CreateByShow", powerId, level, preview)
                            ?? throw new InvalidOperationException($"PowerData.CreateByShow({powerId}) returned no power.");
                if ((ReadNullableInt(Read(power, "tPowerData"), "type") ?? 0) != 1) continue;
                var rowDamage = 0d;
                var typedValues = 0;
                foreach (var entry in ReadEntries(Read(power, "dmgPowerDic")))
                {
                    var value = Convert.ToDouble(Read(entry, "Value") ?? 0d, CultureInfo.InvariantCulture);
                    if (!double.IsFinite(value) || value <= 0d) continue;
                    var nativeDamageType = Read(entry, "Key");
                    var damageType = ToInt(nativeDamageType ?? 0);
                    RememberNativeDamageTypeName(damageType, nativeDamageType);
                    if (IsPeriodicDamageType(damageType)) periodicDamagePerEvent += value;
                    else directDamagePerEvent += value;
                    rowDamage += value;
                    typedValues++;
                }
                if (typedValues == 0)
                {
                    rowDamage = ReadValues(Read(power, "dmgPowerDic"))
                        .Select(value => Convert.ToDouble(value, CultureInfo.InvariantCulture))
                        .Where(value => double.IsFinite(value) && value > 0d)
                        .Sum();
                    if (rowDamage <= 0d)
                        rowDamage = Convert.ToDouble(Read(power, "power") ?? 0d, CultureInfo.InvariantCulture);
                    if (double.IsFinite(rowDamage) && rowDamage > 0d) directDamagePerEvent += rowDamage;
                }
                if (!double.IsFinite(rowDamage) || rowDamage <= 0d) continue;
                damageRows++;
            }
            var nativeDamagePerEvent = directDamagePerEvent + periodicDamagePerEvent;
            if (damageRows == 0 || !double.IsFinite(nativeDamagePerEvent) || nativeDamagePerEvent <= 0d) return false;

            var previewAttr = Read(preview, "attrData") ?? attrData;
            var nativeSpeed = Convert.ToDouble(
                InvokeRequiredInstance(previewAttr, "GetSkillSpeedRate", (object)null!) ?? 1d,
                CultureInfo.InvariantCulture);
            if (!double.IsFinite(nativeSpeed) || nativeSpeed <= 0d) nativeSpeed = 1d;
            nativeSpeed = Math.Clamp(nativeSpeed, 0.05d, 20d);
            var cooldown = Math.Max(0d, ReadAttrRequired(previewAttr, 2001));
            if (ReadAttrRequired(previewAttr, 3001) > 0d) cooldown = 0d;

            // ActionData advances cooldown/action time by the native skill-speed
            // rate. Use the real cooldown when available. For no-cooldown skills,
            // whose animation/resource gate is not exposed safely, assume a
            // conservative one-second base action. This continuous opportunity
            // count avoids ranking cliffs near the preview-window boundary. Speed is
            // applied here once and is not multiplied into damage again.
            var baseInterval = cooldown > 0.01d ? cooldown : 1d;
            var castOpportunities = Math.Clamp(
                windowSeconds * nativeSpeed / baseInterval,
                1d,
                MaximumPerformancePreviewEvents);
            if (!double.IsFinite(castOpportunities) || castOpportunities <= 0d) return false;

            var critChance = Math.Clamp(PercentRate(ReadAttrRequired(attrData, 31)), 0d, 1d);
            var critDamage = Math.Max(0.5d, 0.5d + PercentRate(ReadAttrRequired(attrData, 37)));
            var expectedPerEvent = directDamagePerEvent * Math.Max(0.1d, 1d + critChance * critDamage)
                                   + periodicDamagePerEvent;
            // Do not multiply every Power row by emitter/bullet counts here. Some
            // skills already expose repeated components as separate Power rows,
            // and without an exact row-to-projectile link that would double count.
            previewDamage = expectedPerEvent * castOpportunities;

            if (!sustainedDamageModelLogged)
            {
                sustainedDamageModelLogged = true;
                Plugin.DiagInfo($"AUTO-GEAR 30S ESTIMATE|skill={skillId}|cooldown={cooldown:0.###}|speed={nativeSpeed:0.###}|cast-opportunities={castOpportunities:0.##}|single-target uptime proxy, not exact battle AI");
            }
            return double.IsFinite(previewDamage) && previewDamage > 0d;
        }
        catch (Exception error)
        {
            if (!nativeSkillPreviewFailureLogged)
            {
                nativeSkillPreviewFailureLogged = true;
                Plugin.DiagWarning($"AUTO-GEAR 30S SKILL PREVIEW FAILED|attribute fallback is active|{error.GetBaseException().Message}");
            }
            return false;
        }
    }

    private static bool CandidateEnablesSkillVariant(IEnumerable<GearCandidate> items, int skillId)
        => skillId > 0 && items.SelectMany(candidate => GetItemSkillVariantIds(candidate.Record.ItemData))
            .Any(id => id == skillId);

    private static IEnumerable<int> GetItemSkillVariantIds(object item)
        => CollectEquipmentAffixes(item)
            .Select(ResolveRuntimeAffix)
            .Select(affix => Read(affix, "tAffixData"))
            .Where(definition => (ReadNullableInt(definition, "effectType") ?? 0) == 4)
            .Select(GetSkillVariantId)
            .Where(id => id > 0)
            .Distinct();

    private static IEnumerable<int> GetItemNativeAbilityIds(object item)
        => CollectEquipmentAffixes(item)
            .Concat(CollectGrantedMasteryAffixes(item))
            .Select(ResolveRuntimeAffix)
            .Where(affix => (ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0) == 3)
            .Select(affix => ReadNullableInt(Read(affix, "saveData"), "abilityId")
                             ?? ReadNullableInt(Read(affix, "tAbilityData"), "id")
                             ?? ReadSequence(Read(Read(affix, "tAffixData"), "effectParam"))
                                 .Select(ToInt).FirstOrDefault())
            .Where(id => id > 0)
            .Distinct();

    private static IEnumerable<int> GetRelevantItemSkillVariantIds(
        object item,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
        => CollectEquipmentAffixes(item)
            .Select(ResolveRuntimeAffix)
            .Where(affix => (ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0) == 4)
            .Where(affix => IsAffixRelevantToProfile(affix, profile, relevanceScope))
            .Select(affix => GetSkillVariantId(Read(affix, "tAffixData")))
            .Where(id => id > 0)
            .Distinct();

    private static IEnumerable<int> GetRelevantItemNativeAbilityIds(
        object item,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
        => CollectEquipmentAffixes(item)
            .Concat(CollectGrantedMasteryAffixes(item))
            .Select(ResolveRuntimeAffix)
            .Where(affix => (ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0) == 3)
            .Where(affix => IsAffixRelevantToProfile(affix, profile, relevanceScope))
            .Select(affix => ReadNullableInt(Read(affix, "saveData"), "abilityId")
                             ?? ReadNullableInt(Read(affix, "tAbilityData"), "id")
                             ?? ReadSequence(Read(Read(affix, "tAffixData"), "effectParam"))
                                 .Select(ToInt).FirstOrDefault())
            .Where(id => id > 0)
            .Distinct();

    private static IEnumerable<KeyValuePair<string, int>> GetRelevantGrantedExtraSkillLevels(
        object item,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
        => GetGrantedExtraSkillLevels(item).Where(entry =>
        {
            const string prefix = "extra-skill:";
            return entry.Key.StartsWith(prefix, StringComparison.Ordinal)
                   && int.TryParse(
                       entry.Key.Substring(prefix.Length),
                       NumberStyles.Integer,
                       CultureInfo.InvariantCulture,
                       out var skillId)
                   && IsSkillTargetRelevant(skillId, profile, relevanceScope, true);
        });

    private static bool CurrentEquipmentEnablesSkillVariant(object hero, int skillId)
        => skillId > 0 && GetGearSlots()
            .Select(slot => GetEquippedItem(hero, slot.Part, slot.MainWeapon))
            .Where(item => item is not null).Cast<object>()
            .SelectMany(CollectEquipmentAffixes)
            .Select(ResolveRuntimeAffix)
            .Select(affix => Read(affix, "tAffixData"))
            .Where(definition => (ReadNullableInt(definition, "effectType") ?? 0) == 4)
            .Select(GetSkillVariantId)
            .Any(id => id == skillId);

    // Native AffixData.SetActiveHeroSkillVariant reads effectParam[0] only.
    // Later parameters can describe the effect but are not additional skills.
    private static int GetSkillVariantId(object? affixDefinition)
        => ReadSequence(Read(affixDefinition, "effectParam")).Select(ToInt).FirstOrDefault();

    private static void ApplyEquipmentToAttr(
        object attrData,
        object item,
        bool active,
        bool includeForgeBonuses)
    {
        var equip = Read(item, "itemEquipData")
                    ?? throw new InvalidOperationException("Equipment data is unavailable.");
        var equipAttr = Read(equip, "equipAttrData") ?? throw new InvalidOperationException("Equipment AttrData is unavailable.");
        var sign = active ? 1d : -1d;
        foreach (var mapping in GetEquipAttrMappings())
        {
            var equipType = CreateEnum("EEquipAttrType", mapping.EquipType)
                            ?? throw new InvalidOperationException($"Unknown equipment attribute type {mapping.EquipType}.");
            var value = ReadEquipmentAttrValueForOptimization(
                equip, equipAttr, equipType, includeForgeBonuses);
            if (Math.Abs(value) < double.Epsilon) continue;
            var attrEnum = CreateEnum("EAttrType", mapping.BattleAttrType)
                           ?? throw new InvalidOperationException($"Unknown battle attribute type {mapping.BattleAttrType}.");
            InvokeRequiredInstance(attrData, "ChangeAttr", attrEnum, (float)(value * sign));
        }
        foreach (var affix in CollectEquipmentAffixes(item).Concat(CollectGrantedMasteryAffixes(item)))
            InvokeRequiredInstance(ResolveRuntimeAffix(affix), "SetActiveAttrData", attrData, active);
    }

    private static List<EquipAttrMapping> GetEquipAttrMappings()
    {
        if (equipAttrMappings is not null) return equipAttrMappings;
        var mappings = ReadValues(ReadStatic("TableData", "TEquipAttrDict"))
            .Select(row => new EquipAttrMapping(ReadNullableInt(row, "id") ?? 0, ReadNullableInt(row, "battleAttrId") ?? 0))
            .Where(mapping => mapping.EquipType > 0 && mapping.BattleAttrType > 0)
            .Distinct().ToList();
        if (mappings.Count == 0) throw new InvalidOperationException("TEquipAttr mappings are unavailable.");
        equipAttrMappings = mappings;
        return mappings;
    }

    private static double ReadAttrRequired(object attrData, int id)
    {
        var attrType = CreateEnum("EAttrType", id) ?? throw new InvalidOperationException($"Unknown battle attribute type {id}.");
        return Convert.ToDouble(InvokeRequiredInstance(attrData, "GetAttrValue", attrType) ?? 0d, CultureInfo.InvariantCulture);
    }

    private static int ReadIntAttrRequired(object attrData, int id)
    {
        var attrType = CreateEnum("EAttrType", id) ?? throw new InvalidOperationException($"Unknown battle attribute type {id}.");
        return Convert.ToInt32(InvokeRequiredInstance(attrData, "GetIntAttrValue", attrType) ?? 0, CultureInfo.InvariantCulture);
    }

    private static (double Regular, double Extra) GetDamageTypeBuckets(object attrData, string focusKey)
    {
        var physical = new[] { (Regular: 51, Extra: 110), (Regular: 52, Extra: 111), (Regular: 53, Extra: 112) };
        var elemental = new[] { (Regular: 54, Extra: 113), (Regular: 55, Extra: 114), (Regular: 56, Extra: 115) };
        var pairs = focusKey switch
        {
            "fire" => new[] { elemental[0] },
            "ice" => new[] { elemental[1] },
            "lightning" => new[] { elemental[2] },
            "bleed" => new[] { (Regular: 121, Extra: 0) },
            "corrosion" => new[] { (Regular: 122, Extra: 0) },
            "physical" => physical,
            "elemental" => elemental,
            _ => physical.Concat(elemental).ToArray()
        };
        return pairs.Select(pair => (
                Regular: ReadAttrRequired(attrData, pair.Regular),
                Extra: pair.Extra > 0 ? ReadAttrRequired(attrData, pair.Extra) : 0d))
            .OrderByDescending(pair => NativeRateFactor(pair.Regular) * NativeRateFactor(pair.Extra))
            .FirstOrDefault();
    }

    private static double PercentRate(double value) => value / 100d;
    private static double NativeRateFactor(double value) => value >= 0d ? (100d + value) / 100d : 100d / (100d - value);

    private static List<object> CollectEquipmentAffixes(object item)
    {
        var result = new List<object>();
        var keys = new HashSet<string>(StringComparer.Ordinal);
        var equip = Read(item, "itemEquipData");
        var save = Read(item, "saveItemData");
        var runtimeAffixes = ReadList(Read(equip, "affixList")).ToList();
        AddMany(runtimeAffixes.Count > 0 ? runtimeAffixes : Read(save, "affixList"));
        var runtimeRunes = ReadList(Read(equip, "slotRuneList")).ToList();
        foreach (var rune in runtimeRunes.Count > 0 ? runtimeRunes : ReadList(Read(save, "slotRuneList")))
            AddMany(Read(rune, "affixList"));
        Add(Read(equip, "runewordsAffixData") ?? Read(save, "runewordsAffixData"));
        return result;

        void AddMany(object? values)
        {
            foreach (var value in ReadList(values)) Add(value);
        }

        void Add(object? value)
        {
            if (value is null) return;
            var pointer = Read(value, "Pointer");
            var key = pointer is null
                ? $"ref:{System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(value)}"
                : $"ptr:{pointer}";
            if (keys.Add(key)) result.Add(value);
        }
    }

    private static object? GetRunewordAffix(object item)
    {
        var equip = Read(item, "itemEquipData");
        var save = Read(item, "saveItemData");
        return Read(equip, "runewordsAffixData") ?? Read(save, "runewordsAffixData");
    }

    private static IEnumerable<object> CollectRunewordAffixes(object item)
    {
        if (GetRunewordAffix(item) is { } affix) yield return affix;
    }

    private static IEnumerable<object> CollectGrantedMasteryAffixes(object item)
    {
        // effectType 100 calls HeroTalentData.AddExtraTalent. When that talent
        // is a mastery, native TalentData.Init creates MasteryData at exactly
        // saveData.talentLevel and immediately applies its affixes. Build the
        // game's display-only mastery object to obtain the same scaled affixes
        // without touching the live hero or save.
        foreach (var outer in CollectRunewordAffixes(item).Select(ResolveRuntimeAffix))
        {
            var definition = Read(outer, "tAffixData");
            if ((ReadNullableInt(definition, "effectType") ?? 0) != 100) continue;
            var save = Read(outer, "saveData");
            var talent = Read(outer, "tTalentData")
                         ?? InvokeStatic("TableData", "getTTalentData", ReadNullableInt(save, "talentId") ?? 0);
            var masteryId = ReadNullableInt(talent, "masteryId") ?? 0;
            var talentLevel = ReadNullableInt(save, "talentLevel") ?? 0;
            if (masteryId <= 0 || talentLevel <= 0) continue;
            var preview = InvokeRequiredStaticMany("MasteryData", "CreateByShow", masteryId, talentLevel, talentLevel)
                          ?? throw new InvalidOperationException($"Mastery preview {masteryId} Lv{talentLevel} could not be created.");
            foreach (var affix in ReadList(Read(preview, "affixList")))
            {
                // Native MasteryData.GetMasteryEffect applies only bodyAttr
                // and getAbility affixes. It does not execute nested
                // skillVariant/extraTalent rows even if a future table contains
                // them, so keep the preview contract equally narrow.
                var effectType = ReadNullableInt(Read(ResolveRuntimeAffix(affix), "tAffixData"), "effectType") ?? 0;
                if (effectType is 1 or 3) yield return affix;
            }
        }
    }

    private static HashSet<string> GetNonStackingEffectKeys(object item)
    {
        var result = new HashSet<string>(StringComparer.Ordinal);
        var equip = Read(item, "itemEquipData");
        var equipDefinition = Read(equip, "tEquipData");
        var itemSave = Read(item, "saveItemData");
        var quality = ReadNullableInt(itemSave, "quality") ?? ReadNullableInt(equipDefinition, "quality") ?? 0;
        var uniqueSkillAffix = ReadNullableInt(equipDefinition, "uniqueSkillAffix") ?? 0;
        // Quality-8 Uniques can expose the same named special effect on two
        // physical copies. Native appends both AbilityData instances, but the
        // eventual buff/status may still merge or cap per ability. The user
        // explicitly prefers a different effect over a duplicate Unique, so
        // keep this policy narrow to the Unique's declared special affix rather
        // than incorrectly treating every repeated ability as non-stacking.
        if (quality == 8 && uniqueSkillAffix > 0)
            result.Add($"unique-effect:{uniqueSkillAffix}");

        var runewordAffix = GetRunewordAffix(item) is { } rawRuneword ? ResolveRuntimeAffix(rawRuneword) : null;
        foreach (var affix in CollectEquipmentAffixes(item).Concat(CollectGrantedMasteryAffixes(item)).Select(ResolveRuntimeAffix))
        {
            var definition = Read(affix, "tAffixData");
            var save = Read(affix, "saveData");
            var effectType = ReadNullableInt(definition, "effectType") ?? 0;
            var affixId = ReadNullableInt(definition, "id") ?? ReadNullableInt(save, "id") ?? 0;

            switch (effectType)
            {
                case 4: // skillVariant: enabling the same variant twice is still one boolean state.
                {
                    var skillId = GetSkillVariantId(definition);
                    if (skillId > 0) result.Add($"skill-variant:{skillId}");
                    else if (affixId > 0) result.Add($"skill-variant-affix:{affixId}");
                    break;
                }
                case 100:
                {
                    if (!NativeEquals(affix, runewordAffix)) break;
                    // Extra masteries are independently applied and may stack.
                    // Extra skills are different: GetSkillList deduplicates by
                    // the real TSkill id and keeps only the highest level.
                    var talent = Read(affix, "tTalentData")
                                 ?? InvokeStatic("TableData", "getTTalentData", ReadNullableInt(save, "talentId") ?? 0);
                    var talentType = ReadNullableInt(talent, "type") ?? 0;
                    var skillId = ReadNullableInt(talent, "skillId") ?? 0;
                    var level = Math.Max(0, ReadNullableInt(save, "talentLevel") ?? 0);
                    if (level > 0 && talentType == 1 && skillId > 0)
                        result.Add($"extra-skill:{skillId}");
                    break;
                }
            }
        }
        return result;
    }

    private static HashSet<string> GetRelevantHardExclusiveEffectKeys(
        object item,
        IEnumerable<string> nonStackingEffectKeys,
        HeroEffectProfile profile)
    {
        var relevantAffixIds = new HashSet<int>();
        foreach (var affix in CollectEquipmentAffixes(item)
                     .Concat(CollectGrantedMasteryAffixes(item))
                     .Select(ResolveRuntimeAffix))
        {
            var affixId = ReadNullableInt(Read(affix, "tAffixData"), "id")
                          ?? ReadNullableInt(Read(affix, "saveData"), "id") ?? 0;
            if (affixId <= 0) continue;
            if (IsAffixRelevantToProfile(
                    affix, profile, EffectRelevanceScope.SelectableJointPlan))
                relevantAffixIds.Add(affixId);
        }

        var result = new HashSet<string>(StringComparer.Ordinal);
        const string prefix = "unique-effect:";
        foreach (var key in nonStackingEffectKeys.Where(IsHardExclusiveEffectKey))
        {
            if (!key.StartsWith(prefix, StringComparison.Ordinal)
                || !int.TryParse(
                    key.Substring(prefix.Length),
                    NumberStyles.Integer,
                    CultureInfo.InvariantCulture,
                    out var affixId)) continue;
            // Never infer that this Unique's declared effect is relevant merely
            // because some *other* effect on the item is relevant. That fallback
            // could reject the whole second item even when the declared special
            // targets an unused skill. A hard exclusion requires an exact,
            // independently verified affix match; the item's stats remain valid.
            if (relevantAffixIds.Contains(affixId))
                result.Add(key);
        }
        return result;
    }

    private static bool IsHardExclusiveEffectKey(string key)
        => key.StartsWith("unique-effect:", StringComparison.Ordinal);

    private static Dictionary<string, int> GetGrantedExtraSkillLevels(object item)
    {
        var result = new Dictionary<string, int>(StringComparer.Ordinal);
        foreach (var affix in CollectRunewordAffixes(item).Select(ResolveRuntimeAffix))
        {
            var definition = Read(affix, "tAffixData");
            if ((ReadNullableInt(definition, "effectType") ?? 0) != 100) continue;
            var save = Read(affix, "saveData");
            var talent = Read(affix, "tTalentData")
                         ?? InvokeStatic("TableData", "getTTalentData", ReadNullableInt(save, "talentId") ?? 0);
            if ((ReadNullableInt(talent, "type") ?? 0) != 1) continue;
            var skillId = ReadNullableInt(talent, "skillId") ?? 0;
            if (skillId <= 0) continue;
            var key = $"extra-skill:{skillId}";
            var level = Math.Max(0, ReadNullableInt(save, "talentLevel") ?? 0);
            if (level <= 0) continue;
            result[key] = Math.Max(result.GetValueOrDefault(key), level);
        }
        return result;
    }

    private static IEnumerable<DeduplicatedEffectContribution> GetDeduplicatedEffectContributions(
        object item,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        var equipId = ReadNullableInt(Read(Read(item, "itemEquipData"), "tEquipData"), "id") ?? 0;
        var runewordAffix = GetRunewordAffix(item) is { } rawRuneword ? ResolveRuntimeAffix(rawRuneword) : null;
        foreach (var affix in CollectEquipmentAffixes(item).Concat(CollectGrantedMasteryAffixes(item)).Select(ResolveRuntimeAffix))
        {
            var definition = Read(affix, "tAffixData");
            var save = Read(affix, "saveData");
            var effectType = ReadNullableInt(definition, "effectType") ?? 0;
            string? key = null;
            var level = 1;
            if (effectType == 4)
            {
                var skillId = GetSkillVariantId(definition);
                var affixId = ReadNullableInt(definition, "id") ?? ReadNullableInt(save, "id") ?? 0;
                key = skillId > 0 ? $"skill-variant:{skillId}"
                    : affixId > 0 ? $"skill-variant-affix:{affixId}" : null;
            }
            else if (effectType == 100)
            {
                if (!NativeEquals(affix, runewordAffix)) continue;
                var talent = Read(affix, "tTalentData")
                             ?? InvokeStatic("TableData", "getTTalentData", ReadNullableInt(save, "talentId") ?? 0);
                if ((ReadNullableInt(talent, "type") ?? 0) != 1) continue;
                var skillId = ReadNullableInt(talent, "skillId") ?? 0;
                level = Math.Max(0, ReadNullableInt(save, "talentLevel") ?? 0);
                if (level <= 0) continue;
                if (skillId > 0) key = $"extra-skill:{skillId}";
            }
            if (key is null) continue;

            var direct = CountDirectAffixMatches(affix, profile, relevanceScope);
            var behavior = ScoreAffixBehavior(
                affix,
                equipId,
                profile,
                GetAffixSearchText(affix),
                relevanceScope);
            var value = Math.Max(0d, behavior);
            if (value > 0d || direct > 0)
                yield return new DeduplicatedEffectContribution(key, level, value, direct);
        }
    }

    private static IEnumerable<DeduplicatedEffectContribution> SelectEffectiveDeduplicatedEffects(
        IEnumerable<DeduplicatedEffectContribution> contributions)
        => contributions.GroupBy(entry => entry.Key, StringComparer.Ordinal).Select(group =>
            group.Key.StartsWith("extra-skill:", StringComparison.Ordinal)
                ? group.OrderByDescending(entry => entry.Level).ThenByDescending(entry => entry.Value).First()
                : group.OrderByDescending(entry => entry.Value).First());

    private static double ScoreSingleItemWithDeduplicatedEffects(
        object item,
        HeroEffectProfile profile,
        double rawScore,
        EffectRelevanceScope relevanceScope,
        IReadOnlyList<DeduplicatedEffectContribution>? cachedContributions = null)
    {
        var contributions = cachedContributions?.ToList()
                            ?? GetDeduplicatedEffectContributions(item, profile, relevanceScope).ToList();
        if (contributions.Count == 0) return rawScore;
        return rawScore - contributions.Sum(entry => entry.Value)
                        + SelectEffectiveDeduplicatedEffects(contributions).Sum(entry => entry.Value);
    }

    private static double ScoreItemsWithDeduplicatedEffects(
        IReadOnlyCollection<GearCandidate> items,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        var raw = items.Sum(item => item.Score);
        var perItemEffective = relevanceScope == EffectRelevanceScope.SelectableJointPlan
            ? items.SelectMany(item => SelectEffectiveDeduplicatedEffects(
                item.SelectableFacts.DeduplicatedContributions)).ToList()
            : items.SelectMany(item => SelectEffectiveDeduplicatedEffects(
                GetDeduplicatedEffectContributions(
                    item.Record.ItemData, profile, relevanceScope).ToList())).ToList();
        if (perItemEffective.Count == 0) return raw;
        return raw - perItemEffective.Sum(entry => entry.Value)
                   + SelectEffectiveDeduplicatedEffects(perItemEffective).Sum(entry => entry.Value);
    }

    private static int CountEffectiveDirectMatches(
        IReadOnlyCollection<GearCandidate> items,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        var raw = items.Sum(item => item.DirectMatches);
        var contributions = items.SelectMany(item => GetDeduplicatedEffectContributions(
            item.Record.ItemData, profile, relevanceScope)).ToList();
        return Math.Max(0, raw - contributions.Sum(entry => entry.DirectMatches)
                           + SelectEffectiveDeduplicatedEffects(contributions).Sum(entry => entry.DirectMatches));
    }

    private static string GetNonStackingEffectSignature(IEnumerable<string> keys)
    {
        var values = keys.OrderBy(value => value, StringComparer.Ordinal).ToArray();
        return values.Length == 0 ? "none" : string.Join("+", values);
    }

    private static HashSet<string> UnionEffectKeys(IEnumerable<string> left, IEnumerable<string> right)
    {
        var result = new HashSet<string>(left, StringComparer.Ordinal);
        result.UnionWith(right);
        return result;
    }

    private static object ResolveRuntimeAffix(object affix)
    {
        if (Read(affix, "tAffixData") is not null) return affix;
        var save = Read(affix, "saveData") ?? affix;
        return InvokeStaticMany("AffixData", "Create", save, true, -1) ?? affix;
    }

    private static string GetAffixSearchText(object affix)
    {
        var definition = Read(affix, "tAffixData");
        var ability = Read(affix, "tAbilityData");
        var talent = Read(affix, "tTalentData");
        var skill = ReadNullableInt(talent, "skillId") is > 0 and var skillId ? InvokeStatic("TableData", "getTSkillData", skillId) : null;
        var mastery = ReadNullableInt(talent, "masteryId") is > 0 and var masteryId ? InvokeStatic("TableData", "getTMasteryData", masteryId) : null;
        return Clean(string.Join(" ",
            InvokeString(affix, "GetDesc") ?? string.Empty,
            ReadString(definition, "des") ?? string.Empty, EnglishText(definition, "_des", string.Empty) ?? string.Empty,
            ReadString(ability, "name") ?? string.Empty, EnglishName(ability, string.Empty) ?? string.Empty, EnglishText(ability, "_des", string.Empty) ?? string.Empty,
            ReadString(talent, "name") ?? string.Empty, EnglishName(talent, string.Empty) ?? string.Empty,
            ReadString(skill, "name") ?? string.Empty, EnglishName(skill, string.Empty) ?? string.Empty,
            ReadString(mastery, "name") ?? string.Empty, EnglishName(mastery, string.Empty) ?? string.Empty));
    }

    private static int CountDirectAffixMatches(
        object affix,
        HeroEffectProfile profile,
        EffectRelevanceScope relevanceScope)
    {
        if (!IsAffixRelevantToProfile(affix, profile, relevanceScope)) return 0;
        var matched = false;
        var jobId = ReadNullableInt(Read(affix, "tHeroJobData"), "id") ?? 0;
        if (jobId > 0 && jobId != profile.JobId) return 0;
        var talent = Read(affix, "tTalentData");
        var talentId = ReadNullableInt(talent, "id") ?? 0;
        var skillId = ReadNullableInt(talent, "skillId") ?? 0;
        var masteryId = ReadNullableInt(talent, "masteryId") ?? 0;
        if ((talentId > 0 && profile.TalentIds.Contains(talentId))
            || (skillId > 0 && profile.SkillIds.Contains(skillId))
            || (masteryId > 0 && profile.MasteryIds.Contains(masteryId))) matched = true;
        var definition = Read(affix, "tAffixData");
        if ((ReadNullableInt(definition, "effectType") ?? 0) == 4)
        {
            var variantSkillId = GetSkillVariantId(definition);
            if (profile.SkillIds.Contains(variantSkillId)) matched = true;
        }
        return matched ? 1 : 0;
    }

    private static SkillVariantVerification VerifyEquippedSkillVariants(
        object hero,
        object talentData,
        string scope,
        IReadOnlySet<int>? requiredSkillIds = null)
    {
        var skills = ReadList(InvokeRequiredInstance(talentData, "GetSkillList")).ToList();
        // GetSkillList omits the separately selected base attack. Variant
        // affixes can target that skill too, so verify its live SkillData beside
        // the active list instead of reporting a false missing base variant.
        var baseSkill = InvokeRequiredInstance(hero, "GetNowBaseSkillData");
        if (baseSkill is not null) skills.Add(baseSkill);
        var available = skills.Select(skill => ReadNullableInt(Read(skill, "tSkillData"), "id") ?? 0)
            .Where(id => id > 0).ToHashSet();
        var actual = skills.Where(skill => ReadBool(Read(skill, "isVariant")))
            .Select(skill => ReadNullableInt(Read(skill, "tSkillData"), "id") ?? 0)
            .Where(id => id > 0).Distinct().ToList();
        var equippedTargets = GetGearSlots().Select(slot => GetEquippedItem(hero, slot.Part, slot.MainWeapon))
            .Where(item => item is not null).Cast<object>()
            .SelectMany(CollectEquipmentAffixes)
            .Select(ResolveRuntimeAffix)
            .Select(affix => Read(affix, "tAffixData"))
            .Where(definition => (ReadNullableInt(definition, "effectType") ?? 0) == 4)
            .Select(GetSkillVariantId)
            .Where(id => id > 0).Distinct().ToHashSet();
        // Gear verification can validate only variants for skills already present.
        // Auto Skills additionally supplies its complete joint target set, so a
        // selected variant item whose target skill failed to transform/learn is
        // reported as missing instead of disappearing from the expected set.
        var expected = equippedTargets
            .Where(id => available.Contains(id) || (requiredSkillIds?.Contains(id) ?? false))
            .ToHashSet();
        var missing = expected.Where(id => !actual.Contains(id)).ToList();
        var unexpected = actual.Where(id => !equippedTargets.Contains(id)).ToList();
        Plugin.DiagInfo($"{scope} VARIANTS|expected={string.Join(',', expected)}|actual={string.Join(',', actual)}|missing={string.Join(',', missing)}|unexpected={string.Join(',', unexpected)}");
        if (missing.Count > 0 || unexpected.Count > 0)
            Plugin.DiagWarning($"{scope} VARIANT MISMATCH|missing={string.Join(',', missing)}|unexpected={string.Join(',', unexpected)}");
        return new SkillVariantVerification(expected.OrderBy(id => id).ToList(), actual.OrderBy(id => id).ToList(), missing.OrderBy(id => id).ToList(), unexpected.OrderBy(id => id).ToList());
    }

    private static Dictionary<int, int> GetHeroAbilityCounts(object hero)
        => ReadList(Read(hero, "abilityList"))
            .Select(ability => ReadNullableInt(Read(ability, "tAbilityData"), "id")
                               ?? ReadNullableInt(ability, "id") ?? 0)
            .Where(id => id > 0)
            .GroupBy(id => id)
            .ToDictionary(group => group.Key, group => group.Count());

    private static Dictionary<int, int> GetVerifiedHeroAbilityCounts(object hero)
    {
        var counts = GetHeroAbilityCounts(hero);
        var knownSetEffectIds = GetSetEffectScoreRows().Values
            .SelectMany(effects => effects)
            .Select(effect => effect.EffectId)
            .Where(id => id > 0)
            .ToHashSet();
        var unverifiedActiveSetAbilities = ReadList(Read(Read(hero, "heroEquipData"), "activeSetsEffectList"))
            .Select(effect => Read(effect, "tSetEffectData") ?? effect)
            .Where(effect =>
            {
                var effectId = ReadNullableInt(effect, "id") ?? 0;
                return effectId > 0 && !knownSetEffectIds.Contains(effectId);
            })
            .Select(effect => ReadNullableInt(effect, "abilityId") ?? 0)
            .Where(id => id > 0)
            .GroupBy(id => id)
            .ToDictionary(group => group.Key, group => group.Count());
        foreach (var (abilityId, ignoredCount) in unverifiedActiveSetAbilities)
        {
            var remaining = Math.Max(0, counts.GetValueOrDefault(abilityId) - ignoredCount);
            if (remaining > 0) counts[abilityId] = remaining;
            else counts.Remove(abilityId);
        }
        return counts;
    }

    private static Dictionary<int, int> GetExpectedGearAbilityCounts(IEnumerable<object> sourceItems)
    {
        var items = sourceItems.ToList();
        var abilityIds = items
            .SelectMany(item => CollectEquipmentAffixes(item).Concat(CollectGrantedMasteryAffixes(item)))
            .Select(ResolveRuntimeAffix)
            .Where(affix => (ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0) == 3)
            .Select(affix => ReadNullableInt(Read(affix, "tAbilityData"), "id")
                             ?? ReadNullableInt(Read(affix, "saveData"), "abilityId") ?? 0)
            .Where(id => id > 0).ToList();
        foreach (var group in items.Where(item => GetNativeEquipmentSetId(item) > 0)
                     .GroupBy(GetNativeEquipmentSetId))
        {
            if (!GetSetEffectScoreRows().TryGetValue(group.Key, out var effects)) continue;
            var count = CountNativeEquippedSetPieces(group);
            abilityIds.AddRange(effects.Where(effect => effect.Pieces > 0 && effect.Pieces <= count)
                .Select(effect => effect.AbilityId).Where(id => id > 0));
        }
        return abilityIds.GroupBy(id => id).ToDictionary(group => group.Key, group => group.Count());
    }

    private static GearAbilityBaseline CaptureGearAbilityBaseline(object hero, IEnumerable<object> currentItems)
    {
        var actual = GetVerifiedHeroAbilityCounts(hero);
        var expectedGear = GetExpectedGearAbilityCounts(currentItems);
        var nonGear = new Dictionary<int, int>();
        foreach (var id in actual.Keys.Union(expectedGear.Keys))
        {
            var actualCount = actual.GetValueOrDefault(id);
            var gearCount = expectedGear.GetValueOrDefault(id);
            if (actualCount < gearCount)
                throw new InvalidOperationException($"Existing gear ability state is stale for {id} (hero {actualCount}, gear expected {gearCount}); no equipment was changed.");
            var baselineCount = actualCount - gearCount;
            if (baselineCount > 0) nonGear[id] = baselineCount;
        }
        Plugin.DiagInfo($"AUTO-GEAR ABILITY BASELINE|hero={actual.Values.Sum()}|oldGear={expectedGear.Values.Sum()}|nonGear={nonGear.Values.Sum()}");
        return new GearAbilityBaseline(nonGear);
    }

    private static GearEffectVerification VerifyCommittedGearEffects(
        object hero,
        object talentData,
        GearAbilityBaseline abilityBaseline,
        string scope,
        bool verifyStableNonGearAbilities = true)
    {
        var items = GetGearSlots().Select(slot => GetEquippedItem(hero, slot.Part, slot.MainWeapon))
            .Where(item => item is not null).Cast<object>().ToList();
        var expectedGearAbilityCounts = GetExpectedGearAbilityCounts(items);

        var expectedSetEffectIds = new List<int>();
        foreach (var group in items.Where(item => GetNativeEquipmentSetId(item) > 0)
                     .GroupBy(GetNativeEquipmentSetId))
        {
            if (!GetSetEffectScoreRows().TryGetValue(group.Key, out var effects)) continue;
            var count = CountNativeEquippedSetPieces(group);
            var active = effects.Where(effect => effect.Pieces > 0 && effect.Pieces <= count).ToList();
            expectedSetEffectIds.AddRange(active.Select(effect => effect.EffectId));
        }

        // During Auto Gear the hero's skills are unchanged, so the captured
        // non-gear baseline must remain exact. A combined Auto Build then
        // deliberately resets and reallocates talents; its legitimate skill
        // abilities can disappear, change level/family, or be replaced. In
        // that final phase verify that every equipped gear ability is present,
        // while set rows, extra talents, and skill variants are still checked
        // independently below. Requiring the pre-reset non-gear ability vector
        // there incorrectly rejects a valid skill rewrite.
        var expectedAbilityCounts = verifyStableNonGearAbilities
            ? new Dictionary<int, int>(abilityBaseline.NonGearCounts)
            : new Dictionary<int, int>();
        foreach (var (id, count) in expectedGearAbilityCounts)
            expectedAbilityCounts[id] = expectedAbilityCounts.GetValueOrDefault(id) + count;
        var actualAbilityCounts = GetVerifiedHeroAbilityCounts(hero);
        // Ability IDs encode their native level (for example one passive family
        // can advance from 9702 to 9704 after talent allocation). Compare the
        // stable TAbility.index family and multiplicity so a valid level upgrade
        // is not mistaken for one missing plus one unrelated ability.
        int AbilityFamily(int id)
        {
            var row = InvokeStatic("TableData", "getTAbilityData", id);
            var index = ReadNullableInt(row, "index") ?? 0;
            return index > 0 ? index : -id;
        }
        var expectedAbilityFamilies = expectedAbilityCounts
            .GroupBy(entry => AbilityFamily(entry.Key))
            .ToDictionary(group => group.Key, group => group.Sum(entry => entry.Value));
        var actualAbilityFamilies = actualAbilityCounts
            .GroupBy(entry => AbilityFamily(entry.Key))
            .ToDictionary(group => group.Key, group => group.Sum(entry => entry.Value));
        var abilityRows = expectedAbilityFamilies.Keys.Union(actualAbilityFamilies.Keys)
            .Select(id => (Id: id, Expected: expectedAbilityFamilies.GetValueOrDefault(id), Actual: actualAbilityFamilies.GetValueOrDefault(id)))
            .ToList();
        var missingAbilityRows = abilityRows
            .Where(entry => entry.Actual < entry.Expected)
            .ToList();
        var unexpectedAbilityRows = verifyStableNonGearAbilities
            ? abilityRows.Where(entry => entry.Actual > entry.Expected).ToList()
            : new List<(int Id, int Expected, int Actual)>();
        var missingAbilities = missingAbilityRows
            .Select(entry => $"{entry.Id}:{entry.Actual}/{entry.Expected}").ToList();
        var unexpectedAbilities = unexpectedAbilityRows
            .Select(entry => $"{entry.Id}:{entry.Actual}/{entry.Expected}").ToList();

        var expectedExtraTalents = items.SelectMany(CollectRunewordAffixes)
            .Select(ResolveRuntimeAffix)
            .Where(affix => (ReadNullableInt(Read(affix, "tAffixData"), "effectType") ?? 0) == 100)
            .Select(affix =>
            {
                var save = Read(affix, "saveData");
                var talent = Read(affix, "tTalentData")
                             ?? InvokeStatic("TableData", "getTTalentData", ReadNullableInt(save, "talentId") ?? 0);
                return (Id: ReadNullableInt(talent, "id") ?? ReadNullableInt(save, "talentId") ?? 0,
                    Level: Math.Max(0, ReadNullableInt(save, "talentLevel") ?? 0));
            })
            .Where(entry => entry.Id > 0 && entry.Level > 0).ToList();
        var actualExtraTalents = ReadList(Read(talentData, "extraTalentList"))
            .Where(talent => ReadBool(Read(talent, "isRuneWords")))
            .Select(talent => (Id: ReadNullableInt(Read(talent, "tTalentData"), "id") ?? 0,
                Level: GetSavedTalentLevel(talent)))
            .Where(entry => entry.Id > 0 && entry.Level > 0).ToList();
        var remainingActualExtra = actualExtraTalents.ToList();
        var missingExtraTalents = new List<string>();
        foreach (var expected in expectedExtraTalents.OrderByDescending(entry => entry.Level))
        {
            var index = remainingActualExtra.FindIndex(actual => actual.Id == expected.Id && actual.Level == expected.Level);
            if (index >= 0) remainingActualExtra.RemoveAt(index);
            else missingExtraTalents.Add($"{expected.Id}@{expected.Level}");
        }
        var unexpectedExtraTalents = remainingActualExtra.Select(entry => $"{entry.Id}@{entry.Level}").ToList();

        var verifiableSetEffectIds = GetSetEffectScoreRows().Values
            .SelectMany(effects => effects)
            .Select(effect => effect.EffectId)
            .Where(id => id > 0)
            .ToHashSet();
        var actualSetEffectIds = ReadList(Read(Read(hero, "heroEquipData"), "activeSetsEffectList"))
            .Select(effect => ReadNullableInt(Read(effect, "tSetEffectData"), "id") ?? 0)
            .Where(verifiableSetEffectIds.Contains).ToList();
        var missingSetEffects = expectedSetEffectIds.Where(id => !actualSetEffectIds.Contains(id)).Distinct().ToList();
        var unexpectedSetEffects = actualSetEffectIds.Where(id => !expectedSetEffectIds.Contains(id)).Distinct().ToList();
        Plugin.DiagInfo($"{scope} EFFECTS|abilityExact={actualAbilityCounts.Values.Sum()}/{expectedAbilityCounts.Values.Sum()}|newGearAbilities={expectedGearAbilityCounts.Values.Sum()}|extraTalents={expectedExtraTalents.Count - missingExtraTalents.Count}/{expectedExtraTalents.Count}|setEffects={expectedSetEffectIds.Count - missingSetEffects.Count}/{expectedSetEffectIds.Count}|missingAbilities={string.Join(',', missingAbilities)}|unexpectedAbilities={string.Join(',', unexpectedAbilities)}|missingExtra={string.Join(',', missingExtraTalents)}|unexpectedExtra={string.Join(',', unexpectedExtraTalents)}|missingSets={string.Join(',', missingSetEffects)}|unexpectedSets={string.Join(',', unexpectedSetEffects)}");
        if (missingAbilities.Count > 0 || unexpectedAbilities.Count > 0 || missingExtraTalents.Count > 0 || unexpectedExtraTalents.Count > 0
            || missingSetEffects.Count > 0 || unexpectedSetEffects.Count > 0)
            Plugin.DiagWarning($"{scope} EFFECT VERIFICATION FAILED|missingAbilities={string.Join(',', missingAbilities)}|unexpectedAbilities={string.Join(',', unexpectedAbilities)}|missingExtra={string.Join(',', missingExtraTalents)}|unexpectedExtra={string.Join(',', unexpectedExtraTalents)}|missingSets={string.Join(',', missingSetEffects)}|unexpectedSets={string.Join(',', unexpectedSetEffects)}");
        return new GearEffectVerification(missingAbilities, unexpectedAbilities, missingExtraTalents, unexpectedExtraTalents, missingSetEffects, unexpectedSetEffects);
    }

    private static object? GetEquippedItem(object hero, int part, bool main)
    {
        var partType = CreateEnum("EEquipPart", part);
        return partType is null ? null : InvokeInstance(hero, "GetEquipByPart", partType, main);
    }

    private static bool IsVerifiedHeroEquipField(object hero, object item, object destination)
    {
        if (!NativeEquals(Read(destination, "itemData"), item)) return false;
        var heroEquipData = Read(hero, "heroEquipData");
        var belongsToHero = heroEquipData is not null
                            && ReadList(Read(heroEquipData, "fieldList"))
                                .Any(field => NativeEquals(field, destination));
        if (!belongsToHero) return false;

        // `ownerHeroData` and ItemSys' reverse lookup are derived caches. The
        // game can update them a frame after MoveItem even though the exact
        // target field (from this hero's own fieldList) already owns the item.
        // Treating both caches as hard postconditions caused a successful swap
        // to be retried and then rolled back. Keep them as diagnostics while the
        // structural field membership + exact item pointer remain authoritative.
        var ownerMatches = NativeEquals(Read(item, "ownerHeroData"), hero);
        var reverseLookupMatches = NativeEquals(
            InvokeStatic("ItemSys", "FindHeroEquipFieldByItem", item), destination);
        if (!ownerMatches || !reverseLookupMatches)
            Plugin.DiagDebug(
                $"AUTO-GEAR DERIVED OWNERSHIP LAG|owner={ownerMatches}|reverseLookup={reverseLookupMatches}|item={NativeObjectKey(item, item)}");
        return true;
    }

    private static bool TryEquipCandidate(object hero, GearCandidate candidate, GearSlot slot, object? seasonData, List<MoveReceipt> moveJournal, IReadOnlyCollection<object> targetItems, IReadOnlyCollection<object> treasureTargetItems, out int moveCode, out string failure)
    {
        moveCode = int.MinValue;
        failure = string.Empty;
        var item = candidate.Record.ItemData;
        var destination = GetEquipDestinationField(hero, slot);
        if (destination is null)
        {
            failure = "target equip field was not found";
            return false;
        }
        if (NativeEquals(Read(destination, "itemData"), item))
        {
            moveCode = 0;
            if (IsVerifiedHeroEquipField(hero, item, destination)) return true;
            failure = "the item pointer is present, but hero ownership verification failed";
            return false;
        }

        var source = InvokeStatic("ItemSys", "FindHeroEquipFieldByItem", item)
                     ?? InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", item);
        source ??= FindTrackedItemField(item, moveJournal);
        if (source is null && candidate.Record.StorageSource == StorageSource.Warehouse
            && candidate.Record.SourceField is not null
            && NativeEquals(Read(candidate.Record.SourceField, "itemData"), item))
        {
            // Store fields can be swapped directly with an exact hero field. This
            // preserves the native store/equip events and does not require a free
            // bag slot for every warehouse candidate.
            source = candidate.Record.SourceField;
        }
        if (source is null)
        {
            if (!TryMoveCandidateToBag(candidate.Record, seasonData, moveJournal))
            {
                failure = "item could not be moved from storage or Vault to the bag";
                return false;
            }
            source = InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", item);
        }
        if (source is null)
        {
            failure = "source field was not found after moving the item to the bag";
            return false;
        }
        if (NativeEquals(source, destination))
        {
            moveCode = 0;
            if (IsVerifiedHeroEquipField(hero, item, destination)) return true;
            failure = "the source and destination match, but hero ownership verification failed";
            return false;
        }
        var sourceWasBag = NativeEquals(InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", item), source);

        var heroEquipData = Read(hero, "heroEquipData") ?? throw new InvalidOperationException("Hero equipment data is unavailable.");
        var validation = ToInt(InvokeRequiredInstance(heroEquipData, "CheckAddItem", source, destination));
        if (validation is not (0 or -2))
        {
            moveCode = validation;
            failure = MoveItemFailure(validation);
            return false;
        }

        var beforeFrom = Read(source, "itemData");
        var beforeTo = Read(destination, "itemData");
        if (!NativeEquals(beforeFrom, item))
        {
            failure = "the source field changed before the move could be applied";
            return false;
        }
        var rawResult = InvokeRequiredStaticMany("ItemSys", "MoveItem", source, destination);
        moveCode = rawResult is null ? int.MinValue : ToInt(rawResult);
        var destinationMatches = NativeEquals(Read(destination, "itemData"), item);
        var sourceMatches = NativeStateEquals(Read(source, "itemData"), beforeTo);
        if (destinationMatches && sourceMatches)
            moveJournal.Add(new MoveReceipt(MoveReceiptKind.FieldMove, source, destination, beforeFrom!, beforeTo));
        if (destinationMatches && sourceMatches && IsVerifiedHeroEquipField(hero, item, destination))
        {
            var needsTreasureBagSpace = treasureTargetItems.Any(target => InvokeStatic("ItemSys", "FindHeroEquipFieldByItem", target) is null
                && InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", target) is null);
            if (sourceWasBag && beforeTo is not null && needsTreasureBagSpace
                && FindEmptyEquipmentBagField(seasonData) is null
                && !targetItems.Any(target => NativeEquals(target, beforeTo))
                && !TryClearBridgeBagField(source, beforeTo, seasonData, moveJournal, out failure))
            {
                return false;
            }
            return true;
        }

        failure = destinationMatches && !sourceMatches
            ? "the destination changed, but the source swap did not match"
            : destinationMatches
            ? "the destination changed, but hero ownership verification failed"
            : MoveItemFailure(moveCode);
        return false;
    }

    private static object? FindTrackedItemField(object item, List<MoveReceipt> moveJournal)
    {
        for (var index = moveJournal.Count - 1; index >= 0; index--)
        {
            var receipt = moveJournal[index];
            if (receipt.Kind != MoveReceiptKind.FieldMove || receipt.FromField is null || receipt.ToField is null) continue;
            if (NativeEquals(Read(receipt.FromField, "itemData"), item)) return receipt.FromField;
            if (NativeEquals(Read(receipt.ToField, "itemData"), item)) return receipt.ToField;
        }
        return null;
    }

    private static bool TryClearBridgeBagField(object bagField, object outgoingItem, object? seasonData, List<MoveReceipt> moveJournal, out string failure)
    {
        failure = string.Empty;
        if (!NativeEquals(Read(bagField, "itemData"), outgoingItem))
        {
            failure = "the bridge bag field no longer contains the outgoing equipment";
            return false;
        }
        var houseStoreData = ReadValues(Read(Read(seasonData, "townData"), "houseDic"))
            .Select(house => Read(house, "houseStoreData")).FirstOrDefault(store => Read(store, "storeBaseData") is not null);
        var storeBaseData = Read(houseStoreData, "storeBaseData");
        var emptyStoreField = storeBaseData is null ? null : InvokeRequiredInstance(storeBaseData, "QuickPutItemToField", outgoingItem);
        if (emptyStoreField is null || Read(emptyStoreField, "itemData") is not null)
        {
            failure = "no empty warehouse field is available for reversible bag staging";
            return false;
        }
        var moveCode = ToInt(InvokeRequiredStaticMany("ItemSys", "MoveItem", bagField, emptyStoreField));
        if (Read(bagField, "itemData") is null && NativeEquals(Read(emptyStoreField, "itemData"), outgoingItem))
        {
            moveJournal.Add(new MoveReceipt(MoveReceiptKind.FieldMove, bagField, emptyStoreField, outgoingItem, null));
            return true;
        }
        failure = MoveItemFailure(moveCode);
        return false;
    }

    private static object? FindEmptyEquipmentBagField(object? seasonData)
    {
        // ItemSys.FindEmptyLordInventoryField can fail to return when the bag is
        // at its capacity boundary. Enumerating the authoritative equipment
        // fields has no allocation side effect and lets the caller name the
        // exact reversible bridge field instead.
        Plugin.DiagInfo(
            $"AUTO-GEAR BAG FIELD|stage=request|mainThread={MainThreadNativeGateway.IsMainThread}|operation={MainThreadNativeGateway.CurrentWorkerOperation is not null}");
        return MainThreadNativeGateway.Invoke(() =>
        {
            Plugin.DiagInfo("AUTO-GEAR BAG FIELD|stage=execute");
            var lordData = Read(seasonData, "lordData");
            Plugin.DiagInfo("AUTO-GEAR BAG FIELD|stage=lord");
            var bagData = Read(lordData, "lordBagData");
            var equipmentType = CreateEnum("EItemType", 2);
            Plugin.DiagInfo("AUTO-GEAR BAG FIELD|stage=bag-and-type");
            if (bagData is null || equipmentType is null) return null;
            var fields = InvokeRequiredInstance(bagData, "GetFieldList", equipmentType);
            Plugin.DiagInfo("AUTO-GEAR BAG FIELD|stage=fields");
            var empty = ReadList(fields).FirstOrDefault(field => Read(field, "itemData") is null);
            Plugin.DiagInfo($"AUTO-GEAR BAG FIELD|stage=complete|empty={empty is not null}");
            return empty;
        });
    }

    private static int CountEmptyWarehouseEquipmentFields(object? seasonData)
    {
        var houseStoreData = ReadValues(Read(Read(seasonData, "townData"), "houseDic"))
            .Select(house => Read(house, "houseStoreData"))
            .FirstOrDefault(store => Read(store, "storeBaseData") is not null);
        var storeBaseData = Read(houseStoreData, "storeBaseData");
        if (storeBaseData is null) return 0;
        return ReadEntries(Read(storeBaseData, "storeDic"))
            .Select(entry => Read(entry, "Value"))
            .Where(page => page is not null)
            .SelectMany(ReadList)
            .Count(field => Read(field, "itemData") is null);
    }

    private static bool IsVaultRoutedItem(object item, object? seasonData)
    {
        var houseStoreData = ReadValues(Read(Read(seasonData, "townData"), "houseDic"))
            .Select(house => Read(house, "houseStoreData")).FirstOrDefault(store => Read(store, "storeTreaData") is not null);
        var treasureData = Read(houseStoreData, "storeTreaData");
        return treasureData is not null && ReadBool(InvokeRequiredInstance(treasureData, "IsTreasureEquip", item));
    }

    private static bool TryFindEquipmentStorageLocation(
        object item,
        object? seasonData,
        out StorageSource storageSource,
        out object? sourceField,
        out object? groupData)
    {
        // Storage lookup can inspect thousands of Vault entries. During the
        // exclusive mutation phase the gateway deliberately executes only one
        // queued work item per frame, so issuing one work item per property made
        // post-commit cleanup appear hung. Keep this read-only scan atomic and
        // return only the three native references needed by the caller.
        var result = MainThreadNativeGateway.Invoke(() =>
        {
            var found = TryFindEquipmentStorageLocationCore(
                item, seasonData, out var nativeSource,
                out var nativeField, out var nativeGroup);
            return (Found: found, Source: nativeSource,
                Field: nativeField, Group: nativeGroup);
        });
        storageSource = result.Source;
        sourceField = result.Field;
        groupData = result.Group;
        return result.Found;
    }

    private static bool TryFindEquipmentStorageLocationCore(
        object item,
        object? seasonData,
        out StorageSource storageSource,
        out object? sourceField,
        out object? groupData)
    {
        storageSource = StorageSource.Inventory;
        sourceField = null;
        groupData = null;

        var lordData = Read(seasonData, "lordData");
        var bagData = Read(lordData, "lordBagData");
        var equipmentType = CreateEnum("EItemType", 2);
        if (bagData is not null && equipmentType is not null)
        {
            foreach (var field in ReadList(InvokeRequiredInstance(
                         bagData, "GetFieldList", equipmentType)))
            {
                if (!NativeEquals(Read(field, "itemData"), item)) continue;
                storageSource = StorageSource.Inventory;
                sourceField = field;
                return true;
            }
        }

        var houseStoreData = ReadValues(Read(Read(seasonData, "townData"), "houseDic"))
            .Select(house => Read(house, "houseStoreData"))
            .FirstOrDefault(store => Read(store, "storeBaseData") is not null
                                     || Read(store, "storeTreaData") is not null);
        var storeBaseData = Read(houseStoreData, "storeBaseData");
        foreach (var page in ReadEntries(Read(storeBaseData, "storeDic"))
                     .Select(entry => Read(entry, "Value"))
                     .Where(page => page is not null))
        {
            foreach (var field in ReadList(page))
            {
                if (!NativeEquals(Read(field, "itemData"), item)) continue;
                storageSource = StorageSource.Warehouse;
                sourceField = field;
                return true;
            }
        }

        var treasureData = Read(houseStoreData, "storeTreaData");
        foreach (var groupList in ReadValues(Read(treasureData, "equipGroupDic")))
        foreach (var group in ReadList(groupList))
        {
            if (!ReadList(Read(group, "equipList")).Any(candidate =>
                    NativeEquals(candidate, item))) continue;
            storageSource = StorageSource.Treasure;
            groupData = group;
            return true;
        }
        return false;
    }

    private static object? GetEquipDestinationField(object hero, GearSlot slot)
    {
        var equipData = Read(hero, "heroEquipData");
        var fields = ReadList(Read(equipData, "fieldList")).ToList();
        if (slot.Part == 1)
        {
            // This is the exact native contract used by HeroData.GetEquipByPart:
            // raw field 0 is main and raw field 1 is secondary.
            var weaponField = fields.ElementAtOrDefault(slot.MainWeapon ? 0 : 1);
            return (ReadNullableInt(Read(weaponField, "tEquipFieldData"), "part") ?? 0) == 1 ? weaponField : null;
        }
        return fields.FirstOrDefault(field => (ReadNullableInt(Read(field, "tEquipFieldData"), "part") ?? 0) == slot.Part);
    }

    private static string MoveItemFailure(int code) => code switch
    {
        -2 => "swap was rejected before the destination changed",
        0 => "the game returned success but the destination did not change",
        1 => "the item or destination is invalid",
        2 => "the item does not match this equipment slot",
        6 => "the hero's Mythic equipment limit would be exceeded",
        7 => "the two Legendary/Mythic weapons conflict",
        int.MinValue => "the game did not return a move result",
        _ => $"the game rejected the move (code {code})"
    };

    private static bool TryStageEquippedItem(
        object hero,
        GearSlot slot,
        object? seasonData,
        List<MoveReceipt> moveJournal,
        bool preserveBagSpace,
        out string failure)
    {
        failure = string.Empty;
        var source = GetEquipDestinationField(hero, slot);
        var oldItem = Read(source, "itemData");
        if (source is null || oldItem is null)
        {
            failure = "the equipment slot is already empty";
            return false;
        }

        object? TryEmptyWarehouseField()
        {
            var houseStoreData = ReadValues(Read(Read(seasonData, "townData"), "houseDic"))
                .Select(house => Read(house, "houseStoreData")).FirstOrDefault(store => Read(store, "storeBaseData") is not null);
            var storeBaseData = Read(houseStoreData, "storeBaseData");
            return storeBaseData is null
                ? null
                : InvokeRequiredInstance(storeBaseData, "QuickPutItemToField", oldItem);
        }

        // Vault extraction needs a bag bridge. Prefer Warehouse staging in that
        // case; otherwise use the bag first. Fall back to the other reversible
        // lane when the preferred one is full.
        var stagingField = preserveBagSpace
            ? TryEmptyWarehouseField()
            : FindEmptyEquipmentBagField(seasonData);
        stagingField ??= preserveBagSpace
            ? FindEmptyEquipmentBagField(seasonData)
            : TryEmptyWarehouseField();
        if (stagingField is null || Read(stagingField, "itemData") is not null)
        {
            failure = "no empty bag or warehouse field is available to stage outgoing equipment";
            return false;
        }
        var beforeTo = Read(stagingField, "itemData");
        var code = ToInt(InvokeRequiredStaticMany("ItemSys", "MoveItem", source, stagingField));
        if (Read(source, "itemData") is null && beforeTo is null
            && NativeEquals(Read(stagingField, "itemData"), oldItem))
        {
            moveJournal.Add(new MoveReceipt(MoveReceiptKind.FieldMove, source, stagingField, oldItem, null));
            return true;
        }
        failure = MoveItemFailure(code);
        return false;
    }

    private static int NormalizeCommittedStorage(List<MoveReceipt> moveJournal, object? seasonData, IReadOnlyCollection<object> targetItems)
    {
        var failures = 0;
        var houseStoreData = ReadValues(Read(Read(seasonData, "townData"), "houseDic"))
            .Select(house => Read(house, "houseStoreData")).FirstOrDefault(store => Read(store, "storeTreaData") is not null);
        var treasureData = Read(houseStoreData, "storeTreaData");
        var handled = new HashSet<string>(StringComparer.Ordinal);

        // Bridge/conflict staging moves BeforeFromItem into an empty bag or
        // Warehouse field. After all eight targets are verified, route every
        // staged non-target through the configured keep policy: Vault-eligible
        // gear goes to Vault and every other sellable item is sold immediately.
        // Ordinary Warehouse is never the final destination for discarded gear.
        foreach (var staged in moveJournal.Where(receipt => receipt.Kind == MoveReceiptKind.FieldMove)
                     .Select(receipt => receipt.BeforeFromItem)
                     .Where(item => !targetItems.Any(target => NativeEquals(target, item))))
            NormalizeItem(staged, includeBag: true);

        // A direct Warehouse-to-hero swap leaves BeforeToItem in the original
        // Warehouse field. Move it to Vault when eligible; otherwise sell that
        // exact field item immediately.
        foreach (var outgoing in moveJournal.Where(receipt => receipt.Kind == MoveReceiptKind.FieldMove
                     && receipt.BeforeToItem is not null)
                     .Select(receipt => receipt.BeforeToItem!)
                     .Where(item => !targetItems.Any(target => NativeEquals(target, item))))
            NormalizeItem(outgoing, includeBag: false);

        return failures;

        void NormalizeItem(object item, bool includeBag)
        {
            var key = NativeObjectKey(item, item);
            if (handled.Contains(key)) return;

            var bagField = InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", item);
            if (bagField is not null)
            {
                if (!includeBag) return;
                handled.Add(key);
                var vaultRouted = IsVaultRoutedItem(item, seasonData);
                if (!vaultRouted)
                {
                    if (TrySellNormalizationFallback(item, key, bagField))
                    {
                        Plugin.DiagInfo(
                            $"AUTO-GEAR STORAGE NORMALIZED|item={key}|destination=Sold|policy=non-vault");
                    }
                    else
                    {
                        failures++;
                        Plugin.DiagWarning(
                            $"AUTO-GEAR STORAGE NORMALIZE FAILED|item={key}|non-Vault outgoing gear could not be sold from the bag");
                    }
                    return;
                }
                try
                {
                    InvokeRequiredStaticMany("ItemSys", "QuickMoveItemFromBagToStore", item);
                    if (InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", item) is not null)
                        throw new InvalidOperationException("native storage normalization left the staged item in the bag");
                    var foundDestination = TryFindEquipmentStorageLocation(
                        item, seasonData, out var destination, out _, out _);
                    if (!foundDestination || destination != StorageSource.Treasure)
                        throw new InvalidOperationException("native storage normalization used an unexpected destination");
                    Plugin.DiagInfo($"AUTO-GEAR STORAGE NORMALIZED|item={key}|destination={destination}");
                }
                catch (Exception error)
                {
                    if (TrySellNormalizationFallback(item, key, bagField))
                    {
                        Plugin.DiagInfo(
                            $"AUTO-GEAR STORAGE NORMALIZED|item={key}|destination=Sold|vaultFallback={error.GetBaseException().Message}");
                    }
                    else
                    {
                        failures++;
                        Plugin.DiagWarning($"AUTO-GEAR STORAGE NORMALIZE FAILED|item={key}|{error.GetBaseException().Message}");
                    }
                }
                return;
            }

            if (!TryFindEquipmentStorageLocation(
                    item, seasonData, out var storageSource, out var storageField, out _)
                || storageSource is not (StorageSource.Warehouse or StorageSource.Treasure))
            {
                handled.Add(key);
                failures++;
                Plugin.DiagWarning($"AUTO-GEAR STORAGE NORMALIZE FAILED|item={key}|staged item was not found in bag, Warehouse, or Vault");
                return;
            }
            handled.Add(key);
            if (storageSource == StorageSource.Treasure) return;
            if (!IsVaultRoutedItem(item, seasonData))
            {
                if (TrySellNormalizationFallback(item, key, storageField))
                {
                    Plugin.DiagInfo(
                        $"AUTO-GEAR STORAGE NORMALIZED|item={key}|destination=Sold|policy=non-vault");
                }
                else
                {
                    failures++;
                    Plugin.DiagWarning(
                        $"AUTO-GEAR STORAGE NORMALIZE FAILED|item={key}|non-Vault outgoing gear could not be sold from Warehouse");
                }
                return;
            }
            try
            {
                if (treasureData is null || storageField is null)
                    throw new InvalidOperationException("Vault or Warehouse field is unavailable for native normalization");
                InvokeRequiredInstance(treasureData, "TryAddEquip", storageField, false);
                var movedToVault = TryFindEquipmentStorageLocation(
                    item, seasonData, out var movedDestination, out _, out _)
                                   && movedDestination == StorageSource.Treasure;
                if (!movedToVault)
                    throw new InvalidOperationException("native Vault normalization did not move the item");
                Plugin.DiagInfo($"AUTO-GEAR STORAGE NORMALIZED|item={key}|destination=Vault");
            }
            catch (Exception error)
            {
                if (TrySellNormalizationFallback(item, key, storageField))
                {
                    Plugin.DiagInfo(
                        $"AUTO-GEAR STORAGE NORMALIZED|item={key}|destination=Sold|vaultFallback={error.GetBaseException().Message}");
                }
                else
                {
                    failures++;
                    Plugin.DiagWarning($"AUTO-GEAR STORAGE NORMALIZE FAILED|item={key}|{error.GetBaseException().Message}");
                }
            }
        }

        bool TrySellNormalizationFallback(object item, string key, object? preferredField)
        {
            // Vault-full/non-eligible outgoing gear must not be recovered into a
            // full bag or left occupying ordinary Warehouse. Resolve only this
            // exact item and use the same one-at-a-time verified sale path as
            // box routing and Warehouse maintenance.
            object? exactField = preferredField is not null
                                 && NativeEquals(Read(preferredField, "itemData"), item)
                ? preferredField
                : null;
            if (exactField is null)
            {
                var bagCandidate = InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", item);
                if (bagCandidate is not null
                    && NativeEquals(Read(bagCandidate, "itemData"), item))
                    exactField = bagCandidate;
            }
            if (exactField is null
                && TryFindEquipmentStorageLocation(
                    item, seasonData, out var location, out var storageCandidate, out _))
            {
                if (location == StorageSource.Treasure) return true;
                if (location == StorageSource.Warehouse && storageCandidate is not null
                    && NativeEquals(Read(storageCandidate, "itemData"), item))
                    exactField = storageCandidate;
            }
            if (exactField is null
                || !ReadBool(Read(Read(item, "tItemData"), "isSell"))) return false;

            var saleKnown = new HashSet<string>(StringComparer.Ordinal);
            var saleFailed = new HashSet<string>(StringComparer.Ordinal);
            var sale = SellExactEquipmentFromSource(
                saleKnown,
                saleFailed,
                new InventoryEquipment(key, item, exactField));
            if (sale.Sold == 1 && !sale.Uncertain
                               && string.IsNullOrWhiteSpace(sale.Error)) return true;
            Plugin.DiagWarning(
                $"AUTO-GEAR STORAGE SELL FALLBACK FAILED|item={key}|uncertain={sale.Uncertain}|error={sale.Error ?? string.Empty}");
            return false;
        }
    }

    private static GearRollbackStatus RollbackUncommittedCombinedGear(
        object hero,
        object? talentData,
        List<MoveReceipt> moveJournal,
        string originalGearFingerprint,
        GearAbilityBaseline? abilityBaseline)
    {
        var failures = new List<string>();
        var reverseMoveRollback = new MoveJournalRollbackResult(0, 0);
        try
        {
            reverseMoveRollback = RollbackMoveJournal(moveJournal);
            if (reverseMoveRollback.Failures > 0)
                failures.Add($"reverse moves {reverseMoveRollback.Failures}");
        }
        catch (Exception error)
        {
            reverseMoveRollback = new MoveJournalRollbackResult(
                Math.Max(1, moveJournal.Count), reverseMoveRollback.VaultRelocations);
            failures.Add($"reverse move rollback: {error.GetBaseException().Message}");
        }

        if (talentData is null)
        {
            failures.Add("talent data unavailable");
        }
        else
        {
            try
            {
                // Native reverse equipment moves restore affix/set abilities.
                // Rebuild the separate skill-variant projection only after all
                // fields are back in their original slots.
                InvokeRequiredInstance(talentData, "ReapplySkillVariantsFromEquippedItems");
            }
            catch (Exception error)
            {
                failures.Add($"variant refresh: {error.GetBaseException().Message}");
            }
        }

        var fingerprintRestored = false;
        try
        {
            fingerprintRestored = string.Equals(
                GetCurrentGearFingerprint(hero),
                originalGearFingerprint,
                StringComparison.Ordinal);
            if (!fingerprintRestored) failures.Add("original equipment fingerprint mismatch");
        }
        catch (Exception error)
        {
            failures.Add($"fingerprint verification: {error.GetBaseException().Message}");
        }

        if (fingerprintRestored)
        {
            if (talentData is null || abilityBaseline is null)
            {
                failures.Add("effect baseline unavailable");
            }
            else
            {
                try
                {
                    if (!VerifyCommittedGearEffects(hero, talentData, abilityBaseline, "AUTO-GEAR-ROLLBACK").IsVerified)
                        failures.Add("original equipment effects mismatch");
                }
                catch (Exception error)
                {
                    failures.Add($"effect verification: {error.GetBaseException().Message}");
                }
            }
        }

        var recovered = reverseMoveRollback.Failures == 0
                        && fingerprintRestored && failures.Count == 0;
        var exact = recovered && reverseMoveRollback.VaultRelocations == 0;
        var detail = exact
            ? "exact"
            : recovered
                ? $"hero equipment restored; {reverseMoveRollback.VaultRelocations} extracted Vault item(s) preserved in ordinary Warehouse"
                : string.Join("; ", failures.Distinct(StringComparer.Ordinal));
        Plugin.DiagInfo($"AUTO-GEAR COMBINED ROLLBACK|exact={exact}|recovered={recovered}|vaultRelocations={reverseMoveRollback.VaultRelocations}|detail={detail}");
        return new GearRollbackStatus(
            exact, recovered, reverseMoveRollback.VaultRelocations, detail);
    }

    private static string DescribeGearRollbackStorage(GearRollbackStatus rollback)
        => rollback.VaultRelocations <= 0
            ? string.Empty
            : UiText.L(
                $" · 꺼낸 Vault 장비 {rollback.VaultRelocations}개는 일반 창고에 보존",
                $" · {rollback.VaultRelocations} extracted Vault item(s) preserved in ordinary Warehouse",
                $" · {rollback.VaultRelocations} 件已取出的宝库装备保存在普通仓库",
                $" · {rollback.VaultRelocations} 件已取出的寶庫裝備保存在普通倉庫");

    private static MoveJournalRollbackResult RollbackMoveJournal(List<MoveReceipt> moveJournal)
    {
        if (moveJournal.Count > 0)
            ReportAutoBuildProgress(AutoBuildStep.RollingBack, 0, moveJournal.Count);
        var failures = 0;
        var vaultRelocations = 0;
        var receiptCount = moveJournal.Count;
        for (var index = moveJournal.Count - 1; index >= 0; index--)
        {
            var receipt = moveJournal[index];
            ReportAutoBuildProgress(
                AutoBuildStep.RollingBack,
                receiptCount - index - 1,
                receiptCount,
                $"reverse {receipt.Kind} receipt {receiptCount - index}/{receiptCount}");
            try
            {
                if (receipt.Kind == MoveReceiptKind.BagToVault)
                {
                    if (receipt.FromField is null || receipt.TreasureData is null || receipt.GroupData is null
                        || Read(receipt.FromField, "itemData") is not null
                        || !IsItemInVaultGroup(receipt.BeforeFromItem, receipt.GroupData))
                        throw new InvalidOperationException("Vault deposit state no longer matches the recorded move");
                    InvokeRequiredStaticMany("ItemSys", "QuickMoveTreasureEquipToBag", receipt.GroupData, receipt.BeforeFromItem);
                    var actualBagField = InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", receipt.BeforeFromItem)
                                         ?? throw new InvalidOperationException("returned Vault item was not found in the bag");
                    if (!NativeEquals(actualBagField, receipt.FromField))
                    {
                        if (Read(receipt.FromField, "itemData") is not null)
                            throw new InvalidOperationException("original bridge bag field is no longer empty");
                        InvokeRequiredStaticMany("ItemSys", "MoveItem", actualBagField, receipt.FromField);
                    }
                    if (!NativeEquals(Read(receipt.FromField, "itemData"), receipt.BeforeFromItem))
                        throw new InvalidOperationException("Vault deposit reverse move did not restore the bag field");
                    continue;
                }
                if (receipt.Kind == MoveReceiptKind.VaultToBag)
                {
                    // Reinserting several extracted items into Vault can block
                    // the game's main thread. Preserve the exact item through a
                    // normal field-to-field move into the preflighted ordinary
                    // Warehouse rollback lane; hero equipment remains exactly
                    // reversible and no item is lost.
                    if (receipt.ToField is null || receipt.TreasureData is null
                        || !NativeEquals(Read(receipt.ToField, "itemData"), receipt.BeforeFromItem))
                        throw new InvalidOperationException(
                            "extracted Vault item is no longer in its recorded bag field");
                    var houseStoreData = Read(receipt.TreasureData, "houseStoreData")
                                         ?? throw new InvalidOperationException(
                                             "Vault house storage data is unavailable during rollback");
                    var storeBaseData = Read(houseStoreData, "storeBaseData")
                                        ?? throw new InvalidOperationException(
                                            "ordinary Warehouse data is unavailable during Vault rollback");
                    var rollbackField = InvokeRequiredInstance(
                        storeBaseData, "QuickPutItemToField", receipt.BeforeFromItem)
                                        ?? throw new InvalidOperationException(
                                            "no ordinary Warehouse rollback field is available");
                    if (Read(rollbackField, "itemData") is not null)
                        throw new InvalidOperationException(
                            "selected ordinary Warehouse rollback field is not empty");
                    InvokeRequiredStaticMany(
                        "ItemSys", "MoveItem", receipt.ToField, rollbackField);
                    if (Read(receipt.ToField, "itemData") is not null
                        || !NativeEquals(Read(rollbackField, "itemData"), receipt.BeforeFromItem))
                        throw new InvalidOperationException(
                            "Vault rollback item was not preserved in ordinary Warehouse");
                    vaultRelocations++;
                    Plugin.DiagWarning(
                        $"AUTO-GEAR VAULT ROLLBACK RELOCATED|item={NativeObjectKey(receipt.BeforeFromItem, receipt.BeforeFromItem)}|destination=Warehouse");
                    continue;
                }

                if (receipt.FromField is null || receipt.ToField is null
                    || !NativeStateEquals(Read(receipt.ToField, "itemData"), receipt.BeforeFromItem)
                    || !NativeStateEquals(Read(receipt.FromField, "itemData"), receipt.BeforeToItem))
                    throw new InvalidOperationException("field state no longer matches the recorded move");
                InvokeRequiredStaticMany("ItemSys", "MoveItem", receipt.ToField, receipt.FromField);
                if (!NativeStateEquals(Read(receipt.FromField, "itemData"), receipt.BeforeFromItem)
                    || !NativeStateEquals(Read(receipt.ToField, "itemData"), receipt.BeforeToItem))
                    throw new InvalidOperationException("reverse move did not restore both fields");
            }
            catch (Exception error)
            {
                failures++;
                Plugin.DiagWarning($"AUTO-GEAR ROLLBACK FAILED|index={index}|reason={error.GetBaseException().Message}");
            }
            finally
            {
                ReportAutoBuildProgress(
                    AutoBuildStep.RollingBack,
                    receiptCount - index,
                    receiptCount);
            }
        }
        if (receiptCount > 0)
            Plugin.DiagInfo($"AUTO-GEAR ROLLBACK|moves={receiptCount}|failures={failures}");
        moveJournal.Clear();
        return new MoveJournalRollbackResult(failures, vaultRelocations);
    }

    private static bool IsItemInVaultGroup(object item, object expectedGroup)
    {
        // The caller already owns the authoritative Vault group reference.
        // Rebuilding every translated search record here made a single take (and
        // Auto Build rollback) scale with the user's entire 1,000+ item stash.
        // Inspect only that group's native equipment list in one main-thread hop.
        return MainThreadNativeGateway.Invoke(() =>
            ReadList(Read(expectedGroup, "equipList")).Any(candidate =>
                NativeEquals(candidate, item)));
    }

    private static bool TryMoveCandidateToBag(ItemSearchRecord record, object? seasonData, List<MoveReceipt> moveJournal)
    {
        if (InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", record.ItemData) is not null) return true;
        if (record.StorageSource == StorageSource.Equipped)
            return InvokeStatic("ItemSys", "FindHeroEquipFieldByItem", record.ItemData) is not null;
        if (record.StorageSource == StorageSource.Warehouse)
        {
            if (record.SourceField is null || !NativeEquals(Read(record.SourceField, "itemData"), record.ItemData)) return false;
            InvokeRequiredStaticMany("ItemSys", "QuickMoveItemFromStoreToBag", record.ItemData);
            var bagField = InvokeStatic("ItemSys", "FindLordInventoryFieldByItem", record.ItemData);
            if (bagField is null || Read(record.SourceField, "itemData") is not null) return false;
            moveJournal.Add(new MoveReceipt(MoveReceiptKind.FieldMove, record.SourceField, bagField, record.ItemData, null));
            return true;
        }
        var houseStoreData = ReadValues(Read(Read(seasonData, "townData"), "houseDic"))
            .Select(house => Read(house, "houseStoreData")).FirstOrDefault(store => Read(store, "storeTreaData") is not null);
        var treasure = Read(houseStoreData, "storeTreaData");
        if (treasure is null || record.GroupData is null) return false;
        var knownEmptyBagField = FindEmptyEquipmentBagField(seasonData);
        if (knownEmptyBagField is null) return false;
        // Avoid ItemSys.FindEmptyLordInventoryField and the interactive Vault
        // wrapper entirely. Remove and place the exact item inside one Unity-
        // thread transaction, with a direct field fallback and postconditions.
        Plugin.DiagInfo(
            $"AUTO-GEAR VAULT TAKE|stage=start|item={NativeObjectKey(record.ItemData, record.ItemData)}");
        var taken = MainThreadNativeGateway.Invoke(() =>
        {
            if (Read(knownEmptyBagField, "itemData") is not null
                || !ReadList(Read(record.GroupData, "equipList")).Any(candidate =>
                    NativeEquals(candidate, record.ItemData)))
                return false;
            var removed = Convert.ToBoolean(
                InvokeRequiredInstance(treasure, "RemoveEquipFromGroup", record.GroupData, record.ItemData)
                ?? false,
                CultureInfo.InvariantCulture);
            if (!removed) return false;
            try
            {
                InvokeRequiredInstance(treasure, "PutItemToField", record.ItemData, knownEmptyBagField);
            }
            catch
            {
                // Preserve the already-removed item in the exact known field even
                // if StoreTreaData's presentation helper is unavailable.
                InvokeRequiredInstance(knownEmptyBagField, "addItem", record.ItemData);
            }
            if (!NativeEquals(Read(knownEmptyBagField, "itemData"), record.ItemData))
            {
                // Some game versions return normally without assigning the
                // provided field. The exact ItemFieldData operation is the
                // loss-prevention fallback after the group removal succeeded.
                InvokeRequiredInstance(knownEmptyBagField, "addItem", record.ItemData);
            }
            var stillInGroup = ReadList(Read(record.GroupData, "equipList")).Any(candidate =>
                NativeEquals(candidate, record.ItemData));
            if (stillInGroup && NativeEquals(Read(knownEmptyBagField, "itemData"), record.ItemData))
            {
                // Never leave a transient duplicate if the group refused its
                // removal despite reporting success.
                InvokeRequiredInstance(knownEmptyBagField, "removeItem");
                return false;
            }
            return NativeEquals(Read(knownEmptyBagField, "itemData"), record.ItemData)
                   && !stillInGroup;
        });
        Plugin.DiagInfo(
            $"AUTO-GEAR VAULT TAKE|stage=returned|item={NativeObjectKey(record.ItemData, record.ItemData)}|success={taken}");
        if (!taken) return false;
        var extractedBagField = knownEmptyBagField;
        if (!NativeEquals(Read(extractedBagField, "itemData"), record.ItemData))
        {
            Plugin.DiagWarning(
                $"AUTO-GEAR VAULT TAKE FAILED|item={NativeObjectKey(record.ItemData, record.ItemData)}|bag=false");
            return false;
        }
        moveJournal.Add(new MoveReceipt(MoveReceiptKind.VaultToBag, null, extractedBagField, record.ItemData, null, treasure, record.GroupData));
        return true;
    }

    private static double ReadHeroAttr(object hero, int id)
    {
        try
        {
            var attr = Read(hero, "attrData");
            var type = CreateEnum("EAttrType", id);
            return attr is null || type is null ? 0d : Convert.ToDouble(InvokeInstance(attr, "GetAttrValue", type) ?? 0d, CultureInfo.InvariantCulture);
        }
        catch { return 0d; }
    }

    private static int KeywordScore(string text, IEnumerable<string> words)
    {
        // Match complete ASCII words/phrases. The old substring check counted
        // `ice` inside justice/sacrifice/price and could select an Ice guide with
        // no ice effect at all. Morphological aliases are one evidence family,
        // preventing burn+burning or crit+critical from double weighting a row.
        var haystack = $" {Regex.Replace((text ?? string.Empty).ToLowerInvariant(), "[^a-z0-9]+", " ").Trim()} ";
        return words.Select(NormalizeKeyword)
            .Where(word => word.Length > 0)
            .GroupBy(KeywordFamily, StringComparer.Ordinal)
            .Count(group => KeywordFamilyForms(group.Key, group).Any(form =>
                haystack.Contains($" {NormalizeKeyword(form)} ", StringComparison.Ordinal)));
    }

    private static string NormalizeKeyword(string value)
        => Regex.Replace((value ?? string.Empty).ToLowerInvariant(), "[^a-z0-9]+", " ").Trim();

    private static string KeywordFamily(string word) => word switch
    {
        "burn" or "burning" => "burn",
        "freeze" or "frozen" => "freeze",
        "shock" or "shocked" => "shock",
        "summon" or "summoned" => "summon",
        "bleed" or "bleeding" => "bleed",
        "crit" or "critical" or "critical strike" => "critical",
        "corrosion" or "corrode" => "corrosion",
        "immunity" or "immune" => "immune",
        "defense" or "defence" => "defense",
        "armor" or "armour" => "armor",
        _ => word
    };

    private static IEnumerable<string> KeywordFamilyForms(string family, IEnumerable<string> declared) => family switch
    {
        "burn" => new[] { "burn", "burning" },
        "freeze" => new[] { "freeze", "frozen" },
        "shock" => new[] { "shock", "shocked" },
        "summon" => new[] { "summon", "summoned" },
        "bleed" => new[] { "bleed", "bleeding" },
        "critical" => new[] { "crit", "critical", "critical strike" },
        "corrosion" => new[] { "corrosion", "corrode" },
        "immune" => new[] { "immunity", "immune" },
        "defense" => new[] { "defense", "defence" },
        "armor" => new[] { "armor", "armour" },
        _ => declared
    };

